/**
 * OBreadcrumbFrame - 面包屑导航。
 *
 * Frame 不持业务数据,items 由 Page 传入(items 是 UI 数据,不是业务实体)。
 *
 * @example
 * <OBreadcrumbFrame items={[
 *   { label: 'Home', href: '/' },
 *   { label: 'Markets', href: '/markets' },
 *   { label: 'BTC/USDT' },
 * ]} />
 */
'use client';

import { forwardRef, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OBreadcrumbItem {
  label: ReactNode;
  href?: string;
  /** 自定义点击回调(替代 href 跳转,由 Page 处理路由)。 */
  onClick?: () => void;
}

export interface OBreadcrumbFrameProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  items: OBreadcrumbItem[];
  /** 分隔符,默认 '/'。可传 'chevron' / '>' / 自定义 React 节点。 */
  separator?: 'slash' | 'chevron' | 'dot' | ReactNode;
  /** 是否折叠中间项(显示首/尾,中间用 '...' 替代,适合长路径)。 */
  collapse?: boolean;
  /** 折叠时显示的边项数(首尾各几项)。 */
  collapseEdgeCount?: number;
}

function Sep({ kind }: { kind: OBreadcrumbFrameProps['separator'] }) {
  if (kind === 'chevron')
    return (
      <svg
        width="12"
        height="12"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        aria-hidden="true"
      >
        <polyline points="9 18 15 12 9 6" />
      </svg>
    );
  if (kind === 'dot') return <span aria-hidden="true">·</span>;
  if (kind === 'slash' || !kind) return <span aria-hidden="true">/</span>;
  return <>{kind}</>;
}

export const OBreadcrumbFrame = forwardRef<HTMLElement, OBreadcrumbFrameProps>(
  function OBreadcrumbFrame(
    {
      items,
      separator = 'chevron',
      collapse = false,
      collapseEdgeCount = 1,
      className,
      theme: _t,
    },
    ref
  ) {
    const shouldCollapse = collapse && items.length > collapseEdgeCount * 2 + 1;
    const renderItems: (OBreadcrumbItem | 'ellipsis')[] = shouldCollapse
      ? [
          ...items.slice(0, collapseEdgeCount),
          'ellipsis' as const,
          ...items.slice(items.length - collapseEdgeCount),
        ]
      : items;

    return (
      <nav
        ref={ref}
        aria-label="Breadcrumb"
        className={cn('text-sm text-muted-foreground', className)}
      >
        <ol className="flex items-center gap-2 flex-wrap">
          {renderItems.map((it, i) => {
            const isLast = i === renderItems.length - 1;
            if (it === 'ellipsis') {
              return (
                <li key={`ell-${i}`} className="flex items-center gap-2">
                  <span aria-hidden="true"></span>
                  {!isLast ? <Sep kind={separator} /> : null}
                </li>
              );
            }
            return (
              <li key={i} className="flex items-center gap-2 min-w-0">
                {it.href || it.onClick ? (
                  <a
                    href={it.href}
                    onClick={
                      it.onClick
                        ? (e) => {
                            e.preventDefault();
                            it.onClick!();
                          }
                        : undefined
                    }
                    className="hover:text-foreground transition-colors truncate"
                  >
                    {it.label}
                  </a>
                ) : (
                  <span aria-current={isLast ? 'page' : undefined} className="text-foreground truncate">
                    {it.label}
                  </span>
                )}
                {!isLast ? <Sep kind={separator} /> : null}
              </li>
            );
          })}
        </ol>
      </nav>
    );
  }
);

OBreadcrumbFrame.displayName = 'OBreadcrumbFrame';
