/**
 * OMarkdownRenderer - Markdown 渲染。
 *
 * 通过 dynamic import 加载 react-markdown + remark-gfm + rehype-pretty-code (代码高亮) + rehype-katex (数学)。
 * 不入 main bundle (~150KB),只在使用时加载。
 *
 * 安全:默认禁用 raw HTML (XSS 防护)。
 *
 * @example
 * <OMarkdownRenderer content="# Hello\n\n```js\nconst x = 1;\n```" />
 */
'use client';

import { Suspense, lazy, forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';
import { OLoadingState } from '../OLoadingState';

const Renderer = lazy(() =>
  import('./OMarkdownRenderer.impl').then((m) => ({ default: m.MarkdownImpl }))
);

export interface OMarkdownRendererProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  /** Markdown 源文本。 */
  content: string;
  /** 启用 GFM (表格、删除线、任务列表)。 */
  gfm?: boolean;
  /** 启用代码高亮 (shiki)。 */
  highlight?: boolean;
  /** 启用数学公式 (KaTeX, $$...$$ 和 $...$ )。 */
  math?: boolean;
  /** 允许 raw HTML (XSS 危险,谨慎使用)。 */
  allowHtml?: boolean;
  /** 视觉变体。 */
  variant?: 'article' | 'compact' | 'doc';
  /** shiki 主题。 */
  codeTheme?: string;
}

const VARIANT_CLASS = {
  article: 'prose prose-base max-w-prose',
  compact: 'prose prose-sm',
  doc: 'prose prose-base max-w-none',
};

export const OMarkdownRenderer = forwardRef<HTMLDivElement, OMarkdownRendererProps>(
  function OMarkdownRenderer(
    {
      content,
      gfm = true,
      highlight = true,
      math = false,
      allowHtml = false,
      variant = 'article',
      codeTheme = 'github-dark',
      className,
      theme: _t,
    },
    ref
  ) {
    return (
      <div
        ref={ref}
        className={cn(
          // base typography styles via Tailwind typography plugin (recommend installing @tailwindcss/typography)
          // 如果项目没装 prose 插件, 用 fallback 样式
          VARIANT_CLASS[variant],
          // semantic colors
          'text-foreground',
          '[&>h1]:text-3xl [&>h1]:font-bold [&>h1]:mt-8 [&>h1]:mb-4',
          '[&>h2]:text-2xl [&>h2]:font-semibold [&>h2]:mt-6 [&>h2]:mb-3',
          '[&>h3]:text-xl [&>h3]:font-semibold [&>h3]:mt-5 [&>h3]:mb-2',
          '[&>p]:leading-relaxed [&>p]:mb-3',
          '[&_a]:text-primary [&_a]:underline [&_a]:underline-offset-2 hover:[&_a]:opacity-80',
          '[&_code:not(pre_code)]:px-1.5 [&_code:not(pre_code)]:py-0.5 [&_code:not(pre_code)]:rounded [&_code:not(pre_code)]:bg-muted [&_code:not(pre_code)]:text-sm [&_code:not(pre_code)]:font-mono',
          '[&_pre]:bg-card [&_pre]:border [&_pre]:border-border [&_pre]:rounded-md [&_pre]:p-4 [&_pre]:overflow-auto [&_pre]:text-sm [&_pre]:my-4',
          '[&>ul]:list-disc [&>ul]:pl-6 [&>ul]:mb-3 [&>ol]:list-decimal [&>ol]:pl-6 [&>ol]:mb-3',
          '[&>blockquote]:border-l-4 [&>blockquote]:border-primary/40 [&>blockquote]:pl-4 [&>blockquote]:italic [&>blockquote]:text-muted-foreground',
          '[&>table]:w-full [&>table]:border-collapse [&_th]:text-left [&_th]:p-2 [&_th]:border-b [&_th]:border-border [&_td]:p-2 [&_td]:border-b [&_td]:border-border/40',
          '[&>hr]:border-border [&>hr]:my-6',
          '@container',
          className
        )}
      >
        <Suspense fallback={<OLoadingState rows={4} />}>
          <Renderer
            content={content}
            gfm={gfm}
            highlight={highlight}
            math={math}
            allowHtml={allowHtml}
            codeTheme={codeTheme}
          />
        </Suspense>
      </div>
    );
  }
);

OMarkdownRenderer.displayName = 'OMarkdownRenderer';
