/**
 * RegulationProvider - 合规守门。
 *
 * 根据 region 自动:
 *   - 控制全局 banner 显示
 *   - 决定哪些功能可用 (AI 推荐等)
 *   - 提供延时标签格式化
 *
 * Helios 加密优先 → 默认 region=global (全球加密合规相对宽松)
 * 中国区 (cn) → 加密功能强禁用,banner 强制显示
 */
'use client';

import { createContext, useContext, useMemo, type ReactNode } from 'react';
import type {
  RegulationProtocol,
  RegulationConfig,
  RegulationRegion,
} from '../protocols';

const DEFAULT_CONFIGS: Record<RegulationRegion, RegulationConfig> = {
  global: {
    region: 'global',
    showBanner: false,
    disabledFeatures: [],
    defaultDataDelay: 0,
  },
  cn: {
    region: 'cn',
    showBanner: true,
    disabledFeatures: ['ai-recommendation', 'leverage-suggest'],
    defaultDataDelay: 15,
  },
  hk: {
    region: 'hk',
    showBanner: true,
    disabledFeatures: ['ai-recommendation'],
    defaultDataDelay: 15,
  },
  us: {
    region: 'us',
    showBanner: false,
    disabledFeatures: [],
    defaultDataDelay: 0,
  },
  eu: {
    region: 'eu',
    showBanner: false,
    disabledFeatures: [],
    defaultDataDelay: 0,
  },
};

const DISCLAIMERS: Record<RegulationRegion, string> = {
  global: 'For informational purposes only. Not investment advice.',
  cn: '本产品仅供学习参考,不构成任何投资建议,据此操作风险自负。',
  hk: '本資料僅供參考,並不構成任何投資建議。',
  us: 'For informational purposes only. Not investment advice.',
  eu: 'For informational purposes only. Not investment advice. Compliant with MiFID II disclosure.',
};

const RegulationContext = createContext<RegulationProtocol | null>(null);

interface RegulationProviderProps {
  children: ReactNode;
  region?: RegulationRegion;
  /** 覆盖默认配置 (e.g. 自定义延时)。 */
  overrides?: Partial<RegulationConfig>;
}

export function RegulationProvider({
  children,
  region = 'global',
  overrides,
}: RegulationProviderProps) {
  const protocol = useMemo<RegulationProtocol>(() => {
    const config: RegulationConfig = { ...DEFAULT_CONFIGS[region], ...overrides };
    return {
      config,
      isAllowed(feature) {
        return !config.disabledFeatures.includes(feature as never);
      },
      formatDataDelay(minutes) {
        if (minutes <= 0) return 'Live';
        if (minutes < 60) return `Delayed ${minutes}m`;
        const h = Math.floor(minutes / 60);
        const m = minutes % 60;
        return m === 0 ? `Delayed ${h}h` : `Delayed ${h}h${m}m`;
      },
      disclaimer: DISCLAIMERS[region],
    };
  }, [region, overrides]);

  return <RegulationContext.Provider value={protocol}>{children}</RegulationContext.Provider>;
}

RegulationProvider.displayName = 'RegulationProvider';

export function useRegulation(): RegulationProtocol {
  const ctx = useContext(RegulationContext);
  if (!ctx) {
    // 默认 global 配置兜底
    const config = DEFAULT_CONFIGS.global;
    return {
      config,
      isAllowed: () => true,
      formatDataDelay: (m) => (m <= 0 ? 'Live' : `Delayed ${m}m`),
      disclaimer: DISCLAIMERS.global,
    };
  }
  return ctx;
}
