/**
 * OPresetMarket - 工作区场景预设 Block (Helios 杀手锏)。
 *
 * 加密散户高频场景:
 *   - 现货监控 (spot)
 *   - 合约交易 (perp)
 *   - 网格策略 (grid)
 *   - 套利监控 (arbitrage)
 *   - 复盘模式 (replay)
 *
 * 每个预设是一个工作区布局(WorkspaceProtocol),包含哪些 Block + 怎么排列。
 * 用户点击 → WorkspaceProvider.load(preset.layout) → 整个工作台瞬间切换。
 *
 * 受控:
 *   - presets: 由 Wiki 团队预定义 (但 Helios 内置 5 个标准 preset)
 *   - currentId: 当前激活的 preset id
 *   - onSelect: 切换回调
 */

'use client';

import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';
import { useWorkspace } from '../../providers/WorkspaceProvider';

export interface OPreset {
  id: string;
  /** 显示名称(中文)。 */
  name: string;
  /** 短描述。 */
  description?: string;
  /** 图标(emoji 或 SVG)。 */
  icon?: React.ReactNode;
  /** 这个 preset 用到的 Block id 列表(展示用)。 */
  blocks?: string[];
  /** 实际加载到 WorkspaceProvider 的布局 JSON。 */
  layout?: unknown;
  /** 自定义颜色(高亮)。 */
  accent?: string;
}

export interface OPresetMarketProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  /** preset 列表。不传则使用 Helios 内置 5 个标准 preset。 */
  presets?: OPreset[];
  /** 当前激活的 preset id(受控)。 */
  currentId?: string;
  /** 切换回调(也会自动调用 WorkspaceProvider.load)。 */
  onSelect?: (preset: OPreset) => void;
  /** 视觉变体。 */
  variant?: 'grid' | 'tabs' | 'list';
}

// ============================================================
// Helios 内置 5 个标准 preset (加密散户场景)
// ============================================================

