// ============================================================
// 单卡片
// ============================================================

function PresetCard({
  preset,
  active,
  onClick,
}: {
  preset: OPreset;
  active: boolean;
  onClick: () => void;
}) {
  return (
    <button
      onClick={onClick}
      aria-pressed={active}
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'flex-start',
        gap: 8,
        padding: 'var(--space-card-pad, 12px)',
        borderRadius: 8,
        border: `1px solid ${active ? preset.accent ?? 'var(--primary)' : 'var(--border)'}`,
        background: active
          ? `color-mix(in oklch, ${preset.accent ?? 'var(--primary)'} 8%, var(--card))`
          : 'var(--card)',
        color: 'var(--foreground)',
        cursor: 'pointer',
        textAlign: 'left',
        transition: 'all 160ms ease-out',
        boxShadow: active ? `0 0 0 3px color-mix(in oklch, ${preset.accent ?? 'var(--primary)'} 20%, transparent)` : 'none',
        fontFamily: 'var(--font-ui)',
        minHeight: 96,
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, width: '100%' }}>
        <span style={{ fontSize: 22, lineHeight: 1 }}>{preset.icon}</span>
        <span style={{ fontSize: 14, fontWeight: 600, flex: 1 }}>{preset.name}</span>
        {active && (
          <span
            style={{
              fontSize: 10,
              padding: '2px 6px',
              borderRadius: 999,
              background: preset.accent ?? 'var(--primary)',
              color: 'var(--primary-foreground)',
              fontWeight: 600,
              letterSpacing: 0.5,
            }}
          >
            ACTIVE
          </span>
        )}
      </div>
      {preset.description && (
        <div style={{ fontSize: 11, color: 'var(--text-muted)', lineHeight: 1.4 }}>
          {preset.description}
        </div>
      )}
      {preset.blocks && preset.blocks.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, marginTop: 'auto' }}>
          {preset.blocks.slice(0, 4).map((b) => (
            <span
              key={b}
              style={{
                fontSize: 9,
                padding: '1px 6px',
                borderRadius: 3,
                background: 'var(--terminal-bg-3, var(--muted))',
                color: 'var(--text-muted)',
                fontFamily: 'var(--font-data)',
              }}
            >
              {b.replace(/^O/, '')}
            </span>
          ))}
        </div>
      )}
    </button>
  );
}

// ============================================================
// 主组件
// ============================================================

export const OPresetMarket = forwardRef<HTMLDivElement, OPresetMarketProps>(
  function OPresetMarket(
    {
      presets = DEFAULT_PRESETS,
      currentId,
      onSelect,
      variant = 'grid',
      className,
      theme: _t,
    },
    ref
  ) {
    const workspace = useWorkspace();

    function handleSelect(preset: OPreset) {
      onSelect?.(preset);
      if (workspace && preset.layout) {
        workspace.loadLayout(preset.layout as never);
      }
    }

    if (variant === 'tabs') {
      return (
        <div
          ref={ref}
          className={cn('flex gap-1 p-1 rounded-md border border-border @container', className)}
          style={{
            background: 'var(--terminal-bg-1, var(--muted))',
            overflowX: 'auto',
            fontFamily: 'var(--font-ui)',
          }}
        >
          {presets.map((p) => {
            const active = p.id === currentId;
            return (
              <button
                key={p.id}
                onClick={() => handleSelect(p)}
                aria-pressed={active}
                style={{
                  padding: '6px 14px',
                  borderRadius: 5,
                  border: 'none',
                  background: active ? 'var(--card)' : 'transparent',
                  color: active ? 'var(--foreground)' : 'var(--text-muted)',
                  fontWeight: active ? 600 : 400,
                  fontSize: 12,
                  cursor: 'pointer',
                  whiteSpace: 'nowrap',
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 6,
                }}
              >
                <span>{p.icon}</span>
                <span>{p.name}</span>
              </button>
            );
          })}
        </div>
      );
    }

    if (variant === 'list') {
      return (
        <div
          ref={ref}
          className={cn('flex flex-col gap-2', className)}
        >
          {presets.map((p) => (
            <PresetCard key={p.id} preset={p} active={p.id === currentId} onClick={() => handleSelect(p)} />
          ))}
        </div>
      );
    }

    // grid (默认)
    return (
      <div
        ref={ref}
        className={cn(className)}
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))',
          gap: 12,
        }}
      >
        {presets.map((p) => (
          <PresetCard key={p.id} preset={p} active={p.id === currentId} onClick={() => handleSelect(p)} />
        ))}
      </div>
    );
  }
);

OPresetMarket.displayName = 'OPresetMarket';

// 暴露内置 preset 给消费方
export { DEFAULT_PRESETS as HELIOS_DEFAULT_PRESETS };
