/**
 * OFeatureGrid - 营销功能卡片网格。
 *
 * 受控:features 由 Page 传入。
 *
 * 自适应列数 (container queries):
 *   < 480px: 1 列
 *   < 768px: 2 列
 *   >=768px: cols (默认 3)
 */
'use client';

import { forwardRef, type ReactNode } from 'react';
import { motion } from 'motion/react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

export interface OFeatureItem {
  id: string;
  /** 图标节点 (推荐用 lucide-react icon 组件)。 */
  icon?: ReactNode;
  title: string;
  description: string;
  /** 可选 CTA。 */
  link?: { label: string; href: string };
}

export interface OFeatureGridProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  features: OFeatureItem[];
  /** 大屏列数。 */
  cols?: 2 | 3 | 4;
  /** 视觉变体。 */
  variant?: 'card' | 'minimal' | 'bordered';
  /** 章节标题 (可选)。 */
  heading?: string;
  /** 章节副标题。 */
  subheading?: string;
  /** 进场动画 stagger 延迟 (ms)。 */
  stagger?: number;
}

const COLS_CLASS = {
  2: '@[768px]:grid-cols-2',
  3: '@[768px]:grid-cols-2 @[1024px]:grid-cols-3',
  4: '@[768px]:grid-cols-2 @[1024px]:grid-cols-4',
};

const CARD_CLASS = {
  card: 'bg-card border border-border rounded-lg p-6 hover:border-primary/40 hover:shadow-lg transition-all',
  minimal: 'p-4',
  bordered: 'border-l-2 border-border pl-4 py-2 hover:border-primary transition-colors',
};

export const OFeatureGrid = forwardRef<HTMLElement, OFeatureGridProps>(function OFeatureGrid(
  {
    features,
    cols = 3,
    variant = 'card',
    heading,
    subheading,
    stagger = 80,
    className,
    theme: _t,
  },
  ref
) {
  const reduced = useReducedMotion();

  return (
    <section ref={ref} className={cn('w-full @container', className)}>
      {heading || subheading ? (
        <div className="max-w-3xl mx-auto text-center mb-10">
          {heading ? (
            <h2 className="text-3xl md:text-4xl font-bold tracking-tight">{heading}</h2>
          ) : null}
          {subheading ? (
            <p className="text-lg text-muted-foreground mt-3">{subheading}</p>
          ) : null}
        </div>
      ) : null}
      <div className={cn('grid grid-cols-1 @[480px]:grid-cols-2 gap-6', COLS_CLASS[cols])}>
        {features.map((f, i) => (
          <motion.div
            key={f.id}
            initial={reduced ? false : { opacity: 0, y: 20 }}
            whileInView={reduced ? undefined : { opacity: 1, y: 0 }}
            viewport={{ once: true, margin: '-50px' }}
            transition={{ duration: 0.4, delay: reduced ? 0 : (i * stagger) / 1000 }}
            className={cn('flex flex-col gap-3', CARD_CLASS[variant])}
          >
            {f.icon ? (
              <div className="w-10 h-10 rounded-md bg-primary/10 text-primary flex items-center justify-center shrink-0">
                {f.icon}
              </div>
            ) : null}
            <h3 className="text-lg font-bold tracking-[-0.01em]">{f.title}</h3>
            <p className="text-sm text-muted-foreground leading-relaxed">{f.description}</p>
            {f.link ? (
              <a
                href={f.link.href}
                className="text-sm text-primary font-medium mt-2 inline-flex items-center gap-1 hover:underline"
              >
                {f.link.label}
                <span aria-hidden></span>
              </a>
            ) : null}
          </motion.div>
        ))}
      </div>
    </section>
  );
});

OFeatureGrid.displayName = 'OFeatureGrid';
