/**
 * OSearchableSelect - 可搜索单选/多选下拉。
 *
 * 基于 cmdk + @radix-ui/react-popover。键盘可达,无障碍。
 *
 * @example
 * <OSearchableSelect
 *   options={[{ value: 'btc', label: 'BTC' }, { value: 'eth', label: 'ETH' }]}
 *   value={value}
 *   onChange={setValue}
 *   placeholder="Select symbol..."
 * />
 */
'use client';

import * as Popover from '@radix-ui/react-popover';
import { Command } from 'cmdk';
import { forwardRef, useState } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OSelectOption {
  value: string;
  label: string;
  description?: string;
  disabled?: boolean;
}

export interface OSearchableSelectProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  options: OSelectOption[];
  /** 单选 value 或多选 values。 */
  value?: string | string[] | null;
  onChange: (value: string | string[] | null) => void;
  /** 多选模式。 */
  multiple?: boolean;
  placeholder?: string;
  /** 搜索框 placeholder。 */
  searchPlaceholder?: string;
  /** 无结果文本。 */
  emptyMessage?: string;
  /** 禁用整个组件。 */
  disabled?: boolean;
  /** 触发按钮宽度。 */
  width?: string;
}

function ChevronIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
      <polyline points="6 9 12 15 18 9" />
    </svg>
  );
}

function CheckIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" aria-hidden="true">
      <polyline points="20 6 9 17 4 12" />
    </svg>
  );
}

export const OSearchableSelect = forwardRef<HTMLButtonElement, OSearchableSelectProps>(
  function OSearchableSelect(
    {
      options,
      value,
      onChange,
      multiple = false,
      placeholder = 'Select...',
      searchPlaceholder = 'Search...',
      emptyMessage = 'No results',
      disabled = false,
      width = '14rem',
      className,
      theme: _t,
    },
    ref
  ) {
    const [open, setOpen] = useState(false);

    const selectedValues = multiple
      ? Array.isArray(value)
        ? value
        : []
      : typeof value === 'string'
        ? [value]
        : [];

    const displayLabel = (() => {
      if (selectedValues.length === 0) return placeholder;
      if (!multiple) {
        const found = options.find((o) => o.value === selectedValues[0]);
        return found?.label ?? placeholder;
      }
      return `${selectedValues.length} selected`;
    })();

    function handleSelect(v: string) {
      if (multiple) {
        const arr = Array.isArray(value) ? [...value] : [];
        const idx = arr.indexOf(v);
        if (idx >= 0) arr.splice(idx, 1);
        else arr.push(v);
        onChange(arr);
      } else {
        onChange(v);
        setOpen(false);
      }
    }

    return (
      <Popover.Root open={open} onOpenChange={setOpen}>
        <Popover.Trigger asChild>
          <button
            ref={ref}
            type="button"
            disabled={disabled}
            className={cn(
              'inline-flex items-center justify-between gap-2 rounded-md border border-input bg-card px-3 py-2 text-sm @container',
              'hover:bg-muted transition-colors disabled:opacity-50 disabled:cursor-not-allowed',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
              className
            )}
            style={{ width }}
            aria-expanded={open}
            aria-haspopup="listbox"
          >
            <span className={cn('truncate', selectedValues.length === 0 && 'text-muted-foreground')}>
              {displayLabel}
            </span>
            <ChevronIcon />
          </button>
        </Popover.Trigger>
        <Popover.Portal>
          <Popover.Content
            sideOffset={4}
            className="z-50 rounded-md border border-border bg-popover text-popover-foreground shadow-md outline-none"
            style={{ width }}
          >
            <Command className="flex flex-col">
              <div className="px-2 py-1.5 border-b border-border">
                <Command.Input
                  placeholder={searchPlaceholder}
                  className="w-full bg-transparent outline-none text-sm placeholder:text-muted-foreground"
                />
              </div>
              <Command.List className="max-h-64 overflow-auto p-1">
                <Command.Empty className="py-3 text-center text-sm text-muted-foreground">
                  {emptyMessage}
                </Command.Empty>
                {options.map((opt) => {
                  const checked = selectedValues.includes(opt.value);
                  return (
                    <Command.Item
                      key={opt.value}
                      value={`${opt.label} ${opt.value}`}
                      disabled={opt.disabled}
                      onSelect={() => !opt.disabled && handleSelect(opt.value)}
                      className={cn(
                        'flex items-center gap-2 px-2 py-1.5 rounded text-sm cursor-pointer',
                        'data-[selected=true]:bg-muted aria-selected:bg-muted',
                        'data-[disabled=true]:opacity-50 data-[disabled=true]:cursor-not-allowed'
                      )}
                    >
                      <span className={cn('w-4 h-4 flex items-center justify-center', !checked && 'opacity-0')}>
                        <CheckIcon />
                      </span>
                      <div className="min-w-0 flex-1">
                        <div className="truncate">{opt.label}</div>
                        {opt.description ? (
                          <div className="text-xs text-muted-foreground truncate">{opt.description}</div>
                        ) : null}
                      </div>
                    </Command.Item>
                  );
                })}
              </Command.List>
            </Command>
          </Popover.Content>
        </Popover.Portal>
      </Popover.Root>
    );
  }
);

OSearchableSelect.displayName = 'OSearchableSelect';
