/**
 * OCitationCard — Citation 卡片渲染
 *
 * 用途:渲染单条 Citation,Stratum Web alpha 的"citation 一等公民"基础组件。
 * 用在 OAIQAPanel / OSemanticSearch / ODocumentReader 任何引用源出现处。
 *
 * 数据契约:消费 @helios/blocks 的 Citation interface(API v1.0 §1.7)
 *
 * 设计原则(R0 §"Citation 一等公民"):
 *   1. 强制可见 — 不可隐藏
 *   2. 点击跳 deep_link
 *   3. fragment_id "{substrate_id}#{chunk_idx}" 截断展示
 *   4. anchor.section 有则 prefix
 *
 * v1.0 限制(API 文档 §1.2):
 *   - anchor.char_start / char_end 始终 0(chunk-level only)
 *   - 不显示 char range,只显示 section + fragment chunk idx
 */
import { forwardRef, useCallback, type MouseEvent } from 'react';
import { cn } from '../../lib/cn';
import type { Citation, AgentCitation } from '../../types/stratum';
import type { OBlockBaseProps } from '../../lib/types';

export interface OCitationCardProps extends Omit<OBlockBaseProps, 'variant'> {
  /**
   * Citation 数据(支持 API v1.0 命名 Citation + helios 旧名 AgentCitation,兼容)。
   */
  citation: Citation | AgentCitation;
  /**
   * 点击回调。如不提供 + citation.deep_link 存在,默认 window.open(deep_link)。
   */
  onClick?: (citation: Citation | AgentCitation, event: MouseEvent<HTMLButtonElement>) => void;
  /**
   * 紧凑模式 — 单行 chip 风格(默认 false 双行卡片)。
   * AOI 回答内嵌引用用 compact,搜索结果列表用全卡。
   */
  compact?: boolean;
  /**
   * 显示 source substrate 标题(citation.title 可选)。
   * 默认 true。Compact 模式自动设 false。
   */
  showTitle?: boolean;
  /**
   * fragment_id chunk idx 截断显示位数。默认 6 字符(`abc12...`)。
   */
  fragmentIdLength?: number;
}

/**
 * 解析 fragment_id "{substrate_id}#{chunk_idx}" → chunk_idx 短显示。
 *
 * v1.0 fragment_id 格式: "01KS2MD25C3FAAAD7B9KTF9ZM9#0"
 */
function extractChunkIdx(fragmentId: string | null): string | null {
  if (!fragmentId) return null;
  const hashIdx = fragmentId.lastIndexOf('#');
  if (hashIdx === -1) return null;
  return fragmentId.substring(hashIdx + 1);
}

/**
 * 解析 anchor 显示 — v1.0 only section prefix(char_start/end 始终 0,不显示)。
 */
function formatAnchor(anchor: Citation['anchor']): string | null {
  if (!anchor) return null;
  if (anchor.section) return anchor.section;
  return null;
}

export const OCitationCard = forwardRef<HTMLButtonElement, OCitationCardProps>(
  function OCitationCard(
    {
      citation,
      onClick,
      compact = false,
      showTitle = true,
      fragmentIdLength: _fragmentIdLength = 6,
      className,
      theme: _theme,
      size: _size,
    },
    ref
  ) {
    const chunkIdx = extractChunkIdx(citation.fragment_id);
    const section = formatAnchor(citation.anchor);
    const title = 'title' in citation ? citation.title : undefined;
    const effectiveShowTitle = compact ? false : showTitle;

    const handleClick = useCallback(
      (event: MouseEvent<HTMLButtonElement>) => {
        if (onClick) {
          onClick(citation, event);
          return;
        }
        // 默认行为:打开 deep_link
        if (citation.deep_link) {
          window.open(citation.deep_link, '_blank', 'noopener,noreferrer');
        }
      },
      [citation, onClick]
    );

    if (compact) {
      // Chip 单行风格
      return (
        <button
          ref={ref}
          type="button"
          onClick={handleClick}
          className={cn(
            'inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-mono @container',
            'bg-muted/50 hover:bg-muted',
            'border border-border transition-colors',
            'text-[color:var(--foreground)]',
            citation.deep_link && 'cursor-pointer',
            !citation.deep_link && 'cursor-default',
            className
          )}
          title={citation.deep_link ?? undefined}
          aria-label={`Citation ${citation.substrate_id}${chunkIdx ? `#${chunkIdx}` : ''}`}
        >
          <span className="text-[color:var(--text-muted)]" aria-hidden="true">
            📎
          </span>
          <span>{citation.substrate_id.slice(0, 12)}…</span>
          {chunkIdx !== null && (
            <span className="text-[color:var(--text-muted)]">#{chunkIdx}</span>
          )}
        </button>
      );
    }

    // 全卡片(双行)
    return (
      <button
        ref={ref}
        type="button"
        onClick={handleClick}
        className={cn(
          'flex flex-col gap-1 px-3 py-2 rounded-md text-left w-full',
          'bg-card hover:bg-muted/30',
          'border border-border transition-colors',
          citation.deep_link && 'cursor-pointer',
          !citation.deep_link && 'cursor-default',
          className
        )}
        title={citation.deep_link ?? undefined}
        aria-label={
          title
            ? `Citation: ${title}`
            : `Citation ${citation.substrate_id}${chunkIdx ? `#${chunkIdx}` : ''}`
        }
      >
        <div className="flex items-center gap-1.5 text-xs">
          <span aria-hidden="true">📎</span>
          {effectiveShowTitle && title ? (
            <span className="font-medium text-[color:var(--foreground)] truncate">{title}</span>
          ) : (
            <span className="font-mono text-[color:var(--foreground)]">
              {citation.substrate_id.slice(0, 16)}…
            </span>
          )}
        </div>
        {(section || chunkIdx !== null) && (
          <div className="flex items-center gap-2 text-[10px] text-[color:var(--text-muted)] font-mono">
            {section && <span>§ {section}</span>}
            {chunkIdx !== null && <span>chunk #{chunkIdx}</span>}
          </div>
        )}
      </button>
    );
  }
);

OCitationCard.displayName = 'OCitationCard';
