/**
 * OEmptyState - 空数据状态。
 *
 * variant:
 *   - minimal:     纯文本,极简
 *   - illustrated: 带图标 + 描述 + action 按钮
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

const variants = cva('w-full', {
  variants: {
    variant: {
      minimal: 'p-4 text-center text-sm text-muted-foreground',
      illustrated: 'p-8 flex flex-col items-center justify-center text-center gap-4 min-h-48',
    },
  },
  defaultVariants: { variant: 'illustrated' },
});

type EmptyVariantProps = VariantProps<typeof variants>;

export interface OEmptyStateProps
  extends Omit<OBlockBaseProps, 'variant'>,
    EmptyVariantProps {
  title: string;
  description?: string;
  /** 自定义图标 (默认是个简笔 box)。 */
  icon?: ReactNode;
  /** 主操作按钮文本。 */
  actionLabel?: string;
  /** 主操作回调。 */
  onAction?: () => void;
}

function DefaultIcon() {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      width="48"
      height="48"
      aria-hidden="true"
    >
      <path d="M21 8v13H3V8" />
      <path d="M1 3h22v5H1z" />
      <line x1="10" y1="12" x2="14" y2="12" />
    </svg>
  );
}

export const OEmptyState = forwardRef<HTMLDivElement, OEmptyStateProps>(function OEmptyState(
  { title, description, icon, actionLabel, onAction, variant = 'illustrated', className, theme: _t, size: _s, ...rest },
  ref
) {
  if (variant === 'minimal') {
    return (
      <div ref={ref} className={cn(variants({ variant }), className)} {...rest}>
        {title}
        {description ? <span className="block text-xs opacity-70 mt-1 @container">{description}</span> : null}
      </div>
    );
  }

  return (
    <div ref={ref} className={cn(variants({ variant }), className)} {...rest}>
      <div className="text-muted-foreground/60">{icon ?? <DefaultIcon />}</div>
      <div className="space-y-1 max-w-md">
        <h3 className="font-bold text-base tracking-[-0.01em]">{title}</h3>
        {description ? <p className="text-sm text-muted-foreground">{description}</p> : null}
      </div>
      {actionLabel && onAction ? (
        <button
          type="button"
          onClick={onAction}
          className="mt-2 px-4 py-2 text-sm rounded bg-primary text-primary-foreground hover:opacity-90 transition-opacity"
        >
          {actionLabel}
        </button>
      ) : null}
    </div>
  );
});

OEmptyState.displayName = 'OEmptyState';
