/**
 * useContainerSize - 监听元素自身宽度,实现 JS 层面的 container queries 等价能力。
 *
 * 优先用 CSS container queries (Tailwind `@[400px]:...`),JS 不可达时才用此 hook。
 *
 * SPEC §3.2: Block 自适应优先用 CSS container queries,本 hook 是补充。
 *
 * @example
 * const { width, breakpoint } = useContainerSize(ref);
 * if (breakpoint === 'sm') return <Compact />;
 */

'use client';

import { useEffect, useState, type RefObject } from 'react';
import { CONTAINER_BREAKPOINT, type ContainerBreakpoint } from '../themes/tokens';

interface ContainerSize {
  width: number;
  height: number;
  breakpoint: ContainerBreakpoint;
}

function resolveBreakpoint(width: number): ContainerBreakpoint {
  if (width >= CONTAINER_BREAKPOINT.xl) return 'xl';
  if (width >= CONTAINER_BREAKPOINT.lg) return 'lg';
  if (width >= CONTAINER_BREAKPOINT.md) return 'md';
  return 'sm';
}

export function useContainerSize(ref: RefObject<HTMLElement | null>): ContainerSize {
  const [size, setSize] = useState<ContainerSize>({
    width: 0,
    height: 0,
    breakpoint: 'sm',
  });

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof ResizeObserver === 'undefined') return;

    const observer = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (!entry) return;
      const { width, height } = entry.contentRect;
      setSize({ width, height, breakpoint: resolveBreakpoint(width) });
    });

    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  return size;
}
