/**
 * useGpuTier - 检测设备 GPU 等级,用于类 3 重型 Block 的降级决策。
 *
 * SPEC §3.7: 类 3 Block 必须在低端设备 (tier ≤ 1) 显示 fallback。
 *
 * 检测策略 (轻量,不引入额外依赖):
 *   - WebGL 不支持        → tier 0 (无 GPU,必须降级)
 *   - WebGL 支持但 SOFTWARE_RENDERER 或硬件信息缺失 → tier 1
 *   - WebGL 2 支持且 renderer 包含 Intel/Mali/Adreno (低端) → tier 2
 *   - 其它 (NVIDIA/AMD/Apple/高端 ARM) → tier 3
 *
 * 想要更精确的检测可换 detect-gpu 库,但会增加 ~30KB bundle。
 */

'use client';

import { useEffect, useState } from 'react';

export type GpuTier = 0 | 1 | 2 | 3;

interface GpuInfo {
  tier: GpuTier;
  renderer: string;
  vendor: string;
  isLowEnd: boolean;
}

const DEFAULT: GpuInfo = { tier: 2, renderer: '', vendor: '', isLowEnd: false };

function detect(): GpuInfo {
  if (typeof window === 'undefined' || typeof document === 'undefined') return DEFAULT;

  try {
    const canvas = document.createElement('canvas');
    const gl =
      (canvas.getContext('webgl2') as WebGL2RenderingContext | null) ||
      (canvas.getContext('webgl') as WebGLRenderingContext | null) ||
      (canvas.getContext('experimental-webgl') as WebGLRenderingContext | null);

    if (!gl) return { tier: 0, renderer: '', vendor: '', isLowEnd: true };

    const dbgInfo = gl.getExtension('WEBGL_debug_renderer_info');
    const renderer = dbgInfo
      ? String(gl.getParameter(dbgInfo.UNMASKED_RENDERER_WEBGL) ?? '').toLowerCase()
      : '';
    const vendor = dbgInfo
      ? String(gl.getParameter(dbgInfo.UNMASKED_VENDOR_WEBGL) ?? '').toLowerCase()
      : '';

    if (!renderer) return { tier: 1, renderer, vendor, isLowEnd: true };

    if (renderer.includes('swiftshader') || renderer.includes('software')) {
      return { tier: 1, renderer, vendor, isLowEnd: true };
    }

    // 低端 GPU 启发式
    const isMobileLowEnd =
      /\b(mali-?[0-4]\d{2}|adreno (?:[1-4]\d{2}|5[0-2]\d)|powervr (sgx|rogue ge[0-9]))/i.test(
        renderer
      );
    if (isMobileLowEnd) {
      return { tier: 2, renderer, vendor, isLowEnd: true };
    }

    // 中低: 集显
    const isIntegrated =
      /\bintel(?!.*arc)/i.test(renderer) ||
      /\b(uhd|hd) graphics\b/i.test(renderer) ||
      /\biris (?:plus|pro)?(?!\s+xe)/i.test(renderer);
    if (isIntegrated) {
      return { tier: 2, renderer, vendor, isLowEnd: false };
    }

    // 高端
    return { tier: 3, renderer, vendor, isLowEnd: false };
  } catch {
    return DEFAULT;
  }
}

export function useGpuTier(): GpuInfo {
  const [info, setInfo] = useState<GpuInfo>(DEFAULT);
  useEffect(() => {
    setInfo(detect());
  }, []);
  return info;
}
