/**
 * AIIntentProvider - 自然语言意图解析。
 *
 * 设计:
 *   - v1.0 接口完整,实现走 endpoint 抽象
 *   - 后端负责接 Vercel AI SDK / OpenAI / Claude / 本地模型
 *   - Provider 只做接口转发 + 命令查找映射
 *
 * 用户在命令面板输入:
 *   "买入 0.5 BTC 限价 67000"  →  parse 返回 [{type:'execute', commandId:'trade.buy', args:{symbol,qty,price}}]
 *   "涨幅前 10 的板块"           →  parse 返回 [{type:'filter', commandId:'market.topGainers', args:{n:10}}]
 *
 * 后端实际实现 endpoint 返回 ParsedIntent[] JSON。
 */
'use client';

import { createContext, useContext, useMemo, useRef, type ReactNode } from 'react';
import type {
  AIIntentProtocol,
  ParsedIntent,
  CommandProtocol,
} from '../protocols';

const AIIntentContext = createContext<AIIntentProtocol | null>(null);

interface AIIntentProviderProps {
  children: ReactNode;
  /** 后端 endpoint, POST 接收 { text, context }, 返回 ParsedIntent[]。 */
  endpoint?: string;
  /** 流式问答 endpoint (SSE/streaming),POST 同上,返回文本流。 */
  streamEndpoint?: string;
  /** 命令系统引用,用于自动 execute。 */
  commandProtocol?: CommandProtocol;
  /** 自定义 fetch (用于鉴权)。 */
  fetcher?: typeof fetch;
}

export function AIIntentProvider({
  children,
  endpoint,
  streamEndpoint,
  commandProtocol,
  fetcher = typeof fetch !== 'undefined' ? fetch : undefined,
}: AIIntentProviderProps) {
  const cmdRef = useRef(commandProtocol);
  cmdRef.current = commandProtocol;

  const protocol = useMemo<AIIntentProtocol>(
    () => ({
      isReady() {
        return !!endpoint && !!fetcher;
      },
      async parse(text, context) {
        if (!endpoint || !fetcher) {
          throw new Error('[AIIntentProvider] No endpoint configured');
        }
        const res = await fetcher(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ text, context }),
        });
        if (!res.ok) throw new Error(`AI parse failed: ${res.status}`);
        const intents = (await res.json()) as ParsedIntent[];
        return intents;
      },
      async execute(intent) {
        if (intent.commandId && cmdRef.current) {
          await cmdRef.current.execute(intent.commandId, intent.args);
        }
      },
      async *stream(text, context) {
        if (!streamEndpoint || !fetcher) {
          throw new Error('[AIIntentProvider] No stream endpoint');
        }
        const res = await fetcher(streamEndpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ text, context }),
        });
        if (!res.ok || !res.body) throw new Error(`AI stream failed: ${res.status}`);
        const reader = res.body.getReader();
        const decoder = new TextDecoder();
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          yield decoder.decode(value, { stream: true });
        }
      },
    }),
    [endpoint, streamEndpoint, fetcher]
  );

  return <AIIntentContext.Provider value={protocol}>{children}</AIIntentContext.Provider>;
}

AIIntentProvider.displayName = 'AIIntentProvider';

export function useAIIntent(): AIIntentProtocol {
  const ctx = useContext(AIIntentContext);
  if (!ctx) {
    return {
      isReady: () => false,
      parse: async () => [],
      execute: async () => {},
      stream: async function* () {
        // noop generator(provider 未 ready 的兜底)
        if (false as boolean) yield '';
        return;
      },
    };
  }
  return ctx;
}
