/**
 * OLLMProfile (Tide Wave 2 E15, Block)
 *
 * LLM 个股画像, 5 段 narrative + metadata。
 * 来源:OUI_WAVE_2_REQUIREMENTS_v1.0.md §12
 *
 * markdown 简单支持(**bold** + - list)
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface ProfileSection {
  heading: string;
  body: string;
}

export interface ProfileMetadata {
  model: string;
  generatedAt: string | Date;
  tokenCount: number;
  costYuan: number;
}

export interface OLLMProfileProps extends Omit<OBlockBaseProps, 'variant'> {
  symbol: string;
  sections: ProfileSection[];
  regimeContext: string;
  metadata: ProfileMetadata;
  loading?: boolean;
  onRegenerate?: () => void;
}

/** 简单 markdown 解析:仅支持 **bold** 和 - list */
function renderMarkdown(text: string): React.ReactNode {
  const lines = text.split('\n');
  const elements: React.ReactNode[] = [];
  let currentList: React.ReactNode[] = [];

  const flushList = () => {
    if (currentList.length > 0) {
      elements.push(
        <ul key={`ul-${elements.length}`} className="ml-4 list-disc">
          {currentList}
        </ul>
      );
      currentList = [];
    }
  };

  lines.forEach((line, i) => {
    if (line.trim().startsWith('- ')) {
      currentList.push(<li key={i}>{renderInline(line.trim().substring(2))}</li>);
    } else {
      flushList();
      elements.push(
        <p key={i} className="mb-1">
          {renderInline(line)}
        </p>
      );
    }
  });
  flushList();

  return elements;
}

function renderInline(text: string): React.ReactNode {
  const parts = text.split(/(\*\*[^*]+\*\*)/);
  return parts.map((p, i) => {
    if (p.startsWith('**') && p.endsWith('**')) {
      return <strong key={i}>{p.slice(2, -2)}</strong>;
    }
    return <span key={i}>{p}</span>;
  });
}

export const OLLMProfile = forwardRef<HTMLDivElement, OLLMProfileProps>(
  function OLLMProfile(
    {
      symbol: _symbol,
      sections,
      regimeContext,
      metadata,
      loading,
      onRegenerate,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const generated =
      metadata.generatedAt instanceof Date
        ? metadata.generatedAt.toLocaleString()
        : metadata.generatedAt;

    return (
      <div
        ref={ref}
        className={cn(
          'flex flex-col gap-2 px-3 py-2 rounded @container',
          'bg-[color:var(--card)] border border-[color:var(--border-strong)]',
          className
        )}
        style={{ fontFamily: 'var(--font-sans)' }}
        role="article"
        aria-label="LLM 个股画像"
      >
        {/* actions */}
        {onRegenerate && (
          <div className="flex items-center justify-between">
            <span
              className="text-[10px] uppercase tracking-[0.04em]"
              style={{ color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)' }}
            >
              {regimeContext}
            </span>
            <button
              type="button"
              onClick={onRegenerate}
              disabled={loading}
              className={cn(
                'px-2 py-0.5 text-[10px] rounded',
                'bg-[color:var(--muted)] text-[color:var(--foreground)]',
                'hover:bg-[color:var(--accent)] transition-colors',
                'disabled:opacity-50 disabled:cursor-not-allowed'
              )}
            >
              {loading ? '生成中...' : '↻ 重新生成'}
            </button>
          </div>
        )}

        {/* sections */}
        {loading ? (
          <div
            className="text-xs italic"
            style={{ color: 'var(--text-tertiary)' }}
          >
            正在生成画像...
          </div>
        ) : (
          <div className="flex flex-col gap-2 max-h-[400px] overflow-y-auto">
            {sections.map((s, i) => (
              <section key={i}>
                <h4
                  className="text-xs font-bold mb-1"
                  style={{ color: 'var(--foreground)' }}
                >
                  {s.heading}
                </h4>
                <div
                  className="text-xs leading-relaxed"
                  style={{ color: 'var(--muted-foreground)' }}
                >
                  {renderMarkdown(s.body)}
                </div>
              </section>
            ))}
          </div>
        )}

        {/* metadata */}
        <div
          className="text-[10px] text-right border-t border-[color:var(--border-subtle)] pt-1"
          style={{ color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)' }}
        >
          {metadata.model} · {generated} · {metadata.tokenCount} tokens · ¥
          {metadata.costYuan.toFixed(3)}
        </div>
      </div>
    );
  }
);

OLLMProfile.displayName = 'OLLMProfile';
