/**
 * OLoadingState - 加载状态展示。
 *
 * 三种 variant:
 *   - skeleton: 占位骨架 (推荐, 视觉无突变)
 *   - spinner:  转圈
 *   - shimmer:  闪光骨架 (skeleton + 流光动画)
 *
 * SPEC §3.7 在 reduced-motion 下 spinner/shimmer 退化为静态。
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

const variants = cva('w-full', {
  variants: {
    variant: {
      skeleton: '',
      spinner: 'flex items-center justify-center',
      shimmer: '',
    },
  },
  defaultVariants: { variant: 'skeleton' },
});

type LoadingVariantProps = VariantProps<typeof variants>;

export interface OLoadingStateProps
  extends Omit<OBlockBaseProps, 'variant'>,
    LoadingVariantProps {
  /** skeleton 行数。 */
  rows?: number;
  /** spinner 显示文本。 */
  message?: string;
  /** 占位高度 (skeleton/shimmer 单行)。 */
  rowHeight?: string;
}

export const OLoadingState = forwardRef<HTMLDivElement, OLoadingStateProps>(function OLoadingState(
  { variant = 'skeleton', rows = 3, message, rowHeight = '0.75rem', className, theme: _t, size: _s, ...rest },
  ref
) {
  const reduced = useReducedMotion();

  if (variant === 'spinner') {
    return (
      <div
        ref={ref}
        role="status"
        aria-live="polite"
        aria-busy="true"
        className={cn(variants({ variant }), 'flex-col gap-3 py-6', className)}
        {...rest}
      >
        <svg
          width="32"
          height="32"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          className={cn('text-primary', !reduced && 'animate-spin')}
          aria-hidden="true"
        >
          <path d="M21 12a9 9 0 1 1-6.219-8.56" />
        </svg>
        {message ? <span className="text-sm text-muted-foreground">{message}</span> : null}
        <span className="sr-only">Loading{message ? `: ${message}` : ''}</span>
      </div>
    );
  }

  const isShimmer = variant === 'shimmer';
  return (
    <div
      ref={ref}
      role="status"
      aria-busy="true"
      aria-live="polite"
      className={cn(variants({ variant }), 'space-y-2', className)}
      {...rest}
    >
      {Array.from({ length: rows }).map((_, i) => (
        <div
          key={i}
          className={cn(
            'rounded bg-muted @container',
            isShimmer && !reduced && 'relative overflow-hidden',
            isShimmer &&
              !reduced &&
              'before:absolute before:inset-0 before:bg-gradient-to-r before:from-transparent before:via-foreground/10 before:to-transparent before:animate-[shimmer_1.5s_infinite]'
          )}
          style={{
            height: rowHeight,
            width: `${100 - i * 10}%`,
          }}
        />
      ))}
      <span className="sr-only">Loading</span>
      {isShimmer ? (
        <style>{`@keyframes shimmer{0%{transform:translateX(-100%)}100%{transform:translateX(100%)}}`}</style>
      ) : null}
    </div>
  );
});

OLoadingState.displayName = 'OLoadingState';
