/**
 * useFlashOnChange - 五维数据脉冲 hook (Helios Terminal SPEC §7)。
 *
 * 当数值变化超过阈值时,在元素上触发可感知的瞬时反馈。
 * 五维之一即可,可组合使用。
 *
 * 维度:
 *   - color   颜色脉冲    背景 80ms 闪烁,涨绿跌红
 *   - sound   音效脉冲    短促音 (可全局禁用,频率限制)
 *   - haptic  触觉脉冲    移动端 vibrate
 *   - density 密度脉冲    数字字重短暂加粗
 *   - focus   焦点脉冲    父容器边缘呼吸 (严重警报)
 *
 * 用法:
 *   const ref = useFlashOnChange(price, {
 *     modes: ['color', 'density'],
 *     direction: 'auto',
 *   });
 *   return <span ref={ref}>{price}</span>;
 *
 * 加密场景:
 *   - 大单成交时触发 color + sound
 *   - 价格突破时触发 color + density + haptic
 *   - 强制平仓时触发 focus
 */

'use client';

import { useEffect, useRef, useCallback } from 'react';
import { useReducedMotion } from './useReducedMotion';

export type FlashMode = 'color' | 'sound' | 'haptic' | 'density' | 'focus';
export type FlashDirection = 'up' | 'down' | 'neutral' | 'auto';

export interface FlashConfig {
  /** 要触发的维度。可多选。 */
  modes?: FlashMode[];
  /** 持续时间 (ms)。默认 80。 */
  duration?: number;
  /** 变化方向。'auto' 表示根据数值正负自动判断。 */
  direction?: FlashDirection;
  /** 变化阈值。绝对值小于此值不触发。默认 0(任何变化都触发)。 */
  threshold?: number;
  /** 音效 URL。仅 modes 包含 'sound' 时使用。 */
  soundUrl?: string;
  /** 音效音量 0-1。 */
  soundVolume?: number;
  /** focus 模式下,作用到的父容器选择器。默认作用到 ref 元素本身。 */
  focusTarget?: string;
}

// ============================================================
// 全局节流 (避免一秒内 sound/haptic 重复触发)
// ============================================================

const RATE_LIMITS = {
  sound: 333,   // 最多 3 次/秒
  haptic: 200,  // 最多 5 次/秒
};

const lastTriggerTime: Record<string, number> = {
  sound: 0,
  haptic: 0,
};

function throttled(mode: 'sound' | 'haptic'): boolean {
  const now = Date.now();
  if (now - (lastTriggerTime[mode] ?? 0) < RATE_LIMITS[mode]) return false;
  lastTriggerTime[mode] = now;
  return true;
}

// ============================================================
// 全局开关 (用户偏好,localStorage 持久化)
// ============================================================

let GLOBAL_SOUND_ENABLED = true;
let GLOBAL_HAPTIC_ENABLED = true;

if (typeof window !== 'undefined') {
  try {
    GLOBAL_SOUND_ENABLED = localStorage.getItem('helios-sound') !== 'false';
    GLOBAL_HAPTIC_ENABLED = localStorage.getItem('helios-haptic') !== 'false';
  } catch {
    /* SSR or no storage */
  }
}

export function setGlobalSoundEnabled(enabled: boolean): void {
  GLOBAL_SOUND_ENABLED = enabled;
  if (typeof localStorage !== 'undefined') {
    localStorage.setItem('helios-sound', String(enabled));
  }
}

export function setGlobalHapticEnabled(enabled: boolean): void {
  GLOBAL_HAPTIC_ENABLED = enabled;
  if (typeof localStorage !== 'undefined') {
    localStorage.setItem('helios-haptic', String(enabled));
  }
}

// ============================================================
// 五维实现
// ============================================================

function flashColor(el: HTMLElement, direction: FlashDirection, duration: number): void {
  const colorVar =
    direction === 'up'
      ? 'var(--flash-color-up, oklch(0.68 0.20 145 / 0.15))'
      : direction === 'down'
        ? 'var(--flash-color-down, oklch(0.62 0.22 25 / 0.15))'
        : 'var(--muted, oklch(0.5 0 0 / 0.15))';

  // 用 element.animate() 避免覆盖现有 background-color style
  el.animate(
    [
      { backgroundColor: colorVar },
      { backgroundColor: colorVar },
      { backgroundColor: 'transparent' },
    ],
    { duration: duration * 3, easing: 'ease-out' }
  );
}

function flashDensity(el: HTMLElement, duration: number): void {
  el.animate(
    [
      { fontWeight: 'var(--flash-density-weight, 700)' as never },
      { fontWeight: 'inherit' as never },
    ],
    { duration: duration * 3, easing: 'ease-out' }
  );
}

function flashFocus(el: HTMLElement, duration: number): void {
  const shadow = 'var(--flash-focus-shadow, 0 0 24px oklch(0.70 0.25 30))';
  el.animate(
    [
      { boxShadow: '0 0 0 transparent' },
      { boxShadow: shadow },
      { boxShadow: '0 0 0 transparent' },
    ],
    { duration: duration * 8, easing: 'ease-in-out' }
  );
}

function flashSound(soundUrl: string, volume: number): void {
  if (!GLOBAL_SOUND_ENABLED) return;
  if (!throttled('sound')) return;
  try {
    const audio = new Audio(soundUrl);
    audio.volume = Math.max(0, Math.min(1, volume));
    audio.play().catch(() => {
      /* autoplay blocked */
    });
  } catch {
    /* CORS / network */
  }
}

function flashHaptic(): void {
  if (!GLOBAL_HAPTIC_ENABLED) return;
  if (!throttled('haptic')) return;
  if (typeof navigator !== 'undefined' && navigator.vibrate) {
    navigator.vibrate(30);
  }
}

// ============================================================
// 主 Hook
// ============================================================

/**
 * 监听 value 变化,触发五维脉冲。
 *
 * @param value 监听的值 (number 或可转 number 的字符串)
 * @param config 脉冲配置
 * @returns ref - 挂到目标元素
 */
export function useFlashOnChange<T extends number | string | null | undefined>(
  value: T,
  config: FlashConfig = {}
): React.RefCallback<HTMLElement> {
  const {
    modes = ['color'],
    duration = 80,
    direction = 'auto',
    threshold = 0,
    soundUrl,
    soundVolume = 0.3,
    focusTarget,
  } = config;

  const elRef = useRef<HTMLElement | null>(null);
  const prevValueRef = useRef<T>(value);
  const reduced = useReducedMotion();

  // 触发函数
  const trigger = useCallback(
    (resolvedDirection: FlashDirection) => {
      const el = elRef.current;
      if (!el) return;

      for (const mode of modes) {
        switch (mode) {
          case 'color':
            // color 模式始终保留 (即便 reduced motion,因为它不是运动)
            flashColor(el, resolvedDirection, duration);
            break;
          case 'density':
            // density 也保留 (不是运动)
            flashDensity(el, duration);
            break;
          case 'focus':
            if (!reduced) {
              const target = focusTarget
                ? (el.closest(focusTarget) as HTMLElement | null) ?? el
                : el;
              flashFocus(target, duration);
            }
            break;
          case 'sound':
            if (soundUrl) flashSound(soundUrl, soundVolume);
            break;
          case 'haptic':
            flashHaptic();
            break;
        }
      }
    },
    [modes, duration, reduced, focusTarget, soundUrl, soundVolume]
  );

  // value 变化检测
  useEffect(() => {
    const prev = prevValueRef.current;
    prevValueRef.current = value;

    if (prev === undefined || prev === null || value === undefined || value === null) return;

    const prevNum = typeof prev === 'string' ? parseFloat(prev) : (prev as number);
    const nextNum = typeof value === 'string' ? parseFloat(value) : (value as number);

    if (Number.isNaN(prevNum) || Number.isNaN(nextNum)) return;

    const diff = nextNum - prevNum;
    if (Math.abs(diff) < threshold) return;
    if (diff === 0) return;

    const resolvedDirection: FlashDirection =
      direction !== 'auto' ? direction : diff > 0 ? 'up' : 'down';

    trigger(resolvedDirection);
  }, [value, direction, threshold, trigger]);

  // ref callback
  return useCallback((el: HTMLElement | null) => {
    elRef.current = el;
  }, []);
}

/**
 * 手动触发脉冲(不依赖 value 变化)。
 *
 * 用法:
 *   const { flash } = useManualFlash({ modes: ['focus'] });
 *   // 在某事件中:
 *   flash('up');
 */
export function useManualFlash(config: FlashConfig = {}): {
  ref: React.RefCallback<HTMLElement>;
  flash: (direction?: FlashDirection) => void;
} {
  const {
    modes = ['color'],
    duration = 80,
    soundUrl,
    soundVolume = 0.3,
    focusTarget,
  } = config;

  const elRef = useRef<HTMLElement | null>(null);
  const reduced = useReducedMotion();

  const flash = useCallback(
    (direction: FlashDirection = 'neutral') => {
      const el = elRef.current;
      if (!el) return;
      for (const mode of modes) {
        switch (mode) {
          case 'color':
            flashColor(el, direction, duration);
            break;
          case 'density':
            flashDensity(el, duration);
            break;
          case 'focus':
            if (!reduced) {
              const target = focusTarget
                ? (el.closest(focusTarget) as HTMLElement | null) ?? el
                : el;
              flashFocus(target, duration);
            }
            break;
          case 'sound':
            if (soundUrl) flashSound(soundUrl, soundVolume);
            break;
          case 'haptic':
            flashHaptic();
            break;
        }
      }
    },
    [modes, duration, reduced, focusTarget, soundUrl, soundVolume]
  );

  const ref = useCallback((el: HTMLElement | null) => {
    elRef.current = el;
  }, []);

  return { ref, flash };
}
