/**
 * WorkspaceProvider - 可拖拽工作区,基于 dockview。
 *
 * 设计:
 *   - 包装 dockview 的 API,暴露 WorkspaceProtocol 简化版
 *   - 支持 panel 添加/移除、布局序列化、URL 分享、preset 切换
 *   - v1.0 v: dockview API 可能改动,在 props 直接传 dockview 实例的 ref
 *
 * 注意:dockview 是 zero-dep 库,需要消费方安装。
 * Provider 本身不引入 dockview (peer dep),只暴露协议。
 *
 * Block 真正的 panel 容器组件 OWorkspaceFrame 在 frames/ 内独立实现,
 * 它会用 dockview-react。
 */
'use client';

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import type {
  WorkspaceProtocol,
  PanelDescriptor,
  SerializedLayout,
} from '../protocols';

const LAYOUT_VERSION = 1;

const WorkspaceContext = createContext<WorkspaceProtocol | null>(null);

interface WorkspaceProviderProps {
  children: ReactNode;
  /** 预设 preset 库:name → 布局。 */
  presets?: Record<string, SerializedLayout>;
  /** 默认 preset 名。 */
  defaultPreset?: string;
  /** localStorage 持久化的 key (默认开启)。 */
  storageKey?: string;
}

/**
 * 外部桥接:OWorkspaceFrame 通过 setBridge() 把自己的 dockview API 注册进来,
 * 这样 Provider 才能调用底层 dockview。
 */
interface DockviewBridge {
  addPanel: (panel: PanelDescriptor, position?: string) => void;
  removePanel: (id: string) => void;
  saveLayout: () => unknown;
  loadLayout: (grid: unknown) => void;
  reset: () => void;
}

interface WorkspaceContextValue extends WorkspaceProtocol {
  /** 内部用:OWorkspaceFrame 注册自己的 dockview bridge。 */
  __setBridge: (bridge: DockviewBridge | null) => void;
}

export function WorkspaceProvider({
  children,
  presets = {},
  defaultPreset,
  storageKey = 'helios:workspace',
}: WorkspaceProviderProps) {
  const bridgeRef = useRef<DockviewBridge | null>(null);
  const panelsRef = useRef<PanelDescriptor[]>([]);
  const [, force] = useState(0);

  const setBridge = useCallback((bridge: DockviewBridge | null) => {
    bridgeRef.current = bridge;
    if (bridge && defaultPreset && presets[defaultPreset]) {
      // 启动时加载默认 preset
      const layout = presets[defaultPreset];
      bridge.loadLayout(layout.grid);
      panelsRef.current = layout.panels;
      force((v) => v + 1);
    } else if (bridge) {
      // 尝试从 localStorage 恢复
      try {
        const raw = localStorage.getItem(storageKey);
        if (raw) {
          const layout: SerializedLayout = JSON.parse(raw);
          if (layout.version === LAYOUT_VERSION) {
            bridge.loadLayout(layout.grid);
            panelsRef.current = layout.panels;
            force((v) => v + 1);
          }
        }
      } catch {
        // 忽略恢复错误
      }
    }
  }, [defaultPreset, presets, storageKey]);

  function persistAuto(): void {
    if (!bridgeRef.current) return;
    try {
      const layout: SerializedLayout = {
        version: LAYOUT_VERSION,
        panels: panelsRef.current,
        grid: bridgeRef.current.saveLayout(),
      };
      localStorage.setItem(storageKey, JSON.stringify(layout));
    } catch {
      // localStorage 不可用时静默
    }
  }

  const protocol = useMemo<WorkspaceContextValue>(
    () => ({
      addPanel(panel, position) {
        bridgeRef.current?.addPanel(panel, position);
        panelsRef.current = [...panelsRef.current.filter((p) => p.id !== panel.id), panel];
        persistAuto();
        force((v) => v + 1);
      },
      removePanel(id) {
        bridgeRef.current?.removePanel(id);
        panelsRef.current = panelsRef.current.filter((p) => p.id !== id);
        persistAuto();
        force((v) => v + 1);
      },
      saveLayout() {
        if (!bridgeRef.current) {
          return { version: LAYOUT_VERSION, panels: panelsRef.current, grid: null };
        }
        return {
          version: LAYOUT_VERSION,
          panels: panelsRef.current,
          grid: bridgeRef.current.saveLayout(),
        };
      },
      loadLayout(layout) {
        if (layout.version !== LAYOUT_VERSION) {
          console.warn('[WorkspaceProvider] layout version mismatch, ignoring');
          return;
        }
        bridgeRef.current?.loadLayout(layout.grid);
        panelsRef.current = layout.panels;
        persistAuto();
        force((v) => v + 1);
      },
      reset() {
        bridgeRef.current?.reset();
        panelsRef.current = [];
        try {
          localStorage.removeItem(storageKey);
        } catch {
          // ignore
        }
        force((v) => v + 1);
      },
      shareURL() {
        if (typeof window === 'undefined') return '';
        try {
          const layout = this.saveLayout();
          const compressed = btoa(JSON.stringify(layout));
          const url = new URL(window.location.href);
          url.searchParams.set('layout', compressed);
          return url.toString();
        } catch {
          return window.location.href;
        }
      },
      presets: Object.keys(presets),
      loadPreset(name) {
        const layout = presets[name];
        if (layout) {
          this.loadLayout(layout);
        }
      },
      __setBridge: setBridge,
    }),
    // persistAuto 是 provider 闭包内函数,通过 ref 操作 state,
    // 不需要随 render 重建 protocol。
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [presets, setBridge, storageKey]
  );

  return <WorkspaceContext.Provider value={protocol}>{children}</WorkspaceContext.Provider>;
}

WorkspaceProvider.displayName = 'WorkspaceProvider';

export function useWorkspace(): WorkspaceProtocol {
  const ctx = useContext(WorkspaceContext);
  if (!ctx) {
    return {
      addPanel: () => {},
      removePanel: () => {},
      saveLayout: () => ({ version: LAYOUT_VERSION, panels: [], grid: null }),
      loadLayout: () => {},
      reset: () => {},
      shareURL: () => '',
      presets: [],
      loadPreset: () => {},
    };
  }
  return ctx;
}

/**
 * 内部用:OWorkspaceFrame 注册自己的 bridge。
 */
export function useWorkspaceBridge(): (bridge: DockviewBridge | null) => void {
  const ctx = useContext(WorkspaceContext) as WorkspaceContextValue | null;
  if (!ctx) return () => {};
  return ctx.__setBridge;
}
