/**
 * OEpistemicCard — 带认识论可信度标注的内容卡片(认识论原语)。
 *
 * 用于:
 *   - AII Query 结果(每条 KU 一卡)
 *   - AII Ingest 结果(已入库 / 隔离区 / 拒绝)
 *   - AII Graph Health 待裁决项
 *   - 任何"内容 + 可信度标注"场景(Stratum 引用 / Tide 信号 / Aegis 根因)
 *
 * 设计:
 *   - grade 徽标必现(集成 OEpistemicBadge)
 *   - defeaters 非空时强制显示展开槽(红线 #2 不平滑)
 *   - 可选 expandable sections(符号本体 / 证据 / score / debug)
 *   - 隔离区 / unverified 视觉强警示(红线 #1)
 *
 * 来源:AII-FRONTEND-REQ-001 Page 1/2/3 共用。
 */
import { forwardRef, useState, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import { OCard } from '../OCard';
import { OEpistemicBadge } from '../OEpistemicBadge';
import { useUiLang } from '../../lang/LangProvider';
import type {
  EpistemicGrade,
  EpistemicDefeater,
} from '../../types/epistemic';
import type { OBlockBaseProps } from '../../lib/types';

export interface EpistemicCardSection {
  /** Section 唯一标识。 */
  id: string;
  /** 展开按钮 label。 */
  label: string;
  /** 展开后的内容(项目自由渲染:OJsonViewer / 文本 / 自定义)。 */
  content: ReactNode;
  /** 默认是否展开。 */
  defaultOpen?: boolean;
}

export interface OEpistemicCardProps extends Omit<OBlockBaseProps, 'variant'> {
  // 内容
  title?: string;
  body: ReactNode;
  /** knowledge_type / source_kind 等类型标识。 */
  kind?: string;

  // 认识论元数据(必传)
  grade: EpistemicGrade;
  source?: string;
  defeaters?: EpistemicDefeater[];

  // 可选附加 metadata(score / 时间 / 作者等)
  metadata?: Array<{ label: string; value: ReactNode }>;

  // 展开 sections
  expandable?: EpistemicCardSection[];

  // 操作
  onClick?: () => void;
  /** action bar 自定义 ReactNode(裁决按钮等)。 */
  actions?: ReactNode;

  /** 强调态(隔离区 / unverified 用) — 给整卡加警示边框,默认根据 grade 自动判断。 */
  emphasize?: boolean | 'auto';
}

/** auto 模式:unverified / contradicted / pending_verification 自动强调。 */
function shouldEmphasize(grade: EpistemicGrade, emphasize: OEpistemicCardProps['emphasize']): boolean {
  if (emphasize === true) return true;
  if (emphasize === false) return false;
  // auto / undefined:风险态自动加边框
  return grade === 'unverified' || grade === 'contradicted' || grade === 'pending_verification';
}

function emphasizeColor(grade: EpistemicGrade): string {
  if (grade === 'unverified') return 'var(--warning)';
  if (grade === 'contradicted') return 'var(--destructive)';
  if (grade === 'pending_verification') return 'var(--warning)';
  return 'var(--border)';
}

export const OEpistemicCard = forwardRef<HTMLElement, OEpistemicCardProps>(
  function OEpistemicCard(
    {
      title,
      body,
      kind,
      grade,
      source,
      defeaters = [],
      metadata,
      expandable = [],
      onClick,
      actions,
      emphasize = 'auto',
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const { tr } = useUiLang();
    const emp = shouldEmphasize(grade, emphasize);
    const empColor = emp ? emphasizeColor(grade) : undefined;
    const hasDefeaters = defeaters.length > 0;

    // 内部 toggle state(展开 sections)
    const initialOpen: Record<string, boolean> = {};
    expandable.forEach((s) => {
      if (s.defaultOpen) initialOpen[s.id] = true;
    });
    const [open, setOpen] = useState<Record<string, boolean>>(initialOpen);
    const [showDefeaters, setShowDefeaters] = useState(false);

    const toggle = (id: string) => setOpen((p) => ({ ...p, [id]: !p[id] }));

    return (
      <OCard
        ref={ref as any}
        as="article"
        container
        padded={false}
        emphasis={emp}
        accentColor={emp ? empColor : undefined}
        interactive={!!onClick}
        elevation="flat"
        className={cn(
          'flex flex-col gap-2 px-3 py-2',
          onClick && 'hover:bg-muted/30 transition-colors',
          className
        )}
        onClick={onClick}
        aria-label={title ?? tr('认识论内容卡', 'Epistemic content card')}
      >
        {/* 顶部:kind + grade badge */}
        <header className="flex flex-col @[280px]:flex-row items-start @[280px]:justify-between gap-2">
          <div className="flex flex-col min-w-0 gap-0.5">
            {kind && (
              <span className="text-[10px] uppercase tracking-[0.04em] font-semibold text-muted-foreground">
                {kind}
              </span>
            )}
            {title && (
              <h3 className="text-base font-bold leading-tight tracking-[-0.01em]">{title}</h3>
            )}
          </div>
          <OEpistemicBadge
            grade={grade}
            defeaterCount={defeaters.length}
            {...(source ? { source } : {})}
          />
        </header>

        {/* 主 body */}
        <div className="text-sm leading-relaxed">{body}</div>

        {/* metadata 行 */}
        {metadata && metadata.length > 0 && (
          <div className="flex items-center gap-3 text-xs text-muted-foreground flex-wrap">
            {metadata.map((m, i) => (
              <span key={i}>
                <span className="text-muted-foreground/70">{m.label}:</span>{' '}
                <span className="text-foreground">{m.value}</span>
              </span>
            ))}
          </div>
        )}

        {/* defeaters 区(强制显示 if 非空 — 红线 #2) */}
        {hasDefeaters && (
          <div
            className="rounded border px-2 py-1.5 text-xs"
            style={{
              borderColor: 'var(--destructive)',
              backgroundColor: 'color-mix(in srgb, var(--destructive) 8%, transparent)',
            }}
          >
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                setShowDefeaters((v) => !v);
              }}
              aria-expanded={showDefeaters}
              className="flex items-center gap-1 font-medium hover:opacity-80"
              style={{ color: 'var(--destructive)' }}
            >
              <span aria-hidden="true">{showDefeaters ? '▾' : '▸'}</span>
              ⚠ {tr('存在', 'Has')} {defeaters.length} {tr('条反证', 'defeaters')}
            </button>
            {showDefeaters && (
              <ul className="mt-1.5 list-none p-0 m-0 flex flex-col gap-0.5 pl-3">
                {defeaters.map((d) => (
                  <li
                    key={d.id}
                    className="text-foreground"
                    style={{ borderLeft: '2px solid var(--destructive)', paddingLeft: 6 }}
                  >
                    {d.text}
                    {d.weight !== undefined && (
                      <span className="ml-1 text-muted-foreground">
                        ({tr('强度', 'weight')} {d.weight.toFixed(2)})
                      </span>
                    )}
                  </li>
                ))}
              </ul>
            )}
          </div>
        )}

        {/* expandable sections */}
        {expandable.length > 0 && (
          <div className="flex flex-col gap-1 border-t border-border pt-2">
            {expandable.map((s) => (
              <div key={s.id}>
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    toggle(s.id);
                  }}
                  aria-expanded={!!open[s.id]}
                  className="flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground"
                >
                  <span aria-hidden="true">{open[s.id] ? '▾' : '▸'}</span>
                  {s.label}
                </button>
                {open[s.id] && <div className="mt-1 pl-3 text-xs">{s.content}</div>}
              </div>
            ))}
          </div>
        )}

        {/* actions 槽 */}
        {actions && (
          <div
            className="flex items-center gap-2 pt-2 border-t border-border"
            onClick={(e) => e.stopPropagation()}
          >
            {actions}
          </div>
        )}
      </OCard>
    );
  }
);

OEpistemicCard.displayName = 'OEpistemicCard';
