/**
 * OGradientFrame - 运动渐变边框 Frame (Wiki 明确要求的视觉)。
 *
 * 实现方式: CSS @property + conic-gradient + 旋转动画。
 * 关键帧定义在 themes/index.css (helios-gradient-spin)。
 *
 * SPEC §3.5 类 2 视觉增强。在 prefers-reduced-motion 下自动停止动画。
 *
 * @example
 * <OGradientFrame speed="normal" thickness={2}>
 *   <OKPICard data={...} />
 * </OGradientFrame>
 */
'use client';

import { forwardRef, useMemo, type CSSProperties, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';
import { useReducedMotion } from '../../hooks/useReducedMotion';

const SPEED_DURATION = {
  slow: '8s',
  normal: '4s',
  fast: '2s',
} as const;

export interface OGradientFrameProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 旋转速度。 */
  speed?: keyof typeof SPEED_DURATION;
  /** 边框粗细 (px)。 */
  thickness?: number;
  /**
   * 渐变色 (CSS 颜色字符串数组)。
   * 留空则使用当前主题的 --gradient-border。
   */
  colors?: string[];
  /** 圆角 (CSS 值)。 */
  radius?: string;
  /** 内边距 (CSS 值,默认 0)。 */
  padding?: string;
  /** 关闭动画 (静态渐变边框)。 */
  static?: boolean;
  children: ReactNode;
}

export const OGradientFrame = forwardRef<HTMLDivElement, OGradientFrameProps>(
  function OGradientFrame(
    {
      speed = 'normal',
      thickness = 2,
      colors,
      radius = 'var(--radius-md)',
      padding = '0',
      static: isStatic = false,
      className,
      children,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const reduced = useReducedMotion();
    const animate = !isStatic && !reduced;

    const gradient = useMemo(() => {
      if (colors && colors.length > 0) {
        const stops = [...colors, colors[0]].join(', ');
        return `conic-gradient(from var(--gradient-angle, 0deg), ${stops})`;
      }
      return 'var(--gradient-border)';
    }, [colors]);

    const wrapperStyle: CSSProperties = {
      padding: `${thickness}px`,
      borderRadius: radius,
      background: gradient,
      animation: animate ? `helios-gradient-spin ${SPEED_DURATION[speed]} linear infinite` : 'none',
    };

    const innerStyle: CSSProperties = {
      borderRadius: `calc(${radius} - ${thickness}px)`,
      padding,
    };

    return (
      <div
        ref={ref}
        className={cn('relative inline-block', className)}
        style={wrapperStyle}
        data-animated={animate}
      >
        <div className="bg-card text-card-foreground" style={innerStyle}>
          {children}
        </div>
      </div>
    );
  }
);

OGradientFrame.displayName = 'OGradientFrame';
