/**
 * OGlobe3D - 3D 地球 (类 3 重型)。
 *
 * SPEC §3.5 类 3 + §3.6 性能 budget:
 *   - bundle:  three + R3F + drei 通过 dynamic import 拆出 main
 *   - GPU:    tier ≤ 1 时强制降级到 2D fallback
 *   - reduced-motion: 关闭自动旋转
 *   - fallback prop 必填 (SPEC §3.7 硬约束)
 *
 * @example
 * <OGlobe3D
 *   data={{ markers: [{ lat: 22.5, lng: 114, value: 80, label: 'Shenzhen' }] }}
 *   fallback={<O2DWorldMap data={...} />}
 * />
 */
'use client';

import { Suspense, lazy, forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { useGpuTier } from '../../hooks/useGpuTier';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import { useHeliosChartColors } from '../../lib/chart-tokens';
import type { OBlockDataProps, OHeavyBlockProps } from '../../lib/types';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import type { OGlobe3DData } from './OGlobe3D.types';

const GlobeScene = lazy(() =>
  import('./OGlobe3D.scene').then((m) => ({ default: m.GlobeScene }))
);

export interface OGlobe3DProps extends OBlockDataProps<OGlobe3DData>, OHeavyBlockProps {
  /** 自动旋转 (默认 true,reduced-motion 自动关)。 */
  autoRotate?: boolean;
  /** 鼠标交互 (拖拽缩放)。默认 true。 */
  interactive?: boolean;
  /** 容器高度 (CSS 值)。默认 400px。 */
  height?: string | number;
  /** 数据点颜色 (CSS 值)。默认跟随主题 --chart-1。 */
  markerColor?: string;
  /** arcs 颜色。默认跟随主题 --chart-2。 */
  arcColor?: string;
  /** 地球线框颜色。默认跟随主题 --border。 */
  globeColor?: string;
  /** 强制使用 fallback (用于测试或主动降级)。 */
  forceFallback?: boolean;
}

const DefaultFallback = ({ data }: { data: OGlobe3DData }) => (
  <div className="w-full h-full bg-card border border-border rounded-md p-4 flex flex-col items-center justify-center text-center gap-2">
    <span className="text-sm text-muted-foreground">3D unavailable — showing data summary</span>
    <span className="text-2xl font-bold">{data.markers.length}</span>
    <span className="text-xs text-muted-foreground">global data points</span>
  </div>
);

export const OGlobe3D = forwardRef<HTMLDivElement, OGlobe3DProps>(function OGlobe3D(
  {
    data,
    loading,
    error,
    empty,
    autoRotate = true,
    interactive = true,
    height = 400,
    markerColor,
    arcColor,
    globeColor,
    fallback,
    forceFallback = false,
    className,
    theme: _t,
    size: _s,
  },
  ref
) {
  const state = resolveBlockState({ data, loading, error, empty });
  const gpu = useGpuTier();
  const reduced = useReducedMotion();
  // #4: WebGL 读不到 CSS 变量,这里把主题 token 解析成具体色值传给 three.js 场景,
  // 使地球/数据点/弧线跟随 [data-theme] 切换(未显式传色时)。
  const chart = useHeliosChartColors();
  const resolvedMarker = markerColor ?? chart.series[0];
  const resolvedArc = arcColor ?? chart.series[1];
  const resolvedGlobe = globeColor ?? chart.border;

  const containerStyle = { height: typeof height === 'number' ? `${height}px` : height };

  if (state === 'loading')
    return (
      <div
        ref={ref}
        className={cn('rounded-md border border-border bg-card p-4 w-full', className)}
        style={containerStyle}
      >
        <OLoadingState variant="spinner" message="Loading 3D scene..." />
      </div>
    );
  if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
  if (state === 'empty' || !data || data.markers.length === 0)
    return (
      <OEmptyState
        ref={ref}
        title="No data points"
        description="There are no markers to plot on the globe."
        className={className}
      />
    );

  // GPU tier 降级:tier ≤ 1 用 fallback
  const shouldFallback = forceFallback || gpu.tier <= 1;
  if (shouldFallback) {
    return (
      <div
        ref={ref}
        className={cn('relative w-full overflow-hidden rounded-md border border-border', className)}
        style={containerStyle}
        data-fallback="true"
      >
        {fallback ?? <DefaultFallback data={data} />}
      </div>
    );
  }

  return (
    <div
      ref={ref}
      className={cn(
        'relative w-full overflow-hidden rounded-md border border-border bg-background @container',
        className
      )}
      style={containerStyle}
      data-gpu-tier={gpu.tier}
    >
      <Suspense
        fallback={
          <div className="w-full h-full flex items-center justify-center">
            <OLoadingState variant="spinner" message="Loading 3D..." />
          </div>
        }
      >
        <GlobeScene
          data={data}
          autoRotate={autoRotate && !reduced}
          interactive={interactive}
          markerColor={resolvedMarker}
          arcColor={resolvedArc}
          globeColor={resolvedGlobe}
        />
      </Suspense>
    </div>
  );
});

OGlobe3D.displayName = 'OGlobe3D';
