/**
 * resolveBlockState - 数据 Block 状态机判定。
 *
 * 把 props (data / loading / error / empty) 收敛为一个明确状态,
 * Block 内不再到处写 if 链。
 *
 * SPEC §5.3 Block 永远受控。
 *
 * @example
 * function OKPICard({ data, loading, error, empty }: OKPICardProps) {
 *   const state = resolveBlockState({ data, loading, error, empty });
 *   if (state === 'loading') return <OLoadingState />;
 *   if (state === 'error')   return <OErrorState error={error!} />;
 *   if (state === 'empty')   return <OEmptyState title="No data" />;
 *   return <ActualRender data={data!} />;
 * }
 */

import type { OBlockDataState } from './types';

export type BlockState = 'loading' | 'error' | 'empty' | 'ready';

export function resolveBlockState<T>(input: OBlockDataState<T>): BlockState {
  if (input.error) return 'error';
  if (input.loading) return 'loading';
  if (input.data == null) return 'loading';
  if (input.empty) return 'empty';
  return 'ready';
}
