/**
 * PresenceProvider - 协作 presence (v1.0 占位实现)。
 *
 * v1.0 提供接口和 no-op 实现。
 * v2.0 可以接 Liveblocks 或 Yjs 真实实现,API 不变。
 */
'use client';

import { createContext, useContext, useMemo, type ReactNode } from 'react';
import type { PresenceProtocol, PresenceState } from '../protocols';

const EMPTY: PresenceState = {
  users: [],
  cursors: new Map(),
};

const PresenceContext = createContext<PresenceProtocol | null>(null);

interface PresenceProviderProps {
  children: ReactNode;
  enabled?: boolean;
}

export function PresenceProvider({ children, enabled = false }: PresenceProviderProps) {
  const protocol = useMemo<PresenceProtocol>(
    () => ({
      isEnabled: enabled,
      getState() {
        return EMPTY;
      },
      subscribe() {
        return () => {};
      },
      updateCursor() {
        // no-op
      },
    }),
    [enabled]
  );

  return <PresenceContext.Provider value={protocol}>{children}</PresenceContext.Provider>;
}

PresenceProvider.displayName = 'PresenceProvider';

export function usePresence(): PresenceProtocol {
  const ctx = useContext(PresenceContext);
  return (
    ctx ?? {
      isEnabled: false,
      getState: () => EMPTY,
      subscribe: () => () => {},
      updateCursor: () => {},
    }
  );
}
