/**
 * OFilterChip — 多选 / 单选过滤标签组。
 *
 * 用途:列表 / 表格顶部按状态过滤(running/exited/restarting, info/warn/critical 等)。
 *
 * 设计:
 *   - 多选(默认)或单选模式
 *   - 每个 chip 可选显示计数
 *   - "全部" 选项(可选)
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OFilterChipOption {
  value: string;
  label: string;
  count?: number;
  /** chip 颜色提示(常用于 severity 着色)。 */
  colorVar?: string;
}

export interface OFilterChipProps extends Omit<OBlockBaseProps, 'variant'> {
  label?: string;
  options: OFilterChipOption[];
  selected: string[];
  onChange: (selected: string[]) => void;
  /** 单选模式(默认多选)。 */
  single?: boolean;
  /** 显示"全部"选项(选中时清空 selected)。 */
  showAll?: boolean;
  allLabel?: string;
}

export const OFilterChip = forwardRef<HTMLDivElement, OFilterChipProps>(function OFilterChip(
  {
    label,
    options,
    selected,
    onChange,
    single = false,
    showAll = false,
    allLabel = '全部',
    className,
    theme: _t,
    size: _s,
  },
  ref
) {
  const toggle = (value: string) => {
    if (single) {
      onChange(selected.includes(value) ? [] : [value]);
      return;
    }
    if (selected.includes(value)) {
      onChange(selected.filter((v) => v !== value));
    } else {
      onChange([...selected, value]);
    }
  };

  const allSelected = selected.length === 0;

  return (
    <div
      ref={ref}
      role="group"
      aria-label={label ?? '过滤'}
      className={cn('inline-flex items-center gap-1 flex-wrap', className)}
    >
      {label && (
        <span className="text-xs text-muted-foreground mr-1">{label}:</span>
      )}
      {showAll && (
        <button
          type="button"
          onClick={() => onChange([])}
          aria-pressed={allSelected}
          className={cn(
            'px-2 py-0.5 text-xs rounded border transition-colors @container',
            allSelected
              ? 'bg-foreground text-background border-foreground'
              : 'bg-card text-foreground border-border hover:bg-muted'
          )}
        >
          {allLabel}
        </button>
      )}
      {options.map((opt) => {
        const isSel = selected.includes(opt.value);
        return (
          <button
            key={opt.value}
            type="button"
            onClick={() => toggle(opt.value)}
            aria-pressed={isSel}
            className={cn(
              'inline-flex items-center gap-1 px-2 py-0.5 text-xs rounded border transition-colors',
              isSel
                ? 'border-current'
                : 'bg-card text-foreground border-border hover:bg-muted'
            )}
            style={
              isSel
                ? {
                    backgroundColor: opt.colorVar
                      ? `color-mix(in srgb, var(${opt.colorVar}) 15%, transparent)`
                      : undefined,
                    color: opt.colorVar ? `var(${opt.colorVar})` : undefined,
                    borderColor: opt.colorVar
                      ? `var(${opt.colorVar})`
                      : 'var(--foreground)',
                  }
                : undefined
            }
          >
            <span>{opt.label}</span>
            {opt.count !== undefined && (
              <span
                className={cn(
                  'text-[10px]',
                  !isSel && 'text-muted-foreground'
                )}
              >
                {opt.count}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
});

OFilterChip.displayName = 'OFilterChip';
