// ============================================================
// Lock 1: Agent Invocation (AgentRunner.run)
// ============================================================

/**
 * 后端 AgentRunner.run() 完整返回 = AgentResult.
 *
 * 后端签名:
 *   async def run(agent: Agent, user_id: str, params: dict) -> AgentResult
 */
export interface AgentResult {
  /** UUID 字符串 */
  run_id: string;
  user_id: string;
  agent_name: AgentName;
  /** 入参 dict (前端不假设 schema,开放传递) */
  params: Record<string, unknown>;
  /** ISO 8601 UTC string */
  started_at: string;
  /** ⚠️ 单位是**秒** (float),不是毫秒。前端最常见踩坑点。 */
  elapsed_seconds: number;
  total_input_tokens: number;
  total_output_tokens: number;
  /** 美元成本 */
  cost_usd: number;
  /** 详细见 Lock 2 */
  trace: AgentTraceStep[];
  /** Citation 强制 (Stratum ADR) */
  citations: AgentCitation[];
  /** ⚠️ 平铺 dict,**非嵌套对象**。前端不能假设固定 schema。 */
  output: Record<string, unknown>;
  /** 完成态(可选,运行中不存在)*/
  completed_at?: string;
  /** 失败信息(可选)*/
  error_message?: string;
  /**
   * 状态。
   * ⚠️ v1.2 修正(基于 STRATUM_API_v1.md 大纲 §1.7):
   *   - `timeout` 是 Stratum 独有(后端 task 超时主动 kill)
   *   - 没有 `pending`(Stratum 不排队,创建即 running)
   */
  status?: AgentRunStatus;
}

/**
 * Agent run 生命周期状态。
 *
 * 基于 STRATUM_API_v1.md §1.7 agent_run status enum.
 *
 * - running: 执行中
 * - completed: 成功完成
 * - failed: 失败(error_message 必填)
 * - timeout: 超过 max_runtime_seconds 被 kill
 */
export type AgentRunStatus = 'running' | 'completed' | 'failed' | 'timeout';

export type AgentName =
  | 'knowledge_curator'
  | 'reading_companion'
  | 'daily_digest'
  | 'translation_worker'
  | 'lint_bot'
  /**
   * audio_generator — F5-TTS 生成 substrate 音频朗读。
   *
   * ⚠️ v1.0 不可用(upstream image ghcr.io/swivid/f5-tts:main torch 冲突)。
   * scheduled_jobs.nightly_audio_gen 默认 enabled=false。
   * 调用 run() 立即 raise NotImplementedError("TTS unavailable v1.0")。
   *
   * v1.1 计划修(自写 wrapper 或换 image)。
   *
   * UI 处理:配合 StratumFeature.TTS / isStratumFeatureEnabled() 隐藏或禁用。
   */
  | 'audio_generator';

