/**
 * 推送请求入参.
 *
 * ⚠️ 字段名:
 *   - body (不是 message / content)
 *   - channels_preference (不是 channels)
 */
export interface PushRequest {
  user_id: string;
  title: string;
  /** ⚠️ 字段名是 body,不是 message/content */
  body: string;
  /** ⚠️ 字段名是 channels_preference,数组,优先级排序 */
  channels_preference: PushChannel[];
  /** 跳转 deep link */
  deep_link?: string;
  /** 开放 dict */
  metadata?: Record<string, unknown>;
}

/**
 * 推送渠道。
 *
 * ⚠️ v1.2 修正(基于 STRATUM_API_v1.md 大纲 §6.2):
 *   Stratum 用 VAPID Web Push,**不是** telegram/dingtalk(那是 Aegis 项目)。
 *
 * - web: VAPID Web Push(浏览器原生推送,需用户授权)
 * - email: SMTP
 * - wechat: placeholder,Phase 14+ 实施
 * - system: 本地 log,测试用
 */
export type PushChannel = 'web' | 'email' | 'wechat' | 'system';

/**
 * 推送结果 — **数组**,每个尝试的 channel 一条.
 *
 * ⚠️ 返回结构是 PushResult[],不是单个 PushResult.
 * 后端会按 channels_preference 顺序尝试,成功后停止 → 通常数组只有 1 条.
 */
export interface PushResult {
  channel: PushChannel;
  success: boolean;
  recipient: string;
  error_message: string | null;
  /** ISO 8601 UTC datetime */
  sent_at: string;
}

/**
 * 用户的推送订阅.
 */
export interface PushSubscription {
  user_id: string;
  channel: PushChannel;
  recipient: string;
  enabled: boolean;
}

