/**
 * OHeroBanner - 营销首屏 Block。
 *
 * 大号首屏组合: 背景 + 大标题 + 副标题 + CTA + 可选媒体。
 *
 * 背景可选:
 *   - 'gradient'  CSS 渐变
 *   - 'particle'  OParticleBackground (类 2)
 *   - 'flow'      OFlowField (类 3,GPU 检测自动降级)
 *   - 'image'     用户传入图片 URL
 *   - 'plain'     纯 bg-background
 *
 * 文字进场动画通过 motion + stagger 实现,reduced-motion 直出。
 */
'use client';

import { forwardRef, type ReactNode } from 'react';
import { motion } from 'motion/react';
import { cn } from '../../lib/cn';
import { OButton } from '../OButton';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';
import { OParticleBackground } from '../OParticleBackground';
import { OFlowField } from '../OFlowField';

export interface OHeroBannerProps extends Omit<OBlockBaseProps, 'size'> {
  /** 主标题。 */
  title: ReactNode;
  /** 副标题/描述。 */
  subtitle?: ReactNode;
  /** 顶部小标签 (e.g. "v0.2 NEW")。 */
  eyebrow?: ReactNode;
  /** 主 CTA 按钮。 */
  primaryCta?: { label: string; href?: string; onClick?: () => void };
  /** 次 CTA 按钮。 */
  secondaryCta?: { label: string; href?: string; onClick?: () => void };
  /** 右侧媒体 (图片/产品截图)。两栏布局。 */
  media?: ReactNode;
  /** 背景类型。 */
  background?: 'gradient' | 'particle' | 'flow' | 'image' | 'plain';
  /** background='image' 时的 URL。 */
  backgroundImage?: string;
  /** 布局方向。 */
  layout?: 'centered' | 'split-left' | 'split-right';
  /** 高度档位。 */
  size?: 'sm' | 'md' | 'lg' | 'fullscreen';
  /** 顶部 / 底部 padding。 */
  padded?: boolean;
}

const SIZE_CLASS = {
  sm: 'min-h-[40vh]',
  md: 'min-h-[60vh]',
  lg: 'min-h-[80vh]',
  fullscreen: 'min-h-screen',
};

function HeroBackground({
  background,
  backgroundImage,
}: {
  background: NonNullable<OHeroBannerProps['background']>;
  backgroundImage?: string;
}) {
  if (background === 'plain') return null;
  if (background === 'gradient') {
    return (
      <div
        aria-hidden="true"
        className="absolute inset-0 -z-10"
        style={{
          background:
            'radial-gradient(80% 60% at 30% 30%, color-mix(in oklch, var(--primary) 30%, transparent), transparent), radial-gradient(60% 60% at 70% 70%, color-mix(in oklch, var(--secondary) 25%, transparent), transparent)',
        }}
      />
    );
  }
  if (background === 'image' && backgroundImage) {
    return (
      <>
        <img
          src={backgroundImage}
          alt=""
          aria-hidden="true"
          className="absolute inset-0 -z-10 w-full h-full object-cover"
        />
        <div aria-hidden className="absolute inset-0 -z-10 bg-background/60" />
      </>
    );
  }
  if (background === 'particle') {
    return (
      <div aria-hidden className="absolute inset-0 -z-10">
        <OParticleBackground density={0.6} connectDistance={140} />
      </div>
    );
  }
  if (background === 'flow') {
    return <OFlowField intensity={0.6} colorScheme="cyan_purple" />;
  }
  return null;
}

function CtaButton({
  cta,
  primary,
}: {
  cta: { label: string; href?: string; onClick?: () => void };
  primary: boolean;
}) {
  // primary CTA 的发光效果(HeroBanner 特有视觉),作为附加 className
  const glowCls = primary
    ? 'shadow-[0_0_24px_color-mix(in_oklch,var(--primary)_30%,transparent)]'
    : '';
  const variant = primary ? 'primary' : 'outline';
  if (cta.href) {
    // 链接型 CTA:用原生 a + OButton 同款 recipe 样式(OButton 是 <button>,链接保留语义用 a)
    return (
      <a href={cta.href} className={cn('inline-flex items-center justify-center gap-2 px-5 py-2.5 rounded-[var(--control-radius)] font-medium text-sm transition-all',
        primary ? 'bg-[color:var(--primary)] text-[color:var(--primary-foreground)] hover:opacity-90' : 'border border-[color:var(--border)] text-[color:var(--foreground)] hover:bg-[color:var(--muted)]',
        glowCls)}>
        {cta.label}
      </a>
    );
  }
  return (
    <OButton variant={variant} size="lg" onClick={cta.onClick} className={glowCls}>
      {cta.label}
    </OButton>
  );
}

export const OHeroBanner = forwardRef<HTMLElement, OHeroBannerProps>(function OHeroBanner(
  {
    title,
    subtitle,
    eyebrow,
    primaryCta,
    secondaryCta,
    media,
    background = 'gradient',
    backgroundImage,
    layout = 'centered',
    size = 'lg',
    padded = true,
    className,
    theme: _t,
  },
  ref
) {
  const reduced = useReducedMotion();
  const baseT = reduced ? { duration: 0 } : { duration: 0.5, ease: [0.16, 1, 0.3, 1] as const };

  const contentBlock = (
    <div
      className={cn(
        'relative z-10 flex flex-col gap-6 max-w-2xl @container',
        layout === 'centered' && 'items-center text-center mx-auto'
      )}
    >
      {eyebrow ? (
        <motion.div
          initial={reduced ? false : { opacity: 0, y: 10 }}
          animate={reduced ? undefined : { opacity: 1, y: 0 }}
          transition={baseT}
          className="inline-flex items-center gap-2 px-3 py-1 rounded-full border border-border bg-card/60 backdrop-blur-sm text-xs text-muted-foreground"
        >
          {eyebrow}
        </motion.div>
      ) : null}
      <motion.h1
        initial={reduced ? false : { opacity: 0, y: 20 }}
        animate={reduced ? undefined : { opacity: 1, y: 0 }}
        transition={{ ...baseT, delay: reduced ? 0 : 0.1 }}
        className="text-4xl md:text-5xl lg:text-6xl font-bold tracking-tight text-foreground"
        style={{ fontFamily: 'var(--font-display, var(--font-sans))' }}
      >
        {title}
      </motion.h1>
      {subtitle ? (
        <motion.p
          initial={reduced ? false : { opacity: 0, y: 20 }}
          animate={reduced ? undefined : { opacity: 1, y: 0 }}
          transition={{ ...baseT, delay: reduced ? 0 : 0.2 }}
          className="text-lg md:text-xl text-muted-foreground leading-relaxed max-w-prose"
        >
          {subtitle}
        </motion.p>
      ) : null}
      {primaryCta || secondaryCta ? (
        <motion.div
          initial={reduced ? false : { opacity: 0, y: 20 }}
          animate={reduced ? undefined : { opacity: 1, y: 0 }}
          transition={{ ...baseT, delay: reduced ? 0 : 0.3 }}
          className={cn('flex flex-wrap gap-3', layout === 'centered' && 'justify-center')}
        >
          {primaryCta ? <CtaButton cta={primaryCta} primary /> : null}
          {secondaryCta ? <CtaButton cta={secondaryCta} primary={false} /> : null}
        </motion.div>
      ) : null}
    </div>
  );

  const mediaBlock = media ? (
    <motion.div
      initial={reduced ? false : { opacity: 0, scale: 0.95 }}
      animate={reduced ? undefined : { opacity: 1, scale: 1 }}
      transition={{ ...baseT, delay: reduced ? 0 : 0.4 }}
      className="relative z-10 flex-1 min-w-0"
    >
      {media}
    </motion.div>
  ) : null;

  return (
    <section
      ref={ref}
      className={cn('relative w-full overflow-hidden', SIZE_CLASS[size], padded && 'py-16 md:py-24', className)}
    >
      <HeroBackground background={background} backgroundImage={backgroundImage} />
      <div
        className={cn(
          'relative h-full w-full max-w-7xl mx-auto px-6 md:px-10 flex',
          layout === 'centered' && 'items-center justify-center',
          layout === 'split-left' && 'items-center gap-12 flex-col md:flex-row',
          layout === 'split-right' && 'items-center gap-12 flex-col md:flex-row-reverse'
        )}
      >
        {contentBlock}
        {layout !== 'centered' ? mediaBlock : null}
      </div>
    </section>
  );
});

OHeroBanner.displayName = 'OHeroBanner';
