/**
 * OGateBadge — backtest gate 验证徽章(量化策略通用)。
 *
 * 诚实原则:FAIL 如实显示,不美化成"接近成功"。
 *   - PASS:绿色 ✓(策略通过 walk-forward + DSR + PBO)
 *   - FAIL:红色 ✕(任一指标不达标)
 *   - pending:灰色 ○(未跑)
 *
 * compact 显示 PASS/FAIL + 关键指标(DSR/PBO)。
 * 跨项目:helivex / helios / selene 等量化系统通用。
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export type GateVerdict = 'pass' | 'fail' | 'pending';

export interface OGateBadgeProps extends Omit<OBlockBaseProps, 'variant'> {
  verdict: GateVerdict;
  /** Deflated Sharpe Ratio */
  dsr?: number;
  /** Probability of Backtest Overfitting */
  pbo?: number;
  /** FAIL 原因(简短) */
  reason?: string;
  compact?: boolean;
}

const META: Record<GateVerdict, { color: string; icon: string; label: string }> = {
  pass:    { color: 'var(--success, oklch(0.62 0.18 145))', icon: '✓', label: 'PASS' },
  fail:    { color: 'var(--destructive, oklch(0.60 0.22 25))', icon: '✕', label: 'FAIL' },
  pending: { color: 'var(--muted-foreground)', icon: '○', label: 'PENDING' },
};

export const OGateBadge = forwardRef<HTMLSpanElement, OGateBadgeProps>(
  function OGateBadge({ verdict, dsr, pbo, reason, compact, className, ...rest }, ref) {
    const m = META[verdict];
    return (
      <span
        ref={ref}
        className={cn('inline-flex items-center gap-1.5 rounded-md px-2 py-1 text-xs font-semibold tabular-nums', className)}
        style={{
          color: m.color,
          background: `color-mix(in oklch, ${m.color} 14%, transparent)`,
          border: `1px solid color-mix(in oklch, ${m.color} 30%, transparent)`,
        }}
        title={reason}
        {...rest}
      >
        <span aria-hidden>{m.icon}</span>
        <span>{m.label}</span>
        {!compact && dsr != null && (
          <span className="opacity-80">DSR {dsr.toFixed(2)}</span>
        )}
        {!compact && pbo != null && (
          <span className="opacity-80">PBO {(pbo * 100).toFixed(0)}%</span>
        )}
      </span>
    );
  }
);

OGateBadge.displayName = 'OGateBadge';
