/**
 * OSearchBar — inline 列表 / 表格搜索框(非全局 ⌘K)。
 *
 * 区别 OCommandPalette:
 *   - OSearchBar 是列表/表格顶部就地搜索(应用列表 / 容器列表)
 *   - OCommandPalette 是全局 ⌘K 命令面板
 *
 * 设计:
 *   - 受控 value + onChange
 *   - 内置 debounce(默认 300ms)
 *   - clear 按钮(value 非空时显示)
 *   - aria-label / placeholder
 *
 * Page 拿到 debounced value 后调 API / 过滤本地数据。
 */
import { forwardRef, useCallback, useEffect, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import { useUiLang } from '../../lang/LangProvider';
import type { OBlockBaseProps } from '../../lib/types';

export interface OSearchBarProps extends Omit<OBlockBaseProps, 'variant'> {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  /** debounce 毫秒数。0 = 不 debounce(立即 onChange)。 */
  debounceMs?: number;
  /** 是否显示 clear 按钮。 */
  clearable?: boolean;
  /** aria-label,默认 placeholder。 */
  ariaLabel?: string;
  disabled?: boolean;
  width?: string | number;
}

export const OSearchBar = forwardRef<HTMLInputElement, OSearchBarProps>(function OSearchBar(
  {
    value,
    onChange,
    placeholder,
    debounceMs = 300,
    clearable = true,
    ariaLabel,
    disabled,
    width,
    className,
    theme: _t,
    size: _s,
  },
  ref
) {
  const { tr } = useUiLang();
  const ph = placeholder ?? tr('搜索...', 'Search...');
  const [local, setLocal] = useState(value);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // 外部 value 变化时同步 local
  useEffect(() => {
    setLocal(value);
  }, [value]);

  // 卸载时清 timer
  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    []
  );

  const handleChange = useCallback(
    (next: string) => {
      setLocal(next);
      if (debounceMs <= 0) {
        onChange(next);
        return;
      }
      if (timer.current) clearTimeout(timer.current);
      timer.current = setTimeout(() => onChange(next), debounceMs);
    },
    [onChange, debounceMs]
  );

  const handleClear = () => {
    setLocal('');
    if (timer.current) clearTimeout(timer.current);
    onChange('');
  };

  return (
    <div
      className={cn(
        'inline-flex items-center gap-1 px-2 py-1 rounded border border-border bg-card @container',
        'focus-within:ring-1 focus-within:ring-ring',
        disabled && 'opacity-50',
        className
      )}
      style={{ width }}
    >
      <span aria-hidden="true" className="text-muted-foreground text-xs">
        🔍
      </span>
      <input
        ref={ref}
        type="text"
        value={local}
        onChange={(e) => handleChange(e.target.value)}
        placeholder={ph}
        aria-label={ariaLabel ?? ph}
        disabled={disabled}
        className="flex-1 bg-transparent text-sm focus:outline-none focus-visible:ring-2 focus-visible:ring-ring placeholder:text-muted-foreground"
      />
      {clearable && local && (
        <button
          type="button"
          onClick={handleClear}
          aria-label={tr('清除搜索', 'Clear search')}
          disabled={disabled}
          className="text-muted-foreground hover:text-foreground text-xs"
        >
          ✕
        </button>
      )}
    </div>
  );
});

OSearchBar.displayName = 'OSearchBar';
