/**
 * ODrawerFrame - 抽屉容器。
 *
 * 基于 @radix-ui/react-dialog (复用 OModalFrame 的底层机制),
 * 但改为从屏幕边缘滑入,适合长内容(详情页、设置、过滤器)。
 *
 * 4 个方向: right (默认) / left / top / bottom
 */
'use client';

import * as Dialog from '@radix-ui/react-dialog';
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { FrameSlot, OBlockBaseProps } from '../../lib/types';

const SIZE_CLASS = {
  sm: { right: 'w-80', left: 'w-80', top: 'h-1/3', bottom: 'h-1/3' },
  md: { right: 'w-[28rem]', left: 'w-[28rem]', top: 'h-1/2', bottom: 'h-1/2' },
  lg: { right: 'w-[42rem]', left: 'w-[42rem]', top: 'h-2/3', bottom: 'h-2/3' },
  xl: { right: 'w-[60vw]', left: 'w-[60vw]', top: 'h-[80vh]', bottom: 'h-[80vh]' },
} as const;

const POSITION_CLASS = {
  right: 'inset-y-0 right-0 border-l',
  left: 'inset-y-0 left-0 border-r',
  top: 'inset-x-0 top-0 border-b',
  bottom: 'inset-x-0 bottom-0 border-t',
} as const;

const SLIDE_IN = {
  right: 'data-[state=open]:slide-in-from-right data-[state=closed]:slide-out-to-right',
  left: 'data-[state=open]:slide-in-from-left data-[state=closed]:slide-out-to-left',
  top: 'data-[state=open]:slide-in-from-top data-[state=closed]:slide-out-to-top',
  bottom: 'data-[state=open]:slide-in-from-bottom data-[state=closed]:slide-out-to-bottom',
} as const;

export interface ODrawerFrameProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  open: boolean;
  onClose: () => void;
  side?: 'right' | 'left' | 'top' | 'bottom';
  size?: keyof typeof SIZE_CLASS;
  header?: FrameSlot;
  body?: FrameSlot;
  footer?: FrameSlot;
  showCloseButton?: boolean;
  closeOnOverlayClick?: boolean;
  ariaLabel?: string;
}

export const ODrawerFrame = forwardRef<HTMLDivElement, ODrawerFrameProps>(function ODrawerFrame(
  {
    open,
    onClose,
    side = 'right',
    size = 'md',
    header,
    body,
    footer,
    showCloseButton = true,
    closeOnOverlayClick = true,
    ariaLabel = 'Drawer',
    className,
    theme: _t,
  },
  ref
) {
  const dim = SIZE_CLASS[size][side];

  return (
    <Dialog.Root open={open} onOpenChange={(o) => !o && onClose()}>
      <Dialog.Portal>
        <Dialog.Overlay
          className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0"
          onClick={(e) => {
            if (!closeOnOverlayClick) e.preventDefault();
          }}
        />
        <Dialog.Content
          ref={ref}
          aria-label={ariaLabel}
          className={cn(
            'fixed z-50 bg-card border-border shadow-lg flex flex-col',
            'data-[state=open]:animate-in data-[state=closed]:animate-out duration-300',
            POSITION_CLASS[side],
            dim,
            SLIDE_IN[side],
            className
          )}
        >
          {header ? (
            <header className="flex items-center justify-between px-6 py-4 border-b border-border shrink-0">
              <div className="flex-1 min-w-0">{header}</div>
              {showCloseButton ? (
                <Dialog.Close
                  className="ml-4 p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                  aria-label="Close drawer"
                >
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <line x1="18" y1="6" x2="6" y2="18" />
                    <line x1="6" y1="6" x2="18" y2="18" />
                  </svg>
                </Dialog.Close>
              ) : null}
            </header>
          ) : null}
          {body ? <div className="flex-1 overflow-auto px-6 py-4">{body}</div> : null}
          {footer ? (
            <footer className="px-6 py-4 border-t border-border shrink-0 flex items-center justify-end gap-2">
              {footer}
            </footer>
          ) : null}
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
});

ODrawerFrame.displayName = 'ODrawerFrame';
