/**
 * OParticleBackground - Canvas 粒子背景 (类 2)。
 *
 * 装饰性 Block,通常装在 Frame 后面作为视觉背景。
 * 在 reduced-motion 下显示静态分布的粒子 (不动)。
 *
 * 参数化但不持业务数据,可视为"参数化装饰 Block"。
 */
'use client';

import { forwardRef, useEffect, useRef } from 'react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

export interface OParticleBackgroundProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 粒子密度 (粒子数 / 10000px²)。默认 0.5。 */
  density?: number;
  /** 颜色 (CSS 颜色值)。默认主题 primary。 */
  color?: string;
  /** 速度倍率 (0-2)。 */
  speed?: number;
  /** 粒子最大半径 (px)。 */
  maxRadius?: number;
  /** 是否连接附近粒子 (画线)。 */
  connect?: boolean;
  /** 连接最大距离 (px)。 */
  connectDistance?: number;
  /** 鼠标交互 (粒子被吸引)。 */
  interactive?: boolean;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  r: number;
}

export const OParticleBackground = forwardRef<HTMLCanvasElement, OParticleBackgroundProps>(
  function OParticleBackground(
    {
      density = 0.5,
      color,
      speed = 0.5,
      maxRadius = 1.6,
      connect = true,
      connectDistance = 120,
      interactive = false,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const reduced = useReducedMotion();
    const rafRef = useRef<number | null>(null);
    const mouseRef = useRef<{ x: number; y: number } | null>(null);

    useEffect(() => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      let particles: Particle[] = [];
      let w = 0;
      let h = 0;
      let dpr = window.devicePixelRatio || 1;

      function resize() {
        if (!canvas) return;
        const parent = canvas.parentElement!;
        w = parent.clientWidth;
        h = parent.clientHeight;
        dpr = window.devicePixelRatio || 1;
        canvas.width = w * dpr;
        canvas.height = h * dpr;
        canvas.style.width = `${w}px`;
        canvas.style.height = `${h}px`;
        ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
        const count = Math.max(8, Math.round((w * h) / 10000 * density));
        particles = Array.from({ length: count }, () => ({
          x: Math.random() * w,
          y: Math.random() * h,
          vx: (Math.random() - 0.5) * speed,
          vy: (Math.random() - 0.5) * speed,
          r: Math.random() * maxRadius + 0.5,
        }));
      }

      function readColor(): string {
        if (color) return color;
        const root = getComputedStyle(canvas!.ownerDocument.documentElement);
        return root.getPropertyValue('--primary').trim() || 'oklch(0.7 0.2 200)';
      }

      function step() {
        if (!ctx) return;
        ctx.clearRect(0, 0, w, h);
        const c = readColor();

        for (const p of particles) {
          if (!reduced) {
            p.x += p.vx;
            p.y += p.vy;
            if (p.x < 0 || p.x > w) p.vx *= -1;
            if (p.y < 0 || p.y > h) p.vy *= -1;

            if (interactive && mouseRef.current) {
              const dx = mouseRef.current.x - p.x;
              const dy = mouseRef.current.y - p.y;
              const dist = Math.hypot(dx, dy);
              if (dist < 150 && dist > 0) {
                p.vx += (dx / dist) * 0.02;
                p.vy += (dy / dist) * 0.02;
              }
            }
          }
          ctx.fillStyle = c;
          ctx.globalAlpha = 0.8;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
          ctx.fill();
        }

        if (connect) {
          ctx.strokeStyle = c;
          ctx.lineWidth = 0.4;
          for (let i = 0; i < particles.length; i++) {
            for (let j = i + 1; j < particles.length; j++) {
              const a = particles[i];
              const b = particles[j];
              if (!a || !b) continue;
              const dx = a.x - b.x;
              const dy = a.y - b.y;
              const d = Math.hypot(dx, dy);
              if (d < connectDistance) {
                ctx.globalAlpha = (1 - d / connectDistance) * 0.4;
                ctx.beginPath();
                ctx.moveTo(a.x, a.y);
                ctx.lineTo(b.x, b.y);
                ctx.stroke();
              }
            }
          }
        }

        ctx.globalAlpha = 1;
        if (!reduced) {
          rafRef.current = requestAnimationFrame(step);
        }
      }

      function onMouse(e: MouseEvent) {
        if (!canvas) return;
        const rect = canvas.getBoundingClientRect();
        mouseRef.current = { x: e.clientX - rect.left, y: e.clientY - rect.top };
      }
      function onLeave() {
        mouseRef.current = null;
      }

      resize();
      const ro = new ResizeObserver(resize);
      if (canvas.parentElement) ro.observe(canvas.parentElement);

      if (interactive) {
        canvas.addEventListener('mousemove', onMouse);
        canvas.addEventListener('mouseleave', onLeave);
      }

      rafRef.current = requestAnimationFrame(step);

      return () => {
        if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
        ro.disconnect();
        canvas.removeEventListener('mousemove', onMouse);
        canvas.removeEventListener('mouseleave', onLeave);
      };
    }, [density, color, speed, maxRadius, connect, connectDistance, interactive, reduced]);

    return (
      <canvas
        ref={(el) => {
          canvasRef.current = el;
          if (typeof ref === 'function') ref(el);
          else if (ref) ref.current = el;
        }}
        aria-hidden="true"
        className={cn('absolute inset-0 w-full h-full pointer-events-none @container', interactive && 'pointer-events-auto', className)}
      />
    );
  }
);

OParticleBackground.displayName = 'OParticleBackground';
