/**
 * ODataTable - 数据表格 (Terminal-grade v1.0)。
 *
 * 基于 @tanstack/react-table v8 + @tanstack/react-virtual v3。
 *
 * Terminal-grade 升级 (Batch 15):
 *   ✓ virtual          虚拟化 (>200 行强烈建议) - TanStack Virtual,1M cells 60fps
 *   ✓ flashOnUpdate    行变化时整行高亮 (适合实时报价表)
 *   ✓ channel          FastDataProvider 直接订阅
 *   ✓ dataDelay        合规延时标签
 *   ✓ density-aware    table-row-height 跟随双轴密度
 *
 * @example 普通用法
 *   <ODataTable data={{ columns, rows }} />
 *
 * @example 大数据虚拟化
 *   <ODataTable data={{ columns, rows: bigList }} virtual maxHeight={500} />
 *
 * @example 实时报价表 (推荐)
 *   <ODataTable
 *     channel="quotes:all"
 *     virtual
 *     flashOnUpdate
 *     trackKey="symbol"
 *     trackField="price"
 *   />
 */
'use client';

import {
  flexRender,
  getCoreRowModel,
  getSortedRowModel,
  useReactTable,
  type ColumnDef,
  type SortingState,
} from '@tanstack/react-table';
import { useVirtualizer } from '@tanstack/react-virtual';
import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, useEffect, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import { useFastData } from '../../providers/FastDataProvider';

export interface ODataTableData<T> {
  columns: ColumnDef<T>[];
  rows: T[];
  pagination?: {
    page: number;
    pageSize: number;
    total: number;
    onPageChange?: (page: number) => void;
  };
}

const tableVariants = cva('w-full text-sm', {
  variants: {
    variant: {
      standard: '',
      compact: '[&_td]:py-1 [&_th]:py-1',
      card: '[&_tr]:bg-card [&_tr]:border [&_tr]:border-border [&_tr]:rounded-md [&_td]:p-3',
    },
    striped: {
      true: '[&_tbody_tr:nth-child(even)]:bg-muted/30',
      false: '',
    },
  },
  defaultVariants: { variant: 'standard', striped: false },
});

type TableVariantProps = VariantProps<typeof tableVariants>;

export interface ODataTableProps<T>
  extends Omit<OBlockDataProps<ODataTableData<T>>, 'variant'>,
    TableVariantProps,
    Pick<
      TerminalBlockProps,
      'virtual' | 'flashOnUpdate' | 'channel' | 'dataDelay' | 'regulation' | 'lowPerformanceMode'
    > {
  sortable?: boolean;
  onRowClick?: (row: T) => void;
  /** 虚拟化最大高度 (虚拟模式下需要)。默认 480px。 */
  maxHeight?: number;
  /** flashOnUpdate 模式下,用哪个字段做唯一 key (默认 'id' 或 'symbol')。 */
  trackKey?: string;
  /** flashOnUpdate 模式下,监听哪个字段的变化触发闪烁 (例如 'price')。 */
  trackField?: string;
}

function ODataTableInner<T>(
  {
    data: dataProp,
    loading,
    error,
    empty,
    variant = 'standard',
    striped = false,
    sortable = true,
    onRowClick,
    virtual = false,
    flashOnUpdate,
    channel,
    dataDelay = 0,
    regulation: _r,
    lowPerformanceMode,
    maxHeight = 480,
    trackKey = 'id',
    trackField = 'price',
    className,
    theme: _t,
    size: _s,
  }: ODataTableProps<T>,
  ref: React.Ref<HTMLDivElement>
) {
  // Worker channel 订阅
  const fastData = useFastData();
  const [channelData, setChannelData] = useState<ODataTableData<T> | null>(null);

  useEffect(() => {
    if (!channel || !fastData) return;
    return fastData.subscribe<ODataTableData<T>>(channel, setChannelData);
  }, [channel, fastData]);

  const data = channel ? channelData : (dataProp ?? null);

  // 跟踪上一次每行的 trackField 值,用于 flashOnUpdate 判定
  const prevValuesRef = useRef<Map<unknown, number>>(new Map());
  const flashedRowsRef = useRef<Map<unknown, { dir: 'up' | 'down'; ts: number }>>(new Map());
  const [, forceRender] = useState(0);

  const flashEnabled = !!flashOnUpdate && !lowPerformanceMode;

  useEffect(() => {
    if (!flashEnabled || !data) return;
    const next = new Map<unknown, number>();
    const newFlashes = new Map(flashedRowsRef.current);
    const now = Date.now();
    for (const row of data.rows) {
      const key = (row as Record<string, unknown>)[trackKey];
      const value = (row as Record<string, unknown>)[trackField] as number;
      if (typeof value !== 'number') continue;
      next.set(key, value);
      const prev = prevValuesRef.current.get(key);
      if (prev != null && prev !== value) {
        newFlashes.set(key, { dir: value > prev ? 'up' : 'down', ts: now });
      }
    }
    prevValuesRef.current = next;
    // 清理 80ms 前的 flash
    for (const [k, f] of newFlashes) {
      if (now - f.ts > 200) newFlashes.delete(k);
    }
    flashedRowsRef.current = newFlashes;
    forceRender((c) => c + 1);
    // 200ms 后清除
    const timer = setTimeout(() => {
      const nowInner = Date.now();
      for (const [k, f] of flashedRowsRef.current) {
        if (nowInner - f.ts > 200) flashedRowsRef.current.delete(k);
      }
      forceRender((c) => c + 1);
    }, 220);
    return () => clearTimeout(timer);
  }, [data, flashEnabled, trackKey, trackField]);

  const [sorting, setSorting] = useState<SortingState>([]);
  const state = resolveBlockState({ data, loading, error, empty });

  const table = useReactTable<T>({
    data: data?.rows ?? [],
    columns: data?.columns ?? [],
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: sortable ? getSortedRowModel() : undefined,
    enableSorting: sortable,
  });

  const rows = table.getRowModel().rows;

  // 虚拟化
  const scrollContainerRef = useRef<HTMLDivElement | null>(null);
  const virtualizer = useVirtualizer({
    count: virtual ? rows.length : 0,
    getScrollElement: () => scrollContainerRef.current,
    estimateSize: () => {
      // 跟随密度
      if (typeof document === 'undefined') return 32;
      const styles = getComputedStyle(document.documentElement);
      const h = parseInt(styles.getPropertyValue('--table-row-height') || '32', 10);
      return h || 32;
    },
    overscan: 6,
  });

  // 状态分流
  if (state === 'loading')
    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card p-4 @container',
          className
        )}
      >
        <OLoadingState rows={5} />
      </div>
    );
  if (state === 'error')
    return (
      <OErrorState ref={ref} error={error!} className={className} variant="inline" />
    );
  if (state === 'empty' || !data || data.rows.length === 0)
    return (
      <OEmptyState
        ref={ref}
        title="No records"
        description="There is no data to display in this table."
        className={className}
      />
    );

  const containerStyle: React.CSSProperties = virtual
    ? { maxHeight, overflow: 'auto' }
    : {};

  const tableBody = virtual ? (
    <tbody style={{ position: 'relative', display: 'block', height: virtualizer.getTotalSize() }}>
      {virtualizer.getVirtualItems().map((vRow) => {
        const row = rows[vRow.index];
        if (!row) return null;
        const key = (row.original as Record<string, unknown>)[trackKey];
        const flash = flashEnabled ? flashedRowsRef.current.get(key) : null;
        return (
          <tr
            key={row.id}
            ref={virtualizer.measureElement as never}
            data-index={vRow.index}
            className={cn(
              'border-b border-border/50 transition-colors absolute left-0 w-full',
              onRowClick && 'cursor-pointer hover:bg-muted/40'
            )}
            style={{
              transform: `translateY(${vRow.start}px)`,
              background: flash
                ? flash.dir === 'up'
                  ? 'var(--quote-up-bg)'
                  : 'var(--quote-down-bg)'
                : undefined,
              display: 'table',
              tableLayout: 'fixed',
            }}
            onClick={onRowClick ? () => onRowClick(row.original) : undefined}
          >
            {row.getVisibleCells().map((cell) => (
              <td key={cell.id} className="px-3 py-2 tabular-nums">
                {flexRender(cell.column.columnDef.cell, cell.getContext())}
              </td>
            ))}
          </tr>
        );
      })}
    </tbody>
  ) : (
    <tbody>
      {rows.map((row) => {
        const key = (row.original as Record<string, unknown>)[trackKey];
        const flash = flashEnabled ? flashedRowsRef.current.get(key) : null;
        return (
          <tr
            key={row.id}
            className={cn(
              'border-b border-border/50 transition-colors',
              onRowClick && 'cursor-pointer hover:bg-muted/40'
            )}
            style={{
              background: flash
                ? flash.dir === 'up'
                  ? 'var(--quote-up-bg)'
                  : 'var(--quote-down-bg)'
                : undefined,
            }}
            onClick={onRowClick ? () => onRowClick(row.original) : undefined}
          >
            {row.getVisibleCells().map((cell) => (
              <td key={cell.id} className="px-3 py-2 tabular-nums">
                {flexRender(cell.column.columnDef.cell, cell.getContext())}
              </td>
            ))}
          </tr>
        );
      })}
    </tbody>
  );

  return (
    <div ref={ref} className={cn('w-full relative', className)}>
      {dataDelay > 0 ? (
        <div className="absolute top-1 right-2 z-10 text-[10px] text-[color:var(--alert-warn)] font-mono pointer-events-none">
          延时 {dataDelay}m
        </div>
      ) : null}
      <div ref={scrollContainerRef} style={containerStyle} className={virtual ? 'overflow-auto' : ''}>
        <table className={cn(tableVariants({ variant, striped }))}>
          <thead
            className="text-left text-[0.6875rem] text-[color:var(--text-muted)] uppercase tracking-[0.04em] font-semibold sticky top-0 z-[1] bg-card"
          >
            {table.getHeaderGroups().map((hg) => (
              <tr key={hg.id} className="border-b border-border">
                {hg.headers.map((h) => {
                  const canSort = h.column.getCanSort();
                  const sortDir = h.column.getIsSorted();
                  return (
                    <th
                      key={h.id}
                      className={cn(
                        'px-3 py-2 font-medium',
                        canSort &&
                          'cursor-pointer select-none hover:text-[color:var(--foreground)] transition-colors'
                      )}
                      onClick={canSort ? h.column.getToggleSortingHandler() : undefined}
                      aria-sort={
                        sortDir === 'asc'
                          ? 'ascending'
                          : sortDir === 'desc'
                            ? 'descending'
                            : 'none'
                      }
                    >
                      <span className="inline-flex items-center gap-1">
                        {h.isPlaceholder
                          ? null
                          : flexRender(h.column.columnDef.header, h.getContext())}
                        {canSort ? (
                          <span className="text-xs opacity-60">
                            {sortDir === 'asc' ? '▲' : sortDir === 'desc' ? '▼' : '↕'}
                          </span>
                        ) : null}
                      </span>
                    </th>
                  );
                })}
              </tr>
            ))}
          </thead>
          {tableBody}
        </table>
      </div>

      {data.pagination ? (
        <div className="flex items-center justify-between mt-3 px-3 text-xs text-[color:var(--text-muted)]">
          <span>
            Showing {(data.pagination.page - 1) * data.pagination.pageSize + 1}–
            {Math.min(
              data.pagination.page * data.pagination.pageSize,
              data.pagination.total
            )}{' '}
            of {data.pagination.total}
          </span>
          {data.pagination.onPageChange ? (
            <div className="flex gap-1">
              <button
                type="button"
                disabled={data.pagination.page <= 1}
                onClick={() => data.pagination!.onPageChange!(data.pagination!.page - 1)}
                className="px-2 py-1 rounded hover:bg-muted disabled:opacity-40 disabled:cursor-not-allowed"
              >
                Prev
              </button>
              <button
                type="button"
                disabled={
                  data.pagination.page * data.pagination.pageSize >= data.pagination.total
                }
                onClick={() => data.pagination!.onPageChange!(data.pagination!.page + 1)}
                className="px-2 py-1 rounded hover:bg-muted disabled:opacity-40 disabled:cursor-not-allowed"
              >
                Next
              </button>
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

export const ODataTable = forwardRef(ODataTableInner) as <T>(
  props: ODataTableProps<T> & { ref?: React.Ref<HTMLDivElement> }
) => ReturnType<typeof ODataTableInner>;
