/**
 * OConsistencyScoreBadge (Tide Wave 3 E23, Atom)
 *
 * 一致性 score donut(0-1)+ label。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §3.4
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OConsistencyScoreBadgeProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 0-1 */
  score: number;
  label?: string;
  showLabel?: boolean;
  diameter?: number;
}

function scoreColor(s: number): string {
  if (s >= 0.7) return 'var(--success)';
  if (s >= 0.4) return 'var(--warning)';
  return 'var(--destructive)';
}

function scoreText(s: number): string {
  if (s >= 0.8) return '优秀';
  if (s >= 0.6) return '良好';
  if (s >= 0.4) return '一般';
  if (s >= 0.2) return '较差';
  return '差';
}

export const OConsistencyScoreBadge = forwardRef<HTMLDivElement, OConsistencyScoreBadgeProps>(
  function OConsistencyScoreBadge(
    {
      score,
      label,
      showLabel = true,
      diameter = 64,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const clamped = Math.max(0, Math.min(1, score));
    const radius = diameter / 2 - 4;
    const circumference = 2 * Math.PI * radius;
    const dashOffset = circumference * (1 - clamped);
    const color = scoreColor(clamped);

    return (
      <div
        ref={ref}
        className={cn('inline-flex items-center gap-2 @container', className)}
        style={{ fontFamily: 'var(--font-mono)' }}
        role="img"
        aria-label={`一致性 score ${(clamped * 100).toFixed(0)}% ${scoreText(clamped)}`}
      >
        <svg width={diameter} height={diameter} className="shrink-0">
          {/* track */}
          <circle
            cx={diameter / 2}
            cy={diameter / 2}
            r={radius}
            stroke="var(--muted)"
            strokeWidth={6}
            fill="none"
          />
          {/* progress */}
          <circle
            cx={diameter / 2}
            cy={diameter / 2}
            r={radius}
            stroke={color}
            strokeWidth={6}
            fill="none"
            strokeDasharray={circumference}
            strokeDashoffset={dashOffset}
            strokeLinecap="round"
            transform={`rotate(-90 ${diameter / 2} ${diameter / 2})`}
          />
          {/* center text */}
          <text
            x={diameter / 2}
            y={diameter / 2}
            textAnchor="middle"
            dominantBaseline="central"
            style={{
              fontSize: diameter * 0.3,
              fontWeight: 700,
              fill: 'var(--foreground)',
              fontFamily: 'var(--font-mono)',
            }}
          >
            {clamped.toFixed(2)}
          </text>
        </svg>
        {showLabel && (
          <div className="flex flex-col text-xs">
            <span style={{ color: 'var(--text-tertiary)', fontSize: 10 }}>
              {label ?? '一致性'}
            </span>
            <span style={{ color }} className="font-bold">
              {scoreText(clamped)}
            </span>
          </div>
        )}
      </div>
    );
  }
);

OConsistencyScoreBadge.displayName = 'OConsistencyScoreBadge';
