/**
 * OGlassFrame - 毛玻璃面板 Frame。
 *
 * 使用 backdrop-filter + 半透明背景。SPEC §3 类 2 视觉增强。
 * Theme 内 --glass-bg / --glass-border / --glass-blur 提供主题响应。
 *
 * 注意: backdrop-blur 在某些浏览器/低端设备性能差,使用时注意页面 budget。
 *
 * @example
 * <OGlassFrame intensity="medium">
 *   <div>Content over hero image</div>
 * </OGlassFrame>
 */
'use client';

import { forwardRef, type CSSProperties, type HTMLAttributes, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

const BLUR_MAP = {
  none: '0px',
  light: '6px',
  medium: '12px',
  heavy: '24px',
} as const;

const OPACITY_MAP = {
  light: '0.85',
  medium: '0.6',
  heavy: '0.4',
} as const;

export interface OGlassFrameProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>,
    Omit<OBlockBaseProps, 'variant' | 'size'> {
  /** 模糊强度。 */
  intensity?: keyof typeof BLUR_MAP;
  /** 透明度档位 (背景不透明度)。 */
  opacity?: keyof typeof OPACITY_MAP;
  /** 圆角 CSS 值。 */
  radius?: string;
  /** 内边距 CSS 值。 */
  padding?: string;
  /** 是否带边框。 */
  bordered?: boolean;
  children: ReactNode;
}

export const OGlassFrame = forwardRef<HTMLDivElement, OGlassFrameProps>(function OGlassFrame(
  {
    intensity = 'medium',
    opacity = 'medium',
    radius = 'var(--radius-md)',
    padding,
    bordered = true,
    className,
    children,
    style,
    theme: _t,
    ...rest
  },
  ref
) {
  const blur = BLUR_MAP[intensity];
  const alpha = OPACITY_MAP[opacity];

  const finalStyle: CSSProperties = {
    backdropFilter: `blur(${blur}) saturate(180%)`,
    WebkitBackdropFilter: `blur(${blur}) saturate(180%)`,
    backgroundColor: `color-mix(in oklch, var(--card) ${parseFloat(alpha) * 100}%, transparent)`,
    borderRadius: radius,
    padding,
    ...style,
  };

  return (
    <div
      ref={ref}
      className={cn(
        'relative',
        bordered && 'border border-white/10',
        className
      )}
      style={finalStyle}
      {...rest}
    >
      {children}
    </div>
  );
});

OGlassFrame.displayName = 'OGlassFrame';
