/**
 * OHeatmap - 热力图。
 *
 * 两种模式:
 *   - matrix:  规则二维矩阵 (e.g. 时段 × 品种 价格变化)
 *   - cells:   不规则单元 (e.g. 市场地图,大小 + 颜色双维度,类似 Finviz)
 *
 * Canvas 自绘以支持大数据量 (1000+ 格子)。
 *
 * 数据契约: 见下方类型。
 */
'use client';

import { forwardRef, useEffect, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import type { OBlockDataProps } from '../../lib/types';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';

export interface OHeatmapMatrix {
  mode: 'matrix';
  /** 行标签。 */
  rows: string[];
  /** 列标签。 */
  cols: string[];
  /** values[row][col] = 数值,-Infinity/null 视为缺失。 */
  values: (number | null)[][];
  /** value 范围,用于颜色归一化。不填则自动算 min/max。 */
  domain?: [number, number];
}

export interface OHeatmapCells {
  mode: 'cells';
  cells: Array<{
    label: string;
    /** 决定颜色 (-100 到 +100,正绿负红)。 */
    change: number;
    /** 决定尺寸权重。 */
    size: number;
    group?: string;
  }>;
}

export type OHeatmapData = OHeatmapMatrix | OHeatmapCells;

export interface OHeatmapProps extends OBlockDataProps<OHeatmapData> {
  height?: number;
  /** 配色:绿红 (金融) 或 单色渐变。 */
  palette?: 'rg' | 'br' | 'mono';
  /** 显示数值标签。 */
  showLabels?: boolean;
  onCellHover?: (info: { label: string; value: number } | null) => void;
}

function valueToColor(v: number, palette: 'rg' | 'br' | 'mono', vmin: number, vmax: number): string {
  const range = vmax - vmin || 1;
  const t = (v - vmin) / range; // 0..1
  if (palette === 'rg') {
    // -值红 +值绿,中性灰
    if (v >= 0) {
      const k = Math.min(v / Math.max(Math.abs(vmax), 0.0001), 1);
      return `oklch(${0.4 + k * 0.25} ${0.15 + k * 0.1} 145)`;
    } else {
      const k = Math.min(Math.abs(v) / Math.max(Math.abs(vmin), 0.0001), 1);
      return `oklch(${0.4 + k * 0.2} ${0.15 + k * 0.1} 25)`;
    }
  }
  if (palette === 'br') {
    // 蓝→红
    const hue = 240 - t * 240;
    return `oklch(0.6 0.2 ${hue})`;
  }
  // mono: 深→亮
  return `oklch(${0.2 + t * 0.5} 0.1 220)`;
}

/** 简化的 squarified treemap layout (适合 cells 模式)。 */
function layoutTreemap(
  items: { label: string; change: number; size: number }[],
  w: number,
  h: number
): Array<{ x: number; y: number; w: number; h: number; label: string; change: number }> {
  const total = items.reduce((s, i) => s + i.size, 0) || 1;
  const sorted = [...items].sort((a, b) => b.size - a.size);
  const out: ReturnType<typeof layoutTreemap> = [];
  // 简化策略:贪心切片 (非最优 squarified,但足够现代金融 heatmap 视觉)
  let x = 0,
    y = 0,
    rowW = w,
    rowH = h;
  let rowItems: typeof sorted = [];
  function flushRow(isHorizontal: boolean) {
    const totalRow = rowItems.reduce((s, i) => s + i.size, 0);
    if (isHorizontal) {
      const rh = (totalRow / total) * h;
      let cx = x;
      for (const it of rowItems) {
        const cw = (it.size / totalRow) * w;
        out.push({ x: cx, y: y, w: cw, h: rh, label: it.label, change: it.change });
        cx += cw;
      }
      y += rh;
      rowH -= rh;
    } else {
      const rw = (totalRow / total) * w;
      let cy = y;
      for (const it of rowItems) {
        const ch = (it.size / totalRow) * h;
        out.push({ x: x, y: cy, w: rw, h: ch, label: it.label, change: it.change });
        cy += ch;
      }
      x += rw;
      rowW -= rw;
    }
    rowItems = [];
  }
  for (const it of sorted) {
    rowItems.push(it);
    // 每 4-6 个 flush 一行 (简化策略)
    if (rowItems.length >= Math.max(2, Math.round(Math.sqrt(sorted.length)))) {
      flushRow(rowW > rowH);
    }
  }
  if (rowItems.length > 0) flushRow(rowW > rowH);
  return out;
}

interface HoverInfo {
  label: string;
  value: number;
  x: number;
  y: number;
}

export const OHeatmap = forwardRef<HTMLDivElement, OHeatmapProps>(function OHeatmap(
  {
    data,
    loading,
    error,
    empty,
    height = 400,
    palette = 'rg',
    showLabels = true,
    onCellHover,
    className,
    theme: _t,
    size: _s,
  },
  ref
) {
  const state = resolveBlockState({ data, loading, error, empty });
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [hover, setHover] = useState<HoverInfo | null>(null);

  useEffect(() => {
    if (state !== 'ready' || !data) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let cellRects: Array<{ x: number; y: number; w: number; h: number; label: string; value: number }> = [];

    function resize() {
      if (!canvas) return;
      const parent = canvas.parentElement!;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const w = parent.clientWidth;
      const h = parent.clientHeight;
      canvas.width = w * dpr;
      canvas.height = h * dpr;
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx!.clearRect(0, 0, w, h);

      cellRects = [];

      if (data!.mode === 'matrix') {
        const m = data!;
        const cols = m.cols.length;
        const rows = m.rows.length;
        const headerW = 60;
        const headerH = 20;
        const cellW = (w - headerW) / cols;
        const cellH = (h - headerH) / rows;
        let vmin = Infinity,
          vmax = -Infinity;
        if (m.domain) {
          [vmin, vmax] = m.domain;
        } else {
          for (const row of m.values) for (const v of row) if (v != null) {
            if (v < vmin) vmin = v;
            if (v > vmax) vmax = v;
          }
        }
        // headers
        ctx!.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--muted-foreground').trim() || '#888';
        ctx!.font = '10px ui-sans-serif, system-ui';
        ctx!.textAlign = 'center';
        ctx!.textBaseline = 'middle';
        m.cols.forEach((c, i) => {
          ctx!.fillText(c, headerW + cellW * (i + 0.5), headerH / 2);
        });
        ctx!.textAlign = 'right';
        m.rows.forEach((r, j) => {
          ctx!.fillText(r, headerW - 4, headerH + cellH * (j + 0.5));
        });
        // cells
        for (let j = 0; j < rows; j++) {
          for (let i = 0; i < cols; i++) {
            const v = m.values[j]?.[i];
            if (v == null) continue;
            ctx!.fillStyle = valueToColor(v, palette, vmin, vmax);
            ctx!.fillRect(headerW + i * cellW, headerH + j * cellH, cellW - 1, cellH - 1);
            cellRects.push({
              x: headerW + i * cellW,
              y: headerH + j * cellH,
              w: cellW - 1,
              h: cellH - 1,
              label: `${m.rows[j]} · ${m.cols[i]}`,
              value: v,
            });
            if (showLabels && cellW > 36 && cellH > 20) {
              ctx!.fillStyle = '#fff';
              ctx!.font = '10px ui-monospace, monospace';
              ctx!.textAlign = 'center';
              ctx!.fillText(v.toFixed(1), headerW + cellW * (i + 0.5), headerH + cellH * (j + 0.5));
            }
          }
        }
      } else {
        // cells mode
        const rects = layoutTreemap(data!.cells, w, h);
        let vmin = Infinity,
          vmax = -Infinity;
        for (const c of data!.cells) {
          if (c.change < vmin) vmin = c.change;
          if (c.change > vmax) vmax = c.change;
        }
        for (const r of rects) {
          ctx!.fillStyle = valueToColor(r.change, palette, vmin, vmax);
          ctx!.fillRect(r.x, r.y, r.w - 1, r.h - 1);
          cellRects.push({
            x: r.x,
            y: r.y,
            w: r.w - 1,
            h: r.h - 1,
            label: r.label,
            value: r.change,
          });
          if (showLabels && r.w > 40 && r.h > 24) {
            ctx!.fillStyle = '#fff';
            ctx!.font = 'bold 11px ui-sans-serif, system-ui';
            ctx!.textAlign = 'center';
            ctx!.textBaseline = 'middle';
            ctx!.fillText(r.label, r.x + r.w / 2, r.y + r.h / 2 - 6);
            ctx!.font = '10px ui-monospace, monospace';
            ctx!.fillText(
              `${r.change >= 0 ? '+' : ''}${r.change.toFixed(1)}%`,
              r.x + r.w / 2,
              r.y + r.h / 2 + 7
            );
          }
        }
      }
    }

    resize();

    function onMove(e: MouseEvent) {
      if (!canvas) return;
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;
      const hit = cellRects.find((c) => mx >= c.x && mx <= c.x + c.w && my >= c.y && my <= c.y + c.h);
      if (hit) {
        setHover({ label: hit.label, value: hit.value, x: mx, y: my });
        onCellHover?.({ label: hit.label, value: hit.value });
      } else {
        setHover(null);
        onCellHover?.(null);
      }
    }
    function onLeave() {
      setHover(null);
      onCellHover?.(null);
    }
    canvas.addEventListener('mousemove', onMove);
    canvas.addEventListener('mouseleave', onLeave);

    const ro = new ResizeObserver(resize);
    if (canvas.parentElement) ro.observe(canvas.parentElement);

    return () => {
      ro.disconnect();
      canvas.removeEventListener('mousemove', onMove);
      canvas.removeEventListener('mouseleave', onLeave);
    };
  }, [data, state, palette, showLabels, onCellHover]);

  if (state === 'loading')
    return (
      <div
        ref={ref}
        className={cn('rounded-md border border-border bg-card p-4 @container', className)}
        style={{ height }}
      >
        <OLoadingState rows={3} />
      </div>
    );
  if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
  if (state === 'empty' || !data)
    return <OEmptyState ref={ref} title="No heatmap data" className={className} />;

  return (
    <div
      ref={ref}
      className={cn('relative rounded-md border border-border bg-card overflow-hidden', className)}
      style={{ height }}
    >
      <canvas ref={canvasRef} aria-hidden="true" />
      {hover ? (
        <div
          className="absolute px-2 py-1 bg-popover text-popover-foreground border border-border rounded text-xs shadow pointer-events-none whitespace-nowrap"
          style={{ left: hover.x + 10, top: hover.y + 10 }}
        >
          <span className="font-medium">{hover.label}</span>
          <span className="ml-2 text-muted-foreground tabular-nums">
            {hover.value >= 0 ? '+' : ''}
            {hover.value.toFixed(2)}
          </span>
        </div>
      ) : null}
    </div>
  );
});

OHeatmap.displayName = 'OHeatmap';
