// ============================================================
// AuditDecision (audit.audit_decisions 表主行)
// ============================================================

/** 11 类 audit event 类型(Phase 3 lock)。 */
export type HelivexAuditEventType =
  | 'signal_proposed'
  | 'signal_dropped'
  | 'order_approved'
  | 'risk_blocked'
  | 'order_submitted'
  | 'fill_received'
  | 'order_rejected'
  | 'order_cancelled'
  | 'account_update'
  | 'mode_transition'
  | 'circuit_breaker_state_change';

/** Execution mode 三态(Phase 3 P19 透传)。 */
export type HelivexExecutionMode = 'shadow' | 'paper' | 'live';

/**
 * Conformance tier 三态。
 *
 * ⚠️ 'SILVER_LEGACY' 是 Phase 3 P21 hack tier,验签按 SILVER 走(跳过)。
 *    Phase 4 归一化决定是否合并到 SILVER。
 */
export type HelivexConformanceTier = 'SILVER' | 'SILVER_LEGACY' | 'GOLD';

/** Trade direction 三态。 */
export type HelivexDirection = 'long' | 'short' | 'neutral';

/**
 * 单 audit decision 行。
 *
 * 跟 audit.audit_decisions 表 1:1 映射。
 */
export interface HelivexAuditDecision {
  event_id: string;
  /** ISO 8601 with milliseconds + Z(UTC)。 */
  event_timestamp: string;
  event_type: HelivexAuditEventType;
  strategy_id: string;
  strategy_instance_id: string;
  decision_payload: HelivexDecisionPayload;
  determinism_evidence: HelivexDeterminismEvidence;
  faithfulness_evidence: HelivexFaithfulnessEvidence;
  /** 32-byte hex(64 char string)。 */
  hash_prev: string;
  /** 32-byte hex(64 char string)。 */
  hash_current: string;
  /**
   * ⚠️ NULL = SILVER tier(无签名)。
   *    不是 GOLD signature missing。用 conformance_tier 判断 tier。
   *    64-byte hex(128 char string)。
   */
  signature: string | null;
  /** ⚠️ NULL = SILVER tier。 */
  signing_key_id: string | null;
  conformance_tier: HelivexConformanceTier;
}

/**
 * Decision payload(strategy 决策结果)。
 */
export interface HelivexDecisionPayload {
  symbol: string;
  /**
   * ⚠️ 字符串不是 enum,历史数据可能有 NULL(Phase 2 早期 / neutral signal)。
   */
  direction: HelivexDirection | null;
  /**
   * ⚠️ shadow 模式是模拟值不是真持仓;paper/live 才真。
   *    用 execution_mode 区分。
   */
  notional_filled_usd: number | null;
  /**
   * ⚠️ shadow 模式 = estimated_impact_bps(无真 OKX fill);
   *    paper/live 才有真实差。
   */
  actual_impact_bps: number | null;
  /** 估计 impact(策略层算的预期 bps,所有 mode 都有)。 */
  estimated_impact_bps: number;
  /**
   * ⚠️ Phase 3 P19 透传,paper/live 才填;
   *    shadow 模式可能 NULL(legacy events Pre-P19)。
   */
  execution_mode: HelivexExecutionMode | null;
  /**
   * ⚠️ Phase 3 P0-1 修后含 cost_model_name 字段,
   *    paper 启动后才会出现 'crypto_market_impact_sigmoid_v1'。
   */
  cost_model_name?: string;
  // ... 其他 strategy-specific 字段(Helivex 项目内补充)
}

/**
 * Determinism evidence(可重放性证据)。
 *
 * Helivex 项目内具体补充字段(input_snapshot_hash / stack_version 等)。
 */
export interface HelivexDeterminismEvidence {
  input_snapshot_hash: string;
  stack_version: string;
  /** 其他 strategy-specific 重放证据。 */
  [key: string]: unknown;
}

/**
 * Faithfulness evidence(忠实性证据 — LLM 等不确定性源的痕迹)。
 */
export interface HelivexFaithfulnessEvidence {
  stack_calls: Array<{ function: string; args_hash: string }>;
  /**
   * ⚠️ LLM strategy only(tradingagents_v1+)。
   *    经典 strategy 此字段 undefined。
   *    字符串可能 5-10k 字符。
   */
  llm_reasoning_trace?: string;
  /** ⚠️ LLM strategy only。字符串可能 5-10k 字符。 */
  llm_factor_dsl?: string;
  llm_consensus_votes?: {
    bull: number;
    bear: number;
    referee: number;
  };
  /**
   * ⚠️ 单位 USD。
   *    mock LLM 时为 0,真 DeepSeek 才有非零。
   */
  llm_cost_usd?: number;
  llm_input_tokens?: number;
  llm_output_tokens?: number;
  /**
   * ⚠️ Phase 3 P0-1 修后真填 'crypto_market_impact_sigmoid_v1';
   *    pre-fix audit 此字段缺。
   */
  impact_model_name?: string;
}

// ============================================================
// Chain health (GET /audit/chain/verify 响应)
// ============================================================

export interface HelivexChainBreak {
  event_id: string;
  reason: string;
  /** 期望的 hash_prev,实际的 hash_prev 不一致。 */
  expected_hash_prev?: string;
  actual_hash_prev?: string;
}

export interface HelivexInvalidSignature {
  event_id: string;
  reason: string;
  /** 签名 tier — 通常 GOLD 才检查签名。 */
  conformance_tier: HelivexConformanceTier;
}

export interface HelivexChainVerifyResponse {
  /** 总体是否有效(无 breaks 且无 invalid_signatures)。 */
  chain_valid: boolean;
  /** chain 断裂点列表。 */
  breaks: HelivexChainBreak[];
  /** 签名验证失败列表。 */
  invalid_signatures: HelivexInvalidSignature[];
  /** Tier 分布统计。 */
  tier_distribution: {
    SILVER: number;
    GOLD: number;
    SILVER_LEGACY: number;
  };
}

// ============================================================
// FeatureFlag (Helivex v1.0 已知限制硬阻止)
// 模板参考 Stratum Lock 8(STRATUM_V1_0_DISABLED 模式)
// ============================================================

/**
 * Helivex v1.0(Phase 3 ship 后)已知限制 feature flag。
 *
 * Phase 4+ 启用时,从 HELIVEX_V1_0_DISABLED 集合移除即可。
 */
export enum HelivexFeature {
  /** Backtest engine(Phase 4 W10)。 */
  BacktestEngine = 'backtest_engine',
  /** Live trading mode(Phase 4 W1)。 */
  LiveTradingMode = 'live_trading_mode',
  /** WORM / SEC 17a-4 合规存档(Phase 5)。 */
  WormCompliance = 'worm_compliance',
  /** 多 host HA 部署(Phase 4 W2-infra)。 */
  MultiHostHA = 'multi_host_ha',
  /** Strategy 感知仓位(max_hold 完整实施)(Phase 4 W2 fill subscribe)。 */
  StrategyPositionAware = 'strategy_position_aware',
}

export const HELIVEX_V1_0_DISABLED: Set<HelivexFeature> = new Set([
  HelivexFeature.BacktestEngine,
  HelivexFeature.LiveTradingMode,
  HelivexFeature.WormCompliance,
  HelivexFeature.MultiHostHA,
  HelivexFeature.StrategyPositionAware,
]);

export function isHelivexFeatureEnabled(feature: HelivexFeature): boolean {
  return !HELIVEX_V1_0_DISABLED.has(feature);
}

