/**
 * OCommandPaletteAI - AI 增强命令面板 (Helios Terminal SPEC §14)。
 *
 * 与 OCommandPalette (Batch 9 营销/简单版) 区别:
 *   - OCommandPalette = cmdk 基础组件,纯命令搜索
 *   - OCommandPaletteAI = Terminal-grade,接 AIIntentProvider,中文/拼音/英文三语 + 自然语言
 *
 * Helios 工作台核心入口:
 *   ⌘K → 出现面板 → 用户可以:
 *     [Mode 1] 输入命令名: "BTC K 线"        → 直接匹配命令
 *     [Mode 2] 输入自然语言: "今天 ETH 涨了多少" → 调 AI 解析为 ParsedIntent[],用户确认后执行
 *     [Mode 3] 输入拼音: "btb"              → 拼音首字母模糊匹配
 *
 * 关键特性:
 *   1. 多模式三语搜索 (中文/拼音/英文)  无论用户在哪个语言习惯下输入
 *   2. AI 自然语言意图  解析为 ParsedIntent,用户预览后确认执行
 *   3. 上下文记忆  上次的 symbol / timeframe 作为下次默认上下文
 *   4. 命令历史 + 收藏  最近 20 条 + 用户标星,localStorage 持久化
 *   5. 移动端全屏 + 数字键盘提示  phone 形态下自动全屏
 *   6. 流式 AI 回答 (可选)  stream() 接口,边解析边显示
 *
 * 用法:
 *   <OCommandPaletteAI open={open} onOpenChange={setOpen} />
 *
 *   命令通过 CommandProvider 注册,本组件自动从 useCommands() 拉取。
 *   AI 通过 AIIntentProvider 提供,无 endpoint 时自动降级为纯命令搜索。
 */

'use client';

import * as Dialog from '@radix-ui/react-dialog';
import { Command } from 'cmdk';
import {
  forwardRef,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { cn } from '../../lib/cn';
import { useCommands } from '../../providers/CommandProvider';
import { useAIIntent } from '../../providers/AIIntentProvider';
import { useViewportClass } from '../../hooks/useViewportClass';
import type { CommandDescriptor, ParsedIntent } from '../../protocols';
import { matchPinyin, isLikelyChinese, isPureAscii } from './pinyin-match';

// ============================================================
// Props
// ============================================================

export interface OCommandPaletteAIProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** 显示在搜索框的 placeholder。 */
  placeholder?: string;
  /** 自定义初始查询(打开时填入)。 */
  initialQuery?: string;
  /** 全局快捷键 (默认 ⌘K / Ctrl+K)。 */
  enableShortcut?: boolean;
  /**
   * 当用户输入超过此长度时自动调 AI 解析。0 = 关闭自动,需要手动按 Tab。默认 8。
   */
  aiThreshold?: number;
  /** 上下文 - 透传给 AIIntentProvider.parse 的 context 参数。 */
  context?: Record<string, unknown>;
  /** className 透传到 Dialog.Content。 */
  className?: string;
  /** localStorage key 前缀 (用于多实例隔离)。 */
  storageKey?: string;
}

// ============================================================
// 本地存储
// ============================================================

interface HistoryItem {
  id: string;
  query: string;
  ts: number;
  /** 用户标星收藏。 */
  starred?: boolean;
}

const HISTORY_LIMIT = 30;

function loadHistory(key: string): HistoryItem[] {
  if (typeof localStorage === 'undefined') return [];
  try {
    const raw = localStorage.getItem(`${key}:history`);
    if (!raw) return [];
    return JSON.parse(raw) as HistoryItem[];
  } catch {
    return [];
  }
}

function saveHistory(key: string, history: HistoryItem[]): void {
  if (typeof localStorage === 'undefined') return;
  try {
    localStorage.setItem(`${key}:history`, JSON.stringify(history));
  } catch {
    /* quota */
  }
}

// ============================================================
// 主组件
// ============================================================

export const OCommandPaletteAI = forwardRef<HTMLDivElement, OCommandPaletteAIProps>(
  function OCommandPaletteAI(
    {
      open,
      onOpenChange,
      placeholder = '输入命令、币种或问题... (⌘K)',
      initialQuery = '',
      enableShortcut = true,
      aiThreshold = 8,
      context,
      className,
      storageKey = 'helios-cmd',
    },
    ref
  ) {
    const commands = useCommands();
    const ai = useAIIntent();
    const vp = useViewportClass();
    const isMobile = vp === 'phone';

    const [query, setQuery] = useState(initialQuery);
    const [aiIntents, setAiIntents] = useState<ParsedIntent[] | null>(null);
    const [aiLoading, setAiLoading] = useState(false);
    const [aiError, setAiError] = useState<string | null>(null);
    const [history, setHistory] = useState<HistoryItem[]>(() => loadHistory(storageKey));
    const aiAbortRef = useRef<AbortController | null>(null);
    const aiThrottleRef = useRef<number | null>(null);

    // Open 时聚焦输入 (mobile 也调出键盘)
    const inputRef = useRef<HTMLInputElement | null>(null);
    useEffect(() => {
      if (open) {
        const t = setTimeout(() => inputRef.current?.focus(), 50);
        return () => clearTimeout(t);
      } else {
        setQuery('');
        setAiIntents(null);
        setAiError(null);
        setAiLoading(false);
        aiAbortRef.current?.abort();
        return undefined;
      }
    }, [open]);

    // 当 initialQuery 变 (协议 openPalette 触发) 时同步
    useEffect(() => {
      if (initialQuery) setQuery(initialQuery);
    }, [initialQuery]);

    // 全局快捷键
    useEffect(() => {
      if (!enableShortcut || typeof window === 'undefined') return;
      const onKey = (e: KeyboardEvent) => {
        if ((e.key === 'k' || e.key === 'K') && (e.metaKey || e.ctrlKey)) {
          e.preventDefault();
          onOpenChange(!open);
        }
      };
      window.addEventListener('keydown', onKey);
      return () => window.removeEventListener('keydown', onKey);
    }, [open, onOpenChange, enableShortcut]);

    // 收集所有命令 (按 group)
    // 注:不用 useMemo,因为 registry 是 mutable Map(useRef),
    // 没有 React 状态变化触发重算。每次 render 直接 list() 确保正确。
    const allCommands = commands.list();

    const groupedCommands = useMemo(() => {
      const groups = new Map<string, CommandDescriptor[]>();
      for (const cmd of allCommands) {
        const g = cmd.group ?? 'system';
        if (!groups.has(g)) groups.set(g, []);
        groups.get(g)!.push(cmd);
      }
      return groups;
    }, [allCommands]);

    // 自定义搜索过滤 (cmdk 默认按 label,我们扩展到 aliases + pinyin)
    const filterCommand = useCallback(
      (value: string, search: string, keywords?: string[]): number => {
        if (!search) return 1;
        const lowQ = search.toLowerCase();
        const lowVal = value.toLowerCase();
        // 1) 完全匹配
        if (lowVal.includes(lowQ)) return 1;
        // 2) keywords (含 aliases)
        if (keywords?.some((k) => k.toLowerCase().includes(lowQ))) return 0.9;
        // 3) 拼音匹配 (用户输入纯英文,匹配中文 label 的拼音)
        if (isPureAscii(search)) {
          const allLabels = [value, ...(keywords ?? [])];
          for (const lbl of allLabels) {
            if (isLikelyChinese(lbl) && matchPinyin(lbl, search)) return 0.8;
          }
        }
        return 0;
      },
      []
    );

    // 用户提交查询 → 写历史
    const recordHistory = useCallback(
      (q: string) => {
        if (!q.trim()) return;
        setHistory((h) => {
          const next: HistoryItem[] = [
            { id: `${Date.now()}-${Math.random().toString(36).slice(2)}`, query: q, ts: Date.now() },
            ...h.filter((x) => x.query !== q),
          ].slice(0, HISTORY_LIMIT);
          saveHistory(storageKey, next);
          return next;
        });
      },
      [storageKey]
    );

    // AI 解析触发 (输入超过 aiThreshold 自动,或 Tab 手动)
    const triggerAi = useCallback(
      async (text: string) => {
        if (!ai.isReady()) {
          setAiError('AI 未配置 - 请在 AIIntentProvider 中提供 endpoint');
          return;
        }
        aiAbortRef.current?.abort();
        const ctrl = new AbortController();
        aiAbortRef.current = ctrl;
        setAiLoading(true);
        setAiError(null);
        setAiIntents(null);
        try {
          const intents = await ai.parse(text, context);
          if (!ctrl.signal.aborted) {
            setAiIntents(intents);
          }
        } catch (e) {
          if (!ctrl.signal.aborted) {
            setAiError(e instanceof Error ? e.message : String(e));
          }
        } finally {
          if (!ctrl.signal.aborted) setAiLoading(false);
        }
      },
      [ai, context]
    );

    // 自动触发(节流 600ms)
    useEffect(() => {
      if (!aiThreshold || aiThreshold <= 0) return;
      if (query.length < aiThreshold) {
        setAiIntents(null);
        return;
      }
      // 简单命令匹配的话不去 AI (节省 token)
      const hasMatch = allCommands.some(
        (cmd) =>
          cmd.label.toLowerCase().includes(query.toLowerCase()) ||
          cmd.aliases?.some((a) => a.toLowerCase().includes(query.toLowerCase()))
      );
      if (hasMatch) {
        setAiIntents(null);
        return;
      }
      // 节流
      if (aiThrottleRef.current != null) {
        clearTimeout(aiThrottleRef.current);
      }
      aiThrottleRef.current = window.setTimeout(() => {
        void triggerAi(query);
      }, 600);
      return () => {
        if (aiThrottleRef.current != null) {
          clearTimeout(aiThrottleRef.current);
          aiThrottleRef.current = null;
        }
      };
    }, [query, aiThreshold, triggerAi, allCommands]);

    function handleSelectCommand(cmd: CommandDescriptor) {
      recordHistory(cmd.label);
      cmd.run();
      onOpenChange(false);
    }

    function handleConfirmIntent(intent: ParsedIntent) {
      recordHistory(query);
      void ai.execute(intent);
      onOpenChange(false);
    }

    function handleSelectHistory(item: HistoryItem) {
      setQuery(item.query);
      // 不立即关闭,允许用户检查
    }

    function handleToggleStar(item: HistoryItem) {
      setHistory((h) => {
        const next = h.map((x) =>
          x.id === item.id ? { ...x, starred: !x.starred } : x
        );
        saveHistory(storageKey, next);
        return next;
      });
    }

    function handleClearHistory() {
      setHistory((h) => {
        const kept = h.filter((x) => x.starred);
        saveHistory(storageKey, kept);
        return kept;
      });
    }

    // 移动端全屏样式
    const contentClasses = isMobile
      ? cn(
          'fixed inset-0 z-50 w-full h-full',
          'bg-[color:var(--popover)] flex flex-col',
          className
        )
      : cn(
          'fixed left-1/2 top-[15%] z-50 w-full max-w-2xl -translate-x-1/2',
          'bg-[color:var(--popover)] border border-border rounded-lg shadow-2xl',
          'data-[state=open]:animate-in data-[state=closed]:animate-out',
          'data-[state=open]:zoom-in-95 data-[state=closed]:zoom-out-95',
          className
        );

    return (
      <Dialog.Root open={open} onOpenChange={onOpenChange}>
        <Dialog.Portal>
          <Dialog.Overlay
            className={cn(
              'fixed inset-0 z-50 @container',
              'bg-black/50 backdrop-blur-sm',
              'data-[state=open]:animate-in data-[state=open]:fade-in-0',
              isMobile && 'hidden' // 移动端 content 已经全屏占据
            )}
          />
          <Dialog.Content ref={ref} aria-label="Helios Command Palette" className={contentClasses}>
            <Command
              label="Command Menu"
              loop
              shouldFilter={false}
              className="flex flex-col h-full"
            >
              <Header
                placeholder={placeholder}
                query={query}
                setQuery={setQuery}
                inputRef={inputRef}
                isMobile={isMobile}
                onClose={() => onOpenChange(false)}
                onAskAi={() => void triggerAi(query)}
                aiReady={ai.isReady()}
              />

              <Command.List
                className={cn(
                  'overflow-auto p-2 flex-1',
                  !isMobile && 'max-h-[60vh]'
                )}
              >
                {/* 1. AI 意图区 (优先展示) */}
                {aiLoading || aiError || aiIntents ? (
                  <AiPanel
                    loading={aiLoading}
                    error={aiError}
                    intents={aiIntents}
                    query={query}
                    onConfirm={handleConfirmIntent}
                    commands={allCommands}
                  />
                ) : null}

                {/* 2. 命令区 (按 group) */}
                {!query && history.length > 0 ? (
                  <Command.Group
                    heading="最近 / 收藏"
                    className="text-[10px] text-[color:var(--text-muted)] [&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:uppercase [&_[cmdk-group-heading]]:tracking-[0.04em]"
                  >
                    {history.slice(0, 10).map((h) => (
                      <Command.Item
                        key={h.id}
                        value={h.query}
                        onSelect={() => handleSelectHistory(h)}
                        className="flex items-center gap-3 px-2 py-2 rounded-md cursor-pointer text-sm data-[selected=true]:bg-muted aria-selected:bg-muted"
                      >
                        <span className="text-[color:var(--text-muted)] shrink-0">⏱</span>
                        <span className="flex-1 truncate">{h.query}</span>
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleToggleStar(h);
                          }}
                          className="text-[color:var(--text-muted)] hover:text-[color:var(--alert-warn)]"
                          aria-label="Toggle star"
                        >
                          {h.starred ? '★' : '☆'}
                        </button>
                      </Command.Item>
                    ))}
                    <div className="px-2 pt-1">
                      <button
                        type="button"
                        onClick={handleClearHistory}
                        className="text-[10px] text-[color:var(--text-muted)] hover:text-[color:var(--foreground)] underline"
                      >
                        清除历史 (收藏保留)
                      </button>
                    </div>
                  </Command.Group>
                ) : null}

                {Array.from(groupedCommands.entries()).map(([groupKey, cmds]) => {
                  // 应用自定义 filter
                  const filtered = cmds
                    .map((c) => ({
                      cmd: c,
                      score: filterCommand(c.label, query, c.aliases),
                    }))
                    .filter((x) => x.score > 0)
                    .sort((a, b) => b.score - a.score);

                  if (filtered.length === 0) return null;

                  return (
                    <Command.Group
                      key={groupKey}
                      heading={groupLabel(groupKey as CommandDescriptor['group'])}
                      className="text-[10px] text-[color:var(--text-muted)] [&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:uppercase [&_[cmdk-group-heading]]:tracking-[0.04em]"
                    >
                      {filtered.map(({ cmd }) => (
                        <CommandRow
                          key={cmd.id}
                          cmd={cmd}
                          onSelect={() => handleSelectCommand(cmd)}
                        />
                      ))}
                    </Command.Group>
                  );
                })}

                {/* 3. 空状态 */}
                {query && !aiLoading && !aiIntents && (
                  <Command.Empty className="py-6 text-center text-sm text-[color:var(--text-muted)]">
                    没有匹配命令。
                    {ai.isReady() ? (
                      <div className="mt-1 text-xs">
                        按 <kbd className="px-1 mx-1 rounded bg-muted">Tab</kbd> 或继续输入让 AI 帮你解析
                      </div>
                    ) : null}
                  </Command.Empty>
                )}
              </Command.List>

              <Footer isMobile={isMobile} aiReady={ai.isReady()} />
            </Command>
          </Dialog.Content>
        </Dialog.Portal>
      </Dialog.Root>
    );
  }
);

OCommandPaletteAI.displayName = 'OCommandPaletteAI';

// ============================================================
// 子组件
// ============================================================

function Header({
  placeholder,
  query,
  setQuery,
  inputRef,
  isMobile,
  onClose,
  onAskAi,
  aiReady,
}: {
  placeholder: string;
  query: string;
  setQuery: (q: string) => void;
  inputRef: React.RefObject<HTMLInputElement | null>;
  isMobile: boolean;
  onClose: () => void;
  onAskAi: () => void;
  aiReady: boolean;
}) {
  function handleKey(e: React.KeyboardEvent) {
    // Tab → 立即触发 AI
    if (e.key === 'Tab' && query.trim() && aiReady) {
      e.preventDefault();
      onAskAi();
    }
  }

  return (
    <div
      className={cn(
        'flex items-center border-b border-border px-3',
        isMobile && 'pt-2'
      )}
    >
      <svg
        width="16"
        height="16"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        className="text-[color:var(--text-muted)] shrink-0"
        aria-hidden="true"
      >
        <circle cx="11" cy="11" r="8" />
        <line x1="21" y1="21" x2="16.65" y2="16.65" />
      </svg>
      <Command.Input
        ref={inputRef as never}
        value={query}
        onValueChange={setQuery}
        onKeyDown={handleKey}
        placeholder={placeholder}
        // 移动端提示英文键盘 + 数字 (常用于价格)
        inputMode={isMobile ? 'search' : undefined}
        className={cn(
          'flex w-full bg-transparent px-3 py-2 outline-none placeholder:text-[color:var(--text-muted)]',
          'text-[color:var(--foreground)]',
          isMobile ? 'h-14 text-base' : 'h-12 text-sm'
        )}
        style={{ fontFamily: 'var(--font-ui)' }}
      />
      {isMobile ? (
        <button
          type="button"
          onClick={onClose}
          className="ml-2 px-3 h-10 inline-flex items-center text-[color:var(--text-muted)] active:bg-muted rounded"
          aria-label="Close"
        >
          取消
        </button>
      ) : (
        <kbd
          className="ml-2 inline-flex h-5 select-none items-center rounded border border-border bg-muted px-1.5 font-mono text-[10px] text-[color:var(--text-muted)]"
          aria-hidden="true"
        >
          ESC
        </kbd>
      )}
    </div>
  );
}

function Footer({ isMobile, aiReady }: { isMobile: boolean; aiReady: boolean }) {
  if (isMobile) return null;
  return (
    <div className="border-t border-border px-3 py-2 flex items-center justify-between text-[10px] text-[color:var(--text-muted)] font-mono">
      <div className="flex items-center gap-4">
        <span><kbd className="px-1 rounded bg-muted">↑↓</kbd> 选择</span>
        <span><kbd className="px-1 rounded bg-muted">↵</kbd> 执行</span>
        {aiReady ? (
          <span><kbd className="px-1 rounded bg-muted">Tab</kbd> AI 解析</span>
        ) : null}
      </div>
      <div className="flex items-center gap-2">
        {aiReady ? (
          <span className="text-[color:var(--accent)]">● AI 已就绪</span>
        ) : (
          <span>AI 未配置</span>
        )}
      </div>
    </div>
  );
}

function CommandRow({
  cmd,
  onSelect,
}: {
  cmd: CommandDescriptor;
  onSelect: () => void;
}) {
  return (
    <Command.Item
      value={`${cmd.label} ${cmd.aliases?.join(' ') ?? ''}`}
      onSelect={onSelect}
      className={cn(
        'flex items-center gap-3 px-2 py-2 rounded-md cursor-pointer text-sm',
        'text-[color:var(--foreground)]',
        'data-[selected=true]:bg-muted aria-selected:bg-muted',
        'data-[disabled=true]:opacity-50 data-[disabled=true]:cursor-not-allowed'
      )}
    >
      {cmd.icon ? (
        <span className="shrink-0 text-[color:var(--text-muted)]" aria-hidden="true">
          {/* 我们不内置 lucide,展示首字符占位,实际项目层 wrap 一下 */}
          {String(cmd.icon).charAt(0).toUpperCase()}
        </span>
      ) : null}
      <div className="min-w-0 flex-1">
        <div className="truncate">{cmd.label}</div>
      </div>
      {cmd.hotkey ? (
        <kbd className="ml-auto inline-flex h-5 select-none items-center rounded border border-border bg-muted px-1.5 font-mono text-[10px] text-[color:var(--text-muted)]">
          {cmd.hotkey}
        </kbd>
      ) : null}
    </Command.Item>
  );
}

function AiPanel({
  loading,
  error,
  intents,
  query,
  onConfirm,
  commands,
}: {
  loading: boolean;
  error: string | null;
  intents: ParsedIntent[] | null;
  query: string;
  onConfirm: (intent: ParsedIntent) => void;
  commands: CommandDescriptor[];
}) {
  return (
    <div className="mb-2 rounded-md border border-[color:var(--accent)]/30 bg-[color:var(--accent)]/5 p-3">
      <div className="text-[10px] text-[color:var(--accent)] uppercase tracking-[0.04em]r mb-2 flex items-center gap-2">
        <AiSparkle />
        AI 解析: {query.slice(0, 40)}
        {loading ? <Spinner /> : null}
      </div>

      {error ? (
        <div className="text-xs text-[color:var(--quote-down)]">{error}</div>
      ) : null}

      {intents && intents.length === 0 ? (
        <div className="text-xs text-[color:var(--text-muted)]">没有解析出可执行意图。</div>
      ) : null}

      {intents?.map((intent, i) => {
        const cmd = commands.find((c) => c.id === intent.commandId);
        return (
          <div
            key={i}
            className="mb-1 last:mb-0 p-2 rounded bg-card border border-border/50"
          >
            <div className="flex items-start justify-between gap-2">
              <div className="min-w-0 flex-1">
                <div className="text-sm text-[color:var(--foreground)]">
                  {intent.explanation}
                </div>
                {cmd ? (
                  <div className="mt-1 text-[10px] text-[color:var(--text-muted)] font-mono">
                    → {cmd.label}
                    {Object.keys(intent.args).length > 0 ? (
                      <span className="ml-1 text-[color:var(--accent)]">
                        ({Object.entries(intent.args).map(([k, v]) => `${k}: ${String(v)}`).join(', ')})
                      </span>
                    ) : null}
                  </div>
                ) : (
                  <div className="mt-1 text-[10px] text-[color:var(--quote-down)]">
                    未知命令 {intent.commandId ?? '(无)'}
                  </div>
                )}
                <ConfidenceBar value={intent.confidence} />
              </div>
              {cmd ? (
                <button
                  type="button"
                  onClick={() => onConfirm(intent)}
                  className="px-3 py-1.5 text-xs rounded bg-primary text-primary-foreground hover:opacity-90 shrink-0"
                >
                  执行 ↵
                </button>
              ) : null}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function ConfidenceBar({ value }: { value: number }) {
  const pct = Math.max(0, Math.min(100, value * 100));
  const color =
    value >= 0.8
      ? 'var(--quote-up)'
      : value >= 0.5
        ? 'var(--alert-warn)'
        : 'var(--quote-down)';
  return (
    <div className="mt-1 flex items-center gap-2">
      <div className="h-1 flex-1 rounded bg-muted overflow-hidden">
        <div
          className="h-full transition-[width]"
          style={{ width: `${pct}%`, background: color }}
        />
      </div>
      <span className="text-[10px] text-[color:var(--text-muted)] font-mono">
        {pct.toFixed(0)}%
      </span>
    </div>
  );
}

function AiSparkle() {
  return (
    <svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
      <path d="M12 0l2.5 7.5L22 10l-7.5 2.5L12 20l-2.5-7.5L2 10l7.5-2.5L12 0z" />
    </svg>
  );
}

function Spinner() {
  return (
    <svg width="12" height="12" viewBox="0 0 24 24" className="animate-spin" aria-hidden="true">
      <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="2" fill="none" opacity="0.25" />
      <path
        d="M12 2 A10 10 0 0 1 22 12"
        stroke="currentColor"
        strokeWidth="2"
        fill="none"
        strokeLinecap="round"
      />
    </svg>
  );
}

function groupLabel(group: CommandDescriptor['group']): string {
  const map: Record<NonNullable<CommandDescriptor['group']>, string> = {
    trading: '交易',
    view: '视图',
    chart: '图表',
    alert: '警报',
    system: '系统',
    ai: 'AI',
  };
  return group ? map[group] || group : '系统';
}
