/**
 * FastDataProvider - 高频数据流基础设施。
 *
 * 设计目标:
 *   - 数据接收/处理在 Web Worker (不阻塞主线程)
 *   - 60fps 数据脉冲下主线程零抖动
 *   - 后端通过 WebSocket / SSE 推数据,Worker 负责协议解析
 *   - 订阅者通过回调 (而非 React state) 拿数据,避免重渲染
 *
 * 三种数据接入模式:
 *   1. mock - 内存模拟 (storybook / dev)
 *   2. ws - WebSocket (后端推送)
 *   3. worker - Web Worker 包装 ws + 协议解析
 *
 * v1.0 实现 mock 和 ws 模式,worker 留扩展点 (后端实际启动后再切)。
 */
'use client';

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import type {
  FastDataProtocol,
  ChannelName,
  Unsubscribe,
} from '../protocols';

type Listener = (data: unknown) => void;

interface FastDataProviderProps {
  /** 数据源模式。 */
  mode?: 'mock' | 'ws' | 'worker';

  /** ws 模式时的 endpoint。 */
  endpoint?: string;

  /** worker 模式时的 worker URL。 */
  workerUrl?: string;

  /** 调试日志开关。 */
  debug?: boolean;

  children: ReactNode;
}

const FastDataContext = createContext<FastDataProtocol | null>(null);

/**
 * 内部数据 store。
 * channel → snapshot + listener set
 */
class DataStore {
  private snapshots = new Map<ChannelName, unknown>();
  private listeners = new Map<ChannelName, Set<Listener>>();
  private debug = false;

  constructor(debug = false) {
    this.debug = debug;
  }

  push(channel: ChannelName, data: unknown): void {
    this.snapshots.set(channel, data);
    const ls = this.listeners.get(channel);
    if (ls) {
      for (const l of ls) {
        try {
          l(data);
        } catch (e) {
          if (this.debug) console.error('[FastData listener error]', e);
        }
      }
    }
  }

  subscribe(channel: ChannelName, listener: Listener): Unsubscribe {
    let set = this.listeners.get(channel);
    if (!set) {
      set = new Set();
      this.listeners.set(channel, set);
    }
    set.add(listener);

    // 立即推送当前快照(如有)
    const cur = this.snapshots.get(channel);
    if (cur !== undefined) {
      try {
        listener(cur);
      } catch (e) {
        if (this.debug) console.error('[FastData snapshot push error]', e);
      }
    }

    return () => {
      set!.delete(listener);
      if (set!.size === 0) this.listeners.delete(channel);
    };
  }

  snapshot(channel: ChannelName): unknown {
    return this.snapshots.get(channel) ?? null;
  }

  clear(): void {
    this.snapshots.clear();
    this.listeners.clear();
  }

  channels(): ChannelName[] {
    return Array.from(this.snapshots.keys());
  }
}

/**
 * WebSocket 后端连接管理。
 * 协议假设(后端约定):
 *   - 客户端发送: { type: 'subscribe' | 'unsubscribe', channel: string }
 *   - 服务端推送: { type: 'data', channel: string, payload: unknown }
 *   - 服务端心跳: { type: 'ping' }
 */
class WSConnection {
  private ws: WebSocket | null = null;
  private endpoint: string;
  private subscribed = new Set<ChannelName>();
  private store: DataStore;
  private debug: boolean;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private reconnectAttempt = 0;

  status: 'connecting' | 'connected' | 'disconnected' | 'error' = 'disconnected';
  onStatusChange?: () => void;

  constructor(endpoint: string, store: DataStore, debug: boolean) {
    this.endpoint = endpoint;
    this.store = store;
    this.debug = debug;
  }

  connect(): void {
    if (typeof WebSocket === 'undefined') {
      // SSR / Node 环境跳过
      return;
    }
    this.setStatus('connecting');
    try {
      this.ws = new WebSocket(this.endpoint);
    } catch (_e) {
      this.setStatus('error');
      this.scheduleReconnect();
      return;
    }

    this.ws.onopen = () => {
      this.setStatus('connected');
      this.reconnectAttempt = 0;
      // 重连后恢复订阅
      for (const ch of this.subscribed) {
        this.sendSubscribe(ch);
      }
    };

    this.ws.onmessage = (e) => {
      try {
        const msg = JSON.parse(e.data);
        if (msg.type === 'data' && typeof msg.channel === 'string') {
          this.store.push(msg.channel, msg.payload);
        }
      } catch (err) {
        if (this.debug) console.warn('[FastData WS parse error]', err);
      }
    };

    this.ws.onerror = () => {
      this.setStatus('error');
    };

    this.ws.onclose = () => {
      this.setStatus('disconnected');
      this.scheduleReconnect();
    };
  }

  private setStatus(s: typeof this.status): void {
    if (this.status !== s) {
      this.status = s;
      this.onStatusChange?.();
      if (this.debug) console.log('[FastData WS]', s);
    }
  }

  private scheduleReconnect(): void {
    if (this.reconnectTimer) return;
    // 指数退避: 1s → 2s → 4s → ... 最大 30s
    const delay = Math.min(1000 * Math.pow(2, this.reconnectAttempt), 30000);
    this.reconnectAttempt++;
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      this.connect();
    }, delay);
  }

  private sendSubscribe(channel: ChannelName): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type: 'subscribe', channel }));
    }
  }

  private sendUnsubscribe(channel: ChannelName): void {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type: 'unsubscribe', channel }));
    }
  }

  subscribe(channel: ChannelName): void {
    if (!this.subscribed.has(channel)) {
      this.subscribed.add(channel);
      this.sendSubscribe(channel);
    }
  }

  unsubscribe(channel: ChannelName): void {
    if (this.subscribed.has(channel)) {
      this.subscribed.delete(channel);
      this.sendUnsubscribe(channel);
    }
  }

  disconnect(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    this.subscribed.clear();
    this.ws?.close();
    this.ws = null;
  }

  forceReconnect(): void {
    this.disconnect();
    this.connect();
  }
}

export function FastDataProvider({
  mode = 'mock',
  endpoint,
  debug = false,
  children,
}: FastDataProviderProps) {
  const storeRef = useRef<DataStore | null>(null);
  if (!storeRef.current) storeRef.current = new DataStore(debug);
  const store = storeRef.current;

  const wsRef = useRef<WSConnection | null>(null);
  const [statusVersion, setStatusVersion] = useState(0);

  // 初始化连接
  useEffect(() => {
    if (mode === 'ws' && endpoint && !wsRef.current) {
      wsRef.current = new WSConnection(endpoint, store, debug);
      wsRef.current.onStatusChange = () => setStatusVersion((v) => v + 1);
      wsRef.current.connect();
    }
    // worker 模式 v1.0 不实现,留扩展点
    return () => {
      wsRef.current?.disconnect();
      wsRef.current = null;
    };
  }, [mode, endpoint, debug, store]);

  // 跟踪订阅引用计数,channel 没人订阅时通知后端取消
  const refCount = useRef(new Map<ChannelName, number>());

  const protocol = useMemo<FastDataProtocol>(
    () => ({
      subscribe(channel, callback) {
        // 引用计数 ++
        const cur = refCount.current.get(channel) ?? 0;
        refCount.current.set(channel, cur + 1);
        if (cur === 0 && wsRef.current) {
          wsRef.current.subscribe(channel);
        }

        const unsub = store.subscribe(channel, callback as Listener);
        return () => {
          unsub();
          // 引用计数 --
          const n = (refCount.current.get(channel) ?? 1) - 1;
          if (n <= 0) {
            refCount.current.delete(channel);
            wsRef.current?.unsubscribe(channel);
          } else {
            refCount.current.set(channel, n);
          }
        };
      },
      snapshot(channel) {
        return store.snapshot(channel) as never;
      },
      inject(channel, data) {
        store.push(channel, data);
      },
      get status() {
        // statusVersion 仅用于触发重新计算
        void statusVersion;
        return wsRef.current?.status ?? (mode === 'mock' ? 'connected' : 'disconnected');
      },
      reconnect() {
        wsRef.current?.forceReconnect();
      },
    }),
    [store, mode, statusVersion]
  );

  return <FastDataContext.Provider value={protocol}>{children}</FastDataContext.Provider>;
}

FastDataProvider.displayName = 'FastDataProvider';

export function useFastData(): FastDataProtocol {
  const ctx = useContext(FastDataContext);
  if (!ctx) {
    // 不抛错,返回 no-op 兜底,避免 storybook 单独渲染 Block 时崩
    return {
      subscribe: () => () => {},
      snapshot: () => null,
      inject: () => {},
      status: 'disconnected' as const,
      reconnect: () => {},
    };
  }
  return ctx;
}

/**
 * 订阅 channel 的便利 hook。
 * 返回最新数据,内部用 useState 触发组件重渲染 (适合需要展示的场景)。
 *
 * 注意:高频场景(>10Hz)不要用 useFastDataValue,直接用 useFastData().subscribe + ref。
 */
export function useFastDataValue<T = unknown>(channel: ChannelName | null): T | null {
  const data = useFastData();
  const [value, setValue] = useState<T | null>(() => (channel ? (data.snapshot(channel) as T) : null));

  useEffect(() => {
    if (!channel) {
      setValue(null);
      return;
    }
    const unsub = data.subscribe<T>(channel, (d) => setValue(d));
    return unsub;
  }, [channel, data]);

  return value;
}
