/**
 * OFileUpload - 文件上传 (拖拽 + 选择)。
 *
 * 受控:由 Page 管理 file 列表 + 上传进度。Block 只负责选择 + 显示。
 *
 * @example
 * <OFileUpload
 *   files={files}
 *   onFilesAdd={(newFiles) => uploadAll(newFiles)}
 *   onRemove={(id) => removeFile(id)}
 *   accept="image/*"
 *   maxSize={5 * 1024 * 1024}
 * />
 */
'use client';

import { forwardRef, useCallback, useRef, useState, type DragEvent } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OUploadFile {
  id: string;
  name: string;
  size: number;
  type: string;
  /** 上传进度 0-100。 */
  progress?: number;
  /** 状态。 */
  status?: 'pending' | 'uploading' | 'done' | 'error';
  error?: string;
  /** 预览 URL (图片/视频)。 */
  previewUrl?: string;
}

export interface OFileUploadProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  files: OUploadFile[];
  /** 当用户选择/拖入新文件时触发(由 Page 处理上传)。 */
  onFilesAdd: (files: File[]) => void;
  onRemove?: (id: string) => void;
  /** MIME pattern。 */
  accept?: string;
  /** 单文件最大字节。 */
  maxSize?: number;
  /** 多选。 */
  multiple?: boolean;
  /** 文案。 */
  label?: string;
  hint?: string;
  disabled?: boolean;
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
  return `${(bytes / 1024 / 1024 / 1024).toFixed(1)} GB`;
}

function UploadIcon() {
  return (
    <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
      <path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4" />
      <polyline points="17 8 12 3 7 8" />
      <line x1="12" y1="3" x2="12" y2="15" />
    </svg>
  );
}

function FileIcon() {
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
      <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z" />
      <polyline points="14 2 14 8 20 8" />
    </svg>
  );
}

function XIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
      <line x1="18" y1="6" x2="6" y2="18" />
      <line x1="6" y1="6" x2="18" y2="18" />
    </svg>
  );
}

export const OFileUpload = forwardRef<HTMLDivElement, OFileUploadProps>(function OFileUpload(
  {
    files,
    onFilesAdd,
    onRemove,
    accept,
    maxSize,
    multiple = false,
    label = 'Drop files here or click to upload',
    hint,
    disabled,
    className,
    theme: _t,
  },
  ref
) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isDragOver, setIsDragOver] = useState(false);

  const handleFiles = useCallback(
    (list: FileList | null) => {
      if (!list || disabled) return;
      const arr = Array.from(list);
      const filtered = maxSize ? arr.filter((f) => f.size <= maxSize) : arr;
      if (filtered.length > 0) onFilesAdd(filtered);
    },
    [disabled, maxSize, onFilesAdd]
  );

  return (
    <div ref={ref} className={cn('w-full space-y-3', className)}>
      <button
        type="button"
        onClick={() => inputRef.current?.click()}
        onDragEnter={(e: DragEvent) => {
          e.preventDefault();
          if (!disabled) setIsDragOver(true);
        }}
        onDragLeave={(e: DragEvent) => {
          e.preventDefault();
          setIsDragOver(false);
        }}
        onDragOver={(e: DragEvent) => e.preventDefault()}
        onDrop={(e: DragEvent) => {
          e.preventDefault();
          setIsDragOver(false);
          handleFiles(e.dataTransfer.files);
        }}
        disabled={disabled}
        className={cn(
          'w-full border-2 border-dashed rounded-lg p-8 flex flex-col items-center justify-center gap-2 text-center transition-colors @container',
          'cursor-pointer hover:bg-muted/30',
          isDragOver ? 'border-primary bg-primary/5' : 'border-border',
          disabled && 'opacity-50 cursor-not-allowed'
        )}
      >
        <span className="text-muted-foreground">
          <UploadIcon />
        </span>
        <span className="text-sm font-medium">{label}</span>
        {hint || maxSize || accept ? (
          <span className="text-xs text-muted-foreground">
            {hint ?? `${accept ? `Accepts ${accept}.` : ''} ${maxSize ? `Max ${formatSize(maxSize)}.` : ''}`}
          </span>
        ) : null}
        <input
          ref={inputRef}
          type="file"
          className="sr-only"
          accept={accept}
          multiple={multiple}
          onChange={(e) => {
            handleFiles(e.target.files);
            e.target.value = ''; // 允许重新选同名文件
          }}
        />
      </button>

      {files.length > 0 ? (
        <ul className="space-y-2">
          {files.map((f) => (
            <li
              key={f.id}
              className="flex items-center gap-3 px-3 py-2 bg-card border border-border rounded-md"
            >
              {f.previewUrl ? (
                <img src={f.previewUrl} alt="" className="w-10 h-10 rounded object-cover shrink-0" />
              ) : (
                <span className="w-10 h-10 rounded bg-muted flex items-center justify-center text-muted-foreground shrink-0">
                  <FileIcon />
                </span>
              )}
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between gap-2">
                  <span className="text-sm font-medium truncate">{f.name}</span>
                  <span className="text-xs text-muted-foreground shrink-0">{formatSize(f.size)}</span>
                </div>
                {f.status === 'uploading' ? (
                  <div className="mt-1 h-1 w-full bg-muted rounded-full overflow-hidden">
                    <div
                      className="h-full bg-primary transition-all"
                      style={{ width: `${f.progress ?? 0}%` }}
                    />
                  </div>
                ) : f.status === 'error' ? (
                  <p className="text-xs text-destructive mt-0.5">{f.error ?? 'Upload failed'}</p>
                ) : f.status === 'done' ? (
                  <p className="text-xs text-success mt-0.5">Uploaded</p>
                ) : null}
              </div>
              {onRemove ? (
                <button
                  type="button"
                  onClick={() => onRemove(f.id)}
                  aria-label={`Remove ${f.name}`}
                  className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                >
                  <XIcon />
                </button>
              ) : null}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
});

OFileUpload.displayName = 'OFileUpload';
