/**
 * OAnimatedChart - 折线图带绘制动画 (类 2)。
 *
 * 利用 recharts Line 内置 isAnimationActive + animationDuration,
 * 再叠加 motion 的容器淡入与数据点 stagger。
 *
 * 在 reduced-motion 下完全静态。
 */
'use client';

import {
  CartesianGrid,
  Legend,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import { motion } from 'motion/react';
import { forwardRef, useMemo } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockDataProps } from '../../lib/types';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import type { OTimeSeriesData } from '../OTimeSeriesChart';

const CHART_COLORS = ['var(--chart-1)', 'var(--chart-2)', 'var(--chart-3)', 'var(--chart-4)', 'var(--chart-5)'];

export interface OAnimatedChartProps extends OBlockDataProps<OTimeSeriesData> {
  height?: number;
  /** 绘制动画总时长 (ms)。 */
  animationDuration?: number;
  /** 多 series 时,每条之间的延迟 (ms)。 */
  stagger?: number;
  showLegend?: boolean;
  showGrid?: boolean;
}

function transform(series: OTimeSeriesData['series']) {
  const keyMap = new Map<string | number, Record<string, unknown>>();
  for (const s of series) {
    for (const p of s.data) {
      const k = p.x instanceof Date ? p.x.toISOString() : p.x;
      const row = keyMap.get(k) ?? { x: p.x };
      row[s.name] = p.y;
      keyMap.set(k, row);
    }
  }
  return Array.from(keyMap.values()).sort((a, b) => {
    const ax = a.x as number | string;
    const bx = b.x as number | string;
    return ax < bx ? -1 : ax > bx ? 1 : 0;
  });
}

export const OAnimatedChart = forwardRef<HTMLDivElement, OAnimatedChartProps>(
  function OAnimatedChart(
    {
      data,
      loading,
      error,
      empty,
      height = 300,
      animationDuration = 1500,
      stagger = 200,
      showLegend = true,
      showGrid = true,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const state = resolveBlockState({ data, loading, error, empty });
    const reduced = useReducedMotion();
    const merged = useMemo(() => (data ? transform(data.series) : []), [data]);

    if (state === 'loading')
      return (
        <div
          ref={ref}
          className={cn('rounded-md border border-border bg-card p-4 @container', className)}
          style={{ height }}
        >
          <OLoadingState variant="shimmer" rows={3} rowHeight="2rem" />
        </div>
      );
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data || merged.length === 0)
      return (
        <OEmptyState
          ref={ref}
          title="No data"
          description="No time series to animate."
          className={className}
        />
      );

    const xFmt = data.xAxis?.format ?? ((v: unknown) => String(v));
    const yFmt = data.yAxis?.format ?? ((v: number) => v.toLocaleString());

    return (
      <motion.div
        ref={ref}
        className={cn('rounded-md border border-border bg-card p-4', className)}
        initial={reduced ? false : { opacity: 0, y: 8 }}
        animate={reduced ? undefined : { opacity: 1, y: 0 }}
        transition={{ duration: 0.4 }}
      >
        <ResponsiveContainer width="100%" height={height}>
          <LineChart data={merged}>
            {showGrid ? (
              <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" opacity={0.5} />
            ) : null}
            <XAxis dataKey="x" tickFormatter={xFmt} stroke="var(--muted-foreground)" fontSize={11} />
            <YAxis tickFormatter={yFmt} stroke="var(--muted-foreground)" fontSize={11} />
            <Tooltip
              contentStyle={{
                background: 'var(--popover)',
                border: '1px solid var(--border)',
                borderRadius: 'var(--radius-md)',
                fontSize: 12,
                color: 'var(--popover-foreground)',
              }}
              formatter={(v) => yFmt(Number(v))}
            />
            {showLegend ? <Legend wrapperStyle={{ fontSize: 12 }} /> : null}
            {data.series.map((s, i) => (
              <Line
                key={s.name}
                dataKey={s.name}
                type="monotone"
                stroke={CHART_COLORS[i % CHART_COLORS.length]}
                strokeWidth={2}
                dot={false}
                activeDot={{ r: 4 }}
                isAnimationActive={!reduced}
                animationDuration={animationDuration}
                animationBegin={i * stagger}
                animationEasing="ease-out"
              />
            ))}
          </LineChart>
        </ResponsiveContainer>
      </motion.div>
    );
  }
);

OAnimatedChart.displayName = 'OAnimatedChart';
