/**
 * ORegimeBar (Tide Wave 1 E1, Atom)
 *
 * 顶部状态条核心,显示当前 regime 状态、置信度、趋势、sparkline、持久天数。
 *
 * 来源: OUI_WAVE_1_REQUIREMENTS_v1.0.md §3
 *
 * 视觉示意:
 *   [积极] 0.82 ⬈ ▁▂▃▄▅▆▇█ ✓ 持久 2 天
 *
 * 关键行为:
 *   - regime 颜色用 --regime-{state} CSS 变量
 *   - transitional 中: pulse 动画 + 显示 "→ {target} {days}d"
 *   - sparkline 最后 3 bar 用 regime 颜色 1.0,其余 hesitant 0.4
 *   - daysInState: 1 天不显示 / 2-6 天 / 7+ 天加粗
 *   - 单击 → onClick(父组件挂 ORegimeExplanationPopover)
 */
import { forwardRef, useCallback, type KeyboardEvent } from 'react';
import { cn } from '../../lib/cn';
import {
  REGIME_COLOR_VAR,
  REGIME_LABEL,
  type RegimeState,
} from '../../types/tide';
import type { OBlockBaseProps } from '../../lib/types';

export interface ORegimeBarProps extends Omit<OBlockBaseProps, 'variant'> {
  regime: RegimeState;
  /** 0-1 */
  confidence: number;
  trendDirection: 'up' | 'down' | 'flat';
  /** 近 15 数据点,用于 sparkline */
  sparklineData: number[];
  /** 当前 regime 持续天数 */
  daysInState?: number;
  /** 是否有 transitional 切换中 */
  hasPendingChange?: boolean;
  transitionalState?: RegimeState;
  transitionalDays?: number;
  /** 单击触发(父组件弹 ORegimeExplanationPopover)。 */
  onClick?: () => void;
}

const TREND_ICON: Record<'up' | 'down' | 'flat', string> = {
  up: '⬈',
  down: '⬊',
  flat: '→',
};

const TREND_COLOR: Record<'up' | 'down' | 'flat', string> = {
  up: 'var(--red-up)',
  down: 'var(--green-down)',
  flat: 'var(--muted-foreground)',
};

export const ORegimeBar = forwardRef<HTMLButtonElement, ORegimeBarProps>(
  function ORegimeBar(
    {
      regime,
      confidence,
      trendDirection,
      sparklineData,
      daysInState,
      hasPendingChange,
      transitionalState,
      transitionalDays,
      onClick,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    // sparkline 截断到 15 点
    const sparkData = sparklineData.slice(-15);
    const sparkMax = Math.max(...sparkData, 1);
    const sparkMin = Math.min(...sparkData, 0);
    const sparkRange = sparkMax - sparkMin || 1;

    const handleClick = useCallback(() => {
      onClick?.();
    }, [onClick]);

    const handleKey = useCallback(
      (e: KeyboardEvent<HTMLButtonElement>) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick?.();
        }
      },
      [onClick]
    );

    const regimeColor = REGIME_COLOR_VAR[regime];
    const showPersistence = (daysInState ?? 0) >= 2;
    const persistenceBold = (daysInState ?? 0) >= 7;

    return (
      <button
        ref={ref}
        type="button"
        onClick={handleClick}
        onKeyDown={handleKey}
        aria-label={`当前 regime: ${REGIME_LABEL[regime]} 置信度 ${(confidence * 100).toFixed(0)}%`}
        className={cn(
          'inline-flex items-center gap-2 px-2 py-1 rounded @container',
          'bg-[color:var(--card)] hover:bg-[color:var(--accent)]',
          'border border-[color:var(--border-strong)]',
          'transition-colors cursor-pointer',
          'focus:outline-none focus-visible:ring-2 focus-visible:ring-ring',
          hasPendingChange && 'animate-pulse',
          className
        )}
        style={{ fontFamily: 'var(--font-mono)' }}
      >
        {/* regime chip */}
        <span
          className="px-1.5 py-0.5 rounded text-xs font-bold"
          style={{
            backgroundColor: regimeColor,
            color: 'var(--foreground)',
          }}
        >
          {REGIME_LABEL[regime]}
        </span>

        {/* confidence */}
        <span
          className="text-sm font-mono"
          style={{ color: 'var(--foreground)' }}
        >
          {confidence.toFixed(2)}
        </span>

        {/* trend arrow */}
        <span
          className="text-sm"
          style={{ color: TREND_COLOR[trendDirection] }}
          aria-hidden="true"
        >
          {TREND_ICON[trendDirection]}
        </span>

        {/* sparkline (svg) */}
        <svg
          width={60}
          height={16}
          className="shrink-0"
          aria-hidden="true"
          role="img"
        >
          {sparkData.map((v, i) => {
            const total = sparkData.length;
            const barWidth = 60 / total - 1;
            const barHeight = ((v - sparkMin) / sparkRange) * 14 + 2;
            const x = i * (60 / total);
            const y = 16 - barHeight;
            const isRecent = i >= total - 3;
            return (
              <rect
                key={i}
                x={x}
                y={y}
                width={Math.max(barWidth, 1)}
                height={barHeight}
                fill={isRecent ? regimeColor : 'var(--regime-hesitant)'}
                opacity={isRecent ? 1.0 : 0.4}
              />
            );
          })}
        </svg>

        {/* transitional → target */}
        {hasPendingChange && transitionalState && (
          <span
            className="text-xs font-mono"
            style={{ color: 'var(--muted-foreground)' }}
          >
            → {REGIME_LABEL[transitionalState]} {transitionalDays ?? 0}d
          </span>
        )}

        {/* persistence */}
        {showPersistence && (
          <span
            className={cn('text-xs', persistenceBold && 'font-bold')}
            style={{ color: 'var(--muted-foreground)' }}
          >
            ✓ 持久 {daysInState} 天
          </span>
        )}
      </button>
    );
  }
);

ORegimeBar.displayName = 'ORegimeBar';
