/**
 * OSparkline — 迷你折线 / 趋势图。
 *
 * 用途:
 *   - 数据点序列(健康 24h trend / 价格走势 / 容量曲线)
 *   - 独立使用,或嵌入卡片(OKPICard 内置 MiniSparkline 即此组件)
 *
 * 设计原则:无 axis / 无 grid / 无 tooltip — 这是"sparkline",不是 chart。
 * 需要交互的用 OAnimatedChart / OEquityCurveChart 等更重组件。
 *
 * 数据契约:`values: number[]`(任意正负数),`indicator?: 'up'|'down'|'neutral'`(影响颜色)
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OSparklineProps extends Omit<OBlockBaseProps, 'variant'> {
  values: number[];
  indicator?: 'up' | 'down' | 'neutral';
  /** 自定义颜色 CSS variable,例 '--success'。优先级高于 indicator 推断。 */
  colorVar?: string;
  width?: number;
  height?: number;
  /** 是否填充曲线下方区域。 */
  fill?: boolean;
  /** 终点标记圆点。 */
  showEndDot?: boolean;
  strokeWidth?: number;
  ariaLabel?: string;
}

function indicatorColor(indicator?: 'up' | 'down' | 'neutral'): string {
  if (indicator === 'up') return 'var(--quote-up)';
  if (indicator === 'down') return 'var(--quote-down)';
  return 'var(--muted-foreground)';
}

export const OSparkline = forwardRef<SVGSVGElement, OSparklineProps>(function OSparkline(
  {
    values,
    indicator,
    colorVar,
    width = 80,
    height = 24,
    fill = false,
    showEndDot = false,
    strokeWidth = 1.5,
    ariaLabel,
    className,
    theme: _t,
    size: _s,
  },
  ref
) {
  if (!values.length) return null;
  const min = Math.min(...values);
  const max = Math.max(...values);
  const range = max - min || 1;
  const step = values.length > 1 ? width / (values.length - 1) : width;

  const coords = values.map((v, i) => ({
    x: i * step,
    y: height - ((v - min) / range) * height,
  }));

  const pointsStr = coords.map((p) => `${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(' ');
  const color = colorVar ? `var(${colorVar})` : indicatorColor(indicator);

  const last = coords[coords.length - 1]!;

  return (
    <svg
      ref={ref}
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      role="img"
      aria-label={ariaLabel ?? `Sparkline of ${values.length} points`}
      className={cn('inline-block @container', className)}
      preserveAspectRatio="none"
    >
      {fill && (
        <polygon
          points={`0,${height} ${pointsStr} ${last.x.toFixed(2)},${height}`}
          fill={color}
          opacity={0.15}
        />
      )}
      <polyline
        points={pointsStr}
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      {showEndDot && (
        <circle
          cx={last.x}
          cy={last.y}
          r={Math.max(strokeWidth * 1.5, 2)}
          fill={color}
        />
      )}
    </svg>
  );
});

OSparkline.displayName = 'OSparkline';
