/**
 * OCommandPalette - 全局命令面板 (⌘K)。
 *
 * 基于 cmdk + Radix Dialog。支持:
 *   - 全局快捷键 (默认 ⌘K / Ctrl+K)
 *   - 分组命令 (group)
 *   - 关键词搜索
 *   - 键盘导航 (↑↓ Enter Esc)
 *   - recent / favorites 状态由 Page 维护(受控)
 *
 * @example
 * <OCommandPalette
 *   open={open}
 *   onOpenChange={setOpen}
 *   groups={[
 *     {
 *       label: 'Markets',
 *       commands: [
 *         { id: 'btc', label: 'BTC/USDT', onSelect: () => router.push('/btc') },
 *       ],
 *     },
 *   ]}
 * />
 */
'use client';

import * as Dialog from '@radix-ui/react-dialog';
import { Command } from 'cmdk';
import { forwardRef, useEffect, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OCommandItem {
  id: string;
  label: string;
  description?: string;
  icon?: ReactNode;
  shortcut?: string;
  keywords?: string[];
  onSelect: () => void;
  disabled?: boolean;
}

export interface OCommandGroup {
  label: string;
  commands: OCommandItem[];
}

export interface OCommandPaletteProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  groups: OCommandGroup[];
  placeholder?: string;
  emptyMessage?: string;
  /** 启用全局快捷键 (默认 true,⌘K / Ctrl+K)。 */
  enableShortcut?: boolean;
}

export const OCommandPalette = forwardRef<HTMLDivElement, OCommandPaletteProps>(
  function OCommandPalette(
    {
      open,
      onOpenChange,
      groups,
      placeholder = 'Type a command or search...',
      emptyMessage = 'No results found.',
      enableShortcut = true,
      className,
      theme: _t,
    },
    ref
  ) {
    useEffect(() => {
      if (!enableShortcut || typeof window === 'undefined') return;
      const onKey = (e: KeyboardEvent) => {
        if ((e.key === 'k' || e.key === 'K') && (e.metaKey || e.ctrlKey)) {
          e.preventDefault();
          onOpenChange(!open);
        }
      };
      window.addEventListener('keydown', onKey);
      return () => window.removeEventListener('keydown', onKey);
    }, [open, onOpenChange, enableShortcut]);

    return (
      <Dialog.Root open={open} onOpenChange={onOpenChange}>
        <Dialog.Portal>
          <Dialog.Overlay className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm data-[state=open]:animate-in data-[state=open]:fade-in-0" />
          <Dialog.Content
            ref={ref}
            aria-label="Command palette"
            className={cn(
              'fixed left-1/2 top-[20%] z-50 w-full max-w-xl -translate-x-1/2 @container',
              'bg-popover border border-border rounded-lg shadow-2xl',
              'data-[state=open]:animate-in data-[state=closed]:animate-out',
              'data-[state=open]:zoom-in-95 data-[state=closed]:zoom-out-95',
              className
            )}
          >
            <Command label="Command Menu" loop>
              <div className="flex items-center border-b border-border px-3">
                <svg
                  width="16"
                  height="16"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  className="text-muted-foreground shrink-0"
                  aria-hidden="true"
                >
                  <circle cx="11" cy="11" r="8" />
                  <line x1="21" y1="21" x2="16.65" y2="16.65" />
                </svg>
                <Command.Input
                  placeholder={placeholder}
                  className="flex h-12 w-full bg-transparent px-3 py-2 text-sm outline-none placeholder:text-muted-foreground"
                />
                <kbd className="ml-2 hidden sm:inline-flex h-5 select-none items-center gap-1 rounded border border-border bg-muted px-1.5 font-mono text-[10px] text-muted-foreground">
                  ESC
                </kbd>
              </div>
              <Command.List className="max-h-[400px] overflow-auto p-2">
                <Command.Empty className="py-6 text-center text-sm text-muted-foreground">
                  {emptyMessage}
                </Command.Empty>
                {groups.map((group) => (
                  <Command.Group
                    key={group.label}
                    heading={group.label}
                    className="text-xs text-muted-foreground [&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:uppercase [&_[cmdk-group-heading]]:tracking-[0.04em]"
                  >
                    {group.commands.map((cmd) => (
                      <Command.Item
                        key={cmd.id}
                        value={`${cmd.label} ${cmd.keywords?.join(' ') ?? ''}`}
                        disabled={cmd.disabled}
                        onSelect={() => {
                          cmd.onSelect();
                          onOpenChange(false);
                        }}
                        className={cn(
                          'flex items-center gap-3 px-2 py-2 rounded-md cursor-pointer text-sm',
                          'data-[selected=true]:bg-muted aria-selected:bg-muted',
                          'data-[disabled=true]:opacity-50 data-[disabled=true]:cursor-not-allowed'
                        )}
                      >
                        {cmd.icon ? <span className="shrink-0 text-muted-foreground">{cmd.icon}</span> : null}
                        <div className="min-w-0 flex-1">
                          <div className="truncate text-foreground">{cmd.label}</div>
                          {cmd.description ? (
                            <div className="text-xs text-muted-foreground truncate">{cmd.description}</div>
                          ) : null}
                        </div>
                        {cmd.shortcut ? (
                          <kbd className="ml-auto inline-flex h-5 select-none items-center gap-1 rounded border border-border bg-muted px-1.5 font-mono text-[10px] text-muted-foreground">
                            {cmd.shortcut}
                          </kbd>
                        ) : null}
                      </Command.Item>
                    ))}
                  </Command.Group>
                ))}
              </Command.List>
            </Command>
          </Dialog.Content>
        </Dialog.Portal>
      </Dialog.Root>
    );
  }
);

OCommandPalette.displayName = 'OCommandPalette';
