/**
 * OUserPresence - 用户在线状态指示。
 *
 * 4 状态: online / away / busy / offline
 * 通常和 OAvatar 一起用,作为右下角小圆点。
 *
 * @example
 * <div className="relative inline-block">
 *   <OAvatar name="Alice" />
 *   <OUserPresence status="online" className="absolute -bottom-0.5 -right-0.5" />
 * </div>
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, type CSSProperties } from 'react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

export type PresenceStatus = 'online' | 'away' | 'busy' | 'offline';

const STATUS_COLOR: Record<PresenceStatus, string> = {
  online: 'var(--success)',
  away: 'var(--warning)',
  busy: 'var(--destructive)',
  offline: 'var(--muted-foreground)',
};

const dotVariants = cva('rounded-full ring-2 ring-background inline-block', {
  variants: {
    size: {
      sm: 'w-2 h-2',
      md: 'w-2.5 h-2.5',
      lg: 'w-3 h-3',
    },
  },
  defaultVariants: { size: 'md' },
});

type DotVariantProps = VariantProps<typeof dotVariants>;

export interface OUserPresenceProps
  extends Omit<OBlockBaseProps, 'variant' | 'size'>,
    DotVariantProps {
  status: PresenceStatus;
  /** 显示文本标签 (e.g. "Online"),不显示则只有圆点。 */
  showLabel?: boolean;
  /** pulse 动画 (仅 online)。 */
  pulse?: boolean;
}

const LABELS: Record<PresenceStatus, string> = {
  online: 'Online',
  away: 'Away',
  busy: 'Busy',
  offline: 'Offline',
};

export const OUserPresence = forwardRef<HTMLSpanElement, OUserPresenceProps>(function OUserPresence(
  { status, size = 'md', showLabel = false, pulse = false, className, theme: _t },
  ref
) {
  const reduced = useReducedMotion();
  const animate = pulse && !reduced && status === 'online';
  const color = STATUS_COLOR[status];
  const dotStyle: CSSProperties = { backgroundColor: color };

  const dot = (
    <span className="relative inline-flex items-center justify-center" aria-hidden="true">
      {animate ? (
        <span
          className="absolute inline-flex h-full w-full rounded-full opacity-75 animate-ping"
          style={dotStyle}
        />
      ) : null}
      <span className={cn(dotVariants({ size }))} style={dotStyle} />
    </span>
  );

  if (!showLabel) {
    return (
      <span
        ref={ref}
        className={cn('inline-flex @container', className)}
        role="img"
        aria-label={LABELS[status]}
        title={LABELS[status]}
      >
        {dot}
      </span>
    );
  }

  return (
    <span
      ref={ref}
      className={cn('inline-flex items-center gap-1.5 text-xs text-muted-foreground', className)}
    >
      {dot}
      <span>{LABELS[status]}</span>
    </span>
  );
});

OUserPresence.displayName = 'OUserPresence';
