/**
 * OToolbarFrame - 工具栏容器。
 *
 * 三槽位:left / center / right。紧凑布局,装 Atom (Button / Input / Select 等)。
 */
'use client';

import { forwardRef, type HTMLAttributes } from 'react';
import { cn } from '../../lib/cn';
import type { FrameSlot, OBlockBaseProps } from '../../lib/types';

const HEIGHT_CLASS = {
  sm: 'h-9',
  md: 'h-11',
  lg: 'h-14',
} as const;

const VARIANT_CLASS = {
  default: 'bg-card border border-border',
  ghost: 'bg-transparent',
  elevated: 'bg-card border border-border shadow-sm',
} as const;

export interface OToolbarFrameProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>,
    Omit<OBlockBaseProps, 'variant' | 'size'> {
  left?: FrameSlot;
  center?: FrameSlot;
  right?: FrameSlot;
  variant?: keyof typeof VARIANT_CLASS;
  size?: keyof typeof HEIGHT_CLASS;
  /** 是否粘性顶部。 */
  sticky?: boolean;
}

export const OToolbarFrame = forwardRef<HTMLDivElement, OToolbarFrameProps>(function OToolbarFrame(
  { left, center, right, variant = 'default', size = 'md', sticky = false, className, theme: _t, ...rest },
  ref
) {
  return (
    <div
      ref={ref}
      role="toolbar"
      className={cn(
        'flex items-center gap-2 px-3 rounded-md',
        HEIGHT_CLASS[size],
        VARIANT_CLASS[variant],
        sticky && 'sticky top-0 z-20 backdrop-blur-md',
        className
      )}
      {...rest}
    >
      <div className="flex items-center gap-2 min-w-0">{left}</div>
      <div className="flex-1 flex items-center justify-center gap-2 min-w-0">{center}</div>
      <div className="flex items-center gap-2 min-w-0 ml-auto">{right}</div>
    </div>
  );
});

OToolbarFrame.displayName = 'OToolbarFrame';
