/**
 * OScrollRevealSection - 滚动驱动显示 (类 2)。
 *
 * 优先使用 CSS scroll-driven animations (2024+ 标准),
 * 不支持时降级为 IntersectionObserver + class 切换。
 *
 * SPEC §3.5 类 1/2 基础前沿。在 reduced-motion 下:
 *   元素直接显示 (不滚动驱动)。
 */
'use client';

import { forwardRef, useEffect, useRef, useState, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

const SUPPORTS_SCROLL_TIMELINE = (() => {
  if (typeof CSS === 'undefined' || !CSS.supports) return false;
  return CSS.supports('animation-timeline: view()');
})();

const DIRECTION_INITIAL: Record<string, string> = {
  up: 'translateY(24px)',
  down: 'translateY(-24px)',
  left: 'translateX(24px)',
  right: 'translateX(-24px)',
  none: 'translateY(0)',
};

export interface OScrollRevealSectionProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 进场方向 (元素从该方向滑入)。 */
  direction?: 'up' | 'down' | 'left' | 'right' | 'none';
  /** 进度阈值 (IntersectionObserver fallback 用,0-1)。 */
  threshold?: number;
  /** 动画时长 (ms,fallback 用)。 */
  duration?: number;
  /** 一次性触发 (默认 true)。 */
  once?: boolean;
  children: ReactNode;
}

export const OScrollRevealSection = forwardRef<HTMLDivElement, OScrollRevealSectionProps>(
  function OScrollRevealSection(
    {
      direction = 'up',
      threshold = 0.15,
      duration = 600,
      once = true,
      className,
      children,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const reduced = useReducedMotion();
    const localRef = useRef<HTMLDivElement | null>(null);
    const [revealed, setRevealed] = useState(reduced);

    useEffect(() => {
      if (reduced) {
        setRevealed(true);
        return;
      }
      // 如果浏览器支持 scroll-timeline,跳过 IO (CSS 接管)
      if (SUPPORTS_SCROLL_TIMELINE) return;
      const el = localRef.current;
      if (!el || typeof IntersectionObserver === 'undefined') {
        setRevealed(true);
        return;
      }
      const io = new IntersectionObserver(
        (entries) => {
          for (const entry of entries) {
            if (entry.isIntersecting) {
              setRevealed(true);
              if (once) io.disconnect();
            } else if (!once) {
              setRevealed(false);
            }
          }
        },
        { threshold }
      );
      io.observe(el);
      return () => io.disconnect();
    }, [reduced, threshold, once]);

    const useCssTimeline = SUPPORTS_SCROLL_TIMELINE && !reduced;

    const style = useCssTimeline
      ? ({
          animation: `helios-reveal-${direction} ${duration}ms ease-out both`,
          animationTimeline: 'view()',
          animationRange: 'entry 0% cover 30%',
        } as React.CSSProperties)
      : ({
          transition: `opacity ${duration}ms ease-out, transform ${duration}ms ease-out`,
          opacity: revealed ? 1 : 0,
          transform: revealed ? 'translate(0,0)' : DIRECTION_INITIAL[direction],
        } as React.CSSProperties);

    // CSS keyframes (一次性注入)
    useEffect(() => {
      if (!useCssTimeline || typeof document === 'undefined') return;
      const id = 'helios-reveal-keyframes';
      if (document.getElementById(id)) return;
      const tag = document.createElement('style');
      tag.id = id;
      tag.textContent = `
@keyframes helios-reveal-up { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
@keyframes helios-reveal-down { from { opacity: 0; transform: translateY(-24px); } to { opacity: 1; transform: translateY(0); } }
@keyframes helios-reveal-left { from { opacity: 0; transform: translateX(24px); } to { opacity: 1; transform: translateX(0); } }
@keyframes helios-reveal-right { from { opacity: 0; transform: translateX(-24px); } to { opacity: 1; transform: translateX(0); } }
@keyframes helios-reveal-none { from { opacity: 0; } to { opacity: 1; } }
      `;
      document.head.appendChild(tag);
    }, [useCssTimeline]);

    return (
      <div
        ref={(el) => {
          localRef.current = el;
          if (typeof ref === 'function') ref(el);
          else if (ref) ref.current = el;
        }}
        className={cn('@container', className)}
        style={style}
        data-revealed={revealed || useCssTimeline ? 'true' : 'false'}
        data-uses-scroll-timeline={useCssTimeline}
      >
        {children}
      </div>
    );
  }
);

OScrollRevealSection.displayName = 'OScrollRevealSection';
