/**
 * OPositionList - 持仓列表 (合约专用)。
 *
 * 不是简单的 ODataTable - 含合约专属字段:
 *   - 方向 (LONG / SHORT) + 杠杆 chip
 *   - 持仓数量 + 入场价 + 标记价
 *   - 未实现 PnL (大字,绿/红) + PnL%
 *   - 强平价 + 距强平 % (危险高亮)
 *   - 保证金 (逐仓金额 / 全仓占比)
 *   - 一键平仓按钮 / 一键反手
 *
 * 数据契约对齐 Binance ACCOUNT_UPDATE.P 字段:
 *   pa  = positionAmt (持仓数量)
 *   ep  = entryPrice
 *   up  = unrealizedPnl
 *   ps  = positionSide (LONG | SHORT | BOTH)
 *   + REST /fapi/v2/positionRisk 补充 liquidationPrice / leverage / marginType
 */

'use client';

import { forwardRef, useEffect, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import { useFastData } from '../../providers/FastDataProvider';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';

export interface OPosition {
  symbol: string;
  side: 'LONG' | 'SHORT';
  /** 持仓数量 (币本位). */
  amount: number;
  entryPrice: number;
  markPrice: number;
  /** 强平价. */
  liquidationPrice: number;
  leverage: number;
  marginType: 'isolated' | 'cross';
  /** 占用保证金 USDT. */
  margin: number;
  /** 未实现盈亏 USDT. */
  unrealizedPnl: number;
  /** 盈亏百分比 (相对入场,已乘杠杆). */
  pnlPercent: number;
  /** 已实现盈亏 (累计). */
  realizedPnl?: number;
  /** 止盈 (可选). */
  tp?: number;
  /** 止损 (可选). */
  sl?: number;
}

export interface OPositionListData {
  positions: OPosition[];
}

export interface OPositionListProps
  extends OBlockDataProps<OPositionListData>,
    Pick<TerminalBlockProps, 'channel' | 'flashOnUpdate' | 'dataDelay' | 'regulation'> {
  onClose?: (position: OPosition) => void;
  onReverse?: (position: OPosition) => void;
  onAdjustLeverage?: (position: OPosition) => void;
  onAdjustTpSl?: (position: OPosition) => void;
  /** 行点击 (例如跳到该 symbol K 线). */
  onRowClick?: (position: OPosition) => void;
  /** 距强平百分比小于此值则整行高亮警告. */
  dangerThreshold?: number;
  maxHeight?: number;
}

export const OPositionList = forwardRef<HTMLDivElement, OPositionListProps>(
  function OPositionList(
    {
      data: dataProp,
      loading,
      error,
      empty,
      channel,
      onClose,
      onReverse,
      onAdjustLeverage,
      onAdjustTpSl,
      onRowClick,
      dangerThreshold = 5,
      maxHeight = 480,
      flashOnUpdate: _f,
      dataDelay = 0,
      regulation: _r,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OPositionListData | null>(null);
    useEffect(() => {
      if (!channel || !fastData) return;
      return fastData.subscribe<OPositionListData>(channel, setChannelData);
    }, [channel, fastData]);

    const data = channel ? channelData : (dataProp ?? null);
    const state = resolveBlockState({ data, loading, error, empty });

    if (state === 'loading')
      return (
        <div ref={ref} className={cn('rounded-md border border-border bg-card p-4', className)}>
          <OLoadingState rows={4} />
        </div>
      );
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data || data.positions.length === 0)
      return (
        <OEmptyState
          ref={ref}
          title="暂无持仓"
          description="还没有开仓,使用下单面板开始交易"
          className={className}
        />
      );

    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card overflow-hidden flex flex-col relative @container',
          className
        )}
        style={{ fontFamily: 'var(--font-ui)' }}
      >
        {dataDelay > 0 ? (
          <div className="absolute top-2 right-3 z-10 text-[10px] text-[color:var(--alert-warn)] font-mono pointer-events-none">
            延时 {dataDelay}m
          </div>
        ) : null}

        {/* Header */}
        <div className="px-3 py-2 border-b border-border flex items-center justify-between">
          <span className="text-[11px] font-semibold uppercase tracking-[0.04em] text-[color:var(--muted-foreground)]">
            持仓 ({data.positions.length})
          </span>
        </div>

        {/* 表头 */}
        <div
          className="grid px-3 py-1.5 text-[10px] text-[color:var(--text-muted)] uppercase border-b border-border bg-muted/20"
          style={{ gridTemplateColumns: '1.4fr 1fr 1fr 1.2fr 1.2fr 0.9fr 1.4fr' }}
        >
          <div>合约 / 方向</div>
          <div className="text-right">数量</div>
          <div className="text-right">入场 / 标记</div>
          <div className="text-right">未实现 PnL</div>
          <div className="text-right">强平价</div>
          <div className="text-right">保证金</div>
          <div className="text-right">操作</div>
        </div>

        {/* 行 */}
        <div style={{ maxHeight, overflowY: 'auto' }}>
          {data.positions.map((p, i) => {
            const sideColor = p.side === 'LONG' ? 'var(--quote-up)' : 'var(--quote-down)';
            const pnlPositive = p.unrealizedPnl >= 0;
            const pnlColor = pnlPositive ? 'var(--quote-up)' : 'var(--quote-down)';
            // 距强平百分比
            const distance =
              p.side === 'LONG'
                ? ((p.markPrice - p.liquidationPrice) / p.markPrice) * 100
                : ((p.liquidationPrice - p.markPrice) / p.markPrice) * 100;
            const dangerous = distance < dangerThreshold;

            return (
              <div
                key={`${p.symbol}-${p.side}-${i}`}
                onClick={() => onRowClick?.(p)}
                className={cn(
                  'grid px-3 py-2 text-xs border-b border-border/50 items-center',
                  onRowClick && 'cursor-pointer hover:bg-muted/40',
                  dangerous && 'bg-[color:var(--quote-down)]/5'
                )}
                style={{ gridTemplateColumns: '1.4fr 1fr 1fr 1.2fr 1.2fr 0.9fr 1.4fr' }}
              >
                {/* 合约 / 方向 */}
                <div className="min-w-0">
                  <div className="font-mono text-[color:var(--foreground)] truncate">{p.symbol}</div>
                  <div className="flex items-center gap-1 mt-0.5">
                    <span
                      className="px-1 text-[9px] rounded font-bold text-white"
                      style={{ background: sideColor }}
                    >
                      {p.side === 'LONG' ? '多' : '空'}
                    </span>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        onAdjustLeverage?.(p);
                      }}
                      className="text-[9px] text-[color:var(--text-muted)] font-mono hover:text-[color:var(--foreground)]"
                    >
                      {p.leverage}x · {p.marginType === 'isolated' ? '逐仓' : '全仓'}
                    </button>
                  </div>
                </div>

                {/* 数量 */}
                <div className="text-right tabular-nums font-mono text-[color:var(--foreground)]">
                  {p.amount.toFixed(4)}
                </div>

                {/* 入场 / 标记 */}
                <div className="text-right text-[color:var(--muted-foreground)]">
                  <div className="tabular-nums font-mono">{p.entryPrice.toFixed(2)}</div>
                  <div className="tabular-nums font-mono text-[10px] text-[color:var(--text-muted)]">
                    {p.markPrice.toFixed(2)}
                  </div>
                </div>

                {/* PnL */}
                <div className="text-right">
                  <div className="tabular-nums font-mono font-semibold" style={{ color: pnlColor }}>
                    {pnlPositive ? '+' : ''}
                    {p.unrealizedPnl.toFixed(2)}
                  </div>
                  <div className="tabular-nums font-mono text-[10px]" style={{ color: pnlColor }}>
                    ({pnlPositive ? '+' : ''}
                    {p.pnlPercent.toFixed(2)}%)
                  </div>
                </div>

                {/* 强平价 */}
                <div className="text-right">
                  <div
                    className="tabular-nums font-mono text-[color:var(--alert-warn)]"
                  >
                    {p.liquidationPrice.toFixed(2)}
                  </div>
                  <div
                    className="tabular-nums font-mono text-[10px]"
                    style={{
                      color: dangerous ? 'var(--quote-down)' : 'var(--text-muted)',
                    }}
                  >
                    {dangerous ? '⚠ ' : ''}
                    {distance.toFixed(2)}%
                  </div>
                </div>

                {/* 保证金 */}
                <div className="text-right tabular-nums font-mono text-[color:var(--muted-foreground)]">
                  {p.margin.toFixed(2)}
                </div>

                {/* 操作 */}
                <div className="flex justify-end gap-1" onClick={(e) => e.stopPropagation()}>
                  <button
                    type="button"
                    onClick={() => onAdjustTpSl?.(p)}
                    className="px-1.5 py-0.5 text-[10px] rounded border border-border hover:bg-muted"
                  >
                    TP/SL
                  </button>
                  <button
                    type="button"
                    onClick={() => onReverse?.(p)}
                    className="px-1.5 py-0.5 text-[10px] rounded text-white"
                    style={{
                      background: p.side === 'LONG' ? 'var(--quote-down)' : 'var(--quote-up)',
                    }}
                  >
                    反手
                  </button>
                  <button
                    type="button"
                    onClick={() => onClose?.(p)}
                    className="px-1.5 py-0.5 text-[10px] rounded text-white"
                    style={{ background: sideColor }}
                  >
                    平仓
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }
);

OPositionList.displayName = 'OPositionList';
