/**
 * OLogsViewer — 容器 / 进程日志查看器。
 *
 * 功能:
 *   - ANSI color 支持(转义序列 → CSS span)
 *   - 自动滚底 + 用户向上滚动时自动暂停
 *   - 搜索(关键字过滤 / 行号跳转)
 *   - 行号 gutter
 *   - 最大行数限制(超出从头丢弃)
 *
 * 数据契约:`lines: string[]`(每行可含 ANSI 转义)
 *
 * 设计:接收 lines 数组(纯字符串),Page 自己拉 logs(WS / SSE / 轮询)。不内置 fetch。
 */
import { forwardRef, useCallback, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OLogsViewerProps extends Omit<OBlockBaseProps, 'variant'> {
  lines: string[];
  ansiColor?: boolean;
  autoScrollToBottom?: boolean;
  searchable?: boolean;
  showLineNumbers?: boolean;
  maxLines?: number;
  height?: number | string;
  onPauseChange?: (paused: boolean) => void;
}

// ANSI 颜色码 → CSS color
// #4: OLogsViewer 是 DOM 组件,CSS var() 原生可读主题变量 —— 无需 getHeliosChartColors()(那是给
// canvas/WebGL 的)。这里让 ANSI 色跟随主题的正确做法是:回退链改为"显式 --ansi-* → 语义/图表 token → 裸 hex"。
// 这样未定义 --ansi-* 的主题也能让日志色跟随 --destructive/--success/--chart-* 等,且明暗(bright)用 color-mix 提亮保留区分。
const ANSI_FG: Record<string, string> = {
  '30': 'var(--ansi-black, var(--background, #000))',
  '31': 'var(--ansi-red, var(--destructive, #ef4444))',
  '32': 'var(--ansi-green, var(--success, #10b981))',
  '33': 'var(--ansi-yellow, var(--warning, #f59e0b))',
  '34': 'var(--ansi-blue, var(--info, #3b82f6))',
  '35': 'var(--ansi-magenta, var(--chart-5, #a855f7))',
  '36': 'var(--ansi-cyan, var(--chart-1, #06b6d4))',
  '37': 'var(--ansi-white, var(--foreground, #e5e7eb))',
  '90': 'var(--ansi-gray, var(--muted-foreground, #6b7280))',
  '91': 'var(--ansi-bright-red, color-mix(in oklch, var(--destructive, #f87171) 78%, white))',
  '92': 'var(--ansi-bright-green, color-mix(in oklch, var(--success, #34d399) 78%, white))',
  '93': 'var(--ansi-bright-yellow, color-mix(in oklch, var(--warning, #fbbf24) 78%, white))',
  '94': 'var(--ansi-bright-blue, color-mix(in oklch, var(--info, #60a5fa) 78%, white))',
  '95': 'var(--ansi-bright-magenta, color-mix(in oklch, var(--chart-5, #c084fc) 78%, white))',
  '96': 'var(--ansi-bright-cyan, color-mix(in oklch, var(--chart-1, #22d3ee) 78%, white))',
};

/** 解析单行 ANSI → 段数组 */
function parseAnsi(line: string): { text: string; color?: string; bold?: boolean }[] {
  // eslint-disable-next-line no-control-regex
  const re = /\u001b\[([\d;]+)m/g;
  const segments: { text: string; color?: string; bold?: boolean }[] = [];
  let lastIndex = 0;
  let currentColor: string | undefined;
  let currentBold = false;
  let m: RegExpExecArray | null;
  while ((m = re.exec(line)) !== null) {
    if (m.index > lastIndex) {
      segments.push({ text: line.slice(lastIndex, m.index), color: currentColor, bold: currentBold });
    }
    const codes = m[1]!.split(';');
    for (const code of codes) {
      if (code === '0') {
        currentColor = undefined;
        currentBold = false;
      } else if (code === '1') {
        currentBold = true;
      } else if (ANSI_FG[code]) {
        currentColor = ANSI_FG[code];
      }
    }
    lastIndex = re.lastIndex;
  }
  if (lastIndex < line.length) {
    segments.push({ text: line.slice(lastIndex), color: currentColor, bold: currentBold });
  }
  if (segments.length === 0) segments.push({ text: line });
  return segments;
}

function stripAnsi(line: string): string {
  // eslint-disable-next-line no-control-regex
  return line.replace(/\u001b\[[\d;]+m/g, '');
}

export const OLogsViewer = forwardRef<HTMLDivElement, OLogsViewerProps>(function OLogsViewer(
  {
    lines,
    ansiColor = true,
    autoScrollToBottom = true,
    searchable = true,
    showLineNumbers = true,
    maxLines = 1000,
    height = 400,
    onPauseChange,
    className,
    theme: _t,
    size: _s,
  },
  ref
) {
  const scrollRef = useRef<HTMLDivElement | null>(null);
  const [paused, setPaused] = useState(false);
  const [search, setSearch] = useState('');

  // 截断到 maxLines
  const displayLines = useMemo(() => {
    if (lines.length <= maxLines) return lines;
    return lines.slice(lines.length - maxLines);
  }, [lines, maxLines]);

  // 搜索过滤
  const filtered = useMemo(() => {
    if (!search) return displayLines.map((line, i) => ({ line, idx: i }));
    const lower = search.toLowerCase();
    return displayLines
      .map((line, i) => ({ line, idx: i }))
      .filter(({ line }) => stripAnsi(line).toLowerCase().includes(lower));
  }, [displayLines, search]);

  // 自动滚底(useLayoutEffect 保证 DOM 已更新,真实浏览器 + jsdom 都生效)
  useLayoutEffect(() => {
    if (!autoScrollToBottom || paused) return;
    const el = scrollRef.current;
    if (!el) return;
    el.scrollTop = el.scrollHeight;
  }, [filtered.length, autoScrollToBottom, paused]);

  // 用户滚动时若离底超过 50px,自动暂停
  const handleScroll = useCallback(() => {
    if (!autoScrollToBottom) return;
    const el = scrollRef.current;
    if (!el) return;
    const distFromBottom = el.scrollHeight - el.scrollTop - el.clientHeight;
    const shouldPause = distFromBottom > 50;
    setPaused((prev) => {
      if (prev !== shouldPause) {
        onPauseChange?.(shouldPause);
        return shouldPause;
      }
      return prev;
    });
  }, [autoScrollToBottom, onPauseChange]);

  const handleResume = () => {
    setPaused(false);
    onPauseChange?.(false);
    const el = scrollRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  };

  return (
    <div
      ref={ref}
      className={cn(
        'flex flex-col rounded border border-border bg-card text-card-foreground @container',
        className
      )}
      style={{ fontFamily: 'var(--font-mono, ui-monospace)', height }}
      role="region"
      aria-label="Logs viewer"
    >
      {/* toolbar */}
      <div className="flex items-center gap-2 px-2 py-1 border-b border-border text-xs">
        <span className="text-muted-foreground">
          {filtered.length} / {displayLines.length} 行
        </span>
        {searchable && (
          <input
            type="text"
            placeholder="搜索..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            aria-label="搜索日志"
            className="flex-1 px-2 py-0.5 bg-transparent border border-border rounded text-xs focus:outline-none focus-visible:ring-2 focus-visible:ring-ring focus:ring-1 focus:ring-ring"
          />
        )}
        {paused && (
          <button
            type="button"
            onClick={handleResume}
            className="px-2 py-0.5 text-xs rounded bg-warning/20 text-warning hover:opacity-80"
          >
            ▼ 恢复滚动
          </button>
        )}
      </div>

      {/* lines */}
      <div
        ref={scrollRef}
        onScroll={handleScroll}
        className="flex-1 overflow-auto px-2 py-1 text-xs"
        style={{ fontFamily: 'var(--font-mono, ui-monospace)' }}
      >
        {filtered.length === 0 ? (
          <div className="text-muted-foreground text-center py-4">
            {search ? '无匹配' : '暂无日志'}
          </div>
        ) : (
          <table className="w-full border-collapse" role="presentation">
            <tbody>
              {filtered.map(({ line, idx }) => {
                const segs = ansiColor ? parseAnsi(line) : [{ text: stripAnsi(line) }];
                return (
                  <tr key={idx} className="o-cv-row-sm">
                    {showLineNumbers && (
                      <td
                        className="text-muted-foreground text-right pr-2 select-none"
                        style={{ minWidth: 40 }}
                      >
                        {idx + 1}
                      </td>
                    )}
                    <td className="whitespace-pre-wrap break-all">
                      {segs.map((s, j) => (
                        <span
                          key={j}
                          style={{
                            color: s.color,
                            fontWeight: s.bold ? 600 : 400,
                          }}
                        >
                          {s.text}
                        </span>
                      ))}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
});

OLogsViewer.displayName = 'OLogsViewer';

// 暴露给测试 / 外部用
export { parseAnsi, stripAnsi };
