/**
 * OBlockedCard — 功能阻塞 / Coming Soon 卡片
 *
 * 来源:Tide R1 §5(Sprint 2.5 已自写)+ Stratum / Helivex FeatureFlag 配套
 *
 * 设计参考(横向对标):
 *   - Nielsen Norman Group "Inactive Features" 研究 — 4 信号原则:
 *     (1) 为什么不可用     → reason
 *     (2) 何时可用         → estimatedAvailability
 *     (3) 替代方案         → alternative      ← 我们原 v1.3 spec 缺
 *     (4) 通知我           → onNotifyMe       ← 我们原 v1.3 spec 缺
 *   - Microsoft Fluent UI 2024 Spec — Blocked vs Empty 明确区分
 *   - GitHub Primer Banner — dismiss + action 模式
 *
 * 配套使用(跟 FeatureFlag 模式直接对接):
 *   ```tsx
 *   import {
 *     OBlockedCard,
 *     isStratumFeatureEnabled,
 *     StratumFeature,
 *   } from '@helios/blocks';
 *
 *   {!isStratumFeatureEnabled(StratumFeature.TTS) && (
 *     <OBlockedCard
 *       title="语音朗读"
 *       reason="v1.0 暂未实施 TTS"
 *       estimatedAvailability="v1.1(预计 2026-Q4)"
 *       alternative="可用浏览器自带的朗读功能"
 *       onNotifyMe={() => subscribeFeatureUpdate('tts')}
 *     />
 *   )}
 *   ```
 *
 * a11y:
 *   - role="status" + aria-live="polite"(状态变化通知,但不打断)
 *   - 4 信号区块各自 heading 层级(语义化结构)
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import { OButton } from '../OButton';
import type { OBlockBaseProps } from '../../lib/types';

// ============================================================
// 视觉变体
// ============================================================

const cardVariants = cva(
  'rounded-md border p-4 space-y-3',
  {
    variants: {
      tone: {
        soft: 'bg-muted/40 border-border text-foreground',
        info: 'bg-info/10 border-info/30 text-foreground',
        warning: 'bg-warning/10 border-warning/30 text-foreground',
      },
    },
    defaultVariants: {
      tone: 'soft',
    },
  }
);

type CardVariantProps = VariantProps<typeof cardVariants>;

// ============================================================
// Props
// ============================================================

export interface OBlockedCardProps
  extends Omit<OBlockBaseProps, 'variant' | 'size'>,
    CardVariantProps {
  /** 阻塞功能名(NN 信号 0 — 主标题)。 */
  title: string;

  /**
   * 为什么不可用(NN 信号 1)。
   * 例:"v1.0 暂未实施 TTS" / "等 Sprint 7 策略与回测完工"
   */
  reason: string;

  /**
   * 预计可用时间(NN 信号 2)。
   * 例:"v1.1(预计 2026-Q4)" / "Sprint 7(2026-06)"
   */
  estimatedAvailability?: string;

  /**
   * 替代方案(NN 信号 3)。
   * 例:"可用浏览器自带的朗读功能" / "可手动从 OKX 看 K 线"
   * 给用户**可以做什么**,而不只是"功能没了"。
   */
  alternative?: string;

  /**
   * "通知我"回调(NN 信号 4)。
   * 用户主动订阅 feature 启用通知。
   * 不传 = 不显示按钮。
   */
  onNotifyMe?: () => void;

  /**
   * "通知我"按钮文本(默认"功能上线后通知我")。
   */
  notifyMeLabel?: string;

  /**
   * 解除阻塞动作(可选,跟 onNotifyMe 互斥 — 二选一)。
   * 例:跳转到 settings 启用 / 文档链接。
   */
  unblockAction?: {
    label: string;
    onClick?: () => void;
    href?: string;
  };

  /**
   * 图标(可选,默认 lock 图标)。
   */
  icon?: ReactNode;
}

// ============================================================
// 默认 lock 图标
// ============================================================

function LockIcon() {
  return (
    <svg
      className="w-5 h-5 text-muted-foreground flex-shrink-0"
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
    >
      <rect
        x="5"
        y="11"
        width="14"
        height="10"
        rx="2"
        stroke="currentColor"
        strokeWidth="1.5"
      />
      <path
        d="M8 11V7a4 4 0 018 0v4"
        stroke="currentColor"
        strokeWidth="1.5"
      />
    </svg>
  );
}

// ============================================================
// 主组件
// ============================================================

export const OBlockedCard = forwardRef<HTMLDivElement, OBlockedCardProps>(
  function OBlockedCard(
    {
      title,
      reason,
      estimatedAvailability,
      alternative,
      onNotifyMe,
      notifyMeLabel = '功能上线后通知我',
      unblockAction,
      icon,
      tone = 'soft',
      className,
      theme: _t,
    },
    ref
  ) {
    return (
      <div
        ref={ref}
        role="status"
        aria-live="polite"
        className={cn(cardVariants({ tone }), className)}
      >
        {/* 标题区:icon + title */}
        <div className="flex items-start gap-3">
          {icon ?? <LockIcon />}
          <div className="flex-1 min-w-0">
            <h4 className="text-sm font-medium text-foreground">{title}</h4>
            {/* NN 信号 1: 为什么 */}
            <p className="text-sm text-muted-foreground mt-1">{reason}</p>
          </div>
        </div>

        {/* NN 信号 2: 何时可用 */}
        {estimatedAvailability && (
          <div className="flex items-start gap-2 text-xs">
            <span
              className="inline-flex items-center gap-1 text-muted-foreground"
              aria-label="预计可用时间"
            >
              <svg
                className="w-3.5 h-3.5"
                viewBox="0 0 16 16"
                fill="none"
                aria-hidden="true"
              >
                <circle
                  cx="8"
                  cy="8"
                  r="6"
                  stroke="currentColor"
                  strokeWidth="1.2"
                />
                <path
                  d="M8 5v3l2 2"
                  stroke="currentColor"
                  strokeWidth="1.2"
                  strokeLinecap="round"
                />
              </svg>
              <span>预计 {estimatedAvailability}</span>
            </span>
          </div>
        )}

        {/* NN 信号 3: 替代方案 */}
        {alternative && (
          <div className="text-xs text-foreground/80 border-l-2 border-primary/30 pl-3 py-1">
            <span className="text-muted-foreground">替代方案:</span>{' '}
            {alternative}
          </div>
        )}

        {/* NN 信号 4: 通知我 / unblock action */}
        {(onNotifyMe || unblockAction) && (
          <div className="flex flex-wrap gap-2 pt-1">
            {onNotifyMe && (
              <OButton
                type="button"
                variant="outline"
                size="sm"
                onClick={onNotifyMe}
              >
                <svg
                  className="w-3.5 h-3.5"
                  viewBox="0 0 16 16"
                  fill="none"
                  aria-hidden="true"
                >
                  <path
                    d="M3 6a5 5 0 0110 0v3l1 2H2l1-2V6zm3 7a2 2 0 004 0"
                    stroke="currentColor"
                    strokeWidth="1.2"
                    strokeLinejoin="round"
                  />
                </svg>
                <span>{notifyMeLabel}</span>
              </OButton>
            )}
            {unblockAction &&
              (unblockAction.href ? (
                <a
                  href={unblockAction.href}
                  className={cn(
                    'inline-flex items-center px-3 py-1.5 text-xs rounded-md',
                    'border border-primary bg-primary text-primary-foreground',
                    'hover:bg-primary/90 transition-colors',
                    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring'
                  )}
                >
                  {unblockAction.label}
                </a>
              ) : (
                <OButton
                  type="button"
                  variant="primary"
                  size="sm"
                  onClick={unblockAction.onClick}
                >
                  {unblockAction.label}
                </OButton>
              ))}
          </div>
        )}
      </div>
    );
  }
);

OBlockedCard.displayName = 'OBlockedCard';
