/**
 * OFormField - 表单字段包装。
 *
 * 提供标签 + 必填标记 + 描述 + 错误信息 + 帮助文本 的标准布局。
 * 不直接装输入控件,通过 children 接收任意 input/select/textarea。
 *
 * @example
 * <OFormField label="Email" required error={errors.email} description="We never share">
 *   <input type="email" {...register('email')} />
 * </OFormField>
 */
'use client';

import {
  forwardRef,
  useId,
  cloneElement,
  isValidElement,
  type ReactNode,
  type ReactElement,
} from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OFormFieldProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  label?: ReactNode;
  /**
   * label 关联的 input id。
   * - 如果你的 children 是单个 input 且自己有 id,传该 id 让 label htmlFor 关联
   * - 不传则用内部 useId(label 关联到外层 div,a11y 工具可能会警告 input 无 label)
   */
  htmlFor?: string;
  /** 必填标记。 */
  required?: boolean;
  /** 字段描述(标签下方,输入框上方)。 */
  description?: ReactNode;
  /** 错误信息(高于 description 优先级)。 */
  error?: string | null;
  /** 帮助文本(输入框下方,non-error 状态)。 */
  help?: ReactNode;
  /** 字段方向。 */
  orientation?: 'vertical' | 'horizontal';
  children: ReactNode;
}

export const OFormField = forwardRef<HTMLDivElement, OFormFieldProps>(function OFormField(
  {
    label,
    htmlFor,
    required = false,
    description,
    error,
    help,
    orientation = 'vertical',
    className,
    children,
    theme: _t,
  },
  ref
) {
  const autoId = useId();
  const id = htmlFor ?? autoId;
  const descriptionId = description ? `${id}-desc` : undefined;
  const errorId = error ? `${id}-err` : undefined;

  // a11y 接线:把 id / aria-* 注入单个子控件,让屏幕阅读器能把标签、描述、错误
  // 关联到输入框,并在校验失败时播报。若子元素自带这些属性则以子元素为准(不覆盖)。
  // aria-describedby 只引用"实际渲染出来"的节点 id,避免悬空引用(axe 会告警):
  //   • 描述仅在 !error 时渲染 → 有 error 时不引用 descriptionId
  //   • 错误仅在 error 时渲染
  const describedBy =
    [description && !error ? descriptionId : null, error ? errorId : null]
      .filter(Boolean)
      .join(' ') || undefined;
  const wiredChildren =
    isValidElement(children)
      ? cloneElement(children as ReactElement<Record<string, unknown>>, {
          id: (children as ReactElement<Record<string, unknown>>).props.id ?? id,
          'aria-invalid':
            (children as ReactElement<Record<string, unknown>>).props['aria-invalid'] ??
            (error ? true : undefined),
          'aria-required':
            (children as ReactElement<Record<string, unknown>>).props['aria-required'] ??
            (required || undefined),
          'aria-errormessage':
            (children as ReactElement<Record<string, unknown>>).props['aria-errormessage'] ??
            (errorId || undefined),
          'aria-describedby':
            (children as ReactElement<Record<string, unknown>>).props['aria-describedby'] ??
            describedBy,
        })
      : children;

  return (
    <div
      ref={ref}
      className={cn(
        orientation === 'horizontal' ? 'grid grid-cols-[12rem_1fr] items-start gap-4' : 'space-y-1.5',
        className
      )}
    >
      {label ? (
        <label htmlFor={id} className="text-sm font-medium leading-none flex items-center gap-1 @container">
          {label}
          {required ? (
            <span className="text-destructive" role="img" aria-label="required">
              *
            </span>
          ) : null}
        </label>
      ) : null}

      <div className="space-y-1.5 min-w-0">
        {description && !error ? (
          <p id={descriptionId} className="text-xs text-muted-foreground">
            {description}
          </p>
        ) : null}

        {/* a11y: 通过 cloneElement 注入 id / aria-invalid / aria-describedby / aria-errormessage,
            使标签·描述·错误与控件关联,校验失败时 SR 可播报。子元素自带同名属性时以其为准。 */}
        <div>{wiredChildren}</div>

        {error ? (
          <p id={errorId} className="text-xs text-destructive" role="alert" aria-live="assertive">
            {error}
          </p>
        ) : help ? (
          <p className="text-xs text-muted-foreground">{help}</p>
        ) : null}
      </div>
    </div>
  );
});

OFormField.displayName = 'OFormField';
