/**
 * OPricingTable - 价格对比表。
 *
 * 支持月/年切换 (toggle),亮点 highlight tier,CTA 按钮。
 * billing 状态受控:由 Page 管 (因可能跟 URL query 同步)。
 */
'use client';

import { forwardRef, type ReactNode } from 'react';
import { motion } from 'motion/react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

export interface OPricingTier {
  id: string;
  name: string;
  /** 月单价 (数字),或 'Custom' / 'Free' 字符串。 */
  monthly: number | string;
  /** 年单价 (按月计算)。可不填,用 monthly * 10 默认。 */
  yearly?: number | string;
  /** 价格单位 (默认 'USD/mo')。 */
  unit?: string;
  /** 描述。 */
  description?: string;
  /** 特性列表 (✓ 显示)。 */
  features: ReactNode[];
  /** CTA。 */
  cta: { label: string; href?: string; onClick?: () => void };
  /** 高亮 (推荐档位)。 */
  highlight?: boolean;
  /** 高亮标签文字。 */
  highlightLabel?: string;
}

export interface OPricingTableProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  tiers: OPricingTier[];
  /** 当前计费周期。 */
  billing?: 'monthly' | 'yearly';
  onBillingChange?: (billing: 'monthly' | 'yearly') => void;
  /** 年付折扣文字 (e.g. "Save 20%")。 */
  yearlyHint?: string;
  /** 标题。 */
  heading?: string;
  subheading?: string;
}

function CheckIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" aria-hidden="true">
      <polyline points="20 6 9 17 4 12" />
    </svg>
  );
}

function formatPrice(p: number | string, unit: string): { display: string; unit: string } {
  if (typeof p === 'number') {
    return { display: `$${p}`, unit };
  }
  return { display: p, unit: '' };
}

export const OPricingTable = forwardRef<HTMLElement, OPricingTableProps>(function OPricingTable(
  {
    tiers,
    billing = 'monthly',
    onBillingChange,
    yearlyHint,
    heading,
    subheading,
    className,
    theme: _t,
  },
  ref
) {
  const reduced = useReducedMotion();

  return (
    <section ref={ref} className={cn('w-full @container', className)}>
      {heading || subheading ? (
        <div className="max-w-3xl mx-auto text-center mb-8">
          {heading ? <h2 className="text-3xl md:text-4xl font-bold tracking-tight">{heading}</h2> : null}
          {subheading ? <p className="text-lg text-muted-foreground mt-3">{subheading}</p> : null}
        </div>
      ) : null}

      {onBillingChange ? (
        <div className="flex items-center justify-center gap-3 mb-8">
          <div className="inline-flex rounded-full border border-border bg-card p-1">
            <button
              onClick={() => onBillingChange('monthly')}
              className={cn(
                'px-4 py-1.5 text-sm rounded-full transition-colors',
                billing === 'monthly'
                  ? 'bg-primary text-primary-foreground'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Monthly
            </button>
            <button
              onClick={() => onBillingChange('yearly')}
              className={cn(
                'px-4 py-1.5 text-sm rounded-full transition-colors inline-flex items-center gap-2',
                billing === 'yearly'
                  ? 'bg-primary text-primary-foreground'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Yearly
              {yearlyHint ? (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-success/20 text-success">
                  {yearlyHint}
                </span>
              ) : null}
            </button>
          </div>
        </div>
      ) : null}

      <div
        className={cn(
          'grid grid-cols-1 @[640px]:grid-cols-2 @[1024px]:grid-cols-3 gap-6 max-w-6xl mx-auto'
        )}
      >
        {tiers.map((tier, i) => {
          const raw = billing === 'yearly'
            ? tier.yearly ?? (typeof tier.monthly === 'number' ? tier.monthly * 10 : tier.monthly)
            : tier.monthly;
          const { display, unit } = formatPrice(raw, tier.unit ?? 'USD/mo');
          return (
            <motion.div
              key={tier.id}
              initial={reduced ? false : { opacity: 0, y: 20 }}
              whileInView={reduced ? undefined : { opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.4, delay: reduced ? 0 : i * 0.1 }}
              className={cn(
                'relative flex flex-col gap-4 p-6 rounded-lg border bg-card transition-all',
                tier.highlight
                  ? 'border-primary shadow-[0_0_32px_color-mix(in_oklch,var(--primary)_20%,transparent)] @[640px]:-translate-y-2'
                  : 'border-border'
              )}
            >
              {tier.highlight ? (
                <span className="absolute -top-3 left-1/2 -translate-x-1/2 px-3 py-0.5 rounded-full bg-primary text-primary-foreground text-xs font-medium">
                  {tier.highlightLabel ?? 'Most popular'}
                </span>
              ) : null}
              <div>
                <h3 className="text-lg font-bold tracking-[-0.01em]">{tier.name}</h3>
                {tier.description ? (
                  <p className="text-sm text-muted-foreground mt-1">{tier.description}</p>
                ) : null}
              </div>
              <div className="flex items-baseline gap-1">
                <span className="text-4xl font-extrabold tracking-[-0.03em] tabular-nums">{display}</span>
                {unit ? <span className="text-sm text-muted-foreground">/{unit.replace('USD/', '')}</span> : null}
              </div>
              {tier.cta.href ? (
                <a
                  href={tier.cta.href}
                  className={cn(
                    'w-full inline-flex items-center justify-center px-4 py-2 rounded-md font-medium text-sm transition-opacity',
                    tier.highlight
                      ? 'bg-primary text-primary-foreground hover:opacity-90'
                      : 'bg-card border border-border hover:bg-muted'
                  )}
                >
                  {tier.cta.label}
                </a>
              ) : (
                <button
                  onClick={tier.cta.onClick}
                  className={cn(
                    'w-full px-4 py-2 rounded-md font-medium text-sm transition-opacity',
                    tier.highlight
                      ? 'bg-primary text-primary-foreground hover:opacity-90'
                      : 'bg-card border border-border hover:bg-muted'
                  )}
                >
                  {tier.cta.label}
                </button>
              )}
              <ul className="space-y-2 mt-2">
                {tier.features.map((f, idx) => (
                  <li key={idx} className="flex items-start gap-2 text-sm">
                    <span
                      className={cn(
                        'shrink-0 mt-0.5',
                        tier.highlight ? 'text-primary' : 'text-success'
                      )}
                    >
                      <CheckIcon />
                    </span>
                    <span className="text-foreground/90">{f}</span>
                  </li>
                ))}
              </ul>
            </motion.div>
          );
        })}
      </div>
    </section>
  );
});

OPricingTable.displayName = 'OPricingTable';
