/**
 * OBacklinkPanel — wikilink 反向引用面板
 *
 * 消费 Note.wikilinks 数组(API §1.4)+ 反向计算引用关系。
 *
 * 设计:
 *   - 当前 substrate / note 被哪些 note 引用(backlinks)
 *   - 列表显示引用方 note(title + excerpt)
 *   - 点击跳转到引用方 note
 *   - 数据来源:消费方传入 backlinks(已经 query 好的反向引用列表)
 *
 * 反向引用计算由消费方完成(SQL: SELECT * FROM note WHERE wikilinks LIKE '%[[target]]%')。
 * Block 只负责渲染。
 */
import { forwardRef, useCallback, type KeyboardEvent } from 'react';
import { cn } from '../../lib/cn';
import type { Note } from '../../types/stratum';
import type { OBlockBaseProps } from '../../lib/types';

export interface BacklinkItem {
  /** 引用方 note。 */
  note: Note;
  /** 引用上下文(可选,引用前后片段)。 */
  excerpt?: string;
  /** 引用 wikilink 文本(可选,"[[target]]" 形式)。 */
  link_text?: string;
}

export interface OBacklinkPanelProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 反向引用项。 */
  backlinks: BacklinkItem[];
  /** 当前 target(只显示标题用)。 */
  targetTitle?: string;
  /** 点击 backlink。 */
  onSelect?: (item: BacklinkItem) => void;
  /** 空状态文案。 */
  emptyText?: string;
}

export const OBacklinkPanel = forwardRef<HTMLDivElement, OBacklinkPanelProps>(
  function OBacklinkPanel(
    {
      backlinks,
      targetTitle,
      onSelect,
      emptyText = '暂无反向引用',
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const handleKey = useCallback(
      (e: KeyboardEvent<HTMLButtonElement>, item: BacklinkItem) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onSelect?.(item);
        }
      },
      [onSelect]
    );

    return (
      <aside ref={ref} className={cn('flex flex-col gap-2 w-full', className)}>
        <header className="flex items-center gap-2">
          <span aria-hidden="true">🔗</span>
          <h3 className="text-sm font-bold text-[color:var(--foreground)] tracking-[-0.01em]">
            反向引用
          </h3>
          <span className="text-xs text-[color:var(--text-muted)] font-mono">
            ({backlinks.length})
          </span>
          {targetTitle && (
            <span className="text-xs text-[color:var(--text-muted)] truncate">
              → {targetTitle}
            </span>
          )}
        </header>

        {backlinks.length === 0 ? (
          <div
            className={cn(
              'px-3 py-6 text-center text-xs text-[color:var(--text-muted)] @container',
              'border border-dashed border-border rounded-md'
            )}
          >
            {emptyText}
          </div>
        ) : (
          <ul
            className="flex flex-col gap-1.5 list-none p-0 m-0"
            aria-label={`反向引用 ${backlinks.length} 条`}
          >
            {backlinks.map((item) => (
              <li key={item.note.id}>
                <button
                  type="button"
                  onClick={() => onSelect?.(item)}
                  onKeyDown={(e) => handleKey(e, item)}
                  className={cn(
                    'flex flex-col gap-1 px-3 py-2 rounded-md text-left w-full',
                    'bg-card hover:bg-muted/30',
                    'border border-border transition-colors',
                    'cursor-pointer',
                    'focus:outline-none focus-visible:ring-2 focus-visible:ring-ring'
                  )}
                >
                  <div className="flex items-center gap-2">
                    <span aria-hidden="true">📝</span>
                    <span className="font-medium text-sm text-[color:var(--foreground)] truncate flex-1">
                      {item.note.title || item.note.id.slice(0, 8)}
                    </span>
                    <span className="text-[10px] text-[color:var(--text-muted)] font-mono">
                      {new Date(item.note.created_at).toLocaleDateString()}
                    </span>
                  </div>
                  {item.excerpt && (
                    <div className="text-xs text-[color:var(--text-muted)] line-clamp-2 leading-relaxed">
                      {item.excerpt}
                    </div>
                  )}
                  {item.link_text && (
                    <div className="text-[10px] font-mono text-primary">
                      {item.link_text}
                    </div>
                  )}
                </button>
              </li>
            ))}
          </ul>
        )}
      </aside>
    );
  }
);

OBacklinkPanel.displayName = 'OBacklinkPanel';
