/**
 * OIndicatorCard — 技术指标配置卡(量化配置通用)。
 *
 * toggle(enabled)+ 参数控件(slider)+ role 标签。
 * 6 个一组用于策略配置。跨项目:量化系统配置面板通用。
 *
 * v2.15:复用原子层 — 容器=OCard, 开关=OSwitch, 参数=OSlider(消除手写元素)。
 */
'use client';
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';
import { OCard } from '../OCard';
import { OSwitch } from '../OSwitch';
import { OSlider } from '../OSlider';

export interface IndicatorParam {
  key: string;
  label: string;
  value: number;
  min: number;
  max: number;
  step?: number;
}

export interface OIndicatorCardProps extends Omit<OBlockBaseProps, 'variant'> {
  name: string;
  enabled: boolean;
  /** 指标在 signal 中的角色,如 primary_direction / chop_filter */
  role?: string;
  params: IndicatorParam[];
  onToggle?: (enabled: boolean) => void;
  onParamChange?: (key: string, value: number) => void;
}

export const OIndicatorCard = forwardRef<HTMLDivElement, OIndicatorCardProps>(
  function OIndicatorCard(
    { name, enabled, role, params, onToggle, onParamChange, className, ...rest },
    ref
  ) {
    return (
      <OCard
        ref={ref as any}
        as="div"
        container
        elevation="flat"
        className={cn(
          'p-4 flex flex-col gap-3',
          !enabled && 'opacity-60',
          className
        )}
        {...rest}
      >
        {/* 头部:名字 + toggle(OSwitch) */}
        <div className="flex items-center justify-between gap-2">
          <div className="flex flex-col gap-0.5">
            <span className="text-sm font-bold tracking-[-0.01em]">{name}</span>
            {role && (
              <span className="text-[10px] uppercase tracking-[0.04em] font-semibold text-muted-foreground">
                {role}
              </span>
            )}
          </div>
          <OSwitch
            checked={enabled}
            onChange={e => onToggle?.(e.target.checked)}
            aria-label={`${name} toggle`}
          />
        </div>

        {/* 参数 sliders(OSlider) */}
        {enabled && params.length > 0 && (
          <div className="flex flex-col gap-2.5">
            {params.map(p => (
              <div key={p.key} className="flex flex-col gap-1">
                <div className="flex items-center justify-between text-xs">
                  <span className="text-muted-foreground">{p.label}</span>
                  <span className="font-semibold tabular-nums">{p.value}</span>
                </div>
                <OSlider
                  min={p.min} max={p.max} step={p.step ?? 1}
                  value={[p.value]}
                  onValueChange={(v) => onParamChange?.(p.key, v[0])}
                />
              </div>
            ))}
          </div>
        )}
      </OCard>
    );
  }
);

OIndicatorCard.displayName = 'OIndicatorCard';
