/**
 * OToast - 顶部/角落弹出通知。
 *
 * 提供三件套:
 *   1. OToastProvider — 挂在 App 根 (一次,管渲染容器)
 *   2. useToast()      — 任意组件调用 toast({ ... })
 *   3. (内部)         — 队列管理 + 自动消失
 *
 * @example
 * // app/layout.tsx:
 * <OToastProvider position="bottom-right">
 *   <App />
 * </OToastProvider>
 *
 * // 任意组件:
 * const { toast } = useToast();
 * toast({ kind: 'success', title: 'Saved', description: 'Your changes have been saved.' });
 */
'use client';

import { motion, AnimatePresence } from 'motion/react';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';

export type ToastKind = 'success' | 'error' | 'warning' | 'info' | 'default';

export interface ToastItem {
  id: string;
  kind?: ToastKind;
  title: string;
  description?: string;
  /** 自动消失毫秒,0 = 不自动消失。默认 4000。 */
  duration?: number;
  /** 操作按钮。 */
  action?: { label: string; onClick: () => void };
}

export type ToastPosition =
  | 'top-left'
  | 'top-center'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-center'
  | 'bottom-right';

interface ToastContextValue {
  toast: (item: Omit<ToastItem, 'id'> & { id?: string }) => string;
  dismiss: (id: string) => void;
  clear: () => void;
}

const ToastContext = createContext<ToastContextValue | null>(null);

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (ctx) return ctx;
  // 在 Provider 外调用时给一个 no-op 实现,避免直接抛错
  if (typeof console !== 'undefined') {
    console.warn('[OToast] useToast called outside OToastProvider; calls are no-op.');
  }
  return { toast: () => '', dismiss: () => {}, clear: () => {} };
}

const POSITION_CLASS: Record<ToastPosition, string> = {
  'top-left': 'top-4 left-4 items-start',
  'top-center': 'top-4 left-1/2 -translate-x-1/2 items-center',
  'top-right': 'top-4 right-4 items-end',
  'bottom-left': 'bottom-4 left-4 items-start',
  'bottom-center': 'bottom-4 left-1/2 -translate-x-1/2 items-center',
  'bottom-right': 'bottom-4 right-4 items-end',
};

const KIND_CLASS: Record<ToastKind, string> = {
  default: 'bg-card border-border text-card-foreground',
  success: 'bg-success/10 border-success/30 text-foreground',
  error: 'bg-destructive/10 border-destructive/30 text-foreground',
  warning: 'bg-warning/10 border-warning/30 text-foreground',
  info: 'bg-info/10 border-info/30 text-foreground',
};

const KIND_DOT: Record<ToastKind, string> = {
  default: 'var(--muted-foreground)',
  success: 'var(--success)',
  error: 'var(--destructive)',
  warning: 'var(--warning)',
  info: 'var(--info)',
};

function nanoid(): string {
  return Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
}

export interface OToastProviderProps {
  position?: ToastPosition;
  /** 最大同时显示数,超出排队。 */
  max?: number;
  /** 默认 duration。 */
  defaultDuration?: number;
  children: ReactNode;
}

export function OToastProvider({
  position = 'bottom-right',
  max = 4,
  defaultDuration = 4000,
  children,
}: OToastProviderProps) {
  const [items, setItems] = useState<ToastItem[]>([]);
  const reduced = useReducedMotion();

  const dismiss = useCallback((id: string) => {
    setItems((prev) => prev.filter((it) => it.id !== id));
  }, []);

  const toast = useCallback(
    (item: Omit<ToastItem, 'id'> & { id?: string }): string => {
      const id = item.id ?? nanoid();
      const next: ToastItem = {
        id,
        kind: item.kind ?? 'default',
        title: item.title,
        description: item.description,
        action: item.action,
        duration: item.duration ?? defaultDuration,
      };
      setItems((prev) => [...prev, next].slice(-max));
      return id;
    },
    [defaultDuration, max]
  );

  const clear = useCallback(() => setItems([]), []);

  // 自动消失
  useEffect(() => {
    const timers: ReturnType<typeof setTimeout>[] = [];
    for (const it of items) {
      if (it.duration && it.duration > 0) {
        const t = setTimeout(() => dismiss(it.id), it.duration);
        timers.push(t);
      }
    }
    return () => timers.forEach(clearTimeout);
  }, [items, dismiss]);

  const ctxValue = useMemo<ToastContextValue>(() => ({ toast, dismiss, clear }), [toast, dismiss, clear]);

  const isBottom = position.startsWith('bottom');
  const slide = isBottom ? { y: 20 } : { y: -20 };

  return (
    <ToastContext.Provider value={ctxValue}>
      {children}
      <div
        aria-live="polite"
        aria-atomic="true"
        className={cn(
          'fixed z-[100] pointer-events-none flex flex-col gap-2 max-w-sm w-full @container',
          POSITION_CLASS[position]
        )}
      >
        <AnimatePresence initial={false}>
          {items.map((it) => (
            <motion.div
              key={it.id}
              layout
              initial={reduced ? false : { opacity: 0, ...slide, scale: 0.95 }}
              animate={reduced ? undefined : { opacity: 1, y: 0, scale: 1 }}
              exit={reduced ? undefined : { opacity: 0, scale: 0.95, transition: { duration: 0.15 } }}
              transition={{ type: 'spring', stiffness: 280, damping: 24 }}
              className={cn(
                'pointer-events-auto border rounded-md shadow-lg p-3 flex items-start gap-3',
                KIND_CLASS[it.kind ?? 'default']
              )}
              role={it.kind === 'error' ? 'alert' : 'status'}
            >
              <span
                className="w-2 h-2 rounded-full mt-1.5 shrink-0"
                style={{ backgroundColor: KIND_DOT[it.kind ?? 'default'] }}
                aria-hidden="true"
              />
              <div className="flex-1 min-w-0">
                <div className="font-medium text-sm">{it.title}</div>
                {it.description ? (
                  <div className="text-xs text-muted-foreground mt-0.5">{it.description}</div>
                ) : null}
                {it.action ? (
                  <button
                    onClick={() => {
                      it.action!.onClick();
                      dismiss(it.id);
                    }}
                    className="text-xs font-medium text-primary hover:underline mt-1.5"
                  >
                    {it.action.label}
                  </button>
                ) : null}
              </div>
              <button
                onClick={() => dismiss(it.id)}
                aria-label="Dismiss"
                className="text-muted-foreground hover:text-foreground transition-colors shrink-0"
              >
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <line x1="18" y1="6" x2="6" y2="18" />
                  <line x1="6" y1="6" x2="18" y2="18" />
                </svg>
              </button>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>
    </ToastContext.Provider>
  );
}

OToastProvider.displayName = 'OToastProvider';
