/**
 * OModalFrame - 弹窗容器。基于 @radix-ui/react-dialog (focus trap + ESC 关闭 + 背景蒙层)。
 *
 * 命名槽位: header / body / footer。
 *
 * @example
 * <OModalFrame
 *   open={open}
 *   onClose={() => setOpen(false)}
 *   header={<h2>Title</h2>}
 *   body={<p>Confirm action?</p>}
 *   footer={<Button onClick={confirm}>OK</Button>}
 * />
 */
'use client';

import * as Dialog from '@radix-ui/react-dialog';
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { FrameSlot, OBlockBaseProps } from '../../lib/types';

const SIZE_CLASS = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-2xl',
  xl: 'max-w-4xl',
  full: 'max-w-[95vw] h-[95vh]',
} as const;

const POSITION_CLASS = {
  center: 'top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2',
  top: 'top-16 left-1/2 -translate-x-1/2',
} as const;

export interface OModalFrameProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  open: boolean;
  onClose: () => void;
  header?: FrameSlot;
  body?: FrameSlot;
  footer?: FrameSlot;
  size?: keyof typeof SIZE_CLASS;
  position?: keyof typeof POSITION_CLASS;
  /** 关闭按钮显示。 */
  showCloseButton?: boolean;
  /** 点背景关闭。 */
  closeOnOverlayClick?: boolean;
  /** ESC 关闭。 */
  closeOnEscape?: boolean;
  /** 可访问性: dialog 标题 (即使不可见也需要)。 */
  ariaLabel?: string;
}

export const OModalFrame = forwardRef<HTMLDivElement, OModalFrameProps>(function OModalFrame(
  {
    open,
    onClose,
    header,
    body,
    footer,
    size = 'md',
    position = 'center',
    showCloseButton = true,
    closeOnOverlayClick = true,
    closeOnEscape = true,
    ariaLabel = 'Dialog',
    className,
    theme: _t,
  },
  ref
) {
  return (
    <Dialog.Root open={open} onOpenChange={(o) => !o && onClose()}>
      <Dialog.Portal>
        <Dialog.Overlay
          className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0"
          onClick={(e) => {
            if (!closeOnOverlayClick) e.preventDefault();
          }}
        />
        <Dialog.Content
          ref={ref}
          aria-label={ariaLabel}
          onEscapeKeyDown={(e) => {
            if (!closeOnEscape) e.preventDefault();
          }}
          onPointerDownOutside={(e) => {
            if (!closeOnOverlayClick) e.preventDefault();
          }}
          className={cn(
            'fixed z-50 w-full bg-card border border-border rounded-lg shadow-lg flex flex-col',
            'data-[state=open]:animate-in data-[state=closed]:animate-out',
            'data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0',
            'data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95',
            'duration-200',
            SIZE_CLASS[size],
            POSITION_CLASS[position],
            className
          )}
        >
          {header ? (
            <header className="flex items-center justify-between px-6 py-4 border-b border-border">
              <div className="flex-1 min-w-0">{header}</div>
              {showCloseButton ? (
                <Dialog.Close
                  className="ml-4 p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                  aria-label="Close"
                >
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <line x1="18" y1="6" x2="6" y2="18" />
                    <line x1="6" y1="6" x2="18" y2="18" />
                  </svg>
                </Dialog.Close>
              ) : null}
            </header>
          ) : null}

          {body ? <div className="px-6 py-4 flex-1 overflow-auto">{body}</div> : null}

          {footer ? (
            <footer className="px-6 py-4 border-t border-border flex items-center justify-end gap-2">
              {footer}
            </footer>
          ) : null}
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
});

OModalFrame.displayName = 'OModalFrame';
