'use client';
import { forwardRef, type ComponentPropsWithoutRef, type ElementRef } from 'react';
import * as SliderPrimitive from '@radix-ui/react-slider';
import { cn } from '../../lib/cn';
import { sliderTrackRecipe, sliderRangeRecipe, sliderThumbRecipe } from '../../recipes';

export const OSlider = forwardRef<
  ElementRef<typeof SliderPrimitive.Root>,
  ComponentPropsWithoutRef<typeof SliderPrimitive.Root>
>(function OSlider({ className, value, defaultValue, ...props }, ref) {
  const count = (value ?? defaultValue ?? [0]).length;
  return (
    <SliderPrimitive.Root
      ref={ref}
      className={cn('relative flex w-full touch-none select-none items-center', className)}
      value={value} defaultValue={defaultValue} {...props}
    >
      <SliderPrimitive.Track className={sliderTrackRecipe()}>
        <SliderPrimitive.Range className={sliderRangeRecipe()} />
      </SliderPrimitive.Track>
      {Array.from({ length: count }).map((_, i) => (
        <SliderPrimitive.Thumb key={i} className={sliderThumbRecipe()} aria-label="slider thumb" />
      ))}
    </SliderPrimitive.Root>
  );
});
OSlider.displayName = 'OSlider';
