/**
 * OGridFrame - CSS grid 容器,container queries 响应式。
 *
 * SPEC §4.4 响应式优先 container queries。
 *
 * 支持两种模式:
 *   1. 固定列数: cols={3}
 *   2. 响应式列数: cols={{ sm: 1, md: 2, lg: 3 }} (容器宽度自适应)
 */
'use client';

import { forwardRef, useMemo, type CSSProperties, type HTMLAttributes } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

type GridCols =
  | number
  | { sm?: number; md?: number; lg?: number; xl?: number };

const GAP_CLASS = {
  none: 'gap-0',
  xs: 'gap-1',
  sm: 'gap-2',
  md: 'gap-4',
  lg: 'gap-6',
  xl: 'gap-8',
} as const;

export interface OGridFrameProps
  extends HTMLAttributes<HTMLDivElement>,
    Omit<OBlockBaseProps, 'variant'> {
  /** 列数。固定数字或响应式对象 ({ sm, md, lg, xl })。 */
  cols?: GridCols;
  /** 行数 (可选,通常 grid 由行内容自动决定)。 */
  rows?: number;
  /** 间距档位。 */
  gap?: keyof typeof GAP_CLASS;
  /** 自动行高度模式。 */
  autoRows?: 'auto' | 'min' | 'max' | 'fr';
}

function buildColsClass(cols: GridCols | undefined): string {
  if (!cols) return 'grid-cols-1';
  if (typeof cols === 'number') return `grid-cols-${Math.min(Math.max(cols, 1), 12)}`;
  // 响应式: 默认 sm 兜底
  const parts: string[] = [`grid-cols-${cols.sm ?? 1}`];
  if (cols.md) parts.push(`@[400px]:grid-cols-${cols.md}`);
  if (cols.lg) parts.push(`@[800px]:grid-cols-${cols.lg}`);
  if (cols.xl) parts.push(`@[1200px]:grid-cols-${cols.xl}`);
  return parts.join(' ');
}

export const OGridFrame = forwardRef<HTMLDivElement, OGridFrameProps>(function OGridFrame(
  {
    cols = 1,
    rows,
    gap = 'md',
    autoRows,
    className,
    children,
    theme: _theme,
    size: _size,
    style,
    ...rest
  },
  ref
) {
  const colsClass = useMemo(() => buildColsClass(cols), [cols]);

  const mergedStyle = useMemo<CSSProperties | undefined>(() => {
    if (!rows && !autoRows) return style;
    return {
      ...style,
      ...(rows ? { gridTemplateRows: `repeat(${rows}, minmax(0, 1fr))` } : {}),
      ...(autoRows === 'auto'
        ? { gridAutoRows: 'auto' }
        : autoRows === 'min'
          ? { gridAutoRows: 'min-content' }
          : autoRows === 'max'
            ? { gridAutoRows: 'max-content' }
            : autoRows === 'fr'
              ? { gridAutoRows: '1fr' }
              : {}),
    };
  }, [style, rows, autoRows]);

  return (
    <div
      ref={ref}
      className={cn('@container grid', colsClass, GAP_CLASS[gap], className)}
      style={mergedStyle}
      {...rest}
    >
      {children}
    </div>
  );
});

OGridFrame.displayName = 'OGridFrame';
