/**
 * OCandidateCard (Tide Wave 2 E10, Block)
 *
 * 候选 row 卡片,2 variant: compact 列表 / full 含 Plan。
 * 来源:OUI_WAVE_2_REQUIREMENTS_v1.0.md §7
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { OPlanCard } from '../OPlanCard';
import type { PlanData } from '../../types/tide';
import type { OBlockBaseProps } from '../../lib/types';

export interface OCandidateCardProps extends Omit<OBlockBaseProps, 'variant'> {
  rank: number;
  symbol: string;
  name: string;
  fusionScore: number;
  vetoPassed: number;
  vetoTotal: number;
  currentPrice: number;
  todayPct: number;
  industry?: string;
  isLeader?: boolean;
  isInHoldings?: boolean;
  inWatchlist?: boolean;
  candidateVariant: 'compact' | 'full';
  plan?: PlanData;
  isActive?: boolean;
  onClick?: () => void;
}

function fusionColor(score: number): string {
  if (score >= 80) return 'var(--red-up)';
  if (score >= 60) return 'var(--yellow)';
  return 'var(--muted-foreground)';
}

function vetoLabel(passed: number, total: number): { text: string; color: string } {
  if (passed === total) return { text: `✓ ${passed}/${total}`, color: 'var(--green-down)' };
  if (passed >= total - 1) return { text: `⚠ ${passed}/${total}`, color: 'var(--yellow)' };
  return { text: `✗ ${passed}/${total}`, color: 'var(--red-up)' };
}

export const OCandidateCard = forwardRef<HTMLDivElement, OCandidateCardProps>(
  function OCandidateCard(
    {
      rank,
      symbol,
      name,
      fusionScore,
      vetoPassed,
      vetoTotal,
      currentPrice,
      todayPct,
      industry,
      isLeader,
      isInHoldings,
      candidateVariant,
      plan,
      isActive,
      onClick,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const veto = vetoLabel(vetoPassed, vetoTotal);
    const pctColor =
      todayPct > 0 ? 'var(--red-up)' : todayPct < 0 ? 'var(--green-down)' : 'var(--muted-foreground)';

    const compactBody = (
      <div
        className="grid items-center gap-2 px-2 py-1.5"
        style={{ gridTemplateColumns: '28px 1fr 1fr 50px 60px' }}
      >
        {/* rank */}
        <span
          className="text-xs font-bold text-right"
          style={{ color: 'var(--text-tertiary)' }}
        >
          #{rank}
        </span>
        {/* symbol + name */}
        <div className="flex flex-col min-w-0">
          <div className="flex items-center gap-1">
            <span
              className="text-xs"
              style={{ color: 'var(--muted-foreground)', fontFamily: 'var(--font-mono)' }}
            >
              {symbol}
            </span>
            {isLeader && (
              <span
                className="text-[9px] px-1 rounded"
                style={{ backgroundColor: 'var(--red-up)', color: '#fff' }}
              >
                龙
              </span>
            )}
            {isInHoldings && (
              <span
                className="text-[9px] px-1 rounded"
                style={{ backgroundColor: 'var(--blue-accent)', color: '#fff' }}
              >
                持
              </span>
            )}
          </div>
          <span
            className="text-xs truncate"
            style={{ color: 'var(--foreground)', fontFamily: 'var(--font-sans)' }}
          >
            {name}
          </span>
        </div>
        {/* industry + price */}
        <div className="flex flex-col min-w-0 text-right">
          {industry && (
            <span
              className="text-[10px] truncate"
              style={{ color: 'var(--text-tertiary)' }}
            >
              {industry}
            </span>
          )}
          <span
            className="text-xs font-bold"
            style={{ color: 'var(--foreground)', fontFamily: 'var(--font-mono)' }}
          >
            {currentPrice.toFixed(2)}
          </span>
        </div>
        {/* today pct */}
        <span
          className="text-xs text-right"
          style={{ color: pctColor, fontFamily: 'var(--font-mono)' }}
        >
          {todayPct > 0 ? '+' : ''}
          {todayPct.toFixed(2)}%
        </span>
        {/* fusion + veto */}
        <div className="flex flex-col items-end">
          <span
            className="text-sm font-bold"
            style={{ color: fusionColor(fusionScore), fontFamily: 'var(--font-mono)' }}
          >
            {fusionScore.toFixed(0)}
          </span>
          <span
            className="text-[10px]"
            style={{ color: veto.color, fontFamily: 'var(--font-mono)' }}
          >
            {veto.text}
          </span>
        </div>
      </div>
    );

    return (
      <div
        ref={ref}
        onClick={onClick}
        role={onClick ? 'button' : 'group'}
        tabIndex={onClick ? 0 : undefined}
        onKeyDown={
          onClick
            ? (e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  onClick();
                }
              }
            : undefined
        }
        aria-label={`候选 #${rank} ${symbol} ${name}`}
        className={cn(
          'flex flex-col rounded border transition-colors @container',
          isActive
            ? 'bg-[color:var(--muted)] border-[color:var(--border-active)]'
            : 'bg-[color:var(--card)] border-[color:var(--border-strong)]',
          onClick && 'cursor-pointer hover:bg-[color:var(--accent)]',
          'focus:outline-none focus-visible:ring-2 focus-visible:ring-ring',
          className
        )}
      >
        {compactBody}
        {candidateVariant === 'full' && plan && (
          <div
            className="px-2 pb-2 pt-1 border-t border-[color:var(--border-subtle)]"
            onClick={(e) => e.stopPropagation()}
          >
            <OPlanCard plan={plan} planVariant="embedded" />
          </div>
        )}
      </div>
    );
  }
);

OCandidateCard.displayName = 'OCandidateCard';
