/**
 * ObservabilityProvider — 统一前端可观测性 (FRONTEND_STACK v1.0 §13)。
 *
 * v1.2 阶段:**仅提供 hook + Provider 契约,不接具体 collector**。
 *   - 各项目应用层在 init 时配置 endpoint
 *   - hooks 把 trace / error / event / vitals 推到内部 sink
 *   - 默认 sink = console.debug (开发) / noop (production 未配置时)
 *   - 用户传入 sink = 接 OTel / Sentry / 自研 collector
 *
 * v1.3 阶段:实现具体 OTel collector + 默认 Sentry self-hosted 适配。
 *
 * 设计原则:
 *   - 跟后端 trace_id 串联 (W3C TraceContext, propagation)
 *   - trace_id 格式 = `trc_xxx` (跟 Aegis 后端一致)
 *   - 严禁第三方 SaaS observability (Datadog / New Relic / Sentry SaaS)
 *   - 用户行为埋点命名 = ChannelName (例 "aegis.alert.fired.critical")
 *   - 抽样: 错误 100% / trace 10% / vitals 10%
 *
 * 跟 ChannelName 规范 (FRONTEND_STACK v1.0 §3) 对齐:
 *   eventName 必须形如 "{project}.{domain}.{action}"
 */

'use client';

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  type ReactNode,
} from 'react';

// ============================================================
// Types
// ============================================================

export type SeverityLevel = 'debug' | 'info' | 'warning' | 'error' | 'fatal';

/** Trace span (W3C Trace Context) */
export interface ObservabilitySpan {
  /** trace_id 格式 = `trc_xxx` (跟 Aegis 后端一致) */
  traceId: string;
  spanId: string;
  parentSpanId?: string;
  name: string;
  startTime: number; // unix ms
  endTime?: number;
  attributes?: Record<string, unknown>;
  status?: 'ok' | 'error';
  events?: Array<{ name: string; time: number; attributes?: Record<string, unknown> }>;
}

/** 用户行为埋点事件 */
export interface ObservabilityEvent {
  /** 命名遵循 ChannelName 规范: {project}.{domain}.{action} */
  name: string;
  timestamp: number;
  traceId?: string;
  blockName?: string;
  attributes?: Record<string, unknown>;
}

/** 错误监控事件 */
export interface ObservabilityError {
  message: string;
  stack?: string;
  severity: SeverityLevel;
  timestamp: number;
  traceId?: string;
  blockName?: string;
  url?: string;
  userAgent?: string;
  attributes?: Record<string, unknown>;
}

/** Web Vitals 指标 */
export interface ObservabilityVital {
  name: 'LCP' | 'FID' | 'CLS' | 'TTFB' | 'FCP' | 'INP';
  value: number;
  rating: 'good' | 'needs-improvement' | 'poor';
  timestamp: number;
  url: string;
  attributes?: Record<string, unknown>;
}

/** Sink - 数据出口,各项目应用层配置 */
export interface ObservabilitySink {
  span?: (span: ObservabilitySpan) => void | Promise<void>;
  event?: (event: ObservabilityEvent) => void | Promise<void>;
  error?: (error: ObservabilityError) => void | Promise<void>;
  vital?: (vital: ObservabilityVital) => void | Promise<void>;
}

/** 抽样策略 (FRONTEND_STACK v1.0 §13.5) */
export interface SamplingStrategy {
  /** 错误抽样,默认 1.0 (全部上报) */
  error?: number;
  /** trace 抽样,默认 0.1 (10%) */
  trace?: number;
  /** web vitals 抽样,默认 0.1 (10%) */
  vital?: number;
  /** 用户行为事件抽样,默认 1.0 */
  event?: number;
}

export interface ObservabilityConfig {
  /** 项目名 (跟 ChannelName 第一段一致) */
  project: 'helios' | 'aegis' | 'stratum' | 'tide' | 'hevi' | 'helixa' | 'selene' | string;
  environment?: 'dev' | 'staging' | 'production';
  /** 服务名 (例 "aegis-frontend") */
  serviceName?: string;
  /** OTel endpoint (v1.3 实现) */
  otelEndpoint?: string;
  /** Sink 自定义 (覆盖默认 console.debug) */
  sink?: ObservabilitySink;
  /** 抽样 */
  sampling?: SamplingStrategy;
  /** 启用 web vitals (默认 true) */
  enableVitals?: boolean;
  /** 当前用户的 traceId 生成器 (默认 generateTraceId) */
  traceIdGenerator?: () => string;
}

// ============================================================
// 默认 sink (开发: console.debug, 生产: noop)
// ============================================================

function makeDefaultSink(env: ObservabilityConfig['environment']): ObservabilitySink {
  if (env === 'production' || env === 'staging') {
    return {}; // noop, 等 v1.3 接 OTel
  }
  // dev 默认 console.debug
  return {
    span: (s) => console.debug('[obs.span]', s),
    event: (e) => console.debug('[obs.event]', e.name, e.attributes),
    error: (e) =>
      console.error('[obs.error]', e.severity, e.message, e.attributes),
    vital: (v) => console.debug('[obs.vital]', v.name, v.value, v.rating),
  };
}

// ============================================================
// trace_id 生成器
// ============================================================

/**
 * 生成 Aegis 风格的 trace_id (`trc_xxx`)。
 * 跟后端 obase 已有的 trace_id 格式一致。
 */
export function generateTraceId(): string {
  // 12 字符随机,可读性优先 (不用 UUID,太长)
  const chars = '0123456789abcdef';
  let result = 'trc_';
  for (let i = 0; i < 16; i++) {
    result += chars[Math.floor(Math.random() * chars.length)];
  }
  return result;
}

export function generateSpanId(): string {
  const chars = '0123456789abcdef';
  let result = 'spn_';
  for (let i = 0; i < 12; i++) {
    result += chars[Math.floor(Math.random() * chars.length)];
  }
  return result;
}

// ============================================================
// dev 模式校验工具
// ============================================================

/** 已警告过的 channel name 集合,避免同一 channel 反复打 warn 污染 console。 */
const warnedChannels = new Set<string>();

/**
 * ChannelName 规范校验(dev 模式调用)。
 *
 * 规范来自 HELIOS_SPEC v3.0 §8.5 / FRONTEND_STACK v1.0 §3:
 *   `{project}.{domain}.{resource}.{detail}`
 *
 * 例:
 *   ✅ `stratum.note.updated`           (3 段也可,resource 兼具 detail)
 *   ✅ `aegis.incident.opened`
 *   ✅ `helios.order.filled`
 *   ✅ `hevi.pipeline.stage_completed`
 *   ❌ `note-updated`                   (无 project 前缀)
 *   ❌ `update`                         (单段)
 *   ❌ `Stratum.Note.Updated`           (大写,kebab/snake 不一致)
 */
export function validateChannelName(name: string, expectedProject?: string): void {
  if (warnedChannels.has(name)) return;

  const issues: string[] = [];

  // 至少 2 段
  const segments = name.split('.');
  if (segments.length < 2) {
    issues.push('至少 2 段(建议 3-4 段): {project}.{domain}.{resource}.{detail}');
  }

  // 全小写 + snake_case 字符
  if (!/^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$/.test(name)) {
    issues.push('只允许小写字母 + 数字 + 下划线,段之间用 "."(snake_case)');
  }

  // 项目前缀
  if (expectedProject && segments[0] !== expectedProject) {
    issues.push(`首段应为项目名 "${expectedProject}",实际为 "${segments[0]}"`);
  }

  if (issues.length > 0) {
    warnedChannels.add(name);
    console.warn(
      `[obs] ChannelName "${name}" 不符合规范:\n` +
        issues.map((i) => `  - ${i}`).join('\n') +
        `\n  参考: HELIOS_SPEC v3.0 §8.5`
    );
  }
}

/**
 * 重置已警告 channel 集合(测试用)。
 */
export function __resetChannelWarnings(): void {
  warnedChannels.clear();
}

/**
 * 检测 sink 是否疑似 SaaS APM(违反 SPEC v3.0 §2.4 数据所有权原则)。
 * 通过 sink 名 / endpoint 启发式判断,dev 模式 warn 一次。
 */
const SAAS_BLACKLIST_HINTS = [
  'datadog',
  'newrelic',
  'new-relic',
  'sentry.io',          // 自托管 Sentry 例外(域名不同)
  'mixpanel',
  'amplitude',
  'google-analytics',
  'googletagmanager',
];

let saasWarned = false;

export function checkSinkForSaaS(otelEndpoint?: string, sinkName?: string): void {
  if (saasWarned) return;

  const haystack = `${otelEndpoint ?? ''} ${sinkName ?? ''}`.toLowerCase();
  for (const hint of SAAS_BLACKLIST_HINTS) {
    if (haystack.includes(hint)) {
      saasWarned = true;
      console.warn(
        `[obs] ⚠️ 检测到疑似 SaaS APM ("${hint}")。\n` +
          `  HELIOS_SPEC v3.0 §2.4 数据所有权原则要求自托管 only。\n` +
          `  允许:OTel collector / Tempo / Grafana / Loki / 自托管 Sentry\n` +
          `  禁止:Datadog / New Relic / Sentry SaaS / GA / Mixpanel`
      );
      return;
    }
  }
}

// ============================================================
// Context
// ============================================================

interface ObservabilityContextValue {
  config: Required<Pick<ObservabilityConfig, 'project' | 'environment'>> &
    ObservabilityConfig;
  /** 记录 span (自动抽样) */
  recordSpan: (span: ObservabilitySpan) => void;
  /** 记录用户行为事件 */
  recordEvent: (name: string, attributes?: Record<string, unknown>) => void;
  /** 记录错误 */
  recordError: (
    error: Error | string,
    options?: {
      severity?: SeverityLevel;
      blockName?: string;
      attributes?: Record<string, unknown>;
    }
  ) => void;
  /** 当前激活的 traceId (用于跨调用串联) */
  currentTraceId: () => string | null;
  /** 开始新 trace 并返回 traceId */
  startTrace: (name: string) => string;
  /** 结束 trace */
  endTrace: (traceId: string, status?: 'ok' | 'error') => void;
}

const ObservabilityContext = createContext<ObservabilityContextValue | null>(null);

// ============================================================
// Provider
// ============================================================

export interface ObservabilityProviderProps {
  config: ObservabilityConfig;
  children: ReactNode;
}

export function ObservabilityProvider({
  config,
  children,
}: ObservabilityProviderProps) {
  const env = config.environment ?? 'dev';
  const sink = config.sink ?? makeDefaultSink(env);
  const sampling: Required<SamplingStrategy> = {
    error: 1.0,
    trace: 0.1,
    vital: 0.1,
    event: 1.0,
    ...config.sampling,
  };

  const activeTraceIdRef = useRef<string | null>(null);
  const tracesRef = useRef(new Map<string, ObservabilitySpan>());

  // === recordSpan with sampling ===
  const recordSpan = useCallback(
    (span: ObservabilitySpan) => {
      if (Math.random() > sampling.trace) return;
      void sink.span?.(span);
    },
    [sink, sampling.trace]
  );

  // === recordEvent ===
  const recordEvent = useCallback(
    (name: string, attributes?: Record<string, unknown>) => {
      if (Math.random() > sampling.event) return;

      // dev 模式 ChannelName 规范校验
      // 规范: {project}.{domain}.{resource}.{detail}
      // 每个 channel 只警告一次,避免污染 console
      if (env === 'dev') {
        validateChannelName(name, config.project);
      }

      const evt: ObservabilityEvent = {
        name,
        timestamp: Date.now(),
        traceId: activeTraceIdRef.current ?? undefined,
        attributes,
      };
      void sink.event?.(evt);
    },
    [sink, sampling.event, env, config.project]
  );

  // === recordError ===
  const recordError = useCallback(
    (
      error: Error | string,
      options?: {
        severity?: SeverityLevel;
        blockName?: string;
        attributes?: Record<string, unknown>;
      }
    ) => {
      if (Math.random() > sampling.error) return;
      const message = typeof error === 'string' ? error : error.message;
      const stack = typeof error === 'string' ? undefined : error.stack;
      const obsErr: ObservabilityError = {
        message,
        stack,
        severity: options?.severity ?? 'error',
        timestamp: Date.now(),
        traceId: activeTraceIdRef.current ?? undefined,
        blockName: options?.blockName,
        url: typeof window !== 'undefined' ? window.location.href : undefined,
        userAgent:
          typeof navigator !== 'undefined' ? navigator.userAgent : undefined,
        attributes: options?.attributes,
      };
      void sink.error?.(obsErr);
    },
    [sink, sampling.error]
  );

  // === trace lifecycle ===
  const startTrace = useCallback(
    (name: string) => {
      const traceId = (config.traceIdGenerator ?? generateTraceId)();
      const span: ObservabilitySpan = {
        traceId,
        spanId: generateSpanId(),
        name,
        startTime: Date.now(),
      };
      tracesRef.current.set(traceId, span);
      activeTraceIdRef.current = traceId;
      return traceId;
    },
    [config.traceIdGenerator]
  );

  const endTrace = useCallback(
    (traceId: string, status: 'ok' | 'error' = 'ok') => {
      const span = tracesRef.current.get(traceId);
      if (!span) return;
      span.endTime = Date.now();
      span.status = status;
      recordSpan(span);
      tracesRef.current.delete(traceId);
      if (activeTraceIdRef.current === traceId) {
        activeTraceIdRef.current = null;
      }
    },
    [recordSpan]
  );

  const currentTraceId = useCallback(() => activeTraceIdRef.current, []);

  // === dev 模式:SaaS sink 检测 ===
  useEffect(() => {
    if (env !== 'dev') return;
    checkSinkForSaaS(config.otelEndpoint);
  }, [env, config.otelEndpoint]);

  // === window error / unhandledrejection 自动接管 ===
  useEffect(() => {
    if (typeof window === 'undefined') return;
    function onError(e: ErrorEvent) {
      recordError(e.error ?? e.message, { severity: 'error' });
    }
    function onRejection(e: PromiseRejectionEvent) {
      recordError(
        e.reason instanceof Error ? e.reason : String(e.reason),
        { severity: 'error', attributes: { kind: 'unhandledrejection' } }
      );
    }
    window.addEventListener('error', onError);
    window.addEventListener('unhandledrejection', onRejection);
    return () => {
      window.removeEventListener('error', onError);
      window.removeEventListener('unhandledrejection', onRejection);
    };
  }, [recordError]);

  // === Web Vitals 自动采集 (v1.2 占位, 待 v1.3 接 web-vitals npm) ===
  // 这里只暴露 sink.vital,具体由应用层在 init 时调用 web-vitals lib
  // 例:
  //   import { onLCP, onINP, onCLS } from 'web-vitals';
  //   onLCP((m) => sink.vital?.({ ... }));

  const ctxValue = useMemo<ObservabilityContextValue>(
    () => ({
      config: { ...config, project: config.project, environment: env },
      recordSpan,
      recordEvent,
      recordError,
      currentTraceId,
      startTrace,
      endTrace,
    }),
    [config, env, recordSpan, recordEvent, recordError, currentTraceId, startTrace, endTrace]
  );

  return (
    <ObservabilityContext.Provider value={ctxValue}>
      {children}
    </ObservabilityContext.Provider>
  );
}

ObservabilityProvider.displayName = 'ObservabilityProvider';

// ============================================================
// Hooks
// ============================================================

/**
 * 使用 observability context。
 *
 * 用法:
 *   const obs = useObservability();
 *   obs.recordEvent('aegis.alert.fired.critical', { alertId: '...' });
 */
export function useObservability(): ObservabilityContextValue {
  const ctx = useContext(ObservabilityContext);
  if (!ctx) {
    // 优雅降级:Provider 不存在时返回 noop
    return {
      config: { project: 'unknown', environment: 'dev' },
      recordSpan: () => {},
      recordEvent: () => {},
      recordError: () => {},
      currentTraceId: () => null,
      startTrace: () => 'trc_noprovider',
      endTrace: () => {},
    };
  }
  return ctx;
}

/**
 * 给 Block 用,自动注入 data-helios-block + 出错追踪 (FRONTEND_STACK v1.0 §13.4)。
 *
 * 用法 (在 Block 内部):
 *   const { dataAttrs } = useBlockObservability('OOrderbookL2');
 *   return <div {...dataAttrs} ...>...</div>;
 */
export function useBlockObservability(blockName: string): {
  dataAttrs: { 'data-helios-block': string; 'data-helios-trace-id'?: string };
  recordEvent: (action: string, attributes?: Record<string, unknown>) => void;
  recordError: (error: Error | string, attributes?: Record<string, unknown>) => void;
} {
  const obs = useObservability();
  const traceId = obs.currentTraceId();

  const recordEvent = useCallback(
    (action: string, attributes?: Record<string, unknown>) => {
      // 自动拼 project.block-name.action
      const eventName = `${obs.config.project}.block.${blockName}.${action}`;
      obs.recordEvent(eventName, { ...attributes, blockName });
    },
    [obs, blockName]
  );

  const recordError = useCallback(
    (error: Error | string, attributes?: Record<string, unknown>) => {
      obs.recordError(error, { blockName, attributes });
    },
    [obs, blockName]
  );

  return {
    dataAttrs: {
      'data-helios-block': blockName,
      ...(traceId ? { 'data-helios-trace-id': traceId } : {}),
    },
    recordEvent,
    recordError,
  };
}

/**
 * fetch wrapper 自动注入 traceparent (W3C Trace Context)。
 *
 * 用法:
 *   const fetch = useTracedFetch();
 *   const res = await fetch('/api/v1/...');
 */
export function useTracedFetch(): typeof fetch {
  const obs = useObservability();
  return useCallback<typeof fetch>(
    async (input, init) => {
      const traceId = obs.currentTraceId() ?? generateTraceId();
      const spanId = generateSpanId();
      // W3C Trace Context: traceparent = "00-{trace_id_hex}-{span_id_hex}-01"
      // 简化版,详细见 https://www.w3.org/TR/trace-context/
      const traceparent = `00-${traceId.replace('trc_', '').padEnd(32, '0').slice(0, 32)}-${spanId.replace('spn_', '').padEnd(16, '0').slice(0, 16)}-01`;
      const headers = new Headers(init?.headers);
      if (!headers.has('traceparent')) {
        headers.set('traceparent', traceparent);
      }
      return fetch(input, { ...init, headers });
    },
    [obs]
  );
}
