/**
 * OAccordionFrame - 折叠面板 (Radix Accordion 包装)。
 *
 * 用于 FAQ / 设置分组 / 长列表分段展开。
 */
'use client';

import * as Accordion from '@radix-ui/react-accordion';
import { forwardRef, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OAccordionItem {
  key: string;
  title: ReactNode;
  content: ReactNode;
  disabled?: boolean;
}

export interface OAccordionFrameProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  items: OAccordionItem[];
  /** 单选 (single) / 多选 (multiple) 展开。 */
  type?: 'single' | 'multiple';
  /** 默认展开的 key (single) 或 keys (multiple)。 */
  defaultValue?: string | string[];
  /** 单选模式下可关闭。 */
  collapsible?: boolean;
  variant?: 'bordered' | 'separated' | 'minimal';
}

const CHEVRON = (
  <svg
    width="14"
    height="14"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    aria-hidden="true"
    className="shrink-0 transition-transform duration-200"
  >
    <polyline points="6 9 12 15 18 9" />
  </svg>
);

export const OAccordionFrame = forwardRef<HTMLDivElement, OAccordionFrameProps>(
  function OAccordionFrame(
    {
      items,
      type = 'single',
      defaultValue,
      collapsible = true,
      variant = 'bordered',
      className,
      theme: _t,
    },
    ref
  ) {
    const wrapperCls =
      variant === 'separated'
        ? 'space-y-2'
        : variant === 'bordered'
          ? 'border border-border rounded-md divide-y divide-border bg-card'
          : 'space-y-0';

    const itemCls =
      variant === 'separated'
        ? 'border border-border rounded-md bg-card overflow-hidden'
        : variant === 'minimal'
          ? 'border-b border-border last:border-0'
          : '';

    const commonRoot =
      type === 'single'
        ? { type: 'single' as const, collapsible, defaultValue: defaultValue as string | undefined }
        : { type: 'multiple' as const, defaultValue: defaultValue as string[] | undefined };

    return (
      <Accordion.Root
        ref={ref}
        {...commonRoot}
        className={cn(wrapperCls, className)}
      >
        {items.map((it) => (
          <Accordion.Item key={it.key} value={it.key} disabled={it.disabled} className={itemCls}>
            <Accordion.Header className="flex">
              <Accordion.Trigger
                className={cn(
                  'flex flex-1 items-center justify-between gap-3 px-4 py-3 text-left text-sm font-medium',
                  'hover:bg-muted/40 transition-colors',
                  'disabled:opacity-50 disabled:cursor-not-allowed',
                  '[&[data-state=open]>svg]:rotate-180'
                )}
              >
                {it.title}
                {CHEVRON}
              </Accordion.Trigger>
            </Accordion.Header>
            <Accordion.Content
              className={cn(
                'overflow-hidden text-sm text-muted-foreground',
                'data-[state=open]:animate-accordion-down',
                'data-[state=closed]:animate-accordion-up'
              )}
            >
              <div className="px-4 pb-4">{it.content}</div>
            </Accordion.Content>
          </Accordion.Item>
        ))}
      </Accordion.Root>
    );
  }
);

OAccordionFrame.displayName = 'OAccordionFrame';
