/**
 * OEconomicCalendar (Tide Wave 3 E26, Block)
 *
 * 财经日历(list / calendar 双视图)。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §4.3
 */
import { forwardRef, useMemo } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export type EventImpact = 'high' | 'medium' | 'low';

export interface EconomicEvent {
  id: string;
  date: string | Date;
  time?: string;
  title: string;
  country: string;
  impact: EventImpact;
  actualValue?: string;
  forecastValue?: string;
  previousValue?: string;
}

export interface OEconomicCalendarProps extends Omit<OBlockBaseProps, 'variant'> {
  events: EconomicEvent[];
  view?: 'list' | 'calendar';
  onEventClick?: (event: EconomicEvent) => void;
  highlightCountry?: string;
}

const IMPACT_COLOR: Record<EventImpact, string> = {
  high: 'var(--red-up)',
  medium: 'var(--yellow)',
  low: 'var(--text-tertiary)',
};

const IMPACT_DOTS: Record<EventImpact, string> = {
  high: '●●●',
  medium: '●●○',
  low: '●○○',
};

function fmtDate(d: string | Date): string {
  return typeof d === 'string' ? d : d.toISOString().slice(0, 10);
}

export const OEconomicCalendar = forwardRef<HTMLDivElement, OEconomicCalendarProps>(
  function OEconomicCalendar(
    {
      events,
      view: _view = 'list',
      onEventClick,
      highlightCountry,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const grouped = useMemo(() => {
      const map = new Map<string, EconomicEvent[]>();
      for (const e of events) {
        const k = fmtDate(e.date);
        if (!map.has(k)) map.set(k, []);
        map.get(k)!.push(e);
      }
      return Array.from(map.entries()).sort(([a], [b]) => a.localeCompare(b));
    }, [events]);

    if (events.length === 0) {
      return (
        <div
          ref={ref}
          className={cn('py-6 text-center text-sm border border-dashed rounded', className)}
          style={{ color: 'var(--text-tertiary)', borderColor: 'var(--border-strong)' }}
        >
          暂无重要财经事件
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn(
          'flex flex-col gap-1.5 px-3 py-2 rounded @container',
          'bg-[color:var(--card)] border border-[color:var(--border-strong)]',
          className
        )}
        style={{ fontFamily: 'var(--font-sans)' }}
        aria-label={`财经日历 ${events.length} 事件`}
      >
        {grouped.map(([date, dayEvents]) => (
          <section key={date} className="flex flex-col gap-1">
            <div
              className="text-[10px] uppercase tracking-[0.04em] px-1 py-0.5 rounded"
              style={{
                color: 'var(--text-tertiary)',
                backgroundColor: 'var(--muted)',
                fontFamily: 'var(--font-mono)',
              }}
            >
              {date}
            </div>
            <ul className="flex flex-col gap-0.5 list-none p-0 m-0">
              {dayEvents.map((e) => {
                const isHl = highlightCountry === e.country;
                return (
                  <li key={e.id}>
                    <button
                      type="button"
                      onClick={() => onEventClick?.(e)}
                      disabled={!onEventClick}
                      className={cn(
                        'grid items-center gap-2 px-2 py-1 w-full text-left text-xs rounded',
                        onEventClick && 'hover:bg-[color:var(--accent)] transition-colors',
                        isHl && 'bg-[color:var(--muted)]'
                      )}
                      style={{
                        gridTemplateColumns: '50px 30px 1fr 60px 60px',
                        color: 'var(--foreground)',
                      }}
                    >
                      <span
                        style={{
                          color: 'var(--text-tertiary)',
                          fontFamily: 'var(--font-mono)',
                          fontSize: 10,
                        }}
                      >
                        {e.time ?? '--:--'}
                      </span>
                      <span
                        className="text-[10px] text-center px-1 rounded"
                        style={{
                          backgroundColor: 'var(--muted)',
                          color: 'var(--muted-foreground)',
                        }}
                      >
                        {e.country}
                      </span>
                      <span className="truncate">{e.title}</span>
                      <span
                        className="text-[10px] text-right"
                        style={{ color: IMPACT_COLOR[e.impact], fontFamily: 'var(--font-mono)' }}
                      >
                        {IMPACT_DOTS[e.impact]}
                      </span>
                      <span
                        className="text-[10px] text-right"
                        style={{ color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)' }}
                      >
                        {e.actualValue ?? e.forecastValue ?? '-'}
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
          </section>
        ))}
      </div>
    );
  }
);

OEconomicCalendar.displayName = 'OEconomicCalendar';
