/**
 * OCandlestickChart - K 线图 (Terminal-grade v1.0)。
 *
 * 使用 lightweight-charts (TradingView 开源,28KB gzipped,业内标准)。
 * 通过 dynamic import 拆出 main bundle。
 *
 * Terminal-grade 升级 (Batch 15):
 *   ✓ syncToCrosshair  跨图联动 (TV 内置 crosshair → 转发到 CrosshairProvider)
 *   ✓ channel          FastDataProvider 直接订阅
 *   ✓ syncToTimeline   时空切片回放
 *   ✓ dataDelay        合规延时标签
 *   ✓ lowPerformanceMode 关闭 indicators + volume
 *
 * 数据契约:
 *   { symbol, candles: [{ time, open, high, low, close, volume? }], indicators? }
 *
 * @example
 *   <OCandlestickChart
 *     data={{ symbol: 'BTC/USDT', candles: btcCandles }}
 *     syncToCrosshair
 *     syncToTimeline
 *     height={400}
 *   />
 */
'use client';

import { Suspense, lazy, forwardRef, useEffect, useState, useMemo } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import { useFastData } from '../../providers/FastDataProvider';
import { useTimeline } from '../../providers/TimelineProvider';

const ChartImpl = lazy(() =>
  import('./OCandlestickChart.impl').then((m) => ({ default: m.CandlestickImpl }))
);

export interface OCandle {
  /** Unix timestamp (秒) 或 ISO 字符串。 */
  time: number | string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume?: number;
}

export interface OIndicatorLine {
  name: string;
  values: { time: number | string; value: number }[];
  color?: string;
}

export interface OCandlestickData {
  candles: OCandle[];
  indicators?: OIndicatorLine[];
  showVolume?: boolean;
  /** Terminal-grade: 标的 (crosshair 联动)。 */
  symbol?: string;
}

export interface OCandlestickChartProps
  extends OBlockDataProps<OCandlestickData>,
    Pick<
      TerminalBlockProps,
      'syncToCrosshair' | 'channel' | 'dataDelay' | 'regulation' | 'syncToTimeline' | 'lowPerformanceMode'
    > {
  height?: number;
  /** 主题色: 涨绿跌红 (默认 'std') 或 反向 'inv'。 */
  colorScheme?: 'std' | 'inv';
  /** 隐藏时间轴 (小型缩略图)。 */
  hideTimeAxis?: boolean;
}

export const OCandlestickChart = forwardRef<HTMLDivElement, OCandlestickChartProps>(
  function OCandlestickChart(
    {
      data: dataProp,
      loading,
      error,
      empty,
      height = 400,
      colorScheme = 'std',
      hideTimeAxis = false,
      syncToCrosshair,
      channel,
      dataDelay = 0,
      regulation: _r,
      syncToTimeline,
      lowPerformanceMode,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    // Worker 数据订阅
    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OCandlestickData | null>(null);

    useEffect(() => {
      if (!channel || !fastData) return;
      return fastData.subscribe<OCandlestickData>(channel, setChannelData);
    }, [channel, fastData]);

    const rawData = channel ? channelData : (dataProp ?? null);

    // Timeline 切片
    const timeline = useTimeline();
    const [timelineSlice, setTimelineSlice] = useState<number | null>(null);

    useEffect(() => {
      if (!syncToTimeline || !timeline) return;
      return timeline.subscribe((s) => setTimelineSlice(s.currentTime));
    }, [timeline, syncToTimeline]);

    const data = useMemo<OCandlestickData | null>(() => {
      if (!rawData) return null;
      if (timelineSlice == null) return rawData;
      // 截断到 timelineSlice
      const candles = rawData.candles.filter((c) => {
        const t = typeof c.time === 'number'
          ? (c.time > 1e10 ? Math.floor(c.time / 1000) : c.time)
          : Math.floor(new Date(c.time).getTime() / 1000);
        return t <= timelineSlice;
      });
      return { ...rawData, candles };
    }, [rawData, timelineSlice]);

    const state = resolveBlockState({ data, loading, error, empty });

    // 准备给 impl 的 props
    const symbolForCrosshair = useMemo(() => {
      if (typeof syncToCrosshair === 'string') return syncToCrosshair;
      if (syncToCrosshair === true) return data?.symbol ?? null;
      return null;
    }, [syncToCrosshair, data]);

    if (state === 'loading')
      return (
        <div
          ref={ref}
          className={cn(
            'rounded-md border border-border bg-card p-4 w-full @container',
            className
          )}
          style={{ height }}
        >
          <OLoadingState variant="shimmer" rows={3} rowHeight="2rem" />
        </div>
      );
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data || data.candles.length === 0)
      return (
        <OEmptyState
          ref={ref}
          title="No candle data"
          description="There is no OHLC data to render."
          className={className}
        />
      );

    return (
      <div
        ref={ref}
        className={cn(
          'relative w-full overflow-hidden rounded-md border border-border bg-card',
          className
        )}
        style={{ height }}
      >
        {dataDelay > 0 ? (
          <div className="absolute top-2 right-3 z-10 text-[10px] text-[color:var(--alert-warn)] font-mono pointer-events-none">
            延时 {dataDelay}m
          </div>
        ) : null}
        {timelineSlice != null ? (
          <div className="absolute top-2 left-3 z-10 text-[10px] text-[color:var(--alert-info)] font-mono pointer-events-none">
            回放: {new Date(timelineSlice * 1000).toLocaleString()}
          </div>
        ) : null}
        <Suspense
          fallback={
            <div className="w-full h-full flex items-center justify-center">
              <OLoadingState variant="spinner" message="Loading chart..." />
            </div>
          }
        >
          <ChartImpl
            data={data}
            colorScheme={colorScheme}
            hideTimeAxis={hideTimeAxis}
            height={height}
            symbolForCrosshair={symbolForCrosshair}
            lowPerformanceMode={!!lowPerformanceMode}
          />
        </Suspense>
      </div>
    );
  }
);

OCandlestickChart.displayName = 'OCandlestickChart';
