/**
 * useViewportClass - 视口形态检测 hook (Helios Terminal SPEC §10)。
 *
 * 与 useContainerSize 区别:
 *   - useContainerSize 检测 Block 父容器宽度 (用于单个 Block 内部布局)
 *   - useViewportClass 检测整个视口 (用于决定 phone/tablet/desktop 形态)
 *
 * 不是 responsive 是形态切换:
 *   - phone (< 640px):    ODataTable → 卡片列表,OSplitFrame → 标签页
 *   - tablet (640-1024):   桌面布局但密度变 comfortable
 *   - desktop (>= 1024):   完整工作台
 *
 * 用法:
 *   const vp = useViewportClass();
 *   if (vp === 'phone') return <CardList />;
 *   return <Table />;
 *
 * 实现:
 *   - 监听 window resize
 *   - 同时监听 'pointer: coarse' (触摸设备) 用于辅助判断
 *   - 节流 + RAF 优化,resize 1000 次/秒 也不卡
 *   - SSR 安全 (初始返回 'desktop' 兜底,挂载后修正)
 */

'use client';

import { useEffect, useState } from 'react';

export type ViewportClass = 'phone' | 'tablet' | 'desktop';

export interface ViewportInfo {
  /** 三档形态分类。 */
  class: ViewportClass;
  /** 视口宽度 px。 */
  width: number;
  /** 视口高度 px。 */
  height: number;
  /** 横屏 (width > height)。 */
  landscape: boolean;
  /** 触摸设备 (pointer: coarse)。 */
  touch: boolean;
  /** 设备像素比 (>= 2 视为 retina)。 */
  dpr: number;
}

// 断点 (SPEC §10)
const PHONE_MAX = 640;
const TABLET_MAX = 1024;

function classify(width: number): ViewportClass {
  if (width < PHONE_MAX) return 'phone';
  if (width < TABLET_MAX) return 'tablet';
  return 'desktop';
}

function readViewport(): ViewportInfo {
  if (typeof window === 'undefined') {
    return {
      class: 'desktop',
      width: 1280,
      height: 720,
      landscape: true,
      touch: false,
      dpr: 1,
    };
  }
  const w = window.innerWidth;
  const h = window.innerHeight;
  const touch = window.matchMedia('(pointer: coarse)').matches;
  return {
    class: classify(w),
    width: w,
    height: h,
    landscape: w > h,
    touch,
    dpr: Math.min(window.devicePixelRatio || 1, 3),
  };
}

/**
 * 主 hook: 监听视口变化并返回完整 ViewportInfo。
 */
export function useViewport(): ViewportInfo {
  const [info, setInfo] = useState<ViewportInfo>(readViewport);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    let raf = 0;
    function update() {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        setInfo(readViewport());
      });
    }

    window.addEventListener('resize', update);
    window.addEventListener('orientationchange', update);
    // pointer 类型变化也监听 (某些设备外接键盘后)
    const mq = window.matchMedia('(pointer: coarse)');
    mq.addEventListener?.('change', update);

    // 初次挂载校正一次 (SSR 兜底可能不准)
    update();

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener('resize', update);
      window.removeEventListener('orientationchange', update);
      mq.removeEventListener?.('change', update);
    };
  }, []);

  return info;
}

/**
 * 简化 hook: 仅返回 viewport class。
 *
 * 大多数 Block 只需要知道 phone/tablet/desktop,用这个更轻量。
 */
export function useViewportClass(): ViewportClass {
  return useViewport().class;
}

/**
 * 判断是否为某档,常用于 JSX 短路。
 *
 *   const isPhone = useIsViewport('phone');
 *   return isPhone ? <Mobile /> : <Desktop />;
 */
export function useIsViewport(target: ViewportClass): boolean {
  return useViewportClass() === target;
}

/**
 * SSR 安全的初始判断 (不订阅 resize)。
 * 用于 SSR 渲染时,客户端 hydration 后才接管为 useViewportClass。
 */
export function getStaticViewportClass(userAgent?: string): ViewportClass {
  if (!userAgent) return 'desktop';
  if (/Mobile|iPhone|Android.*Mobile/i.test(userAgent)) return 'phone';
  if (/iPad|Tablet|Android(?!.*Mobile)/i.test(userAgent)) return 'tablet';
  return 'desktop';
}
