/**
 * OAvatar - 头像。
 *
 * 优先 img,加载失败或无 src 时 fallback 到 initials。
 * 3 形状: circle (默认) / rounded / square
 * 4 尺寸: xs / sm / md / lg / xl
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, useState, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

const avatarVariants = cva(
  'inline-flex items-center justify-center font-medium shrink-0 overflow-hidden select-none',
  {
    variants: {
      size: {
        xs: 'w-6 h-6 text-[10px]',
        sm: 'w-8 h-8 text-xs',
        md: 'w-10 h-10 text-sm',
        lg: 'w-12 h-12 text-base',
        xl: 'w-16 h-16 text-lg',
      },
      shape: {
        circle: 'rounded-full',
        rounded: 'rounded-md',
        square: 'rounded-none',
      },
    },
    defaultVariants: { size: 'md', shape: 'circle' },
  }
);

type AvatarVariantProps = VariantProps<typeof avatarVariants>;

export interface OAvatarProps
  extends Omit<OBlockBaseProps, 'variant' | 'size'>,
    AvatarVariantProps {
  src?: string;
  /** 用于 alt 文本 + initials fallback。 */
  name: string;
  /** 自定义 fallback (覆盖 initials)。 */
  fallback?: ReactNode;
  /** 边框 (有时叠加在背景上需要)。 */
  bordered?: boolean;
  /** 单击。 */
  onClick?: () => void;
}

function getInitials(name: string): string {
  const parts = name.trim().split(/\s+/);
  if (parts.length === 0) return '?';
  if (parts.length === 1) return parts[0]!.slice(0, 2).toUpperCase();
  return ((parts[0]?.[0] ?? '') + (parts[parts.length - 1]?.[0] ?? '')).toUpperCase();
}

// 从名字稳定地映射到 5 个颜色(避免每次 mount 颜色变)
function colorFromName(name: string): string {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
  const idx = h % 5;
  return ['--chart-1', '--chart-2', '--chart-3', '--chart-4', '--chart-5'][idx]!;
}

export const OAvatar = forwardRef<HTMLSpanElement, OAvatarProps>(function OAvatar(
  { src, name, fallback, bordered = false, size, shape, onClick, className, theme: _t, ...rest },
  ref
) {
  const [errored, setErrored] = useState(false);
  const showImage = src && !errored;
  const colorVar = colorFromName(name);

  const Tag = onClick ? 'button' : 'span';

  return (
    <Tag
      ref={ref as never}
      onClick={onClick}
      className={cn(
        avatarVariants({ size, shape }),
        bordered && 'ring-2 ring-background',
        onClick && 'cursor-pointer hover:opacity-90 transition-opacity',
        className
      )}
      style={
        showImage
          ? undefined
          : {
              backgroundColor: `color-mix(in oklch, var(${colorVar}) 25%, transparent)`,
              color: `var(${colorVar})`,
            }
      }
      title={name}
      aria-label={name}
      {...rest}
    >
      {showImage ? (
        <img
          src={src}
          alt={name}
          className="w-full h-full object-cover @container"
          onError={() => setErrored(true)}
        />
      ) : (
        fallback ?? <span>{getInitials(name)}</span>
      )}
    </Tag>
  );
});

OAvatar.displayName = 'OAvatar';
