/**
 * ResponsiveBlock - 桌面 / 移动形态自动切换包装器。
 *
 * 让任一 Block 提供两种形态实现,根据 viewport 自动渲染合适形态。
 *
 * 用法:
 *   <ResponsiveBlock
 *     desktop={<ODataTable data={data} />}
 *     mobile={<ODataTableCardList data={data} />}
 *   />
 *
 * 也可以用 render prop:
 *   <ResponsiveBlock>
 *     {(vp) => (vp === 'phone' ? <Mobile /> : <Desktop />)}
 *   </ResponsiveBlock>
 *
 * 三档形态可指定 (默认 tablet 跟 desktop 同):
 *   <ResponsiveBlock desktop={<A />} tablet={<B />} mobile={<C />} />
 *
 * SSR 友好:
 *   - 若提供 ssrFallback,SSR 时渲染这个
 *   - 否则 SSR 时渲染 desktop
 *   - 客户端 hydration 后切换到正确形态
 */

'use client';

import { type ReactNode } from 'react';
import { useViewportClass, type ViewportClass } from '../hooks/useViewportClass';

export interface ResponsiveBlockProps {
  /** 桌面形态 (>= 1024px)。 */
  desktop?: ReactNode;
  /** 平板形态 (640-1024px)。不传则用 desktop。 */
  tablet?: ReactNode;
  /** 移动形态 (< 640px)。不传则用 desktop。 */
  mobile?: ReactNode;
  /** Render prop 模式 (覆盖以上三个,完全自定义)。 */
  children?: (viewport: ViewportClass) => ReactNode;
  /** SSR 兜底 (避免 hydration mismatch)。默认用 desktop。 */
  ssrFallback?: ReactNode;
}

export function ResponsiveBlock({
  desktop,
  tablet,
  mobile,
  children,
  ssrFallback,
}: ResponsiveBlockProps) {
  const vp = useViewportClass();

  // Render prop 模式优先
  if (children) {
    return <>{children(vp)}</>;
  }

  // 三档选择
  if (vp === 'phone' && mobile) return <>{mobile}</>;
  if (vp === 'tablet' && tablet) return <>{tablet}</>;
  if (desktop) return <>{desktop}</>;

  // 兜底
  return <>{ssrFallback ?? desktop ?? mobile ?? tablet ?? null}</>;
}

ResponsiveBlock.displayName = 'ResponsiveBlock';
