/**
 * OOrderbookDepth - 盘口深度图。
 *
 * 高频更新场景 (撮合实时数据), 用 Canvas 自绘避免 React 重建 DOM。
 *
 * 数据契约:
 *   bids/asks: { price, size }[] 已排序 (bids 从高到低, asks 从低到高)
 *
 * Block 受控: 数据由 Page 通过 WebSocket 推送更新。
 *
 * @example
 * <OOrderbookDepth data={{ bids, asks }} height={300} />
 */
'use client';

import { forwardRef, useEffect, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import { useFastData } from '../../providers/FastDataProvider';

export interface OOrderbookLevel {
  price: number;
  size: number;
}

export interface OOrderbookData {
  bids: OOrderbookLevel[];
  asks: OOrderbookLevel[];
  /** 用于显示 (e.g. "BTC/USDT")。 */
  symbol?: string;
}

export interface OOrderbookDepthProps
  extends OBlockDataProps<OOrderbookData>,
    Pick<TerminalBlockProps, 'channel' | 'dataDelay' | 'regulation'> {
  height?: number;
  /** 显示档位数 (各 side)。 */
  levels?: number;
  /** 颜色方向 (std: 涨绿跌红 / inv 反向)。 */
  colorScheme?: 'std' | 'inv';
  /** 视觉风格。 */
  variant?: 'area' | 'bars';
}

function drawOrderbook(
  ctx: CanvasRenderingContext2D,
  w: number,
  h: number,
  data: OOrderbookData,
  levels: number,
  variant: 'area' | 'bars',
  colors: { bid: string; ask: string; bidFill: string; askFill: string; mid: string; text: string }
) {
  ctx.clearRect(0, 0, w, h);
  const halfW = w / 2;
  const padH = 16;
  const innerH = h - padH * 2;

  const bids = data.bids.slice(0, levels);
  const asks = data.asks.slice(0, levels);

  // 累积 cumulative size
  let cb = 0;
  const cumBids = bids.map((b) => ((cb += b.size), { ...b, cum: cb }));
  let ca = 0;
  const cumAsks = asks.map((a) => ((ca += a.size), { ...a, cum: ca }));

  const maxCum = Math.max(cb, ca, 1);

  // 中线
  ctx.strokeStyle = colors.mid;
  ctx.setLineDash([2, 4]);
  ctx.beginPath();
  ctx.moveTo(halfW, padH);
  ctx.lineTo(halfW, h - padH);
  ctx.stroke();
  ctx.setLineDash([]);

  if (variant === 'area') {
    // BIDS area (左侧, 从 halfW 向左)
    ctx.beginPath();
    ctx.moveTo(halfW, h - padH);
    cumBids.forEach((b, i) => {
      const x = halfW - (i / (cumBids.length - 1 || 1)) * halfW;
      const y = h - padH - (b.cum / maxCum) * innerH;
      if (i === 0) ctx.lineTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.lineTo(0, h - padH);
    ctx.closePath();
    ctx.fillStyle = colors.bidFill;
    ctx.fill();
    ctx.strokeStyle = colors.bid;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // ASKS area (右侧)
    ctx.beginPath();
    ctx.moveTo(halfW, h - padH);
    cumAsks.forEach((a, i) => {
      const x = halfW + (i / (cumAsks.length - 1 || 1)) * halfW;
      const y = h - padH - (a.cum / maxCum) * innerH;
      ctx.lineTo(x, y);
    });
    ctx.lineTo(w, h - padH);
    ctx.closePath();
    ctx.fillStyle = colors.askFill;
    ctx.fill();
    ctx.strokeStyle = colors.ask;
    ctx.stroke();
  } else {
    // bars 模式: 每档一条横向 bar
    const rowH = innerH / levels;
    bids.forEach((b, i) => {
      const len = (b.size / maxCum) * halfW;
      ctx.fillStyle = colors.bidFill;
      ctx.fillRect(halfW - len, padH + i * rowH, len, rowH - 1);
    });
    asks.forEach((a, i) => {
      const len = (a.size / maxCum) * halfW;
      ctx.fillStyle = colors.askFill;
      ctx.fillRect(halfW, padH + i * rowH, len, rowH - 1);
    });
  }

  // 中价 (spread label)
  const bestBid = bids[0]?.price;
  const bestAsk = asks[0]?.price;
  if (bestBid != null && bestAsk != null) {
    const mid = ((bestBid + bestAsk) / 2).toFixed(2);
    const spread = (bestAsk - bestBid).toFixed(2);
    ctx.fillStyle = colors.text;
    ctx.font = '11px ui-monospace, monospace';
    ctx.textAlign = 'center';
    ctx.fillText(`${mid}`, halfW, padH - 3);
    ctx.font = '10px ui-monospace, monospace';
    ctx.fillText(`spread ${spread}`, halfW, h - 4);
  }
}

export const OOrderbookDepth = forwardRef<HTMLDivElement, OOrderbookDepthProps>(
  function OOrderbookDepth(
    {
      data: dataProp,
      loading,
      error,
      empty,
      height = 300,
      levels = 30,
      colorScheme = 'std',
      variant = 'area',
      channel,
      dataDelay = 0,
      regulation: _r,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    // Worker channel 订阅
    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OOrderbookData | null>(null);

    useEffect(() => {
      if (!channel || !fastData) return;
      return fastData.subscribe<OOrderbookData>(channel, setChannelData);
    }, [channel, fastData]);

    const data = channel ? channelData : (dataProp ?? null);

    const state = resolveBlockState({ data, loading, error, empty });
    const canvasRef = useRef<HTMLCanvasElement | null>(null);

    useEffect(() => {
      if (state !== 'ready' || !data) return;
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      function resize() {
        if (!canvas) return;
        const parent = canvas.parentElement!;
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        const w = parent.clientWidth;
        const h = parent.clientHeight;
        canvas.width = w * dpr;
        canvas.height = h * dpr;
        canvas.style.width = `${w}px`;
        canvas.style.height = `${h}px`;
        ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
        const styles = getComputedStyle(document.documentElement);
        const bidColor = colorScheme === 'inv' ? styles.getPropertyValue('--destructive') : styles.getPropertyValue('--success');
        const askColor = colorScheme === 'inv' ? styles.getPropertyValue('--success') : styles.getPropertyValue('--destructive');
        drawOrderbook(ctx!, w, h, data!, levels, variant, {
          bid: bidColor.trim(),
          ask: askColor.trim(),
          bidFill: `color-mix(in oklch, ${bidColor.trim()} 25%, transparent)`,
          askFill: `color-mix(in oklch, ${askColor.trim()} 25%, transparent)`,
          mid: styles.getPropertyValue('--border').trim() || '#666',
          text: styles.getPropertyValue('--foreground').trim() || '#fff',
        });
      }
      resize();

      const ro = new ResizeObserver(resize);
      if (canvas.parentElement) ro.observe(canvas.parentElement);
      return () => ro.disconnect();
    }, [data, state, levels, variant, colorScheme]);

    if (state === 'loading')
      return (
        <div
          ref={ref}
          className={cn('rounded-md border border-border bg-card p-4 @container', className)}
          style={{ height }}
        >
          <OLoadingState variant="skeleton" rows={3} />
        </div>
      );
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data || (data.bids.length === 0 && data.asks.length === 0))
      return <OEmptyState ref={ref} title="No orderbook data" className={className} />;

    return (
      <div
        ref={ref}
        className={cn('relative rounded-md border border-border bg-card overflow-hidden', className)}
        style={{ height }}
      >
        {data.symbol ? (
          <div className="absolute top-2 left-3 text-xs text-muted-foreground">{data.symbol}</div>
        ) : null}
        {dataDelay > 0 ? (
          <div className="absolute top-2 right-3 text-[10px] text-[color:var(--alert-warn)] font-mono pointer-events-none">
            延时 {dataDelay}m
          </div>
        ) : null}
        <canvas ref={canvasRef} aria-hidden="true" />
      </div>
    );
  }
);

OOrderbookDepth.displayName = 'OOrderbookDepth';
