/**
 * OTabFrame - Tab 切换容器。基于 @radix-ui/react-tabs (无障碍 + 键盘导航)。
 *
 * @example
 * <OTabFrame
 *   tabs={[
 *     { key: 'a', label: 'Overview', content: <OKPIGrid /> },
 *     { key: 'b', label: 'Detail', content: <ODataTable /> },
 *   ]}
 * />
 */
'use client';

import * as Tabs from '@radix-ui/react-tabs';
import { forwardRef, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OTabItem {
  key: string;
  label: ReactNode;
  content: ReactNode;
  disabled?: boolean;
}

const VARIANT_TRIGGER = {
  line:
    'border-b-2 border-transparent data-[state=active]:border-primary data-[state=active]:text-foreground text-muted-foreground hover:text-foreground px-4 py-2 transition-colors',
  pills:
    'rounded-md data-[state=active]:bg-primary data-[state=active]:text-primary-foreground text-muted-foreground hover:bg-muted px-4 py-1.5 transition-colors',
  underline:
    'relative data-[state=active]:text-primary text-muted-foreground hover:text-foreground px-4 py-2 transition-colors after:absolute after:left-0 after:right-0 after:bottom-0 after:h-px after:bg-primary after:scale-x-0 data-[state=active]:after:scale-x-100 after:transition-transform',
} as const;

const VARIANT_LIST = {
  line: 'flex border-b border-border',
  pills: 'inline-flex gap-1 p-1 bg-muted rounded-lg',
  underline: 'flex gap-1',
} as const;

export interface OTabFrameProps extends Omit<OBlockBaseProps, 'variant'> {
  tabs: OTabItem[];
  defaultTab?: string;
  /** 受控 value。 */
  value?: string;
  onChange?: (key: string) => void;
  variant?: keyof typeof VARIANT_TRIGGER;
  /** Tab list 对齐。 */
  align?: 'start' | 'center' | 'end';
}

export const OTabFrame = forwardRef<HTMLDivElement, OTabFrameProps>(function OTabFrame(
  { tabs, defaultTab, value, onChange, variant = 'line', align = 'start', className, theme: _t, size: _s },
  ref
) {
  const defaultVal = defaultTab ?? tabs[0]?.key;
  const alignClass =
    align === 'center' ? 'justify-center' : align === 'end' ? 'justify-end' : 'justify-start';

  return (
    <Tabs.Root
      ref={ref}
      defaultValue={defaultVal}
      value={value}
      onValueChange={onChange}
      className={cn('w-full', className)}
    >
      <Tabs.List className={cn(VARIANT_LIST[variant], alignClass)}>
        {tabs.map((t) => (
          <Tabs.Trigger
            key={t.key}
            value={t.key}
            disabled={t.disabled}
            className={cn(
              'text-sm font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring',
              'disabled:opacity-50 disabled:cursor-not-allowed',
              VARIANT_TRIGGER[variant]
            )}
          >
            {t.label}
          </Tabs.Trigger>
        ))}
      </Tabs.List>
      {tabs.map((t) => (
        <Tabs.Content
          key={t.key}
          value={t.key}
          className="pt-4 outline-none focus-visible:ring-2 focus-visible:ring-ring rounded"
        >
          {t.content}
        </Tabs.Content>
      ))}
    </Tabs.Root>
  );
});

OTabFrame.displayName = 'OTabFrame';
