/**
 * OOrderList - 委托列表 (当前委托 / 历史委托 / 成交记录)。
 *
 * 数据契约对齐 Binance ORDER_TRADE_UPDATE:
 *   o.s   = symbol
 *   o.S   = side (BUY/SELL)
 *   o.o   = orderType
 *   o.q   = origQty
 *   o.p   = origPrice
 *   o.ap  = avgPrice
 *   o.x   = executionType
 *   o.X   = orderStatus
 *   o.i   = orderId
 *   o.z   = cumQty (累计成交)
 *   o.R   = reduceOnly
 *   o.ps  = positionSide
 *   o.rp  = realizedProfit
 *
 * Tab 切换: 当前委托 / 历史委托 / 成交.
 */

'use client';

import { forwardRef, useEffect, useState, useMemo } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import { useFastData } from '../../providers/FastDataProvider';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';

export interface OOrder {
  orderId: string | number;
  symbol: string;
  side: 'BUY' | 'SELL';
  positionSide: 'LONG' | 'SHORT' | 'BOTH';
  type:
    | 'LIMIT'
    | 'MARKET'
    | 'STOP'
    | 'STOP_MARKET'
    | 'TAKE_PROFIT'
    | 'TAKE_PROFIT_MARKET'
    | 'TRAILING_STOP_MARKET';
  status:
    | 'NEW'
    | 'PARTIALLY_FILLED'
    | 'FILLED'
    | 'CANCELED'
    | 'REJECTED'
    | 'EXPIRED';
  origQty: number;
  /** 已成交数量. */
  filledQty: number;
  price?: number;
  /** 平均成交价. */
  avgPrice?: number;
  stopPrice?: number;
  reduceOnly?: boolean;
  /** 创建时间 (Unix ms). */
  time: number;
  /** 已实现盈亏 (历史委托 / 成交记录). */
  realizedPnl?: number;
  timeInForce?: 'GTC' | 'IOC' | 'FOK' | 'GTX';
}

export type OOrderTab = 'open' | 'history' | 'fills';

export interface OOrderListData {
  open: OOrder[];
  history?: OOrder[];
  fills?: OOrder[];
}

export interface OOrderListProps
  extends OBlockDataProps<OOrderListData>,
    Pick<TerminalBlockProps, 'channel' | 'flashOnUpdate' | 'dataDelay'> {
  /** 取消单个委托. */
  onCancel?: (order: OOrder) => void;
  /** 取消所有当前委托. */
  onCancelAll?: () => void;
  defaultTab?: OOrderTab;
  maxHeight?: number;
  /** 显示哪些 tab (默认全部). */
  tabs?: OOrderTab[];
}

function formatTime(ms: number): string {
  const d = new Date(ms);
  return `${d.getHours().toString().padStart(2, '0')}:${d.getMinutes().toString().padStart(2, '0')}:${d.getSeconds().toString().padStart(2, '0')}`;
}

function statusColor(s: OOrder['status']): string {
  switch (s) {
    case 'NEW':
    case 'PARTIALLY_FILLED':
      return 'var(--alert-info)';
    case 'FILLED':
      return 'var(--quote-up)';
    case 'CANCELED':
    case 'EXPIRED':
      return 'var(--text-muted)';
    case 'REJECTED':
      return 'var(--quote-down)';
    default:
      return 'var(--text-muted)';
  }
}

function statusLabel(s: OOrder['status']): string {
  return {
    NEW: '挂单中',
    PARTIALLY_FILLED: '部分成交',
    FILLED: '全部成交',
    CANCELED: '已取消',
    REJECTED: '已拒绝',
    EXPIRED: '已过期',
  }[s];
}

export const OOrderList = forwardRef<HTMLDivElement, OOrderListProps>(
  function OOrderList(
    {
      data: dataProp,
      loading,
      error,
      empty,
      channel,
      onCancel,
      onCancelAll,
      defaultTab = 'open',
      tabs = ['open', 'history', 'fills'],
      maxHeight = 320,
      flashOnUpdate: _f,
      dataDelay = 0,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const [tab, setTab] = useState<OOrderTab>(defaultTab);

    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OOrderListData | null>(null);
    useEffect(() => {
      if (!channel || !fastData) return;
      return fastData.subscribe<OOrderListData>(channel, setChannelData);
    }, [channel, fastData]);

    const data = channel ? channelData : (dataProp ?? null);
    const state = resolveBlockState({ data, loading, error, empty });

    const rows: OOrder[] = useMemo(() => {
      if (!data) return [];
      if (tab === 'open') return data.open;
      if (tab === 'history') return data.history ?? [];
      return data.fills ?? [];
    }, [data, tab]);

    if (state === 'loading')
      return (
        <div ref={ref} className={cn('rounded-md border border-border bg-card p-4', className)}>
          <OLoadingState rows={4} />
        </div>
      );
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;

    const tabLabel: Record<OOrderTab, string> = {
      open: `当前委托${data?.open.length ? ` (${data.open.length})` : ''}`,
      history: '历史委托',
      fills: '成交记录',
    };

    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card overflow-hidden flex flex-col relative @container',
          className
        )}
        style={{ fontFamily: 'var(--font-ui)' }}
      >
        {dataDelay > 0 ? (
          <div className="absolute top-2 right-3 z-10 text-[10px] text-[color:var(--alert-warn)] font-mono pointer-events-none">
            延时 {dataDelay}m
          </div>
        ) : null}

        {/* Tab + 全部取消 */}
        <div className="flex items-center border-b border-border">
          {tabs.map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => setTab(t)}
              className={cn(
                'px-3 py-2 text-xs',
                tab === t
                  ? 'text-[color:var(--foreground)] border-b-2 border-primary -mb-px'
                  : 'text-[color:var(--text-muted)] hover:text-[color:var(--foreground)]'
              )}
            >
              {tabLabel[t]}
            </button>
          ))}
          {tab === 'open' && onCancelAll && rows.length > 0 ? (
            <button
              type="button"
              onClick={onCancelAll}
              className="ml-auto mr-3 text-[10px] text-[color:var(--quote-down)] hover:underline"
            >
              全部取消
            </button>
          ) : null}
        </div>

        {/* 表头 */}
        <div
          className="grid px-3 py-1.5 text-[10px] text-[color:var(--text-muted)] uppercase border-b border-border bg-muted/20"
          style={{ gridTemplateColumns: '0.8fr 1.4fr 1fr 1fr 1.2fr 0.9fr 0.6fr' }}
        >
          <div>时间</div>
          <div>合约 / 类型</div>
          <div className="text-right">委托价</div>
          <div className="text-right">数量</div>
          <div className="text-right">{tab === 'fills' ? '成交价' : '已成交 / 状态'}</div>
          <div className="text-right">{tab === 'open' ? '减仓' : '已实现'}</div>
          <div className="text-right">操作</div>
        </div>

        {/* 行 */}
        <div style={{ maxHeight, overflowY: 'auto' }}>
          {rows.length === 0 ? (
            <OEmptyState
              title={tab === 'open' ? '没有当前委托' : tab === 'history' ? '没有历史委托' : '没有成交记录'}
              variant="minimal"
            />
          ) : (
            rows.map((o) => {
              const sideColor = o.side === 'BUY' ? 'var(--quote-up)' : 'var(--quote-down)';
              const realizedPositive = (o.realizedPnl ?? 0) >= 0;
              return (
                <div
                  key={o.orderId}
                  className="grid px-3 py-2 text-xs border-b border-border/50 items-center"
                  style={{ gridTemplateColumns: '0.8fr 1.4fr 1fr 1fr 1.2fr 0.9fr 0.6fr' }}
                >
                  <div className="text-[10px] text-[color:var(--text-muted)] font-mono">
                    {formatTime(o.time)}
                  </div>
                  <div className="min-w-0">
                    <div className="font-mono text-[color:var(--foreground)] flex items-center gap-1">
                      <span className="truncate">{o.symbol}</span>
                      <span
                        className="px-1 text-[9px] rounded font-bold text-white shrink-0"
                        style={{ background: sideColor }}
                      >
                        {o.side === 'BUY' ? '买' : '卖'}
                      </span>
                    </div>
                    <div className="text-[10px] text-[color:var(--text-muted)] font-mono">
                      {o.type}
                      {o.reduceOnly ? ' · 减仓' : ''}
                      {o.timeInForce === 'GTX' ? ' · GTX' : ''}
                    </div>
                  </div>
                  <div className="text-right tabular-nums font-mono text-[color:var(--foreground)]">
                    {o.type.includes('MARKET') ? '市价' : o.price?.toFixed(2) ?? '-'}
                  </div>
                  <div className="text-right tabular-nums font-mono text-[color:var(--foreground)]">
                    {o.origQty.toFixed(4)}
                  </div>
                  <div className="text-right">
                    {tab === 'fills' ? (
                      <div className="tabular-nums font-mono">{o.avgPrice?.toFixed(2) ?? '-'}</div>
                    ) : (
                      <>
                        <div className="tabular-nums font-mono">
                          {o.filledQty.toFixed(4)} / {o.origQty.toFixed(4)}
                        </div>
                        <div className="text-[10px] font-mono" style={{ color: statusColor(o.status) }}>
                          {statusLabel(o.status)}
                        </div>
                      </>
                    )}
                  </div>
                  <div
                    className="text-right tabular-nums font-mono"
                    style={{
                      color: o.realizedPnl != null
                        ? realizedPositive
                          ? 'var(--quote-up)'
                          : 'var(--quote-down)'
                        : 'var(--text-muted)',
                    }}
                  >
                    {tab === 'open'
                      ? o.reduceOnly
                        ? '是'
                        : '-'
                      : o.realizedPnl != null
                        ? `${realizedPositive ? '+' : ''}${o.realizedPnl.toFixed(2)}`
                        : '-'}
                  </div>
                  <div className="text-right">
                    {tab === 'open' && onCancel ? (
                      <button
                        type="button"
                        onClick={() => onCancel(o)}
                        className="text-[10px] text-[color:var(--quote-down)] hover:underline"
                      >
                        取消
                      </button>
                    ) : null}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
    );
  }
);

OOrderList.displayName = 'OOrderList';
