/**
 * ORegimeSegmentedTable (Tide Wave 3 E29, Block)
 *
 * 按 regime 分段的策略统计表(7 行 × N 列)。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §5.2
 */
import { forwardRef, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import { REGIME_LABEL, REGIME_COLOR_VAR, type RegimeState } from '../../types/tide';
import type { OBlockBaseProps } from '../../lib/types';

export interface RegimeSegmentedColumn<T> {
  key: keyof T;
  header: string;
  format?: (v: unknown, row: T) => ReactNode;
  align?: 'left' | 'right' | 'center';
}

export interface ORegimeSegmentedTableProps<
  T extends { regime: RegimeState } = { regime: RegimeState }
> extends Omit<OBlockBaseProps, 'variant'> {
  rows: T[];
  columns: RegimeSegmentedColumn<T>[];
  onRegimeClick?: (regime: RegimeState) => void;
}

export const ORegimeSegmentedTable = forwardRef<HTMLDivElement, ORegimeSegmentedTableProps>(
  function ORegimeSegmentedTable(
    { rows, columns, onRegimeClick, className, theme: _t, size: _s },
    ref
  ) {
    if (rows.length === 0) {
      return (
        <div
          ref={ref}
          className={cn('py-6 text-center text-sm border border-dashed rounded', className)}
          style={{ color: 'var(--text-tertiary)', borderColor: 'var(--border-strong)' }}
        >
          无 regime 分段数据
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn('flex flex-col w-full rounded',
          'bg-[color:var(--card)] border border-[color:var(--border-strong)]',
          className
        )}
        style={{ fontFamily: 'var(--font-mono)' }}
        role="table"
        aria-label="Regime 分段统计"
      >
        {/* header */}
        <div
          className="grid items-center px-2 py-1 border-b border-[color:var(--border-strong)]"
          style={{
            gridTemplateColumns: `80px repeat(${columns.length}, 1fr)`,
            fontSize: 10,
            color: 'var(--text-tertiary)',
            textTransform: 'uppercase',
          }}
          role="row"
        >
          <div role="columnheader">Regime</div>
          {columns.map((c) => (
            <div
              key={String(c.key)}
              role="columnheader"
              style={{ textAlign: c.align ?? 'right' }}
            >
              {c.header}
            </div>
          ))}
        </div>
        {/* rows */}
        {rows.map((r) => (
          <div
            key={r.regime}
            role="row"
            onClick={() => onRegimeClick?.(r.regime)}
            className={cn(
              'grid items-center px-2 py-1.5 text-xs @container',
              'border-b border-[color:var(--border-subtle)] last:border-b-0',
              onRegimeClick && 'cursor-pointer hover:bg-[color:var(--accent)]'
            )}
            style={{
              gridTemplateColumns: `80px repeat(${columns.length}, 1fr)`,
              color: 'var(--foreground)',
            }}
          >
            <div
              role="rowheader"
              className="flex items-center gap-1.5"
            >
              <span
                className="inline-block w-2 h-2 rounded-sm"
                style={{ backgroundColor: REGIME_COLOR_VAR[r.regime] }}
                aria-hidden="true"
              />
              <span>{REGIME_LABEL[r.regime]}</span>
            </div>
            {columns.map((c) => {
              const v = r[c.key];
              const content = c.format ? c.format(v, r) : (v as ReactNode);
              return (
                <div
                  key={String(c.key)}
                  role="cell"
                  className="truncate"
                  style={{ textAlign: c.align ?? 'right' }}
                >
                  {content}
                </div>
              );
            })}
          </div>
        ))}
      </div>
    );
  }
) as <T extends { regime: RegimeState }>(
  p: ORegimeSegmentedTableProps<T> & { ref?: React.Ref<HTMLDivElement> }
) => React.ReactElement;

(ORegimeSegmentedTable as unknown as { displayName?: string }).displayName = 'ORegimeSegmentedTable';
