/**
 * ODSLEditor (Tide Wave 3 E30, Block)
 *
 * DSL 编辑器(简化版 — Monaco 集成留 v2.x)。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §5.3
 *
 * 简化版特性:
 *   - textarea + 等宽字体
 *   - 行号
 *   - 错误高亮(简单 underline)
 *   - validate + run callback
 */
import { forwardRef, useCallback, useMemo, useState } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface DSLError {
  line: number;
  message: string;
}

export interface ODSLEditorProps extends Omit<OBlockBaseProps, 'variant'> {
  value: string;
  onChange?: (value: string) => void;
  errors?: DSLError[];
  language?: string;
  readOnly?: boolean;
  height?: number;
  onValidate?: () => void;
  onRun?: () => void;
  showLineNumbers?: boolean;
}

export const ODSLEditor = forwardRef<HTMLTextAreaElement, ODSLEditorProps>(
  function ODSLEditor(
    {
      value,
      onChange,
      errors = [],
      language = 'dsl',
      readOnly,
      height = 280,
      onValidate,
      onRun,
      showLineNumbers = true,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const [focused, setFocused] = useState(false);
    const lines = useMemo(() => value.split('\n'), [value]);
    const errorMap = useMemo(() => {
      const m = new Map<number, string>();
      for (const e of errors) m.set(e.line, e.message);
      return m;
    }, [errors]);

    const handleChange = useCallback(
      (e: React.ChangeEvent<HTMLTextAreaElement>) => onChange?.(e.target.value),
      [onChange]
    );

    return (
      <div
        className={cn(
          'flex flex-col rounded @container',
          'bg-[color:var(--card)] border',
          focused ? 'border-[color:var(--blue-accent)]' : 'border-[color:var(--border-strong)]',
          className
        )}
        style={{ fontFamily: 'var(--font-mono)' }}
      >
        {/* toolbar */}
        <div
          className="flex items-center justify-between px-2 py-1 border-b border-[color:var(--border-subtle)]"
          style={{ fontSize: 10, color: 'var(--text-tertiary)', textTransform: 'uppercase' }}
        >
          <span>{language}</span>
          <div className="flex gap-1">
            {onValidate && (
              <button
                type="button"
                onClick={onValidate}
                className="px-2 py-0.5 rounded text-[10px]"
                style={{
                  backgroundColor: 'var(--muted)',
                  color: 'var(--foreground)',
                }}
              >
                ✓ validate
              </button>
            )}
            {onRun && (
              <button
                type="button"
                onClick={onRun}
                className="px-2 py-0.5 rounded text-[10px] font-bold"
                style={{
                  backgroundColor: 'var(--blue-accent)',
                  color: '#fff',
                }}
              >
                ▶ run
              </button>
            )}
          </div>
        </div>

        <div className="flex" style={{ height }}>
          {showLineNumbers && (
            <div
              aria-hidden="true"
              className="px-1 py-1 text-right shrink-0 select-none overflow-hidden"
              style={{
                backgroundColor: 'var(--muted)',
                color: 'var(--text-tertiary)',
                fontSize: 11,
                fontFamily: 'var(--font-mono)',
                minWidth: 28,
                lineHeight: '1.5em',
              }}
            >
              {lines.map((_, i) => {
                const lineNo = i + 1;
                const hasErr = errorMap.has(lineNo);
                return (
                  <div
                    key={lineNo}
                    style={{
                      color: hasErr ? 'var(--red-up)' : undefined,
                      fontWeight: hasErr ? 700 : 400,
                    }}
                  >
                    {lineNo}
                  </div>
                );
              })}
            </div>
          )}
          <textarea
            ref={ref}
            value={value}
            onChange={handleChange}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            readOnly={readOnly}
            spellCheck={false}
            aria-label="DSL editor"
            className="flex-1 px-2 py-1 resize-none outline-none"
            style={{
              backgroundColor: 'transparent',
              color: 'var(--foreground)',
              fontFamily: 'var(--font-mono)',
              fontSize: 12,
              lineHeight: '1.5em',
              border: 'none',
            }}
          />
        </div>

        {errors.length > 0 && (
          <div
            className="px-2 py-1 border-t border-[color:var(--border-subtle)] flex flex-col gap-0.5"
            role="alert"
          >
            {errors.map((e, i) => (
              <div
                key={i}
                className="text-[10px]"
                style={{ color: 'var(--red-up)', fontFamily: 'var(--font-mono)' }}
              >
                line {e.line}: {e.message}
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }
);

ODSLEditor.displayName = 'ODSLEditor';
