/**
 * OStageDotProgress — 长任务 stage 进度 dot 显示
 *
 * 直接消费 BatchJob.stages,**任何 BatchJob 都可用**。
 *
 * 来源: hevi advisor R3 §1.2 (2026-05-22) — BatchJob 配套必须
 * 跨项目场景:
 *   - hevi pipeline 7 stage (script → storyboard → image → wav2lip → mix → assembly)
 *   - Stratum agent_run stage (reading_companion / meta_analyzer / etc)
 *   - Aegis playbook step (detect → isolate → reroute → notify)
 *   - Selene long task (backfill chunks / offline analysis steps)
 *   - Helivex daily_anchor (compute_merkle → ots_submit → cf_tsa → confirm_wait)
 *
 * 6 状态对应 dot 颜色:
 *   pending     → 灰
 *   running     → 蓝色 + pulse (reduced-motion 时禁用)
 *   succeeded   → 绿
 *   failed      → 红 + ✕ 图标
 *   skipped     → 灰 + - 图标
 *
 * 紧凑模式 (compact=true):
 *   - 仅 dot,无 label
 *   - 适合 ODataTable 行内显示
 *
 * 完整模式 (compact=false,默认):
 *   - dot + label (中文)
 *   - 横向 / 纵向布局选择
 *
 * a11y:
 *   - 整体 role="list" + aria-label="任务进度"
 *   - 每个 stage 是 role="listitem" + aria-label="{label}: {状态}"
 *   - failed stage 用 aria-describedby 关联 error.message
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';
import type { BatchJobStage, BatchJobStageStatus } from '../../types/batch-job';

// ============================================================
// dot 视觉变体
// ============================================================

const dotVariants = cva(
  'inline-flex items-center justify-center rounded-full transition-colors',
  {
    variants: {
      status: {
        pending: 'bg-muted border border-border',
        running: 'bg-info text-info-foreground',
        succeeded: 'bg-success text-success-foreground',
        failed: 'bg-destructive text-destructive-foreground',
        skipped: 'bg-muted text-muted-foreground border border-border',
      },
      size: {
        sm: 'w-2 h-2 text-[8px]',
        md: 'w-3 h-3 text-[10px]',
        lg: 'w-4 h-4 text-xs',
      },
    },
    defaultVariants: {
      status: 'pending',
      size: 'sm',
    },
  }
);

type DotVariantProps = VariantProps<typeof dotVariants>;

// ============================================================
// 状态 → 中文 label 映射(无障碍朗读用)
// ============================================================

const STATUS_LABELS: Record<BatchJobStageStatus, string> = {
  pending: '待执行',
  running: '执行中',
  succeeded: '已完成',
  failed: '失败',
  skipped: '已跳过',
};

// ============================================================
// 单 dot 子组件
// ============================================================

interface StageDotProps {
  stage: BatchJobStage;
  size: NonNullable<DotVariantProps['size']>;
  reduced: boolean;
  onClick?: (stage: BatchJobStage) => void;
}

function StageDot({ stage, size, reduced, onClick }: StageDotProps) {
  const isRunning = stage.status === 'running';
  const isClickable = !!onClick;
  const fullLabel = `${stage.label}:${STATUS_LABELS[stage.status]}`;

  const dot = (
    <span
      className={cn(
        dotVariants({ status: stage.status, size }),
        isRunning && !reduced && 'animate-pulse',
        isClickable && 'cursor-pointer hover:ring-2 hover:ring-ring/40'
      )}
      role="img"
      aria-label={fullLabel}
      title={fullLabel}
    >
      {stage.status === 'failed' ? '✕' : stage.status === 'skipped' ? '−' : null}
    </span>
  );

  if (!isClickable) {
    return dot;
  }

  return (
    <button
      type="button"
      className="inline-flex items-center"
      onClick={() => onClick?.(stage)}
      aria-label={fullLabel}
    >
      {dot}
    </button>
  );
}

// ============================================================
// 主组件 Props
// ============================================================

export interface OStageDotProgressProps
  extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  /** BatchJob.stages 数组。直接传入,自动渲染。 */
  stages: BatchJobStage[];
  /** dot 大小。 */
  size?: NonNullable<DotVariantProps['size']>;
  /**
   * 紧凑模式 — 仅 dot,无 label。
   * 适合 ODataTable 行内或仪表盘缩略视图。
   */
  compact?: boolean;
  /** 布局方向。 */
  orientation?: 'horizontal' | 'vertical';
  /**
   * 失败 stage 是否高亮(红色边框 + 图标加粗)。
   * 默认 true。
   */
  emphasizeFailed?: boolean;
  /**
   * dot 点击回调(可选)。
   * 传了表示 dot 可点(详情页跳转 / 弹 stage modal)。
   */
  onStageClick?: (stage: BatchJobStage) => void;
}

// ============================================================
// 主组件
// ============================================================

export const OStageDotProgress = forwardRef<HTMLDivElement, OStageDotProgressProps>(
  function OStageDotProgress(
    {
      stages,
      size = 'sm',
      compact = false,
      orientation = 'horizontal',
      emphasizeFailed: _emphasizeFailed = true,
      onStageClick,
      className,
      theme: _t,
    },
    ref
  ) {
    const reduced = useReducedMotion();

    // 空数组兜底
    if (!stages || stages.length === 0) {
      return (
        <div
          ref={ref}
          className={cn('text-xs text-muted-foreground italic', className)}
        >
          (无 stage)
        </div>
      );
    }

    const containerCls = cn(
      'inline-flex',
      orientation === 'horizontal' ? 'flex-row items-center gap-1.5' : 'flex-col items-start gap-1.5',
      className
    );

    // 紧凑模式 — 仅 dot 排列
    if (compact) {
      return (
        <div
          ref={ref}
          className={containerCls}
          role="list"
          aria-label="任务进度"
        >
          {stages.map((stage) => (
            <span key={stage.id} role="listitem">
              <StageDot
                stage={stage}
                size={size}
                reduced={reduced}
                {...(onStageClick && { onClick: onStageClick })}
              />
            </span>
          ))}
        </div>
      );
    }

    // 完整模式 — dot + label
    return (
      <div
        ref={ref}
        className={cn(
          'flex @container',
          orientation === 'horizontal'
            ? 'flex-row items-center gap-3 flex-wrap'
            : 'flex-col items-start gap-2',
          className
        )}
        role="list"
        aria-label="任务进度"
      >
        {stages.map((stage, idx) => (
          <div
            key={stage.id}
            role="listitem"
            className="inline-flex items-center gap-1.5"
          >
            <StageDot
              stage={stage}
              size={size}
              reduced={reduced}
              {...(onStageClick && { onClick: onStageClick })}
            />
            <span
              className={cn(
                'text-xs',
                stage.status === 'pending' && 'text-muted-foreground',
                stage.status === 'running' && 'text-foreground font-medium',
                stage.status === 'succeeded' && 'text-foreground',
                stage.status === 'failed' && 'text-destructive font-medium',
                stage.status === 'skipped' && 'text-muted-foreground line-through'
              )}
            >
              {stage.label}
            </span>
            {orientation === 'horizontal' && idx < stages.length - 1 && (
              <span className="text-muted-foreground/40 select-none" aria-hidden="true">
                →
              </span>
            )}
          </div>
        ))}
      </div>
    );
  }
);

OStageDotProgress.displayName = 'OStageDotProgress';
