'use client';
import { forwardRef, type ComponentPropsWithoutRef, type ElementRef } from 'react';
import * as AccordionPrimitive from '@radix-ui/react-accordion';
import { cn } from '../../lib/cn';
import { accordionItemRecipe, accordionTriggerRecipe, accordionContentRecipe } from '../../recipes';

export const OAccordion = AccordionPrimitive.Root;

export const OAccordionSection = forwardRef<
  ElementRef<typeof AccordionPrimitive.Item>,
  ComponentPropsWithoutRef<typeof AccordionPrimitive.Item>
>(function OAccordionSection({ className, ...props }, ref) {
  return <AccordionPrimitive.Item ref={ref} className={cn(accordionItemRecipe(), className)} {...props} />;
});
OAccordionSection.displayName = 'OAccordionSection';

export const OAccordionSectionTrigger = forwardRef<
  ElementRef<typeof AccordionPrimitive.Trigger>,
  ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger>
>(function OAccordionSectionTrigger({ className, children, ...props }, ref) {
  return (
    <AccordionPrimitive.Header className="flex">
      <AccordionPrimitive.Trigger ref={ref} className={cn(accordionTriggerRecipe(), className)} {...props}>
        {children}
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
          <path d="M4 6l4 4 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
        </svg>
      </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
  );
});
OAccordionSectionTrigger.displayName = 'OAccordionSectionTrigger';

export const OAccordionSectionContent = forwardRef<
  ElementRef<typeof AccordionPrimitive.Content>,
  ComponentPropsWithoutRef<typeof AccordionPrimitive.Content>
>(function OAccordionSectionContent({ className, children, ...props }, ref) {
  return (
    <AccordionPrimitive.Content ref={ref} className={accordionContentRecipe()} {...props}>
      <div className={cn('pb-4 pt-0', className)}>{children}</div>
    </AccordionPrimitive.Content>
  );
});
OAccordionSectionContent.displayName = 'OAccordionSectionContent';
