'use client';
import { forwardRef, createContext, useContext, useState, type HTMLAttributes } from 'react';
import { cn } from '../../lib/cn';
import { checkboxRecipe } from '../../recipes';

interface RadioCtx { value?: string; onValueChange?: (v: string) => void; name: string; }
const Ctx = createContext<RadioCtx | null>(null);

export interface ORadioGroupProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  name?: string;
}

export const ORadioGroup = forwardRef<HTMLDivElement, ORadioGroupProps>(
  function ORadioGroup({ value, defaultValue, onValueChange, name, className, children, ...rest }, ref) {
    const [internal, setInternal] = useState(defaultValue);
    const current = value !== undefined ? value : internal;
    const groupName = name || `rg-${Math.random().toString(36).slice(2,8)}`;
    return (
      <Ctx.Provider value={{
        value: current, name: groupName,
        onValueChange: v => { if (value === undefined) setInternal(v); onValueChange?.(v); },
      }}>
        <div ref={ref} role="radiogroup" className={cn('flex flex-col gap-3', className)} {...rest}>
          {children}
        </div>
      </Ctx.Provider>
    );
  }
);
ORadioGroup.displayName = 'ORadioGroup';

export interface ORadioProps { value: string; label?: string; disabled?: boolean; }
export function ORadio({ value, label, disabled }: ORadioProps) {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error('ORadio must be used within ORadioGroup');
  const checked = ctx.value === value;
  const id = `${ctx.name}-${value}`;
  return (
    <label htmlFor={id} className={cn('inline-flex items-center gap-2', disabled ? 'cursor-not-allowed opacity-50' : 'cursor-pointer')}>
      <input
        id={id} type="radio" name={ctx.name} value={value} checked={checked} disabled={disabled}
        className="sr-only peer" onChange={() => ctx.onValueChange?.(value)}
      />
      <span data-checked={checked} className={cn(checkboxRecipe({ shape: 'circle', size: 'md' }), 'flex items-center justify-center')}>
        {checked && <span className="size-2 rounded-full bg-[color:var(--primary-foreground)]" />}
      </span>
      {label && <span className="text-[length:var(--text-sm)] select-none">{label}</span>}
    </label>
  );
}
