/**
 * OTradePanel - 合约下单面板。
 *
 * Helios 合约交易终端的核心 Block。
 *
 * 功能:
 *   - 限价 / 市价 / 触发单 / 止盈止损 / 跟踪委托
 *   - 多仓 / 空仓 (双向持仓模式)
 *   - 杠杆调节 (集成 OLeverageSlider)
 *   - 保证金模式 (逐仓 / 全仓)
 *   - TP/SL 同时挂单
 *   - 仓位百分比快捷 (25% / 50% / 75% / 100%)
 *   - 数量 vs 保证金 vs 倍数 三种输入模式
 *   - 强平价格预估
 *   - 滑点保护 (市价单时)
 *
 * 数据契约 (与 Binance / OKX / Bybit 合约 API 对齐):
 *   symbol:        BTCUSDT
 *   markPrice:     mark price (用于强平估算)
 *   indexPrice:    指数价格
 *   leverage:      当前杠杆
 *   marginMode:    isolated | cross
 *   positionMode:  one-way | hedge
 *   walletBalance: 钱包余额 (USDT)
 *   availableBalance: 可用余额
 *   maxLeverage:   品种最大杠杆 (例如 125x)
 *
 * 提交格式 (onSubmit 回调):
 *   {
 *     side: 'BUY' | 'SELL',
 *     positionSide: 'LONG' | 'SHORT' | 'BOTH',
 *     type: 'LIMIT' | 'MARKET' | 'STOP' | 'STOP_MARKET' | 'TAKE_PROFIT' | 'TAKE_PROFIT_MARKET' | 'TRAILING_STOP_MARKET',
 *     quantity: number,
 *     price?: number,
 *     stopPrice?: number,
 *     tp?: number,       // 止盈
 *     sl?: number,       // 止损
 *     reduceOnly?: boolean,
 *     timeInForce?: 'GTC' | 'IOC' | 'FOK' | 'GTX',
 *   }
 */

'use client';

import { forwardRef, useEffect, useMemo, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { useFastData } from '../../providers/FastDataProvider';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';

// ============================================================
// 数据契约
// ============================================================

export interface OTradePanelData {
  symbol: string;
  /** 标的全名,如 "BTC/USDT 永续". */
  symbolDisplay?: string;
  markPrice: number;
  indexPrice?: number;
  /** 当前用户在此 symbol 的杠杆. */
  leverage: number;
  /** 最大杠杆. */
  maxLeverage: number;
  /** 保证金模式. */
  marginMode: 'isolated' | 'cross';
  /** 持仓模式. */
  positionMode: 'one-way' | 'hedge';
  /** 钱包余额 (USDT). */
  walletBalance: number;
  availableBalance: number;
  /** 当前持仓 (用于 reduceOnly + 仓位预估). */
  currentPosition?: {
    side: 'LONG' | 'SHORT' | 'BOTH';
    amount: number;
    entryPrice: number;
  } | null;
  /** 维持保证金率 (用于强平价估算). */
  maintMarginRate?: number;
  /** 手续费率. */
  takerFee?: number;
  makerFee?: number;
}

// ============================================================
// 提交事件
// ============================================================

export type OrderType =
  | 'LIMIT'
  | 'MARKET'
  | 'STOP'
  | 'STOP_MARKET'
  | 'TAKE_PROFIT'
  | 'TAKE_PROFIT_MARKET'
  | 'TRAILING_STOP_MARKET';

export interface TradeOrderRequest {
  symbol: string;
  side: 'BUY' | 'SELL';
  positionSide: 'LONG' | 'SHORT' | 'BOTH';
  type: OrderType;
  quantity: number;
  price?: number;
  stopPrice?: number;
  /** 同时挂止盈 (绝对价). */
  tp?: number;
  /** 同时挂止损 (绝对价). */
  sl?: number;
  reduceOnly?: boolean;
  timeInForce?: 'GTC' | 'IOC' | 'FOK' | 'GTX';
}

// ============================================================
// Props
// ============================================================

export interface OTradePanelProps
  extends OBlockDataProps<OTradePanelData>,
    Pick<TerminalBlockProps, 'channel' | 'dataDelay' | 'regulation' | 'lowPerformanceMode'> {
  /** 用户点击下单按钮的回调. */
  onSubmit?: (order: TradeOrderRequest) => void | Promise<void>;
  /** 杠杆调整回调 (打开 OLeverageSlider). */
  onLeverageChange?: (leverage: number) => void;
  /** 保证金模式切换. */
  onMarginModeChange?: (mode: 'isolated' | 'cross') => void;
  /** 默认显示哪个 tab. */
  defaultTab?: 'limit' | 'market' | 'trigger';
  /** 默认买/卖 (默认 'buy'). */
  defaultSide?: 'buy' | 'sell';
  /** 是否显示 TP/SL 输入. */
  showTpSl?: boolean;
  /** 紧凑模式 (隐藏次要元素). */
  compact?: boolean;
}

// ============================================================
// 强平价格估算 (简化版)
// ============================================================

function estimateLiquidationPrice({
  side,
  entryPrice,
  leverage,
  maintMarginRate = 0.005,
}: {
  side: 'BUY' | 'SELL';
  entryPrice: number;
  leverage: number;
  maintMarginRate?: number;
}): number {
  // 简化公式 (实际需要看仓位 + 保证金,这里给个估算给用户参考)
  // 多: 强平价 ≈ 入场价 × (1 - 1/lev + maint)
  // 空: 强平价 ≈ 入场价 × (1 + 1/lev - maint)
  if (side === 'BUY') {
    return entryPrice * (1 - 1 / leverage + maintMarginRate);
  } else {
    return entryPrice * (1 + 1 / leverage - maintMarginRate);
  }
}

// ============================================================
// 子组件: 紧凑数字输入
// ============================================================

function NumInput({
  value,
  onChange,
  placeholder,
  suffix,
  disabled,
  step,
}: {
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  suffix?: string;
  disabled?: boolean;
  step?: number;
}) {
  return (
    <div
      className={cn(
        'flex items-center border border-border rounded bg-[color:var(--input)] @container',
        'focus-within:border-ring',
        disabled && 'opacity-50'
      )}
    >
      <input
        type="text"
        inputMode="decimal"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
        className="flex-1 bg-transparent px-2 py-1.5 text-sm tabular-nums outline-none text-[color:var(--foreground)]"
        style={{ fontFamily: 'var(--font-data)' }}
        step={step}
      />
      {suffix ? (
        <span className="px-2 text-xs text-[color:var(--text-muted)] shrink-0">{suffix}</span>
      ) : null}
    </div>
  );
}

function QtyShortcut({
  pct,
  onClick,
  disabled,
}: {
  pct: number;
  onClick: () => void;
  disabled?: boolean;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      className={cn(
        'flex-1 py-1 text-[10px] rounded border border-border text-[color:var(--text-muted)]',
        'hover:bg-muted hover:text-[color:var(--foreground)]',
        'disabled:opacity-40 disabled:cursor-not-allowed'
      )}
    >
      {pct}%
    </button>
  );
}

// ============================================================
// 主组件
// ============================================================

export const OTradePanel = forwardRef<HTMLDivElement, OTradePanelProps>(
  function OTradePanel(
    {
      data: dataProp,
      loading,
      error,
      empty,
      channel,
      onSubmit,
      onLeverageChange,
      onMarginModeChange,
      defaultTab = 'limit',
      defaultSide = 'buy',
      showTpSl = true,
      compact = false,
      dataDelay = 0,
      regulation: _r,
      lowPerformanceMode: _l,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    // Channel 订阅
    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OTradePanelData | null>(null);
    useEffect(() => {
      if (!channel || !fastData) return;
      return fastData.subscribe<OTradePanelData>(channel, setChannelData);
    }, [channel, fastData]);

    const data = channel ? channelData : (dataProp ?? null);
    const state = resolveBlockState({ data, loading, error, empty });

    // UI state
    const [tab, setTab] = useState<'limit' | 'market' | 'trigger'>(defaultTab);
    const [side, setSide] = useState<'buy' | 'sell'>(defaultSide);
    const [price, setPrice] = useState('');
    const [stopPrice, setStopPrice] = useState('');
    const [quantity, setQuantity] = useState('');
    const [tp, setTp] = useState('');
    const [sl, setSl] = useState('');
    const [reduceOnly, setReduceOnly] = useState(false);
    const [postOnly, setPostOnly] = useState(false);

    // 自动填入 markPrice 作为限价单默认价
    useEffect(() => {
      if (data && tab === 'limit' && !price) {
        setPrice(data.markPrice.toFixed(2));
      }
    }, [data, tab, price]);

    // 估算
    const estimates = useMemo(() => {
      if (!data) return null;
      const qty = parseFloat(quantity) || 0;
      const entryPrice =
        tab === 'market' ? data.markPrice : parseFloat(price) || data.markPrice;
      const cost = (qty * entryPrice) / Math.max(data.leverage, 1);
      const liqPrice = estimateLiquidationPrice({
        side: side === 'buy' ? 'BUY' : 'SELL',
        entryPrice,
        leverage: data.leverage,
        maintMarginRate: data.maintMarginRate,
      });
      const fee = qty * entryPrice * (data.takerFee ?? 0.0004);
      return { cost, liqPrice, fee, entryPrice };
    }, [data, quantity, price, tab, side]);

    function handleQuickQty(pct: number) {
      if (!data || !estimates) return;
      const maxNotional = data.availableBalance * data.leverage;
      const maxQty = maxNotional / estimates.entryPrice;
      setQuantity(((maxQty * pct) / 100).toFixed(4));
    }

    function handleSubmit() {
      if (!data || !onSubmit) return;
      const qty = parseFloat(quantity);
      if (!qty || qty <= 0) return;
      const req: TradeOrderRequest = {
        symbol: data.symbol,
        side: side === 'buy' ? 'BUY' : 'SELL',
        positionSide:
          data.positionMode === 'hedge'
            ? side === 'buy'
              ? 'LONG'
              : 'SHORT'
            : 'BOTH',
        type:
          tab === 'limit'
            ? 'LIMIT'
            : tab === 'market'
              ? 'MARKET'
              : stopPrice
                ? 'STOP'
                : 'STOP_MARKET',
        quantity: qty,
        price: tab === 'limit' ? parseFloat(price) || undefined : undefined,
        stopPrice: tab === 'trigger' ? parseFloat(stopPrice) || undefined : undefined,
        tp: showTpSl ? parseFloat(tp) || undefined : undefined,
        sl: showTpSl ? parseFloat(sl) || undefined : undefined,
        reduceOnly: reduceOnly || undefined,
        timeInForce: postOnly ? 'GTX' : 'GTC',
      };
      void onSubmit(req);
    }

    // 状态分流
    if (state === 'loading')
      return (
        <div
          ref={ref}
          className={cn(
            'rounded-md border border-border bg-card p-4',
            className
          )}
        >
          <OLoadingState rows={6} />
        </div>
      );
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data || !estimates) return null;

    const sideColor = side === 'buy' ? 'var(--quote-up)' : 'var(--quote-down)';
    const sideLabel = side === 'buy' ? '买入做多' : '卖出做空';

    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card flex flex-col',
          className
        )}
        style={{ fontFamily: 'var(--font-ui)' }}
      >
        {/* Header: 杠杆 + 保证金模式 + symbol */}
        <div className="flex items-center justify-between px-3 py-2 border-b border-border">
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() =>
                onMarginModeChange?.(data.marginMode === 'isolated' ? 'cross' : 'isolated')
              }
              className="px-2 py-0.5 text-[10px] rounded border border-border text-[color:var(--text-muted)] hover:bg-muted"
            >
              {data.marginMode === 'isolated' ? '逐仓' : '全仓'}
            </button>
            <button
              type="button"
              onClick={() => {
                const next = Math.min(data.leverage * 2, data.maxLeverage);
                onLeverageChange?.(next);
              }}
              className="px-2 py-0.5 text-[10px] rounded border border-border text-[color:var(--text-muted)] hover:bg-muted font-mono"
            >
              {data.leverage}x
            </button>
          </div>
          <div className="flex items-center gap-2 text-[10px] text-[color:var(--text-muted)]">
            {dataDelay > 0 ? (
              <span className="text-[color:var(--alert-warn)]">延时 {dataDelay}m</span>
            ) : null}
            <span className="font-mono">{data.symbolDisplay ?? data.symbol}</span>
          </div>
        </div>

        {/* Tabs: 限价 / 市价 / 触发 */}
        <div className="flex border-b border-border">
          {(['limit', 'market', 'trigger'] as const).map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => setTab(t)}
              className={cn(
                'flex-1 py-2 text-xs',
                tab === t
                  ? 'text-[color:var(--foreground)] border-b-2 border-primary -mb-px'
                  : 'text-[color:var(--text-muted)] hover:text-[color:var(--foreground)]'
              )}
            >
              {t === 'limit' ? '限价' : t === 'market' ? '市价' : '触发'}
            </button>
          ))}
        </div>

        {/* Buy / Sell tabs */}
        <div className="grid grid-cols-2 gap-2 p-2">
          <button
            type="button"
            onClick={() => setSide('buy')}
            className={cn(
              'py-2 rounded text-sm font-semibold transition-colors',
              side === 'buy'
                ? 'text-white'
                : 'text-[color:var(--text-muted)] bg-muted/40 hover:bg-muted'
            )}
            style={{
              background: side === 'buy' ? 'var(--quote-up)' : undefined,
            }}
          >
            做多 (Buy)
          </button>
          <button
            type="button"
            onClick={() => setSide('sell')}
            className={cn(
              'py-2 rounded text-sm font-semibold transition-colors',
              side === 'sell'
                ? 'text-white'
                : 'text-[color:var(--text-muted)] bg-muted/40 hover:bg-muted'
            )}
            style={{
              background: side === 'sell' ? 'var(--quote-down)' : undefined,
            }}
          >
            做空 (Sell)
          </button>
        </div>

        {/* 输入区 */}
        <div className="px-3 pb-3 flex flex-col gap-2">
          {/* 可用余额 */}
          <div className="flex items-center justify-between text-[10px] text-[color:var(--text-muted)]">
            <span>可用</span>
            <span className="tabular-nums font-mono">
              {data.availableBalance.toFixed(2)} USDT
            </span>
          </div>

          {/* 价格 (limit / trigger 才显示) */}
          {tab !== 'market' ? (
            <div>
              <label className="text-[10px] text-[color:var(--text-muted)] mb-1 block">
                {tab === 'limit' ? '委托价' : '触发价'}
              </label>
              <NumInput
                value={tab === 'limit' ? price : stopPrice}
                onChange={tab === 'limit' ? setPrice : setStopPrice}
                placeholder={data.markPrice.toFixed(2)}
                suffix="USDT"
              />
            </div>
          ) : (
            <div className="text-[10px] text-[color:var(--text-muted)]">
              市价单按当前最优价立即成交
            </div>
          )}

          {/* 数量 */}
          <div>
            <label className="text-[10px] text-[color:var(--text-muted)] mb-1 block">
              数量
            </label>
            <NumInput
              value={quantity}
              onChange={setQuantity}
              placeholder="0.000"
              suffix={data.symbol.replace('USDT', '')}
            />
          </div>

          {/* 仓位百分比快捷 */}
          <div className="flex gap-1">
            <QtyShortcut pct={25} onClick={() => handleQuickQty(25)} />
            <QtyShortcut pct={50} onClick={() => handleQuickQty(50)} />
            <QtyShortcut pct={75} onClick={() => handleQuickQty(75)} />
            <QtyShortcut pct={100} onClick={() => handleQuickQty(100)} />
          </div>

          {/* TP / SL */}
          {showTpSl && !compact ? (
            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="text-[10px] text-[color:var(--quote-up)] mb-1 block">
                  止盈
                </label>
                <NumInput value={tp} onChange={setTp} placeholder="-" suffix="USDT" />
              </div>
              <div>
                <label className="text-[10px] text-[color:var(--quote-down)] mb-1 block">
                  止损
                </label>
                <NumInput value={sl} onChange={setSl} placeholder="-" suffix="USDT" />
              </div>
            </div>
          ) : null}

          {/* Flags */}
          {!compact ? (
            <div className="flex items-center gap-3 text-[10px] text-[color:var(--text-muted)]">
              <label className="inline-flex items-center gap-1 cursor-pointer">
                <input
                  type="checkbox"
                  checked={reduceOnly}
                  onChange={(e) => setReduceOnly(e.target.checked)}
                  className="accent-[color:var(--primary)]"
                />
                只减仓
              </label>
              <label className="inline-flex items-center gap-1 cursor-pointer">
                <input
                  type="checkbox"
                  checked={postOnly}
                  onChange={(e) => setPostOnly(e.target.checked)}
                  disabled={tab !== 'limit'}
                  className="accent-[color:var(--primary)]"
                />
                只做 Maker (GTX)
              </label>
            </div>
          ) : null}

          {/* 估算信息 */}
          <div className="mt-1 pt-2 border-t border-border/50 flex flex-col gap-1 text-[10px]">
            <div className="flex justify-between text-[color:var(--text-muted)]">
              <span>所需保证金</span>
              <span className="tabular-nums font-mono text-[color:var(--foreground)]">
                {estimates.cost.toFixed(2)} USDT
              </span>
            </div>
            <div className="flex justify-between text-[color:var(--text-muted)]">
              <span>预估强平价</span>
              <span
                className="tabular-nums font-mono"
                style={{ color: 'var(--alert-warn)' }}
              >
                {estimates.liqPrice.toFixed(2)} USDT
              </span>
            </div>
            <div className="flex justify-between text-[color:var(--text-muted)]">
              <span>手续费 (taker)</span>
              <span className="tabular-nums font-mono">
                {estimates.fee.toFixed(4)} USDT
              </span>
            </div>
          </div>

          {/* 提交 */}
          <button
            type="button"
            onClick={handleSubmit}
            disabled={!quantity || parseFloat(quantity) <= 0}
            className={cn(
              'w-full py-2.5 rounded text-sm font-bold mt-1 transition-opacity',
              'hover:opacity-90 active:opacity-80',
              'disabled:opacity-40 disabled:cursor-not-allowed text-white'
            )}
            style={{ background: sideColor }}
          >
            {sideLabel}
          </button>
        </div>
      </div>
    );
  }
);

OTradePanel.displayName = 'OTradePanel';
