/**
 * OProgressBar - 进度条。
 *
 * 两种形态:
 *   - linear (默认): 长条形,适合页面/任务进度
 *   - circular:    圆环形,适合 inline / 单个操作
 *
 * indeterminate 模式: value 为 null 时显示永动动画。
 * reduced-motion 下 indeterminate 退化为静态进度条 (50%)。
 */
'use client';

import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

const KIND_COLOR: Record<string, string> = {
  default: 'var(--primary)',
  success: 'var(--success)',
  warning: 'var(--warning)',
  error: 'var(--destructive)',
};

export interface OProgressBarProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  /** 0-100,null = indeterminate。 */
  value?: number | null;
  /** 形态。 */
  variant?: 'linear' | 'circular';
  /** 尺寸。linear 控制高度,circular 控制直径。 */
  size?: 'sm' | 'md' | 'lg';
  /** 配色。 */
  kind?: 'default' | 'success' | 'warning' | 'error';
  /** 是否显示数值。 */
  showValue?: boolean;
  /** label (放在进度条上方)。 */
  label?: string;
  /** 自定义格式化数值显示。 */
  format?: (v: number) => string;
}

const LINEAR_HEIGHT = { sm: 'h-1', md: 'h-2', lg: 'h-3' };
const CIRCULAR_SIZE = { sm: 32, md: 48, lg: 72 };

function LinearBar({
  value,
  size,
  kind,
  reduced,
  ariaLabel,
}: {
  value: number | null;
  size: 'sm' | 'md' | 'lg';
  kind: NonNullable<OProgressBarProps['kind']>;
  reduced: boolean;
  ariaLabel?: string;
}) {
  const isIndeterminate = value == null;
  const color = KIND_COLOR[kind];
  return (
    <div
      role="progressbar"
      aria-label={ariaLabel ?? 'progress'}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={isIndeterminate ? undefined : value}
      aria-busy={isIndeterminate}
      className={cn('w-full bg-muted rounded-full overflow-hidden @container', LINEAR_HEIGHT[size])}
    >
      {isIndeterminate ? (
        reduced ? (
          <div className="h-full" style={{ width: '50%', backgroundColor: color }} />
        ) : (
          <div
            className="h-full rounded-full"
            style={{
              backgroundColor: color,
              width: '40%',
              animation: 'helios-progress-indeterminate 1.6s ease-in-out infinite',
            }}
          />
        )
      ) : (
        <div
          className="h-full rounded-full transition-all duration-300"
          style={{ width: `${Math.max(0, Math.min(100, value))}%`, backgroundColor: color }}
        />
      )}
      <style>{`
@keyframes helios-progress-indeterminate {
  0%   { transform: translateX(-100%); }
  100% { transform: translateX(280%); }
}
      `}</style>
    </div>
  );
}

function CircularRing({
  value,
  size,
  kind,
  reduced,
  ariaLabel,
}: {
  value: number | null;
  size: 'sm' | 'md' | 'lg';
  kind: NonNullable<OProgressBarProps['kind']>;
  reduced: boolean;
  ariaLabel?: string;
}) {
  const dim = CIRCULAR_SIZE[size];
  const stroke = size === 'sm' ? 3 : size === 'lg' ? 6 : 4;
  const r = (dim - stroke) / 2;
  const C = 2 * Math.PI * r;
  const isIndeterminate = value == null;
  const v = isIndeterminate ? 25 : Math.max(0, Math.min(100, value));
  const dashOffset = C - (v / 100) * C;
  const color = KIND_COLOR[kind];

  return (
    <svg
      role="progressbar"
      aria-label={ariaLabel ?? 'progress'}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={isIndeterminate ? undefined : value}
      aria-busy={isIndeterminate}
      width={dim}
      height={dim}
      viewBox={`0 0 ${dim} ${dim}`}
      className={cn(isIndeterminate && !reduced && 'animate-spin')}
    >
      <circle cx={dim / 2} cy={dim / 2} r={r} fill="none" stroke="var(--muted)" strokeWidth={stroke} />
      <circle
        cx={dim / 2}
        cy={dim / 2}
        r={r}
        fill="none"
        stroke={color}
        strokeWidth={stroke}
        strokeLinecap="round"
        strokeDasharray={C}
        strokeDashoffset={dashOffset}
        transform={`rotate(-90 ${dim / 2} ${dim / 2})`}
        style={{ transition: isIndeterminate ? undefined : 'stroke-dashoffset 0.3s ease' }}
      />
    </svg>
  );
}

export const OProgressBar = forwardRef<HTMLDivElement, OProgressBarProps>(function OProgressBar(
  {
    value,
    variant = 'linear',
    size = 'md',
    kind = 'default',
    showValue = false,
    label,
    format,
    className,
    theme: _t,
  },
  ref
) {
  const reduced = useReducedMotion();
  const isIndeterminate = value == null;
  const displayText = isIndeterminate
    ? '…'
    : format
      ? format(value)
      : `${Math.round(value)}%`;

  if (variant === 'circular') {
    return (
      <div ref={ref} className={cn('inline-flex items-center justify-center relative', className)}>
        <CircularRing value={value ?? null} size={size} kind={kind} reduced={reduced} ariaLabel={label} />
        {showValue ? (
          <span
            className="absolute inset-0 flex items-center justify-center text-xs font-medium tabular-nums"
            aria-hidden="true"
          >
            {displayText}
          </span>
        ) : null}
      </div>
    );
  }

  return (
    <div ref={ref} className={cn('w-full', className)}>
      {label || showValue ? (
        <div className="flex items-center justify-between mb-1.5 text-xs">
          {label ? <span className="text-muted-foreground">{label}</span> : <span />}
          {showValue ? <span className="font-medium tabular-nums">{displayText}</span> : null}
        </div>
      ) : null}
      <LinearBar value={value ?? null} size={size} kind={kind} reduced={reduced} ariaLabel={label} />
    </div>
  );
});

OProgressBar.displayName = 'OProgressBar';
