/**
 * OBottomSheet - 移动专用底部抽屉。
 *
 * 加密 App 移动端经典形态:
 *   - K 线全屏 + 底部抽屉露出盘口 / 下单面板
 *   - 三档高度可拖拽 (peek 20% / half 50% / full 90%)
 *   - 上滑/下滑切换高度
 *   - 背景手势穿透 (用户仍能滑动 K 线)
 *
 * 使用场景:
 *   - 包装 OOrderbookL2 在 K 线下方
 *   - 包装 OSymbolSearch (从底部弹出全屏搜索)
 *   - 包装下单表单
 *
 * 用法:
 *   <OBottomSheet
 *     open
 *     heights={['peek', 'half', 'full']}
 *     initialHeight="peek"
 *     onClose={() => setOpen(false)}
 *   >
 *     <OOrderbookL2 channel="l2:BTC" />
 *   </OBottomSheet>
 *
 * 不实现 modal 阻塞 (用户应该能继续看到 K 线);如需阻塞用 OModalFrame。
 */

'use client';

import {
  forwardRef,
  useEffect,
  useState,
  type ReactNode,
  type CSSProperties,
} from 'react';
import { cn } from '../../lib/cn';
import { useTouchGesture } from '../../hooks/useTouchGesture';
import { useReducedMotion } from '../../hooks/useReducedMotion';

export type OBottomSheetHeight = 'peek' | 'half' | 'full';

export interface OBottomSheetProps {
  open: boolean;
  /** 关闭回调。 */
  onClose?: () => void;
  /** 可达高度档位,顺序排列。默认 ['peek', 'half', 'full']。 */
  heights?: OBottomSheetHeight[];
  /** 初始高度。默认第一个。 */
  initialHeight?: OBottomSheetHeight;
  /** 高度变化回调。 */
  onHeightChange?: (height: OBottomSheetHeight) => void;
  /** 标题区 (可选)。 */
  title?: ReactNode;
  /** 是否显示拖拽手柄 (默认 true)。 */
  showHandle?: boolean;
  /** 内容。 */
  children?: ReactNode;
  /** className 透传。 */
  className?: string;
  /** 内容区 className。 */
  bodyClassName?: string;
}

const HEIGHT_VH: Record<OBottomSheetHeight, number> = {
  peek: 25,
  half: 55,
  full: 92,
};

export const OBottomSheet = forwardRef<HTMLDivElement, OBottomSheetProps>(
  function OBottomSheet(
    {
      open,
      onClose,
      heights = ['peek', 'half', 'full'],
      initialHeight,
      onHeightChange,
      title,
      showHandle = true,
      children,
      className,
      bodyClassName,
    },
    ref
  ) {
    const [currentHeight, setCurrentHeight] = useState<OBottomSheetHeight>(
      initialHeight ?? heights[0]!
    );
    const reduced = useReducedMotion();

    useEffect(() => {
      if (initialHeight && initialHeight !== currentHeight) {
        setCurrentHeight(initialHeight);
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [initialHeight]);

    function changeHeight(next: OBottomSheetHeight) {
      setCurrentHeight(next);
      onHeightChange?.(next);
    }

    // 拖拽手势
    const gestureRef = useTouchGesture<HTMLDivElement>({
      onSwipe: (dir) => {
        const idx = heights.indexOf(currentHeight);
        if (dir === 'up' && idx < heights.length - 1) {
          changeHeight(heights[idx + 1]!);
        } else if (dir === 'down') {
          if (idx > 0) {
            changeHeight(heights[idx - 1]!);
          } else if (onClose) {
            onClose();
          }
        }
      },
      swipeThreshold: 30,
    });

    // 顶部手柄点击切高度 (无障碍替代手势)
    function cycleHeight() {
      const idx = heights.indexOf(currentHeight);
      const next = heights[(idx + 1) % heights.length]!;
      changeHeight(next);
    }

    if (!open) return null;

    const vh = HEIGHT_VH[currentHeight];
    const style: CSSProperties = {
      height: `${vh}vh`,
      transition: reduced ? 'none' : 'height 240ms cubic-bezier(0.32, 0.72, 0, 1)',
    };

    return (
      <div
        ref={ref}
        role="dialog"
        aria-modal="false"
        aria-label={typeof title === 'string' ? title : 'Bottom sheet'}
        className={cn(
          'fixed inset-x-0 bottom-0 z-50',
          'bg-[color:var(--card)] text-[color:var(--card-foreground)]',
          'border-t border-[color:var(--border)]',
          'rounded-t-2xl shadow-2xl flex flex-col overflow-hidden',
          className
        )}
        style={style}
      >
        {/* 手柄 + 拖拽区 */}
        <div ref={gestureRef as never} className="shrink-0 select-none touch-none">
          {showHandle ? (
            <button
              type="button"
              onClick={cycleHeight}
              className="w-full py-2 flex items-center justify-center"
              aria-label="Change sheet height"
            >
              <span
                className="block w-10 h-1 rounded-full bg-[color:var(--text-muted)]/40"
                aria-hidden="true"
              />
            </button>
          ) : null}
          {title ? (
            <div className="px-4 pb-2 flex items-center justify-between">
              <div
                className="font-semibold"
                style={{
                  fontSize: 'var(--font-size-title, 15px)',
                  fontFamily: 'var(--font-ui)',
                }}
              >
                {title}
              </div>
              {onClose ? (
                <button
                  type="button"
                  onClick={onClose}
                  className="w-8 h-8 -mr-2 inline-flex items-center justify-center rounded-md hover:bg-[color:var(--muted)]/40 text-[color:var(--text-muted)]"
                  aria-label="Close"
                >
                  <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
                    <path
                      d="M3 3L13 13M13 3L3 13"
                      stroke="currentColor"
                      strokeWidth="1.5"
                      strokeLinecap="round"
                    />
                  </svg>
                </button>
              ) : null}
            </div>
          ) : null}
        </div>

        {/* Body */}
        <div className={cn('flex-1 min-h-0 overflow-auto', bodyClassName)}>{children}</div>
      </div>
    );
  }
);

OBottomSheet.displayName = 'OBottomSheet';
