/**
 * OSemanticSearch — Stratum hybrid_search 结果列表
 *
 * 消费 API v1.0 §7 hybrid_search 返回的 SearchResult[]。
 * 包含 BM25 + dense vector RRF 融合 + pinned_boost 后的结果。
 *
 * 设计:
 *   - 查询框 + 结果列表
 *   - 每条结果显示 title + score + medium badge + highlight
 *   - 强制 citation 渲染(用 OCitationCard compact 模式)
 *   - augmented 模式时 type='llm_augmented' 显示特殊 badge
 *   - 受控/非受控两用(value/onChange + defaultValue)
 *
 * 设计原则:
 *   - 数据请求由消费方实施(onSearch callback),Block 只渲染
 *   - 加载状态 / 错误状态 / 空结果都有 UI
 *   - keyboard a11y(Enter 触发搜索 + 上下箭头导航结果)
 */
import {
  forwardRef,
  useCallback,
  useState,
  type KeyboardEvent,
  type ChangeEvent,
} from 'react';
import { cn } from '../../lib/cn';
import { OCitationCard } from '../OCitationCard';
import type { SearchResult } from '../../types/stratum';
import type { OBlockBaseProps } from '../../lib/types';

export interface OSemanticSearchProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 搜索 callback。消费方实施真实 fetch hybrid_search。 */
  onSearch: (query: string) => Promise<SearchResult[]>;
  /** 点击结果 callback。默认行为是 deep_link 跳转。 */
  onResultClick?: (result: SearchResult) => void;
  /** 输入框 placeholder。 */
  placeholder?: string;
  /** 默认查询(非受控)。 */
  defaultQuery?: string;
  /** 受控查询。 */
  query?: string;
  onQueryChange?: (q: string) => void;
  /** 是否显示 score(默认 true,debug 用)。 */
  showScore?: boolean;
  /** 是否显示 highlight 片段(默认 true)。 */
  showHighlight?: boolean;
}

export const OSemanticSearch = forwardRef<HTMLDivElement, OSemanticSearchProps>(
  function OSemanticSearch(
    {
      onSearch,
      onResultClick,
      placeholder = '搜索知识库...',
      defaultQuery = '',
      query: controlledQuery,
      onQueryChange,
      showScore = true,
      showHighlight = true,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const [uncontrolledQuery, setUncontrolledQuery] = useState(defaultQuery);
    const isControlled = controlledQuery !== undefined;
    const query = isControlled ? controlledQuery : uncontrolledQuery;

    const [results, setResults] = useState<SearchResult[]>([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [searched, setSearched] = useState(false);

    const handleQueryChange = useCallback(
      (e: ChangeEvent<HTMLInputElement>) => {
        const v = e.target.value;
        if (isControlled) {
          onQueryChange?.(v);
        } else {
          setUncontrolledQuery(v);
        }
      },
      [isControlled, onQueryChange]
    );

    const performSearch = useCallback(async () => {
      if (!query.trim()) return;
      setLoading(true);
      setError(null);
      try {
        const r = await onSearch(query);
        setResults(r);
        setSearched(true);
      } catch (e) {
        setError(e instanceof Error ? e.message : '搜索失败');
        setResults([]);
      } finally {
        setLoading(false);
      }
    }, [query, onSearch]);

    const handleKeyDown = useCallback(
      (e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          void performSearch();
        }
      },
      [performSearch]
    );

    const handleResultClick = useCallback(
      (r: SearchResult) => {
        if (onResultClick) {
          onResultClick(r);
          return;
        }
        if (r.citation?.deep_link) {
          window.open(r.citation.deep_link, '_blank', 'noopener,noreferrer');
        }
      },
      [onResultClick]
    );

    return (
      <div ref={ref} className={cn('flex flex-col gap-3 w-full', className)}>
        <div className="flex gap-2">
          <input
            type="search"
            value={query}
            onChange={handleQueryChange}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            aria-label="搜索查询"
            className={cn(
              'flex-1 px-3 py-2 rounded-md text-sm @container',
              'bg-card border border-border',
              'text-[color:var(--foreground)] placeholder:text-[color:var(--text-muted)]',
              'focus:outline-none focus-visible:ring-2 focus-visible:ring-ring'
            )}
          />
          <button
            type="button"
            onClick={() => void performSearch()}
            disabled={loading || !query.trim()}
            className={cn(
              'px-4 py-2 rounded-md text-sm font-medium',
              'bg-primary text-primary-foreground',
              'hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed',
              'transition-opacity'
            )}
          >
            {loading ? '搜索中...' : '搜索'}
          </button>
        </div>

        {error && (
          <div
            role="alert"
            className={cn(
              'px-3 py-2 rounded-md text-sm',
              'bg-destructive/10 text-destructive',
              'border border-destructive/30'
            )}
          >
            {error}
          </div>
        )}

        {searched && !loading && results.length === 0 && !error && (
          <div className="px-3 py-6 text-sm text-[color:var(--text-muted)] text-center">
            无结果
          </div>
        )}

        {results.length > 0 && (
          <ul
            className="flex flex-col gap-2 list-none p-0 m-0"
            aria-label={`搜索结果 ${results.length} 条`}
          >
            {results.map((r) => (
              <li
                key={r.id}
                className={cn(
                  'flex flex-col gap-1 px-3 py-2 rounded-md',
                  'bg-card',
                  'border border-border'
                )}
              >
                <button
                  type="button"
                  onClick={() => handleResultClick(r)}
                  className={cn(
                    'flex items-center gap-2 flex-wrap text-left',
                    'hover:opacity-80 transition-opacity cursor-pointer',
                    'focus:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded'
                  )}
                  aria-label={`查看 ${r.title}`}
                >
                  {r.type === 'llm_augmented' && (
                    <span
                      className={cn(
                        'px-1.5 py-0.5 text-[10px] rounded font-mono',
                        'bg-primary/20 text-primary'
                      )}
                    >
                      AI 增强
                    </span>
                  )}
                  {r.metadata.medium && (
                    <span
                      className={cn(
                        'px-1.5 py-0.5 text-[10px] rounded font-mono',
                        'bg-muted text-[color:var(--text-muted)]'
                      )}
                    >
                      {r.metadata.medium}
                    </span>
                  )}
                  <span className="font-medium text-sm text-[color:var(--foreground)] truncate flex-1">
                    {r.title}
                  </span>
                  {showScore && (
                    <span className="text-[10px] font-mono text-[color:var(--text-muted)]">
                      {r.score.toFixed(3)}
                    </span>
                  )}
                </button>
                {showHighlight && r.highlight && (
                  <div className="text-xs text-[color:var(--text-muted)] line-clamp-2">
                    {r.highlight}
                  </div>
                )}
                {r.citation && (
                  <div className="mt-1">
                    <OCitationCard
                      citation={{
                        substrate_id: r.citation.substrate_id,
                        fragment_id: r.citation.fragment_id,
                        anchor: r.citation.anchor,
                        deep_link: r.citation.deep_link,
                      }}
                      compact
                    />
                  </div>
                )}
              </li>
            ))}
          </ul>
        )}
      </div>
    );
  }
);

OSemanticSearch.displayName = 'OSemanticSearch';
