/**
 * OErrorState - 错误状态展示。
 *
 * variant:
 *   - inline:     紧凑,嵌在卡片内
 *   - fullscreen: 整页错误,带图标 + retry 按钮
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { OCard } from '../OCard';
import { OButton } from '../OButton';
import type { OBlockBaseProps } from '../../lib/types';

const variants = cva('', {
  variants: {
    variant: {
      inline: 'p-3 flex items-start gap-3',
      fullscreen: 'p-8 flex flex-col items-center justify-center text-center gap-3 min-h-48',
    },
  },
  defaultVariants: { variant: 'inline' },
});

type ErrorVariantProps = VariantProps<typeof variants>;

export interface OErrorStateProps
  extends Omit<OBlockBaseProps, 'variant'>,
    ErrorVariantProps {
  /** 错误对象或错误文本。 */
  error: Error | string;
  /** 自定义标题(默认 'Error')。 */
  title?: string;
  /** 重试回调。提供则显示 retry 按钮。 */
  onRetry?: () => void;
  /** 是否显示详细 stack。 */
  showDetails?: boolean;
}

function AlertIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      className={cn('shrink-0 @container', className)}
      aria-hidden="true"
    >
      <circle cx="12" cy="12" r="10" />
      <line x1="12" y1="8" x2="12" y2="12" />
      <line x1="12" y1="16" x2="12.01" y2="16" />
    </svg>
  );
}

export const OErrorState = forwardRef<HTMLDivElement, OErrorStateProps>(function OErrorState(
  { error, title, onRetry, showDetails = false, variant = 'inline', className, theme: _t, size: _s, ...rest },
  ref
) {
  const message = typeof error === 'string' ? error : error.message;
  const stack = typeof error === 'string' ? undefined : error.stack;
  const displayTitle = title ?? 'Error';

  return (
    <OCard
      ref={ref as any}
      role="alert"
      padded={false}
      elevation="flat"
      emphasis
      accentColor="var(--destructive)"
      className={cn(variants({ variant }), 'border-destructive/40', className)}
      {...rest}
    >
      <AlertIcon className={cn('text-destructive', variant === 'inline' ? 'w-5 h-5 mt-0.5' : 'w-12 h-12')} />
      <div className={cn('min-w-0', variant === 'inline' ? 'flex-1' : 'space-y-2 max-w-md')}>
        <h3 className={cn('font-bold tracking-[-0.01em]', variant === 'fullscreen' && 'text-lg')}>
          {displayTitle}
        </h3>
        <p className="text-sm text-muted-foreground break-words">{message}</p>
        {showDetails && stack ? (
          <details className="mt-2">
            <summary className="text-xs text-muted-foreground cursor-pointer hover:text-foreground">
              Details
            </summary>
            <pre className="mt-2 text-xs bg-muted p-2 rounded overflow-auto max-h-48">{stack}</pre>
          </details>
        ) : null}
        {onRetry ? (
          <OButton
            variant="primary"
            size="sm"
            onClick={onRetry}
            className="mt-2"
          >
            Retry
          </OButton>
        ) : null}
      </div>
    </OCard>
  );
});

OErrorState.displayName = 'OErrorState';
