/**
 * OCapitalFlow - 资金流向 Block。
 *
 * 加密场景: 主动买 (taker buy) vs 主动卖 (taker sell) 的力量对比 + 净流入历史趋势。
 *
 * 数据契约:
 *   - current: { takerBuy, takerSell, windowSec }
 *   - history: 时间序列 [{ time, netInflow }] (可选)
 *
 * 视觉:
 *   - 顶部:大数字 净流入 (绿/红)
 *   - 中部:双向对冲条 (左买右卖)
 *   - 底部:迷你 sparkline (近 N 个时段)
 */

'use client';

import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import type { OBlockDataProps } from '../../lib/types';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import { useFlashOnChange } from '../../hooks/useFlashOnChange';

export interface OCapitalFlowSnapshot {
  /** 主动买量(taker buy)。 */
  takerBuy: number;
  /** 主动卖量(taker sell)。 */
  takerSell: number;
  /** 统计窗口(秒)。 */
  windowSec: number;
}

export interface OCapitalFlowPoint {
  time: number;     // Unix ms
  netInflow: number; // takerBuy - takerSell
}

export interface OCapitalFlowData {
  symbol: string;
  current: OCapitalFlowSnapshot;
  history?: OCapitalFlowPoint[];
}

export interface OCapitalFlowProps extends OBlockDataProps<OCapitalFlowData> {
  height?: number;
  /** 显示迷你历史趋势。 */
  showSparkline?: boolean;
  /** 是否启用脉冲。 */
  flashOnUpdate?: boolean;
  /** 数据延时(分钟,合规)。 */
  dataDelay?: number;
}

function formatVol(n: number): string {
  const abs = Math.abs(n);
  if (abs >= 1e9) return (n / 1e9).toFixed(2) + 'B';
  if (abs >= 1e6) return (n / 1e6).toFixed(2) + 'M';
  if (abs >= 1e3) return (n / 1e3).toFixed(2) + 'K';
  return n.toFixed(2);
}

function Sparkline({
  points,
  height,
  color,
}: {
  points: OCapitalFlowPoint[];
  height: number;
  color: string;
}) {
  if (points.length < 2) return null;
  const w = 200;
  const min = Math.min(...points.map((p) => p.netInflow), 0);
  const max = Math.max(...points.map((p) => p.netInflow), 0);
  const range = max - min || 1;
  const yZero = ((max - 0) / range) * height;
  const path = points
    .map((p, i) => {
      const x = (i / (points.length - 1)) * w;
      const y = ((max - p.netInflow) / range) * height;
      return `${i === 0 ? 'M' : 'L'} ${x.toFixed(1)} ${y.toFixed(1)}`;
    })
    .join(' ');
  return (
    <svg width={w} height={height} viewBox={`0 0 ${w} ${height}`} preserveAspectRatio="none" style={{ width: '100%' }}>
      <line x1={0} y1={yZero} x2={w} y2={yZero} stroke="var(--border)" strokeDasharray="2 4" strokeWidth={1} />
      <path d={path} stroke={color} strokeWidth={1.5} fill="none" />
    </svg>
  );
}

export const OCapitalFlow = forwardRef<HTMLDivElement, OCapitalFlowProps>(
  function OCapitalFlow(
    {
      data,
      loading,
      error,
      empty,
      height = 200,
      showSparkline = true,
      flashOnUpdate = true,
      dataDelay,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const state = resolveBlockState({ data, loading, error, empty });

    const netInflow = data?.current
      ? data.current.takerBuy - data.current.takerSell
      : 0;
    const isPositive = netInflow >= 0;

    const flashRef = useFlashOnChange(netInflow, {
      modes: flashOnUpdate ? ['color', 'density'] : [],
      threshold: 0,
    });

    if (state === 'loading')
      return (
        <div
          ref={ref}
          className={cn('rounded-md border border-border bg-card p-4', className)}
          style={{ height }}
        >
          <OLoadingState rows={3} />
        </div>
      );
    if (state === 'error')
      return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data)
      return <OEmptyState ref={ref} title="No flow data" className={className} />;

    const { takerBuy, takerSell, windowSec } = data.current;
    const total = takerBuy + takerSell;
    const buyRatio = total > 0 ? takerBuy / total : 0.5;

    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border overflow-hidden @container',
          'p-4 flex flex-col gap-3',
          className
        )}
        style={{
          height,
          background: 'var(--card)',
          color: 'var(--foreground)',
          fontFamily: 'var(--font-data, ui-monospace, monospace)',
        }}
      >
        {/* 头部 */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
          <span
            style={{
              fontSize: 'var(--font-size-label, 11px)',
              color: 'var(--text-muted)',
            }}
          >
            {data.symbol} · 主动单流向 · {windowSec}s
          </span>
          {dataDelay != null ? (
            <span style={{ fontSize: 10, color: 'var(--text-hint)' }}>延时 {dataDelay} 分钟</span>
          ) : null}
        </div>

        {/* 大数字 */}
        <div
          ref={flashRef as never}
          style={{
            fontSize: 28,
            fontWeight: 700,
            color: isPositive ? 'var(--quote-up)' : 'var(--quote-down)',
            fontVariantNumeric: 'tabular-nums',
            lineHeight: 1,
          }}
        >
          {isPositive ? '+' : ''}
          {formatVol(netInflow)}
        </div>

        {/* 双向对冲条 */}
        <div>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4, fontSize: 11 }}>
            <span style={{ color: 'var(--quote-up)' }}>买 {formatVol(takerBuy)}</span>
            <span style={{ color: 'var(--quote-down)' }}>卖 {formatVol(takerSell)}</span>
          </div>
          <div
            style={{
              display: 'flex',
              height: 6,
              borderRadius: 3,
              overflow: 'hidden',
              background: 'var(--terminal-bg-3, var(--muted))',
            }}
          >
            <div
              style={{
                width: `${buyRatio * 100}%`,
                background: 'var(--quote-up)',
                transition: 'width 240ms ease-out',
              }}
            />
            <div
              style={{
                width: `${(1 - buyRatio) * 100}%`,
                background: 'var(--quote-down)',
                transition: 'width 240ms ease-out',
              }}
            />
          </div>
          <div style={{ display: 'flex', justifyContent: 'center', marginTop: 4, fontSize: 10, color: 'var(--text-muted)' }}>
            买占比 {(buyRatio * 100).toFixed(1)}%
          </div>
        </div>

        {/* sparkline */}
        {showSparkline && data.history && data.history.length > 1 ? (
          <div style={{ flex: 1, minHeight: 30 }}>
            <Sparkline
              points={data.history}
              height={Math.min(40, height * 0.25)}
              color={isPositive ? 'var(--quote-up)' : 'var(--quote-down)'}
            />
          </div>
        ) : null}
      </div>
    );
  }
);

OCapitalFlow.displayName = 'OCapitalFlow';
