'use client';
import { forwardRef, type ComponentPropsWithoutRef, type ElementRef } from 'react';
import * as SelectPrimitive from '@radix-ui/react-select';
import { cn } from '../../lib/cn';
import { selectTriggerRecipe, selectContentRecipe, selectItemRecipe, type SelectTriggerRecipeProps } from '../../recipes';

export const OSelect = SelectPrimitive.Root;
export const OSelectGroup = SelectPrimitive.Group;
export const OSelectValue = SelectPrimitive.Value;

export const OSelectTrigger = forwardRef<
  ElementRef<typeof SelectPrimitive.Trigger>,
  ComponentPropsWithoutRef<typeof SelectPrimitive.Trigger> & SelectTriggerRecipeProps
>(function OSelectTrigger({ className, size, children, ...props }, ref) {
  return (
    <SelectPrimitive.Trigger ref={ref} className={cn(selectTriggerRecipe({ size }), className)} {...props}>
      {children}
      <SelectPrimitive.Icon asChild>
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
          <path d="M4 6l4 4 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
        </svg>
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
});
OSelectTrigger.displayName = 'OSelectTrigger';

export const OSelectContent = forwardRef<
  ElementRef<typeof SelectPrimitive.Content>,
  ComponentPropsWithoutRef<typeof SelectPrimitive.Content>
>(function OSelectContent({ className, children, position = 'popper', ...props }, ref) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Content ref={ref} className={cn(selectContentRecipe(), className)} position={position} {...props}>
        <SelectPrimitive.Viewport className="p-1">{children}</SelectPrimitive.Viewport>
      </SelectPrimitive.Content>
    </SelectPrimitive.Portal>
  );
});
OSelectContent.displayName = 'OSelectContent';

export const OSelectItem = forwardRef<
  ElementRef<typeof SelectPrimitive.Item>,
  ComponentPropsWithoutRef<typeof SelectPrimitive.Item>
>(function OSelectItem({ className, children, ...props }, ref) {
  return (
    <SelectPrimitive.Item ref={ref} className={cn(selectItemRecipe(), className)} {...props}>
      <span className="absolute right-2 flex items-center">
        <SelectPrimitive.ItemIndicator>
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden>
            <path d="M3.5 8.5l3 3 6-7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
        </SelectPrimitive.ItemIndicator>
      </span>
      <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
    </SelectPrimitive.Item>
  );
});
OSelectItem.displayName = 'OSelectItem';
