/**
 * OStrategyLifecycleCard (Tide Wave 3 E31, Block)
 *
 * 策略生命周期 card(draft → shadow → active → deprecated)。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §5.4
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export type StrategyStage = 'draft' | 'shadow' | 'active' | 'deprecated';

export interface StrategyLifecycleData {
  id: string;
  name: string;
  stage: StrategyStage;
  version: string;
  /** stage 进入时间 */
  stageEnteredAt: string | Date;
  /** stage 持续天数 */
  daysInStage: number;
  /** 关键指标摘要 */
  metrics?: {
    totalReturn?: number;
    sharpe?: number;
    winrate?: number;
    nTrades?: number;
  };
  /** 下一步建议动作 */
  nextAction?: string;
  /** 风险信号 */
  warnings?: string[];
}

export interface OStrategyLifecycleCardProps extends Omit<OBlockBaseProps, 'variant'> {
  strategy: StrategyLifecycleData;
  cardVariant?: 'compact' | 'expanded';
  onStageClick?: (stage: StrategyStage) => void;
  onPromote?: () => void;
  onDeprecate?: () => void;
}

const STAGES: StrategyStage[] = ['draft', 'shadow', 'active', 'deprecated'];

const STAGE_LABEL: Record<StrategyStage, string> = {
  draft: '草稿',
  shadow: '影子',
  active: '生产',
  deprecated: '废弃',
};

const STAGE_COLOR: Record<StrategyStage, string> = {
  draft: 'var(--text-tertiary)',
  shadow: 'var(--yellow)',
  active: 'var(--green-down)',
  deprecated: 'var(--red-up)',
};

const STAGE_ICON: Record<StrategyStage, string> = {
  draft: '📝',
  shadow: '👻',
  active: '✅',
  deprecated: '⚰',
};

export const OStrategyLifecycleCard = forwardRef<HTMLDivElement, OStrategyLifecycleCardProps>(
  function OStrategyLifecycleCard(
    {
      strategy,
      cardVariant = 'expanded',
      onStageClick,
      onPromote,
      onDeprecate,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const isCompact = cardVariant === 'compact';

    return (
      <div
        ref={ref}
        className={cn(
          'flex flex-col gap-2 rounded @container',
          'bg-[color:var(--card)] border border-[color:var(--border-strong)]',
          isCompact ? 'px-2 py-1.5' : 'px-3 py-2',
          className
        )}
        style={{ fontFamily: 'var(--font-sans)' }}
        role="region"
        aria-label={`策略 ${strategy.name}`}
      >
        {/* header */}
        <div className="flex items-center justify-between">
          <div className="flex flex-col">
            <span
              className="text-sm font-bold"
              style={{ color: 'var(--foreground)' }}
            >
              {strategy.name}
            </span>
            <span
              className="text-[10px]"
              style={{ color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)' }}
            >
              {strategy.version} · {strategy.daysInStage} 天
            </span>
          </div>
          <span
            className="px-2 py-0.5 rounded text-xs font-bold"
            style={{
              backgroundColor: STAGE_COLOR[strategy.stage],
              color: '#fff',
            }}
          >
            {STAGE_ICON[strategy.stage]} {STAGE_LABEL[strategy.stage]}
          </span>
        </div>

        {/* lifecycle stages */}
        {!isCompact && (
          <div className="flex items-center gap-1">
            {STAGES.map((s, i) => {
              const isCurrent = s === strategy.stage;
              const isPast = STAGES.indexOf(strategy.stage) > i;
              const color = isCurrent || isPast ? STAGE_COLOR[s] : 'var(--text-tertiary)';
              return (
                <button
                  key={s}
                  type="button"
                  onClick={() => onStageClick?.(s)}
                  disabled={!onStageClick}
                  aria-label={`stage ${STAGE_LABEL[s]}${isCurrent ? ' 当前' : ''}`}
                  aria-current={isCurrent ? 'step' : undefined}
                  className={cn(
                    'flex-1 px-1 py-1 text-[10px] rounded transition-opacity',
                    isCurrent && 'ring-1 ring-[color:var(--blue-accent)]'
                  )}
                  style={{
                    backgroundColor:
                      isCurrent || isPast
                        ? `color-mix(in srgb, ${color} 20%, var(--muted))`
                        : 'var(--muted)',
                    color: 'var(--foreground)',
                    border: 'none',
                  }}
                >
                  {STAGE_LABEL[s]}
                </button>
              );
            })}
          </div>
        )}

        {/* metrics */}
        {!isCompact && strategy.metrics && (
          <div className="grid grid-cols-2 gap-1 text-[11px]" style={{ fontFamily: 'var(--font-mono)' }}>
            {strategy.metrics.totalReturn !== undefined && (
              <div style={{ color: 'var(--muted-foreground)' }}>
                收益{' '}
                <span
                  style={{
                    color: strategy.metrics.totalReturn > 0 ? 'var(--red-up)' : 'var(--green-down)',
                  }}
                >
                  {(strategy.metrics.totalReturn * 100).toFixed(1)}%
                </span>
              </div>
            )}
            {strategy.metrics.sharpe !== undefined && (
              <div style={{ color: 'var(--muted-foreground)' }}>
                Sharpe <span style={{ color: 'var(--foreground)' }}>{strategy.metrics.sharpe.toFixed(2)}</span>
              </div>
            )}
            {strategy.metrics.winrate !== undefined && (
              <div style={{ color: 'var(--muted-foreground)' }}>
                胜率 <span style={{ color: 'var(--foreground)' }}>{(strategy.metrics.winrate * 100).toFixed(0)}%</span>
              </div>
            )}
            {strategy.metrics.nTrades !== undefined && (
              <div style={{ color: 'var(--muted-foreground)' }}>
                次数 <span style={{ color: 'var(--foreground)' }}>{strategy.metrics.nTrades}</span>
              </div>
            )}
          </div>
        )}

        {/* warnings */}
        {!isCompact && strategy.warnings && strategy.warnings.length > 0 && (
          <div
            className="text-[10px] px-2 py-1 rounded"
            role="alert"
            style={{
              backgroundColor: 'color-mix(in srgb, var(--yellow) 15%, transparent)',
              color: 'var(--yellow)',
            }}
          >
            {strategy.warnings.map((w, i) => (
              <div key={i}>⚠ {w}</div>
            ))}
          </div>
        )}

        {/* nextAction */}
        {!isCompact && strategy.nextAction && (
          <div
            className="text-[11px] px-2 py-1 rounded"
            style={{
              backgroundColor: 'color-mix(in srgb, var(--blue-accent) 12%, transparent)',
              color: 'var(--foreground)',
            }}
          >
            💡 {strategy.nextAction}
          </div>
        )}

        {/* actions */}
        {!isCompact && (onPromote || onDeprecate) && (
          <div className="flex gap-1.5">
            {onPromote && strategy.stage !== 'active' && strategy.stage !== 'deprecated' && (
              <button
                type="button"
                onClick={onPromote}
                className={cn(
                  'flex-1 px-2 py-1 text-xs rounded font-bold',
                  'bg-[color:var(--green-down)] text-white',
                  'hover:opacity-90 transition-opacity'
                )}
              >
                ⬆ 推进
              </button>
            )}
            {onDeprecate && strategy.stage !== 'deprecated' && (
              <button
                type="button"
                onClick={onDeprecate}
                className={cn(
                  'flex-1 px-2 py-1 text-xs rounded',
                  'bg-[color:var(--muted)] text-[color:var(--red-up)]',
                  'hover:bg-[color:var(--accent)] transition-colors'
                )}
              >
                ⬇ 废弃
              </button>
            )}
          </div>
        )}
      </div>
    );
  }
);

OStrategyLifecycleCard.displayName = 'OStrategyLifecycleCard';
