/**
 * OTabsAccordion — Tabs ↔ Accordion 容器自适应切换
 *
 * 来源:Tide 经理人 R1 §4(9 dimension panel mobile-first)
 *
 * 设计参考:
 *   - Brad Frost 2014 "Responsive nav patterns" — Toggle 模式
 *   - 2024+ Container Queries(CSS Containment Level 3)— 容器宽度而非屏幕宽度
 *   - Nielsen Norman Group "Accordion vs Tabs" 研究 — 移动端 accordion 更可触达
 *
 * 关键创新(2026 现代方案):
 *   - 默认用 ResizeObserver 监听**组件父容器**宽度,而非 window.innerWidth
 *   - 这让一个 Block 可以放在不同位置(主区 / 侧边栏 / 抽屉)自动适配,
 *     不依赖整个页面响应式断点
 *   - viewport breakpoint 仅作 SSR 时的 fallback
 *
 * 跨项目使用:
 *   - Tide 9 dimension panel
 *   - Stratum article view 多视图
 *   - Aegis app detail 多 section
 *   - Helivex tab 多面板
 *
 * a11y:
 *   - Tabs mode: role="tablist" + 每个 tab role="tab" + content role="tabpanel"
 *   - Accordion mode: 每个 item role="region" + button role="button" aria-expanded
 *   - Radix 内置键盘导航(箭头 / Home / End)
 */
'use client';

import * as Tabs from '@radix-ui/react-tabs';
import * as Accordion from '@radix-ui/react-accordion';
import {
  forwardRef,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

// ============================================================
// Props
// ============================================================

export interface OTabsAccordionItem {
  /** 唯一标识。 */
  id: string;
  /** Tab 标签 / Accordion header。 */
  label: ReactNode;
  /** 右侧徽章(红点 / 数字)。 */
  badge?: ReactNode;
  /** 内容。 */
  content: ReactNode;
  /** 是否禁用此 item。 */
  disabled?: boolean;
}

export interface OTabsAccordionProps
  extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  /** 多 item 列表。 */
  items: OTabsAccordionItem[];

  /**
   * 容器宽度切换阈值(像素)。
   * 容器宽度 < threshold → accordion 模式
   * 容器宽度 ≥ threshold → tabs 模式
   * 默认 600。
   */
  containerBreakpoint?: number;

  /**
   * Tabs 模式下默认激活 item id。
   * 不传则用第一个非 disabled 的 item。
   */
  defaultTab?: string;

  /**
   * Accordion 模式下默认展开 item id(单一)。
   * 不传则全部折叠。
   */
  defaultOpen?: string;

  /**
   * Accordion 模式允许多个同时展开。默认 false(单一)。
   */
  accordionMultiOpen?: boolean;

  /**
   * 强制模式(测试 / 特殊场景)。
   * 'auto' = 根据容器宽度自适应(默认)
   * 'tabs' / 'accordion' = 锁定
   */
  forceMode?: 'auto' | 'tabs' | 'accordion';

  /** 切换 item 时回调(tabs / accordion 都触发)。 */
  onItemChange?: (id: string) => void;
}

// ============================================================
// 主组件
// ============================================================

export const OTabsAccordion = forwardRef<HTMLDivElement, OTabsAccordionProps>(
  function OTabsAccordion(
    {
      items,
      containerBreakpoint = 600,
      defaultTab,
      defaultOpen,
      accordionMultiOpen = false,
      forceMode = 'auto',
      onItemChange,
      className,
      theme: _t,
    },
    ref
  ) {
    // ============ Container Query 实现 ============
    // 监听本组件父容器宽度,而非 window 宽度
    const containerRef = useRef<HTMLDivElement | null>(null);
    const [containerWidth, setContainerWidth] = useState<number | null>(null);

    useEffect(() => {
      if (forceMode !== 'auto') return;
      if (typeof ResizeObserver === 'undefined') {
        // SSR / 旧浏览器 fallback:用 window.innerWidth
        if (typeof window !== 'undefined') {
          setContainerWidth(window.innerWidth);
        }
        return;
      }

      const el = containerRef.current;
      if (!el) return;

      // 初始测一次
      setContainerWidth(el.clientWidth);

      const ro = new ResizeObserver((entries) => {
        for (const entry of entries) {
          setContainerWidth(entry.contentRect.width);
        }
      });
      ro.observe(el);

      return () => ro.disconnect();
    }, [forceMode]);

    // 确定当前模式
    const mode: 'tabs' | 'accordion' = (() => {
      if (forceMode === 'tabs') return 'tabs';
      if (forceMode === 'accordion') return 'accordion';
      // auto 模式
      if (containerWidth == null) {
        // SSR / 首次测量前:默认 tabs(桌面优先,内容多场景)
        return 'tabs';
      }
      return containerWidth < containerBreakpoint ? 'accordion' : 'tabs';
    })();

    // 空列表兜底
    if (items.length === 0) {
      return (
        <div
          ref={(node) => {
            containerRef.current = node;
            if (typeof ref === 'function') ref(node);
            else if (ref) ref.current = node;
          }}
          className={cn('text-xs text-muted-foreground italic p-2', className)}
        >
          (无内容)
        </div>
      );
    }

    // 计算默认 tab(第一个非 disabled)
    const firstEnabled = items.find((it) => !it.disabled);
    const resolvedDefaultTab = defaultTab ?? firstEnabled?.id ?? items[0]!.id;

    // 合并 ref
    const setRefs = (node: HTMLDivElement | null) => {
      containerRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };

    // ============ Tabs 模式渲染 ============
    if (mode === 'tabs') {
      return (
        <div ref={setRefs} className={cn('w-full', className)}>
          <Tabs.Root
            defaultValue={resolvedDefaultTab}
            onValueChange={onItemChange}
            className="w-full"
          >
            <Tabs.List
              className="flex border-b border-border overflow-x-auto"
              aria-label="标签页"
            >
              {items.map((it) => (
                <Tabs.Trigger
                  key={it.id}
                  value={it.id}
                  disabled={it.disabled}
                  className={cn(
                    'inline-flex items-center gap-1.5 px-4 py-2 text-sm whitespace-nowrap @container',
                    'border-b-2 border-transparent',
                    'text-muted-foreground hover:text-foreground transition-colors',
                    'data-[state=active]:text-foreground data-[state=active]:border-primary',
                    'data-[state=active]:font-medium',
                    'disabled:opacity-50 disabled:cursor-not-allowed',
                    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring'
                  )}
                >
                  <span>{it.label}</span>
                  {it.badge != null ? <span>{it.badge}</span> : null}
                </Tabs.Trigger>
              ))}
            </Tabs.List>
            {items.map((it) => (
              <Tabs.Content
                key={it.id}
                value={it.id}
                className="py-4 focus-visible:outline-none"
              >
                {it.content}
              </Tabs.Content>
            ))}
          </Tabs.Root>
        </div>
      );
    }

    // ============ Accordion 模式渲染 ============
    if (accordionMultiOpen) {
      return (
        <div ref={setRefs} className={cn('w-full', className)}>
          <Accordion.Root
            type="multiple"
            defaultValue={defaultOpen ? [defaultOpen] : []}
            onValueChange={(vals) => {
              const last = vals[vals.length - 1];
              if (last) onItemChange?.(last);
            }}
            className="w-full divide-y divide-border border border-border rounded-md"
          >
            {items.map((it) => (
              <AccordionItem key={it.id} item={it} />
            ))}
          </Accordion.Root>
        </div>
      );
    }

    return (
      <div ref={setRefs} className={cn('w-full', className)}>
        <Accordion.Root
          type="single"
          collapsible
          {...(defaultOpen ? { defaultValue: defaultOpen } : {})}
          onValueChange={(val) => {
            if (val) onItemChange?.(val);
          }}
          className="w-full divide-y divide-border border border-border rounded-md"
        >
          {items.map((it) => (
            <AccordionItem key={it.id} item={it} />
          ))}
        </Accordion.Root>
      </div>
    );
  }
);

OTabsAccordion.displayName = 'OTabsAccordion';

// ============================================================
// Accordion 单 item 子组件
// ============================================================

function AccordionItem({ item }: { item: OTabsAccordionItem }) {
  return (
    <Accordion.Item value={item.id} disabled={item.disabled}>
      <Accordion.Header className="flex">
        <Accordion.Trigger
          className={cn(
            'group flex flex-1 items-center justify-between px-4 py-3 text-sm font-medium',
            'hover:bg-muted/50 transition-colors',
            'disabled:opacity-50 disabled:cursor-not-allowed',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset'
          )}
        >
          <span className="inline-flex items-center gap-1.5">
            <span>{item.label}</span>
            {item.badge != null ? <span>{item.badge}</span> : null}
          </span>
          <svg
            className="w-4 h-4 text-muted-foreground transition-transform group-data-[state=open]:rotate-180"
            viewBox="0 0 16 16"
            fill="currentColor"
            aria-hidden="true"
          >
            <path d="M4 6l4 4 4-4" stroke="currentColor" strokeWidth="1.5" fill="none" />
          </svg>
        </Accordion.Trigger>
      </Accordion.Header>
      <Accordion.Content className="px-4 py-3 text-sm">
        {item.content}
      </Accordion.Content>
    </Accordion.Item>
  );
}
