/**
 * OPercentileBar (Tide Wave 2 E13, Atom)
 *
 * 估值百分位 bar(PE/PB/PS/PEG),5y 历史百分位 + gradient 颜色。
 * 来源:OUI_WAVE_2_REQUIREMENTS_v1.0.md §10
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OPercentileBarProps extends Omit<OBlockBaseProps, 'variant'> {
  label: string;
  value: number;
  /** 0-100 */
  percentile: number;
  subText?: string;
  colorMode?: 'gradient' | 'binary';
}

function valueColor(percentile: number): string {
  if (percentile < 30) return 'var(--green-down)';
  if (percentile > 70) return 'var(--red-up)';
  return 'var(--yellow)';
}

export const OPercentileBar = forwardRef<HTMLDivElement, OPercentileBarProps>(
  function OPercentileBar(
    { label, value, percentile, subText, colorMode = 'gradient', className, theme: _t, size: _s },
    ref
  ) {
    const clamped = Math.max(0, Math.min(100, percentile));
    return (
      <div
        ref={ref}
        className={cn('flex flex-col gap-0.5 w-full @container', className)}
        style={{ fontFamily: 'var(--font-mono)' }}
      >
        <div
          className="grid items-center gap-2"
          style={{ gridTemplateColumns: '40px 1fr 50px' }}
        >
          <span className="text-xs" style={{ color: 'var(--muted-foreground)' }}>
            {label}
          </span>
          {/* bar */}
          <div
            className="relative h-[18px] rounded"
            style={{
              background:
                colorMode === 'gradient'
                  ? 'linear-gradient(to right, color-mix(in srgb, var(--green-down) 30%, transparent), color-mix(in srgb, var(--yellow) 30%, transparent), color-mix(in srgb, var(--red-up) 30%, transparent))'
                  : 'var(--muted)',
            }}
            role="progressbar"
            aria-valuenow={Math.round(clamped)}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-label={`${label} ${percentile.toFixed(0)}%`}
          >
            {/* marker */}
            <div
              className="absolute inset-y-0 w-[3px]"
              style={{ left: `calc(${clamped}% - 1.5px)`, backgroundColor: 'var(--foreground)' }}
              aria-hidden="true"
            />
            {/* percentile label */}
            <div
              className="absolute -top-3 text-[9px] font-bold whitespace-nowrap"
              style={{
                left: `${clamped}%`,
                transform: 'translateX(-50%)',
                color: 'var(--muted-foreground)',
              }}
            >
              {clamped.toFixed(0)}%
            </div>
          </div>
          <span
            className="text-xs text-right font-bold"
            style={{ color: valueColor(clamped) }}
          >
            {value.toFixed(1)}
          </span>
        </div>
        {subText && (
          <div
            className="text-[10px] text-center"
            style={{ color: 'var(--text-tertiary)' }}
          >
            {subText}
          </div>
        )}
      </div>
    );
  }
);

OPercentileBar.displayName = 'OPercentileBar';
