/**
 * BatchJob 操作协议 — 各项目实现自己的 service,注入 OBatchJobProvider。
 *
 * @template TExtra 项目专属扩展类型
 */
export interface BatchJobService<TExtra = unknown> {
  /** 列表(分页 + 过滤)。 */
  list(params?: {
    kind?: string;
    status?: BatchJobStatus[];
    cursor?: string;
    limit?: number;
  }): Promise<{ items: BatchJobListItem[]; next_cursor?: string }>;

  /** 详情(含 stages + extra)。 */
  get(id: string): Promise<BatchJob<TExtra>>;

  /** 订阅事件流(增量推送)。返回 unsubscribe 函数。 */
  subscribe(handler: (event: BatchJobEvent) => void): () => void;

  /** 暂停(支持的任务才能调)。 */
  pause?(id: string): Promise<void>;

  /** 恢复。 */
  resume?(id: string): Promise<void>;

  /** 取消。 */
  cancel(id: string, reason?: string): Promise<void>;

  /** 重试失败任务(retryable=true 时)。 */
  retry?(id: string): Promise<BatchJob<TExtra>>;
}

// ============================================================
// Helper utilities
// ============================================================

/** 判断任务是否处于终态。 */
export function isBatchJobTerminal(status: BatchJobStatus): boolean {
  return ['succeeded', 'failed', 'cancelled', 'expired'].includes(status);
}

/** 计算任务耗时(秒);未完成返回 null。 */
export function batchJobDurationSeconds(job: BatchJob): number | null {
  if (!job.started_at || !job.finished_at) return null;
  const start = new Date(job.started_at).getTime();
  const end = new Date(job.finished_at).getTime();
  return (end - start) / 1000;
}

/** 找出当前正在跑的 stage(running 状态最后一个)。 */
export function currentRunningStage(job: BatchJob): BatchJobStage | null {
  for (let i = job.stages.length - 1; i >= 0; i--) {
    const s = job.stages[i];
    if (s && s.status === 'running') return s;
  }
  return null;
}

/** 计算 stage 完成比例(succeeded + skipped 算完成)。 */
export function stagesCompletionRatio(job: BatchJob): number {
  if (job.stages.length === 0) return 0;
  const done = job.stages.filter(
    (s) => s.status === 'succeeded' || s.status === 'skipped'
  ).length;
  return done / job.stages.length;
}
