/**
 * ODashboardLayout - 经典 dashboard 布局 (header + sidebar + main + footer)。
 *
 * SPEC §4.2 命名槽位 + §4.5 视觉装饰允许。
 *
 * 整页 Frame,允许用 @media 检测屏幕宽度做大型布局调整 (SPEC §4.4 例外)。
 *
 * @example
 * <ODashboardLayout
 *   header={<AppHeader />}
 *   sidebar={<NavMenu />}
 *   main={<KanpanContent />}
 *   sidebarCollapsible
 * />
 */
'use client';

import { forwardRef, useState } from 'react';
import { cn } from '../../lib/cn';
import type { FrameSlot, OBlockBaseProps } from '../../lib/types';

export interface ODashboardLayoutProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 顶部 header 槽。 */
  header?: FrameSlot;
  /** 侧栏槽 (左侧默认)。 */
  sidebar?: FrameSlot;
  /** 主区,必填。 */
  main: FrameSlot;
  /** 底部 footer 槽。 */
  footer?: FrameSlot;
  /** 侧栏是否可折叠。默认 true。 */
  sidebarCollapsible?: boolean;
  /** 侧栏初始是否展开。默认 true。 */
  defaultSidebarOpen?: boolean;
  /** 侧栏位置。 */
  sidebarPosition?: 'left' | 'right';
  /** 侧栏宽度 (展开时)。 */
  sidebarWidth?: string;
  /** header 高度。 */
  headerHeight?: string;
  /** footer 高度。 */
  footerHeight?: string;
}

export const ODashboardLayout = forwardRef<HTMLDivElement, ODashboardLayoutProps>(
  function ODashboardLayout(
    {
      header,
      sidebar,
      main,
      footer,
      sidebarCollapsible = true,
      defaultSidebarOpen = true,
      sidebarPosition = 'left',
      sidebarWidth = '16rem',
      headerHeight = '3.5rem',
      footerHeight = '2.5rem',
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const [open, setOpen] = useState(defaultSidebarOpen);
    const collapsedW = '3rem';

    return (
      <div
        ref={ref}
        className={cn('min-h-screen w-full bg-background text-foreground flex flex-col', className)}
      >
        {header ? (
          <header
            className="sticky top-0 z-30 flex items-center border-b border-border bg-card/80 backdrop-blur-md px-4"
            style={{ height: headerHeight }}
          >
            {sidebarCollapsible && sidebar ? (
              <button
                type="button"
                onClick={() => setOpen((v) => !v)}
                className="mr-3 p-1.5 rounded hover:bg-muted text-foreground/80 transition-colors"
                aria-label="Toggle sidebar"
                aria-expanded={open}
              >
                <span className="sr-only">Toggle sidebar</span>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <line x1="3" y1="6" x2="21" y2="6" />
                  <line x1="3" y1="12" x2="21" y2="12" />
                  <line x1="3" y1="18" x2="21" y2="18" />
                </svg>
              </button>
            ) : null}
            <div className="flex-1 min-w-0">{header}</div>
          </header>
        ) : null}

        <div
          className={cn(
            'flex-1 flex min-h-0',
            sidebarPosition === 'right' && 'flex-row-reverse'
          )}
        >
          {sidebar ? (
            <aside
              className={cn(
                'border-border bg-card/40 transition-[width] duration-200 overflow-hidden',
                sidebarPosition === 'left' ? 'border-r' : 'border-l'
              )}
              style={{ width: open ? sidebarWidth : sidebarCollapsible ? collapsedW : sidebarWidth }}
              data-collapsed={!open || undefined}
              aria-hidden={!open}
            >
              <div className="h-full overflow-auto" style={{ width: sidebarWidth }}>
                {sidebar}
              </div>
            </aside>
          ) : null}

          <main className="flex-1 min-w-0 overflow-auto">
            {main}
          </main>
        </div>

        {footer ? (
          <footer
            className="border-t border-border bg-card/40 flex items-center px-4 text-sm text-muted-foreground"
            style={{ height: footerHeight }}
          >
            {footer}
          </footer>
        ) : null}
      </div>
    );
  }
);

ODashboardLayout.displayName = 'ODashboardLayout';
