/**
 * OAgentTraceViewer — Stratum Agent 单次执行的完整 trace 详情.
 *
 * 设计要点 (基于 Stratum 5 Lock + 经理人 R5 5 agent output schema):
 *   - 接 AgentResult (完整,含 trace + citations + output)
 *   - 5 个 agent 各有独立 output 渲染(按 agent_name 分发)
 *   - trace 是平铺 array,按 step_num 时序渲染
 *   - citations 强制渲染 (Stratum ADR)
 *   - output 是开放 dict,未知 agent 用 JSON tree fallback
 *
 * 视觉布局:
 *   ┌─ KPI 行 (耗时 / tokens / cost / status) ─┐
 *   ├─ Agent Output (按 agent_name 分发) ────────┤
 *   ├─ Citations (chip 列表) ────────────────────┤
 *   └─ Trace Steps Timeline (可展开) ────────────┘
 */

'use client';

import { forwardRef, useState } from 'react';
import { cn } from '../../lib/cn';
import { useBlockObservability } from '../../providers/ObservabilityProvider';
import {
  type AgentResult,
  type AgentCitation,
  type AgentTraceStep,
} from '../../types/stratum';

// ============================================================
// Props
// ============================================================

export interface OAgentTraceViewerProps {
  result: AgentResult;
  /** 点击 citation chip → 父组件路由到 ODocumentReader */
  onCitationClick?: (citation: AgentCitation) => void;
  /** 点击 replay step (Phase 14+) */
  onReplayStep?: (step: AgentTraceStep) => void;
  className?: string;
}

// ============================================================
// 工具
// ============================================================

function formatSeconds(sec: number): string {
  if (sec < 60) return `${sec.toFixed(1)}s`;
  return `${Math.floor(sec / 60)}m ${Math.round(sec % 60)}s`;
}

function formatMs(ms: number): string {
  if (ms < 1000) return `${ms}ms`;
  return `${(ms / 1000).toFixed(2)}s`;
}

function formatCost(cost: number): string {
  if (cost === 0) return '免费';
  if (cost < 0.01) return `${(cost * 100).toFixed(2)}¢`;
  return `$${cost.toFixed(3)}`;
}

function formatTokens(tokens: number): string {
  if (tokens < 1000) return String(tokens);
  return `${(tokens / 1000).toFixed(1)}k`;
}

// ============================================================
// 5 个 Agent Output 分发渲染
// (基于经理人 R5 §1 真实 output schema)
// ============================================================

function AgentOutputView({ result }: { result: AgentResult }) {
  switch (result.agent_name) {
    case 'reading_companion':
      return <ReadingCompanionOutput output={result.output} />;
    case 'daily_digest':
      return <DailyDigestOutput output={result.output} />;
    case 'knowledge_curator':
      return <KnowledgeCuratorOutput output={result.output} />;
    case 'translation_worker':
      return <TranslationWorkerOutput output={result.output} />;
    case 'lint_bot':
      return <LintBotOutput output={result.output} />;
    default:
      // 未来新 Agent fallback
      return <JsonViewer data={result.output} />;
  }
}

// --- reading_companion: { answer: string } + 顶层 citations 已渲染 ---
function ReadingCompanionOutput({ output }: { output: Record<string, unknown> }) {
  const answer = typeof output.answer === 'string' ? output.answer : '';
  return (
    <div
      className="prose prose-sm max-w-none"
      style={{
        color: 'var(--foreground)',
        fontFamily: 'var(--font-reading, var(--font-sans))',
        lineHeight: 1.7,
      }}
    >
      {answer || (
        <span className="text-[color:var(--text-muted)]">(无回答内容)</span>
      )}
    </div>
  );
}

// --- daily_digest: { new_substrates: number, digest: string } ---
function DailyDigestOutput({ output }: { output: Record<string, unknown> }) {
  const newSubstrates = Number(output.new_substrates ?? 0);
  const digest = String(output.digest ?? '');
  return (
    <div>
      <div className="flex items-center gap-3 mb-3 text-sm">
        <div className="px-2 py-1 rounded bg-muted tabular-nums">
          24h 新增 <strong>{newSubstrates}</strong> 个 substrate
        </div>
      </div>
      <div
        className="prose prose-sm max-w-none whitespace-pre-wrap"
        style={{
          color: 'var(--foreground)',
          fontFamily: 'var(--font-reading, var(--font-sans))',
          lineHeight: 1.7,
        }}
      >
        {digest}
      </div>
    </div>
  );
}

// --- knowledge_curator: { files_processed, ingested, skipped, failed } ---
function KnowledgeCuratorOutput({ output }: { output: Record<string, unknown> }) {
  const stats = [
    { key: 'files_processed', label: '处理', color: 'oklch(0.55 0.05 240)' },
    { key: 'ingested', label: '入库', color: 'oklch(0.55 0.15 145)' },
    { key: 'skipped', label: '跳过(去重)', color: 'oklch(0.55 0.10 80)' },
    { key: 'failed', label: '失败', color: 'oklch(0.55 0.18 25)' },
  ];
  return (
    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
      {stats.map((s) => (
        <div
          key={s.key}
          className="p-3 rounded border border-border bg-background"
        >
          <div className="text-xs text-[color:var(--text-muted)] mb-1">
            {s.label}
          </div>
          <div
            className="text-2xl font-semibold tabular-nums"
            style={{ color: s.color }}
          >
            {Number(output[s.key] ?? 0)}
          </div>
        </div>
      ))}
    </div>
  );
}

// --- translation_worker: { translated, candidates } ---
function TranslationWorkerOutput({ output }: { output: Record<string, unknown> }) {
  const translated = Number(output.translated ?? 0);
  const candidates = Number(output.candidates ?? 0);
  const rate = candidates > 0 ? (translated / candidates) * 100 : 0;
  return (
    <div>
      <div className="flex items-center justify-between mb-2 text-sm">
        <span className="text-[color:var(--text-muted)]">翻译进度</span>
        <span className="tabular-nums text-[color:var(--foreground)]">
          {translated} / {candidates}
        </span>
      </div>
      <div className="h-2 rounded bg-muted overflow-hidden">
        <div
          className="h-full transition-all"
          style={{
            width: `${rate}%`,
            background: 'oklch(0.60 0.15 145)',
          }}
        />
      </div>
      <div className="mt-2 text-xs text-[color:var(--text-muted)]">
        完成率 {rate.toFixed(0)}%
      </div>
    </div>
  );
}

// --- lint_bot: { issues_count, issues: LintIssue[] } ---
interface LintIssue {
  type: string;
  description: string;
  severity: 'low' | 'medium' | 'high';
  related_substrate_id?: string;
}

const SEVERITY_COLOR: Record<LintIssue['severity'], { bg: string; fg: string }> = {
  low: { bg: 'oklch(0.92 0.05 240)', fg: 'oklch(0.40 0.10 240)' },
  medium: { bg: 'oklch(0.92 0.08 80)', fg: 'oklch(0.40 0.15 80)' },
  high: { bg: 'oklch(0.92 0.08 25)', fg: 'oklch(0.45 0.18 25)' },
};

function LintBotOutput({ output }: { output: Record<string, unknown> }) {
  const issuesCount = Number(output.issues_count ?? 0);
  const issues = Array.isArray(output.issues) ? (output.issues as LintIssue[]) : [];

  if (issuesCount === 0) {
    return (
      <div className="p-4 text-center rounded bg-muted/50 text-[color:var(--muted-foreground)]">
        ✨ 无问题,知识库健康
      </div>
    );
  }

  return (
    <div>
      <div className="mb-2 text-sm text-[color:var(--muted-foreground)]">
        发现 <strong className="tabular-nums">{issuesCount}</strong> 个问题
      </div>
      <ul className="space-y-1.5">
        {issues.map((issue, idx) => {
          const c = SEVERITY_COLOR[issue.severity];
          return (
            <li
              key={idx}
              className="flex items-start gap-2 p-2 rounded border border-border text-sm"
            >
              <span
                className="px-1.5 py-0.5 rounded text-xs font-medium shrink-0 tabular-nums uppercase"
                style={{ background: c.bg, color: c.fg }}
              >
                {issue.severity}
              </span>
              <div className="min-w-0 flex-1">
                <div className="text-[color:var(--foreground)] truncate">
                  {issue.type}
                </div>
                <div className="text-xs text-[color:var(--text-muted)] mt-0.5">
                  {issue.description}
                </div>
              </div>
              {issue.related_substrate_id ? (
                <span
                  className="text-xs font-mono text-[color:var(--text-muted)] shrink-0"
                  title={issue.related_substrate_id}
                >
                  {issue.related_substrate_id.slice(0, 8)}…
                </span>
              ) : null}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

// --- Fallback: JSON tree ---
function JsonViewer({ data }: { data: unknown }) {
  return (
    <pre
      className="text-xs font-mono p-3 rounded bg-muted/40 overflow-auto"
      style={{ color: 'var(--foreground)', maxHeight: 300 }}
    >
      {JSON.stringify(data, null, 2)}
    </pre>
  );
}

// ============================================================
// Citation chip 列表
// ============================================================

function CitationList({
  citations,
  onClick,
}: {
  citations: AgentCitation[];
  onClick?: (c: AgentCitation) => void;
}) {
  if (citations.length === 0) {
    return (
      <div className="text-xs text-[color:var(--text-muted)] italic">
        无引用 — 此回答未涉及任何 substrate (不应该出现,reading_companion ADR 强制 citation)
      </div>
    );
  }
  return (
    <div className="flex flex-wrap gap-1.5">
      {citations.map((c, idx) => (
        <button
          key={idx}
          type="button"
          onClick={() => onClick?.(c)}
          className={cn(
            'inline-flex items-center gap-1 px-2 py-1 rounded text-xs @container',
            'bg-muted/50 hover:bg-muted',
            'border border-border transition-colors',
            'font-mono'
          )}
          title={c.deep_link ?? undefined}
        >
          <span className="text-[color:var(--text-muted)]">📎</span>
          <span className="text-[color:var(--foreground)]">
            {c.substrate_id.slice(0, 12)}…
            {c.fragment_id ? `#${c.fragment_id.slice(0, 6)}` : ''}
          </span>
        </button>
      ))}
    </div>
  );
}

// ============================================================
// Trace Step (可展开)
// ============================================================

function TraceStepItem({ step }: { step: AgentTraceStep }) {
  const [expanded, setExpanded] = useState(false);
  const isError = !!step.error;

  return (
    <li
      className={cn(
        'border-l-2 pl-3 py-1.5 transition-colors',
        isError
          ? 'border-[color:oklch(0.55_0.18_25)]'
          : 'border-border hover:border-primary'
      )}
    >
      <button
        type="button"
        onClick={() => setExpanded((e) => !e)}
        className="w-full flex items-center gap-2 text-sm text-left"
      >
        <span
          className="font-mono text-xs text-[color:var(--text-muted)] tabular-nums shrink-0"
          style={{ width: 28 }}
        >
          #{step.step_num}
        </span>
        <span className="font-medium text-[color:var(--foreground)] truncate">
          {step.tool_name}
        </span>
        <span className="flex-1" />
        <span className="text-xs text-[color:var(--text-muted)] tabular-nums shrink-0">
          {formatMs(step.duration_ms)}
        </span>
        {isError ? (
          <span className="px-1.5 py-0.5 rounded text-xs bg-[oklch(0.92_0.08_25)] text-[oklch(0.45_0.18_25)]">
            error
          </span>
        ) : null}
        <span
          className="text-xs text-[color:var(--text-muted)] shrink-0 transition-transform"
          style={{ transform: expanded ? 'rotate(90deg)' : 'rotate(0)' }}
        >
          ▶
        </span>
      </button>

      {expanded ? (
        <div className="mt-2 space-y-2">
          {/* tool_input */}
          <details open>
            <summary className="text-xs text-[color:var(--text-muted)] cursor-pointer">
              tool_input
            </summary>
            <JsonViewer data={step.tool_input} />
          </details>

          {/* tool_output */}
          {step.tool_output !== null && step.tool_output !== undefined ? (
            <details>
              <summary className="text-xs text-[color:var(--text-muted)] cursor-pointer">
                tool_output
              </summary>
              <JsonViewer data={step.tool_output} />
            </details>
          ) : null}

          {/* error */}
          {step.error ? (
            <div className="p-2 rounded bg-[oklch(0.97_0.04_25)] border border-[oklch(0.85_0.10_25)] text-xs text-[oklch(0.40_0.18_25)] font-mono">
              {step.error}
            </div>
          ) : null}
        </div>
      ) : null}
    </li>
  );
}

// ============================================================
// 主 Component
// ============================================================

export const OAgentTraceViewer = forwardRef<HTMLDivElement, OAgentTraceViewerProps>(
  function OAgentTraceViewer(
    { result, onCitationClick, className },
    ref
  ) {
    const { dataAttrs, recordEvent } = useBlockObservability('OAgentTraceViewer');

    const totalTokens = result.total_input_tokens + result.total_output_tokens;

    function handleCitationClick(c: AgentCitation) {
      recordEvent('citation_clicked', { substrateId: c.substrate_id });
      onCitationClick?.(c);
    }

    return (
      <div
        {...dataAttrs}
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card',
          'flex flex-col gap-4 p-4',
          className
        )}
        style={{ fontFamily: 'var(--font-ui)' }}
      >
        {/* === KPI 行 === */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
          <KpiCard
            label="耗时"
            value={formatSeconds(result.elapsed_seconds)}
            sublabel="elapsed_seconds"
          />
          <KpiCard
            label="Tokens"
            value={formatTokens(totalTokens)}
            sublabel={`in ${formatTokens(result.total_input_tokens)} / out ${formatTokens(result.total_output_tokens)}`}
          />
          <KpiCard
            label="成本"
            value={formatCost(result.cost_usd)}
            sublabel="cost_usd"
          />
          <KpiCard
            label="状态"
            value={result.status ?? 'unknown'}
            highlight={result.status === 'failed' || result.status === 'timeout'}
          />
        </div>

        {/* === Output 区 (按 agent_name 分发) === */}
        <section>
          <h3 className="text-xs font-medium text-[color:var(--text-muted)] uppercase tracking-[0.04em] mb-2">
            Output ({result.agent_name})
          </h3>
          {result.status === 'failed' || result.status === 'timeout' ? (
            <div className="p-3 rounded bg-[oklch(0.97_0.04_25)] border border-[oklch(0.85_0.10_25)] text-sm">
              <div className="font-medium text-[oklch(0.40_0.18_25)]">
                {result.status === 'timeout' ? '执行超时' : '执行失败'}
              </div>
              {result.error_message ? (
                <div className="mt-1 text-xs font-mono text-[oklch(0.45_0.15_25)]">
                  {result.error_message}
                </div>
              ) : null}
            </div>
          ) : (
            <div className="p-3 rounded bg-background border border-border/50">
              <AgentOutputView result={result} />
            </div>
          )}
        </section>

        {/* === Citations (强制) === */}
        <section>
          <h3 className="text-xs font-medium text-[color:var(--text-muted)] uppercase tracking-[0.04em] mb-2">
            Citations ({result.citations.length})
          </h3>
          <CitationList
            citations={result.citations}
            onClick={handleCitationClick}
          />
        </section>

        {/* === Trace Steps === */}
        <section>
          <h3 className="text-xs font-medium text-[color:var(--text-muted)] uppercase tracking-[0.04em] mb-2">
            Trace ({result.trace.length} steps)
          </h3>
          {result.trace.length === 0 ? (
            <div className="text-xs text-[color:var(--text-muted)] italic">
              无 trace 记录
            </div>
          ) : (
            <ul className="space-y-1">
              {result.trace.map((step) => (
                <TraceStepItem key={step.step_num} step={step} />
              ))}
            </ul>
          )}
        </section>

        {/* === 元信息 === */}
        <div className="text-xs text-[color:var(--text-muted)] font-mono pt-2 border-t border-border/30">
          run_id: {result.run_id} · started_at: {result.started_at}
        </div>
      </div>
    );
  }
);

OAgentTraceViewer.displayName = 'OAgentTraceViewer';

// ============================================================
// Sub: KPI Card (本 Block 内部用,不暴露)
// ============================================================

function KpiCard({
  label,
  value,
  sublabel,
  highlight,
}: {
  label: string;
  value: string;
  sublabel?: string;
  highlight?: boolean;
}) {
  return (
    <div
      className={cn(
        'p-2.5 rounded border bg-background',
        highlight
          ? 'border-[oklch(0.55_0.18_25)]'
          : 'border-border'
      )}
    >
      <div className="text-[10px] text-[color:var(--text-muted)] uppercase tracking-[0.04em]">
        {label}
      </div>
      <div
        className={cn(
          'text-lg font-semibold tabular-nums',
          highlight
            ? 'text-[oklch(0.55_0.18_25)]'
            : 'text-[color:var(--foreground)]'
        )}
        style={{ fontFamily: 'var(--font-data)' }}
      >
        {value}
      </div>
      {sublabel ? (
        <div className="text-[10px] text-[color:var(--text-muted)] mt-0.5 font-mono">
          {sublabel}
        </div>
      ) : null}
    </div>
  );
}
