/**
 * OTimeSeriesChart - 时序图 (Terminal-grade v1.0)。
 *
 * Recharts 实现 + 跨图联动 + Worker 数据流。
 *
 * Terminal-grade 升级 (Batch 15):
 *   ✓ syncToCrosshair  跨图联动 (鼠标 hover 时 broadcast + 接收时显示 ReferenceLine)
 *   ✓ channel          FastDataProvider 直接订阅
 *   ✓ dataDelay        合规延时标签
 *   ✓ syncToTimeline   时空切片回放
 *
 * @example
 *   <OTimeSeriesChart data={{ symbol: 'BTC', series: [...] }} syncToCrosshair />
 */
'use client';

import {
  Area, AreaChart, Bar, BarChart, CartesianGrid, Legend, Line, LineChart,
  ResponsiveContainer, Tooltip, XAxis, YAxis, ReferenceLine,
} from 'recharts';
import { forwardRef, useEffect, useMemo, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import { useFastData } from '../../providers/FastDataProvider';
import { useCrosshair } from '../../providers/CrosshairProvider';
import { useTimeline } from '../../providers/TimelineProvider';

export interface OTimeSeriesPoint {
  x: number | string | Date;
  y: number;
}

export interface OTimeSeriesData {
  series: { name: string; data: OTimeSeriesPoint[] }[];
  xAxis?: { format?: (v: unknown) => string; label?: string };
  yAxis?: { format?: (v: number) => string; label?: string };
  /** Terminal-grade: 标的 (用于 crosshair 联动)。 */
  symbol?: string;
}

export interface OTimeSeriesChartProps
  extends OBlockDataProps<OTimeSeriesData>,
    Pick<
      TerminalBlockProps,
      'syncToCrosshair' | 'channel' | 'dataDelay' | 'regulation' | 'syncToTimeline' | 'lowPerformanceMode'
    > {
  variant?: 'line' | 'area' | 'bar';
  height?: number;
  showLegend?: boolean;
  showGrid?: boolean;
}

/**
 * 把多 series 合并为 recharts 接受的 [{ x, series1, series2, ... }] 格式。
 */
function transform(series: OTimeSeriesData['series']) {
  const keyMap = new Map<string | number, Record<string, unknown>>();
  for (const s of series) {
    for (const p of s.data) {
      const k = p.x instanceof Date ? p.x.toISOString() : p.x;
      const row = keyMap.get(k) ?? { x: p.x };
      row[s.name] = p.y;
      keyMap.set(k, row);
    }
  }
  return Array.from(keyMap.values()).sort((a, b) => {
    const ax = a.x as number | string;
    const bx = b.x as number | string;
    if (typeof ax === 'number' && typeof bx === 'number') return ax - bx;
    return String(ax).localeCompare(String(bx));
  });
}

const CHART_COLORS = [
  'var(--quote-up)',
  'var(--quote-down)',
  'var(--accent)',
  'var(--primary)',
  'var(--secondary)',
];

export const OTimeSeriesChart = forwardRef<HTMLDivElement, OTimeSeriesChartProps>(
  function OTimeSeriesChart(
    {
      data: dataProp,
      loading,
      error,
      empty,
      variant = 'line',
      height = 320,
      showLegend = true,
      showGrid = true,
      syncToCrosshair,
      channel,
      dataDelay = 0,
      regulation: _r,
      syncToTimeline,
      lowPerformanceMode,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    // Worker 订阅
    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OTimeSeriesData | null>(null);

    useEffect(() => {
      if (!channel || !fastData) return;
      return fastData.subscribe<OTimeSeriesData>(channel, setChannelData);
    }, [channel, fastData]);

    const rawData = channel ? channelData : (dataProp ?? null);

    // Timeline 切片: 如果 syncToTimeline 且当前 timeline 有值,过滤数据到那个时间点
    const timeline = useTimeline();
    const [timelineSlice, setTimelineSlice] = useState<number | null>(null);

    useEffect(() => {
      if (!syncToTimeline || !timeline) return;
      return timeline.subscribe((s) => setTimelineSlice(s.currentTime));
    }, [timeline, syncToTimeline]);

    const data = useMemo<OTimeSeriesData | null>(() => {
      if (!rawData) return null;
      if (timelineSlice == null) return rawData;
      // 截断到 timelineSlice 时间点
      const cutoffMs = timelineSlice * 1000;
      const sliced = rawData.series.map((s) => ({
        ...s,
        data: s.data.filter((p) => {
          const t = p.x instanceof Date ? p.x.getTime() : typeof p.x === 'number' ? p.x : new Date(p.x).getTime();
          return t <= cutoffMs;
        }),
      }));
      return { ...rawData, series: sliced };
    }, [rawData, timelineSlice]);

    // Crosshair
    const crosshair = useCrosshair();
    const [crossX, setCrossX] = useState<number | string | null>(null);
    const symbolForCrosshair =
      typeof syncToCrosshair === 'string'
        ? syncToCrosshair
        : syncToCrosshair === true
          ? data?.symbol
          : null;

    useEffect(() => {
      if (!symbolForCrosshair || !crosshair) return;
      return crosshair.subscribe((s) => {
        if (s.symbol === symbolForCrosshair && s.time != null) {
          // 转换 unix 秒到我们 x 轴的格式 (假设 x 是 unix 秒或类似)
          setCrossX(s.time);
        } else {
          setCrossX(null);
        }
      });
    }, [crosshair, symbolForCrosshair]);

    const state = resolveBlockState({ data, loading, error, empty });

    const transformed = useMemo(
      () => (state === 'ready' && data ? transform(data.series) : []),
      [data, state]
    );

    const formatX = data?.xAxis?.format ?? ((v: unknown) => String(v));
    const formatY = data?.yAxis?.format ?? ((v: number) => String(v));

    // 状态分流
    if (state === 'loading') {
      return (
        <div
          ref={ref}
          className={cn(
            'rounded-md border border-border bg-card p-4 @container',
            className
          )}
          style={{ height }}
        >
          <OLoadingState variant="shimmer" rows={3} rowHeight="2rem" />
        </div>
      );
    }
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data || data.series.length === 0)
      return (
        <OEmptyState
          ref={ref}
          title="No data"
          description="The chart has no series to render."
          className={className}
        />
      );

    // 选 chart 组件
    const ChartComp = variant === 'area' ? AreaChart : variant === 'bar' ? BarChart : LineChart;

    function handleMouseMove(e: unknown) {
      if (!symbolForCrosshair || !crosshair) return;
      // recharts 的 onMouseMove 给的是 { activeLabel, activePayload, ... }
      const evt = e as { activeLabel?: number | string; activePayload?: { value: number }[] };
      if (evt.activeLabel == null) return;
      const value = evt.activePayload?.[0]?.value;
      const t =
        typeof evt.activeLabel === 'number'
          ? evt.activeLabel
          : new Date(evt.activeLabel).getTime() / 1000;
      crosshair.broadcast({ symbol: symbolForCrosshair, time: t, value: value ?? null });
    }

    function handleMouseLeave() {
      if (!symbolForCrosshair || !crosshair) return;
      crosshair.broadcast({ symbol: null, time: null, value: null });
    }

    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card p-2 relative',
          className
        )}
        style={{ height }}
      >
        {dataDelay > 0 ? (
          <div className="absolute top-2 right-3 z-10 text-[10px] text-[color:var(--alert-warn)] font-mono pointer-events-none">
            延时 {dataDelay}m
          </div>
        ) : null}
        {timelineSlice != null ? (
          <div className="absolute top-2 left-3 z-10 text-[10px] text-[color:var(--alert-info)] font-mono pointer-events-none">
            回放: {new Date(timelineSlice * 1000).toLocaleTimeString()}
          </div>
        ) : null}
        <ResponsiveContainer width="100%" height="100%">
          <ChartComp
            data={transformed}
            margin={{ top: 10, right: 10, left: 0, bottom: 0 }}
            onMouseMove={handleMouseMove as never}
            onMouseLeave={handleMouseLeave}
          >
            {showGrid && !lowPerformanceMode ? (
              <CartesianGrid stroke="var(--grid-major)" strokeDasharray="2 4" />
            ) : null}
            <XAxis
              dataKey="x"
              tickFormatter={formatX as never}
              stroke="var(--text-muted)"
              tick={{ fontSize: 11, fill: 'var(--text-muted)' }}
              label={data.xAxis?.label ? { value: data.xAxis.label, position: 'insideBottom', offset: -2 } : undefined}
            />
            <YAxis
              tickFormatter={formatY}
              stroke="var(--text-muted)"
              tick={{ fontSize: 11, fill: 'var(--text-muted)' }}
              label={data.yAxis?.label ? { value: data.yAxis.label, angle: -90, position: 'insideLeft' } : undefined}
            />
            {!lowPerformanceMode ? (
              <Tooltip
                contentStyle={{
                  background: 'var(--popover)',
                  border: '1px solid var(--border)',
                  borderRadius: 4,
                  fontSize: 11,
                  color: 'var(--popover-foreground)',
                }}
              />
            ) : null}
            {showLegend ? <Legend wrapperStyle={{ fontSize: 11 }} /> : null}
            {/* crosshair ReferenceLine - 当其他 Block broadcast 时显示 */}
            {crossX != null ? (
              <ReferenceLine
                x={crossX as never}
                stroke="var(--foreground)"
                strokeOpacity={0.5}
                strokeDasharray="2 3"
              />
            ) : null}
            {data.series.map((s, i) => {
              const color = CHART_COLORS[i % CHART_COLORS.length];
              if (variant === 'line') {
                return (
                  <Line
                    key={s.name}
                    type="monotone"
                    dataKey={s.name}
                    stroke={color}
                    strokeWidth={1.8}
                    dot={false}
                    isAnimationActive={false}
                  />
                );
              }
              if (variant === 'area') {
                return (
                  <Area
                    key={s.name}
                    type="monotone"
                    dataKey={s.name}
                    stroke={color}
                    fill={color}
                    fillOpacity={0.2}
                    isAnimationActive={false}
                  />
                );
              }
              return (
                <Bar key={s.name} dataKey={s.name} fill={color} isAnimationActive={false} />
              );
            })}
          </ChartComp>
        </ResponsiveContainer>
      </div>
    );
  }
);

OTimeSeriesChart.displayName = 'OTimeSeriesChart';
