/**
 * OArticleHeader - 文章/博客标题头。
 *
 * 标题 + 副标题 + 作者 + 发布时间 + 标签 + 阅读时间估算。
 */
'use client';

import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OAuthor {
  name: string;
  avatar?: string;
  link?: string;
}

export interface OArticleHeaderProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  title: string;
  subtitle?: string;
  authors?: OAuthor[];
  /** ISO 字符串或 Date。 */
  publishedAt?: string | Date;
  /** 阅读时间 (分钟)。如不提供且 contentLength 有值则估算。 */
  readingMinutes?: number;
  /** 文章字数 (用于估算 readingMinutes)。 */
  contentLength?: number;
  tags?: string[];
  /** 封面图 URL。 */
  cover?: string;
  /** 视觉变体。 */
  variant?: 'default' | 'centered' | 'minimal';
  /** 字数到分钟的转换率 (默认 200 wpm)。 */
  wordsPerMinute?: number;
}

function formatDate(d: string | Date): string {
  const date = typeof d === 'string' ? new Date(d) : d;
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
}

function AvatarStack({ authors }: { authors: OAuthor[] }) {
  return (
    <div className="flex -space-x-2">
      {authors.slice(0, 3).map((a) => (
        a.avatar ? (
          <img
            key={a.name}
            src={a.avatar}
            alt={a.name}
            className="w-8 h-8 rounded-full border-2 border-background object-cover"
          />
        ) : (
          <div
            key={a.name}
            className="w-8 h-8 rounded-full border-2 border-background bg-primary/15 text-primary flex items-center justify-center text-xs font-medium"
          >
            {a.name[0]?.toUpperCase()}
          </div>
        )
      ))}
    </div>
  );
}

export const OArticleHeader = forwardRef<HTMLElement, OArticleHeaderProps>(function OArticleHeader(
  {
    title,
    subtitle,
    authors = [],
    publishedAt,
    readingMinutes,
    contentLength,
    tags = [],
    cover,
    variant = 'default',
    wordsPerMinute = 200,
    className,
    theme: _t,
  },
  ref
) {
  const estimatedRead =
    readingMinutes ??
    (typeof contentLength === 'number' ? Math.max(1, Math.round(contentLength / wordsPerMinute)) : null);

  const centered = variant === 'centered';

  return (
    <header
      ref={ref}
      className={cn(
        'w-full space-y-4 @container',
        centered && 'text-center',
        variant === 'minimal' && 'pb-4 border-b border-border',
        className
      )}
    >
      {tags.length > 0 ? (
        <div className={cn('flex flex-wrap gap-2', centered && 'justify-center')}>
          {tags.map((t) => (
            <span
              key={t}
              className="px-2 py-0.5 text-xs rounded-full bg-primary/10 text-primary"
            >
              {t}
            </span>
          ))}
        </div>
      ) : null}
      <h1 className={cn('font-bold tracking-tight text-foreground', variant === 'minimal' ? 'text-2xl' : 'text-3xl md:text-5xl')}>
        {title}
      </h1>
      {subtitle ? (
        <p className={cn('text-lg text-muted-foreground', !centered && 'max-w-3xl')}>
          {subtitle}
        </p>
      ) : null}
      <div
        className={cn(
          'flex flex-wrap items-center gap-x-4 gap-y-2 text-sm text-muted-foreground',
          centered && 'justify-center'
        )}
      >
        {authors.length > 0 ? (
          <div className="flex items-center gap-2">
            <AvatarStack authors={authors} />
            <span className="text-foreground">
              {authors.map((a, i) => (
                <span key={a.name}>
                  {a.link ? (
                    <a href={a.link} className="hover:underline">{a.name}</a>
                  ) : (
                    a.name
                  )}
                  {i < authors.length - 1 ? ', ' : ''}
                </span>
              ))}
            </span>
          </div>
        ) : null}
        {publishedAt ? (
          <>
            <span aria-hidden></span>
            <time dateTime={typeof publishedAt === 'string' ? publishedAt : publishedAt.toISOString()}>
              {formatDate(publishedAt)}
            </time>
          </>
        ) : null}
        {estimatedRead != null ? (
          <>
            <span aria-hidden></span>
            <span>{estimatedRead} min read</span>
          </>
        ) : null}
      </div>
      {cover ? (
        <img
          src={cover}
          alt=""
          className="w-full rounded-lg aspect-video object-cover mt-6"
        />
      ) : null}
    </header>
  );
});

OArticleHeader.displayName = 'OArticleHeader';
