/**
 * ONumberInput - 数字输入。
 *
 * 受控,带:
 *   - 步进按钮 (+/-)
 *   - 单位前后缀
 *   - min/max/step
 *   - 千分位格式化 (可选)
 *   - 键盘 ↑↓ 步进
 */
'use client';

import { forwardRef, useState, type InputHTMLAttributes, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface ONumberInputProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'value' | 'defaultValue' | 'onChange' | 'size' | 'prefix'>,
    Omit<OBlockBaseProps, 'size'> {
  value?: number | null;
  defaultValue?: number;
  onChange?: (value: number | null) => void;
  min?: number;
  max?: number;
  step?: number;
  /** 显示步进按钮。 */
  showSteppers?: boolean;
  /** 前缀 (e.g. "$" )。 */
  prefix?: ReactNode;
  /** 后缀单位 (e.g. "USD", "%")。 */
  suffix?: ReactNode;
  /** 千分位格式化。 */
  thousandsSeparator?: boolean;
  /** 小数位数。 */
  precision?: number;
  size?: 'sm' | 'md' | 'lg';
  invalid?: boolean;
}

function clamp(v: number, min: number | undefined, max: number | undefined): number {
  if (typeof min === 'number' && v < min) v = min;
  if (typeof max === 'number' && v > max) v = max;
  return v;
}

function formatNumber(n: number | null, precision?: number, thousands?: boolean): string {
  if (n == null || Number.isNaN(n)) return '';
  const fixed = typeof precision === 'number' ? n.toFixed(precision) : String(n);
  if (!thousands) return fixed;
  const [intPart, decPart] = fixed.split('.');
  const withCommas = (intPart ?? '').replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return decPart ? `${withCommas}.${decPart}` : withCommas;
}

// 高度走密度 token(与 inputRecipe 一致),让 [data-density] compact/terminal 生效,
// 不再写死 h-8/h-10(既不跟随密度,又与其它输入控件高度不一致)。
const SIZE = {
  sm: 'h-[var(--control-h-sm)] text-[length:var(--text-xs)]',
  md: 'h-[var(--control-h-md)] text-[length:var(--text-sm)]',
  lg: 'h-[var(--control-h-lg)] text-[length:var(--text-base)]',
};

export const ONumberInput = forwardRef<HTMLInputElement, ONumberInputProps>(function ONumberInput(
  {
    value,
    defaultValue,
    onChange,
    min,
    max,
    step = 1,
    showSteppers = true,
    prefix,
    suffix,
    thousandsSeparator = false,
    precision,
    size = 'md',
    invalid,
    className,
    disabled,
    theme: _t,
    ...rest
  },
  ref
) {
  const [internal, setInternal] = useState<number | null>(defaultValue ?? null);
  const isControlled = value !== undefined;
  const currentValue = isControlled ? value ?? null : internal;

  function commit(next: number | null) {
    if (next != null) next = clamp(next, min, max);
    if (!isControlled) setInternal(next);
    onChange?.(next);
  }

  function onInputChange(e: React.ChangeEvent<HTMLInputElement>) {
    const raw = e.target.value.replace(/,/g, '');
    if (raw === '' || raw === '-') {
      commit(raw === '' ? null : 0);
      return;
    }
    const n = Number(raw);
    if (Number.isFinite(n)) commit(n);
  }

  function stepBy(delta: number) {
    const base = currentValue ?? 0;
    commit(base + delta);
  }

  function onKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === 'ArrowUp') {
      e.preventDefault();
      stepBy(step);
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      stepBy(-step);
    }
  }

  const displayValue = formatNumber(currentValue, precision, thousandsSeparator);

  return (
    <div
      className={cn(
        'flex items-stretch w-full bg-card border border-input rounded-md overflow-hidden transition-colors @container',
        'focus-within:ring-2 focus-within:ring-ring',
        invalid && '!border-destructive focus-within:!ring-destructive',
        disabled && 'opacity-50',
        SIZE[size],
        className
      )}
    >
      {prefix ? (
        <span className="flex items-center px-3 text-muted-foreground border-r border-border bg-muted/30 shrink-0">
          {prefix}
        </span>
      ) : null}

      <input
        ref={ref}
        type="text"
        inputMode="decimal"
        value={displayValue}
        onChange={onInputChange}
        onKeyDown={onKeyDown}
        disabled={disabled}
        className={cn(
          'flex-1 bg-transparent outline-none min-w-0 px-3 tabular-nums',
          'placeholder:text-muted-foreground'
        )}
        {...rest}
      />

      {suffix ? (
        <span className="flex items-center px-3 text-muted-foreground border-l border-border bg-muted/30 shrink-0">
          {suffix}
        </span>
      ) : null}

      {showSteppers ? (
        <div className="flex flex-col border-l border-border shrink-0">
          <button
            type="button"
            tabIndex={-1}
            disabled={disabled || (typeof max === 'number' && (currentValue ?? 0) >= max)}
            onClick={() => stepBy(step)}
            aria-label="Increment"
            className="flex-1 px-2 text-muted-foreground hover:text-foreground hover:bg-muted/40 transition-colors disabled:opacity-30 disabled:cursor-not-allowed border-b border-border"
          >
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
              <polyline points="18 15 12 9 6 15" />
            </svg>
          </button>
          <button
            type="button"
            tabIndex={-1}
            disabled={disabled || (typeof min === 'number' && (currentValue ?? 0) <= min)}
            onClick={() => stepBy(-step)}
            aria-label="Decrement"
            className="flex-1 px-2 text-muted-foreground hover:text-foreground hover:bg-muted/40 transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
          >
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
              <polyline points="6 9 12 15 18 9" />
            </svg>
          </button>
        </div>
      ) : null}
    </div>
  );
});

ONumberInput.displayName = 'ONumberInput';
