/**
 * OVideoPlayer - 视频播放器。
 *
 * 自定义播放控件 (避免浏览器默认 controls 不能主题化)。
 * HLS 通过 dynamic import hls.js (~70KB),仅在 m3u8 url 才加载。
 *
 * 受控:src 由 Page 提供。
 * 简化:不实现复杂的 PiP / 字幕选择,只做核心功能。
 */
'use client';

import { forwardRef, useEffect, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OVideoPlayerProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  /** 视频 URL。可以是 mp4 / webm / m3u8 (HLS)。 */
  src: string;
  /** 海报图。 */
  poster?: string;
  /** 自动播放 (静音,符合浏览器策略)。 */
  autoplay?: boolean;
  /** 循环。 */
  loop?: boolean;
  /** 默认静音。 */
  muted?: boolean;
  /** 字幕轨 (VTT URL)。 */
  subtitles?: Array<{ lang: string; label: string; src: string }>;
  /** 容器宽高比。 */
  aspectRatio?: '16/9' | '4/3' | '1/1' | '9/16';
  /** 标题 (顶部显示)。 */
  title?: string;
}

function formatTime(sec: number): string {
  if (!Number.isFinite(sec) || sec < 0) sec = 0;
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${m}:${String(s).padStart(2, '0')}`;
}

export const OVideoPlayer = forwardRef<HTMLDivElement, OVideoPlayerProps>(function OVideoPlayer(
  {
    src,
    poster,
    autoplay = false,
    loop = false,
    muted: initialMuted = false,
    subtitles = [],
    aspectRatio = '16/9',
    title,
    className,
    theme: _t,
  },
  ref
) {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [playing, setPlaying] = useState(false);
  const [muted, setMuted] = useState(initialMuted || autoplay);
  const [time, setTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [showControls, setShowControls] = useState(true);
  const hideTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // HLS 支持
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    if (src.endsWith('.m3u8') && !video.canPlayType('application/vnd.apple.mpegurl')) {
      // hls.js 第三方,structurally type 局部以避免 any
      interface HlsLike {
        loadSource(src: string): void;
        attachMedia(el: HTMLVideoElement): void;
        destroy(): void;
      }
      interface HlsCtor {
        new (): HlsLike;
        isSupported(): boolean;
      }
      let hlsInstance: HlsLike | null = null;
      import('hls.js' as never).then((mod) => {
        const Hls = (mod as { default: HlsCtor }).default;
        if (Hls?.isSupported()) {
          hlsInstance = new Hls();
          hlsInstance.loadSource(src);
          hlsInstance.attachMedia(video);
        }
      }).catch((e) => console.error('HLS load failed', e));
      return () => {
        hlsInstance?.destroy();
      };
    } else {
      video.src = src;
      return undefined;
    }
  }, [src]);

  function togglePlay() {
    const v = videoRef.current;
    if (!v) return;
    if (v.paused) v.play();
    else v.pause();
  }

  function toggleMute() {
    const v = videoRef.current;
    if (!v) return;
    v.muted = !v.muted;
    setMuted(v.muted);
  }

  function seek(t: number) {
    const v = videoRef.current;
    if (!v) return;
    v.currentTime = t;
  }

  function fullscreen() {
    const v = videoRef.current;
    if (!v) return;
    if (document.fullscreenElement) {
      document.exitFullscreen?.();
    } else {
      v.requestFullscreen?.();
    }
  }

  function hideControlsLater() {
    if (hideTimeoutRef.current) clearTimeout(hideTimeoutRef.current);
    hideTimeoutRef.current = setTimeout(() => setShowControls(false), 2500);
  }

  return (
    <div
      ref={ref}
      className={cn('relative bg-black overflow-hidden rounded-md group', className)}
      style={{ aspectRatio }}
      onMouseEnter={() => {
        setShowControls(true);
        hideControlsLater();
      }}
      onMouseMove={() => {
        setShowControls(true);
        hideControlsLater();
      }}
      onMouseLeave={() => {
        if (playing) setShowControls(false);
      }}
    >
      <video
        ref={videoRef}
        poster={poster}
        autoPlay={autoplay}
        loop={loop}
        muted={muted}
        playsInline
        className="w-full h-full"
        onPlay={() => setPlaying(true)}
        onPause={() => setPlaying(false)}
        onTimeUpdate={() => setTime(videoRef.current?.currentTime ?? 0)}
        onLoadedMetadata={() => setDuration(videoRef.current?.duration ?? 0)}
        onClick={togglePlay}
      >
        {subtitles.map((s) => (
          <track key={s.lang} kind="subtitles" srcLang={s.lang} label={s.label} src={s.src} />
        ))}
      </video>

      {title ? (
        <div
          className={cn(
            'absolute top-0 left-0 right-0 p-3 bg-gradient-to-b from-black/80 to-transparent text-white text-sm transition-opacity @container',
            showControls ? 'opacity-100' : 'opacity-0'
          )}
        >
          {title}
        </div>
      ) : null}

      <div
        className={cn(
          'absolute bottom-0 left-0 right-0 p-3 bg-gradient-to-t from-black/80 to-transparent text-white transition-opacity',
          showControls ? 'opacity-100' : 'opacity-0'
        )}
      >
        <input
          type="range"
          min={0}
          max={duration || 1}
          step="any"
          value={time}
          onChange={(e) => seek(Number(e.target.value))}
          aria-label="Seek"
          className="w-full accent-primary"
        />
        <div className="flex items-center gap-3 mt-1 text-xs">
          <button onClick={togglePlay} aria-label={playing ? 'Pause' : 'Play'} className="hover:opacity-80">
            {playing ? (
              <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16" /><rect x="14" y="4" width="4" height="16" /></svg>
            ) : (
              <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3" /></svg>
            )}
          </button>
          <span className="tabular-nums">{formatTime(time)} / {formatTime(duration)}</span>
          <div className="flex-1" />
          <button onClick={toggleMute} aria-label={muted ? 'Unmute' : 'Mute'} className="hover:opacity-80">
            {muted ? (
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" /><line x1="23" y1="9" x2="17" y2="15" /><line x1="17" y1="9" x2="23" y2="15" /></svg>
            ) : (
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" /><path d="M15.54 8.46a5 5 0 010 7.07" /></svg>
            )}
          </button>
          <button onClick={fullscreen} aria-label="Fullscreen" className="hover:opacity-80">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M8 3H5a2 2 0 00-2 2v3 M21 8V5a2 2 0 00-2-2h-3 M3 16v3a2 2 0 002 2h3 M16 21h3a2 2 0 002-2v-3" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
});

OVideoPlayer.displayName = 'OVideoPlayer';
