/**
 * OAlertBadge (Tide Wave 3 E18, Atom)
 *
 * 顶部状态条 alert badge,带 pulse 动画。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §2.3
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { useUiLang } from '../../lang/LangProvider';
import type { OBlockBaseProps } from '../../lib/types';

export interface OAlertBadgeProps extends Omit<OBlockBaseProps, 'variant'> {
  count: number;
  criticalCount: number;
  hasUnread: boolean;
  onClick?: () => void;
}

export const OAlertBadge = forwardRef<HTMLButtonElement, OAlertBadgeProps>(
  function OAlertBadge(
    { count, criticalCount, hasUnread, onClick, className, theme: _t, size: _s },
    ref
  ) {
    const { tr } = useUiLang();
    const hasCritical = criticalCount > 0;
    const isNormal = count === 0;

    let bg: string;
    let fg: string;
    let icon: string;
    let label: string;

    if (hasCritical) {
      bg = 'var(--destructive)';
      fg = 'var(--destructive-foreground)';
      icon = '⚠';
      label = `${criticalCount} critical`;
    } else if (count > 0) {
      bg = 'var(--warning)';
      fg = 'var(--warning-foreground)';
      icon = '!';
      label = `${count}`;
    } else {
      bg = 'var(--muted)';
      fg = 'var(--muted-foreground)';
      icon = '✓';
      label = tr('正常', 'Normal');
    }

    return (
      <button
        ref={ref}
        type="button"
        onClick={onClick}
        aria-label={
          hasCritical
            ? `${criticalCount} ${tr('条紧急告警', 'critical alerts')}`
            : count > 0
              ? `${count} ${tr('条告警', 'alerts')}`
              : tr('系统正常', 'System normal')
        }
        className={cn(
          'inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-xs font-bold @container',
          'transition-opacity hover:opacity-80',
          hasCritical && hasUnread && 'animate-pulse',
          'focus:outline-none focus-visible:ring-2 focus-visible:ring-ring',
          className
        )}
        style={{
          backgroundColor: bg,
          color: fg,
          fontFamily: 'var(--font-mono)',
          cursor: onClick && !isNormal ? 'pointer' : 'default',
        }}
      >
        <span aria-hidden="true">{icon}</span>
        <span>{label}</span>
      </button>
    );
  }
);

OAlertBadge.displayName = 'OAlertBadge';
