/**
 * OSplitFrame - 可拖拽分割容器。
 *
 * 基于 react-resizable-panels。两个 named slot: primary / secondary。
 *
 * @example
 * <OSplitFrame
 *   direction="horizontal"
 *   ratio={[1, 2]}
 *   primary={<NavSidebar />}
 *   secondary={<MainContent />}
 * />
 */
'use client';

import { forwardRef, useId } from 'react';
import { Group, Panel, Separator } from 'react-resizable-panels';
import { cn } from '../../lib/cn';
import type { FrameSlot, OBlockBaseProps } from '../../lib/types';

export interface OSplitFrameProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 切割方向。 */
  direction?: 'horizontal' | 'vertical';
  /** 初始比例 [primary, secondary]。默认 [1, 1]。 */
  ratio?: [number, number];
  /** 是否允许用户拖动。默认 true。 */
  resizable?: boolean;
  /** primary 最小尺寸 (百分比)。 */
  minPrimary?: number;
  /** secondary 最小尺寸 (百分比)。 */
  minSecondary?: number;
  /** primary slot. */
  primary: FrameSlot;
  /** secondary slot. */
  secondary: FrameSlot;
  /** 容器整体高度,默认 100%。 */
  height?: string | number;
}

export const OSplitFrame = forwardRef<HTMLDivElement, OSplitFrameProps>(function OSplitFrame(
  {
    direction = 'horizontal',
    ratio = [1, 1],
    resizable = true,
    minPrimary = 10,
    minSecondary = 10,
    primary,
    secondary,
    height = '100%',
    className,
    theme: _t,
    size: _s,
  },
  ref
) {
  const id = useId();
  const total = ratio[0] + ratio[1];
  const sizeP = (ratio[0] / total) * 100;
  const sizeS = (ratio[1] / total) * 100;

  return (
    <div ref={ref} className={cn('w-full', className)} style={{ height }}>
      <Group orientation={direction} id={`split-${id}`}>
        <Panel defaultSize={sizeP} minSize={minPrimary}>
          <div className="h-full w-full overflow-auto">{primary}</div>
        </Panel>
        <Separator
          disabled={!resizable}
          className={cn(
            'bg-border transition-colors hover:bg-primary/40',
            direction === 'horizontal' ? 'w-px hover:w-1 cursor-col-resize' : 'h-px hover:h-1 cursor-row-resize',
            !resizable && 'pointer-events-none'
          )}
        />
        <Panel defaultSize={sizeS} minSize={minSecondary}>
          <div className="h-full w-full overflow-auto">{secondary}</div>
        </Panel>
      </Group>
    </div>
  );
});

OSplitFrame.displayName = 'OSplitFrame';
