/**
 * OKPICard - KPI 卡片 (Terminal-grade v1.0)。
 *
 * SPEC 多次引用的标杆 Block。
 * 数据契约: { label, primary, secondary?, indicator?, sparkline?, symbol? }
 * 自适应: container queries (sm/md/lg padding + 字号)
 *
 * Terminal-grade 升级 (Batch 15):
 *   ✓ flashOnUpdate    五维数据脉冲
 *   ✓ syncToCrosshair  跨图联动 (data.symbol 自动 broadcast)
 *   ✓ channel          FastDataProvider 直接订阅
 *   ✓ dataDelay        合规延时标签
 *   ✓ regulation       合规类型 (默认 quote)
 *
 * @example 简单用法 (向后兼容,无 Terminal 升级)
 *   <OKPICard data={{ label: 'BTC/USDT', primary: '67,432', indicator: 'up' }} />
 *
 * @example Terminal-grade 用法
 *   <OKPICard
 *     data={{ symbol: 'BTC/USDT', label: 'BTC/USDT', primary: 67432, indicator: 'up' }}
 *     flashOnUpdate={{ modes: ['color', 'density'] }}
 *     syncToCrosshair
 *     dataDelay={0}
 *   />
 *
 * @example 从 Worker channel 直接订阅
 *   <OKPICard channel="kpi:BTC-USDT" syncToCrosshair flashOnUpdate />
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, useEffect, useState } from 'react';
import { cn } from '../../lib/cn';
import { useUiLang } from '../../lang/LangProvider';
import { resolveBlockState } from '../../lib/resolveBlockState';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import { useFlashOnChange } from '../../hooks/useFlashOnChange';
import { useFastData } from '../../providers/FastDataProvider';
import { useCrosshair } from '../../providers/CrosshairProvider';

// ============================================================
// 数据契约
// ============================================================

export interface OKPIData {
  label: string;
  primary: number | string;
  secondary?: string;
  indicator?: 'up' | 'down' | 'neutral';
  /** 趋势百分比 (e.g. 2.3 for +2.3%) */
  changePercent?: number;
  /** sparkline 数据点。 */
  sparkline?: number[];
  /** 标的 key (Terminal-grade: 用于 crosshair 联动 / 数据脉冲方向)。 */
  symbol?: string;
}

const kpiVariants = cva(
  'rounded-md border border-border bg-card text-card-foreground transition-colors @container flex flex-col gap-1 relative',
  {
    variants: {
      variant: {
        standard: 'p-4',
        compact: 'p-2',
        detailed: 'p-6 gap-2',
      },
    },
    defaultVariants: { variant: 'standard' },
  }
);

type KPIVariantProps = VariantProps<typeof kpiVariants>;

export interface OKPICardProps
  extends OBlockDataProps<OKPIData>,
    KPIVariantProps,
    Pick<
      TerminalBlockProps,
      'flashOnUpdate' | 'syncToCrosshair' | 'channel' | 'dataDelay' | 'regulation'
    > {}

// ============================================================
// Sparkline (跟之前一样,保留)
// ============================================================

function MiniSparkline({
  values,
  indicator,
}: {
  values: number[];
  indicator?: 'up' | 'down' | 'neutral';
}) {
  if (!values.length) return null;
  const min = Math.min(...values);
  const max = Math.max(...values);
  const range = max - min || 1;
  const w = 80;
  const h = 24;
  const step = values.length > 1 ? w / (values.length - 1) : w;
  const points = values
    .map(
      (v, i) =>
        `${(i * step).toFixed(2)},${(h - ((v - min) / range) * h).toFixed(2)}`
    )
    .join(' ');

  const color =
    indicator === 'up'
      ? 'var(--quote-up)'
      : indicator === 'down'
        ? 'var(--quote-down)'
        : 'var(--muted-foreground)';

  return (
    <svg
      viewBox={`0 0 ${w} ${h}`}
      width={w}
      height={h}
      aria-hidden="true"
      className="overflow-visible"
    >
      <polyline
        points={points}
        fill="none"
        stroke={color}
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function IndicatorArrow({
  direction,
}: {
  direction: 'up' | 'down' | 'neutral';
}) {
  if (direction === 'neutral') {
    return (
      <span className="text-[color:var(--text-muted)]" aria-hidden="true">
        ●
      </span>
    );
  }
  return (
    <span
      style={{
        color:
          direction === 'up' ? 'var(--quote-up)' : 'var(--quote-down)',
      }}
      aria-hidden="true"
    >
      {direction === 'up' ? '▲' : '▼'}
    </span>
  );
}

// ============================================================
// 主组件
// ============================================================

export const OKPICard = forwardRef<HTMLDivElement, OKPICardProps>(
  function OKPICard(
    {
      data: dataProp,
      loading,
      error,
      empty,
      variant = 'standard',
      flashOnUpdate,
      syncToCrosshair,
      channel,
      dataDelay = 0,
      regulation = 'quote',
      className,
      theme: _t,
      size: _s,
      ...rest
    },
    ref
  ) {
    const { tr } = useUiLang();
    // Worker 数据流订阅 (channel 优先)
    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OKPIData | null>(null);

    useEffect(() => {
      if (!channel || !fastData) return;
      const unsub = fastData.subscribe<OKPIData>(channel, (next) => {
        setChannelData(next);
      });
      return unsub;
    }, [channel, fastData]);

    const data = channel ? channelData : (dataProp ?? null);
    const state = resolveBlockState({ data, loading, error, empty });

    // 数据脉冲 - 监听 primary 数值变化
    const flashConfig =
      flashOnUpdate === true
        ? { modes: ['color' as const, 'density' as const] }
        : flashOnUpdate === false || !flashOnUpdate
          ? null
          : flashOnUpdate;

    const flashValue =
      data && typeof data.primary === 'number'
        ? data.primary
        : data && typeof data.primary === 'string'
          ? parseFloat(data.primary.replace(/[,$\s]/g, ''))
          : 0;

    const flashRef = useFlashOnChange(
      flashConfig ? flashValue : null,
      flashConfig ?? { modes: [] }
    );

    // crosshair 同步 - 鼠标 hover 时 broadcast
    const crosshair = useCrosshair();
    const symbolForCrosshair =
      typeof syncToCrosshair === 'string'
        ? syncToCrosshair
        : syncToCrosshair === true
          ? data?.symbol
          : null;

    function handleMouseEnter() {
      if (!symbolForCrosshair || !crosshair) return;
      crosshair.broadcast({
        symbol: symbolForCrosshair,
        time: Date.now() / 1000,
        value: typeof flashValue === 'number' ? flashValue : null,
      });
    }
    function handleMouseLeave() {
      if (!symbolForCrosshair || !crosshair) return;
      crosshair.broadcast({ symbol: null, time: null, value: null });
    }

    // 状态分流
    if (state === 'loading') {
      return (
        <div ref={ref} className={cn(kpiVariants({ variant }), className)} {...rest}>
          <OLoadingState rows={2} rowHeight="1rem" />
        </div>
      );
    }
    if (state === 'error') {
      return (
        <OErrorState ref={ref} error={error!} variant="inline" className={cn(className)} />
      );
    }
    if (state === 'empty' || !data) {
      return (
        <OEmptyState
          ref={ref}
          title={data?.label ?? 'No data'}
          variant="minimal"
          className={cn(kpiVariants({ variant }), className)}
        />
      );
    }

    return (
      <div
        ref={ref}
        className={cn(kpiVariants({ variant }), className)}
        data-indicator={data.indicator}
        data-regulation={regulation}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        {...rest}
      >
        {/* 顶部:标签 + 延时标签 (合规) */}
        <div className="flex items-baseline justify-between gap-2">
          <div className="text-[0.625rem] @[200px]:text-[0.6875rem] text-[color:var(--text-muted)] font-semibold uppercase tracking-[0.04em] truncate">
            {data.label}
          </div>
          {dataDelay > 0 ? (
            <span className="text-[9px] text-[color:var(--alert-warn)] shrink-0 font-mono">
              {tr("延时", "Delay")} {dataDelay}m
            </span>
          ) : null}
        </div>

        {/* 主体 */}
        <div className="flex items-end justify-between gap-3">
          <div className="min-w-0 flex-1">
            {/* primary - 这是脉冲目标元素 */}
            <div
              ref={flashRef as never}
              className="text-2xl @[200px]:text-3xl @[400px]:text-4xl font-extrabold tabular-nums truncate tracking-[-0.03em] leading-none"
              style={{
                fontFamily: 'var(--font-display, var(--font-data, ui-monospace, monospace))',
                fontWeight: 'var(--weight-display, 780)',
                color:
                  data.indicator === 'up'
                    ? 'var(--quote-up)'
                    : data.indicator === 'down'
                      ? 'var(--quote-down)'
                      : 'inherit',
              }}
            >
              {data.primary}
            </div>
            {data.secondary || data.indicator || typeof data.changePercent === 'number' ? (
              <div className="text-xs @[200px]:text-sm text-[color:var(--text-muted)] flex items-center gap-1 mt-0.5">
                {data.indicator ? <IndicatorArrow direction={data.indicator} /> : null}
                {typeof data.changePercent === 'number' ? (
                  <span
                    style={{
                      color:
                        data.indicator === 'up'
                          ? 'var(--quote-up)'
                          : data.indicator === 'down'
                            ? 'var(--quote-down)'
                            : undefined,
                    }}
                    className="tabular-nums"
                  >
                    {data.changePercent >= 0 ? '+' : ''}
                    {data.changePercent.toFixed(2)}%
                  </span>
                ) : null}
                {data.secondary ? <span className="ml-1">{data.secondary}</span> : null}
              </div>
            ) : null}
          </div>
          {data.sparkline && data.sparkline.length > 0 ? (
            <div className="hidden @[200px]:block shrink-0">
              <MiniSparkline values={data.sparkline} indicator={data.indicator} />
            </div>
          ) : null}
        </div>
      </div>
    );
  }
);

OKPICard.displayName = 'OKPICard';
