/**
 * ORadarChart — 多维度雷达图(认识论中性,只显客观值)。
 *
 * 用途:
 *   - AII Diagnosis Page:知识点掌握度雷达
 *   - 任何"多维度对比"场景(skill 矩阵 / 角色能力图 / KPI 多维评估)
 *
 * ⚠ 硬护栏(AII 经理人 §3 约束,红线 #3 落地):
 *   - 禁止 reference line / target zone / threshold band
 *   - 禁止"达标线 / 及格线 / 目标区 / 建议区"任何隐含价值判断的视觉元素
 *   - 掌握度就是掌握度,是高是低用户自己判断
 *   - 图不替用户画"应该到哪"的线
 *
 * 不提供 prop 让外部加 reference line 是有意为之 — 把"不开处方"原则
 * 烧进 API,使各项目想加目标线也加不了(违规会被阻止)。
 */
import { forwardRef, useMemo } from 'react';
import { cn } from '../../lib/cn';
import { useUiLang } from '../../lang/LangProvider';
import type { OBlockBaseProps } from '../../lib/types';

export interface RadarAxis {
  /** 轴名称(显示在图外)。 */
  label: string;
  /** 当前值。 */
  value: number;
}

export interface RadarSeries {
  /** Series 名称(legend / 多 series 区分时用)。 */
  name?: string;
  /** 多边形填充色 CSS var。 */
  colorVar?: string;
  /** 各轴的值,顺序对应 axes 数组。 */
  values: number[];
}

export interface ORadarChartProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 轴定义(至少 3 个)。 */
  axes: { label: string }[];
  /** 一个或多个 series。 */
  series: RadarSeries[];
  /** 最大值(归一化用,默认按所有 series 最大值计算)。 */
  maxValue?: number;
  /** 网格层数(同心多边形,默认 4)。 */
  gridLevels?: number;
  /** 视图尺寸(px,默认 320)。 */
  svgSize?: number;
  /** 标题。 */
  title?: string;
  /** 显示数值标注在各轴端点。 */
  showValueLabels?: boolean;
}

const DEFAULT_COLORS = [
  'var(--info)',
  'var(--success)',
  'var(--warning)',
  'var(--muted-foreground)',
];

export const ORadarChart = forwardRef<HTMLDivElement, ORadarChartProps>(function ORadarChart(
  {
    axes,
    series,
    maxValue,
    gridLevels = 4,
    svgSize = 320,
    title,
    showValueLabels = false,
    className,
    theme: _t,
    size: _s,
  },
  ref
) {
  const { tr } = useUiLang();
  const computed = useMemo(() => {
    if (axes.length < 3 || series.length === 0) return null;
    const n = axes.length;
    const cx = svgSize / 2;
    const cy = svgSize / 2;
    const radius = (svgSize / 2) * 0.7;

    // 算 max
    const allValues = series.flatMap((s) => s.values);
    const max = maxValue ?? Math.max(...allValues, 1);

    // 各轴角度(顶部开始,顺时针)
    const angles = axes.map((_, i) => -Math.PI / 2 + (2 * Math.PI * i) / n);
    const axisPoints = angles.map((a) => ({
      x: cx + Math.cos(a) * radius,
      y: cy + Math.sin(a) * radius,
    }));

    // 网格(同心多边形 — 注意:只是网格,不是 reference line)
    const gridPolys = Array.from({ length: gridLevels }, (_, i) => {
      const r = (radius * (i + 1)) / gridLevels;
      return angles
        .map((a) => `${cx + Math.cos(a) * r},${cy + Math.sin(a) * r}`)
        .join(' ');
    });

    // 各 series 多边形
    const seriesPolys = series.map((s, si) => {
      const points = s.values
        .map((v, i) => {
          const r = (Math.min(v, max) / max) * radius;
          return {
            x: cx + Math.cos(angles[i]!) * r,
            y: cy + Math.sin(angles[i]!) * r,
            value: v,
          };
        });
      return {
        name: s.name,
        color: s.colorVar ?? DEFAULT_COLORS[si % DEFAULT_COLORS.length]!,
        points,
        pointsStr: points.map((p) => `${p.x},${p.y}`).join(' '),
      };
    });

    return { cx, cy, radius, axisPoints, gridPolys, seriesPolys, max };
  }, [axes, series, maxValue, gridLevels, svgSize]);

  if (!computed) {
    return (
      <div
        ref={ref}
        className={cn(
          'flex items-center justify-center px-3 py-2 rounded border border-dashed text-xs text-muted-foreground @container',
          className
        )}
        style={{ minHeight: 60 }}
      >
        {tr('雷达图需要 ≥ 3 个轴和 ≥ 1 个 series', 'Radar chart requires ≥ 3 axes and ≥ 1 series')}
      </div>
    );
  }

  const { cx, cy, axisPoints, gridPolys, seriesPolys, max } = computed;

  return (
    <div
      ref={ref}
      className={cn('flex flex-col gap-2', className)}
    >
      {title && <div className="text-sm font-medium">{title}</div>}
      <svg
        width={svgSize}
        height={svgSize}
        viewBox={`0 0 ${svgSize} ${svgSize}`}
        role="img"
        aria-label={
          title
            ? `${title} ${tr('雷达图', 'radar chart')},${axes.length} ${tr('维', 'dims')},${series.length} ${tr('个系列', 'series')}`
            : `${tr('雷达图', 'Radar chart')},${axes.length} ${tr('维', 'dims')}`
        }
      >
        {/* 网格(同心多边形,纯视觉参考,无语义 — 不是 reference line) */}
        {gridPolys.map((poly, i) => (
          <polygon
            key={i}
            points={poly}
            fill="none"
            stroke="var(--border)"
            strokeWidth={1}
            strokeOpacity={0.4}
          />
        ))}

        {/* 轴线 */}
        {axisPoints.map((p, i) => (
          <line
            key={i}
            x1={cx}
            y1={cy}
            x2={p.x}
            y2={p.y}
            stroke="var(--border)"
            strokeWidth={1}
            strokeOpacity={0.5}
          />
        ))}

        {/* Series 多边形 */}
        {seriesPolys.map((s, si) => (
          <g key={si}>
            <polygon
              points={s.pointsStr}
              fill={s.color}
              fillOpacity={0.18}
              stroke={s.color}
              strokeWidth={1.5}
              strokeLinejoin="round"
            />
            {s.points.map((p, i) => (
              <circle
                key={i}
                cx={p.x}
                cy={p.y}
                r={2.5}
                fill={s.color}
              />
            ))}
            {showValueLabels &&
              s.points.map((p, i) => (
                <text
                  key={i}
                  x={p.x}
                  y={p.y - 5}
                  fontSize={9}
                  fill="var(--foreground)"
                  textAnchor="middle"
                >
                  {p.value.toFixed(2)}
                </text>
              ))}
          </g>
        ))}

        {/* 轴 label(显示在图外) */}
        {axisPoints.map((p, i) => {
          // 略外推一点
          const dx = p.x - cx;
          const dy = p.y - cy;
          const len = Math.sqrt(dx * dx + dy * dy);
          const outX = cx + (dx / len) * (len + 16);
          const outY = cy + (dy / len) * (len + 12);
          // textAnchor 根据位置选
          let anchor: 'start' | 'middle' | 'end' = 'middle';
          if (Math.abs(dx) > 0.5) anchor = dx > 0 ? 'start' : 'end';
          return (
            <text
              key={i}
              x={outX}
              y={outY}
              fontSize={11}
              fill="var(--foreground)"
              textAnchor={anchor}
              dominantBaseline="middle"
            >
              {axes[i]!.label}
            </text>
          );
        })}
      </svg>

      {series.length > 1 && (
        <ul className="flex flex-wrap gap-3 list-none p-0 m-0 text-xs">
          {seriesPolys.map((s, i) => (
            <li key={i} className="inline-flex items-center gap-1">
              <span
                className="w-2.5 h-2.5 rounded-sm"
                style={{ backgroundColor: s.color }}
                aria-hidden="true"
              />
              <span>{s.name ?? `${tr('系列', 'Series')} ${i + 1}`}</span>
            </li>
          ))}
        </ul>
      )}

      {/* 值域提示 */}
      <div className="text-[10px] text-muted-foreground">
        {tr('最大值', 'Max')} {max.toFixed(2)} · {tr('仅显示客观数值,不含目标线/达标线', 'objective values only; no target / threshold lines')}
      </div>
    </div>
  );
});

ORadarChart.displayName = 'ORadarChart';
