/**
 * OMuteRulesModal (Tide Wave 3 E17, Block)
 *
 * 静音规则管理 modal。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §2.2
 */
import { forwardRef, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface MuteRule {
  id: string;
  scopeType: 'symbol' | 'anomaly_type' | 'time_window' | 'combined';
  scopeValue: string | Record<string, unknown>;
  duration: '1h' | 'today' | 'this_week' | 'permanent' | 'custom_hours';
  createdAt: string | Date;
  expiresAt?: string | Date;
  description: string;
  remainingMinutes?: number;
}

export interface NewMuteRule {
  scope: { type: string; value: unknown };
  duration: string;
  customHours?: number;
}

export interface OMuteRulesModalProps extends Omit<OBlockBaseProps, 'variant'> {
  isOpen: boolean;
  rules: MuteRule[];
  onAdd?: (rule: NewMuteRule) => void;
  onRemove?: (ruleId: string) => void;
  onClose: () => void;
}

const SCOPE_LABEL: Record<string, string> = {
  symbol: '个股',
  anomaly_type: '异常类型',
  time_window: '时段',
  combined: '组合',
};

export const OMuteRulesModal = forwardRef<HTMLDivElement, OMuteRulesModalProps>(
  function OMuteRulesModal(
    { isOpen, rules, onRemove, onClose, className, theme: _t, size: _s },
    ref
  ) {
    const dialogRef = useRef<HTMLDivElement | null>(null);

    useEffect(() => {
      if (!isOpen) return;
      const onKey = (e: globalThis.KeyboardEvent) => {
        if (e.key === 'Escape') onClose();
      };
      document.addEventListener('keydown', onKey);
      return () => document.removeEventListener('keydown', onKey);
    }, [isOpen, onClose]);

    useEffect(() => {
      if (isOpen && dialogRef.current) dialogRef.current.focus();
    }, [isOpen]);

    if (!isOpen) return null;

    const content = (
      <div
        role="presentation"
        className="fixed inset-0 z-[1000] flex items-center justify-center"
        style={{ backgroundColor: 'rgba(0,0,0,0.5)' }}
        onClick={onClose}
      >
        <div
          ref={(n) => {
            dialogRef.current = n;
            if (typeof ref === 'function') ref(n);
            else if (ref) ref.current = n;
          }}
          role="dialog"
          aria-modal="true"
          aria-label="静音规则管理"
          tabIndex={-1}
          onClick={(e) => e.stopPropagation()}
          className={cn(
            'w-[600px] max-h-[500px] rounded-md flex flex-col @container',
            'bg-[color:var(--card)] border border-[color:var(--border-strong)]',
            'shadow-2xl',
            className
          )}
          style={{ fontFamily: 'var(--font-sans)' }}
        >
          <div className="flex items-center justify-between px-3 py-2 border-b border-[color:var(--border-subtle)]">
            <h2 className="text-sm font-bold tracking-[-0.01em]" style={{ color: 'var(--foreground)' }}>
              静音规则 ({rules.length})
            </h2>
            <button
              type="button"
              onClick={onClose}
              aria-label="关闭"
              className="text-xs px-2 py-0.5 rounded hover:bg-[color:var(--muted)]"
              style={{ color: 'var(--muted-foreground)' }}
            >
              关闭
            </button>
          </div>

          <div className="flex-1 overflow-auto p-3">
            {rules.length === 0 ? (
              <div
                className="px-4 py-6 text-center text-sm"
                style={{ color: 'var(--text-tertiary)' }}
              >
                暂无静音规则
              </div>
            ) : (
              <ul className="flex flex-col gap-2 list-none p-0 m-0">
                {rules.map((r) => (
                  <li
                    key={r.id}
                    className={cn(
                      'flex items-center gap-2 px-3 py-2 rounded',
                      'bg-[color:var(--muted)] border border-[color:var(--border-subtle)]'
                    )}
                  >
                    <span
                      className="text-[10px] px-1.5 py-0.5 rounded font-mono"
                      style={{
                        backgroundColor: 'var(--blue-accent)',
                        color: '#fff',
                      }}
                    >
                      {SCOPE_LABEL[r.scopeType] ?? r.scopeType}
                    </span>
                    <div className="flex-1 flex flex-col">
                      <span className="text-xs" style={{ color: 'var(--foreground)' }}>
                        {r.description}
                      </span>
                      <span
                        className="text-[10px]"
                        style={{ color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)' }}
                      >
                        {r.duration}
                        {r.remainingMinutes !== undefined &&
                          ` · 剩余 ${r.remainingMinutes} 分钟`}
                      </span>
                    </div>
                    {onRemove && (
                      <button
                        type="button"
                        onClick={() => onRemove(r.id)}
                        className={cn(
                          'px-2 py-0.5 text-[10px] rounded',
                          'text-[color:var(--red-up)]'
                        )}
                        style={{
                          backgroundColor:
                            'color-mix(in srgb, var(--red-up) 15%, transparent)',
                        }}
                      >
                        取消
                      </button>
                    )}
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>
    );

    return typeof document !== 'undefined' ? createPortal(content, document.body) : null;
  }
);

OMuteRulesModal.displayName = 'OMuteRulesModal';
