/**
 * ONullableNumber — null 数据的显式展示策略
 *
 * 来源:Helios 经理人 R1 §1.6(ADR-038 诚实到不舒服)+ 红线 #1
 * 哲学:**绝不替你假装算出**。null 必须显式标注,不能用 0 / N/A / -- 蒙混。
 *
 * 跨项目通用:任何 number | null 字段(fusion score / position pnl / kpi 等)。
 */

'use client';

import { forwardRef } from 'react';
import { cn } from './cn';

export type ONullableNumberPolicy =
  /** 显示 placeholder 字符串(默认 "—",有提示但弱化)。 */
  | 'placeholder'
  /** 显示 "数据缺失" 红色警告(关键字段必须明示)。 */
  | 'stale-warning'
  /** 显示 "数据矛盾" 红色警告(冲突 / contradictory state)。 */
  | 'contradictory'
  /** 数据缺失时整个组件不渲染(非关键字段)。 */
  | 'hide';

export interface ONullableNumberProps {
  /** 数值。null / undefined 触发 policy 渲染。 */
  value: number | null | undefined;
  /** null 时怎么显示。默认 placeholder。 */
  policy?: ONullableNumberPolicy;
  /** 自定义格式化(value 非 null 时调)。默认 toLocaleString。 */
  format?: (n: number) => string;
  /** placeholder 字符 / 文案(policy='placeholder' 时用)。默认 "—"。 */
  placeholder?: string;
  /** 警告文案(policy='stale-warning' / 'contradictory' 时用)。 */
  warningText?: string;
  /** 类名透传。 */
  className?: string;
}

/**
 * 显式处理 null 的数字展示。
 *
 * @example
 * ```tsx
 * <ONullableNumber value={fusion.bullScore} policy="contradictory" />
 * // 非 null 时:渲染 toLocaleString 数字
 * // null 时:红色 "数据矛盾"(不是 0,不是空)
 * ```
 */
export const ONullableNumber = forwardRef<HTMLSpanElement, ONullableNumberProps>(
  function ONullableNumber(
    {
      value,
      policy = 'placeholder',
      format,
      placeholder = '—',
      warningText,
      className,
    },
    ref
  ) {
    if (value == null) {
      if (policy === 'hide') return null;

      if (policy === 'stale-warning') {
        return (
          <span
            ref={ref}
            role="status"
            aria-label="数据缺失"
            className={cn('text-destructive font-medium', className)}
          >
            {warningText ?? '数据缺失'}
          </span>
        );
      }

      if (policy === 'contradictory') {
        return (
          <span
            ref={ref}
            role="status"
            aria-label="数据矛盾"
            className={cn('text-destructive font-medium', className)}
          >
            {warningText ?? '数据矛盾'}
          </span>
        );
      }

      // policy === 'placeholder'
      return (
        <span
          ref={ref}
          aria-label="无数据"
          className={cn('text-muted-foreground', className)}
        >
          {placeholder}
        </span>
      );
    }

    const text = format ? format(value) : value.toLocaleString();
    return (
      <span ref={ref} className={cn('o-data-number', className)}>
        {text}
      </span>
    );
  }
);
