/**
 * OAvatarGroup - 多头像堆叠展示。
 *
 * 超过 max 时显示 "+N" 余量。
 * 鼠标 hover 可展开(可选)。
 */
'use client';

import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';
import { OAvatar, type OAvatarProps } from '../OAvatar';

export interface OAvatarPerson {
  name: string;
  src?: string;
}

export interface OAvatarGroupProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  people: OAvatarPerson[];
  /** 最多显示数,超出显示 +N。 */
  max?: number;
  /** 头像尺寸,会传给所有头像。 */
  size?: OAvatarProps['size'];
  /** 堆叠方向。 */
  direction?: 'rtl' | 'ltr';
  /** 单击 "+N" 时回调(可打开完整列表)。 */
  onMoreClick?: () => void;
}

export const OAvatarGroup = forwardRef<HTMLDivElement, OAvatarGroupProps>(function OAvatarGroup(
  { people, max = 4, size = 'md', direction = 'rtl', onMoreClick, className, theme: _t },
  ref
) {
  const visible = people.slice(0, max);
  const overflow = people.length - visible.length;

  return (
    <div
      ref={ref}
      className={cn(
        'inline-flex @container',
        direction === 'rtl' ? '-space-x-2' : '-space-x-2 flex-row-reverse',
        className
      )}
    >
      {visible.map((p, i) => (
        <OAvatar
          key={`${p.name}-${i}`}
          name={p.name}
          src={p.src}
          size={size}
          bordered
        />
      ))}
      {overflow > 0 ? (
        <OAvatar
          name={`+${overflow}`}
          size={size}
          bordered
          onClick={onMoreClick}
          fallback={<span className="font-semibold">+{overflow}</span>}
        />
      ) : null}
    </div>
  );
});

OAvatarGroup.displayName = 'OAvatarGroup';
