/**
 * OMacroCycleTags (Tide Wave 3 E24, Atom)
 *
 * 宏观周期 tag chips(9 规则)。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §4.1
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export type CycleSentiment = 'positive' | 'negative' | 'neutral';

export interface MacroCycleTag {
  id: string;
  label: string;
  sentiment: CycleSentiment;
  /** 触发该 tag 的规则 ID */
  ruleId?: string;
  /** 强度 0-1 */
  intensity?: number;
  description?: string;
}

export interface OMacroCycleTagsProps extends Omit<OBlockBaseProps, 'variant'> {
  tags: MacroCycleTag[];
  /** 'inline' or 'grid' */
  layout?: 'inline' | 'grid';
  onTagClick?: (tag: MacroCycleTag) => void;
}

const SENTIMENT_COLOR: Record<CycleSentiment, string> = {
  positive: 'var(--red-up)', // A 股: 利好 = 红
  negative: 'var(--green-down)',
  neutral: 'var(--muted-foreground)',
};

const SENTIMENT_ICON: Record<CycleSentiment, string> = {
  positive: '↑',
  negative: '↓',
  neutral: '→',
};

export const OMacroCycleTags = forwardRef<HTMLDivElement, OMacroCycleTagsProps>(
  function OMacroCycleTags(
    { tags, layout = 'inline', onTagClick, className, theme: _t, size: _s },
    ref
  ) {
    if (tags.length === 0) {
      return (
        <div
          ref={ref}
          className={cn(
            'text-center py-4 text-xs border border-dashed rounded @container',
            className
          )}
          style={{ color: 'var(--text-tertiary)', borderColor: 'var(--border-strong)' }}
        >
          无宏观信号
        </div>
      );
    }

    return (
      <ul
        ref={ref as React.Ref<HTMLUListElement>}
        className={cn(
          'list-none p-0 m-0',
          layout === 'inline' ? 'flex flex-wrap gap-1.5' : 'grid grid-cols-2 gap-1.5',
          className
        )}
        style={{ fontFamily: 'var(--font-mono)' }}
        aria-label="宏观周期标签"
      >
        {tags.map((t) => {
          const color = SENTIMENT_COLOR[t.sentiment];
          const intensity = t.intensity ?? 0.5;
          const baseColor =
            t.sentiment === 'neutral'
              ? 'var(--muted)'
              : `color-mix(in srgb, ${color} ${Math.round(intensity * 35)}%, var(--card))`;
          return (
            <li key={t.id}>
              {onTagClick ? (
                <button
                  type="button"
                  onClick={() => onTagClick(t)}
                  title={t.description}
                  className={cn(
                    'inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs',
                    'hover:opacity-80 cursor-pointer transition-opacity'
                  )}
                  style={{
                    backgroundColor: baseColor,
                    color: 'var(--foreground)',
                    border: `1px solid ${color}`,
                    fontFamily: 'inherit',
                  }}
                >
                  <span style={{ color }} aria-hidden="true">
                    {SENTIMENT_ICON[t.sentiment]}
                  </span>
                  <span>{t.label}</span>
                </button>
              ) : (
                <span
                  title={t.description}
                  className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs"
                  style={{
                    backgroundColor: baseColor,
                    color: 'var(--foreground)',
                    border: `1px solid ${color}`,
                  }}
                >
                  <span style={{ color }} aria-hidden="true">
                    {SENTIMENT_ICON[t.sentiment]}
                  </span>
                  <span>{t.label}</span>
                </span>
              )}
            </li>
          );
        })}
      </ul>
    );
  }
);

OMacroCycleTags.displayName = 'OMacroCycleTags';
