/**
 * OEquityCurveChart (Tide Wave 3 E28, Block)
 *
 * 资产曲线(IS / OOS-1 / OOS-2 三段)+ drawdown 子图。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §5.1
 */
import { forwardRef, useMemo } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface EquityPoint {
  date: string;
  /** 净值 累计 */
  equity: number;
  /** drawdown 0..-1 */
  drawdown?: number;
  /** 'is'(in-sample) / 'oos1' / 'oos2' */
  phase?: 'is' | 'oos1' | 'oos2';
}

export interface PhaseStats {
  totalReturn: number;
  maxDrawdown: number;
  sharpe?: number;
  winrate?: number;
}

export interface OEquityCurveChartProps extends Omit<OBlockBaseProps, 'variant'> {
  points: EquityPoint[];
  /** 阶段统计(可选,显示在 chart 上方) */
  phaseStats?: {
    is?: PhaseStats;
    oos1?: PhaseStats;
    oos2?: PhaseStats;
  };
  /** 是否显示 drawdown 子图 */
  showDrawdown?: boolean;
  height?: number;
}

const PHASE_COLOR: Record<'is' | 'oos1' | 'oos2', string> = {
  is: 'var(--text-tertiary)',
  oos1: 'var(--blue-accent)',
  oos2: 'var(--red-up)',
};

const PHASE_LABEL: Record<'is' | 'oos1' | 'oos2', string> = {
  is: 'IS (in-sample)',
  oos1: 'OOS-1',
  oos2: 'OOS-2',
};

export const OEquityCurveChart = forwardRef<HTMLDivElement, OEquityCurveChartProps>(
  function OEquityCurveChart(
    {
      points,
      phaseStats,
      showDrawdown = true,
      height = 240,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const view = useMemo(() => {
      if (points.length === 0) return null;
      const w = 600;
      const ddH = showDrawdown ? 60 : 0;
      const equityH = height - 80 - ddH;
      const equityVals = points.map((p) => p.equity);
      const maxEq = Math.max(...equityVals, 1.0);
      const minEq = Math.min(...equityVals, 1.0);
      const eqRange = maxEq - minEq || 1;
      const stepX = w / Math.max(points.length - 1, 1);

      // build path per phase to color separately
      const segments: { phase: 'is' | 'oos1' | 'oos2'; d: string }[] = [];
      let curPhase: 'is' | 'oos1' | 'oos2' | undefined;
      let curPath: string[] = [];

      points.forEach((p, i) => {
        const phase = p.phase ?? 'is';
        const x = i * stepX;
        const y = 4 + ((maxEq - p.equity) / eqRange) * (equityH - 8);

        if (phase !== curPhase) {
          if (curPath.length > 0 && curPhase) {
            segments.push({ phase: curPhase, d: curPath.join(' ') });
          }
          curPath = [`M ${x} ${y}`];
          // 链接上一段
          if (curPhase && i > 0) {
            const prev = points[i - 1]!;
            const px = (i - 1) * stepX;
            const py = 4 + ((maxEq - prev.equity) / eqRange) * (equityH - 8);
            curPath = [`M ${px} ${py}`, `L ${x} ${y}`];
          }
          curPhase = phase;
        } else {
          curPath.push(`L ${x} ${y}`);
        }
      });
      if (curPath.length > 0 && curPhase) {
        segments.push({ phase: curPhase, d: curPath.join(' ') });
      }

      // 1.0 baseline y
      const y1 = 4 + ((maxEq - 1.0) / eqRange) * (equityH - 8);

      // drawdown bars
      const ddBars = showDrawdown
        ? points.map((p, i) => {
            const dd = p.drawdown ?? 0;
            const ddPct = Math.max(0, Math.abs(dd));
            const barH = ddPct * (ddH - 4);
            return {
              x: i * stepX,
              y: 4,
              h: barH,
              w: stepX * 0.9,
            };
          })
        : [];

      return { w, equityH, ddH, segments, y1, ddBars, maxEq, minEq };
    }, [points, height, showDrawdown]);

    if (!view) {
      return (
        <div
          ref={ref}
          className={cn('py-6 text-center text-sm border border-dashed rounded', className)}
          style={{ color: 'var(--text-tertiary)', borderColor: 'var(--border-strong)' }}
        >
          无回测数据
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn(
          'flex flex-col gap-2 px-3 py-2 rounded @container',
          'bg-[color:var(--card)] border border-[color:var(--border-strong)]',
          className
        )}
        style={{ fontFamily: 'var(--font-mono)' }}
        role="region"
        aria-label="资产曲线"
      >
        {/* phase stats */}
        {phaseStats && (
          <div className="grid grid-cols-3 gap-2 text-[10px]">
            {(['is', 'oos1', 'oos2'] as const).map((ph) => {
              const s = phaseStats[ph];
              if (!s) return <div key={ph} />;
              return (
                <div
                  key={ph}
                  className="px-2 py-1 rounded"
                  style={{
                    backgroundColor: 'var(--muted)',
                    borderLeft: `2px solid ${PHASE_COLOR[ph]}`,
                  }}
                >
                  <div style={{ color: PHASE_COLOR[ph], fontWeight: 700 }}>
                    {PHASE_LABEL[ph]}
                  </div>
                  <div style={{ color: 'var(--foreground)' }}>
                    收益 {(s.totalReturn * 100).toFixed(1)}%
                  </div>
                  <div style={{ color: 'var(--green-down)' }}>
                    MDD {(s.maxDrawdown * 100).toFixed(1)}%
                  </div>
                  {s.sharpe !== undefined && (
                    <div style={{ color: 'var(--muted-foreground)' }}>
                      Sharpe {s.sharpe.toFixed(2)}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}

        {/* svg chart */}
        <svg
          width="100%"
          height={view.equityH + view.ddH + 30}
          viewBox={`0 0 ${view.w} ${view.equityH + view.ddH + 30}`}
          preserveAspectRatio="none"
          role="img"
          aria-label="资产曲线 svg"
        >
          {/* baseline 1.0 */}
          <line
            x1={0}
            y1={view.y1}
            x2={view.w}
            y2={view.y1}
            stroke="var(--text-tertiary)"
            strokeWidth={0.5}
            strokeDasharray="2 2"
          />
          {/* equity path per phase */}
          {view.segments.map((s, i) => (
            <path key={i} d={s.d} stroke={PHASE_COLOR[s.phase]} strokeWidth={1.5} fill="none" />
          ))}

          {/* drawdown bars */}
          {showDrawdown && (
            <g transform={`translate(0, ${view.equityH + 20})`}>
              <text
                x={4}
                y={-4}
                fontSize={9}
                fill="var(--text-tertiary)"
              >
                Drawdown
              </text>
              {view.ddBars.map((b, i) => (
                <rect
                  key={i}
                  x={b.x}
                  y={b.y}
                  width={b.w}
                  height={b.h}
                  fill="var(--green-down)"
                  opacity={0.6}
                />
              ))}
            </g>
          )}
        </svg>
      </div>
    );
  }
);

OEquityCurveChart.displayName = 'OEquityCurveChart';
