/**
 * OEpistemicDistribution — 认识论可信度分布条(知识图整体质量概览)。
 *
 * 用途:
 *   - AII GraphHealth Page 顶部:整张知识图各 grade 占比
 *   - 任何场景需"按可信度分布看池子"
 *
 * 红线 #2:不平滑、真实比例。
 *   - 渲染严格按 count 比例,不做归一化抹平
 *   - count=0 的 grade 不渲染段(避免假占位)
 *   - 显示总数 + 每段 count + 百分比
 *
 * 视觉:横向堆叠 bar,grade 颜色跟 OEpistemicBadge 硬规范一致。
 */
import { forwardRef, useMemo } from 'react';
import { cn } from '../../lib/cn';
import {
  EPISTEMIC_GRADE_LABEL,
  EPISTEMIC_GRADE_RANK,
  type EpistemicGrade,
} from '../../types/epistemic';
import { useUiLang } from '../../lang/LangProvider';
import type { OBlockBaseProps } from '../../lib/types';

export interface OEpistemicDistributionProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 各 grade 的 count(缺省的 grade 视为 0,不渲染段)。 */
  counts: Partial<Record<EpistemicGrade, number>>;
  /** 标题。 */
  title?: string;
  /** 高度 px,默认 24。 */
  height?: number;
  /** 是否显示 legend(默认 true)。 */
  showLegend?: boolean;
  /** 点击某段时回调(项目自管 drill-down)。 */
  onSegmentClick?: (grade: EpistemicGrade, count: number) => void;
}

/** Grade 颜色硬规范(跟 OEpistemicBadge 视觉一致)。 */
const GRADE_COLOR: Record<EpistemicGrade, string> = {
  proven: 'var(--success)',
  high: 'var(--info)',
  moderate: 'color-mix(in srgb, var(--info) 60%, var(--muted))',
  low: 'color-mix(in srgb, var(--muted-foreground) 80%, var(--muted))',
  very_low: 'var(--muted-foreground)',
  unverified: 'var(--warning)',
  contradicted: 'var(--destructive)',
  pending_verification: 'color-mix(in srgb, var(--warning) 80%, var(--destructive))',
};

/** 渲染顺序(从可信到不可信)。 */
const ORDER: EpistemicGrade[] = [
  'proven', 'high', 'moderate', 'low', 'very_low',
  'pending_verification', 'unverified', 'contradicted',
];

export const OEpistemicDistribution = forwardRef<HTMLDivElement, OEpistemicDistributionProps>(
  function OEpistemicDistribution(
    {
      counts,
      title,
      height = 24,
      showLegend = true,
      onSegmentClick,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const { tr } = useUiLang();
    const labelOf = (g: EpistemicGrade) =>
      tr(EPISTEMIC_GRADE_LABEL[g].zh, EPISTEMIC_GRADE_LABEL[g].en);
    const { segments, total } = useMemo(() => {
      const segs: Array<{ grade: EpistemicGrade; count: number; pct: number }> = [];
      let sum = 0;
      for (const g of ORDER) {
        const c = counts[g] ?? 0;
        if (c > 0) sum += c;
      }
      for (const g of ORDER) {
        const c = counts[g] ?? 0;
        if (c <= 0) continue; // 不渲染 0 段(红线 #2 — 不假占位)
        segs.push({ grade: g, count: c, pct: sum > 0 ? (c / sum) * 100 : 0 });
      }
      return { segments: segs, total: sum };
    }, [counts]);

    if (total === 0) {
      return (
        <div
          ref={ref}
          className={cn(
            'flex items-center justify-center px-3 py-2 rounded border border-dashed text-xs text-muted-foreground @container',
            className
          )}
        >
          {tr('暂无数据', 'No data')}
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn('flex flex-col gap-1.5', className)}
        role="region"
        aria-label={title ?? tr('认识论可信度分布', 'Epistemic confidence distribution')}
      >
        {(title || total) && (
          <div className="flex items-center justify-between text-xs">
            {title && <span className="font-medium">{title}</span>}
            <span className="text-muted-foreground">
              {tr('共', 'Total')} {total} {tr('条', '')}
            </span>
          </div>
        )}

        {/* stacked bar */}
        <div
          className="flex w-full rounded overflow-hidden border border-border"
          style={{ height, backgroundColor: 'var(--muted)' }}
          aria-label={`${tr('分布', 'Distribution')}: ${segments.map((s) => `${labelOf(s.grade)} ${s.count}`).join(', ')}`}
          data-testid="epistemic-distribution-bar"
        >
          {segments.map((s) => {
            const clickable = !!onSegmentClick;
            const segLabel = `${labelOf(s.grade)} ${s.count} (${s.pct.toFixed(1)}%)`;
            const inner = (
              <span className="sr-only">{segLabel}</span>
            );
            const style = {
              width: `${s.pct}%`,
              backgroundColor: GRADE_COLOR[s.grade],
            };
            const title = segLabel;
            if (clickable) {
              return (
                <button
                  key={s.grade}
                  type="button"
                  onClick={() => onSegmentClick!(s.grade, s.count)}
                  className="h-full transition-opacity hover:opacity-80 focus:outline-none focus-visible:ring-2 focus-visible:ring-ring focus:ring-2 focus:ring-[color:var(--ring)]/60"
                  style={style}
                  title={title}
                  aria-label={segLabel}
                >
                  {inner}
                </button>
              );
            }
            return (
              <div key={s.grade} className="h-full" style={style} title={title} aria-label={segLabel}>
                {inner}
              </div>
            );
          })}
        </div>

        {/* legend */}
        {showLegend && (
          <ul className="flex flex-wrap gap-x-3 gap-y-1 list-none p-0 m-0 text-xs">
            {segments.map((s) => (
              <li
                key={s.grade}
                className="inline-flex items-center gap-1 text-muted-foreground"
              >
                <span
                  className="w-2.5 h-2.5 rounded-sm border border-border"
                  style={{ backgroundColor: GRADE_COLOR[s.grade] }}
                  aria-hidden="true"
                />
                <span className="text-foreground">{labelOf(s.grade)}</span>
                <span className="font-mono">
                  {s.count} ({s.pct.toFixed(1)}%)
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>
    );
  }
);

OEpistemicDistribution.displayName = 'OEpistemicDistribution';
// 保留 rank 内部使用避免 lint 警告
void EPISTEMIC_GRADE_RANK;
