/**
 * OEventTimeline — 通用事件时间线。
 *
 * 用途:
 *   - Aegis: event_trail 审计(omodul_name + status + cost + duration)
 *   - Stratum: 文档处理流水线时序
 *   - 任何 "按时间排列的事件序列"
 *
 * 数据契约:`events: TimelineEvent[]`(已按时间排序,实现自动按日分组)
 * 与 OAnomalyFeed 的区别:OAnomalyFeed 是 Tide 异常告警(severity / 静音 / 操作),
 * OEventTimeline 是中性的事件审计(无 severity,可点开看 details)。
 */
import { forwardRef, useMemo } from 'react';
import { cn } from '../../lib/cn';
import { useUiLang } from '../../lang/LangProvider';
import type { OBlockBaseProps } from '../../lib/types';

export type EventStatus = 'success' | 'failure' | 'pending' | 'cancelled' | 'partial';

export interface TimelineEvent {
  id: string;
  /** 显示名称(模块名 / 操作名)。 */
  title: string;
  /** 时间戳(ISO 字符串或 Date)。 */
  time: string | Date;
  status?: EventStatus;
  /** 子文本(描述 / actor / project_id)。 */
  subtitle?: string;
  /** 数字 metrics(成本 / 时长 / 行数,按需展示)。 */
  metrics?: { label: string; value: string | number }[];
  /** Page 自定义 detail 内容(展开时显示)。 */
  detail?: React.ReactNode;
  /** 是否默认展开 detail。 */
  defaultExpanded?: boolean;
}

export interface OEventTimelineProps extends Omit<OBlockBaseProps, 'variant'> {
  events: TimelineEvent[];
  /** 'default' = empty 态带虚线框;'ghost' = 无框(嵌入容器时用) */
  variant?: 'default' | 'ghost';
  /** 是否按日期分组(默认 true)。 */
  groupByDate?: boolean;
  /** 时间格式器(默认 toLocaleTimeString)。 */
  formatTime?: (time: Date) => string;
  /** 日期格式器(默认 toLocaleDateString)。 */
  formatDate?: (time: Date) => string;
  onEventClick?: (event: TimelineEvent) => void;
  emptyMessage?: string;
}

const STATUS_COLOR: Record<EventStatus, string> = {
  success: 'var(--success)',
  failure: 'var(--destructive)',
  pending: 'var(--info)',
  cancelled: 'var(--muted-foreground)',
  partial: 'var(--warning)',
};

const STATUS_ICON: Record<EventStatus, string> = {
  success: '✓',
  failure: '✗',
  pending: '○',
  cancelled: '—',
  partial: '◐',
};

function toDate(t: string | Date): Date {
  return t instanceof Date ? t : new Date(t);
}

export const OEventTimeline = forwardRef<HTMLDivElement, OEventTimelineProps>(
  function OEventTimeline(
    {
      events,
      variant = 'default',
      groupByDate = true,
      formatTime,
      formatDate,
      onEventClick,
      emptyMessage,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const { tr } = useUiLang();
    const emptyText = emptyMessage ?? tr('暂无事件', 'No events');
    const fmtTime = useMemo(
      () => formatTime ?? ((d: Date) => d.toLocaleTimeString('zh-CN', { hour12: false })),
      [formatTime]
    );
    const fmtDate = useMemo(
      () => formatDate ?? ((d: Date) => d.toLocaleDateString('zh-CN')),
      [formatDate]
    );

    const groups = useMemo(() => {
      if (!groupByDate) {
        return [{ date: '', events }];
      }
      const map = new Map<string, TimelineEvent[]>();
      for (const e of events) {
        const dateKey = fmtDate(toDate(e.time));
        const arr = map.get(dateKey) ?? [];
        arr.push(e);
        map.set(dateKey, arr);
      }
      return Array.from(map.entries()).map(([date, evs]) => ({ date, events: evs }));
    }, [events, groupByDate, fmtDate]);

    if (events.length === 0) {
      return (
        <div
          ref={ref}
          className={cn(
            'px-4 py-6 text-center text-sm text-muted-foreground',
            variant === 'ghost' ? '' : 'border border-dashed border-border rounded',
            className
          )}
        >
          {emptyText}
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn('flex flex-col gap-3 @container', className)}
        role="region"
        aria-label={tr('事件时间线', 'Event timeline')}
      >
        {groups.map((g) => (
          <div key={g.date}>
            {g.date && (
              <div className="text-xs text-muted-foreground mb-1 px-1 sticky top-0 bg-background z-10">
                {g.date}
              </div>
            )}
            <ul className="list-none p-0 m-0 flex flex-col">
              {g.events.map((e) => {
                const d = toDate(e.time);
                const status = e.status;
                const color = status ? STATUS_COLOR[status] : 'var(--muted-foreground)';
                const icon = status ? STATUS_ICON[status] : '·';
                const clickable = !!onEventClick;
                return (
                  <li
                    key={e.id}
                    role="listitem"
                    className={cn(
                      'flex items-start gap-2 px-2 py-1.5 border-l-2 transition-colors',
                      clickable && 'cursor-pointer hover:bg-muted'
                    )}
                    style={{ borderLeftColor: color }}
                    onClick={clickable ? () => onEventClick!(e) : undefined}
                  >
                    <span
                      className="inline-flex items-center justify-center text-xs font-bold shrink-0"
                      style={{ color, width: 16 }}
                      aria-hidden="true"
                    >
                      {icon}
                    </span>
                    <div className="flex-1 min-w-0">
                      <div className="flex flex-col @[320px]:flex-row @[320px]:items-baseline gap-1 @[320px]:gap-2 flex-wrap">
                        <span className="text-sm font-medium">{e.title}</span>
                        <span className="text-xs text-muted-foreground font-mono">
                          {fmtTime(d)}
                        </span>
                      </div>
                      {e.subtitle && (
                        <div className="text-xs text-muted-foreground truncate">
                          {e.subtitle}
                        </div>
                      )}
                      {e.metrics && e.metrics.length > 0 && (
                        <div className="flex items-center gap-3 text-[10px] text-muted-foreground mt-0.5 font-mono">
                          {e.metrics.map((m, i) => (
                            <span key={i}>
                              {m.label}={m.value}
                            </span>
                          ))}
                        </div>
                      )}
                      {e.detail && (e.defaultExpanded ?? false) && (
                        <div className="mt-1">{e.detail}</div>
                      )}
                    </div>
                  </li>
                );
              })}
            </ul>
          </div>
        ))}
      </div>
    );
  }
);

OEventTimeline.displayName = 'OEventTimeline';
