/**
 * ODateRangePicker - 日期范围选择器。
 *
 * 自实现简易月历(避免引入 date-fns / dayjs 等增加 bundle)。
 * 受控:value 是 [from, to] | null。
 *
 * 包含快捷预设 (Today / 7 days / 30 days / 90 days / This year)。
 *
 * @example
 * const [range, setRange] = useState<[Date, Date] | null>(null);
 * <ODateRangePicker value={range} onChange={setRange} />
 */
'use client';

import * as Popover from '@radix-ui/react-popover';
import { forwardRef, useMemo, useState } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export type DateRange = [Date, Date];

export interface ODateRangePickerProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  value?: DateRange | null;
  onChange: (range: DateRange | null) => void;
  placeholder?: string;
  /** 显示预设按钮。 */
  presets?: boolean;
  /** 最小可选日期。 */
  minDate?: Date;
  /** 最大可选日期。 */
  maxDate?: Date;
  /** 触发按钮的宽度。 */
  width?: string;
  disabled?: boolean;
}

function startOfDay(d: Date): Date {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  return x;
}

function endOfDay(d: Date): Date {
  const x = new Date(d);
  x.setHours(23, 59, 59, 999);
  return x;
}

function addDays(d: Date, n: number): Date {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
}

function sameDay(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

function inRange(d: Date, from: Date, to: Date): boolean {
  return d >= startOfDay(from) && d <= endOfDay(to);
}

function formatRange(range: DateRange | null | undefined): string {
  if (!range) return '';
  const fmt = (d: Date) => d.toLocaleDateString();
  return `${fmt(range[0])} → ${fmt(range[1])}`;
}

const WEEKDAYS = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

function MonthGrid({
  year,
  month,
  hover,
  setHover,
  pickStart,
  pickEnd,
  range,
  onPick,
  minDate,
  maxDate,
}: {
  year: number;
  month: number;
  hover: Date | null;
  setHover: (d: Date | null) => void;
  pickStart: Date | null;
  pickEnd: Date | null;
  range: DateRange | null;
  onPick: (d: Date) => void;
  minDate?: Date;
  maxDate?: Date;
}) {
  const first = new Date(year, month, 1);
  const firstWeekday = first.getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells: (Date | null)[] = Array.from({ length: firstWeekday }, () => null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d));

  return (
    <div>
      <div className="text-center text-sm font-medium mb-2">
        {first.toLocaleDateString(undefined, { year: 'numeric', month: 'long' })}
      </div>
      <div className="grid grid-cols-7 gap-0.5 text-xs">
        {WEEKDAYS.map((w, i) => (
          <div key={`${w}-${i}`} className="text-center text-muted-foreground py-1">
            {w}
          </div>
        ))}
        {cells.map((d, i) => {
          if (!d) return <div key={`e-${i}`} />;
          const disabled = (minDate && d < startOfDay(minDate)) || (maxDate && d > endOfDay(maxDate));
          const isStart = pickStart && sameDay(d, pickStart);
          const isEnd = pickEnd && sameDay(d, pickEnd);
          const inSelectedRange = range && inRange(d, range[0], range[1]);
          const inHoverRange =
            pickStart && !pickEnd && hover && inRange(d, pickStart < hover ? pickStart : hover, pickStart < hover ? hover : pickStart);
          const isInRange = inSelectedRange || inHoverRange;

          return (
            <button
              key={d.toISOString()}
              type="button"
              disabled={!!disabled}
              onClick={() => onPick(d)}
              onMouseEnter={() => setHover(d)}
              onMouseLeave={() => setHover(null)}
              className={cn(
                'h-8 w-full rounded text-xs transition-colors @container',
                'hover:bg-muted disabled:opacity-30 disabled:cursor-not-allowed',
                isInRange && !isStart && !isEnd && 'bg-primary/15 text-foreground',
                (isStart || isEnd) && 'bg-primary text-primary-foreground font-medium'
              )}
            >
              {d.getDate()}
            </button>
          );
        })}
      </div>
    </div>
  );
}

export const ODateRangePicker = forwardRef<HTMLButtonElement, ODateRangePickerProps>(
  function ODateRangePicker(
    {
      value,
      onChange,
      placeholder = 'Select date range',
      presets = true,
      minDate,
      maxDate,
      width = '18rem',
      disabled,
      className,
      theme: _t,
    },
    ref
  ) {
    const [open, setOpen] = useState(false);
    const [pickStart, setPickStart] = useState<Date | null>(value?.[0] ?? null);
    const [pickEnd, setPickEnd] = useState<Date | null>(value?.[1] ?? null);
    const [hover, setHover] = useState<Date | null>(null);
    const [viewDate, setViewDate] = useState(() => value?.[0] ?? new Date());

    function handlePick(d: Date) {
      if (!pickStart || (pickStart && pickEnd)) {
        setPickStart(d);
        setPickEnd(null);
      } else {
        let s = pickStart;
        let e = d;
        if (e < s) [s, e] = [e, s];
        setPickStart(s);
        setPickEnd(e);
        onChange([startOfDay(s), endOfDay(e)]);
        setOpen(false);
      }
    }

    function applyPreset(days: number) {
      const end = new Date();
      const start = addDays(end, -days + 1);
      onChange([startOfDay(start), endOfDay(end)]);
      setPickStart(start);
      setPickEnd(end);
      setOpen(false);
    }

    function clear() {
      onChange(null);
      setPickStart(null);
      setPickEnd(null);
      setOpen(false);
    }

    const nextMonth = useMemo(() => {
      const d = new Date(viewDate);
      d.setMonth(d.getMonth() + 1);
      return d;
    }, [viewDate]);

    return (
      <Popover.Root open={open} onOpenChange={setOpen}>
        <Popover.Trigger asChild>
          <button
            ref={ref}
            type="button"
            disabled={disabled}
            className={cn(
              'inline-flex items-center gap-2 rounded-md border border-input bg-card px-3 py-2 text-sm',
              'hover:bg-muted transition-colors disabled:opacity-50',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
              className
            )}
            style={{ width }}
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
              <rect x="3" y="4" width="18" height="18" rx="2" />
              <line x1="16" y1="2" x2="16" y2="6" />
              <line x1="8" y1="2" x2="8" y2="6" />
              <line x1="3" y1="10" x2="21" y2="10" />
            </svg>
            <span className={cn('truncate', !value && 'text-muted-foreground')}>
              {value ? formatRange(value) : placeholder}
            </span>
          </button>
        </Popover.Trigger>
        <Popover.Portal>
          <Popover.Content
            sideOffset={4}
            className="z-50 rounded-md border border-border bg-popover text-popover-foreground shadow-lg p-4"
          >
            <div className="flex gap-6">
              {presets ? (
                <div className="border-r border-border pr-4 space-y-1">
                  <button
                    onClick={() => applyPreset(1)}
                    className="block w-full text-left px-2 py-1 text-sm rounded hover:bg-muted"
                  >
                    Today
                  </button>
                  <button
                    onClick={() => applyPreset(7)}
                    className="block w-full text-left px-2 py-1 text-sm rounded hover:bg-muted"
                  >
                    Last 7 days
                  </button>
                  <button
                    onClick={() => applyPreset(30)}
                    className="block w-full text-left px-2 py-1 text-sm rounded hover:bg-muted"
                  >
                    Last 30 days
                  </button>
                  <button
                    onClick={() => applyPreset(90)}
                    className="block w-full text-left px-2 py-1 text-sm rounded hover:bg-muted"
                  >
                    Last 90 days
                  </button>
                  <button
                    onClick={() => applyPreset(365)}
                    className="block w-full text-left px-2 py-1 text-sm rounded hover:bg-muted"
                  >
                    Last year
                  </button>
                  <button
                    onClick={clear}
                    className="block w-full text-left px-2 py-1 text-sm rounded hover:bg-muted text-muted-foreground"
                  >
                    Clear
                  </button>
                </div>
              ) : null}
              <div>
                <div className="flex items-center justify-between mb-2">
                  <button
                    onClick={() => {
                      const d = new Date(viewDate);
                      d.setMonth(d.getMonth() - 1);
                      setViewDate(d);
                    }}
                    aria-label="Previous month"
                    className="p-1 rounded hover:bg-muted"
                  >
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <polyline points="15 18 9 12 15 6" />
                    </svg>
                  </button>
                  <button
                    onClick={() => {
                      const d = new Date(viewDate);
                      d.setMonth(d.getMonth() + 1);
                      setViewDate(d);
                    }}
                    aria-label="Next month"
                    className="p-1 rounded hover:bg-muted"
                  >
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <polyline points="9 18 15 12 9 6" />
                    </svg>
                  </button>
                </div>
                <div className="flex gap-4">
                  <div style={{ width: 220 }}>
                    <MonthGrid
                      year={viewDate.getFullYear()}
                      month={viewDate.getMonth()}
                      hover={hover}
                      setHover={setHover}
                      pickStart={pickStart}
                      pickEnd={pickEnd}
                      range={value ?? null}
                      onPick={handlePick}
                      minDate={minDate}
                      maxDate={maxDate}
                    />
                  </div>
                  <div style={{ width: 220 }}>
                    <MonthGrid
                      year={nextMonth.getFullYear()}
                      month={nextMonth.getMonth()}
                      hover={hover}
                      setHover={setHover}
                      pickStart={pickStart}
                      pickEnd={pickEnd}
                      range={value ?? null}
                      onPick={handlePick}
                      minDate={minDate}
                      maxDate={maxDate}
                    />
                  </div>
                </div>
              </div>
            </div>
          </Popover.Content>
        </Popover.Portal>
      </Popover.Root>
    );
  }
);

ODateRangePicker.displayName = 'ODateRangePicker';
