/**
 * OHealthBanner — 整体健康状态顶部 banner
 *
 * 来源:Helivex 经理人 R1 §4.2(Chain Health Banner)+ Aegis incident health 共需
 *
 * 设计参考(横向对标):
 *   - GitHub Status Page — 3 态 banner + 折叠详情(经典模式)
 *   - Datadog incident banner — 顶部 banner + collapse 模式
 *   - Nielsen Norman Group "Status Indicators" — color / motion / position 3 关键
 *   - WCAG 2.1 SC 1.4.1 — 颜色不能是唯一指示器(必须配 icon + text)
 *   - WAI-ARIA Live Regions Best Practice
 *
 * 业界对标的关键改进:
 *   - **WCAG 1.4.1 合规**:icon + text + color 三重冗余
 *   - **WAI-ARIA Live Regions**:role="status" + aria-live="polite" + aria-atomic="true"
 *     (业界多数 banner 库只做 aria-live 漏掉 aria-atomic,导致状态变化时屏幕阅读器只读 diff)
 *
 * 跨项目场景:
 *   - Helivex:chain health(`GET /audit/chain/verify` response)
 *   - Aegis:incident health 整体状态
 *   - Stratum:graph integrity(KB 数据完整性)
 *
 * a11y:
 *   - role="status"(隐含 polite + atomic)
 *   - 显式补 aria-live="polite" + aria-atomic="true" 避免实现差异
 *   - icon role="img" + aria-label
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, useState, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

// ============================================================
// 视觉变体(WCAG 1.4.1 — 必须 color + icon + text 三重冗余)
// ============================================================

const bannerVariants = cva(
  'w-full border-y px-4 py-3 transition-colors',
  {
    variants: {
      status: {
        healthy:
          'bg-success/10 border-success/40 text-foreground',
        degraded:
          'bg-warning/10 border-warning/40 text-foreground',
        critical:
          'bg-destructive/10 border-destructive/50 text-foreground',
      },
    },
    defaultVariants: {
      status: 'healthy',
    },
  }
);

type BannerVariantProps = VariantProps<typeof bannerVariants>;

const iconClsByStatus = {
  healthy: 'text-success',
  degraded: 'text-warning',
  critical: 'text-destructive',
} as const;

// ============================================================
// 状态对应的 icon + label(冗余指示器)
// ============================================================

function StatusIcon({
  status,
  pulse,
}: {
  status: 'healthy' | 'degraded' | 'critical';
  pulse: boolean;
}) {
  const cls = iconClsByStatus[status];
  const pulseCls = pulse ? 'animate-pulse' : '';
  const label = STATUS_LABEL[status];

  if (status === 'healthy') {
    return (
      <svg
        className={cn('w-5 h-5 flex-shrink-0', cls, pulseCls)}
        viewBox="0 0 20 20"
        fill="currentColor"
        role="img"
        aria-label={label}
      >
        <path
          fillRule="evenodd"
          d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z"
        />
      </svg>
    );
  }
  if (status === 'degraded') {
    return (
      <svg
        className={cn('w-5 h-5 flex-shrink-0', cls, pulseCls)}
        viewBox="0 0 20 20"
        fill="currentColor"
        role="img"
        aria-label={label}
      >
        <path
          fillRule="evenodd"
          d="M8.485 2.495c.673-1.167 2.357-1.167 3.03 0l6.28 10.875c.673 1.167-.17 2.625-1.516 2.625H3.72c-1.347 0-2.189-1.458-1.515-2.625L8.485 2.495zM10 5a1 1 0 011 1v3a1 1 0 11-2 0V6a1 1 0 011-1zm0 9a1 1 0 100-2 1 1 0 000 2z"
        />
      </svg>
    );
  }
  // critical
  return (
    <svg
      className={cn('w-5 h-5 flex-shrink-0', cls, pulseCls)}
      viewBox="0 0 20 20"
      fill="currentColor"
      role="img"
      aria-label={label}
    >
      <path
        fillRule="evenodd"
        d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.28 7.22a.75.75 0 00-1.06 1.06L8.94 10l-1.72 1.72a.75.75 0 101.06 1.06L10 11.06l1.72 1.72a.75.75 0 101.06-1.06L11.06 10l1.72-1.72a.75.75 0 00-1.06-1.06L10 8.94 8.28 7.22z"
      />
    </svg>
  );
}

const STATUS_LABEL: Record<'healthy' | 'degraded' | 'critical', string> = {
  healthy: '健康',
  degraded: '降级',
  critical: '严重',
};

// ============================================================
// Props
// ============================================================

export interface OHealthBannerProps
  extends Omit<OBlockBaseProps, 'variant' | 'size'>,
    BannerVariantProps {
  /**
   * 当前健康状态。
   * - healthy: 全部正常
   * - degraded: 部分降级,功能仍可用
   * - critical: 严重问题,需要立即关注
   */
  status: 'healthy' | 'degraded' | 'critical';

  /**
   * 主要消息(简短,中文)。
   * 例:"链验证全部通过" / "3 个事件签名失败" / "db-primary 连接失败"
   */
  message: string;

  /**
   * 详情区(可选,折叠展开)。
   */
  details?: {
    /** 摘要文本(展开前/后都显示在 message 旁)。 */
    summary?: string;
    /** 完整详情内容(展开后显示)。 */
    content: ReactNode;
  };

  /**
   * pulse 动画。默认 critical 时 true,其他 false。
   * reduced-motion 偏好时自动关。
   */
  pulse?: boolean;

  /**
   * 详情默认是否展开。默认 false(折叠)。
   * critical 时建议传 true。
   */
  defaultExpanded?: boolean;

  /**
   * 顶部操作(可选)。
   * 例:"查看详情" 跳转,或 "尝试自愈" 触发动作。
   */
  action?: {
    label: string;
    onClick?: () => void;
    href?: string;
  };
}

// ============================================================
// 主组件
// ============================================================

export const OHealthBanner = forwardRef<HTMLDivElement, OHealthBannerProps>(
  function OHealthBanner(
    {
      status,
      message,
      details,
      pulse,
      defaultExpanded = false,
      action,
      className,
      theme: _t,
    },
    ref
  ) {
    const reduced = useReducedMotion();
    const [expanded, setExpanded] = useState(defaultExpanded);

    // pulse 默认值:critical 时 true,其他 false
    const shouldPulse = (pulse ?? status === 'critical') && !reduced;

    const hasDetails = !!details;
    const canExpand = hasDetails;

    return (
      <div
        ref={ref}
        role="status"
        aria-live="polite"
        aria-atomic="true"
        className={cn(bannerVariants({ status }), className)}
      >
        <div className="flex items-start gap-3">
          {/* WCAG 1.4.1 冗余:icon 跟随状态色 + aria-label */}
          <StatusIcon status={status} pulse={shouldPulse} />

          <div className="flex-1 min-w-0">
            <div className="flex flex-wrap items-baseline gap-x-2 gap-y-1">
              {/* WCAG 1.4.1 冗余:status text(中文 label)+ 主消息 */}
              <span
                className={cn(
                  'text-xs font-semibold',
                  iconClsByStatus[status]
                )}
              >
                {STATUS_LABEL[status]}
              </span>
              <span className="text-sm font-medium text-foreground">
                {message}
              </span>
              {details?.summary && (
                <span className="text-xs text-muted-foreground">
                  {details.summary}
                </span>
              )}
            </div>

            {/* 展开后的详情 */}
            {hasDetails && expanded && (
              <div className="mt-3 text-sm text-foreground/90">
                {details.content}
              </div>
            )}
          </div>

          {/* 右侧:action + expand toggle */}
          <div className="flex items-center gap-2 flex-shrink-0">
            {action &&
              (action.href ? (
                <a
                  href={action.href}
                  className={cn(
                    'inline-flex items-center px-3 py-1 text-xs rounded-md',
                    'border border-border bg-background hover:bg-muted',
                    'transition-colors',
                    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring'
                  )}
                >
                  {action.label}
                </a>
              ) : (
                <button
                  type="button"
                  onClick={action.onClick}
                  className={cn(
                    'inline-flex items-center px-3 py-1 text-xs rounded-md',
                    'border border-border bg-background hover:bg-muted',
                    'transition-colors',
                    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring'
                  )}
                >
                  {action.label}
                </button>
              ))}

            {canExpand && (
              <button
                type="button"
                onClick={() => setExpanded((e) => !e)}
                className={cn(
                  'inline-flex items-center justify-center w-7 h-7 rounded',
                  'text-muted-foreground hover:text-foreground hover:bg-muted',
                  'transition-colors',
                  'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring'
                )}
                aria-expanded={expanded}
                aria-label={expanded ? '收起详情' : '展开详情'}
              >
                <svg
                  className={cn(
                    'w-4 h-4 transition-transform',
                    expanded && 'rotate-180'
                  )}
                  viewBox="0 0 16 16"
                  fill="currentColor"
                  aria-hidden="true"
                >
                  <path d="M4 6l4 4 4-4z" />
                </svg>
              </button>
            )}
          </div>
        </div>
      </div>
    );
  }
);

OHealthBanner.displayName = 'OHealthBanner';
