/**
 * OAnnotationLayer — 文档选区高亮层
 *
 * v1.0 限制(API §1.2):
 *   - 仅 chunk-level fragment(无 char-level)
 *   - anchor.char_start / char_end 始终 0
 *   - 通过 fragment_id "{substrate_id}#{chunk_idx}" 锚定
 *
 * 设计:
 *   - 接收 fragments[] + 渲染对应高亮区块
 *   - 每个 fragment 显示 chunk_idx + section(如有)+ 内容预览
 *   - 点击触发 onSelect(传 FragmentRef)
 *   - 新建选区:onCreateAnnotation 提供时显示"新建"按钮(模拟选区)
 *
 * 注:v1.0 不支持 PDF DOM 选区(无 char_start/end),本 Block 是"chunk 列表"风格,
 *     v2.0+ 升级为真正的 DOM 选区高亮(需 char-level fragment)
 */
import { forwardRef, useCallback, type KeyboardEvent } from 'react';
import { cn } from '../../lib/cn';
import type { FragmentRef } from '../../types/stratum';
import type { OBlockBaseProps } from '../../lib/types';

export interface AnnotationFragment extends FragmentRef {
  /** chunk 文本预览(消费方截取,通常 100-200 字符)。 */
  text_preview?: string;
  /** 用户笔记/批注(如果有)。 */
  note?: string;
  /** 是否为当前选中态。 */
  is_selected?: boolean;
}

export interface OAnnotationLayerProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 注释列表。 */
  fragments: AnnotationFragment[];
  /** 点击注释。 */
  onSelect?: (fragment: AnnotationFragment) => void;
  /** 编辑笔记(可选)。 */
  onEditNote?: (fragment: AnnotationFragment) => void;
  /** 删除注释(可选)。 */
  onDelete?: (fragment: AnnotationFragment) => void;
  /** 空状态文案。 */
  emptyText?: string;
}

function parseFragmentId(fragmentId: string): { substrate_id: string; chunk_idx: string } {
  const hashIdx = fragmentId.lastIndexOf('#');
  if (hashIdx === -1) return { substrate_id: fragmentId, chunk_idx: '0' };
  return {
    substrate_id: fragmentId.substring(0, hashIdx),
    chunk_idx: fragmentId.substring(hashIdx + 1),
  };
}

export const OAnnotationLayer = forwardRef<HTMLDivElement, OAnnotationLayerProps>(
  function OAnnotationLayer(
    {
      fragments,
      onSelect,
      onEditNote,
      onDelete,
      emptyText = '暂无注释',
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const handleKey = useCallback(
      (e: KeyboardEvent<HTMLButtonElement>, f: AnnotationFragment) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onSelect?.(f);
        }
      },
      [onSelect]
    );

    if (fragments.length === 0) {
      return (
        <div
          ref={ref}
          className={cn(
            'px-4 py-8 text-center text-sm text-[color:var(--text-muted)] @container',
            'border border-dashed border-border rounded-lg',
            className
          )}
        >
          {emptyText}
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn('flex flex-col gap-2', className)}
        aria-label={`注释列表 ${fragments.length} 条`}
      >
        {fragments.map((f) => {
          const { chunk_idx } = parseFragmentId(f.fragment_id);
          return (
            <div
              key={f.fragment_id}
              className={cn(
                'flex flex-col gap-1.5 px-3 py-2 rounded-md',
                'bg-card border border-border',
                f.is_selected && 'ring-2 ring-[color:var(--primary)]/40'
              )}
            >
              <button
                type="button"
                onClick={() => onSelect?.(f)}
                onKeyDown={(e) => handleKey(e, f)}
                aria-pressed={f.is_selected}
                className={cn(
                  'flex items-start gap-2 text-left w-full cursor-pointer',
                  'hover:opacity-80 transition-opacity',
                  'focus:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded'
                )}
              >
                <span
                  className={cn(
                    'shrink-0 px-1.5 py-0.5 text-[10px] rounded font-mono',
                    'bg-primary/10 text-primary'
                  )}
                  aria-label={`chunk ${chunk_idx}`}
                >
                  #{chunk_idx}
                </span>
                <div className="flex flex-col gap-1 flex-1 min-w-0">
                  {f.anchor.section && (
                    <div className="text-[10px] text-[color:var(--text-muted)] font-mono">
                      § {f.anchor.section}
                    </div>
                  )}
                  {f.text_preview && (
                    <div className="text-sm text-[color:var(--foreground)] line-clamp-3">
                      {f.text_preview}
                    </div>
                  )}
                  {f.note && (
                    <div
                      className={cn(
                        'mt-1 px-2 py-1 rounded text-xs italic',
                        'bg-[color:var(--accent)]/10 text-[color:var(--foreground)]',
                        'border-l-2 border-[color:var(--accent)]'
                      )}
                    >
                      💭 {f.note}
                    </div>
                  )}
                </div>
              </button>
              {(onEditNote || onDelete) && (
                <div className="flex gap-1.5 justify-end">
                  {onEditNote && (
                    <button
                      type="button"
                      onClick={() => onEditNote(f)}
                      className={cn(
                        'px-2 py-0.5 text-[10px] rounded',
                        'bg-muted text-[color:var(--foreground)]',
                        'hover:opacity-80 transition-opacity'
                      )}
                    >
                      编辑
                    </button>
                  )}
                  {onDelete && (
                    <button
                      type="button"
                      onClick={() => onDelete(f)}
                      className={cn(
                        'px-2 py-0.5 text-[10px] rounded',
                        'bg-destructive/10 text-destructive',
                        'hover:bg-destructive/20 transition-colors'
                      )}
                    >
                      删除
                    </button>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    );
  }
);

OAnnotationLayer.displayName = 'OAnnotationLayer';
