/**
 * OWorkspaceGrid — 可拖拽/可 resize 的工作台网格(12×12 精细网格)。
 *
 * 核心设计:
 *   - 12列×12行 CSS Grid,最小单位约屏幕 1/12(比原 3×3 细 16 倍)
 *   - 拖拽移动:HTML5 drag-and-drop,有 ghost 占位高亮反馈
 *   - Resize:拖 cell 右下角 handle 改 colSpan/rowSpan
 *   - 持久化:自动通过 OPersistenceProvider 存读,key=workspace-layout:{userId}:{layoutName}
 *   - 降级安全:无 Provider 时静默 no-op
 */
'use client';

import {
  forwardRef, useState, useRef, useCallback,
  useEffect, useMemo, type ReactNode,
} from 'react';
import { cn } from '../../lib/cn';
import { usePersistence } from '../../providers/PersistenceProvider';
import type { OBlockBaseProps } from '../../lib/types';

// ── 类型 ────────────────────────────────────────────────────────

export interface GridPosition {
  row: number;
  col: number;
  rowSpan?: number;
  colSpan?: number;
}

interface CellAction {
  icon: string;
  label?: string;
  onClick: () => void;
}

export interface WorkspaceCell {
  id: string;
  title: string;
  position?: GridPosition;
  component: ReactNode;
  actions?: CellAction[];
  expandPath?: string;
  minColSpan?: number;
  minRowSpan?: number;
}

export type WorkspaceLayoutType = 'default' | 'trading' | 'monitor' | 'custom';

export interface OWorkspaceGridProps extends Omit<OBlockBaseProps, 'variant'> {
  layout: WorkspaceLayoutType;
  cells: WorkspaceCell[];
  editable?: boolean;
  userId?: string;
  layoutName?: string;
  onCellMove?: (fromId: string, toPosition: GridPosition) => void;
  onCellExpand?: (cellId: string) => void;
  onLayoutSave?: (name: string, cells: WorkspaceCell[]) => void;
}

// ── 常量 ────────────────────────────────────────────────────────

const COLS = 12;
const ROWS = 12;

const DEFAULT_POSITIONS: Record<WorkspaceLayoutType, GridPosition[]> = {
  default: [
    { row: 0, col: 0, rowSpan: 4, colSpan: 4 },
    { row: 0, col: 4, rowSpan: 4, colSpan: 4 },
    { row: 0, col: 8, rowSpan: 4, colSpan: 4 },
    { row: 4, col: 0, rowSpan: 4, colSpan: 4 },
    { row: 4, col: 4, rowSpan: 4, colSpan: 4 },
    { row: 4, col: 8, rowSpan: 4, colSpan: 4 },
    { row: 8, col: 0, rowSpan: 4, colSpan: 4 },
    { row: 8, col: 4, rowSpan: 4, colSpan: 4 },
    { row: 8, col: 8, rowSpan: 4, colSpan: 4 },
  ],
  trading: [
    { row: 0, col: 0, rowSpan: 9, colSpan: 3 },
    { row: 0, col: 3, rowSpan: 7, colSpan: 5 },
    { row: 0, col: 8, rowSpan: 9, colSpan: 4 },
    { row: 7, col: 3, rowSpan: 2, colSpan: 5 },
  ],
  monitor: [
    { row: 0, col: 0, rowSpan: 12, colSpan: 4 },
    { row: 0, col: 4, rowSpan: 12, colSpan: 4 },
    { row: 0, col: 8, rowSpan: 12, colSpan: 4 },
  ],
  custom: [],
};

function persistKey(userId?: string, layoutName?: string): string | null {
  if (!userId) return null;
  return `workspace-layout:${userId}:${layoutName ?? 'default'}`;
}

function assignDefaults(cells: WorkspaceCell[], layout: WorkspaceLayoutType): WorkspaceCell[] {
  const defs = DEFAULT_POSITIONS[layout];
  return cells.map((c, i) => ({
    ...c,
    position: c.position ?? defs[i] ?? {
      row: Math.floor(i / 4) * 3,
      col: (i % 4) * 3,
      rowSpan: 3, colSpan: 3,
    },
  }));
}

// ── 主组件 ───────────────────────────────────────────────────────

export const OWorkspaceGrid = forwardRef<HTMLDivElement, OWorkspaceGridProps>(
  function OWorkspaceGrid({
    layout, cells, editable, userId, layoutName,
    onCellMove, onCellExpand, onLayoutSave, className,
  }, ref) {
    const persistence = usePersistence();

    const [liveCells, setLiveCells] = useState<WorkspaceCell[]>(() => {
      const key = persistKey(userId, layoutName);
      if (key && persistence) {
        const saved = persistence.get<WorkspaceCell[]>(key);
        if (saved?.length) return saved;
      }
      return assignDefaults(cells, layout);
    });

    // 外部 cells 变化:仅同步新增/删除,不覆盖用户位置
    const cellIds = cells.map(c => c.id).join(',');
    useEffect(() => {
      setLiveCells(prev => {
        const ids = new Set(cells.map(c => c.id));
        const filtered = prev.filter(c => ids.has(c.id));
        const existingIds = new Set(filtered.map(c => c.id));
        const newOnes = cells.filter(c => !existingIds.has(c.id));
        return [...filtered, ...assignDefaults(newOnes, layout)];
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [cellIds]);

    // 拖拽
    const [dragId, setDragId]         = useState<string | null>(null);
    const [dropTarget, setDropTarget] = useState<{ row: number; col: number } | null>(null);

    // resize
    const [resizingId, setResizingId] = useState<string | null>(null);
    const resizeStartRef = useRef<{ x: number; y: number; colSpan: number; rowSpan: number } | null>(null);
    const gridRef        = useRef<HTMLDivElement | null>(null);

    const saveCells = useCallback((next: WorkspaceCell[]) => {
      const key = persistKey(userId, layoutName);
      if (key && persistence) {
        try { persistence.set(key, next); } catch { /* quota */ }
      }
      onLayoutSave?.(layoutName ?? 'default', next);
    }, [userId, layoutName, persistence, onLayoutSave]);

    const cellPx = useCallback(() => {
      if (!gridRef.current) return { w: 80, h: 60 };
      const { width, height } = gridRef.current.getBoundingClientRect();
      return { w: width / COLS, h: height / ROWS };
    }, []);

    // drag handlers
    const onDragStart = useCallback((id: string, e: React.DragEvent) => {
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', id);
      setDragId(id);
    }, []);
    const onDragOver = useCallback((row: number, col: number, e: React.DragEvent) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      setDropTarget({ row, col });
    }, []);
    const onDrop = useCallback((row: number, col: number) => {
      if (!dragId) return;
      setLiveCells(prev => {
        const cell = prev.find(c => c.id === dragId);
        if (!cell) return prev;
        const pos: GridPosition = {
          row, col,
          rowSpan: cell.position?.rowSpan ?? 1,
          colSpan: cell.position?.colSpan ?? 1,
        };
        const next = prev.map(c => c.id === dragId ? { ...c, position: pos } : c);
        saveCells(next);
        onCellMove?.(dragId, pos);
        return next;
      });
      setDragId(null); setDropTarget(null);
    }, [dragId, onCellMove, saveCells]);

    // resize handlers(pointer events for cross-device)
    const onResizeDown = useCallback((id: string, e: React.PointerEvent) => {
      e.stopPropagation();
      (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
      const cell = liveCells.find(c => c.id === id);
      if (!cell) return;
      setResizingId(id);
      resizeStartRef.current = {
        x: e.clientX, y: e.clientY,
        colSpan: cell.position?.colSpan ?? 1,
        rowSpan: cell.position?.rowSpan ?? 1,
      };
    }, [liveCells]);

    const onResizeMove = useCallback((id: string, e: React.PointerEvent) => {
      if (resizingId !== id || !resizeStartRef.current) return;
      const { w, h } = cellPx();
      const dCol = Math.round((e.clientX - resizeStartRef.current.x) / w);
      const dRow = Math.round((e.clientY - resizeStartRef.current.y) / h);
      setLiveCells(prev => prev.map(c => {
        if (c.id !== id) return c;
        const col = c.position?.col ?? 0;
        const row = c.position?.row ?? 0;
        const newCol = Math.max(c.minColSpan ?? 1, Math.min(COLS - col, resizeStartRef.current!.colSpan + dCol));
        const newRow = Math.max(c.minRowSpan ?? 1, Math.min(ROWS - row, resizeStartRef.current!.rowSpan + dRow));
        return { ...c, position: { ...(c.position ?? { row: 0, col: 0 }), colSpan: newCol, rowSpan: newRow } };
      }));
    }, [resizingId, cellPx]);

    const onResizeUp = useCallback((id: string) => {
      if (resizingId !== id) return;
      setResizingId(null);
      resizeStartRef.current = null;
      saveCells(liveCells);
    }, [resizingId, liveCells, saveCells]);

    // ghost grid(drop zones)
    const ghostGrid = useMemo(() => {
      if (!editable || !dragId) return null;
      const out = [];
      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const active = dropTarget?.row === r && dropTarget?.col === c;
          out.push(
            <div
              key={`g${r}-${c}`}
              className={cn('workspace-ghost', active && 'workspace-ghost--active')}
              style={{ gridRow: r + 1, gridColumn: c + 1 }}
              onDragOver={e => onDragOver(r, c, e)}
              onDrop={() => onDrop(r, c)}
            />
          );
        }
      }
      return out;
    }, [editable, dragId, dropTarget, onDragOver, onDrop]);

    if (!liveCells.length) {
      return <div ref={ref} className={cn('workspace-empty', className)}>无 cell</div>;
    }

    return (
      <div
        ref={node => {
          gridRef.current = node;
          if (typeof ref === 'function') ref(node);
          else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }}
        key={layout}
        className={cn('workspace-grid', editable && 'workspace-grid--editable', className)}
        style={{
          display: 'grid',
          gridTemplateColumns: `repeat(${COLS}, 1fr)`,
          gridTemplateRows: `repeat(${ROWS}, 1fr)`,
        }}
        role="region"
        aria-label={`workspace ${layout}`}
      >
        {ghostGrid}

        {liveCells.map(cell => {
          const { row = 0, col = 0, rowSpan = 1, colSpan = 1 } = cell.position ?? {};
          return (
            <section
              key={cell.id}
              data-cell-id={cell.id}
              className={cn(
                'workspace-cell group',
                dragId === cell.id && 'workspace-cell--dragging',
                resizingId === cell.id && 'workspace-cell--resizing',
              )}
              style={{
                gridRow: `${row + 1} / span ${rowSpan}`,
                gridColumn: `${col + 1} / span ${colSpan}`,
              }}
              aria-label={cell.title}
            >
              <header
                className={cn('workspace-cell__header', editable && 'cursor-move')}
                draggable={editable}
                onDragStart={editable ? e => onDragStart(cell.id, e) : undefined}
                onDragEnd={editable ? () => { setDragId(null); setDropTarget(null); } : undefined}
              >
                <button type="button" className="workspace-cell__title"
                  onClick={() => onCellExpand?.(cell.id)}>
                  {cell.title}
                </button>
                {cell.actions?.length ? (
                  <div className="workspace-cell__actions">
                    {cell.actions.map((a, i) => (
                      <button key={i} type="button" onClick={a.onClick}
                        title={a.label} aria-label={a.label ?? a.icon}
                        className="workspace-cell__action-btn">
                        {a.icon}
                      </button>
                    ))}
                  </div>
                ) : null}
              </header>

              <div className="workspace-cell__body">{cell.component}</div>

              {editable && (
                <div
                  className="workspace-resize-handle"
                  aria-label="调整大小"
                  onPointerDown={e => onResizeDown(cell.id, e)}
                  onPointerMove={e => onResizeMove(cell.id, e)}
                  onPointerUp={() => onResizeUp(cell.id)}
                >
                  <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden>
                    <path d="M10 0 L10 10 L0 10 Z" fill="currentColor" opacity="0.4"/>
                  </svg>
                </div>
              )}
            </section>
          );
        })}
      </div>
    );
  }
);

OWorkspaceGrid.displayName = 'OWorkspaceGrid';
