/**
 * ORegimeBadge — 市场 regime 状态徽章(量化通用)。
 *
 * trend(趋势)/ chop(震荡)/ bear(熊) 三态,各有稳定状态色。
 * 跨项目:量化策略系统通用。
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export type MarketRegime = 'trend' | 'chop' | 'bear' | 'bull' | 'unknown';

export interface ORegimeBadgeProps extends Omit<OBlockBaseProps, 'variant'> {
  regime: MarketRegime;
  compact?: boolean;
}

const META: Record<MarketRegime, { color: string; icon: string; label: string }> = {
  trend:   { color: 'oklch(0.62 0.16 200)', icon: '↗', label: 'TREND' },
  bull:    { color: 'oklch(0.62 0.18 145)', icon: '↑', label: 'BULL' },
  chop:    { color: 'oklch(0.70 0.14 80)',  icon: '⇄', label: 'CHOP' },
  bear:    { color: 'oklch(0.60 0.22 25)',  icon: '↓', label: 'BEAR' },
  unknown: { color: 'var(--muted-foreground)', icon: '?', label: 'UNKNOWN' },
};

export const ORegimeBadge = forwardRef<HTMLSpanElement, ORegimeBadgeProps>(
  function ORegimeBadge({ regime, compact, className, ...rest }, ref) {
    const m = META[regime];
    return (
      <span
        ref={ref}
        className={cn('inline-flex items-center gap-1 rounded px-2 py-0.5 text-xs font-semibold tracking-[0.04em]', className)}
        style={{
          color: m.color,
          background: `color-mix(in oklch, ${m.color} 14%, transparent)`,
        }}
        {...rest}
      >
        <span aria-hidden>{m.icon}</span>
        {!compact && <span>{m.label}</span>}
      </span>
    );
  }
);

ORegimeBadge.displayName = 'ORegimeBadge';
