/**
 * OSocialOverlay - 社交热度叠加层。
 *
 * 加密场景:把社区/股吧/Twitter 的"提及量"和"情绪指数"叠加到图表时间轴上,
 * 帮散户判断"为什么这一段价格这么动"。
 *
 * 数据契约:
 *   - sentiments: [{ time, score, volume, top? }]
 *     time:   Unix 秒
 *     score:  情绪指数 -1.0 (极度看空) 到 +1.0 (极度看多)
 *     volume: 该时段提及量
 *     top:    可选,该时段最热帖标题 (鼠标 hover 显示)
 *
 * 视觉:
 *   - 透明背景 (作为图表上层 overlay)
 *   - 上方:情绪热力色条 (绿/中性/红)
 *   - 下方:提及量柱状 (灰色,克制)
 *   - 接 CrosshairProvider:鼠标 hover 时同步主图时间轴
 *
 * 使用方式:
 *   <div className="relative">
 *     <OCandlestickChart ... />
 *     <OSocialOverlay
 *       className="absolute inset-x-0 bottom-0 h-16"
 *       data={{ symbol, sentiments }}
 *       syncToCrosshair
 *     />
 *   </div>
 *
 * 工程细节:
 *   - Canvas 自绘
 *   - 接 FastDataProvider 可选 channel
 *   - 接 CrosshairProvider 双向 (它既能驱动也能跟随)
 *   - 低性能模式只显示情绪线,不显示柱
 */

'use client';

import { forwardRef, useEffect, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import { useCrosshair } from '../../providers/CrosshairProvider';
import { useFastData } from '../../providers/FastDataProvider';
import type { OBlockDataProps } from '../../lib/types';

// ============================================================
// 数据契约
// ============================================================

export interface OSentimentPoint {
  /** Unix 秒。 */
  time: number;
  /** 情绪指数 -1.0 (极看空) 到 +1.0 (极看多)。 */
  score: number;
  /** 该时段社区提及量。 */
  volume: number;
  /** 可选 - 该时段最热门帖子标题 (用于 hover 显示)。 */
  top?: string;
}

export interface OSocialOverlayData {
  symbol: string;
  sentiments: OSentimentPoint[];
  /** 数据源标识 (例如 'snowball+twitter')。 */
  source?: string;
}

// ============================================================
// Props
// ============================================================

export interface OSocialOverlayProps extends OBlockDataProps<OSocialOverlayData> {
  /** 接 FastData channel,优先级高于 data prop。 */
  channel?: string;
  /** 跨图联动。 */
  syncToCrosshair?: boolean;
  /** 高度 px。 */
  height?: number;
  /** 是否显示提及量柱。 */
  showVolume?: boolean;
  /** 低性能模式 (隐藏柱 + 简化绘制)。 */
  lowPerformanceMode?: boolean;
  /** 数据延时 (分钟)。 */
  dataDelay?: number;
}

// ============================================================
// 自绘
// ============================================================

interface OverlayColors {
  bullish: string;       // 看多色 (绿)
  bearish: string;       // 看空色 (红)
  neutral: string;       // 中性色
  volume: string;        // 提及量柱色
  text: string;
  textMuted: string;
  highlight: string;     // crosshair 高亮线
}

function readColors(): OverlayColors {
  const s = getComputedStyle(document.documentElement);
  const get = (n: string, fb: string) => s.getPropertyValue(n).trim() || fb;
  return {
    bullish: get('--quote-up', 'oklch(0.65 0.20 145)'),
    bearish: get('--quote-down', 'oklch(0.62 0.22 25)'),
    neutral: get('--text-muted', 'oklch(0.55 0 0)'),
    volume: get('--maker', 'oklch(0.55 0.08 220)'),
    text: get('--text-primary', 'oklch(0.95 0 0)'),
    textMuted: get('--text-muted', 'oklch(0.55 0 0)'),
    highlight: get('--text-primary', 'oklch(0.95 0 0)'),
  };
}

function scoreToColor(score: number, colors: OverlayColors): string {
  // score [-1, 1] → 颜色
  if (score > 0.1) {
    // 偏看多:从中性 → 绿
    const t = Math.min(score, 1);
    return `color-mix(in oklch, ${colors.neutral} ${(1 - t) * 100}%, ${colors.bullish} ${t * 100}%)`;
  }
  if (score < -0.1) {
    const t = Math.min(-score, 1);
    return `color-mix(in oklch, ${colors.neutral} ${(1 - t) * 100}%, ${colors.bearish} ${t * 100}%)`;
  }
  return colors.neutral;
}

function drawOverlay(
  ctx: CanvasRenderingContext2D,
  w: number,
  h: number,
  sentiments: OSentimentPoint[],
  colors: OverlayColors,
  showVolume: boolean,
  highlightTime: number | null,
  lowPerformanceMode: boolean
): { timeToX: (t: number) => number; xToTime: (x: number) => number } | null {
  ctx.clearRect(0, 0, w, h);
  if (sentiments.length === 0) return null;

  const minT = sentiments[0]!.time;
  const maxT = sentiments[sentiments.length - 1]!.time;
  const tRange = Math.max(maxT - minT, 1);

  const maxVol = Math.max(...sentiments.map((s) => s.volume), 1);

  const timeToX = (t: number) => ((t - minT) / tRange) * w;
  const xToTime = (x: number) => minT + (x / w) * tRange;

  // 1) Sentiment 色条 (顶部)
  const sentimentBandH = showVolume ? h * 0.45 : h * 0.8;
  const sentimentBandY = h * 0.1;
  const barW = w / sentiments.length;

  for (let i = 0; i < sentiments.length; i++) {
    const s = sentiments[i]!;
    const x = timeToX(s.time);
    ctx.fillStyle = scoreToColor(s.score, colors);
    // 用半透明,作为 overlay 不喧宾夺主
    ctx.globalAlpha = 0.5;
    ctx.fillRect(x, sentimentBandY, Math.max(barW - 0.5, 1), sentimentBandH);
  }
  ctx.globalAlpha = 1;

  // 2) Volume 柱 (底部) - 低性能模式跳过
  if (showVolume && !lowPerformanceMode) {
    const volBandY = sentimentBandY + sentimentBandH + 4;
    const volBandH = h - volBandY - 12;
    ctx.fillStyle = colors.volume;
    ctx.globalAlpha = 0.4;
    for (let i = 0; i < sentiments.length; i++) {
      const s = sentiments[i]!;
      const x = timeToX(s.time);
      const barH = (s.volume / maxVol) * volBandH;
      ctx.fillRect(x, volBandY + volBandH - barH, Math.max(barW - 0.5, 1), barH);
    }
    ctx.globalAlpha = 1;
  }

  // 3) Crosshair 高亮线
  if (highlightTime != null && highlightTime >= minT && highlightTime <= maxT) {
    const hx = timeToX(highlightTime);
    ctx.strokeStyle = colors.highlight;
    ctx.globalAlpha = 0.5;
    ctx.setLineDash([2, 3]);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(hx, 0);
    ctx.lineTo(hx, h);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.globalAlpha = 1;
  }

  // 4) Y 轴标签 (情绪强度示意,极简)
  ctx.fillStyle = colors.textMuted;
  ctx.font = '9px ui-monospace, monospace';
  ctx.textAlign = 'left';
  ctx.fillText('情绪', 4, sentimentBandY + 8);
  if (showVolume && !lowPerformanceMode) {
    ctx.fillText('热度', 4, sentimentBandY + sentimentBandH + 14);
  }

  return { timeToX, xToTime };
}

// ============================================================
// 主组件
// ============================================================

interface HoverInfo {
  x: number;
  y: number;
  point: OSentimentPoint;
}

export const OSocialOverlay = forwardRef<HTMLDivElement, OSocialOverlayProps>(
  function OSocialOverlay(
    {
      data: dataProp,
      loading,
      error,
      empty,
      channel,
      syncToCrosshair = true,
      height = 80,
      showVolume = true,
      lowPerformanceMode = false,
      dataDelay = 0,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OSocialOverlayData | null>(null);

    useEffect(() => {
      if (!channel || !fastData) return;
      const unsub = fastData.subscribe<OSocialOverlayData>(channel, (next) => {
        setChannelData(next);
      });
      return unsub;
    }, [channel, fastData]);

    const data = channel ? channelData : (dataProp ?? null);
    const state = resolveBlockState({ data, loading, error, empty });

    const crosshair = useCrosshair();
    const [highlightTime, setHighlightTime] = useState<number | null>(null);
    const [hover, setHover] = useState<HoverInfo | null>(null);

    useEffect(() => {
      if (!syncToCrosshair || !crosshair) return;
      return crosshair.subscribe((s) => {
        if (s.symbol && data && s.symbol === data.symbol) {
          setHighlightTime(s.time);
        } else {
          setHighlightTime(null);
        }
      });
    }, [crosshair, syncToCrosshair, data]);

    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const coordsRef = useRef<{
      timeToX: (t: number) => number;
      xToTime: (x: number) => number;
    } | null>(null);

    useEffect(() => {
      if (state !== 'ready' || !data) return;
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      function draw() {
        if (!canvas || !data) return;
        const parent = canvas.parentElement!;
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        const w = parent.clientWidth;
        const h = parent.clientHeight;
        canvas.width = w * dpr;
        canvas.height = h * dpr;
        canvas.style.width = `${w}px`;
        canvas.style.height = `${h}px`;
        ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);

        const colors = readColors();
        coordsRef.current = drawOverlay(
          ctx!,
          w,
          h,
          data.sentiments,
          colors,
          showVolume,
          highlightTime,
          lowPerformanceMode
        );
      }

      draw();
      const ro = new ResizeObserver(draw);
      if (canvas.parentElement) ro.observe(canvas.parentElement);
      return () => ro.disconnect();
    }, [data, state, showVolume, lowPerformanceMode, highlightTime]);

    function handleMouseMove(e: React.MouseEvent) {
      if (!data || !coordsRef.current) return;
      const canvas = canvasRef.current;
      if (!canvas) return;
      const rect = canvas.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const t = coordsRef.current.xToTime(x);
      // 找最近的 sentiment 点
      let nearest = data.sentiments[0]!;
      let minDist = Math.abs(t - nearest.time);
      for (const s of data.sentiments) {
        const d = Math.abs(s.time - t);
        if (d < minDist) {
          nearest = s;
          minDist = d;
        }
      }
      setHover({ x, y, point: nearest });

      // 向 crosshair 广播
      if (syncToCrosshair && crosshair) {
        crosshair.broadcast({
          symbol: data.symbol,
          time: nearest.time,
          value: null,
        });
      }
    }

    function handleMouseLeave() {
      setHover(null);
      if (syncToCrosshair && crosshair) {
        crosshair.broadcast({ symbol: null, time: null, value: null });
      }
    }

    if (state === 'loading')
      return (
        <div
          ref={ref}
          className={cn('rounded-md border border-border bg-card', className)}
          style={{ height }}
        >
          <OLoadingState variant="skeleton" rows={1} />
        </div>
      );
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data || data.sentiments.length === 0)
      return (
        <OEmptyState
          ref={ref}
          title="No social data"
          description="No community sentiment available for this time range."
          className={className}
        />
      );

    const scorePct = (s: number) => `${s > 0 ? '+' : ''}${(s * 100).toFixed(0)}%`;
    const sentimentLabel = (s: number) =>
      s > 0.3 ? '看多' : s > 0.1 ? '微多' : s < -0.3 ? '看空' : s < -0.1 ? '微空' : '中性';

    return (
      <div
        ref={ref}
        className={cn(
          'relative rounded-md border border-border bg-card/50 overflow-hidden @container',
          className
        )}
        style={{ height }}
      >
        {/* 顶部 source 标签 */}
        <div className="absolute top-1 right-2 z-10 flex items-center gap-2 text-[10px] text-[color:var(--text-muted)] pointer-events-none">
          {data.source ? <span>{data.source}</span> : null}
          {dataDelay > 0 ? (
            <span className="text-[color:var(--alert-warn)]">延时 {dataDelay}m</span>
          ) : null}
        </div>

        <canvas
          ref={canvasRef}
          onMouseMove={handleMouseMove}
          onMouseLeave={handleMouseLeave}
          className="cursor-crosshair"
          aria-hidden="true"
        />

        {/* Hover tooltip */}
        {hover ? (
          <div
            className="absolute z-20 pointer-events-none px-2 py-1.5 rounded text-[11px] font-mono whitespace-nowrap shadow-lg"
            style={{
              left: Math.min(hover.x + 12, 999),
              top: Math.max(hover.y - 24, 4),
              background: 'var(--popover)',
              color: 'var(--popover-foreground)',
              border: '1px solid var(--border)',
              maxWidth: 260,
            }}
          >
            <div className="flex items-center gap-3">
              <span style={{ color: scoreToColor(hover.point.score, readColors()) }}>
                {sentimentLabel(hover.point.score)} {scorePct(hover.point.score)}
              </span>
              <span className="text-[color:var(--text-muted)]">
                热度 {hover.point.volume}
              </span>
            </div>
            {hover.point.top ? (
              <div className="text-[color:var(--muted-foreground)] mt-1 truncate" style={{ maxWidth: 240 }}>
                {hover.point.top}
              </div>
            ) : null}
          </div>
        ) : null}
      </div>
    );
  }
);

OSocialOverlay.displayName = 'OSocialOverlay';
