/**
 * useCountUp - 数字渐进动画 hook。
 *
 * 在 prefers-reduced-motion 下直接返回终值 (无动画)。
 *
 * @example
 * const display = useCountUp(67432, { duration: 1200, format: (v) => v.toFixed(0) });
 */
'use client';

import { useEffect, useRef, useState } from 'react';
import { useReducedMotion } from './useReducedMotion';

interface CountUpOptions {
  /** 动画时长 (ms)。 */
  duration?: number;
  /** 起始值,默认 0。 */
  start?: number;
  /** 格式化输出。 */
  format?: (v: number) => string;
  /** 缓动函数 (0-1 → 0-1)。默认 ease-out-cubic。 */
  easing?: (t: number) => number;
}

const easeOutCubic = (t: number) => 1 - Math.pow(1 - t, 3);

export function useCountUp(target: number, opts: CountUpOptions = {}) {
  const { duration = 1000, start = 0, format = (v) => v.toLocaleString(), easing = easeOutCubic } = opts;
  const reduced = useReducedMotion();
  const [value, setValue] = useState<number>(reduced ? target : start);
  const rafRef = useRef<number | null>(null);
  const fromRef = useRef<number>(start);

  useEffect(() => {
    if (reduced) {
      setValue(target);
      return;
    }

    fromRef.current = value;
    const begin = performance.now();
    const delta = target - fromRef.current;

    const tick = (now: number) => {
      const elapsed = now - begin;
      const t = Math.min(elapsed / duration, 1);
      const v = fromRef.current + delta * easing(t);
      setValue(v);
      if (t < 1) {
        rafRef.current = requestAnimationFrame(tick);
      }
    };

    rafRef.current = requestAnimationFrame(tick);
    return () => {
      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
    };
    // value intentionally excluded to avoid infinite loop
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target, duration, reduced]);

  return {
    value,
    display: format(value),
  };
}
