'use client';
import { forwardRef, type HTMLAttributes } from 'react';
import { cn } from '../../lib/cn';
import { badgeRecipe, type BadgeRecipeProps } from '../../recipes';

export interface OBadgeProps extends HTMLAttributes<HTMLSpanElement>, BadgeRecipeProps {}

export const OBadge = forwardRef<HTMLSpanElement, OBadgeProps>(
  function OBadge({ variant, shape, className, ...rest }, ref) {
    return <span ref={ref} className={cn(badgeRecipe({ variant, shape }), className)} {...rest} />;
  }
);
OBadge.displayName = 'OBadge';
