/**
 * OStrategyBar (Tide Wave 2 E9, Atom)
 *
 * 候选池顶端的策略状态条。
 * 来源:OUI_WAVE_2_REQUIREMENTS_v1.0.md §6
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { REGIME_COLOR_VAR, REGIME_LABEL, type RegimeState } from '../../types/tide';
import type { OBlockBaseProps } from '../../lib/types';

export interface OStrategyBarProps extends Omit<OBlockBaseProps, 'variant'> {
  regime: RegimeState;
  strategyLabel?: string;
  topNDisplayed: number;
  topNTotal: number;
  multiplier: number;
  highlights: string[];
  icon?: string;
}

export const OStrategyBar = forwardRef<HTMLDivElement, OStrategyBarProps>(
  function OStrategyBar(
    {
      regime,
      strategyLabel = '标准',
      topNDisplayed,
      topNTotal,
      multiplier,
      highlights,
      icon = '🎯',
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const regimeColor = REGIME_COLOR_VAR[regime];
    return (
      <div
        ref={ref}
        className={cn(
          'flex flex-col gap-1 px-2 py-1.5 rounded @container',
          'border border-[color:var(--border-strong)]',
          className
        )}
        style={{
          fontFamily: 'var(--font-mono)',
          backgroundColor: `color-mix(in srgb, ${regimeColor} 10%, var(--card))`,
        }}
        role="region"
        aria-label={`策略 ${strategyLabel} · ${REGIME_LABEL[regime]} regime`}
      >
        <div className="flex items-center justify-between text-xs">
          <div className="flex items-center gap-1.5">
            <span aria-hidden="true">{icon}</span>
            <span style={{ color: 'var(--muted-foreground)' }}>策略 ·</span>
            <span
              className="font-bold"
              style={{ color: regimeColor }}
            >
              {REGIME_LABEL[regime]} regime
            </span>
            <span style={{ color: 'var(--muted-foreground)' }}>· {strategyLabel}</span>
          </div>
          <span
            className="text-[10px]"
            style={{ color: 'var(--muted-foreground)' }}
          >
            top {topNDisplayed} / {topNTotal}
          </span>
        </div>
        <div
          className="text-[10px] flex items-center gap-1 flex-wrap"
          style={{ color: 'var(--text-tertiary)' }}
        >
          <span>multiplier {multiplier.toFixed(1)}×</span>
          {highlights.map((h, i) => (
            <span key={i}>· {h}</span>
          ))}
        </div>
      </div>
    );
  }
);

OStrategyBar.displayName = 'OStrategyBar';
