/**
 * OKlineMultiTimeframe (Tide Wave 2 E12, Block)
 *
 * K 线图 6 timeframe 切换 + 指标 chip + 集合竞价自动 1min。
 * 来源:OUI_WAVE_2_REQUIREMENTS_v1.0.md §9
 *
 * 渲染:轻量 SVG 实现(简化版, 完整 lightweight-charts 集成留 v2.x)
 * 切换 timeframe < 50ms (data 已 prefetch)
 * 集合竞价: 9:15-9:25 (UTC+8) 自动添加 1min tab
 * 红涨绿跌(ashare=true)
 */
import { forwardRef, useEffect, useMemo, useState } from 'react';
import { cn } from '../../lib/cn';
import type { KlineData, TimeframeOption } from '../../types/tide';
import type { OBlockBaseProps } from '../../lib/types';

export interface OKlineMultiTimeframeProps extends Omit<OBlockBaseProps, 'variant'> {
  symbol: string;
  timeframes?: TimeframeOption[];
  defaultTimeframe?: TimeframeOption;
  indicators?: string[];
  activeIndicators?: string[];
  data: { [timeframe: string]: KlineData[] };
  onTimeframeChange?: (tf: TimeframeOption) => void;
  onIndicatorToggle?: (ind: string, active: boolean) => void;
  onFullscreen?: () => void;
  height?: number;
  ashare?: boolean;
}

const DEFAULT_TIMEFRAMES: TimeframeOption[] = ['5min', '15min', '60min', '日', '周', '月'];
const DEFAULT_INDICATORS = ['MA5', 'MA20', 'MA60', 'MACD', 'KDJ', 'BOLL', 'VOL'];

function isAuctionPeriod(): boolean {
  // 简化:UTC+8 9:15-9:25(jsdom 测试可能在其他时区,这里仅 demo)
  try {
    const now = new Date();
    const cn = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Shanghai' }));
    const h = cn.getHours();
    const m = cn.getMinutes();
    const totalMin = h * 60 + m;
    return totalMin >= 9 * 60 + 15 && totalMin <= 9 * 60 + 25;
  } catch {
    return false;
  }
}

export const OKlineMultiTimeframe = forwardRef<HTMLDivElement, OKlineMultiTimeframeProps>(
  function OKlineMultiTimeframe(
    {
      symbol: _symbol,
      timeframes = DEFAULT_TIMEFRAMES,
      defaultTimeframe = '日',
      indicators = DEFAULT_INDICATORS,
      activeIndicators: controlledActive,
      data,
      onTimeframeChange,
      onIndicatorToggle,
      onFullscreen,
      height = 240,
      ashare = true,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const [activeTf, setActiveTf] = useState<TimeframeOption>(defaultTimeframe);
    const [internalActive, setInternalActive] = useState<string[]>(
      controlledActive ?? ['MA5', 'MA20']
    );
    const isControlled = controlledActive !== undefined;
    const activeInds = isControlled ? controlledActive : internalActive;

    // 集合竞价自动加 1min
    const [auctionActive, setAuctionActive] = useState(false);
    useEffect(() => {
      const check = () => setAuctionActive(isAuctionPeriod());
      check();
      const t = setInterval(check, 30000);
      return () => clearInterval(t);
    }, []);

    const effectiveTimeframes = useMemo(() => {
      if (auctionActive && !timeframes.includes('1min')) {
        return ['1min' as TimeframeOption, ...timeframes];
      }
      return timeframes;
    }, [timeframes, auctionActive]);

    const handleTfClick = (tf: TimeframeOption) => {
      setActiveTf(tf);
      onTimeframeChange?.(tf);
    };

    const toggleIndicator = (ind: string) => {
      const isActive = activeInds.includes(ind);
      const next = isActive ? activeInds.filter((i) => i !== ind) : [...activeInds, ind];
      if (!isControlled) setInternalActive(next);
      onIndicatorToggle?.(ind, !isActive);
    };

    const candles = useMemo(() => data[activeTf] ?? [], [data, activeTf]);
    const chartHeight = height - 60;

    // 计算 K 线 SVG 坐标
    const chartView = useMemo(() => {
      if (candles.length === 0) return null;
      const highs = candles.map((c) => c.high);
      const lows = candles.map((c) => c.low);
      const max = Math.max(...highs);
      const min = Math.min(...lows);
      const range = max - min || 1;
      const w = 600;
      const padding = 4;
      const usableH = chartHeight - padding * 2;
      const cw = (w - padding * 2) / candles.length;
      const bw = Math.max(cw * 0.6, 1);

      const upColor = ashare ? 'var(--red-up)' : 'var(--green-down)';
      const downColor = ashare ? 'var(--green-down)' : 'var(--red-up)';

      const bars = candles.map((c, i) => {
        const x = padding + i * cw + cw / 2;
        const isUp = c.close >= c.open;
        const color = isUp ? upColor : downColor;
        const yHigh = padding + ((max - c.high) / range) * usableH;
        const yLow = padding + ((max - c.low) / range) * usableH;
        const yOpen = padding + ((max - c.open) / range) * usableH;
        const yClose = padding + ((max - c.close) / range) * usableH;
        const yTop = Math.min(yOpen, yClose);
        const bodyH = Math.max(Math.abs(yClose - yOpen), 1);
        return { x, yHigh, yLow, yTop, bodyH, bw, color, key: i };
      });
      return { bars, w, padding, max, min };
    }, [candles, chartHeight, ashare]);

    return (
      <div
        ref={ref}
        className={cn('flex flex-col w-full', className)}
        style={{
          fontFamily: 'var(--font-mono)',
          backgroundColor: 'var(--card)',
          minHeight: height,
        }}
      >
        {/* timeframe tabs */}
        <div
          role="tablist"
          aria-label="时间周期"
          className="flex items-center gap-0 border-b border-[color:var(--border-subtle)]"
        >
          {effectiveTimeframes.map((tf) => {
            const active = activeTf === tf;
            const isAuctionTab = tf === '1min' && auctionActive;
            return (
              <button
                key={tf}
                type="button"
                role="tab"
                aria-selected={active}
                onClick={() => handleTfClick(tf)}
                className={cn(
                  'px-2 py-1 text-xs transition-colors @container',
                  active
                    ? 'text-[color:var(--foreground)] border-b border-[color:var(--blue-accent)]'
                    : 'text-[color:var(--text-tertiary)] hover:text-[color:var(--foreground)]',
                  isAuctionTab && 'animate-pulse text-[color:var(--yellow)]'
                )}
              >
                {tf}
                {isAuctionTab && <span className="ml-0.5">●</span>}
              </button>
            );
          })}
          {onFullscreen && (
            <button
              type="button"
              onClick={onFullscreen}
              aria-label="全屏"
              className={cn(
                'ml-auto px-2 py-1 text-xs',
                'text-[color:var(--text-tertiary)] hover:text-[color:var(--foreground)]'
              )}
            >
              ↗
            </button>
          )}
        </div>

        {/* chart */}
        <div className="relative" style={{ height: chartHeight }}>
          {candles.length === 0 ? (
            <div className="absolute inset-0 flex items-center justify-center text-xs"
              style={{ color: 'var(--text-tertiary)' }}
            >
              暂无数据
            </div>
          ) : chartView ? (
            <svg
              width="100%"
              height={chartHeight}
              viewBox={`0 0 ${chartView.w} ${chartHeight}`}
              preserveAspectRatio="none"
              role="img"
              aria-label="K 线图"
            >
              {chartView.bars.map((b) => (
                <g key={b.key}>
                  {/* wick */}
                  <line
                    x1={b.x}
                    y1={b.yHigh}
                    x2={b.x}
                    y2={b.yLow}
                    stroke={b.color}
                    strokeWidth={1}
                  />
                  {/* body */}
                  <rect
                    x={b.x - b.bw / 2}
                    y={b.yTop}
                    width={b.bw}
                    height={b.bodyH}
                    fill={b.color}
                  />
                </g>
              ))}
            </svg>
          ) : null}
        </div>

        {/* indicator chips */}
        <div
          className="flex items-center gap-1 px-2 py-1 border-t border-[color:var(--border-subtle)] flex-wrap"
        >
          {indicators.map((ind) => {
            const active = activeInds.includes(ind);
            return (
              <button
                key={ind}
                type="button"
                onClick={() => toggleIndicator(ind)}
                aria-pressed={active}
                className={cn(
                  'px-1.5 py-0.5 text-[10px] rounded transition-colors',
                  active
                    ? 'bg-[color:var(--blue-accent)]/20 text-[color:var(--blue-accent)]'
                    : 'text-[color:var(--text-tertiary)] hover:text-[color:var(--foreground)]'
                )}
              >
                {ind}
              </button>
            );
          })}
        </div>
      </div>
    );
  }
);

OKlineMultiTimeframe.displayName = 'OKlineMultiTimeframe';
