/**
 * OFeatureFlag — 跨项目 feature flag UI 包装器
 *
 * 来源:Helios 经理人 R1 §1.5(配套 HELIOS_V1_FEATURE_FLAGS)
 *      Tide R1 §5(配套 isTideFeatureEnabled)
 *      Stratum / Helivex / hevi 都有 FeatureFlag enum
 *
 * 哲学:声明式包装 — children 显示条件 + fallback 显示阻塞提示。
 *
 * 跨项目通用,不绑定单一项目的 feature enum。
 */

'use client';

import type { ReactNode } from 'react';

export interface OFeatureFlagProps {
  /**
   * 当前 feature 是否启用。
   * 调用方传 `isStratumFeatureEnabled(StratumFeature.TTS)`
   * 或 `HELIOS_V1_FEATURE_FLAGS.BACKTEST_RESULT_VIEWER` 等任意 boolean。
   */
  enabled: boolean;
  /** 启用时渲染。 */
  children: ReactNode;
  /**
   * 禁用时渲染。
   * - 不传 = 不渲染任何东西(hide 策略)
   * - 传 ReactNode = 渲染 fallback(通常是 OBlockedCard 或 disabled Button)
   */
  fallback?: ReactNode;
}

/**
 * 声明式 feature flag 渲染。
 *
 * @example
 * ```tsx
 * <OFeatureFlag
 *   enabled={isStratumFeatureEnabled(StratumFeature.TTS)}
 *   fallback={<Button disabled>朗读(v1.1 启用)</Button>}
 * >
 *   <Button onClick={handleTTS}>朗读</Button>
 * </OFeatureFlag>
 * ```
 *
 * @example
 * ```tsx
 * // 用 HELIOS_V1_FEATURE_FLAGS
 * <OFeatureFlag
 *   enabled={HELIOS_V1_FEATURE_FLAGS.BACKTEST_RESULT_VIEWER}
 *   fallback={<OBlockedCard title="Backtest" reason="v5-1 上线" />}
 * >
 *   <BacktestResultViewer />
 * </OFeatureFlag>
 * ```
 */
export function OFeatureFlag({
  enabled,
  children,
  fallback = null,
}: OFeatureFlagProps): ReactNode {
  return enabled ? children : fallback;
}

OFeatureFlag.displayName = 'OFeatureFlag';
