'use client';
import { forwardRef, type ButtonHTMLAttributes } from 'react';
import { cn } from '../../lib/cn';
import { buttonRecipe, type ButtonRecipeProps } from '../../recipes';

export interface OButtonProps
  extends ButtonHTMLAttributes<HTMLButtonElement>,
    ButtonRecipeProps {
  loading?: boolean;
}

export const OButton = forwardRef<HTMLButtonElement, OButtonProps>(
  function OButton({ variant, size, loading, disabled, className, children, ...rest }, ref) {
    return (
      <button
        ref={ref}
        className={cn(buttonRecipe({ variant, size }), className)}
        disabled={disabled || loading}
        aria-busy={loading || undefined}
        {...rest}
      >
        {loading && (
          <svg className="animate-spin size-4" viewBox="0 0 24 24" aria-hidden>
            <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3" fill="none" opacity="0.25" />
            <path d="M12 2 a10 10 0 0 1 10 10" stroke="currentColor" strokeWidth="3" fill="none" />
          </svg>
        )}
        {children}
      </button>
    );
  }
);
OButton.displayName = 'OButton';
