/**
 * ThemeProvider - 主题状态管理 (v2.0,支持 Terminal 主题 + 双轴密度)。
 *
 * SPEC §6.2 (主) + Helios Terminal SPEC §5-6 (子)
 *
 * 用法 (展示场景):
 *   <ThemeProvider theme="cyberpunk">
 *     <MarketingPage />
 *   </ThemeProvider>
 *
 * 用法 (工作台场景):
 *   <ThemeProvider
 *     theme="terminal-dark"
 *     density={{ info: 'compact', visual: 'standard' }}
 *   >
 *     <TerminalProviders>
 *       <Dashboard />
 *     </TerminalProviders>
 *   </ThemeProvider>
 *
 * 嵌套覆盖 (单个 Block 用不同 theme):
 *   <ThemeProvider theme="terminal-dark">
 *     <ODataTable />
 *     <ThemeProvider theme="terminal-paper" attachToRoot={false}>
 *       <ResearchPanel />
 *     </ThemeProvider>
 *   </ThemeProvider>
 */

'use client';

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import type { ColorMode, Theme } from '../lib/types';

// ============================================================
// 双轴密度类型
// ============================================================

export type InfoDensity = 'compact' | 'comfortable' | 'spacious';
export type VisualDensity = 'minimal' | 'standard' | 'rich';

export interface Density {
  info: InfoDensity;
  visual: VisualDensity;
}

// ============================================================
// Context
// ============================================================

interface ThemeContextValue {
  theme: Theme;
  mode: ColorMode;
  /** 实际生效的明暗(mode='system' 时为系统解析值;否则等于 mode)。DOM 的 data-mode 用此值。 */
  resolvedMode: 'dark' | 'light';
  density: Density;
  setTheme: (theme: Theme) => void;
  setMode: (mode: ColorMode) => void;
  setDensity: (density: Partial<Density>) => void;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

// ============================================================
// 主题元信息
// ============================================================

const THEME_DEFAULT: Theme = 'terminal-dark';

const MODE_DEFAULTS: Record<Theme, ColorMode> = {
  // 展示主题
  cyberpunk: 'dark',
  professional: 'dark',
  academic: 'light',
  'mneme-friendly': 'light',   // K12 学生端:浅色暖白
  // 工作台主题
  'terminal-dark': 'dark',
  'terminal-light': 'light',
  'terminal-paper': 'light',  // @deprecated alias for zen
  'terminal-neon': 'dark',
  // 知识类主题 (Stratum)
  zen: 'light',
};

/**
 * 每个主题的推荐密度配对。用户可以覆盖,但默认是这个。
 *
 * 推荐配对依据 (Helios Terminal SPEC §6.3):
 *   - 桌面工作台          → compact + standard
 *   - paper (长时间阅读)  → spacious + minimal
 *   - neon (加密用户)     → compact + rich
 *   - academic (论文站)   → spacious + minimal
 */
const DENSITY_DEFAULTS: Record<Theme, Density> = {
  cyberpunk:          { info: 'comfortable', visual: 'rich' },
  professional:       { info: 'comfortable', visual: 'standard' },
  academic:           { info: 'spacious',    visual: 'minimal' },
  'mneme-friendly':   { info: 'spacious',    visual: 'standard' }, // K12: 字大、宽松
  'terminal-dark':    { info: 'compact',     visual: 'standard' },
  'terminal-light':   { info: 'compact',     visual: 'standard' },
  'terminal-paper':   { info: 'spacious',    visual: 'minimal' },
  'terminal-neon':    { info: 'compact',     visual: 'rich' },
  zen:                { info: 'spacious',    visual: 'minimal' },
};

// ============================================================
// Props
// ============================================================

export interface ThemeProviderProps {
  /** 当前主题。默认 'terminal-dark' (加密散户场景)。 */
  theme?: Theme;

  /** 颜色模式。每个主题有默认 mode (见 MODE_DEFAULTS)。 */
  mode?: ColorMode;

  /**
   * 双轴密度。
   * - 完整对象:覆盖默认 { info: 'compact', visual: 'standard' }
   * - 部分对象:只覆盖指定的轴
   * - 不传:使用主题默认
   */
  density?: Partial<Density>;

  /**
   * 是否将 data-theme 写入 document.documentElement (根)。
   * 默认 true。嵌套 ThemeProvider 时,内层应设 false (写到本地 div 而非根)。
   */
  attachToRoot?: boolean;

  children: ReactNode;
}

// ============================================================
// Implementation
// ============================================================

export function ThemeProvider({
  theme: themeProp = THEME_DEFAULT,
  mode: modeProp,
  density: densityProp,
  attachToRoot = true,
  children,
}: ThemeProviderProps) {
  const [theme, setTheme] = useState<Theme>(themeProp);
  const [mode, setMode] = useState<ColorMode>(modeProp ?? MODE_DEFAULTS[themeProp]);

  // 解析系统明暗偏好(SSR 安全:服务端返回 'light' 兜底)
  const getSystemMode = (): 'dark' | 'light' => {
    if (typeof window === 'undefined' || !window.matchMedia) return 'light';
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  };
  // resolvedMode = 实际生效的明暗(mode='system' 时跟随系统;否则等于 mode)
  const [systemMode, setSystemMode] = useState<'dark' | 'light'>(getSystemMode);
  const resolvedMode: 'dark' | 'light' = mode === 'system' ? systemMode : mode;

  // 监听系统明暗变化(仅当 mode='system' 时活跃)
  useEffect(() => {
    if (mode !== 'system' || typeof window === 'undefined' || !window.matchMedia) return;
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    const onChange = (e: MediaQueryListEvent) => setSystemMode(e.matches ? 'dark' : 'light');
    setSystemMode(mq.matches ? 'dark' : 'light'); // 立即同步一次
    // addEventListener 兼容旧 Safari 的 addListener
    if (mq.addEventListener) mq.addEventListener('change', onChange);
    else mq.addListener(onChange);
    return () => {
      if (mq.removeEventListener) mq.removeEventListener('change', onChange);
      else mq.removeListener(onChange);
    };
  }, [mode]);
  const [density, setDensityState] = useState<Density>({
    ...DENSITY_DEFAULTS[themeProp],
    ...densityProp,
  });

  // 外部 prop 变化时同步内部 state
  useEffect(() => {
    setTheme(themeProp);
  }, [themeProp]);

  useEffect(() => {
    if (modeProp) setMode(modeProp);
    else setMode(MODE_DEFAULTS[theme]);
  }, [theme, modeProp]);

  useEffect(() => {
    setDensityState({
      ...DENSITY_DEFAULTS[theme],
      ...densityProp,
    });
  }, [theme, densityProp]);

  // 写入 document.documentElement
  useEffect(() => {
    if (!attachToRoot || typeof document === 'undefined') return;
    const root = document.documentElement;
    const prev = {
      theme: root.getAttribute('data-theme'),
      mode: root.getAttribute('data-mode'),
      info: root.getAttribute('data-info-density'),
      visual: root.getAttribute('data-visual-density'),
    };
    root.setAttribute('data-theme', theme);
    root.setAttribute('data-mode', resolvedMode);
    root.setAttribute('data-info-density', density.info);
    root.setAttribute('data-visual-density', density.visual);
    return () => {
      if (prev.theme) root.setAttribute('data-theme', prev.theme);
      else root.removeAttribute('data-theme');
      if (prev.mode) root.setAttribute('data-mode', prev.mode);
      else root.removeAttribute('data-mode');
      if (prev.info) root.setAttribute('data-info-density', prev.info);
      else root.removeAttribute('data-info-density');
      if (prev.visual) root.setAttribute('data-visual-density', prev.visual);
      else root.removeAttribute('data-visual-density');
    };
  }, [theme, mode, resolvedMode, density, attachToRoot]);

  const setDensity = (next: Partial<Density>) => {
    setDensityState((d) => ({ ...d, ...next }));
  };

  const value = useMemo<ThemeContextValue>(
    () => ({ theme, mode, resolvedMode, density, setTheme, setMode, setDensity }),
    [theme, mode, resolvedMode, density]
  );

  // 嵌套场景: 不写根, 包一个 div 局部切换
  if (!attachToRoot) {
    return (
      <ThemeContext.Provider value={value}>
        <div
          data-theme={theme}
          data-mode={resolvedMode}
          data-info-density={density.info}
          data-visual-density={density.visual}
        >
          {children}
        </div>
      </ThemeContext.Provider>
    );
  }

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

/**
 * 读取当前主题 / 模式 / 密度。
 *
 * 在 ThemeProvider 之外调用时返回兜底值,不抛错,方便测试环境 / Storybook
 * 独立挂载 Block 时也能工作。
 */
export function useTheme(): ThemeContextValue {
  const ctx = useContext(ThemeContext);
  if (ctx) return ctx;
  return {
    theme: THEME_DEFAULT,
    mode: MODE_DEFAULTS[THEME_DEFAULT],
    resolvedMode: MODE_DEFAULTS[THEME_DEFAULT] === 'system' ? 'light' : MODE_DEFAULTS[THEME_DEFAULT],
    density: DENSITY_DEFAULTS[THEME_DEFAULT],
    setTheme: () => {},
    setMode: () => {},
    setDensity: () => {},
  };
}

/** 仅读取密度,便于 Block 内部使用 */
export function useDensity(): Density {
  return useTheme().density;
}

// 元信息导出
export const THEME_LIST: readonly Theme[] = [
  'cyberpunk',
  'professional',
  'academic',
  'mneme-friendly',
  'terminal-dark',
  'terminal-light',
  'terminal-neon',
  'zen',
] as const;

export const TERMINAL_THEMES: readonly Theme[] = [
  'terminal-dark',
  'terminal-light',
  'terminal-neon',
  'zen',
] as const;

export { MODE_DEFAULTS, DENSITY_DEFAULTS };
