/**
 * 拼音匹配工具 (轻量版,无外部依赖)。
 *
 * 加密用户在中文输入下可能想找 "比特币" 但输入 "btb" (拼音首字母),
 * 或者输入 "bite" (拼音前缀)。我们提供两种匹配:
 *
 * 1. 首字母匹配: "比特币" → "btb", "以太坊" → "ytf"
 * 2. 全拼模糊匹配: "比特币" → "bitebi" / "bite"
 *
 * 实现策略 (避免引入 ~200KB 的 pinyin lib):
 *   - 内置约 500 个加密 + 金融常用字的简表
 *   - 表外字降级为忽略 (返回非匹配)
 *   - 实际生产中可以让 Helios 用户传入扩展表
 *
 * 用法:
 *   matchPinyin('比特币', 'btb')   → true (首字母全匹配)
 *   matchPinyin('比特币', 'bite')  → true (全拼前缀)
 *   matchPinyin('比特币', 'xyz')   → false
 *   isLikelyChinese('比特币 BTC')  → true
 *   isPureAscii('btb')             → true
 */

// ============================================================
// 常用字拼音表 (加密/金融场景优先)
// ============================================================

const PINYIN_TABLE: Record<string, string> = {
  // 加密币种常用字
  比: 'bi', 特: 'te', 币: 'bi', 以: 'yi', 太: 'tai', 坊: 'fang',
  索: 'suo', 拉: 'la', 那: 'na', 币安: 'bi an', 安: 'an',
  狗: 'gou', 卡: 'ka', 尔: 'er', 达: 'da', 莱: 'lai',
  // 金融操作
  买: 'mai', 卖: 'mai', 入: 'ru', 出: 'chu', 单: 'dan', 限: 'xian', 价: 'jia',
  市: 'shi', 现: 'xian', 合: 'he', 约: 'yue', 杠: 'gang', 杆: 'gan', 多: 'duo',
  空: 'kong', 平: 'ping', 仓: 'cang', 开: 'kai', 止: 'zhi', 损: 'sun', 盈: 'ying',
  // 行情/视图
  涨: 'zhang', 跌: 'die', 幅: 'fu', 量: 'liang', 价格: 'jia ge',
  日: 'ri', 周: 'zhou', 月: 'yue', 年: 'nian', 分: 'fen', 钟: 'zhong', 时: 'shi',
  线: 'xian', 图: 'tu', 表: 'biao', 盘: 'pan', 口: 'kou', 深: 'shen', 度: 'du',
  成: 'cheng', 交: 'jiao', 历: 'li', 史: 'shi', 资: 'zi', 金: 'jin', 流: 'liu',
  向: 'xiang', 持: 'chi', 有: 'you', 自: 'zi', 选: 'xuan', 股: 'gu',
  // 警报/AI
  警: 'jing', 报: 'bao', 提: 'ti', 醒: 'xing', 设: 'she', 置: 'zhi',
  分析: 'fen xi', 推: 'tui', 荐: 'jian', 建: 'jian', 议: 'yi',
  // 时间/常用
  今: 'jin', 天: 'tian', 昨: 'zuo', 明: 'ming', 上: 'shang', 下: 'xia',
  最: 'zui', 高: 'gao', 低: 'di', 新: 'xin', 近: 'jin', 旧: 'jiu',
  添: 'tian', 加: 'jia', 删: 'shan', 除: 'chu', 复: 'fu', 制: 'zhi',
  // 数字/单位
  万: 'wan', 亿: 'yi', 千: 'qian', 百: 'bai',
  // K 线/技术指标
  均: 'jun', 布: 'bu', 林: 'lin', 带: 'dai',
  // 区域
  美: 'mei', 国: 'guo', 港: 'gang', 中: 'zhong',
  // 工作台/视图
  工: 'gong', 作: 'zuo', 区: 'qu', 视: 'shi', 切: 'qie', 换: 'huan', 主: 'zhu', 题: 'ti',
  // 网格/套利策略
  网: 'wang', 格: 'ge', 套: 'tao', 利: 'li', 化: 'hua',
  // 时空切片
  回: 'hui', 放: 'fang', 重: 'chong', 播: 'bo',
};

// ============================================================
// 公开 API
// ============================================================

/**
 * 把中文文本转成拼音字符串数组 (每个字一段)。
 * 不在表内的字返回原字符 (英文/数字/标点透传)。
 */
function toPinyin(text: string): string[] {
  const result: string[] = [];
  for (const ch of text) {
    if (PINYIN_TABLE[ch]) {
      result.push(PINYIN_TABLE[ch]);
    } else if (/[a-zA-Z0-9]/.test(ch)) {
      result.push(ch.toLowerCase());
    } else if (/\s/.test(ch)) {
      // 空格透传
      result.push(' ');
    } else {
      // 表外中文/特殊字符 → 跳过 (不参与匹配)
    }
  }
  return result;
}

/**
 * 判断字符串是否纯 ASCII (用于判断"用户在用拼音/英文搜中文")。
 */
export function isPureAscii(s: string): boolean {
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c > 127) return false;
  }
  return true;
}

/**
 * 判断字符串是否含中文。
 */
export function isLikelyChinese(s: string): boolean {
  return /[\u4e00-\u9fff]/.test(s);
}

/**
 * 拼音模糊匹配。
 *
 * @param label 被匹配的中文 label (可含英文/数字)
 * @param query 用户输入 (拼音首字母 / 全拼前缀 / 混合)
 * @returns 是否匹配
 *
 * @example
 *   matchPinyin('比特币 BTC', 'btb')  → true
 *   matchPinyin('比特币', 'bite')     → true
 *   matchPinyin('K线图', 'kxiantu')   → true
 */
export function matchPinyin(label: string, query: string): boolean {
  if (!query) return true;
  if (!isPureAscii(query)) return false; // 中文查询走原 substring 匹配

  const q = query.toLowerCase().replace(/\s+/g, '');
  const pinyin = toPinyin(label);

  // 策略 1: 首字母连接
  const firstLetters = pinyin
    .map((p) => p.charAt(0))
    .join('')
    .toLowerCase();
  if (firstLetters.includes(q)) return true;

  // 策略 2: 全拼连接 (无空格)
  const fullPinyin = pinyin.join('').toLowerCase().replace(/\s+/g, '');
  if (fullPinyin.includes(q)) return true;

  // 策略 3: 模糊 - q 的每个字符按顺序在 fullPinyin 中出现
  let qi = 0;
  for (let i = 0; i < fullPinyin.length && qi < q.length; i++) {
    if (fullPinyin[i] === q[qi]) qi++;
  }
  if (qi === q.length && q.length >= 3) return true;

  return false;
}
