/**
 * ODocumentReader — 文档阅读器 + 中英对照
 *
 * 消费 API v1.0 §1.1 Substrate + §1.3 Derivative。
 *
 * 设计:
 *   - 显示 substrate 元信息(title / medium / created_at / pinned)
 *   - 主体显示 derivatives.content(markdown / plaintext)
 *   - 模式切换:
 *     - "原文":kind='markdown' or 'plaintext'
 *     - "对照":左右两栏(原文 + translation_*)
 *     - "译文":只显示 translation_*
 *   - 多个 translation 时(不同 lang)允许切换 target_lang
 *   - pin/unpin 按钮(可选)
 */
import {
  forwardRef,
  useCallback,
  useMemo,
  useState,
} from 'react';
import { cn } from '../../lib/cn';
import type { Substrate, Derivative } from '../../types/stratum';
import type { OBlockBaseProps } from '../../lib/types';

export type ReaderMode = 'original' | 'bilingual' | 'translation';

export interface ODocumentReaderProps extends Omit<OBlockBaseProps, 'variant'> {
  substrate: Substrate;
  /** 该 substrate 的所有 derivative。 */
  derivatives: Derivative[];
  /** 初始模式(默认 'original')。 */
  defaultMode?: ReaderMode;
  /** 切换 pin 状态。 */
  onTogglePin?: (substrate: Substrate, newPinned: boolean) => void;
}

function extractTargetLang(kind: string): string | null {
  const prefix = 'translation_';
  return kind.startsWith(prefix) ? kind.substring(prefix.length) : null;
}

export const ODocumentReader = forwardRef<HTMLDivElement, ODocumentReaderProps>(
  function ODocumentReader(
    {
      substrate,
      derivatives,
      defaultMode = 'original',
      onTogglePin,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const [mode, setMode] = useState<ReaderMode>(defaultMode);

    // 原文 derivative(markdown 优先,fallback plaintext)
    const original = useMemo(() => {
      return (
        derivatives.find((d) => d.kind === 'markdown') ??
        derivatives.find((d) => d.kind === 'plaintext') ??
        null
      );
    }, [derivatives]);

    // 所有 translations
    const translations = useMemo(() => {
      return derivatives.filter((d) => d.kind.startsWith('translation_'));
    }, [derivatives]);

    const [activeLang, setActiveLang] = useState<string | null>(() => {
      const first = translations[0];
      return first ? extractTargetLang(first.kind) : null;
    });

    const activeTranslation = useMemo(() => {
      if (!activeLang) return null;
      return translations.find((d) => extractTargetLang(d.kind) === activeLang) ?? null;
    }, [translations, activeLang]);

    const handleTogglePin = useCallback(() => {
      onTogglePin?.(substrate, !substrate.is_pinned);
    }, [onTogglePin, substrate]);

    const hasTranslation = translations.length > 0;

    return (
      <article ref={ref} className={cn('flex flex-col gap-3 w-full', className)}>
        <header className="flex items-start justify-between gap-3 flex-wrap">
          <div className="flex flex-col gap-1 min-w-0 flex-1">
            <h2 className="text-base font-bold text-[color:var(--foreground)] flex items-center gap-2 tracking-[-0.01em]">
              {substrate.is_pinned && (
                <span aria-label="已 Pin" title="已 Pin">
                  📌
                </span>
              )}
              <span className="truncate">{substrate.title || substrate.id}</span>
            </h2>
            <div className="flex items-center gap-2 text-xs text-[color:var(--text-muted)] font-mono flex-wrap">
              {substrate.meta_json?.medium && <span>{substrate.meta_json.medium}</span>}
              {substrate.language && <span>· {substrate.language}</span>}
              <span>· {new Date(substrate.created_at).toLocaleDateString()}</span>
            </div>
          </div>
          <div className="flex items-center gap-1.5">
            {onTogglePin && (
              <button
                type="button"
                onClick={handleTogglePin}
                aria-pressed={substrate.is_pinned}
                className={cn(
                  'px-2 py-1 rounded text-xs @container',
                  substrate.is_pinned
                    ? 'bg-primary/20 text-primary'
                    : 'bg-muted text-[color:var(--foreground)]',
                  'hover:opacity-80 transition-opacity'
                )}
              >
                {substrate.is_pinned ? '已 Pin' : 'Pin'}
              </button>
            )}
          </div>
        </header>

        {hasTranslation && (
          <div
            role="tablist"
            aria-label="阅读模式"
            className="flex gap-1 border-b border-border"
          >
            <button
              type="button"
              role="tab"
              aria-selected={mode === 'original'}
              onClick={() => setMode('original')}
              className={cn(
                'px-3 py-1.5 text-xs rounded-t -mb-px',
                mode === 'original'
                  ? 'bg-card border border-border border-b-[color:var(--card)] text-[color:var(--foreground)]'
                  : 'text-[color:var(--text-muted)] hover:text-[color:var(--foreground)]'
              )}
            >
              原文
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={mode === 'bilingual'}
              onClick={() => setMode('bilingual')}
              className={cn(
                'px-3 py-1.5 text-xs rounded-t -mb-px',
                mode === 'bilingual'
                  ? 'bg-card border border-border border-b-[color:var(--card)] text-[color:var(--foreground)]'
                  : 'text-[color:var(--text-muted)] hover:text-[color:var(--foreground)]'
              )}
            >
              对照
            </button>
            <button
              type="button"
              role="tab"
              aria-selected={mode === 'translation'}
              onClick={() => setMode('translation')}
              className={cn(
                'px-3 py-1.5 text-xs rounded-t -mb-px',
                mode === 'translation'
                  ? 'bg-card border border-border border-b-[color:var(--card)] text-[color:var(--foreground)]'
                  : 'text-[color:var(--text-muted)] hover:text-[color:var(--foreground)]'
              )}
            >
              译文
            </button>
          </div>
        )}

        {hasTranslation && translations.length > 1 && mode !== 'original' && (
          <div className="flex gap-1 items-center">
            <span className="text-[10px] text-[color:var(--text-muted)] uppercase font-mono">
              语言:
            </span>
            {translations.map((t) => {
              const lang = extractTargetLang(t.kind);
              if (!lang) return null;
              const active = lang === activeLang;
              return (
                <button
                  key={t.id}
                  type="button"
                  onClick={() => setActiveLang(lang)}
                  className={cn(
                    'px-2 py-0.5 rounded text-[10px] font-mono',
                    active
                      ? 'bg-primary/20 text-primary'
                      : 'bg-muted text-[color:var(--text-muted)] hover:text-[color:var(--foreground)]'
                  )}
                >
                  {lang}
                </button>
              );
            })}
          </div>
        )}

        <div className={cn('flex gap-4', mode === 'bilingual' ? 'flex-row' : 'flex-col')}>
          {(mode === 'original' || mode === 'bilingual') && (
            <section
              className={cn(
                'flex-1 px-3 py-2 rounded-md',
                'bg-card border border-border',
                mode === 'bilingual' && 'min-w-0'
              )}
              aria-label="原文"
            >
              {mode === 'bilingual' && (
                <div className="text-[10px] uppercase tracking-[0.04em] text-[color:var(--text-muted)] mb-1 font-mono">
                  原文
                </div>
              )}
              <div className="text-sm leading-relaxed whitespace-pre-wrap text-[color:var(--foreground)]">
                {original?.content ?? <span className="italic text-[color:var(--text-muted)]">无原文内容</span>}
              </div>
            </section>
          )}
          {(mode === 'translation' || mode === 'bilingual') && (
            <section
              className={cn(
                'flex-1 px-3 py-2 rounded-md',
                'bg-card border border-border',
                mode === 'bilingual' && 'min-w-0'
              )}
              aria-label="译文"
            >
              {mode === 'bilingual' && (
                <div className="text-[10px] uppercase tracking-[0.04em] text-[color:var(--text-muted)] mb-1 font-mono">
                  译文 ({activeLang ?? '?'})
                </div>
              )}
              <div className="text-sm leading-relaxed whitespace-pre-wrap text-[color:var(--foreground)]">
                {activeTranslation?.content ?? (
                  <span className="italic text-[color:var(--text-muted)]">无译文</span>
                )}
              </div>
            </section>
          )}
        </div>
      </article>
    );
  }
);

ODocumentReader.displayName = 'ODocumentReader';
