/**
 * OGradientKPICard - 视觉增强版 KPI 卡片 (类 2)。
 *
 * 三大特色:
 *   1. 运动渐变边框 (内置 OGradientFrame)
 *   2. 数字 count-up 动画 (useCountUp)
 *   3. hover 时 glow 效果
 *
 * SPEC §3.5 类 2,在 reduced-motion 下:
 *   - 边框停止旋转 (但保留渐变)
 *   - 数字直接显示终值
 *   - glow hover 仅保留颜色 (无 transition)
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, useState } from 'react';
import { motion } from 'motion/react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import { useCountUp } from '../../hooks/useCountUp';
import type { OBlockDataProps } from '../../lib/types';
import { OGradientFrame } from '../../frames/OGradientFrame';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import type { OKPIData } from '../OKPICard';

const cardVariants = cva('relative @container flex flex-col gap-1', {
  variants: {
    variant: {
      standard: 'p-4',
      compact: 'p-2',
      hero: 'p-8 gap-3',
    },
  },
  defaultVariants: { variant: 'standard' },
});

type CardVariantProps = VariantProps<typeof cardVariants>;

export interface OGradientKPICardProps extends OBlockDataProps<OKPIData>, CardVariantProps {
  /** 边框旋转速度。 */
  borderSpeed?: 'slow' | 'normal' | 'fast';
  /** 边框粗细 (px)。 */
  borderThickness?: number;
  /** count-up 动画时长 (ms)。 */
  countDuration?: number;
}

function IndicatorArrow({ direction }: { direction: 'up' | 'down' | 'neutral' }) {
  if (direction === 'neutral') return <span className="text-muted-foreground" aria-hidden></span>;
  return (
    <span
      className={direction === 'up' ? 'text-success' : 'text-destructive'}
      aria-hidden="true"
    >
      {direction === 'up' ? '▲' : '▼'}
    </span>
  );
}

function AnimatedPrimary({ value, duration }: { value: number | string; duration: number }) {
  // useCountUp 必须无条件调用(Hook Rules)
  // 字符串场景下 value 转 0,但通过下方 isString 判断决定显示什么
  const isString = typeof value === 'string';
  const { display } = useCountUp(isString ? 0 : value, {
    duration,
    format: (v) => v.toLocaleString(undefined, { maximumFractionDigits: 2 }),
  });
  if (isString) return <span>{value}</span>;
  return <span>{display}</span>;
}

export const OGradientKPICard = forwardRef<HTMLDivElement, OGradientKPICardProps>(
  function OGradientKPICard(
    {
      data,
      loading,
      error,
      empty,
      variant = 'standard',
      borderSpeed = 'normal',
      borderThickness = 2,
      countDuration = 1200,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const state = resolveBlockState({ data, loading, error, empty });
    const reduced = useReducedMotion();
    const [hover, setHover] = useState(false);

    if (state === 'loading')
      return (
        <OGradientFrame thickness={borderThickness} speed={borderSpeed} className={className}>
          <div className={cn(cardVariants({ variant }), 'min-w-48')}>
            <OLoadingState rows={2} rowHeight="1rem" />
          </div>
        </OGradientFrame>
      );
    if (state === 'error')
      return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data)
      return (
        <OEmptyState
          ref={ref}
          title={data?.label ?? 'No data'}
          variant="minimal"
          className={className}
        />
      );

    return (
      <OGradientFrame
        ref={ref}
        thickness={borderThickness}
        speed={borderSpeed}
        className={className}
      >
        <motion.div
          className={cn(cardVariants({ variant }), 'min-w-48 rounded-md')}
          onHoverStart={() => setHover(true)}
          onHoverEnd={() => setHover(false)}
          animate={
            reduced
              ? {}
              : {
                  boxShadow: hover
                    ? '0 0 32px color-mix(in oklch, var(--primary) 40%, transparent)'
                    : '0 0 0px color-mix(in oklch, var(--primary) 0%, transparent)',
                }
          }
          transition={{ duration: 0.3 }}
          data-indicator={data.indicator}
        >
          <div className="text-[0.625rem] @[200px]:text-[0.6875rem] text-muted-foreground font-semibold uppercase tracking-[0.04em]">
            {data.label}
          </div>
          <div className="text-3xl @[200px]:text-4xl @[400px]:text-5xl font-extrabold tabular-nums tracking-[-0.03em] leading-none" style={{fontFamily:'var(--font-display, inherit)', fontWeight:'var(--weight-display, 780)'}}>
            <AnimatedPrimary value={data.primary} duration={countDuration} />
          </div>
          {data.indicator || typeof data.changePercent === 'number' || data.secondary ? (
            <div className="text-xs @[200px]:text-sm text-muted-foreground flex items-center gap-2 mt-1">
              {data.indicator ? <IndicatorArrow direction={data.indicator} /> : null}
              {typeof data.changePercent === 'number' ? (
                <span
                  className={
                    data.indicator === 'up'
                      ? 'text-success font-medium'
                      : data.indicator === 'down'
                        ? 'text-destructive font-medium'
                        : ''
                  }
                >
                  {data.changePercent >= 0 ? '+' : ''}
                  {data.changePercent.toFixed(2)}%
                </span>
              ) : null}
              {data.secondary ? <span className="opacity-70">{data.secondary}</span> : null}
            </div>
          ) : null}
        </motion.div>
      </OGradientFrame>
    );
  }
);

OGradientKPICard.displayName = 'OGradientKPICard';
