/**
 * OScheduledJobsManager — Stratum 定时任务管理
 *
 * 消费 API v1.0 §1.8/5.2/5.3:
 *   - ScheduledJob 列表(builtin + 用户自配)
 *   - cron_expression / enabled / timezone / notify_on_* 显示
 *   - 切换 enabled / 编辑 cron / 删除(回调 props)
 *
 * v1.0 限制(API §5.5):
 *   - next_run_at / last_run_at 不在 DB
 *   - 前端用 cron-parser 计算 next_run_at(由消费方传入)
 *
 * 设计:
 *   - 列表渲染,builtin job 不可删除(is_builtin 推断:由消费方标记,这里 prop)
 *   - 切换 enabled 触发 onToggleEnabled
 *   - 编辑 cron 触发 onEditCron(简化,只显示当前)
 *   - 删除非 builtin job 触发 onDelete
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { ScheduledJob } from '../../types/stratum';
import type { OBlockBaseProps } from '../../lib/types';

export interface ScheduledJobWithStatus extends ScheduledJob {
  /** 是否 builtin job(builtin 不可删,只能切 enabled)。 */
  is_builtin?: boolean;
  /** 前端用 cron-parser 计算的下次执行时间(ISO 8601)。 */
  next_run_at?: string | null;
  /** scheduled_job_runs 最新一条的 started_at。 */
  last_run_at?: string | null;
  /** scheduled_job_runs 最新一条的 status。 */
  last_status?: 'running' | 'completed' | 'failed' | 'timeout' | null;
}

export interface OScheduledJobsManagerProps extends Omit<OBlockBaseProps, 'variant'> {
  jobs: ScheduledJobWithStatus[];
  onToggleEnabled?: (job: ScheduledJobWithStatus, newEnabled: boolean) => void;
  onEditCron?: (job: ScheduledJobWithStatus) => void;
  onDelete?: (job: ScheduledJobWithStatus) => void;
  onRunNow?: (job: ScheduledJobWithStatus) => void;
}

const AGENT_ICON: Record<string, string> = {
  knowledge_curator: '📥',
  reading_companion: '💬',
  daily_digest: '📰',
  translation_worker: '🌐',
  lint_bot: '🩺',
  audio_generator: '🔊',
};

const STATUS_COLOR: Record<string, string> = {
  running: 'oklch(0.55 0.13 80)',
  completed: 'oklch(0.55 0.13 160)',
  failed: 'oklch(0.55 0.18 30)',
  timeout: 'oklch(0.55 0.13 30)',
};

export const OScheduledJobsManager = forwardRef<HTMLDivElement, OScheduledJobsManagerProps>(
  function OScheduledJobsManager(
    { jobs, onToggleEnabled, onEditCron, onDelete, onRunNow, className, theme: _t, size: _s },
    ref
  ) {
    if (jobs.length === 0) {
      return (
        <div
          ref={ref}
          className={cn(
            'px-4 py-8 text-center text-sm text-[color:var(--text-muted)] @container',
            'border border-dashed border-border rounded-lg',
            className
          )}
        >
          暂无定时任务
        </div>
      );
    }

    return (
      <div ref={ref} className={cn('flex flex-col gap-2', className)}>
        <ul className="flex flex-col gap-2 list-none p-0 m-0" aria-label="定时任务列表">
          {jobs.map((job) => (
            <li
              key={job.id}
              className={cn(
                'flex flex-col gap-2 px-3 py-2 rounded-md',
                'bg-card border border-border'
              )}
            >
              <div className="flex items-center gap-2 flex-wrap">
                <span aria-hidden="true">{AGENT_ICON[job.agent_name] ?? '⚙️'}</span>
                <span className="font-medium text-sm text-[color:var(--foreground)]">
                  {job.name}
                </span>
                {job.is_builtin && (
                  <span
                    className={cn(
                      'px-1.5 py-0.5 text-[10px] rounded font-mono',
                      'bg-muted text-[color:var(--text-muted)]'
                    )}
                  >
                    builtin
                  </span>
                )}
                <span className="text-xs text-[color:var(--text-muted)] font-mono">
                  {job.agent_name}
                </span>
                {job.last_status && (
                  <span
                    className="px-1.5 py-0.5 text-[10px] rounded font-mono"
                    style={{
                      backgroundColor: `${STATUS_COLOR[job.last_status] ?? 'oklch(0.55 0.13 80)'}33`,
                      color: STATUS_COLOR[job.last_status] ?? 'oklch(0.55 0.13 80)',
                    }}
                  >
                    {job.last_status}
                  </span>
                )}
              </div>

              <div className="flex items-center gap-3 text-xs text-[color:var(--text-muted)] font-mono flex-wrap">
                <span title="cron 表达式">⏱ {job.cron_expression}</span>
                <span title="时区">🌐 {job.timezone}</span>
                {job.next_run_at && (
                  <span title="下次执行">→ {new Date(job.next_run_at).toLocaleString()}</span>
                )}
                {job.last_run_at && (
                  <span title="上次执行">← {new Date(job.last_run_at).toLocaleString()}</span>
                )}
              </div>

              <div className="flex items-center gap-2 flex-wrap">
                <label className="flex items-center gap-1.5 cursor-pointer text-xs">
                  <input
                    type="checkbox"
                    checked={job.enabled}
                    onChange={(e) => onToggleEnabled?.(job, e.target.checked)}
                    className="cursor-pointer"
                    aria-label={`启用 ${job.name}`}
                  />
                  <span className="text-[color:var(--foreground)]">启用</span>
                </label>
                {onRunNow && (
                  <button
                    type="button"
                    onClick={() => onRunNow(job)}
                    className={cn(
                      'px-2 py-1 rounded text-xs',
                      'bg-primary/10 text-primary',
                      'hover:bg-primary/20 transition-colors'
                    )}
                  >
                    立即运行
                  </button>
                )}
                {onEditCron && (
                  <button
                    type="button"
                    onClick={() => onEditCron(job)}
                    className={cn(
                      'px-2 py-1 rounded text-xs',
                      'bg-muted text-[color:var(--foreground)]',
                      'hover:opacity-80 transition-opacity'
                    )}
                  >
                    编辑
                  </button>
                )}
                {onDelete && !job.is_builtin && (
                  <button
                    type="button"
                    onClick={() => onDelete(job)}
                    className={cn(
                      'px-2 py-1 rounded text-xs',
                      'bg-destructive/10 text-destructive',
                      'hover:bg-destructive/20 transition-colors'
                    )}
                  >
                    删除
                  </button>
                )}
              </div>
            </li>
          ))}
        </ul>
      </div>
    );
  }
);

OScheduledJobsManager.displayName = 'OScheduledJobsManager';
