/**
 * OAudioWaveform - 音频波形可视化 + 播放器。
 *
 * 数据契约: { src, peaks? }
 *   - peaks 可由外部预计算(避免每次解码),Block 直接画
 *   - 没 peaks 时,内部用 Web Audio API 实时解码 (lazy)
 *
 * Tide 量化项目可用 (e.g. 复盘音频笔记)。
 */
'use client';

import { forwardRef, useEffect, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OAudioWaveformProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  src: string;
  /** 预计算的峰值数组 (0-1)。优先使用,避免解码。 */
  peaks?: number[];
  /** 波形条目标数量(自动重采样)。 */
  bars?: number;
  /** 高度 (px)。 */
  height?: number;
  /** 视觉颜色。 */
  color?: 'primary' | 'success' | 'warning';
}

const COLOR_VAR: Record<string, string> = {
  primary: '--primary',
  success: '--success',
  warning: '--warning',
};

function downsample(samples: Float32Array, bars: number): number[] {
  const step = Math.floor(samples.length / bars);
  const out: number[] = [];
  for (let i = 0; i < bars; i++) {
    const start = i * step;
    const end = Math.min(start + step, samples.length);
    let max = 0;
    for (let j = start; j < end; j++) {
      const v = Math.abs(samples[j] ?? 0);
      if (v > max) max = v;
    }
    out.push(max);
  }
  // 归一化
  const max = Math.max(...out, 0.0001);
  return out.map((v) => v / max);
}

export const OAudioWaveform = forwardRef<HTMLDivElement, OAudioWaveformProps>(
  function OAudioWaveform(
    { src, peaks: initialPeaks, bars = 80, height = 64, color = 'primary', className, theme: _t },
    ref
  ) {
    const [peaks, setPeaks] = useState<number[] | null>(initialPeaks ?? null);
    const [time, setTime] = useState(0);
    const [duration, setDuration] = useState(0);
    const [playing, setPlaying] = useState(false);
    const audioRef = useRef<HTMLAudioElement | null>(null);

    // 解码生成 peaks (如果没传)
    useEffect(() => {
      if (initialPeaks || typeof window === 'undefined') return;
      let cancelled = false;
      (async () => {
        try {
          const resp = await fetch(src);
          const buf = await resp.arrayBuffer();
          const AudioCtx = (window as { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext }).AudioContext ?? (window as { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
          if (!AudioCtx) return;
          const ctx = new AudioCtx();
          const audio = await ctx.decodeAudioData(buf);
          const data = audio.getChannelData(0);
          if (!cancelled) setPeaks(downsample(data, bars));
          ctx.close();
        } catch (e) {
          console.warn('[OAudioWaveform] decode failed', e);
        }
      })();
      return () => {
        cancelled = true;
      };
    }, [src, bars, initialPeaks]);

    function togglePlay() {
      const a = audioRef.current;
      if (!a) return;
      if (a.paused) a.play();
      else a.pause();
    }

    function seekToBar(idx: number) {
      const a = audioRef.current;
      if (!a || !peaks) return;
      a.currentTime = (idx / peaks.length) * duration;
    }

    const progressBar = peaks ? Math.floor((time / Math.max(duration, 0.001)) * peaks.length) : 0;

    return (
      <div
        ref={ref}
        className={cn('flex items-center gap-3 p-3 rounded-md bg-card border border-border @container', className)}
      >
        <button
          type="button"
          onClick={togglePlay}
          aria-label={playing ? 'Pause' : 'Play'}
          className="w-10 h-10 rounded-full bg-primary text-primary-foreground flex items-center justify-center hover:opacity-90 transition-opacity shrink-0"
        >
          {playing ? (
            <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor">
              <rect x="6" y="4" width="4" height="16" />
              <rect x="14" y="4" width="4" height="16" />
            </svg>
          ) : (
            <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor">
              <polygon points="5 3 19 12 5 21 5 3" />
            </svg>
          )}
        </button>

        <div className="flex-1 min-w-0">
          <div
            className="flex items-end gap-px h-full"
            style={{ height }}
            role="slider"
            aria-label="Audio progress"
            aria-valuemin={0}
            aria-valuemax={duration}
            aria-valuenow={time}
          >
            {peaks ? (
              peaks.map((p, i) => (
                <button
                  key={i}
                  type="button"
                  onClick={() => seekToBar(i)}
                  aria-label={`Seek to ${Math.round((i / peaks.length) * duration)}s`}
                  className="flex-1 transition-colors"
                  style={{
                    height: `${p * 100}%`,
                    minHeight: 2,
                    backgroundColor:
                      i <= progressBar
                        ? `var(${COLOR_VAR[color]})`
                        : `color-mix(in oklch, var(${COLOR_VAR[color]}) 25%, transparent)`,
                  }}
                />
              ))
            ) : (
              <div className="w-full h-full bg-muted/50 rounded animate-pulse" />
            )}
          </div>
          <div className="flex justify-between text-xs text-muted-foreground mt-1 tabular-nums">
            <span>{Math.floor(time)}s</span>
            <span>{Math.floor(duration)}s</span>
          </div>
        </div>

        <audio
          ref={audioRef}
          src={src}
          onPlay={() => setPlaying(true)}
          onPause={() => setPlaying(false)}
          onTimeUpdate={() => setTime(audioRef.current?.currentTime ?? 0)}
          onLoadedMetadata={() => setDuration(audioRef.current?.duration ?? 0)}
          onEnded={() => setPlaying(false)}
        />
      </div>
    );
  }
);

OAudioWaveform.displayName = 'OAudioWaveform';
