'use client';
import { forwardRef, useState, type InputHTMLAttributes } from 'react';
import { cn } from '../../lib/cn';
import { checkboxRecipe, type CheckboxRecipeProps } from '../../recipes';

export interface OCheckboxProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'size'|'type'>,
    CheckboxRecipeProps {
  label?: string;
}

export const OCheckbox = forwardRef<HTMLInputElement, OCheckboxProps>(
  function OCheckbox({ shape, size, label, checked, defaultChecked, onChange, className, disabled, id, ...rest }, ref) {
    const [internal, setInternal] = useState(!!defaultChecked);
    const isChecked = checked !== undefined ? checked : internal;
    const cbId = id || `cb-${Math.random().toString(36).slice(2,8)}`;
    return (
      <label htmlFor={cbId} className={cn('inline-flex items-center gap-2 cursor-pointer', disabled && 'cursor-not-allowed', className)}>
        <span className="relative inline-flex">
          <input
            ref={ref} id={cbId} type="checkbox" className="sr-only peer"
            checked={isChecked} disabled={disabled}
            onChange={e => { if (checked === undefined) setInternal(e.target.checked); onChange?.(e); }}
            {...rest}
          />
          <span data-checked={isChecked} className={cn(checkboxRecipe({ shape, size }), 'flex items-center justify-center')}>
            {isChecked && (
              <svg className="size-3.5" viewBox="0 0 16 16" fill="none" aria-hidden>
                <path d="M3.5 8.5l3 3 6-7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              </svg>
            )}
          </span>
        </span>
        {label && <span className="text-[length:var(--text-sm)] select-none">{label}</span>}
      </label>
    );
  }
);
OCheckbox.displayName = 'OCheckbox';
