/**
 * OLiquidationLine - 强平价位线 (合约救命标记)。
 *
 * 叠加在 K 线图上的"强平/入场/止盈止损"价位线 overlay.
 * 散户合约最痛的事:不知道自己强平价多少,亏完才发现。
 * Helios 把强平价**永久可视化**,可以救命。
 *
 * 用法 (叠加在 OCandlestickChart 上):
 *   <div className="relative">
 *     <OCandlestickChart data={...} />
 *     <OLiquidationLine
 *       className="absolute inset-0 pointer-events-none"
 *       data={{
 *         positions: [
 *           { side: 'LONG', entryPrice: 67000, liquidationPrice: 60000, leverage: 10 },
 *         ],
 *         priceRange: { min: 50000, max: 80000 },
 *         currentPrice: 67500,
 *       }}
 *     />
 *   </div>
 *
 * 也可独立显示("当前持仓的强平价") 卡片式:
 *   <OLiquidationLine data={...} variant="card" />
 */

'use client';

import { forwardRef, useEffect, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { useFastData } from '../../providers/FastDataProvider';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';

export interface OLiquidationPosition {
  side: 'LONG' | 'SHORT';
  entryPrice: number;
  liquidationPrice: number;
  leverage: number;
  /** 持仓数量 (用于显示). */
  amount?: number;
  /** 止盈价 (可选). */
  tp?: number;
  /** 止损价 (可选). */
  sl?: number;
}

export interface OLiquidationLineData {
  positions: OLiquidationPosition[];
  /** 价格区间 (用于线在 overlay 中的 y 位置). */
  priceRange?: { min: number; max: number };
  /** 当前 mark price. */
  currentPrice?: number;
}

export interface OLiquidationLineProps
  extends OBlockDataProps<OLiquidationLineData>,
    Pick<TerminalBlockProps, 'channel' | 'dataDelay' | 'regulation'> {
  /** overlay = 叠加在父容器上的横线 (默认). card = 独立卡片显示文字. */
  variant?: 'overlay' | 'card';
  /** 危险距离阈值 (% of currentPrice). 默认 5%,小于此距离时高亮警告. */
  dangerThreshold?: number;
}

function calcDanger(current: number, liq: number, side: 'LONG' | 'SHORT'): number {
  // 返回距离百分比 (正数 = 安全距离 %, 负数 = 已经过强平价)
  if (side === 'LONG') {
    return ((current - liq) / current) * 100;
  } else {
    return ((liq - current) / current) * 100;
  }
}

export const OLiquidationLine = forwardRef<HTMLDivElement, OLiquidationLineProps>(
  function OLiquidationLine(
    {
      data: dataProp,
      loading,
      error,
      empty,
      channel,
      variant = 'overlay',
      dangerThreshold = 5,
      dataDelay = 0,
      regulation: _r,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OLiquidationLineData | null>(null);
    useEffect(() => {
      if (!channel || !fastData) return;
      return fastData.subscribe<OLiquidationLineData>(channel, setChannelData);
    }, [channel, fastData]);

    const data = channel ? channelData : (dataProp ?? null);
    const state = resolveBlockState({ data, loading, error, empty });

    const canvasRef = useRef<HTMLCanvasElement | null>(null);

    // Canvas 渲染 (overlay 模式)
    useEffect(() => {
      if (variant !== 'overlay' || state !== 'ready' || !data) return;
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      function draw() {
        if (!canvas || !data?.priceRange) return;
        const parent = canvas.parentElement!;
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        const w = parent.clientWidth;
        const h = parent.clientHeight;
        canvas.width = w * dpr;
        canvas.height = h * dpr;
        canvas.style.width = `${w}px`;
        canvas.style.height = `${h}px`;
        ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx!.clearRect(0, 0, w, h);

        const styles = getComputedStyle(document.documentElement);
        const upColor = styles.getPropertyValue('--quote-up').trim() || styles.getPropertyValue('--success').trim();
        const downColor = styles.getPropertyValue('--quote-down').trim() || styles.getPropertyValue('--destructive').trim();
        const warnColor = styles.getPropertyValue('--warning').trim();
        const textColor = styles.getPropertyValue('--foreground').trim();

        const range = data.priceRange.max - data.priceRange.min;
        if (range <= 0) return;

        const priceToY = (p: number) =>
          h - ((p - data.priceRange!.min) / range) * h;

        for (const pos of data.positions) {
          const lineColor = pos.side === 'LONG' ? downColor : upColor;
          // Long 仓的强平价是下方 (跌穿就爆);Short 仓的强平价是上方
          const y = priceToY(pos.liquidationPrice);
          if (y < 0 || y > h) continue;

          // 强平线 (虚线)
          ctx!.strokeStyle = lineColor;
          ctx!.lineWidth = 1.5;
          ctx!.setLineDash([6, 4]);
          ctx!.beginPath();
          ctx!.moveTo(0, y);
          ctx!.lineTo(w, y);
          ctx!.stroke();
          ctx!.setLineDash([]);

          // 标签
          ctx!.fillStyle = lineColor;
          ctx!.fillRect(w - 110, y - 9, 105, 18);
          ctx!.fillStyle = '#fff';
          ctx!.font = 'bold 10px ui-monospace';
          ctx!.textAlign = 'left';
          ctx!.textBaseline = 'middle';
          ctx!.fillText(
            `强平 ${pos.liquidationPrice.toFixed(2)}`,
            w - 105,
            y
          );

          // 入场价线 (实线)
          const entryY = priceToY(pos.entryPrice);
          if (entryY >= 0 && entryY <= h) {
            ctx!.strokeStyle = textColor;
            ctx!.lineWidth = 1;
            ctx!.globalAlpha = 0.5;
            ctx!.beginPath();
            ctx!.moveTo(0, entryY);
            ctx!.lineTo(w, entryY);
            ctx!.stroke();
            ctx!.globalAlpha = 1;
            ctx!.fillStyle = textColor;
            ctx!.font = '10px ui-monospace';
            ctx!.fillText(
              `${pos.side === 'LONG' ? '多' : '空'} ${pos.entryPrice.toFixed(2)} (${pos.leverage}x)`,
              4,
              entryY - 4
            );
          }

          // TP / SL 线
          if (pos.tp) {
            const tpY = priceToY(pos.tp);
            if (tpY >= 0 && tpY <= h) {
              ctx!.strokeStyle = upColor;
              ctx!.lineWidth = 1;
              ctx!.setLineDash([2, 2]);
              ctx!.beginPath();
              ctx!.moveTo(0, tpY);
              ctx!.lineTo(w, tpY);
              ctx!.stroke();
              ctx!.setLineDash([]);
            }
          }
          if (pos.sl) {
            const slY = priceToY(pos.sl);
            if (slY >= 0 && slY <= h) {
              ctx!.strokeStyle = warnColor;
              ctx!.lineWidth = 1;
              ctx!.setLineDash([2, 2]);
              ctx!.beginPath();
              ctx!.moveTo(0, slY);
              ctx!.lineTo(w, slY);
              ctx!.stroke();
              ctx!.setLineDash([]);
            }
          }
        }
      }

      draw();
      const ro = new ResizeObserver(draw);
      if (canvas.parentElement) ro.observe(canvas.parentElement);
      return () => ro.disconnect();
    }, [data, state, variant]);

    if (state === 'loading')
      return variant === 'overlay' ? null : (
        <div ref={ref} className={cn('rounded-md border border-border bg-card p-3', className)}>
          <OLoadingState rows={2} rowHeight="1rem" />
        </div>
      );
    if (state === 'error')
      return variant === 'overlay' ? null : <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data || data.positions.length === 0)
      return variant === 'overlay' ? null : null;

    if (variant === 'overlay') {
      return (
        <div ref={ref} className={cn('pointer-events-none', className)}>
          <canvas ref={canvasRef} aria-hidden="true" className="w-full h-full" />
        </div>
      );
    }

    // Card 模式 - 列出所有持仓的强平价 + 距离
    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card flex flex-col gap-2 p-3 relative @container',
          className
        )}
        style={{ fontFamily: 'var(--font-ui)' }}
      >
        {dataDelay > 0 ? (
          <div className="absolute top-1 right-2 text-[10px] text-[color:var(--alert-warn)] font-mono pointer-events-none">
            延时 {dataDelay}m
          </div>
        ) : null}
        <div className="text-[10px] text-[color:var(--text-muted)] uppercase tracking-[0.04em]">
          强平价位
        </div>
        {data.positions.map((p, i) => {
          const danger =
            typeof data.currentPrice === 'number'
              ? calcDanger(data.currentPrice, p.liquidationPrice, p.side)
              : null;
          const isDangerous = danger != null && danger < dangerThreshold;
          const sideColor = p.side === 'LONG' ? 'var(--quote-up)' : 'var(--quote-down)';
          return (
            <div
              key={i}
              className="flex items-center justify-between p-2 rounded bg-muted/30 border border-border/30"
              style={{
                borderColor: isDangerous ? 'var(--quote-down)' : undefined,
              }}
            >
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2 text-xs">
                  <span style={{ color: sideColor, fontWeight: 600 }}>
                    {p.side === 'LONG' ? '多' : '空'} {p.leverage}x
                  </span>
                  {p.amount != null ? (
                    <span className="text-[color:var(--text-muted)] tabular-nums font-mono">
                      {p.amount}
                    </span>
                  ) : null}
                </div>
                <div className="text-[10px] text-[color:var(--text-muted)] tabular-nums font-mono mt-0.5">
                  入场 {p.entryPrice.toFixed(2)} → 强平 {p.liquidationPrice.toFixed(2)}
                </div>
              </div>
              {danger != null ? (
                <div
                  className="ml-3 tabular-nums font-mono text-xs text-right shrink-0"
                  style={{
                    color: isDangerous ? 'var(--quote-down)' : 'var(--muted-foreground)',
                  }}
                >
                  {isDangerous ? '⚠ ' : ''}
                  距强平 {Math.abs(danger).toFixed(2)}%
                </div>
              ) : null}
            </div>
          );
        })}
      </div>
    );
  }
);

OLiquidationLine.displayName = 'OLiquidationLine';
