/**
 * Tide v4 共享类型
 *
 * 来源:OUI Wave 1-3 需求文档(2026-05-24)
 * 用于 31 个 Tide OUI 元素的 props / data shape。
 */

// ── Regime ───────────────────────────────────────────────────

/**
 * 7 个 Regime 状态(Domain 01)。
 *
 * 注:helios 用英文 key,渲染时通过 REGIME_LABEL 显示中文。
 */
export type RegimeState =
  | 'ice'        // 冰点
  | 'panic'      // 恐慌
  | 'divergent'  // 分歧
  | 'hesitant'   // 犹豫
  | 'cautious'   // 谨慎
  | 'active'     // 积极
  | 'mania';     // 狂热

export const REGIME_LABEL: Record<RegimeState, string> = {
  ice: '冰点',
  panic: '恐慌',
  divergent: '分歧',
  hesitant: '犹豫',
  cautious: '谨慎',
  active: '积极',
  mania: '狂热',
};

export const REGIME_COLOR_VAR: Record<RegimeState, string> = {
  ice: 'var(--regime-ice)',
  panic: 'var(--regime-panic)',
  divergent: 'var(--regime-divergent)',
  hesitant: 'var(--regime-hesitant)',
  cautious: 'var(--regime-cautious)',
  active: 'var(--regime-active)',
  mania: 'var(--regime-mania)',
};

// ── Workspace ────────────────────────────────────────────────

export type WorkspaceLayoutType = 'default' | 'trading' | 'monitor' | 'custom';

export interface GridPosition {
  row: number;
  col: number;
  rowSpan?: number;
  colSpan?: number;
}

export interface CellAction {
  icon: string;
  label?: string;
  onClick: () => void;
}

// ── Plan(Domain 03)────────────────────────────────────────

export interface PlanData {
  entryRange: { low: number; high: number };
  currentPrice: number;
  takeProfit: number;
  takeProfitPct: number;
  stopLoss: number;
  stopLossPct: number;
  riskRewardRatio: number;
  holdPeriodDays: { min: number; max: number };
  positionPctRange: { min: number; max: number };
  exitTriggers: string[];
  warnings: string[];
  regimeContext: string;
  isCustom: boolean;
  llmExplanation?: string;
}

// ── Symbol detail(Domain 04)────────────────────────────────

export interface SymbolTag {
  label: string;
  variant?: 'default' | 'leader';
}

export interface SymbolMeta {
  city?: string;
  industryLv3?: string;
  marketCap?: number;
  freeFloatPct?: number;
  isHkConnect?: boolean;
  hkConnectPct?: number;
}

export interface KlineData {
  date: string | Date;
  open: number;
  close: number;
  high: number;
  low: number;
  volume: number;
}

export type TimeframeOption = '5min' | '15min' | '60min' | '日' | '周' | '月' | '1min';
