/**
 * OStreamingText - 流式输出文字 (打字机效果)。
 *
 * 两种模式:
 *   1. controlled: text 由外部 (Page 推送的 streaming token) 持续追加,Block 跟着重渲染
 *   2. self-typed: 提供完整 text,Block 内部用 setTimeout 打字
 *
 * 在 reduced-motion 下直接显示完整文字。
 *
 * @example
 * // 模式 1: 外部 SSE 推送
 * <OStreamingText text={partialResponse} cursor />
 *
 * // 模式 2: 内部模拟
 * <OStreamingText text="Hello world" mode="self-typed" speed={50} />
 */
'use client';

import { forwardRef, useEffect, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

export interface OStreamingTextProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  text: string;
  /** controlled (默认): 外部累积内容,Block 显示全部
   *  self-typed:           内部模拟打字效果
   */
  mode?: 'controlled' | 'self-typed';
  /** self-typed 模式:每字符延迟 (ms),默认 25。 */
  speed?: number;
  /** 显示光标。 */
  cursor?: boolean;
  /** 完成回调 (self-typed 模式)。 */
  onComplete?: () => void;
  /** HTML tag。 */
  as?: 'span' | 'p' | 'div';
}

export const OStreamingText = forwardRef<HTMLElement, OStreamingTextProps>(function OStreamingText(
  { text, mode = 'controlled', speed = 25, cursor = true, onComplete, as = 'span', className, theme: _t },
  ref
) {
  const reduced = useReducedMotion();
  const [displayed, setDisplayed] = useState(mode === 'controlled' || reduced ? text : '');
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const completedRef = useRef(false);

  useEffect(() => {
    if (mode === 'controlled' || reduced) {
      setDisplayed(text);
      if (!completedRef.current && text.length > 0) {
        completedRef.current = true;
        onComplete?.();
      }
      return;
    }
    // self-typed
    completedRef.current = false;
    setDisplayed('');
    let i = 0;
    function step() {
      if (i >= text.length) {
        if (!completedRef.current) {
          completedRef.current = true;
          onComplete?.();
        }
        return;
      }
      i++;
      setDisplayed(text.slice(0, i));
      timeoutRef.current = setTimeout(step, speed);
    }
    timeoutRef.current = setTimeout(step, speed);
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [text, mode, speed, reduced, onComplete]);

  const Tag = as;
  const showCursor = cursor && !reduced && (mode === 'controlled' ? true : displayed.length < text.length);

  return (
    <Tag ref={ref as never} className={cn('inline @container', className)}>
      {displayed}
      {showCursor ? (
        <span
          aria-hidden="true"
          className="inline-block w-1.5 h-4 align-middle ml-0.5 bg-current animate-pulse"
        />
      ) : null}
    </Tag>
  );
});

OStreamingText.displayName = 'OStreamingText';
