'use client';
import { forwardRef, type ComponentPropsWithoutRef, type ElementRef } from 'react';
import * as TabsPrimitive from '@radix-ui/react-tabs';
import { cn } from '../../lib/cn';
import { tabsListRecipe, tabsTriggerRecipe } from '../../recipes';

export const OTabs = TabsPrimitive.Root;

export const OTabsList = forwardRef<
  ElementRef<typeof TabsPrimitive.List>,
  ComponentPropsWithoutRef<typeof TabsPrimitive.List>
>(function OTabsList({ className, ...props }, ref) {
  return <TabsPrimitive.List ref={ref} className={cn(tabsListRecipe(), className)} {...props} />;
});
OTabsList.displayName = 'OTabsList';

export const OTabsTrigger = forwardRef<
  ElementRef<typeof TabsPrimitive.Trigger>,
  ComponentPropsWithoutRef<typeof TabsPrimitive.Trigger>
>(function OTabsTrigger({ className, ...props }, ref) {
  return <TabsPrimitive.Trigger ref={ref} className={cn(tabsTriggerRecipe(), className)} {...props} />;
});
OTabsTrigger.displayName = 'OTabsTrigger';

export const OTabsContent = forwardRef<
  ElementRef<typeof TabsPrimitive.Content>,
  ComponentPropsWithoutRef<typeof TabsPrimitive.Content>
>(function OTabsContent({ className, ...props }, ref) {
  return <TabsPrimitive.Content ref={ref} className={cn('mt-2 focus-visible:outline-none', className)} {...props} />;
});
OTabsContent.displayName = 'OTabsContent';
