/**
 * ORegimePositionLimitBadge (Tide Wave 2 E5, Atom)
 *
 * 显示当前仓位与 regime 上限的差距,带视觉警告。
 * 来源:OUI_WAVE_2_REQUIREMENTS_v1.0.md §2
 *
 * 主体: 横向 bar + 上限标记 + 可加仓 detail。
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { REGIME_COLOR_VAR, REGIME_LABEL, type RegimeState } from '../../types/tide';
import type { OBlockBaseProps } from '../../lib/types';

export interface ORegimePositionLimitBadgeProps extends Omit<OBlockBaseProps, 'variant'> {
  currentPositionPct: number;
  regimeLimitPct: number;
  regime: RegimeState;
  /** 可加仓金额 元 */
  availableIncreaseAmount?: number;
  badgeVariant?: 'default' | 'compact';
  /** 距上限 N% 内变 warning, 默认 0.10 */
  warningThresholdPct?: number;
}

function formatYuan(amount: number): string {
  if (amount >= 10000) {
    return `${(amount / 10000).toFixed(1)} 万`;
  }
  return `${amount.toFixed(0)}`;
}

export const ORegimePositionLimitBadge = forwardRef<HTMLDivElement, ORegimePositionLimitBadgeProps>(
  function ORegimePositionLimitBadge(
    {
      currentPositionPct,
      regimeLimitPct,
      regime,
      availableIncreaseAmount,
      badgeVariant = 'default',
      warningThresholdPct = 0.1,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const overLimit = currentPositionPct > regimeLimitPct;
    const distanceToLimit = regimeLimitPct - currentPositionPct;
    const nearLimit = !overLimit && distanceToLimit > 0 && distanceToLimit < warningThresholdPct;

    const regimeColor = REGIME_COLOR_VAR[regime];
    const positionPercent = Math.min(currentPositionPct * 100, 100);
    const limitPercent = Math.min(regimeLimitPct * 100, 100);

    let barColor: string;
    if (overLimit) barColor = 'var(--red-up)';
    else if (nearLimit) barColor = 'var(--yellow)';
    else barColor = regimeColor;

    return (
      <div
        ref={ref}
        className={cn(
          'flex flex-col gap-1 @container',
          className
        )}
        style={{ fontFamily: 'var(--font-mono)' }}
      >
        {/* bar */}
        <div
          className="relative h-[18px] rounded"
          style={{ backgroundColor: 'var(--muted)' }}
          role="progressbar"
          aria-valuenow={Math.round(positionPercent)}
          aria-valuemin={0}
          aria-valuemax={Math.round(limitPercent)}
          aria-label={`仓位 ${positionPercent.toFixed(0)}% / 上限 ${limitPercent.toFixed(0)}%`}
        >
          {/* progress */}
          <div
            className={cn(
              'absolute inset-y-0 left-0 rounded transition-all',
              nearLimit && 'animate-pulse'
            )}
            style={{ width: `${positionPercent}%`, backgroundColor: barColor }}
          />
          {/* limit marker (1px white line) */}
          <div
            className="absolute inset-y-0 w-px"
            style={{ left: `${limitPercent}%`, backgroundColor: 'var(--foreground)' }}
            aria-hidden="true"
          />
          {/* center label */}
          <div
            className="absolute inset-0 flex items-center justify-center text-[10px] font-bold"
            style={{ color: 'var(--foreground)', mixBlendMode: 'difference' }}
          >
            {positionPercent.toFixed(0)}% / {limitPercent.toFixed(0)}%
          </div>
        </div>

        {/* detail (default variant) */}
        {badgeVariant === 'default' && (
          <div
            className="text-[11px] flex items-center gap-2"
            style={{ color: 'var(--muted-foreground)' }}
          >
            <span>当前 {positionPercent.toFixed(0)}%</span>
            <span>·</span>
            <span>
              {REGIME_LABEL[regime]} 上限 {limitPercent.toFixed(0)}%
            </span>
            {availableIncreaseAmount !== undefined && !overLimit && (
              <>
                <span>·</span>
                <span style={{ color: 'var(--green-down)' }}>
                  可加 {formatYuan(availableIncreaseAmount)}
                </span>
              </>
            )}
            {overLimit && (
              <span style={{ color: 'var(--red-up)' }} aria-label="超出上限">
                ⚠ 超限
              </span>
            )}
          </div>
        )}
      </div>
    );
  }
);

ORegimePositionLimitBadge.displayName = 'ORegimePositionLimitBadge';
