'use client';
import { forwardRef, type HTMLAttributes, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import { breadcrumbRecipe, breadcrumbItemRecipe } from '../../recipes';

export interface OBreadcrumbEntry { label: string; href?: string; }
export interface OBreadcrumbProps extends HTMLAttributes<HTMLElement> {
  items: OBreadcrumbEntry[];
  separator?: ReactNode;
}
export const OBreadcrumb = forwardRef<HTMLElement, OBreadcrumbProps>(
  function OBreadcrumb({ className, items, separator, ...props }, ref) {
    const sep = separator ?? (
      <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden>
        <path d="M6 4l4 4-4 4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
      </svg>
    );
    return (
      <nav ref={ref} aria-label="breadcrumb" className={cn(breadcrumbRecipe(), className)} {...props}>
        {items.map((it, i) => {
          const isLast = i === items.length - 1;
          return (
            <span key={i} className="flex items-center gap-1.5">
              {it.href && !isLast
                ? <a href={it.href} className={breadcrumbItemRecipe({ current: false })}>{it.label}</a>
                : <span className={breadcrumbItemRecipe({ current: isLast })} aria-current={isLast ? 'page' : undefined}>{it.label}</span>}
              {!isLast && sep}
            </span>
          );
        })}
      </nav>
    );
  }
);
OBreadcrumb.displayName = 'OBreadcrumb';
