/**
 * CommandProvider - 全局命令注册中心。
 *
 * 任何 Block 启动时可注册自己的命令,命令面板会自动收集。
 * 支持快捷键、别名、AI 意图映射。
 */
'use client';

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import type { CommandProtocol, CommandDescriptor } from '../protocols';

const CommandContext = createContext<CommandProtocol | null>(null);

interface CommandProviderProps {
  children: ReactNode;
  /** 全局快捷键启用,默认 cmd/ctrl+k 打开。 */
  globalHotkey?: string;
}

function matchesHotkey(e: KeyboardEvent, hotkey: string): boolean {
  // 简易快捷键解析: cmd+k / ctrl+shift+p / alt+/ 等
  const parts = hotkey.toLowerCase().split('+').map((p) => p.trim());
  const key = parts[parts.length - 1];
  const needCmd = parts.includes('cmd') || parts.includes('meta');
  const needCtrl = parts.includes('ctrl');
  const needShift = parts.includes('shift');
  const needAlt = parts.includes('alt');

  if (needCmd && !e.metaKey) return false;
  if (needCtrl && !e.ctrlKey) return false;
  if (needShift && !e.shiftKey) return false;
  if (needAlt && !e.altKey) return false;

  // 'cmd' 在 Mac 是 meta,在其他平台允许 ctrl
  if ((needCmd || needCtrl) && !e.metaKey && !e.ctrlKey) return false;

  return e.key.toLowerCase() === key;
}

export function CommandProvider({ children, globalHotkey = 'cmd+k' }: CommandProviderProps) {
  const registryRef = useRef(new Map<string, CommandDescriptor>());
  const [paletteOpen, setPaletteOpen] = useState(false);
  const [paletteQuery, setPaletteQuery] = useState('');

  const protocol = useMemo<CommandProtocol>(
    () => ({
      register(cmd) {
        registryRef.current.set(cmd.id, cmd);
        return () => {
          registryRef.current.delete(cmd.id);
        };
      },
      registerAll(cmds) {
        for (const c of cmds) registryRef.current.set(c.id, c);
        return () => {
          for (const c of cmds) registryRef.current.delete(c.id);
        };
      },
      list(group) {
        const all = Array.from(registryRef.current.values());
        return group ? all.filter((c) => c.group === group) : all;
      },
      async execute(id, args) {
        const cmd = registryRef.current.get(id);
        if (!cmd) {
          console.warn(`[CommandProvider] Unknown command: ${id}`);
          return;
        }
        await cmd.run(args);
      },
      openPalette(initialQuery) {
        setPaletteQuery(initialQuery ?? '');
        setPaletteOpen(true);
      },
      closePalette() {
        setPaletteOpen(false);
      },
    }),
    []
  );

  // 全局快捷键监听
  useEffect(() => {
    if (typeof window === 'undefined') return;
    function handler(e: KeyboardEvent) {
      // 命令面板开关
      if (matchesHotkey(e, globalHotkey)) {
        e.preventDefault();
        setPaletteOpen((open) => !open);
        return;
      }
      // 各 command 自己的快捷键
      for (const cmd of registryRef.current.values()) {
        if (cmd.hotkey && matchesHotkey(e, cmd.hotkey)) {
          e.preventDefault();
          cmd.run();
          return;
        }
      }
    }
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [globalHotkey]);

  // 暴露 palette state 给消费方(命令面板组件)
  const value = useMemo(
    () => Object.assign(protocol, { __paletteOpen: paletteOpen, __paletteQuery: paletteQuery }),
    [protocol, paletteOpen, paletteQuery]
  );

  return <CommandContext.Provider value={value}>{children}</CommandContext.Provider>;
}

CommandProvider.displayName = 'CommandProvider';

export function useCommands(): CommandProtocol {
  const ctx = useContext(CommandContext);
  if (!ctx) {
    return {
      register: () => () => {},
      registerAll: () => () => {},
      list: () => [],
      execute: async () => {},
      openPalette: () => {},
      closePalette: () => {},
    };
  }
  return ctx;
}

/** 内部用:命令面板组件读取 open 状态。 */
export function useCommandPaletteState(): { open: boolean; query: string } {
  const ctx = useContext(CommandContext) as
    | (CommandProtocol & { __paletteOpen?: boolean; __paletteQuery?: string })
    | null;
  return { open: ctx?.__paletteOpen ?? false, query: ctx?.__paletteQuery ?? '' };
}

/**
 * 便利 hook:Block 内一次性注册一组命令,unmount 时自动清理。
 */
export function useRegisterCommands(cmds: CommandDescriptor[]): void {
  const { registerAll } = useCommands();
  // 使用 ref 锁定 cmds 引用,避免每次渲染重新注册
  const cmdsRef = useRef(cmds);
  cmdsRef.current = cmds;
  const unsubscribeRef = useRef<(() => void) | null>(null);

  // 注册一次(register 函数依赖 registerAll,但 cmdsRef 是 mutable 不算依赖)
  const register = useCallback(() => {
    unsubscribeRef.current?.();
    unsubscribeRef.current = registerAll(cmdsRef.current);
  }, [registerAll]);

  useEffect(() => {
    register();
    return () => {
      unsubscribeRef.current?.();
      unsubscribeRef.current = null;
    };
    // 仅初次挂载注册,register 内部已通过 cmdsRef 拿最新命令
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
}
