/**
 * OGlowingBadge - 光晕脉冲徽章 (类 2)。
 *
 * 比 OStatusBadge 更强的视觉表达:
 *   - 外层 glow 光晕 (box-shadow + 颜色)
 *   - 内层圆点缓慢 pulse (scale 呼吸)
 *   - 三层 ping 涟漪 (可选)
 *
 * 用于需要醒目提示的场景: live 状态、新通知、关键告警。
 *
 * 在 reduced-motion 下:保留光晕颜色,关闭脉冲与涟漪。
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, type CSSProperties } from 'react';
import { motion } from 'motion/react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

const badgeVariants = cva(
  'relative inline-flex items-center gap-2 rounded-full border font-medium whitespace-nowrap',
  {
    variants: {
      status: {
        live: 'bg-success/10 text-success border-success/40',
        critical: 'bg-destructive/10 text-destructive border-destructive/40',
        warning: 'bg-warning/10 text-warning border-warning/40',
        info: 'bg-info/10 text-info border-info/40',
        primary: 'bg-primary/10 text-primary border-primary/40',
      },
      size: {
        sm: 'px-2.5 py-0.5 text-xs',
        md: 'px-3 py-1 text-sm',
        lg: 'px-4 py-1.5 text-base',
      },
      intensity: {
        subtle: '',
        normal: '',
        intense: '',
      },
    },
    defaultVariants: { status: 'live', size: 'md', intensity: 'normal' },
  }
);

type BadgeVariantProps = VariantProps<typeof badgeVariants>;

const STATUS_COLOR_VAR: Record<string, string> = {
  live: '--success',
  critical: '--destructive',
  warning: '--warning',
  info: '--info',
  primary: '--primary',
};

const GLOW_INTENSITY: Record<string, string> = {
  subtle: '12px',
  normal: '20px',
  intense: '32px',
};

const RIPPLE_INTENSITY: Record<string, number> = {
  subtle: 0,
  normal: 1,
  intense: 2,
};

export interface OGlowingBadgeProps
  extends Omit<OBlockBaseProps, 'variant' | 'size'>,
    BadgeVariantProps {
  label: string;
  /** 关闭呼吸/涟漪 (仅保留 glow)。 */
  static?: boolean;
}

export const OGlowingBadge = forwardRef<HTMLSpanElement, OGlowingBadgeProps>(function OGlowingBadge(
  {
    status = 'live',
    size = 'md',
    intensity = 'normal',
    label,
    static: isStatic = false,
    className,
    theme: _t,
    ...rest
  },
  ref
) {
  const reduced = useReducedMotion();
  const animate = !isStatic && !reduced;
  const colorVar = STATUS_COLOR_VAR[status ?? 'live'] ?? '--primary';
  const glowSize = GLOW_INTENSITY[intensity ?? 'normal'] ?? '20px';
  const ripples = animate ? RIPPLE_INTENSITY[intensity ?? 'normal'] ?? 1 : 0;

  const glowStyle: CSSProperties = {
    boxShadow: `0 0 ${glowSize} color-mix(in oklch, var(${colorVar}) 50%, transparent)`,
  };

  const dotStyle: CSSProperties = { backgroundColor: `var(${colorVar})` };

  return (
    <span
      ref={ref}
      className={cn(badgeVariants({ status, size, intensity }), className)}
      style={glowStyle}
      data-status={status}
      {...rest}
    >
      <span className="relative inline-flex items-center justify-center @container" aria-hidden="true">
        {/* ripple layers */}
        {Array.from({ length: ripples }).map((_, i) => (
          <motion.span
            key={i}
            className="absolute inset-0 rounded-full"
            style={dotStyle}
            initial={{ scale: 1, opacity: 0.6 }}
            animate={{ scale: 3 + i, opacity: 0 }}
            transition={{
              duration: 1.8,
              delay: i * 0.5,
              repeat: Infinity,
              ease: 'easeOut',
            }}
          />
        ))}
        {/* core dot, breathing if animated */}
        {animate ? (
          <motion.span
            className="relative inline-flex h-2 w-2 rounded-full"
            style={dotStyle}
            animate={{ scale: [1, 1.25, 1], opacity: [0.85, 1, 0.85] }}
            transition={{ duration: 1.6, repeat: Infinity, ease: 'easeInOut' }}
          />
        ) : (
          <span className="relative inline-flex h-2 w-2 rounded-full" style={dotStyle} />
        )}
      </span>
      <span>{label}</span>
    </span>
  );
});

OGlowingBadge.displayName = 'OGlowingBadge';
