/**
 * OConfidenceMeter — 置信度/可信度可视化(跨项目认识论原语)。
 *
 * 设计原则(跟 OEpistemicBadge 同精神):
 *   - value→color 硬编码,**不接 colorOverride prop**
 *     → 业务方无法把 0.2 美化成绿色(不美化低可信度)
 *   - basis 文字默认显示,只能 hideBasis 完全关闭
 *   - useUiLang:tier label 跟全局语言联动
 *
 * 使用场景:
 *   - AII 对话区:每条回答的 epistemic_confidence
 *   - Tide 信号:signal confidence
 *   - Stratum 引用:source confidence
 *   - Aegis 根因:diagnosis confidence
 *   - Mneme 掌握度:effective_mastery(K12 场景可 hideBasis=true 配合自己文案)
 *
 * 颜色档(硬编码):
 *   ≥ 0.75  → success (绿)
 *   ≥ 0.50  → moderate (amber)
 *   ≥ 0.25  → warn (orange,警示)
 *   < 0.25  → low (红,unverified-like)
 *
 * @example
 * <OConfidenceMeter value={0.78} basis="基于 5 条 KU:3 proven, 2 high" />
 * <OConfidenceMeter value={0.22} compact />   // 进度条 + 百分比,无 label
 */
'use client';

import { forwardRef, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import { useUiLang } from '../../lang/LangProvider';
import type { OBlockBaseProps } from '../../lib/types';

export interface OConfidenceMeterProps
  extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  /** 0-1 之间的置信度值(超出范围自动 clamp) */
  value: number;
  /** 置信度依据说明(人话),显示在进度条下方 */
  basis?: ReactNode;
  /** 隐藏 basis 文字(默认 false — 显示) */
  hideBasis?: boolean;
  /** 紧凑模式:只显示进度条 + 百分比,隐藏 tier label */
  compact?: boolean;
  /** 进度条高度 px,默认 8 */
  barHeight?: number;
}

type ConfidenceTier = 'high' | 'moderate' | 'warn' | 'low';

interface TierMeta {
  zh: string;
  en: string;
  color: string;
  bg: string;
  ring: string;
}

/** 硬编码 — 跨项目不可覆盖 */
const TIERS: Record<ConfidenceTier, TierMeta> = {
  high: {
    zh: '高可信', en: 'High',
    color: 'var(--success)',
    bg:    'color-mix(in oklch, var(--success) 15%, transparent)',
    ring:  'var(--success)',
  },
  moderate: {
    zh: '中等', en: 'Moderate',
    color: 'var(--warning)',
    bg:    'color-mix(in oklch, var(--warning) 15%, transparent)',
    ring:  'var(--warning)',
  },
  warn: {
    zh: '偏低', en: 'Low',
    color: 'var(--warning)',
    bg:    'color-mix(in oklch, var(--warning) 20%, transparent)',
    ring:  'var(--warning)',
  },
  low: {
    zh: '极低', en: 'Very low',
    color: 'var(--destructive)',
    bg:    'color-mix(in oklch, var(--destructive) 15%, transparent)',
    ring:  'var(--destructive)',
  },
};

function tierOf(v: number): ConfidenceTier {
  if (v >= 0.75) return 'high';
  if (v >= 0.5)  return 'moderate';
  if (v >= 0.25) return 'warn';
  return 'low';
}

export const OConfidenceMeter = forwardRef<HTMLDivElement, OConfidenceMeterProps>(
  function OConfidenceMeter(
    {
      value,
      basis,
      hideBasis = false,
      compact = false,
      barHeight = 8,
      className,
      theme: _t,
    },
    ref
  ) {
    const { tr } = useUiLang();
    const clamped = Math.max(0, Math.min(1, value));
    const pct = Math.round(clamped * 100);
    const tier = tierOf(clamped);
    const meta = TIERS[tier];
    const tierLabel = tr(meta.zh, meta.en);

    return (
      <div
        ref={ref}
        className={cn('flex flex-col gap-1.5 @container', className)}
        role="meter"
        aria-valuenow={pct}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label={`${tr('置信度', 'Confidence')}: ${pct}% (${tierLabel})`}
      >
        {!compact && (
          <div className="flex items-center gap-2">
            <span
              className="text-xs font-medium px-2 py-0.5 rounded-full border"
              style={{ color: meta.color, background: meta.bg, borderColor: meta.ring }}
            >
              {tierLabel}
            </span>
            <span
              className="text-sm font-mono font-semibold"
              style={{ color: meta.color }}
            >
              {pct}%
            </span>
          </div>
        )}

        {compact && (
          <div className="flex items-center gap-2">
            <span className="text-xs font-mono font-semibold" style={{ color: meta.color }}>
              {pct}%
            </span>
          </div>
        )}

        <div
          className="relative rounded-full overflow-hidden"
          style={{
            height: barHeight,
            background: 'var(--muted)',
          }}
        >
          <div
            className="absolute inset-y-0 left-0 transition-[width] duration-300"
            style={{ width: `${pct}%`, background: meta.ring }}
          />
        </div>

        {!compact && !hideBasis && basis !== undefined && (
          <div className="text-xs text-[color:var(--muted-foreground)]">{basis}</div>
        )}
      </div>
    );
  }
);
