/**
 * OCommentThread - 评论串。
 *
 * 支持嵌套(最多 maxDepth 层),回复表单,点赞计数。
 * 受控:数据从 Page 来,操作回调由 Page 处理 (e.g. 提交到后端)。
 */
'use client';

import { forwardRef, useState, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';
import { OAvatar } from '../OAvatar';

export interface OComment {
  id: string;
  author: { name: string; avatar?: string };
  body: ReactNode;
  /** ISO 字符串。 */
  createdAt: string | Date;
  likes?: number;
  liked?: boolean;
  /** 嵌套回复。 */
  replies?: OComment[];
}

export interface OCommentThreadProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  comments: OComment[];
  /** 提交新评论或回复。parentId 为 null 表示顶层评论。 */
  onSubmit?: (body: string, parentId: string | null) => void;
  onLike?: (id: string) => void;
  /** 最大嵌套层级。 */
  maxDepth?: number;
  /** 当前登录用户(显示在输入框头像)。 */
  currentUser?: { name: string; avatar?: string };
  /** 输入框占位文本。 */
  placeholder?: string;
}

function relativeTime(d: string | Date): string {
  const date = typeof d === 'string' ? new Date(d) : d;
  const diff = (Date.now() - date.getTime()) / 1000;
  if (diff < 60) return 'just now';
  if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
  if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
  if (diff < 86400 * 7) return `${Math.floor(diff / 86400)}d ago`;
  return date.toLocaleDateString();
}

function CommentNode({
  comment,
  depth,
  maxDepth,
  onLike,
  onSubmit,
  currentUser,
  placeholder,
}: {
  comment: OComment;
  depth: number;
  maxDepth: number;
  onLike?: (id: string) => void;
  onSubmit?: (body: string, parentId: string | null) => void;
  currentUser?: { name: string; avatar?: string };
  placeholder: string;
}) {
  const [showReplyForm, setShowReplyForm] = useState(false);
  const [draft, setDraft] = useState('');
  const canReply = depth < maxDepth && onSubmit;

  function submit() {
    if (!draft.trim() || !onSubmit) return;
    onSubmit(draft.trim(), comment.id);
    setDraft('');
    setShowReplyForm(false);
  }

  return (
    <li className="flex gap-3">
      <OAvatar name={comment.author.name} src={comment.author.avatar} size="sm" />
      <div className="flex-1 min-w-0">
        <div className="flex items-baseline gap-2 mb-1">
          <span className="text-sm font-medium">{comment.author.name}</span>
          <time className="text-xs text-muted-foreground">{relativeTime(comment.createdAt)}</time>
        </div>
        <div className="text-sm text-foreground/90 break-words">{comment.body}</div>
        <div className="flex items-center gap-3 mt-2 text-xs">
          {onLike ? (
            <button
              type="button"
              onClick={() => onLike(comment.id)}
              className={cn(
                'inline-flex items-center gap-1 hover:text-foreground transition-colors @container',
                comment.liked ? 'text-primary' : 'text-muted-foreground'
              )}
            >
              <svg width="12" height="12" viewBox="0 0 24 24" fill={comment.liked ? 'currentColor' : 'none'} stroke="currentColor" strokeWidth="2">
                <path d="M20.84 4.61a5.5 5.5 0 00-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 00-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 000-7.78z" />
              </svg>
              {comment.likes ?? 0}
            </button>
          ) : null}
          {canReply ? (
            <button
              type="button"
              onClick={() => setShowReplyForm((s) => !s)}
              className="text-muted-foreground hover:text-foreground transition-colors"
            >
              Reply
            </button>
          ) : null}
        </div>

        {showReplyForm ? (
          <div className="flex gap-2 mt-3">
            {currentUser ? <OAvatar name={currentUser.name} src={currentUser.avatar} size="sm" /> : null}
            <div className="flex-1 flex gap-2">
              <textarea
                value={draft}
                onChange={(e) => setDraft(e.target.value)}
                placeholder={placeholder}
                rows={2}
                className="flex-1 px-3 py-2 text-sm bg-card border border-input rounded-md outline-none focus:ring-2 focus:ring-ring resize-none"
              />
              <button
                type="button"
                onClick={submit}
                disabled={!draft.trim()}
                className="px-3 py-1.5 text-sm rounded bg-primary text-primary-foreground disabled:opacity-50 self-end"
              >
                Send
              </button>
            </div>
          </div>
        ) : null}

        {comment.replies && comment.replies.length > 0 ? (
          <ul className="mt-4 space-y-4 border-l border-border pl-4">
            {comment.replies.map((r) => (
              <CommentNode
                key={r.id}
                comment={r}
                depth={depth + 1}
                maxDepth={maxDepth}
                onLike={onLike}
                onSubmit={onSubmit}
                currentUser={currentUser}
                placeholder={placeholder}
              />
            ))}
          </ul>
        ) : null}
      </div>
    </li>
  );
}

export const OCommentThread = forwardRef<HTMLDivElement, OCommentThreadProps>(function OCommentThread(
  {
    comments,
    onSubmit,
    onLike,
    maxDepth = 3,
    currentUser,
    placeholder = 'Write a comment...',
    className,
    theme: _t,
  },
  ref
) {
  const [topDraft, setTopDraft] = useState('');

  return (
    <div ref={ref} className={cn('space-y-6', className)}>
      {onSubmit && currentUser ? (
        <div className="flex gap-3">
          <OAvatar name={currentUser.name} src={currentUser.avatar} size="sm" />
          <div className="flex-1 flex gap-2">
            <textarea
              value={topDraft}
              onChange={(e) => setTopDraft(e.target.value)}
              placeholder={placeholder}
              rows={3}
              className="flex-1 px-3 py-2 text-sm bg-card border border-input rounded-md outline-none focus:ring-2 focus:ring-ring resize-none"
            />
            <button
              type="button"
              onClick={() => {
                if (!topDraft.trim()) return;
                onSubmit(topDraft.trim(), null);
                setTopDraft('');
              }}
              disabled={!topDraft.trim()}
              className="px-4 py-2 text-sm rounded bg-primary text-primary-foreground disabled:opacity-50 self-start"
            >
              Send
            </button>
          </div>
        </div>
      ) : null}
      <ul className="space-y-6">
        {comments.map((c) => (
          <CommentNode
            key={c.id}
            comment={c}
            depth={0}
            maxDepth={maxDepth}
            onLike={onLike}
            onSubmit={onSubmit}
            currentUser={currentUser}
            placeholder={placeholder}
          />
        ))}
      </ul>
    </div>
  );
});

OCommentThread.displayName = 'OCommentThread';
