/**
 * useFreshness — 数据新鲜度判断 hook
 *
 * 用途:任何数据展示场景判断 timestamp 离现在多久,返回新鲜度等级。
 * 跨项目通用(Helios fusion score / Stratum agent run / Aegis incident / hevi job)。
 *
 * 来源:Helios 经理人 R1 §1.6(ADR-038 诚实到不舒服 / 5 红线 #5)。
 */

import { useEffect, useState } from 'react';

/**
 * 数据新鲜度等级。
 * - `fresh`: 在 freshTtl 阈值内
 * - `stale`: 超过 freshTtl,但未超 staleTtl(警告但可用)
 * - `dead`: 超过 staleTtl(数据太老,不应展示或必须警告)
 */
export type FreshnessLevel = 'fresh' | 'stale' | 'dead';

export interface UseFreshnessOptions {
  /** fresh → stale 阈值(毫秒)。默认 60s。 */
  freshTtlMs?: number;
  /** stale → dead 阈值(毫秒)。默认 300s(5min)。 */
  staleTtlMs?: number;
  /** tick interval(每多少 ms 重算)。默认 1000ms。 */
  tickIntervalMs?: number;
}

export interface FreshnessState {
  /** 当前等级。 */
  level: FreshnessLevel;
  /** 数据更新到现在过去多久(毫秒)。 */
  ageMs: number;
  /** 人类可读"3 秒前 / 2 分钟前 / 1 小时前"。 */
  ageHuman: string;
}

/**
 * 给一个 timestamp(unix ms 或 ISO string 或 Date),返回实时更新的新鲜度。
 *
 * @example
 * ```tsx
 * const fr = useFreshness(data.last_updated_at);
 * // fr.level === 'fresh' | 'stale' | 'dead'
 * // fr.ageHuman === "3 秒前" / "2 分钟前"
 * ```
 */
export function useFreshness(
  timestamp: number | string | Date | null | undefined,
  options: UseFreshnessOptions = {}
): FreshnessState {
  const freshTtl = options.freshTtlMs ?? 60_000;
  const staleTtl = options.staleTtlMs ?? 300_000;
  const tick = options.tickIntervalMs ?? 1000;

  const [now, setNow] = useState(() => Date.now());

  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), tick);
    return () => clearInterval(id);
  }, [tick]);

  if (timestamp == null) {
    return { level: 'dead', ageMs: Infinity, ageHuman: '无数据' };
  }

  const ts =
    typeof timestamp === 'number'
      ? timestamp
      : timestamp instanceof Date
        ? timestamp.getTime()
        : new Date(timestamp).getTime();

  if (Number.isNaN(ts)) {
    return { level: 'dead', ageMs: Infinity, ageHuman: '无效时间' };
  }

  const ageMs = now - ts;

  let level: FreshnessLevel;
  if (ageMs <= freshTtl) level = 'fresh';
  else if (ageMs <= staleTtl) level = 'stale';
  else level = 'dead';

  return { level, ageMs, ageHuman: formatAgeHuman(ageMs) };
}

function formatAgeHuman(ms: number): string {
  if (ms < 0) return '刚刚';
  const s = Math.floor(ms / 1000);
  if (s < 1) return '刚刚';
  if (s < 60) return `${s} 秒前`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m} 分钟前`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h} 小时前`;
  const d = Math.floor(h / 24);
  return `${d} 天前`;
}
