/**
 * OQuoteTicker (Tide Wave 2 E6, Atom)
 *
 * 实时跳动的股价 ticker, Bloomberg 仿生 flash 动画。
 * 来源:OUI_WAVE_2_REQUIREMENTS_v1.0.md §3
 *
 * 3 variant: row(单行 5 列) / card(卡片) / hero(大字 detail)
 * 自动 flash:price 变化时触发 flash-up / flash-down 0.8s 动画
 * A 股语义反转:ashare=true 红涨绿跌
 * source 标识:akshare / last_close 显示
 */
import {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
  type MouseEvent,
} from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OQuoteTickerProps extends Omit<OBlockBaseProps, 'variant'> {
  symbol: string;
  name: string;
  price: number;
  change: number;
  pct: number;
  volume?: number;
  /** 量比 */
  volumeRatio?: number;
  source?: 'sina' | 'akshare' | 'last_close';
  /** 数据陈旧时间(秒) */
  ageSeconds?: number;
  /** A 股语义反转, 默认 true */
  ashare?: boolean;
  tickerVariant?: 'row' | 'card' | 'hero';
  onClick?: (e: MouseEvent<HTMLButtonElement>) => void;
}

export interface OQuoteTickerRef {
  triggerFlash: (direction: 'up' | 'down') => void;
}

export const OQuoteTicker = forwardRef<OQuoteTickerRef | null, OQuoteTickerProps>(
  function OQuoteTicker(
    {
      symbol,
      name,
      price,
      change,
      pct,
      volume: _volume,
      volumeRatio,
      source = 'sina',
      ageSeconds = 0,
      ashare = true,
      tickerVariant = 'row',
      onClick,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const lastPriceRef = useRef<number>(price);
    const [flashDir, setFlashDir] = useState<'up' | 'down' | null>(null);
    const flashTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    // 检测 price 变化触发 flash
    useEffect(() => {
      const last = lastPriceRef.current;
      if (price !== last) {
        const dir = price > last ? 'up' : 'down';
        setFlashDir(dir);
        if (flashTimerRef.current) clearTimeout(flashTimerRef.current);
        flashTimerRef.current = setTimeout(() => setFlashDir(null), 800);
        lastPriceRef.current = price;
      }
    }, [price]);

    useEffect(
      () => () => {
        if (flashTimerRef.current) clearTimeout(flashTimerRef.current);
      },
      []
    );

    useImperativeHandle(
      ref,
      () => ({
        triggerFlash: (direction: 'up' | 'down') => {
          setFlashDir(direction);
          if (flashTimerRef.current) clearTimeout(flashTimerRef.current);
          flashTimerRef.current = setTimeout(() => setFlashDir(null), 800);
        },
      }),
      []
    );

    // 涨跌色(A 股反转)
    const upColor = ashare ? 'var(--red-up)' : 'var(--green-down)';
    const downColor = ashare ? 'var(--green-down)' : 'var(--red-up)';
    const changeColor = change > 0 ? upColor : change < 0 ? downColor : 'var(--muted-foreground)';

    // stale data 降饱和
    const stale = ageSeconds > 5;

    // flash 背景色
    const flashBg =
      flashDir === 'up'
        ? `${upColor.replace('var(--', 'rgba(').replace(')', ', 0.3)')}`
        : flashDir === 'down'
        ? `${downColor.replace('var(--', 'rgba(').replace(')', ', 0.3)')}`
        : 'transparent';

    // 实际上 css var 不能直接 rgba 操作。改用 className 控制:
    const flashClass = flashDir === 'up' ? 'tide-flash-up' : flashDir === 'down' ? 'tide-flash-down' : '';

    const Wrapper: React.ComponentType<React.HTMLAttributes<HTMLElement> & Record<string, unknown>> =
      onClick
        ? ((p) => <button {...(p as React.ButtonHTMLAttributes<HTMLButtonElement>)} />)
        : ((p) => <div {...(p as React.HTMLAttributes<HTMLDivElement>)} />);
    const wrapperProps = onClick
      ? { type: 'button' as const, onClick, 'aria-label': `${name} ${symbol} ${price}` }
      : {};

    const sign = change > 0 ? '+' : '';

    if (tickerVariant === 'hero') {
      return (
        <Wrapper
          {...wrapperProps}
          className={cn(
            'flex flex-col gap-1 transition-colors @container',
            flashClass,
            stale && 'opacity-60',
            onClick && 'cursor-pointer hover:opacity-80',
            className
          )}
          style={{
            fontFamily: 'var(--font-mono)',
            backgroundColor: flashBg,
          }}
        >
          <div
            style={{ color: 'var(--foreground)', fontSize: 32, fontWeight: 700, lineHeight: 1 }}
          >
            {price.toFixed(2)}
          </div>
          <div className="flex items-center gap-2" style={{ color: changeColor }}>
            <span style={{ fontSize: 16, fontWeight: 600 }}>
              {sign}
              {change.toFixed(2)}
            </span>
            <span style={{ fontSize: 16, fontWeight: 600 }}>
              {sign}
              {pct.toFixed(2)}%
            </span>
          </div>
          {(source === 'akshare' || source === 'last_close') && (
            <span
              className="text-[10px]"
              style={{ color: source === 'last_close' ? 'var(--text-tertiary)' : 'var(--muted-foreground)' }}
            >
              {source === 'last_close' ? 'last close' : 'akshare'}
            </span>
          )}
        </Wrapper>
      );
    }

    if (tickerVariant === 'card') {
      return (
        <Wrapper
          {...wrapperProps}
          className={cn(
            'flex flex-col gap-1 px-2 py-1.5 rounded',
            'border border-[color:var(--border-subtle)]',
            flashClass,
            stale && 'opacity-60',
            onClick && 'cursor-pointer hover:bg-[color:var(--accent)]',
            className
          )}
          style={{ fontFamily: 'var(--font-mono)', backgroundColor: flashBg }}
        >
          <div className="flex items-center gap-2">
            <span className="text-xs" style={{ color: 'var(--muted-foreground)' }}>
              {symbol}
            </span>
            <span
              className="text-xs truncate"
              style={{ color: 'var(--foreground)', fontFamily: 'var(--font-sans)' }}
            >
              {name}
            </span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-sm font-bold" style={{ color: 'var(--foreground)' }}>
              {price.toFixed(2)}
            </span>
            <span className="text-xs" style={{ color: changeColor }}>
              {sign}
              {pct.toFixed(2)}%
            </span>
            {volumeRatio !== undefined && (
              <span className="text-[10px]" style={{ color: 'var(--muted-foreground)' }}>
                量 {volumeRatio.toFixed(1)}
              </span>
            )}
          </div>
        </Wrapper>
      );
    }

    // row variant (default, 5 列 grid for table)
    return (
      <Wrapper
        {...wrapperProps}
        className={cn(
          'inline-grid items-center gap-2 px-1 py-0.5 transition-colors',
          flashClass,
          stale && 'opacity-60',
          onClick && 'cursor-pointer hover:bg-[color:var(--accent)]',
          className
        )}
        style={{
          fontFamily: 'var(--font-mono)',
          gridTemplateColumns: '80px 1fr 70px 70px 50px',
          backgroundColor: flashBg,
        }}
      >
        <span className="text-xs" style={{ color: 'var(--muted-foreground)' }}>
          {symbol}
        </span>
        <span
          className="text-xs truncate"
          style={{ color: 'var(--foreground)', fontFamily: 'var(--font-sans)' }}
        >
          {name}
        </span>
        <span className="text-xs text-right font-bold" style={{ color: 'var(--foreground)' }}>
          {price.toFixed(2)}
        </span>
        <span className="text-xs text-right" style={{ color: changeColor }}>
          {sign}
          {pct.toFixed(2)}%
        </span>
        {volumeRatio !== undefined ? (
          <span className="text-[10px] text-right" style={{ color: 'var(--muted-foreground)' }}>
            {volumeRatio.toFixed(1)}
          </span>
        ) : (
          <span />
        )}
      </Wrapper>
    );
  }
);

OQuoteTicker.displayName = 'OQuoteTicker';
