/**
 * ODisciplineMatrix (Tide Wave 3 E20, Block)
 *
 * 7 regime × 2 discipline 热力矩阵。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §3.1
 *
 * A 股语义反转(winrate 维度):
 *   - winrate ≥ 60%: red (高 winrate 用红)
 *   - 40-60%: yellow
 *   - < 40%: green (差 winrate 用绿)
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { REGIME_LABEL, type RegimeState } from '../../types/tide';
import type { OBlockBaseProps } from '../../lib/types';

export interface DisciplineMatrixCell {
  regime: RegimeState;
  discipline: 'compliant' | 'violation';
  nTrades: number;
  winrate: number | null;
  avgPnlPct: number | null;
  totalPnl: number | null;
  isEmpty: boolean;
}

export interface ODisciplineMatrixProps extends Omit<OBlockBaseProps, 'variant'> {
  data: DisciplineMatrixCell[][];
  metric?: 'winrate' | 'n_trades' | 'avg_pnl';
  highlight?: { regime: RegimeState; discipline: 'compliant' | 'violation' };
  onCellClick?: (cell: DisciplineMatrixCell) => void;
}

function winrateColor(wr: number | null): string {
  if (wr === null) return 'var(--muted)';
  if (wr >= 0.6) return 'var(--red-up)';
  if (wr >= 0.4) return 'var(--yellow)';
  return 'var(--green-down)';
}

export const ODisciplineMatrix = forwardRef<HTMLDivElement, ODisciplineMatrixProps>(
  function ODisciplineMatrix(
    { data, metric = 'winrate', highlight, onCellClick, className, theme: _t, size: _s },
    ref
  ) {
    return (
      <div
        ref={ref}
        className={cn(
          'flex flex-col gap-1 px-3 py-2 rounded @container',
          'bg-[color:var(--card)] border border-[color:var(--border-strong)]',
          className
        )}
        style={{ fontFamily: 'var(--font-mono)' }}
        role="table"
        aria-label="纪律矩阵"
      >
        {/* header */}
        <div
          className="grid gap-1 items-center"
          style={{
            gridTemplateColumns: '60px 1fr 1fr',
            color: 'var(--text-tertiary)',
            fontSize: 10,
            textTransform: 'uppercase',
          }}
          role="row"
        >
          <div />
          <div className="text-center" role="columnheader">遵守</div>
          <div className="text-center" role="columnheader">违反</div>
        </div>
        {data.map((row, ri) => {
          const regime = row[0]?.regime as RegimeState;
          return (
            <div
              key={regime ?? ri}
              className="grid gap-1 items-center"
              style={{ gridTemplateColumns: '60px 1fr 1fr' }}
              role="row"
            >
              <div
                className="text-xs"
                style={{ color: 'var(--foreground)' }}
                role="rowheader"
              >
                {REGIME_LABEL[regime]}
              </div>
              {row.map((cell) => {
                const isHl =
                  highlight &&
                  highlight.regime === cell.regime &&
                  highlight.discipline === cell.discipline;
                const display = cell.isEmpty
                  ? '-'
                  : metric === 'winrate' && cell.winrate !== null
                    ? `${(cell.winrate * 100).toFixed(0)}%`
                    : metric === 'n_trades'
                      ? `${cell.nTrades}`
                      : metric === 'avg_pnl' && cell.avgPnlPct !== null
                        ? `${(cell.avgPnlPct * 100).toFixed(1)}%`
                        : '-';
                const clickable = !!onCellClick && !cell.isEmpty;
                return (
                  <div
                    key={cell.discipline}
                    role="cell"
                    aria-label={`${REGIME_LABEL[cell.regime]} ${cell.discipline === 'compliant' ? '遵守' : '违反'} winrate ${display}`}
                  >
                    <button
                      type="button"
                      disabled={!clickable}
                      onClick={() => clickable && onCellClick!(cell)}
                      className={cn(
                        'flex flex-col items-center justify-center py-1.5 rounded transition-opacity w-full',
                        clickable ? 'cursor-pointer hover:opacity-80' : 'cursor-default',
                        isHl && 'ring-2 ring-[color:var(--blue-accent)]'
                      )}
                      style={{
                        backgroundColor: cell.isEmpty
                          ? 'var(--muted)'
                          : `color-mix(in srgb, ${winrateColor(cell.winrate)} 25%, var(--card))`,
                        color: cell.isEmpty ? 'var(--text-tertiary)' : 'var(--foreground)',
                        border: 'none',
                        fontFamily: 'inherit',
                      }}
                    >
                      <span className="text-sm font-bold">{display}</span>
                      {!cell.isEmpty && (
                        <span
                          className="text-[10px]"
                          style={{ color: 'var(--muted-foreground)' }}
                        >
                          n={cell.nTrades}
                        </span>
                      )}
                    </button>
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>
    );
  }
);

ODisciplineMatrix.displayName = 'ODisciplineMatrix';
