'use client';
import { forwardRef, useState, type InputHTMLAttributes } from 'react';
import { cn } from '../../lib/cn';
import { switchRecipe, switchThumbRecipe, type SwitchRecipeProps } from '../../recipes';

export interface OSwitchProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'size'|'type'>,
    SwitchRecipeProps {
  label?: string;
}

export const OSwitch = forwardRef<HTMLInputElement, OSwitchProps>(
  function OSwitch({ size, label, checked, defaultChecked, onChange, className, disabled, id, ...rest }, ref) {
    const [internal, setInternal] = useState(!!defaultChecked);
    const isChecked = checked !== undefined ? checked : internal;
    const swId = id || `sw-${Math.random().toString(36).slice(2,8)}`;
    return (
      <label htmlFor={swId} className={cn('inline-flex items-center gap-2 cursor-pointer', disabled && 'cursor-not-allowed', className)}>
        <input
          ref={ref} id={swId} type="checkbox" role="switch" className="sr-only peer"
          checked={isChecked} disabled={disabled}
          onChange={e => { if (checked === undefined) setInternal(e.target.checked); onChange?.(e); }}
          {...rest}
        />
        <span data-checked={isChecked} className={switchRecipe({ size })}>
          <span data-checked={isChecked} className={switchThumbRecipe({ size })} />
        </span>
        {label && <span className="text-[length:var(--text-sm)] select-none">{label}</span>}
      </label>
    );
  }
);
OSwitch.displayName = 'OSwitch';
