/**
 * ONetworkGraph3D - 3D 力导向网络图 (类 3 重型)。
 *
 * 用途:
 *   - Aegis 故障链路图
 *   - Helios 系统性风险传染图
 *   - 知识图谱可视化
 *
 * SPEC §3.5-§3.7:
 *   - GPU tier ≤ 1 → 2D 列表 fallback
 *   - reduced-motion: 不禁止 (用户可手动控制相机)
 *   - 自实现 force-directed,无第三方依赖
 */
'use client';

import { Suspense, lazy, forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { useGpuTier } from '../../hooks/useGpuTier';
import type { OBlockDataProps, OHeavyBlockProps } from '../../lib/types';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import type { ONetworkGraph3DData } from './ONetworkGraph3D.types';

const NetworkScene = lazy(() =>
  import('./ONetworkGraph3D.scene').then((m) => ({ default: m.NetworkScene }))
);

export interface ONetworkGraph3DProps
  extends OBlockDataProps<ONetworkGraph3DData>,
    OHeavyBlockProps {
  interactive?: boolean;
  height?: string | number;
  forceFallback?: boolean;
}

const DefaultFallback = ({ data }: { data: ONetworkGraph3DData }) => (
  <div className="w-full h-full bg-card border border-border rounded-md p-4 overflow-auto">
    <div className="text-sm text-muted-foreground mb-3">
      3D unavailable — node list ({data.nodes.length} nodes, {data.edges.length} edges)
    </div>
    <ul className="space-y-1 text-sm">
      {data.nodes.map((n) => (
        <li key={n.id} className="flex justify-between border-b border-border/40 py-1">
          <span>{n.label ?? n.id}</span>
          <span className="text-muted-foreground">{n.group ?? 'default'}</span>
        </li>
      ))}
    </ul>
  </div>
);

export const ONetworkGraph3D = forwardRef<HTMLDivElement, ONetworkGraph3DProps>(
  function ONetworkGraph3D(
    {
      data,
      loading,
      error,
      empty,
      interactive = true,
      height = 500,
      fallback,
      forceFallback = false,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const state = resolveBlockState({ data, loading, error, empty });
    const gpu = useGpuTier();
    const containerStyle = { height: typeof height === 'number' ? `${height}px` : height };

    if (state === 'loading')
      return (
        <div
          ref={ref}
          className={cn('rounded-md border border-border bg-card p-4 w-full @container', className)}
          style={containerStyle}
        >
          <OLoadingState variant="spinner" message="Loading network graph..." />
        </div>
      );
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data || data.nodes.length === 0)
      return (
        <OEmptyState
          ref={ref}
          title="Empty network"
          description="There are no nodes to render."
          className={className}
        />
      );

    const shouldFallback = forceFallback || gpu.tier <= 1;
    if (shouldFallback) {
      return (
        <div
          ref={ref}
          className={cn('relative w-full overflow-hidden rounded-md border border-border', className)}
          style={containerStyle}
          data-fallback="true"
        >
          {fallback ?? <DefaultFallback data={data} />}
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn('relative w-full overflow-hidden rounded-md border border-border bg-background', className)}
        style={containerStyle}
        data-gpu-tier={gpu.tier}
      >
        <Suspense
          fallback={
            <div className="w-full h-full flex items-center justify-center">
              <OLoadingState variant="spinner" message="Loading 3D scene..." />
            </div>
          }
        >
          <NetworkScene data={data} interactive={interactive} />
        </Suspense>
      </div>
    );
  }
);

ONetworkGraph3D.displayName = 'ONetworkGraph3D';
