/**
 * OSymbolSearch - 加密标的快速搜索 (Helios 杀手锏)。
 *
 * 多维匹配:
 *   - 代码:  BTC / BTC/USDT / BTCUSDT
 *   - 英文:  bitcoin
 *   - 中文:  比特币
 *   - 拼音:  bitebi / btb (首字母)
 *
 * 包含最近搜索 + 收藏 + 键盘导航。
 *
 * 数据契约: 由消费方传入 symbols 列表。Helios 内置 30+ 个主流币种作为兜底。
 */

'use client';

import { forwardRef, useEffect, useMemo, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OSymbolItem {
  /** 标的 key (如 BTC/USDT)。 */
  symbol: string;
  /** 英文名 (如 Bitcoin)。 */
  name?: string;
  /** 中文名 (如 比特币)。 */
  nameZh?: string;
  /** 拼音 (如 bitebi)。 */
  pinyin?: string;
  /** 拼音首字母 (如 btb)。 */
  pinyinAbbr?: string;
  /** 标签 (如 PoW / DeFi / L2)。 */
  tags?: string[];
  /** 24h 涨跌% (用于排序/显示)。 */
  changePct?: number;
  /** 当前价格 (展示用)。 */
  price?: number;
  /** logo URL / emoji。 */
  icon?: React.ReactNode;
}

export interface OSymbolSearchProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  /** 完整 symbol 列表。 */
  symbols?: OSymbolItem[];
  /** 已收藏 symbol keys。 */
  favorites?: string[];
  /** 切换收藏。 */
  onToggleFavorite?: (symbol: string) => void;
  /** 选中 symbol 回调。 */
  onSelect: (symbol: string) => void;
  /** 是否记录最近搜索到 localStorage。 */
  persistRecent?: boolean;
  /** 最大显示结果数。 */
  maxResults?: number;
  /** 占位符。 */
  placeholder?: string;
}

