const RECENT_KEY = 'helios-symbol-recent';
const MAX_RECENT = 8;

// ============================================================
// 匹配评分
// ============================================================

function score(item: OSymbolItem, q: string): number {
  if (!q) return 0;
  const lq = q.toLowerCase();
  // 100 - 全等
  if (item.symbol.toLowerCase() === lq) return 100;
  // 90 - symbol 前缀
  if (item.symbol.toLowerCase().startsWith(lq)) return 90;
  // 80 - pinyinAbbr 全等
  if (item.pinyinAbbr === lq) return 80;
  // 75 - nameZh 包含
  if (item.nameZh?.includes(q)) return 75;
  // 70 - pinyin 前缀
  if (item.pinyin?.startsWith(lq)) return 70;
  // 65 - name 前缀
  if (item.name?.toLowerCase().startsWith(lq)) return 65;
  // 50 - symbol 包含
  if (item.symbol.toLowerCase().includes(lq)) return 50;
  // 40 - name 包含
  if (item.name?.toLowerCase().includes(lq)) return 40;
  // 30 - pinyin 包含
  if (item.pinyin?.includes(lq)) return 30;
  // 20 - pinyinAbbr 前缀
  if (item.pinyinAbbr?.startsWith(lq)) return 20;
  return 0;
}

// ============================================================
// 组件
// ============================================================

export const OSymbolSearch = forwardRef<HTMLDivElement, OSymbolSearchProps>(
  function OSymbolSearch(
    {
      symbols = DEFAULT_SYMBOLS,
      favorites = [],
      onToggleFavorite,
      onSelect,
      persistRecent = true,
      maxResults = 12,
      placeholder = '搜索币种 (BTC / 比特币 / btb / bitcoin)',
      className,
      theme: _t,
    },
    ref
  ) {
    const [query, setQuery] = useState('');
    const [activeIdx, setActiveIdx] = useState(0);
    const [recent, setRecent] = useState<string[]>([]);
    const inputRef = useRef<HTMLInputElement | null>(null);

    // 读取 recent
    useEffect(() => {
      if (!persistRecent || typeof localStorage === 'undefined') return;
      try {
        const raw = localStorage.getItem(RECENT_KEY);
        if (raw) setRecent(JSON.parse(raw));
      } catch {
        /* ignore */
      }
    }, [persistRecent]);

    // 过滤 + 排序
    const results = useMemo(() => {
      if (!query.trim()) {
        // 无查询时:优先显示 favorites + recent + top by changePct
        const favSet = new Set(favorites);
        const recentSet = new Set(recent);
        const favItems = symbols.filter((s) => favSet.has(s.symbol));
        const recentItems = symbols.filter((s) => recentSet.has(s.symbol) && !favSet.has(s.symbol));
        const rest = symbols
          .filter((s) => !favSet.has(s.symbol) && !recentSet.has(s.symbol))
          .sort((a, b) => Math.abs(b.changePct ?? 0) - Math.abs(a.changePct ?? 0));
        return [...favItems, ...recentItems, ...rest].slice(0, maxResults);
      }
      return symbols
        .map((s) => ({ s, score: score(s, query.trim()) }))
        .filter((x) => x.score > 0)
        .sort((a, b) => b.score - a.score)
        .slice(0, maxResults)
        .map((x) => x.s);
    }, [symbols, query, favorites, recent, maxResults]);

    function handleSelect(symbol: string) {
      onSelect(symbol);
      // 记录到 recent
      if (persistRecent) {
        const next = [symbol, ...recent.filter((s) => s !== symbol)].slice(0, MAX_RECENT);
        setRecent(next);
        try {
          localStorage.setItem(RECENT_KEY, JSON.stringify(next));
        } catch {
          /* ignore */
        }
      }
      setQuery('');
    }

    function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setActiveIdx((i) => Math.min(results.length - 1, i + 1));
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setActiveIdx((i) => Math.max(0, i - 1));
      } else if (e.key === 'Enter') {
        e.preventDefault();
        const sel = results[activeIdx];
        if (sel) handleSelect(sel.symbol);
      } else if (e.key === 'Escape') {
        setQuery('');
      }
    }

    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border overflow-hidden flex flex-col @container',
          className
        )}
        style={{
          background: 'var(--card)',
          fontFamily: 'var(--font-ui)',
          maxHeight: 480,
        }}
      >
        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setActiveIdx(0);
          }}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          style={{
            padding: '12px 14px',
            background: 'var(--input)',
            border: 'none',
            borderBottom: '1px solid var(--border)',
            color: 'var(--foreground)',
            fontSize: 13,
            outline: 'none',
            width: '100%',
            fontFamily: 'var(--font-ui)',
          }}
          aria-label="Search symbols"
          autoComplete="off"
        />
        <div
          style={{
            overflow: 'auto',
            flex: 1,
          }}
          role="listbox"
        >
          {results.length === 0 ? (
            <div style={{ padding: 20, textAlign: 'center', color: 'var(--text-muted)', fontSize: 12 }}>
              无匹配结果
            </div>
          ) : (
            results.map((s, i) => {
              const isFav = favorites.includes(s.symbol);
              const isRecent = !query && recent.includes(s.symbol);
              const isActive = i === activeIdx;
              return (
                <div
                  key={s.symbol}
                  role="option"
                  aria-selected={isActive}
                  onClick={() => handleSelect(s.symbol)}
                  onMouseEnter={() => setActiveIdx(i)}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 10,
                    padding: '8px 14px',
                    cursor: 'pointer',
                    background: isActive ? 'var(--terminal-bg-3, var(--muted))' : 'transparent',
                    transition: 'background 80ms',
                  }}
                >
                  <span style={{ fontSize: 18, width: 22, textAlign: 'center' }}>
                    {s.icon ?? s.symbol[0]}
                  </span>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 6,
                        fontSize: 12,
                        fontFamily: 'var(--font-data)',
                      }}
                    >
                      <span style={{ color: 'var(--foreground)', fontWeight: 600 }}>{s.symbol}</span>
                      {s.nameZh && (
                        <span style={{ color: 'var(--text-muted)', fontSize: 11 }}>{s.nameZh}</span>
                      )}
                      {s.name && (
                        <span style={{ color: 'var(--text-hint)', fontSize: 11 }}>· {s.name}</span>
                      )}
                    </div>
                    {s.tags && s.tags.length > 0 && (
                      <div style={{ display: 'flex', gap: 4, marginTop: 2 }}>
                        {s.tags.slice(0, 3).map((t) => (
                          <span
                            key={t}
                            style={{
                              fontSize: 9,
                              padding: '0 5px',
                              borderRadius: 2,
                              background: 'var(--terminal-bg-3, var(--muted))',
                              color: 'var(--text-muted)',
                            }}
                          >
                            {t}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                  {s.price != null && (
                    <span
                      style={{
                        fontSize: 11,
                        fontFamily: 'var(--font-data)',
                        color: 'var(--muted-foreground)',
                        fontVariantNumeric: 'tabular-nums',
                      }}
                    >
                      ${s.price.toLocaleString()}
                    </span>
                  )}
                  {s.changePct != null && (
                    <span
                      style={{
                        fontSize: 11,
                        fontFamily: 'var(--font-data)',
                        color: s.changePct >= 0 ? 'var(--quote-up)' : 'var(--quote-down)',
                        fontVariantNumeric: 'tabular-nums',
                        minWidth: 50,
                        textAlign: 'right',
                      }}
                    >
                      {s.changePct >= 0 ? '+' : ''}
                      {s.changePct.toFixed(2)}%
                    </span>
                  )}
                  {isRecent && !isFav && (
                    <span style={{ fontSize: 9, color: 'var(--text-hint)' }}>最近</span>
                  )}
                  {onToggleFavorite && (
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        onToggleFavorite(s.symbol);
                      }}
                      aria-label={isFav ? '取消收藏' : '收藏'}
                      style={{
                        background: 'transparent',
                        border: 'none',
                        cursor: 'pointer',
                        padding: 4,
                        color: isFav ? 'var(--alert-warn, gold)' : 'var(--text-hint)',
                        fontSize: 14,
                      }}
                    >
                      {isFav ? '★' : '☆'}
                    </button>
                  )}
                </div>
              );
            })
          )}
        </div>
        <div
          style={{
            borderTop: '1px solid var(--border)',
            padding: '6px 14px',
            fontSize: 10,
            color: 'var(--text-hint)',
            display: 'flex',
            gap: 12,
            fontFamily: 'var(--font-data)',
          }}
        >
          <span>↑↓ 导航</span>
          <span>↵ 选择</span>
          <span>ESC 清空</span>
        </div>
      </div>
    );
  }
);

OSymbolSearch.displayName = 'OSymbolSearch';

export { DEFAULT_SYMBOLS as HELIOS_DEFAULT_SYMBOLS };
