/**
 * OEpistemicBadge — 认识论可信度徽标(认识论原语,跨项目通用)。
 *
 * 视觉规范硬编码,各项目不允许覆盖 grade→color/icon 映射:
 *   - proven 永远是深绿稳定方块(最显眼安全色)
 *   - unverified 永远是黄色问号方块(警示色,跟 proven 视觉差异最大)
 *   - contradicted 永远是红色 ×(明确反证)
 *
 * 红线 #1 自动满足:proven 和 unverified 一眼可辨。
 * 红线 #6 满足:compact 模式只省 label 文字,视觉差异不变。
 *
 * 来源:AII-FRONTEND-REQ-001 §0 红线 #1, #6。
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import {
  EPISTEMIC_GRADE_LABEL,
  EPISTEMIC_GRADE_ICON,
  type EpistemicGrade,
} from '../../types/epistemic';
import { useUiLang } from '../../lang/LangProvider';
import type { OBlockBaseProps } from '../../lib/types';

export interface OEpistemicBadgeProps extends Omit<OBlockBaseProps, 'variant'> {
  grade: EpistemicGrade;
  /** 反证数(>0 时显示 "⚠ N 反证")。 */
  defeaterCount?: number;
  /** 证据来源 hint(在 title attribute 显示,鼠标悬停可见)。 */
  source?: string;
  /** 紧凑模式(移动端列表/紧凑表格用)— 只显徽标,文字 label 隐藏。 */
  compact?: boolean;
  /** 是否显示文字 label(默认 true,compact=true 时强制 false)。 */
  showLabel?: boolean;
  /** 点击展开 popover(项目自管 popover 渲染)。 */
  onClick?: () => void;
  /** 自定义 aria-label(默认 "认识论可信度: {label}")。 */
  ariaLabel?: string;
}

/**
 * 视觉规范(硬编码,各项目不可覆盖):
 *   每个 grade 同时由:实心/空心、形状、颜色 三维度区分。
 *   即使色盲也能通过形状区分 unverified(? 问号) 和 proven(✓ 勾)。
 */
type GradeVisual = {
  /** 主色 CSS var。 */
  colorVar: string;
  /** 文字 / icon 色(深底浅字 / 浅底深字)。 */
  fgVar: string;
  /** 是否实心(实心 = 高置信度;空心 = 低置信度)。 */
  filled: boolean;
  /** 形状(square / circle / question / cross / pause)— a11y / 色盲冗余通道。 */
  shape: 'square' | 'circle' | 'question' | 'cross' | 'pause' | 'half-circle';
};

const GRADE_VISUAL: Record<EpistemicGrade, GradeVisual> = {
  proven:               { colorVar: '--success',         fgVar: '#fff',                 filled: true,  shape: 'square' },
  high:                 { colorVar: '--info',            fgVar: '#fff',                 filled: true,  shape: 'circle' },
  moderate:             { colorVar: '--info',            fgVar: 'var(--info)',          filled: false, shape: 'half-circle' },
  low:                  { colorVar: '--muted-foreground',fgVar: 'var(--muted-foreground)', filled: false, shape: 'circle' },
  very_low:             { colorVar: '--muted-foreground',fgVar: 'var(--muted-foreground)', filled: false, shape: 'circle' },
  unverified:           { colorVar: '--warning',         fgVar: 'var(--warning)',       filled: false, shape: 'question' },
  contradicted:         { colorVar: '--destructive',     fgVar: '#fff',                 filled: true,  shape: 'cross' },
  pending_verification: { colorVar: '--warning',         fgVar: '#fff',                 filled: true,  shape: 'pause' },
};

export const OEpistemicBadge = forwardRef<HTMLButtonElement | HTMLSpanElement, OEpistemicBadgeProps>(
  function OEpistemicBadge(
    {
      grade,
      defeaterCount = 0,
      source,
      compact = false,
      showLabel: showLabelProp,
      onClick,
      ariaLabel,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const { tr } = useUiLang();
    const visual = GRADE_VISUAL[grade];
    const labelPair = EPISTEMIC_GRADE_LABEL[grade];
    const label = tr(labelPair.zh, labelPair.en);
    const icon = EPISTEMIC_GRADE_ICON[grade];
    const showLabel = compact ? false : (showLabelProp ?? true);
    const hasDefeaters = defeaterCount > 0;

    const a11yLabel =
      ariaLabel ??
      `${tr('认识论可信度', 'Epistemic confidence')}: ${label}${hasDefeaters ? ` ${tr('反证', 'defeaters')} ${defeaterCount} ${tr('条', '')}`.trimEnd() : ''}${source ? ` ${tr('来源', 'source')} ${source}` : ''}`;

    const title = `${label}${source ? ` · ${source}` : ''}${hasDefeaters ? ` · ${tr('反证', 'defeaters')} ${defeaterCount}` : ''}`;

    const styleFilled: React.CSSProperties = {
      backgroundColor: `var(${visual.colorVar})`,
      color: visual.fgVar,
      borderColor: `var(${visual.colorVar})`,
    };
    const styleOutline: React.CSSProperties = {
      backgroundColor: 'transparent',
      color: visual.fgVar,
      borderColor: `var(${visual.colorVar})`,
    };
    const stylePartial: React.CSSProperties = {
      // half-circle: 用左半深、右半浅的渐变模拟"中等填充"
      background: `linear-gradient(90deg, var(${visual.colorVar}) 50%, transparent 50%)`,
      color: visual.fgVar,
      borderColor: `var(${visual.colorVar})`,
    };
    const style =
      visual.shape === 'half-circle' ? stylePartial : (visual.filled ? styleFilled : styleOutline);

    const Wrapper = onClick ? 'button' : 'span';
    const wrapperProps = onClick
      ? { type: 'button' as const, onClick }
      : {};

    return (
      <Wrapper
        ref={ref as React.Ref<HTMLButtonElement & HTMLSpanElement>}
        {...wrapperProps}
        aria-label={a11yLabel}
        title={title}
        className={cn(
          'inline-flex items-center gap-1 text-xs font-mono leading-none @container',
          'border',
          // 形状:square / circle / question / cross / pause
          visual.shape === 'square' && 'rounded-sm',
          (visual.shape === 'circle' || visual.shape === 'half-circle') && 'rounded-full',
          visual.shape === 'question' && 'rounded-sm',
          visual.shape === 'cross' && 'rounded-sm',
          visual.shape === 'pause' && 'rounded',
          compact ? 'px-1 py-0.5' : 'px-1.5 py-0.5',
          // unverified 必须警示 — 加 ring 增强视觉醒目度
          grade === 'unverified' && 'ring-1 ring-[color:var(--warning)]/40',
          grade === 'contradicted' && 'ring-1 ring-[color:var(--destructive)]/40',
          // 交互态
          onClick && 'cursor-pointer hover:opacity-80 focus:outline-none focus-visible:ring-2 focus-visible:ring-ring focus:ring-2 focus:ring-[color:var(--ring)]/60',
          className
        )}
        style={style}
      >
        <span aria-hidden="true" className="inline-block w-3 text-center">
          {icon}
        </span>
        {showLabel && <span>{label}</span>}
        {hasDefeaters && (
          <span
            aria-hidden="true"
            className="ml-0.5 inline-flex items-center gap-0.5"
            style={{ color: 'var(--destructive)' }}
          >
            ⚠{defeaterCount}
          </span>
        )}
      </Wrapper>
    );
  }
);

OEpistemicBadge.displayName = 'OEpistemicBadge';
