/**
 * OStackFrame - 垂直/水平堆叠容器 (最常用 Frame)。
 *
 * SPEC §4 空容器 / 不持业务数据。
 *
 * @example
 * <OStackFrame direction="vertical" gap="md">
 *   <OKPICard data={kpi1} />
 *   <OKPICard data={kpi2} />
 * </OStackFrame>
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, type HTMLAttributes } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

const stackVariants = cva('flex relative', {
  variants: {
    direction: {
      vertical: 'flex-col',
      horizontal: 'flex-row',
    },
    gap: {
      none: 'gap-0',
      xs: 'gap-1',
      sm: 'gap-2',
      md: 'gap-4',
      lg: 'gap-6',
      xl: 'gap-8',
    },
    align: {
      start: 'items-start',
      center: 'items-center',
      end: 'items-end',
      stretch: 'items-stretch',
      baseline: 'items-baseline',
    },
    justify: {
      start: 'justify-start',
      center: 'justify-center',
      end: 'justify-end',
      between: 'justify-between',
      around: 'justify-around',
      evenly: 'justify-evenly',
    },
    wrap: {
      true: 'flex-wrap',
      false: 'flex-nowrap',
    },
  },
  defaultVariants: {
    direction: 'vertical',
    gap: 'md',
    align: 'stretch',
    justify: 'start',
    wrap: false,
  },
});

type StackVariantProps = VariantProps<typeof stackVariants>;

export interface OStackFrameProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'dir'>,
    StackVariantProps,
    Omit<OBlockBaseProps, 'variant'> {
  /** as: 渲染为指定 HTML tag,默认 div。 */
  as?: 'div' | 'section' | 'article' | 'aside' | 'nav';
}

export const OStackFrame = forwardRef<HTMLDivElement, OStackFrameProps>(function OStackFrame(
  {
    direction,
    gap,
    align,
    justify,
    wrap,
    as: Tag = 'div',
    className,
    theme: _theme,
    size: _size,
    children,
    ...rest
  },
  ref
) {
  return (
    <Tag
      ref={ref as never}
      className={cn(stackVariants({ direction, gap, align, justify, wrap }), className)}
      {...rest}
    >
      {children}
    </Tag>
  );
});

OStackFrame.displayName = 'OStackFrame';
