/**
 * OConfirmDialog - 危险操作确认弹窗。
 *
 * 基于 OModalFrame。提供标准的"确认 + 取消"交互。
 *
 * @example
 * <OConfirmDialog
 *   open={open}
 *   onCancel={() => setOpen(false)}
 *   onConfirm={async () => { await deleteUser(); setOpen(false); }}
 *   title="Delete user?"
 *   description="This action cannot be undone."
 *   danger
 * />
 */
'use client';

import { forwardRef, useState, type ReactNode } from 'react';
import { OModalFrame } from '../../frames/OModalFrame';
import { cn } from '../../lib/cn';
import { useUiLang } from '../../lang/LangProvider';
import type { OBlockBaseProps } from '../../lib/types';

export interface OConfirmDialogProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  open: boolean;
  onConfirm: () => void | Promise<void>;
  onCancel: () => void;
  title: string;
  description?: ReactNode;
  /** 红色危险风格 (删除/不可逆操作)。 */
  danger?: boolean;
  /** 自定义按钮文本。 */
  confirmLabel?: string;
  cancelLabel?: string;
  /** 自定义 dialog size。 */
  size?: 'sm' | 'md' | 'lg';
}

export const OConfirmDialog = forwardRef<HTMLDivElement, OConfirmDialogProps>(
  function OConfirmDialog(
    {
      open,
      onConfirm,
      onCancel,
      title,
      description,
      danger = false,
      confirmLabel,
      cancelLabel,
      size = 'sm',
      className,
      theme: _t,
    },
    ref
  ) {
    const { tr } = useUiLang();
    const [busy, setBusy] = useState(false);
    const confirmText = confirmLabel ?? tr('确认', 'Confirm');
    const cancelText = cancelLabel ?? tr('取消', 'Cancel');

    async function handleConfirm() {
      try {
        setBusy(true);
        await onConfirm();
      } finally {
        setBusy(false);
      }
    }

    return (
      <OModalFrame
        ref={ref}
        open={open}
        onClose={onCancel}
        size={size}
        ariaLabel={title}
        className={className}
        header={<h2 className="text-base font-bold tracking-[-0.01em]">{title}</h2>}
        body={description ? <div className="text-sm text-muted-foreground">{description}</div> : null}
        footer={
          <>
            <button
              type="button"
              onClick={onCancel}
              disabled={busy}
              className="px-4 py-2 text-sm rounded bg-card border border-border hover:bg-muted text-foreground transition-colors disabled:opacity-50"
            >
              {cancelText}
            </button>
            <button
              type="button"
              onClick={handleConfirm}
              disabled={busy}
              className={cn(
                'px-4 py-2 text-sm rounded font-medium transition-opacity disabled:opacity-50 @container',
                danger
                  ? 'bg-destructive text-destructive-foreground hover:opacity-90'
                  : 'bg-primary text-primary-foreground hover:opacity-90'
              )}
            >
              {busy ? '...' : confirmText}
            </button>
          </>
        }
      />
    );
  }
);

OConfirmDialog.displayName = 'OConfirmDialog';
