/**
 * OPlaybackControl - 时空切片回放控制器 (Helios 杀手锏)。
 *
 * 拖动时间轴,所有接入 TimelineProvider 的 Block 同步回放到那个历史时点。
 * "把市场冻在过去某一秒" 是中国散户最爱的复盘功能,TV 也只在 Pro 版才有。
 *
 * 视觉:
 *   - 顶部:当前时间 + 实时/回放切换
 *   - 中部:时间轴 (range slider)
 *   - 底部:播放控件 (back / pause / play / forward + speed)
 */

'use client';

import { forwardRef, useEffect, useState } from 'react';
import { cn } from '../../lib/cn';
import { useTimeline } from '../../providers/TimelineProvider';
import type { OBlockBaseProps } from '../../lib/types';
import type { TimelineState } from '../../protocols';

export interface OPlaybackControlProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  /** 回放范围 [start, end] (秒)。一般是过去 24h 或最近一周。 */
  range?: [number, number];
  /** 当前回放时间 (受控)。 */
  value?: number | null;
  /** 受控 onChange。 */
  onChange?: (time: number | null) => void;
  /** 显示模式。 */
  variant?: 'full' | 'compact';
}

const SPEED_OPTIONS: TimelineState['speed'][] = [0.5, 1, 2, 4, 8, 16];

function formatTime(ts: number | null): string {
  if (ts == null) return 'LIVE';
  const d = new Date(ts * 1000);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const isToday = d.getTime() >= today.getTime();
  if (isToday) {
    return d.toLocaleTimeString('zh-CN', { hour12: false });
  }
  return d.toLocaleString('zh-CN', { hour12: false });
}

export const OPlaybackControl = forwardRef<HTMLDivElement, OPlaybackControlProps>(
  function OPlaybackControl(
    {
      range: rangeProp,
      value: valueProp,
      onChange,
      variant = 'full',
      className,
      theme: _t,
    },
    ref
  ) {
    const timeline = useTimeline();
    // 检测是否真有 Provider:fallback timeline 的 subscribe 返回空函数,
    // 真实 timeline 才会真正订阅。简单 heuristic:fallback 没 __isFallback 标记。
    // 这里用 useContext 直接判断更可靠 — 但 useTimeline 已封装。
    // 暂用 localState 为权威源,timeline 仅在有 provider + 有效数据时覆盖。

    // 优先用 Provider 状态;无 Provider 时用本地 state
    const [localState, setLocalState] = useState<TimelineState>({
      currentTime: valueProp ?? null,
      range: rangeProp ?? null,
      playState: 'idle',
      speed: 1,
      symbols: [],
    });

    useEffect(() => {
      if (!timeline) return;
      const unsub = timeline.subscribe((s) => setLocalState(s));
      // 初始同步:仅在 timeline 真有 range/currentTime 时覆盖 local
      const ts = timeline.getState();
      if (ts.range != null || ts.currentTime != null) {
        setLocalState(ts);
      }
      // 受控 props 推入 timeline
      if (rangeProp) timeline.setRange(rangeProp[0], rangeProp[1]);
      if (valueProp != null) timeline.seek(valueProp);
      return unsub;
    }, [timeline, rangeProp, valueProp]);

    // localState 是权威源(已包含 timeline subscribe 推过来的更新)
    const state = localState;
    const { currentTime, range, playState, speed } = state;
    const effectiveRange = range ?? rangeProp ?? null;
    const isLive = currentTime == null;

    // ----- 操作 -----

    function seekTo(t: number | null) {
      if (timeline) {
        if (t == null) timeline.exitToLive();
        else timeline.seek(t);
      } else {
        setLocalState((s) => ({ ...s, currentTime: t }));
      }
      onChange?.(t);
    }

    function play() {
      if (timeline) timeline.play();
      else setLocalState((s) => ({ ...s, playState: 'playing' }));
    }

    function pause() {
      if (timeline) timeline.pause();
      else setLocalState((s) => ({ ...s, playState: 'paused' }));
    }

    function setSpeed(s: TimelineState['speed']) {
      if (timeline) timeline.setSpeed(s);
      else setLocalState((cs) => ({ ...cs, speed: s }));
    }

    function step(deltaSec: number) {
      if (!effectiveRange) return;
      const base = currentTime ?? effectiveRange[1];
      const next = Math.max(
        effectiveRange[0],
        Math.min(effectiveRange[1], base + deltaSec)
      );
      seekTo(next);
    }

    const progress = (() => {
      if (!effectiveRange || currentTime == null) return 1;
      const [start, end] = effectiveRange;
      return (currentTime - start) / (end - start);
    })();

    // ----- 视觉 -----

    const Btn = ({ children, onClick, primary = false, ariaLabel }: {
      children: React.ReactNode;
      onClick: () => void;
      primary?: boolean;
      ariaLabel: string;
    }) => (
      <button
        onClick={onClick}
        aria-label={ariaLabel}
        style={{
          background: primary ? 'var(--primary)' : 'var(--terminal-bg-3, var(--muted))',
          color: primary ? 'var(--primary-foreground)' : 'var(--foreground)',
          border: 'none',
          padding: '6px 10px',
          borderRadius: 4,
          cursor: 'pointer',
          fontSize: 11,
          fontFamily: 'var(--font-data)',
          minWidth: 32,
        }}
      >
        {children}
      </button>
    );

    if (variant === 'compact') {
      return (
        <div
          ref={ref}
          className={cn('inline-flex items-center gap-2 px-3 py-1.5 rounded-md border border-border @container', className)}
          style={{ background: 'var(--card)', fontFamily: 'var(--font-data)', fontSize: 11 }}
        >
          <span
            style={{
              color: isLive ? 'var(--quote-up)' : 'var(--foreground)',
              fontWeight: isLive ? 700 : 500,
            }}
          >
            {isLive ? '● LIVE' : formatTime(currentTime)}
          </span>
          {!isLive && (
            <button
              onClick={() => seekTo(null)}
              style={{
                background: 'transparent',
                color: 'var(--primary)',
                border: 'none',
                fontSize: 10,
                cursor: 'pointer',
                padding: 0,
              }}
            >
              回到实时
            </button>
          )}
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn('rounded-md border border-border p-3 flex flex-col gap-3', className)}
        style={{ background: 'var(--card)', fontFamily: 'var(--font-ui)' }}
      >
        {/* 顶部 */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span
            style={{
              fontSize: 13,
              fontWeight: 600,
              color: isLive ? 'var(--quote-up)' : 'var(--foreground)',
              fontFamily: 'var(--font-data)',
            }}
          >
            {isLive ? '● LIVE' : formatTime(currentTime)}
          </span>
          {!isLive && (
            <button
              onClick={() => seekTo(null)}
              style={{
                background: 'transparent',
                color: 'var(--primary)',
                border: '1px solid var(--primary)',
                padding: '3px 10px',
                borderRadius: 4,
                fontSize: 11,
                cursor: 'pointer',
              }}
            >
              回到实时
            </button>
          )}
        </div>

        {/* 时间轴 (range slider) */}
        {effectiveRange ? (
          <div>
            <input
              type="range"
              min={effectiveRange[0]}
              max={effectiveRange[1]}
              value={currentTime ?? effectiveRange[1]}
              onChange={(e) => seekTo(parseInt(e.target.value, 10))}
              style={{
                width: '100%',
                accentColor: 'var(--primary)',
              }}
              aria-label="Timeline scrubber"
            />
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 10, color: 'var(--text-muted)', fontFamily: 'var(--font-data)' }}>
              <span>{formatTime(effectiveRange[0])}</span>
              <span>{(progress * 100).toFixed(0)}%</span>
              <span>{formatTime(effectiveRange[1])}</span>
            </div>
          </div>
        ) : (
          <div style={{ fontSize: 11, color: 'var(--text-muted)', textAlign: 'center' }}>
            未设置时间范围
          </div>
        )}

        {/* 控件 */}
        <div style={{ display: 'flex', gap: 6, alignItems: 'center', justifyContent: 'center' }}>
          <Btn ariaLabel="back 1m" onClick={() => step(-60)}>« 1m</Btn>
          <Btn ariaLabel="back 10s" onClick={() => step(-10)}>« 10s</Btn>
          {playState === 'playing' ? (
            <Btn ariaLabel="pause" onClick={pause} primary>⏸ Pause</Btn>
          ) : (
            <Btn ariaLabel="play" onClick={play} primary>▶ Play</Btn>
          )}
          <Btn ariaLabel="forward 10s" onClick={() => step(10)}>10s »</Btn>
          <Btn ariaLabel="forward 1m" onClick={() => step(60)}>1m »</Btn>
          <div style={{ flex: 1 }} />
          <select
            value={speed}
            onChange={(e) => setSpeed(parseFloat(e.target.value) as TimelineState['speed'])}
            style={{
              background: 'var(--input)',
              color: 'var(--foreground)',
              border: '1px solid var(--border)',
              borderRadius: 4,
              padding: '4px 6px',
              fontSize: 11,
              fontFamily: 'var(--font-data)',
            }}
            aria-label="Speed"
          >
            {SPEED_OPTIONS.map((s) => (
              <option key={s} value={s}>{s}x</option>
            ))}
          </select>
        </div>
      </div>
    );
  }
);

OPlaybackControl.displayName = 'OPlaybackControl';
