/**
 * OMarginIndicator - 保证金率指示器 (合约救命 Block)。
 *
 * 显示当前账户/单仓的保证金率,接近 100% 时变红警告。
 * 合约老炮的"心跳监测",随时知道自己离爆仓多远。
 *
 * 保证金率 = 维持保证金 / 账户余额 × 100%
 *   < 30%   绿色 (安全)
 *   30-60%  黄色 (注意)
 *   60-80%  橙色 (危险)
 *   80-100% 红色 (临近强平)
 *   100%    强平
 */

'use client';

import { forwardRef, useEffect, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { useFastData } from '../../providers/FastDataProvider';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';

export interface OMarginIndicatorData {
  /** 保证金率 (0-1, 例如 0.45 表示 45%). */
  marginRatio: number;
  /** 总钱包余额 USDT. */
  walletBalance: number;
  /** 维持保证金 USDT. */
  maintMargin: number;
  /** 可用余额 USDT. */
  availableBalance: number;
  /** 未实现盈亏总和 USDT. */
  totalUnrealizedPnl?: number;
  /** 已用保证金 USDT (initialMargin). */
  initialMargin?: number;
}

export interface OMarginIndicatorProps
  extends OBlockDataProps<OMarginIndicatorData>,
    Pick<TerminalBlockProps, 'channel' | 'flashOnUpdate' | 'regulation'> {
  /** 紧凑横向布局 (单行). */
  compact?: boolean;
  /** 阈值自定义. */
  thresholds?: {
    safe?: number;  // 默认 0.3
    warn?: number;  // 默认 0.6
    danger?: number; // 默认 0.8
  };
}

function getColor(ratio: number, thresholds: NonNullable<OMarginIndicatorProps['thresholds']>): string {
  const safe = thresholds.safe ?? 0.3;
  const warn = thresholds.warn ?? 0.6;
  const danger = thresholds.danger ?? 0.8;
  if (ratio < safe) return 'var(--quote-up)';
  if (ratio < warn) return 'var(--alert-info)';
  if (ratio < danger) return 'var(--alert-warn)';
  return 'var(--quote-down)';
}

function getLabel(ratio: number): string {
  if (ratio < 0.3) return '安全';
  if (ratio < 0.6) return '注意';
  if (ratio < 0.8) return '危险';
  if (ratio < 1) return '临近强平';
  return '已强平';
}

export const OMarginIndicator = forwardRef<HTMLDivElement, OMarginIndicatorProps>(
  function OMarginIndicator(
    {
      data: dataProp,
      loading,
      error,
      empty,
      channel,
      compact = false,
      thresholds = {},
      flashOnUpdate: _f,
      regulation: _r,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OMarginIndicatorData | null>(null);
    useEffect(() => {
      if (!channel || !fastData) return;
      return fastData.subscribe<OMarginIndicatorData>(channel, setChannelData);
    }, [channel, fastData]);

    const data = channel ? channelData : (dataProp ?? null);
    const state = resolveBlockState({ data, loading, error, empty });

    if (state === 'loading')
      return (
        <div ref={ref} className={cn('rounded-md border border-border bg-card p-3', className)}>
          <OLoadingState rows={2} rowHeight="1rem" />
        </div>
      );
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data) return null;

    const pct = Math.min(data.marginRatio * 100, 100);
    const color = getColor(data.marginRatio, thresholds);
    const label = getLabel(data.marginRatio);
    const isDangerous = data.marginRatio >= (thresholds.danger ?? 0.8);

    if (compact) {
      return (
        <div
          ref={ref}
          className={cn(
            'flex items-center gap-3 px-3 py-2 rounded-md border bg-card @container',
            className
          )}
          style={{
            borderColor: isDangerous ? color : 'var(--border)',
            fontFamily: 'var(--font-data)',
          }}
        >
          <div className="flex items-baseline gap-1">
            <span className="text-[10px] text-[color:var(--text-muted)]">保证金率</span>
            <span className="tabular-nums text-sm font-mono font-bold" style={{ color }}>
              {pct.toFixed(2)}%
            </span>
            <span className="text-[10px] font-mono" style={{ color }}>{label}</span>
          </div>
          {/* 进度条 */}
          <div className="flex-1 h-1.5 rounded bg-muted overflow-hidden min-w-[60px]">
            <div
              className="h-full transition-[width]"
              style={{ width: `${pct}%`, background: color }}
            />
          </div>
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border bg-card p-3',
          className
        )}
        style={{
          borderColor: isDangerous ? color : 'var(--border)',
          fontFamily: 'var(--font-ui)',
          boxShadow: isDangerous ? `0 0 0 1px ${color}` : undefined,
        }}
      >
        <div className="flex items-baseline justify-between mb-1">
          <span className="text-[10px] text-[color:var(--text-muted)] uppercase tracking-[0.04em]">
            保证金率
          </span>
          <span className="text-[10px] font-mono" style={{ color }}>
            {label}
          </span>
        </div>

        <div
          className="text-2xl font-extrabold tracking-[-0.03em] tabular-nums"
          style={{ color, fontFamily: 'var(--font-data)' }}
        >
          {pct.toFixed(2)}%
        </div>

        {/* 进度条 */}
        <div className="mt-2 h-2 rounded bg-muted overflow-hidden">
          <div
            className="h-full transition-[width]"
            style={{ width: `${pct}%`, background: color }}
          />
        </div>

        {/* 详情 */}
        <div className="mt-3 pt-2 border-t border-border/50 grid grid-cols-2 gap-2 text-[11px]">
          <div>
            <div className="text-[color:var(--text-muted)]">钱包余额</div>
            <div className="tabular-nums font-mono">{data.walletBalance.toFixed(2)} USDT</div>
          </div>
          <div>
            <div className="text-[color:var(--text-muted)]">可用</div>
            <div className="tabular-nums font-mono">{data.availableBalance.toFixed(2)}</div>
          </div>
          <div>
            <div className="text-[color:var(--text-muted)]">维持保证金</div>
            <div className="tabular-nums font-mono">{data.maintMargin.toFixed(2)}</div>
          </div>
          {typeof data.totalUnrealizedPnl === 'number' ? (
            <div>
              <div className="text-[color:var(--text-muted)]">未实现 PnL</div>
              <div
                className="tabular-nums font-mono"
                style={{
                  color:
                    data.totalUnrealizedPnl >= 0 ? 'var(--quote-up)' : 'var(--quote-down)',
                }}
              >
                {data.totalUnrealizedPnl >= 0 ? '+' : ''}
                {data.totalUnrealizedPnl.toFixed(2)}
              </div>
            </div>
          ) : null}
        </div>
      </div>
    );
  }
);

OMarginIndicator.displayName = 'OMarginIndicator';
