'use client';
import { forwardRef, type HTMLAttributes } from 'react';
import { cn } from '../../lib/cn';
import { alertRecipe, type AlertRecipeProps } from '../../recipes';
export interface OAlertProps extends HTMLAttributes<HTMLDivElement>, AlertRecipeProps {
  icon?: React.ReactNode;
  title?: string;
}
export const OAlert = forwardRef<HTMLDivElement, OAlertProps>(
  function OAlert({ className, variant, icon, title, children, ...props }, ref) {
    return (
      <div ref={ref} role="alert" className={cn(alertRecipe({ variant }), className)} {...props}>
        {icon}
        <div className="flex flex-col gap-0.5">
          {title && <div className="font-[number:var(--fw-semibold)]">{title}</div>}
          {children && <div className="text-[color:var(--muted-foreground)]">{children}</div>}
        </div>
      </div>
    );
  }
);
OAlert.displayName = 'OAlert';
