/**
 * OFusionExplanation (Tide Wave 2 E14, Block)
 *
 * Fusion Score 元能力解释。
 * 来源:OUI_WAVE_2_REQUIREMENTS_v1.0.md §11
 */
import { forwardRef, useMemo } from 'react';
import { cn } from '../../lib/cn';
import { REGIME_LABEL, type RegimeState } from '../../types/tide';
import type { OBlockBaseProps } from '../../lib/types';

export interface DimContribution {
  dimName: string;
  rawScore: number;
  baseWeight: number;
  multiplier: number;
  weightUsed: number;
  contribution: number;
  isBoosted: boolean;
  isDampened: boolean;
  subExplanation?: string;
}

export interface OFusionExplanationProps extends Omit<OBlockBaseProps, 'variant'> {
  fusionScore: number;
  dimContributions: DimContribution[];
  regime: RegimeState;
  expandable?: boolean;
  onDimClick?: (dim: string) => void;
}

export const OFusionExplanation = forwardRef<HTMLDivElement, OFusionExplanationProps>(
  function OFusionExplanation(
    {
      fusionScore,
      dimContributions,
      regime,
      expandable,
      onDimClick,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const computedSum = useMemo(
      () => dimContributions.reduce((s, d) => s + d.contribution, 0),
      [dimContributions]
    );
    const mismatch = Math.abs(computedSum - fusionScore) > 0.5;

    return (
      <div
        ref={ref}
        className={cn(
          'flex flex-col gap-1.5 px-3 py-2 rounded @container',
          'bg-[color:var(--card)] border border-[color:var(--border-strong)]',
          className
        )}
        style={{ fontFamily: 'var(--font-mono)' }}
        role="region"
        aria-label={`Fusion ${fusionScore.toFixed(0)} 解释`}
      >
        <div
          className="text-xs uppercase tracking-[0.04em]"
          style={{ color: 'var(--muted-foreground)' }}
        >
          为什么是 {fusionScore.toFixed(0)} 分?({REGIME_LABEL[regime]} regime)
        </div>

        <ul className="flex flex-col gap-1 list-none p-0 m-0">
          {dimContributions.map((d, i) => {
            const color = d.isBoosted
              ? 'var(--red-up)'
              : d.isDampened
              ? 'var(--text-tertiary)'
              : 'var(--foreground)';
            const clickable = expandable && onDimClick;
            const Wrapper = clickable ? 'button' : 'div';
            const wrapperProps = clickable
              ? {
                  type: 'button' as const,
                  onClick: () => onDimClick!(d.dimName),
                }
              : {};
            return (
              <li key={i}>
                <Wrapper
                  {...wrapperProps}
                  className={cn(
                    'w-full text-left text-xs flex flex-col gap-0.5',
                    clickable && 'hover:bg-[color:var(--accent)] px-1 py-0.5 rounded cursor-pointer'
                  )}
                >
                  <div className="flex items-center justify-between">
                    <span
                      style={{
                        color,
                        fontWeight: d.isBoosted ? 600 : 400,
                        fontFamily: 'var(--font-sans)',
                      }}
                    >
                      {d.dimName}
                    </span>
                    <span style={{ color }}>
                      {d.rawScore.toFixed(0)} × {d.multiplier.toFixed(1)}
                      {' = '}
                      <span style={{ fontWeight: 700 }}>{d.contribution.toFixed(1)}</span>
                    </span>
                  </div>
                  {d.subExplanation && (
                    <div
                      className="text-[10px]"
                      style={{ color: 'var(--text-tertiary)' }}
                    >
                      {d.subExplanation}
                    </div>
                  )}
                </Wrapper>
              </li>
            );
          })}
        </ul>

        <div
          className="flex items-center justify-between pt-1.5 border-t border-[color:var(--border-subtle)]"
        >
          <span
            className="text-xs uppercase tracking-[0.04em]"
            style={{ color: 'var(--muted-foreground)' }}
          >
            合计
          </span>
          <span
            className="text-base font-bold"
            style={{ color: 'var(--foreground)' }}
          >
            {fusionScore.toFixed(0)}
          </span>
        </div>

        {mismatch && (
          <div
            role="alert"
            className="text-[10px] px-2 py-0.5 rounded"
            style={{
              backgroundColor: 'color-mix(in srgb, var(--red-up) 15%, transparent)',
              color: 'var(--red-up)',
            }}
          >
            ⚠ 数学不一致 ({computedSum.toFixed(1)} vs {fusionScore.toFixed(0)})
          </div>
        )}
      </div>
    );
  }
);

OFusionExplanation.displayName = 'OFusionExplanation';
