/**
 * useTouchGesture - 统一触摸手势识别 hook。
 *
 * 加密散户在移动端的高频手势:
 *   - swipeLeft/Right    在自选股之间切换
 *   - swipeUp/Down       拉出 K 线全屏 / 收起 BottomSheet
 *   - pinch              K 线缩放
 *   - longPress          调出快捷菜单 (买入/卖出/设警报)
 *   - doubleTap          重置缩放
 *
 * 不依赖任何第三方库,自实现轻量版 (2KB)。
 * @use-gesture/react 更全面但 24KB,Helios 用不到全部功能。
 *
 * 用法:
 *   const ref = useTouchGesture<HTMLDivElement>({
 *     onSwipe: (dir) => console.log(dir),
 *     onLongPress: () => openMenu(),
 *     onPinch: (scale) => zoom(scale),
 *   });
 *   return <div ref={ref}>...</div>;
 */

'use client';

import { useEffect, useRef, useCallback } from 'react';

export type SwipeDirection = 'left' | 'right' | 'up' | 'down';

export interface TouchGestureConfig {
  /** Swipe (滑动) 触发。 */
  onSwipe?: (
    direction: SwipeDirection,
    detail: { distance: number; velocity: number; duration: number }
  ) => void;
  /** 长按触发 (默认 500ms)。 */
  onLongPress?: (point: { x: number; y: number }) => void;
  /** 双击触发 (双击间隔 < 300ms)。 */
  onDoubleTap?: (point: { x: number; y: number }) => void;
  /** Pinch 缩放 (scale: 1 = 起始,> 1 放大,< 1 缩小)。 */
  onPinch?: (scale: number, detail: { center: { x: number; y: number } }) => void;
  /** Pinch 结束 (回调最终 scale)。 */
  onPinchEnd?: (scale: number) => void;

  /** swipe 最小距离 (px),默认 40。 */
  swipeThreshold?: number;
  /** longPress 时长 (ms),默认 500。 */
  longPressDelay?: number;
  /** 是否阻止默认 touch 事件 (防止页面滚动)。默认 false (按需开启)。 */
  preventDefault?: boolean;
  /** 启用 haptic 反馈 (long-press 时短震)。默认 true。 */
  haptic?: boolean;
}

interface TouchState {
  startX: number;
  startY: number;
  startTime: number;
  startDist: number; // pinch 初始两指距离
  lastTapTime: number;
  longPressTimer: number | null;
  isPinching: boolean;
  pinchScale: number;
  moved: boolean;
}

function dist(t1: Touch, t2: Touch): number {
  const dx = t1.clientX - t2.clientX;
  const dy = t1.clientY - t2.clientY;
  return Math.sqrt(dx * dx + dy * dy);
}

function center(t1: Touch, t2: Touch): { x: number; y: number } {
  return {
    x: (t1.clientX + t2.clientX) / 2,
    y: (t1.clientY + t2.clientY) / 2,
  };
}

const DOUBLE_TAP_WINDOW = 300;
const TAP_MOVE_TOLERANCE = 8;

/**
 * 返回一个 ref callback,挂到目标元素。
 */
export function useTouchGesture<E extends HTMLElement = HTMLElement>(
  config: TouchGestureConfig
): React.RefCallback<E> {
  // 注:onSwipe / onLongPress / onDoubleTap / onPinch / onPinchEnd
  // 通过 cfgRef.current.* 在 closure 内访问 (避免 stale closure),
  // 不在这里解构。
  const {
    swipeThreshold = 40,
    longPressDelay = 500,
    preventDefault = false,
    haptic = true,
  } = config;

  const elRef = useRef<E | null>(null);
  const stateRef = useRef<TouchState>({
    startX: 0,
    startY: 0,
    startTime: 0,
    startDist: 0,
    lastTapTime: 0,
    longPressTimer: null,
    isPinching: false,
    pinchScale: 1,
    moved: false,
  });

  // 永远拿最新 config 的 callbacks (避免 closure 陷阱)
  const cfgRef = useRef(config);
  useEffect(() => {
    cfgRef.current = config;
  }, [config]);

  useEffect(() => {
    const el = elRef.current;
    if (!el) return;

    const s = stateRef.current;

    function clearLongPress() {
      if (s.longPressTimer != null) {
        clearTimeout(s.longPressTimer);
        s.longPressTimer = null;
      }
    }

    function handleTouchStart(e: TouchEvent) {
      if (preventDefault) e.preventDefault();
      const touches = e.touches;

      if (touches.length === 1) {
        // 单指: 可能是 tap / swipe / long-press
        const t = touches[0]!;
        s.startX = t.clientX;
        s.startY = t.clientY;
        s.startTime = Date.now();
        s.moved = false;
        s.isPinching = false;

        // long-press 计时
        if (cfgRef.current.onLongPress) {
          clearLongPress();
          s.longPressTimer = window.setTimeout(() => {
            if (!s.moved) {
              if (haptic && navigator.vibrate) navigator.vibrate(20);
              cfgRef.current.onLongPress?.({ x: s.startX, y: s.startY });
            }
          }, longPressDelay);
        }
      } else if (touches.length === 2) {
        // 双指: pinch 开始
        clearLongPress();
        s.isPinching = true;
        s.startDist = dist(touches[0]!, touches[1]!);
        s.pinchScale = 1;
      }
    }

    function handleTouchMove(e: TouchEvent) {
      if (preventDefault) e.preventDefault();
      const touches = e.touches;

      if (s.isPinching && touches.length === 2) {
        const newDist = dist(touches[0]!, touches[1]!);
        s.pinchScale = newDist / s.startDist;
        cfgRef.current.onPinch?.(s.pinchScale, {
          center: center(touches[0]!, touches[1]!),
        });
        return;
      }

      if (touches.length === 1) {
        const t = touches[0]!;
        const dx = t.clientX - s.startX;
        const dy = t.clientY - s.startY;
        const moved = Math.abs(dx) > TAP_MOVE_TOLERANCE || Math.abs(dy) > TAP_MOVE_TOLERANCE;
        if (moved) {
          s.moved = true;
          clearLongPress();
        }
      }
    }

    function handleTouchEnd(e: TouchEvent) {
      clearLongPress();

      if (s.isPinching && e.touches.length < 2) {
        cfgRef.current.onPinchEnd?.(s.pinchScale);
        s.isPinching = false;
        return;
      }

      if (e.touches.length > 0) return; // 多指还未全抬起

      const duration = Date.now() - s.startTime;
      const changed = e.changedTouches[0];
      if (!changed) return;

      const dx = changed.clientX - s.startX;
      const dy = changed.clientY - s.startY;
      const absX = Math.abs(dx);
      const absY = Math.abs(dy);
      const distance = Math.max(absX, absY);

      // Swipe 判定
      if (distance > swipeThreshold && cfgRef.current.onSwipe) {
        const velocity = distance / Math.max(duration, 1);
        let dir: SwipeDirection;
        if (absX > absY) dir = dx > 0 ? 'right' : 'left';
        else dir = dy > 0 ? 'down' : 'up';
        cfgRef.current.onSwipe(dir, { distance, velocity, duration });
        return;
      }

      // Tap / double-tap (没有 moved 且 duration < 250ms)
      if (!s.moved && duration < 250) {
        const now = Date.now();
        if (cfgRef.current.onDoubleTap && now - s.lastTapTime < DOUBLE_TAP_WINDOW) {
          cfgRef.current.onDoubleTap({ x: changed.clientX, y: changed.clientY });
          s.lastTapTime = 0;
        } else {
          s.lastTapTime = now;
        }
      }
    }

    function handleTouchCancel() {
      clearLongPress();
      s.isPinching = false;
      s.moved = false;
    }

    // passive: !preventDefault 这样能滚动的页面不被打断
    const opts = { passive: !preventDefault };
    el.addEventListener('touchstart', handleTouchStart, opts);
    el.addEventListener('touchmove', handleTouchMove, opts);
    el.addEventListener('touchend', handleTouchEnd);
    el.addEventListener('touchcancel', handleTouchCancel);

    return () => {
      clearLongPress();
      el.removeEventListener('touchstart', handleTouchStart);
      el.removeEventListener('touchmove', handleTouchMove);
      el.removeEventListener('touchend', handleTouchEnd);
      el.removeEventListener('touchcancel', handleTouchCancel);
    };
  }, [preventDefault, swipeThreshold, longPressDelay, haptic]);

  return useCallback((el: E | null) => {
    elRef.current = el;
  }, []);
}
