/**
 * OJsonViewer — 大型 JSON 结构化展示
 *
 * 来源:Helivex 经理人 R1 §4.1(决策 JSON 详情)+ 跨项目共需
 *   - Helivex: dashboard/decisions/[eventId] 决策 JSON dump(faithfulness_evidence 含 5-10k LLM trace)
 *   - Stratum: agent_run output JSON
 *   - Aegis: incident playbook diff + dry_run preview
 *   - hevi: run trail.jsonl
 *
 * 设计参考(横向对标):
 *   - Apple Console.app "渐进展开" — 默认折叠 > 3 字段 object
 *   - Chrome DevTools — 虚拟滚动 + 懒加载大 JSON
 *   - react-json-view 系列库 — 我们不直接用因为缺 typeHints + virtualization
 *   - @tanstack/react-virtual — 已在 deps,免新增依赖
 *
 * 关键创新(业界没有现成方案):
 *   - **typeHints 字段**:路径 → 注释 map,在 key 旁显示 ⚠️ 提示
 *     (Helivex 经理人显式需求 — `signature` 旁显示 "NULL = SILVER tier")
 *   - **virtualization**:5-10k LLM trace 不卡浏览器
 *   - **longStringThreshold**:超长字符串 truncate + 展开
 *
 * a11y:
 *   - role="tree" + role="treeitem"
 *   - aria-expanded for 可折叠节点
 *   - aria-level 反映嵌套深度
 */
'use client';

import { useVirtualizer } from '@tanstack/react-virtual';
import { forwardRef, useMemo, useRef, useState, useCallback } from 'react';
import { cn } from '../../lib/cn';
import { useUiLang } from '../../lang/LangProvider';
import type { OBlockBaseProps } from '../../lib/types';

// ============================================================
// 内部扁平化数据结构
// ============================================================

type JsonNodeKind =
  | 'object-open'    // { 行
  | 'object-close'   // } 行
  | 'array-open'     // [ 行
  | 'array-close'    // ] 行
  | 'leaf';          // 叶子节点(string/number/boolean/null)

interface FlatNode {
  /** 唯一 id(在扁平数组中) */
  id: number;
  /** dot 路径(根 = ''),用于 typeHints 匹配 */
  path: string;
  /** 该行的 key(object 内的属性名,或 array index)。根 = null */
  keyLabel: string | null;
  /** 嵌套深度(0 = 根)*/
  depth: number;
  /** 节点种类 */
  kind: JsonNodeKind;
  /** 叶子值(kind='leaf' 时有效)*/
  value?: unknown;
  /** 对应的展开 / 折叠节点 id(open ↔ close 配对)*/
  pairId?: number;
  /** 摘要(折叠时显示):"3 keys" / "12 items" */
  summary?: string;
}

// ============================================================
// 把树扁平化(深度优先,object-open / leaf / object-close 顺序排)
// ============================================================

function flattenJson(data: unknown): FlatNode[] {
  const nodes: FlatNode[] = [];
  let idCounter = 0;

  function walk(value: unknown, path: string, keyLabel: string | null, depth: number): void {
    if (value === null || typeof value !== 'object') {
      // leaf
      nodes.push({
        id: idCounter++,
        path,
        keyLabel,
        depth,
        kind: 'leaf',
        value,
      });
      return;
    }

    if (Array.isArray(value)) {
      const openId = idCounter++;
      const summary = `${value.length} items`;
      nodes.push({
        id: openId,
        path,
        keyLabel,
        depth,
        kind: 'array-open',
        summary,
        pairId: -1, // 待回填
      });
      value.forEach((item, idx) => {
        walk(item, path ? `${path}.${idx}` : String(idx), String(idx), depth + 1);
      });
      const closeId = idCounter++;
      nodes.push({
        id: closeId,
        path,
        keyLabel: null,
        depth,
        kind: 'array-close',
        pairId: openId,
      });
      nodes[openId]!.pairId = closeId;
      return;
    }

    // object
    const entries = Object.entries(value as Record<string, unknown>);
    const openId = idCounter++;
    const summary = `${entries.length} keys`;
    nodes.push({
      id: openId,
      path,
      keyLabel,
      depth,
      kind: 'object-open',
      summary,
      pairId: -1,
    });
    for (const [k, v] of entries) {
      walk(v, path ? `${path}.${k}` : k, k, depth + 1);
    }
    const closeId = idCounter++;
    nodes.push({
      id: closeId,
      path,
      keyLabel: null,
      depth,
      kind: 'object-close',
      pairId: openId,
    });
    nodes[openId]!.pairId = closeId;
  }

  walk(data, '', null, 0);
  return nodes;
}

// ============================================================
// Props
// ============================================================

export interface OJsonViewerProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  /** JSON 数据(任意 shape) */
  data: unknown;

  /**
   * 默认展开深度。
   * 0 = 全折叠,1 = 只展开根,Infinity = 全展开。
   * 默认 2(根 + 1 层子)。
   */
  defaultExpandDepth?: number;

  /**
   * 长字符串截断阈值(字符数)。
   * 超过显示"... 查看完整" 按钮。
   * 默认 500。
   */
  longStringThreshold?: number;

  /**
   * 路径 → 类型提示注释 map。
   *
   * 例(Helivex):
   *   typeHints={{
   *     'signature': 'NULL = SILVER tier(不是签名缺失)',
   *     'decision_payload.execution_mode': 'shadow / paper / live',
   *   }}
   *
   * 路径用 dot notation(数组索引也用 `.0`,例:`stack_calls.0.function`)。
   */
  typeHints?: Record<string, string>;

  /**
   * 显示 "复制为 JSON" 按钮。默认 true。
   */
  showCopyButton?: boolean;

  /**
   * 容器最大高度(px)。超过启用 virtualization 滚动。
   * 默认 600。
   */
  maxHeight?: number;
}

// ============================================================
// 工具函数 — 渲染 leaf value
// ============================================================

function renderLeafValue(
  value: unknown,
  longStringThreshold: number,
  showFull: boolean
): {
  display: string;
  colorClass: string;
  truncated: boolean;
} {
  if (value === null) {
    return { display: 'null', colorClass: 'text-muted-foreground italic', truncated: false };
  }
  if (typeof value === 'boolean') {
    return { display: String(value), colorClass: 'text-info', truncated: false };
  }
  if (typeof value === 'number') {
    return { display: String(value), colorClass: 'text-warning', truncated: false };
  }
  if (typeof value === 'string') {
    if (value.length > longStringThreshold && !showFull) {
      return {
        display: `"${value.slice(0, longStringThreshold)}..."`,
        colorClass: 'text-success',
        truncated: true,
      };
    }
    return {
      display: `"${value}"`,
      colorClass: 'text-success',
      truncated: false,
    };
  }
  return { display: String(value), colorClass: 'text-foreground', truncated: false };
}

// ============================================================
// 主组件
// ============================================================

export const OJsonViewer = forwardRef<HTMLDivElement, OJsonViewerProps>(
  function OJsonViewer(
    {
      data,
      defaultExpandDepth = 2,
      longStringThreshold = 500,
      typeHints,
      showCopyButton = true,
      maxHeight = 600,
      className,
      theme: _t,
    },
    ref
  ) {
    const { tr } = useUiLang();
    // 扁平化(memo,data 不变时不重建)
    const flatNodes = useMemo(() => flattenJson(data), [data]);

    // 折叠状态:Set<openNodeId>,默认根据 defaultExpandDepth 计算
    const initialCollapsed = useMemo(() => {
      const set = new Set<number>();
      for (const node of flatNodes) {
        if (
          (node.kind === 'object-open' || node.kind === 'array-open') &&
          node.depth >= defaultExpandDepth
        ) {
          set.add(node.id);
        }
      }
      return set;
    }, [flatNodes, defaultExpandDepth]);

    const [collapsed, setCollapsed] = useState<Set<number>>(initialCollapsed);

    // 长字符串展开状态
    const [expandedStrings, setExpandedStrings] = useState<Set<number>>(new Set());

    // 计算可见行 — 跳过折叠区间
    const visibleNodes = useMemo(() => {
      const result: FlatNode[] = [];
      let skipUntilId = -1;
      for (const node of flatNodes) {
        if (skipUntilId !== -1) {
          if (node.id === skipUntilId) {
            skipUntilId = -1; // 到 close,把 close 也跳过
            continue;
          }
          continue; // 折叠区间内,跳过
        }
        result.push(node);
        if (
          (node.kind === 'object-open' || node.kind === 'array-open') &&
          collapsed.has(node.id) &&
          node.pairId !== undefined &&
          node.pairId >= 0
        ) {
          skipUntilId = node.pairId;
        }
      }
      return result;
    }, [flatNodes, collapsed]);

    const toggleCollapse = useCallback((id: number) => {
      setCollapsed((prev) => {
        const next = new Set(prev);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        return next;
      });
    }, []);

    const toggleString = useCallback((id: number) => {
      setExpandedStrings((prev) => {
        const next = new Set(prev);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        return next;
      });
    }, []);

    // 复制按钮
    const handleCopy = useCallback(() => {
      if (typeof navigator !== 'undefined' && navigator.clipboard) {
        navigator.clipboard.writeText(JSON.stringify(data, null, 2));
      }
    }, [data]);

    // virtualization
    const scrollRef = useRef<HTMLDivElement | null>(null);
    const virtualizer = useVirtualizer({
      count: visibleNodes.length,
      getScrollElement: () => scrollRef.current,
      estimateSize: () => 24,
      overscan: 10,
    });

    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card text-sm font-mono @container',
          className
        )}
      >
        {/* 顶部工具栏 */}
        {showCopyButton && (
          <div className="flex items-center justify-between px-3 py-2 border-b border-border">
            <span className="text-xs text-muted-foreground">
              {flatNodes.length} {tr("个节点", "nodes")}
            </span>
            <button
              type="button"
              onClick={handleCopy}
              className={cn(
                'inline-flex items-center gap-1 px-2 py-1 text-xs rounded',
                'border border-border hover:bg-muted',
                'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring'
              )}
              aria-label={tr("复制为 JSON", "Copy as JSON")}
            >
              <svg className="w-3 h-3" viewBox="0 0 16 16" fill="none" aria-hidden="true">
                <rect x="4" y="4" width="9" height="10" rx="1" stroke="currentColor" strokeWidth="1.2" />
                <path d="M3 11V3a1 1 0 011-1h8" stroke="currentColor" strokeWidth="1.2" />
              </svg>
              <span>{tr("复制", "Copy")}</span>
            </button>
          </div>
        )}

        {/* 虚拟滚动容器 */}
        <div
          ref={scrollRef}
          className="overflow-auto"
          style={{ maxHeight }}
          role="tree"
          aria-label={tr("JSON 结构", "JSON structure")}
        >
          <div
            style={{
              height: `${virtualizer.getTotalSize()}px`,
              position: 'relative',
              width: '100%',
            }}
          >
            {virtualizer.getVirtualItems().map((vItem) => {
              const node = visibleNodes[vItem.index]!;
              return (
                <div
                  key={node.id}
                  data-index={vItem.index}
                  ref={virtualizer.measureElement}
                  className="absolute top-0 left-0 w-full"
                  style={{
                    transform: `translateY(${vItem.start}px)`,
                  }}
                >
                  <JsonRow
                    node={node}
                    isCollapsed={collapsed.has(node.id)}
                    isStringExpanded={expandedStrings.has(node.id)}
                    longStringThreshold={longStringThreshold}
                    typeHints={typeHints}
                    onToggleCollapse={toggleCollapse}
                    onToggleString={toggleString}
                  />
                </div>
              );
            })}
          </div>
        </div>
      </div>
    );
  }
);

OJsonViewer.displayName = 'OJsonViewer';

// ============================================================
// 单行渲染
// ============================================================

interface JsonRowProps {
  node: FlatNode;
  isCollapsed: boolean;
  isStringExpanded: boolean;
  longStringThreshold: number;
  typeHints?: Record<string, string>;
  onToggleCollapse: (id: number) => void;
  onToggleString: (id: number) => void;
}

function JsonRow({
  node,
  isCollapsed,
  isStringExpanded,
  longStringThreshold,
  typeHints,
  onToggleCollapse,
  onToggleString,
}: JsonRowProps) {
  const { tr } = useUiLang();
  const indent = node.depth * 16;
  const hint = typeHints?.[node.path];

  // close 行(} ])
  if (node.kind === 'object-close' || node.kind === 'array-close') {
    const ch = node.kind === 'object-close' ? '}' : ']';
    return (
      <div
        className="px-3 leading-6 whitespace-pre"
        style={{ paddingLeft: indent + 12 }}
      >
        <span className="text-muted-foreground">{ch}</span>
      </div>
    );
  }

  // open 行({ [)
  if (node.kind === 'object-open' || node.kind === 'array-open') {
    const openCh = node.kind === 'object-open' ? '{' : '[';
    const closeCh = node.kind === 'object-open' ? '}' : ']';
    return (
      <div
        className="px-3 leading-6 whitespace-pre flex items-baseline"
        style={{ paddingLeft: indent + 12 }}
        role="treeitem"
        aria-level={node.depth + 1}
        aria-expanded={!isCollapsed}
      >
        <button
          type="button"
          onClick={() => onToggleCollapse(node.id)}
          className={cn(
            'inline-flex items-center justify-center w-4 h-4 mr-1 text-muted-foreground',
            'hover:text-foreground rounded',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring'
          )}
          aria-label={isCollapsed ? tr('展开', 'Expand') : tr('折叠', 'Collapse')}
        >
          <svg
            className={cn('w-3 h-3 transition-transform', !isCollapsed && 'rotate-90')}
            viewBox="0 0 12 12"
            fill="currentColor"
            aria-hidden="true"
          >
            <path d="M4 3l4 3-4 3z" />
          </svg>
        </button>
        {node.keyLabel != null && (
          <>
            <span className="text-primary">{`"${node.keyLabel}"`}</span>
            <span className="text-muted-foreground">: </span>
          </>
        )}
        <span className="text-muted-foreground">{openCh}</span>
        {isCollapsed && (
          <>
            <span className="text-muted-foreground mx-1 italic text-xs">{node.summary}</span>
            <span className="text-muted-foreground">{closeCh}</span>
          </>
        )}
        {hint && <TypeHintBadge text={hint} />}
      </div>
    );
  }

  // leaf
  const isLongString =
    typeof node.value === 'string' && node.value.length > longStringThreshold;
  const { display, colorClass, truncated } = renderLeafValue(
    node.value,
    longStringThreshold,
    isStringExpanded
  );

  return (
    <div
      className="px-3 leading-6 whitespace-pre flex items-baseline"
      style={{ paddingLeft: indent + 12 + 16 }}
      role="treeitem"
      aria-level={node.depth + 1}
    >
      {node.keyLabel != null && (
        <>
          <span className="text-primary">{`"${node.keyLabel}"`}</span>
          <span className="text-muted-foreground">: </span>
        </>
      )}
      <span className={cn(colorClass, 'break-all')}>{display}</span>
      {isLongString && (
        <button
          type="button"
          onClick={() => onToggleString(node.id)}
          className={cn(
            'ml-2 text-xs underline text-muted-foreground hover:text-foreground',
            'focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring rounded'
          )}
          aria-label={truncated ? tr('查看完整字符串', 'View full string') : tr('收起', 'Collapse')}
        >
          {truncated ? tr('查看完整', 'View full') : tr('收起', 'Collapse')}
        </button>
      )}
      {hint && <TypeHintBadge text={hint} />}
    </div>
  );
}

// ============================================================
// typeHints 徽章
// ============================================================

function TypeHintBadge({ text }: { text: string }) {
  const { tr } = useUiLang();
  return (
    <span
      className={cn(
        'ml-2 inline-flex items-center gap-1 px-1.5 py-0 text-[10px] rounded',
        'bg-warning/10 text-warning border border-warning/30',
        'cursor-help'
      )}
      title={text}
      role="note"
      aria-label={`${tr('类型提示', 'Type hint')}: ${text}`}
    >
      <svg className="w-2.5 h-2.5" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
        <path d="M8 1.5A6.5 6.5 0 111.5 8 6.5 6.5 0 018 1.5zm0 9.5a.75.75 0 100 1.5.75.75 0 000-1.5zm.75-7a.75.75 0 00-1.5 0v4.5a.75.75 0 001.5 0z" />
      </svg>
      <span className="truncate max-w-[200px]">{text}</span>
    </span>
  );
}
