/**
 * OCursorOverlay - 多用户协作光标层。
 *
 * 受控: cursors 由 Page 层从 WebSocket / Liveblocks / Yjs 推送。
 * 不接业务,只画。
 *
 * 用 absolute 定位 + transform 移动,GPU 加速,平滑 transition。
 */
'use client';

import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OCursor {
  /** 用户 ID,稳定标识用于 key。 */
  id: string;
  /** 用户名(显示在光标旁)。 */
  name: string;
  /** 颜色 (CSS color value)。建议每个用户固定一个色。 */
  color: string;
  /** 位置 (px,相对父容器)。 */
  x: number;
  y: number;
  /** 是否显示标签 (默认 true)。 */
  showLabel?: boolean;
}

export interface OCursorOverlayProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  cursors: OCursor[];
  /** 过渡时长 (ms),用于光标平滑移动。默认 80。 */
  transitionMs?: number;
}

function CursorIcon({ color }: { color: string }) {
  return (
    <svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true">
      <path
        d="M2 2 L18 8 L9 11 L7 18 Z"
        fill={color}
        stroke="rgba(0,0,0,0.2)"
        strokeWidth="0.5"
      />
    </svg>
  );
}

export const OCursorOverlay = forwardRef<HTMLDivElement, OCursorOverlayProps>(
  function OCursorOverlay({ cursors, transitionMs = 80, className, theme: _t }, ref) {
    return (
      <div
        ref={ref}
        aria-hidden="true"
        className={cn('absolute inset-0 pointer-events-none overflow-hidden @container', className)}
      >
        {cursors.map((c) => (
          <div
            key={c.id}
            className="absolute top-0 left-0 will-change-transform"
            style={{
              transform: `translate3d(${c.x}px, ${c.y}px, 0)`,
              transition: `transform ${transitionMs}ms cubic-bezier(0.22, 1, 0.36, 1)`,
            }}
          >
            <CursorIcon color={c.color} />
            {c.showLabel !== false ? (
              <span
                className="absolute left-4 top-4 px-1.5 py-0.5 text-[10px] font-medium text-white rounded whitespace-nowrap shadow-sm"
                style={{ backgroundColor: c.color }}
              >
                {c.name}
              </span>
            ) : null}
          </div>
        ))}
      </div>
    );
  }
);

OCursorOverlay.displayName = 'OCursorOverlay';
