/**
 * OSymbolHero (Tide Wave 2 E11, Frame)
 *
 * 个股 detail page 顶部 Hero 大区(110-130px 高)。
 * 来源:OUI_WAVE_2_REQUIREMENTS_v1.0.md §8
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { OQuoteTicker } from '../OQuoteTicker';
import { REGIME_COLOR_VAR, REGIME_LABEL, type RegimeState, type SymbolTag, type SymbolMeta } from '../../types/tide';
import type { OBlockBaseProps } from '../../lib/types';

export interface HeroAction {
  label: string;
  icon?: string;
  actionVariant?: 'primary' | 'default';
  onClick: () => void;
}

export interface OSymbolHeroProps extends Omit<OBlockBaseProps, 'variant'> {
  symbol: string;
  name: string;
  tags: SymbolTag[];
  meta: SymbolMeta;
  price: number;
  change: number;
  pct: number;
  source?: 'sina' | 'akshare' | 'last_close';
  ageSeconds?: number;
  volumeRatio?: number;
  fusionScore: number;
  vetoPassed: number;
  vetoTotal: number;
  regime: RegimeState;
  regimeWeightsHighlight?: string;
  actions: HeroAction[];
}

export const OSymbolHero = forwardRef<HTMLDivElement, OSymbolHeroProps>(
  function OSymbolHero(
    {
      symbol,
      name,
      tags,
      meta,
      price,
      change,
      pct,
      source = 'sina',
      ageSeconds,
      volumeRatio,
      fusionScore,
      vetoPassed,
      vetoTotal,
      regime,
      regimeWeightsHighlight,
      actions,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const regimeColor = REGIME_COLOR_VAR[regime];
    return (
      <header
        ref={ref}
        className={cn(
          'grid items-stretch gap-3 px-3 py-2 border-b @container',
          'bg-[color:var(--card)] border-[color:var(--border-strong)]',
          className
        )}
        style={{
          fontFamily: 'var(--font-mono)',
          gridTemplateColumns: '1fr 240px 240px 200px',
        }}
        aria-label={`${name} ${symbol}`}
      >
        {/* col 1: symbol + name + tags + meta */}
        <div className="flex flex-col gap-1 min-w-0">
          <div className="flex items-baseline gap-2 flex-wrap">
            <span style={{ fontSize: 28, fontWeight: 700, color: 'var(--foreground)' }}>
              {symbol}
            </span>
            <span
              style={{
                fontSize: 22,
                fontWeight: 600,
                color: 'var(--foreground)',
                fontFamily: 'var(--font-sans)',
              }}
              className="truncate"
            >
              {name}
            </span>
          </div>
          {tags.length > 0 && (
            <div className="flex items-center gap-1 flex-wrap">
              {tags.map((t, i) => (
                <span
                  key={i}
                  className="px-1.5 py-0.5 rounded text-[10px]"
                  style={
                    t.variant === 'leader'
                      ? { backgroundColor: 'var(--red-up)', color: '#fff', fontWeight: 600 }
                      : { backgroundColor: 'var(--muted)', color: 'var(--muted-foreground)' }
                  }
                >
                  {t.label}
                </span>
              ))}
            </div>
          )}
          <div
            className="text-[10px] flex items-center gap-1.5 flex-wrap"
            style={{ color: 'var(--text-tertiary)' }}
          >
            {meta.city && <span>{meta.city}</span>}
            {meta.industryLv3 && <span>· {meta.industryLv3}</span>}
            {meta.marketCap !== undefined && (
              <span>· 市值 {(meta.marketCap / 1e8).toFixed(1)} 亿</span>
            )}
            {meta.freeFloatPct !== undefined && (
              <span>· 流通 {(meta.freeFloatPct * 100).toFixed(0)}%</span>
            )}
            {meta.isHkConnect && meta.hkConnectPct !== undefined && (
              <span>· 沪深通 {(meta.hkConnectPct * 100).toFixed(2)}%</span>
            )}
          </div>
        </div>

        {/* col 2: price */}
        <div className="flex items-center">
          <OQuoteTicker
            symbol={symbol}
            name={name}
            price={price}
            change={change}
            pct={pct}
            source={source}
            {...(ageSeconds !== undefined && { ageSeconds })}
            {...(volumeRatio !== undefined && { volumeRatio })}
            tickerVariant="hero"
          />
        </div>

        {/* col 3: Fusion */}
        <div
          className="flex flex-col items-center justify-center px-2 rounded border"
          style={{
            borderColor: regimeColor,
            backgroundColor: `color-mix(in srgb, ${regimeColor} 8%, transparent)`,
          }}
        >
          <span
            style={{
              fontSize: 48,
              fontWeight: 700,
              color: 'var(--red-up)',
              lineHeight: 1,
            }}
          >
            {fusionScore.toFixed(0)}
          </span>
          <span
            className="text-[10px] uppercase tracking-[0.04em]"
            style={{ color: 'var(--text-tertiary)' }}
          >
            Fusion
          </span>
          <span
            className="text-[10px]"
            style={{ color: 'var(--muted-foreground)' }}
          >
            否决 {vetoPassed}/{vetoTotal} · {REGIME_LABEL[regime]}
          </span>
          {regimeWeightsHighlight && (
            <span
              className="text-[9px] truncate w-full text-center"
              style={{ color: 'var(--text-tertiary)' }}
            >
              {regimeWeightsHighlight}
            </span>
          )}
        </div>

        {/* col 4: actions */}
        <div className="flex flex-col gap-1.5 justify-center">
          {actions.slice(0, 3).map((a, i) => (
            <button
              key={i}
              type="button"
              onClick={a.onClick}
              className={cn(
                'px-2 py-1.5 text-xs rounded transition-opacity hover:opacity-90'
              )}
              style={
                a.actionVariant === 'primary'
                  ? {
                      backgroundColor: 'var(--blue-accent)',
                      color: '#fff',
                      fontWeight: 600,
                    }
                  : {
                      backgroundColor: 'var(--muted)',
                      color: 'var(--foreground)',
                    }
              }
            >
              {a.icon && <span aria-hidden="true">{a.icon} </span>}
              {a.label}
            </button>
          ))}
        </div>
      </header>
    );
  }
);

OSymbolHero.displayName = 'OSymbolHero';
