/**
 * OViewSwitcher — Stratum 5 预置 view 切换器.
 *
 * 使用 5 个内置 view (STRATUM_BUILTIN_VIEWS):
 *   - 🌐 通用 (default)
 *   - 📖 中文文学
 *   - 📊 量化金融
 *   - 💻 技术阅读
 *   - 📝 工作日志
 *
 * 数据契约: StratumView (见 src/types/stratum.ts)
 * 后端 API: stratum.list_views() / stratum.set_default_view(view_id)
 *
 * 视觉:
 *   - 桌面: 横向 pill tabs
 *   - 移动: 横向滚动 chip 行 (touch 友好)
 *   - hover 显示 view description tooltip
 *   - 当前 view icon + name + 描述
 *
 * 使用:
 *   <OViewSwitcher
 *     views={STRATUM_BUILTIN_VIEWS}    // 或者你自己的 custom view 列表
 *     activeViewId={currentView}
 *     onChange={(view) => {
 *       setCurrentView(view.id);
 *       mcp.call('stratum.set_default_view', { viewId: view.id });
 *     }}
 *   />
 */

'use client';

import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import {
  STRATUM_BUILTIN_VIEWS,
  type StratumView,
} from '../../types/stratum';
import { useBlockObservability } from '../../providers/ObservabilityProvider';

export interface OViewSwitcherProps {
  /** 可选的 view 列表,默认 STRATUM_BUILTIN_VIEWS (5 个内置). */
  views?: readonly StratumView[];
  /** 当前激活 view 的 id. */
  activeViewId: string;
  /** 切换回调. */
  onChange: (view: StratumView) => void;
  /** 是否显示描述 (默认 true). */
  showDescription?: boolean;
  /** 是否紧凑 (移动场景). */
  compact?: boolean;
  className?: string;
}

export const OViewSwitcher = forwardRef<HTMLDivElement, OViewSwitcherProps>(
  function OViewSwitcher(
    {
      views = STRATUM_BUILTIN_VIEWS,
      activeViewId,
      onChange,
      showDescription = true,
      compact = false,
      className,
    },
    ref
  ) {
    const { dataAttrs, recordEvent } = useBlockObservability('OViewSwitcher');
    const activeView = views.find((v) => v.id === activeViewId);

    function handleSelect(view: StratumView) {
      recordEvent('view_changed', { viewId: view.id, viewName: view.name });
      onChange(view);
    }

    return (
      <div
        {...dataAttrs}
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card @container',
          className
        )}
        style={{ fontFamily: 'var(--font-ui)' }}
      >
        {/* Pills 行 */}
        <div
          className={cn(
            'flex gap-1 p-1 overflow-x-auto',
            compact ? 'pb-1' : 'pb-1'
          )}
          role="tablist"
          aria-label="Stratum View Switcher"
        >
          {views.map((view) => {
            const isActive = view.id === activeViewId;
            return (
              <button
                key={view.id}
                type="button"
                role="tab"
                aria-selected={isActive}
                onClick={() => handleSelect(view)}
                title={view.description}
                className={cn(
                  'shrink-0 inline-flex items-center gap-1.5 px-3 py-1.5 rounded text-sm transition-colors',
                  'min-h-[36px]', // 移动触摸目标
                  isActive
                    ? 'bg-primary text-primary-foreground font-medium'
                    : 'text-[color:var(--muted-foreground)] hover:bg-muted'
                )}
              >
                <span className="text-base" aria-hidden="true">
                  {view.icon}
                </span>
                <span className="whitespace-nowrap">{view.name}</span>
              </button>
            );
          })}
        </div>

        {/* 描述区 (非紧凑模式) */}
        {!compact && showDescription && activeView ? (
          <div
            className="px-3 pb-2 pt-1 border-t border-border/30 text-xs text-[color:var(--text-muted)]"
            style={{ fontFamily: 'var(--font-data)' }}
          >
            <span className="mr-2 text-[color:var(--muted-foreground)]">
              {activeView.description}
            </span>
            <span className="opacity-60">
              · LLM: {activeView.default_llm.provider}/{activeView.default_llm.model}
            </span>
            {activeView.default_filter.medium ? (
              <span className="opacity-60 ml-2">
                · medium: {activeView.default_filter.medium.join('/')}
              </span>
            ) : null}
            {activeView.default_filter.time_range ? (
              <span className="opacity-60 ml-2">
                · 范围: {activeView.default_filter.time_range}
              </span>
            ) : null}
          </div>
        ) : null}
      </div>
    );
  }
);

OViewSwitcher.displayName = 'OViewSwitcher';
