/**
 * OAgentRunHistory — Stratum Agent 执行历史列表.
 *
 * 设计要点 (基于 Stratum 5 Lock + STRATUM_API_v1.md 大纲 §1.7):
 *   - **只用 AgentRunListItem 精简类型** (list_runs() 不返 trace/citations/output)
 *   - 点击行 → 触发 onSelectRun(runId) → 父组件二次请求 get_run() → 弹 OAgentTraceViewer
 *   - status 4 态 (running/completed/failed/timeout) 颜色 chip
 *   - elapsed_seconds 显示用 secondsToMs 转毫秒,但 UX 用秒/分钟 (人话)
 *   - 按 agent_name / status / 时间区间过滤
 *
 * 反模式:
 *   ❌ 不允许接 AgentResult (完整类型),否则就鼓励 CC 在列表页拉 trace,性能崩
 *   ❌ 不允许前端缓存 trace,每次点击都新鲜请求
 *
 * 视觉:
 *   - 表格行,32px (compact) / 40px (spacious)
 *   - 列: agent 图标 | agent_name | started_at (相对时间) | 耗时 | tokens/cost | status chip
 *   - running 状态行底部加细 progress bar (indeterminate)
 *   - 排序按 started_at desc
 */

'use client';

import { forwardRef, useMemo, useState } from 'react';
import { cn } from '../../lib/cn';
import {
  useBlockObservability,
} from '../../providers/ObservabilityProvider';
import {
  type AgentName,
  type AgentRunListItem,
  type AgentRunStatus,
} from '../../types/stratum';

// ============================================================
// Props
// ============================================================

export interface OAgentRunHistoryProps {
  /** ⚠️ 必须用精简类型,不要传完整 AgentResult */
  runs: AgentRunListItem[];

  loading?: boolean;
  /** 按 agent 过滤 (undefined = all) */
  filterByAgent?: AgentName | 'all';
  /** 按 status 过滤 */
  filterByStatus?: AgentRunStatus | 'all';
  /** 行点击 → 父组件 fetch get_run() → 弹详情 */
  onSelectRun: (runId: string) => void;
  /** 最大高度,默认 600 */
  maxHeight?: number | string;
  /** 紧凑模式 (移动) */
  compact?: boolean;
  className?: string;
}

// ============================================================
// Agent 元信息 (icon + 短描述)
// ============================================================

const AGENT_META: Record<AgentName, { icon: string; label: string; color: string }> = {
  knowledge_curator: { icon: '📥', label: 'Curator', color: 'oklch(0.55 0.13 240)' },
  reading_companion: { icon: '💬', label: 'Reading', color: 'oklch(0.55 0.13 160)' },
  daily_digest: { icon: '📰', label: 'Digest', color: 'oklch(0.55 0.13 80)' },
  translation_worker: { icon: '🌐', label: 'Translate', color: 'oklch(0.55 0.13 320)' },
  lint_bot: { icon: '🩺', label: 'Lint', color: 'oklch(0.55 0.13 30)' },
  audio_generator: { icon: '🔊', label: 'Audio', color: 'oklch(0.55 0.13 280)' },
};

const STATUS_META: Record<
  AgentRunStatus,
  { label: string; bg: string; fg: string }
> = {
  running: {
    label: '运行中',
    bg: 'oklch(0.92 0.08 80)',
    fg: 'oklch(0.40 0.15 80)',
  },
  completed: {
    label: '完成',
    bg: 'oklch(0.92 0.08 145)',
    fg: 'oklch(0.40 0.15 145)',
  },
  failed: {
    label: '失败',
    bg: 'oklch(0.92 0.08 25)',
    fg: 'oklch(0.45 0.18 25)',
  },
  timeout: {
    label: '超时',
    bg: 'oklch(0.92 0.08 50)',
    fg: 'oklch(0.45 0.16 50)',
  },
};

// ============================================================
// Helpers
// ============================================================

/** elapsed_seconds → 人话 */
function formatDuration(seconds: number, status: AgentRunStatus): string {
  if (status === 'running') return '运行中…';
  if (seconds < 1) return `${Math.round(seconds * 1000)}ms`;
  if (seconds < 60) return `${seconds.toFixed(1)}s`;
  const min = Math.floor(seconds / 60);
  const sec = Math.round(seconds % 60);
  return `${min}m ${sec}s`;
}

/** started_at → 相对时间 ("3 分钟前") */
function formatRelative(iso: string): string {
  const date = new Date(iso);
  const diff = Date.now() - date.getTime();
  if (diff < 60_000) return `${Math.round(diff / 1000)} 秒前`;
  if (diff < 3_600_000) return `${Math.round(diff / 60_000)} 分钟前`;
  if (diff < 86_400_000) return `${Math.round(diff / 3_600_000)} 小时前`;
  const days = Math.round(diff / 86_400_000);
  if (days < 30) return `${days} 天前`;
  return date.toLocaleDateString('zh-CN');
}

/** cost_usd → 显示 ($0.001 显示为 "0.1¢") */
function formatCost(cost: number): string {
  if (cost === 0) return '免费';
  if (cost < 0.01) return `${(cost * 100).toFixed(2)}¢`;
  if (cost < 1) return `$${cost.toFixed(3)}`;
  return `$${cost.toFixed(2)}`;
}

// ============================================================
// Component
// ============================================================

export const OAgentRunHistory = forwardRef<HTMLDivElement, OAgentRunHistoryProps>(
  function OAgentRunHistory(
    {
      runs,
      loading = false,
      filterByAgent = 'all',
      filterByStatus = 'all',
      onSelectRun,
      maxHeight = 600,
      compact = false,
      className,
    },
    ref
  ) {
    const { dataAttrs, recordEvent } = useBlockObservability('OAgentRunHistory');
    const [internalAgentFilter, setInternalAgentFilter] = useState<
      AgentName | 'all'
    >(filterByAgent);
    const [internalStatusFilter, setInternalStatusFilter] = useState<
      AgentRunStatus | 'all'
    >(filterByStatus);

    const filteredRuns = useMemo(() => {
      return runs
        .filter(
          (r) =>
            internalAgentFilter === 'all' || r.agent_name === internalAgentFilter
        )
        .filter(
          (r) =>
            internalStatusFilter === 'all' || r.status === internalStatusFilter
        )
        .sort(
          (a, b) =>
            new Date(b.started_at).getTime() - new Date(a.started_at).getTime()
        );
    }, [runs, internalAgentFilter, internalStatusFilter]);

    function handleRowClick(item: AgentRunListItem) {
      recordEvent('row_clicked', {
        runId: item.id,
        agentName: item.agent_name,
        status: item.status,
      });
      onSelectRun(item.id);
    }

    const rowHeight = compact ? 36 : 44;

    return (
      <div
        {...dataAttrs}
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card @container',
          'overflow-hidden flex flex-col',
          className
        )}
        style={{ maxHeight, fontFamily: 'var(--font-ui)' }}
      >
        {/* Toolbar */}
        <div className="flex items-center gap-3 px-3 py-2 border-b border-border text-xs">
          {/* Agent filter */}
          <select
            value={internalAgentFilter}
            onChange={(e) =>
              setInternalAgentFilter(e.target.value as AgentName | 'all')
            }
            className={cn(
              'px-2 py-1 rounded border border-border',
              'bg-background text-[color:var(--foreground)]',
              'min-h-[28px]'
            )}
          >
            <option value="all">全部 Agent</option>
            {(Object.keys(AGENT_META) as AgentName[]).map((name) => (
              <option key={name} value={name}>
                {AGENT_META[name].icon} {AGENT_META[name].label}
              </option>
            ))}
          </select>

          {/* Status filter */}
          <select
            value={internalStatusFilter}
            onChange={(e) =>
              setInternalStatusFilter(e.target.value as AgentRunStatus | 'all')
            }
            className={cn(
              'px-2 py-1 rounded border border-border',
              'bg-background text-[color:var(--foreground)]',
              'min-h-[28px]'
            )}
          >
            <option value="all">全部状态</option>
            {(Object.keys(STATUS_META) as AgentRunStatus[]).map((s) => (
              <option key={s} value={s}>
                {STATUS_META[s].label}
              </option>
            ))}
          </select>

          <div className="flex-1" />

          <span className="text-[color:var(--text-muted)] tabular-nums">
            {filteredRuns.length} / {runs.length}
          </span>
        </div>

        {/* List */}
        <div
          className="flex-1 overflow-y-auto"
          style={{ fontFamily: 'var(--font-data)' }}
        >
          {loading ? (
            <div className="p-4 text-center text-[color:var(--text-muted)] text-sm">
              加载中…
            </div>
          ) : filteredRuns.length === 0 ? (
            <div className="p-8 text-center text-[color:var(--text-muted)] text-sm">
              <div className="text-3xl mb-2">🤖</div>
              <div>暂无 Agent 执行记录</div>
            </div>
          ) : (
            <ul role="list">
              {filteredRuns.map((item) => {
                const agent = AGENT_META[item.agent_name];
                const status = STATUS_META[item.status];
                return (
                  <li
                    key={item.id}
                    role="button"
                    tabIndex={0}
                    onClick={() => handleRowClick(item)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        handleRowClick(item);
                      }
                    }}
                    className={cn(
                      'relative flex items-center gap-3 px-3 cursor-pointer',
                      'border-b border-border/40',
                      'hover:bg-muted/30 transition-colors',
                      'text-sm'
                    )}
                    style={{ minHeight: rowHeight }}
                  >
                    {/* Agent icon + 名 */}
                    <div className="flex items-center gap-2 min-w-[120px]">
                      <span
                        className="text-base shrink-0"
                        aria-hidden="true"
                      >
                        {agent.icon}
                      </span>
                      <span
                        className="text-[color:var(--foreground)] font-medium truncate"
                        style={{ color: agent.color }}
                      >
                        {agent.label}
                      </span>
                    </div>

                    {/* Started */}
                    <div
                      className="text-[color:var(--text-muted)] tabular-nums shrink-0"
                      style={{ minWidth: 80 }}
                      title={item.started_at}
                    >
                      {formatRelative(item.started_at)}
                    </div>

                    {/* Duration */}
                    <div
                      className="text-[color:var(--muted-foreground)] tabular-nums shrink-0"
                      style={{ minWidth: 70 }}
                    >
                      {item.completed_at
                        ? formatDuration(
                            (new Date(item.completed_at).getTime() -
                              new Date(item.started_at).getTime()) /
                              1000,
                            item.status
                          )
                        : formatDuration(0, item.status)}
                    </div>

                    {/* Cost */}
                    <div
                      className="text-[color:var(--text-muted)] tabular-nums shrink-0"
                      style={{ minWidth: 60 }}
                    >
                      {formatCost(item.cost_usd)}
                    </div>

                    <div className="flex-1" />

                    {/* Status chip */}
                    <div
                      className={cn(
                        'px-2 py-0.5 rounded text-xs font-medium shrink-0',
                        'tabular-nums'
                      )}
                      style={{
                        background: status.bg,
                        color: status.fg,
                      }}
                    >
                      {status.label}
                    </div>

                    {/* running 状态:底部 indeterminate progress */}
                    {item.status === 'running' ? (
                      <div
                        className="absolute bottom-0 left-0 right-0 h-[2px] overflow-hidden bg-transparent"
                        aria-hidden="true"
                      >
                        <div
                          className="h-full bg-primary opacity-60"
                          style={{
                            width: '40%',
                            animation:
                              'helios-agent-run-progress 1.4s ease-in-out infinite',
                          }}
                        />
                      </div>
                    ) : null}
                  </li>
                );
              })}
            </ul>
          )}
        </div>

        {/* 内置 keyframe (避免全局 CSS 污染) */}
        <style>{`
          @keyframes helios-agent-run-progress {
            0%   { transform: translateX(-100%); }
            100% { transform: translateX(250%); }
          }
        `}</style>
      </div>
    );
  }
);

OAgentRunHistory.displayName = 'OAgentRunHistory';
