/**
 * OImageGallery - masonry 图片画廊。
 *
 * 用 CSS columns 实现 masonry(零 JS 计算),响应式列数。
 * lightbox 点击放大(简易实现,不引入 yet-another-react-lightbox 等库)。
 */
'use client';

import { forwardRef, useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

export interface OImageItem {
  id: string;
  src: string;
  alt: string;
  /** 宽高比 (可选,用于占位,避免 layout shift)。 */
  aspectRatio?: number;
  /** 图片说明 (lightbox 中显示)。 */
  caption?: string;
}

export interface OImageGalleryProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  images: OImageItem[];
  /** 大屏列数。 */
  cols?: 2 | 3 | 4;
  /** 启用 lightbox。 */
  lightbox?: boolean;
  /** 间距。 */
  gap?: 'sm' | 'md' | 'lg';
}

const COLS_CLASS = {
  2: '@[640px]:columns-2',
  3: '@[640px]:columns-2 @[1024px]:columns-3',
  4: '@[640px]:columns-2 @[768px]:columns-3 @[1280px]:columns-4',
};

const GAP_CLASS = {
  sm: 'gap-2 [&>*]:mb-2',
  md: 'gap-4 [&>*]:mb-4',
  lg: 'gap-6 [&>*]:mb-6',
};

export const OImageGallery = forwardRef<HTMLDivElement, OImageGalleryProps>(function OImageGallery(
  { images, cols = 3, lightbox = true, gap = 'md', className, theme: _t },
  ref
) {
  const [openIdx, setOpenIdx] = useState<number | null>(null);
  const reduced = useReducedMotion();

  useEffect(() => {
    if (openIdx == null) return;
    function onKey(e: KeyboardEvent) {
      if (e.key === 'Escape') setOpenIdx(null);
      if (e.key === 'ArrowLeft') setOpenIdx((i) => (i == null ? null : Math.max(0, i - 1)));
      if (e.key === 'ArrowRight') setOpenIdx((i) => (i == null ? null : Math.min(images.length - 1, i + 1)));
    }
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [openIdx, images.length]);

  return (
    <div ref={ref} className={cn('@container w-full', className)}>
      <div
        className={cn(
          'columns-1',
          COLS_CLASS[cols],
          GAP_CLASS[gap],
          gap === 'sm' ? 'gap-x-2' : gap === 'lg' ? 'gap-x-6' : 'gap-x-4'
        )}
      >
        {images.map((img, i) => (
          <button
            key={img.id}
            type="button"
            onClick={() => lightbox && setOpenIdx(i)}
            className={cn(
              'block w-full break-inside-avoid overflow-hidden rounded-md bg-muted',
              lightbox && 'cursor-zoom-in group'
            )}
            style={img.aspectRatio ? { aspectRatio: `${img.aspectRatio}` } : undefined}
            aria-label={img.alt}
          >
            <img
              src={img.src}
              alt={img.alt}
              loading="lazy"
              className={cn(
                'w-full h-auto block',
                !reduced && lightbox && 'group-hover:scale-105 transition-transform duration-300'
              )}
            />
          </button>
        ))}
      </div>

      <AnimatePresence>
        {openIdx != null && images[openIdx] ? (
          <motion.div
            key="lightbox"
            initial={reduced ? false : { opacity: 0 }}
            animate={reduced ? undefined : { opacity: 1 }}
            exit={reduced ? undefined : { opacity: 0 }}
            transition={{ duration: 0.2 }}
            className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex items-center justify-center p-4"
            onClick={() => setOpenIdx(null)}
            role="dialog"
            aria-modal="true"
            aria-label={images[openIdx]?.alt ?? 'Image'}
          >
            <button
              onClick={(e) => {
                e.stopPropagation();
                setOpenIdx(null);
              }}
              aria-label="Close"
              className="absolute top-4 right-4 p-2 rounded-full bg-white/10 hover:bg-white/20 text-white"
            >
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <line x1="18" y1="6" x2="6" y2="18" />
                <line x1="6" y1="6" x2="18" y2="18" />
              </svg>
            </button>
            <button
              onClick={(e) => {
                e.stopPropagation();
                setOpenIdx((i) => Math.max(0, (i ?? 0) - 1));
              }}
              disabled={openIdx === 0}
              aria-label="Previous"
              className="absolute left-4 p-2 rounded-full bg-white/10 hover:bg-white/20 text-white disabled:opacity-30"
            >
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <polyline points="15 18 9 12 15 6" />
              </svg>
            </button>
            <button
              onClick={(e) => {
                e.stopPropagation();
                setOpenIdx((i) => Math.min(images.length - 1, (i ?? 0) + 1));
              }}
              disabled={openIdx === images.length - 1}
              aria-label="Next"
              className="absolute right-4 p-2 rounded-full bg-white/10 hover:bg-white/20 text-white disabled:opacity-30"
            >
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <polyline points="9 18 15 12 9 6" />
              </svg>
            </button>
            <motion.img
              key={images[openIdx]!.id}
              initial={reduced ? false : { opacity: 0, scale: 0.95 }}
              animate={reduced ? undefined : { opacity: 1, scale: 1 }}
              transition={{ duration: 0.25 }}
              src={images[openIdx]!.src}
              alt={images[openIdx]!.alt}
              className="max-w-[90vw] max-h-[85vh] object-contain"
              onClick={(e) => e.stopPropagation()}
            />
            {images[openIdx]!.caption ? (
              <div className="absolute bottom-4 left-1/2 -translate-x-1/2 text-white text-sm bg-black/50 px-3 py-1.5 rounded">
                {images[openIdx]!.caption}
              </div>
            ) : null}
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
});

OImageGallery.displayName = 'OImageGallery';
