/**
 * OPositionPnLCard - 浮动盈亏卡片 (大字 + 5 维脉冲)。
 *
 * 合约老炮终端最显眼的卡片 - 实时显示总浮盈 / 单仓浮盈.
 * 数字变化时五维脉冲 (color flash + density 字重 + 可选 sound).
 *
 * 用法:
 *   <OPositionPnLCard
 *     data={{ pnl: 1234.56, percent: 4.5, currency: 'USDT' }}
 *     flashOnUpdate
 *     variant="hero"
 *   />
 */

'use client';

import { forwardRef, useEffect, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { useFastData } from '../../providers/FastDataProvider';
import { useFlashOnChange } from '../../hooks/useFlashOnChange';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';

export interface OPositionPnLCardData {
  /** 浮动盈亏 (USDT). */
  pnl: number;
  /** 盈亏百分比 (相对入场,已乘杠杆). */
  percent: number;
  /** 货币单位 (默认 USDT). */
  currency?: string;
  /** 标的 (可选). */
  symbol?: string;
  /** 持仓数量 (可选). */
  amount?: number;
  /** 入场均价. */
  entryPrice?: number;
  /** 标记价. */
  markPrice?: number;
  /** 已实现盈亏 (今日). */
  realizedPnlToday?: number;
}

export interface OPositionPnLCardProps
  extends OBlockDataProps<OPositionPnLCardData>,
    Pick<TerminalBlockProps, 'channel' | 'flashOnUpdate'> {
  /** hero = 顶部超大显示; compact = 小卡片. */
  variant?: 'hero' | 'compact';
  /** 标题 (默认 "未实现盈亏"). */
  title?: string;
}

export const OPositionPnLCard = forwardRef<HTMLDivElement, OPositionPnLCardProps>(
  function OPositionPnLCard(
    {
      data: dataProp,
      loading,
      error,
      empty,
      channel,
      variant = 'hero',
      title = '未实现盈亏',
      flashOnUpdate = false,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OPositionPnLCardData | null>(null);
    useEffect(() => {
      if (!channel || !fastData) return;
      return fastData.subscribe<OPositionPnLCardData>(channel, setChannelData);
    }, [channel, fastData]);

    const data = channel ? channelData : (dataProp ?? null);
    const state = resolveBlockState({ data, loading, error, empty });

    // 5 维脉冲 (返回 RefCallback)
    const flashRef = useFlashOnChange(data?.pnl ?? 0, {
      ...(typeof flashOnUpdate === 'object'
        ? flashOnUpdate
        : { modes: ['color', 'density'] as const }),
    });

    // 合并 forwardRef + flashRef 的辅助
    const mergedRef = (node: HTMLDivElement | null) => {
      flashRef(node);
      if (typeof ref === 'function') ref(node);
      else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
    };

    if (state === 'loading')
      return (
        <div ref={ref} className={cn('rounded-md border border-border bg-card p-3', className)}>
          <OLoadingState rows={2} rowHeight="1.5rem" />
        </div>
      );
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data) return null;

    const positive = data.pnl >= 0;
    const color = positive ? 'var(--quote-up)' : 'var(--quote-down)';
    const sign = positive ? '+' : '';

    if (variant === 'compact') {
      return (
        <div
          ref={mergedRef}
          className={cn(
            'rounded-md border border-border bg-card px-3 py-2 @container',
            className
          )}
          style={{ fontFamily: 'var(--font-ui)' }}
        >
          <div className="text-[10px] text-[color:var(--text-muted)]">{title}</div>
          <div className="flex items-baseline gap-2 mt-0.5">
            <span
              className="text-lg font-bold tabular-nums"
              style={{ color, fontFamily: 'var(--font-data)' }}
            >
              {sign}
              {data.pnl.toFixed(2)}
            </span>
            <span className="text-xs tabular-nums" style={{ color }}>
              ({sign}
              {data.percent.toFixed(2)}%)
            </span>
          </div>
        </div>
      );
    }

    // hero variant
    return (
      <div
        ref={mergedRef}
        className={cn(
          'rounded-lg border border-border bg-card p-4 relative overflow-hidden',
          className
        )}
        style={{ fontFamily: 'var(--font-ui)' }}
      >
        {/* 渐变背景 (按盈亏方向) */}
        <div
          className="absolute inset-0 opacity-[0.06] pointer-events-none"
          style={{
            background: `radial-gradient(circle at 20% 50%, ${color}, transparent 70%)`,
          }}
        />

        <div className="relative">
          {/* 标题 */}
          <div className="flex items-baseline justify-between">
            <span className="text-[10px] text-[color:var(--text-muted)] uppercase tracking-[0.04em]r">
              {title}
            </span>
            {data.symbol ? (
              <span className="text-[10px] font-mono text-[color:var(--text-muted)]">
                {data.symbol}
              </span>
            ) : null}
          </div>

          {/* 大字 PnL */}
          <div
            className="text-4xl font-extrabold tracking-[-0.03em] tabular-nums mt-1"
            style={{
              color,
              fontFamily: 'var(--font-data)',
              letterSpacing: '-0.02em',
            }}
          >
            {sign}
            {Math.abs(data.pnl).toFixed(2)}
            <span className="text-lg ml-2 text-[color:var(--text-muted)] font-normal">
              {data.currency ?? 'USDT'}
            </span>
          </div>

          {/* 百分比 */}
          <div
            className="text-sm tabular-nums font-mono mt-0.5"
            style={{ color }}
          >
            {sign}
            {data.percent.toFixed(2)}%
            {typeof data.realizedPnlToday === 'number' ? (
              <span className="ml-3 text-[color:var(--text-muted)] text-xs">
                今日已实现:{' '}
                <span
                  style={{
                    color: data.realizedPnlToday >= 0 ? 'var(--quote-up)' : 'var(--quote-down)',
                  }}
                >
                  {data.realizedPnlToday >= 0 ? '+' : ''}
                  {data.realizedPnlToday.toFixed(2)}
                </span>
              </span>
            ) : null}
          </div>

          {/* 详情 (entry / mark / amount) */}
          {(data.entryPrice || data.markPrice || data.amount) ? (
            <div className="mt-3 pt-2 border-t border-border/50 grid grid-cols-3 gap-2 text-[11px]">
              {typeof data.amount === 'number' ? (
                <div>
                  <div className="text-[color:var(--text-muted)]">数量</div>
                  <div className="tabular-nums font-mono">{data.amount.toFixed(4)}</div>
                </div>
              ) : null}
              {typeof data.entryPrice === 'number' ? (
                <div>
                  <div className="text-[color:var(--text-muted)]">入场</div>
                  <div className="tabular-nums font-mono">{data.entryPrice.toFixed(2)}</div>
                </div>
              ) : null}
              {typeof data.markPrice === 'number' ? (
                <div>
                  <div className="text-[color:var(--text-muted)]">标记</div>
                  <div className="tabular-nums font-mono">{data.markPrice.toFixed(2)}</div>
                </div>
              ) : null}
            </div>
          ) : null}
        </div>
      </div>
    );
  }
);

OPositionPnLCard.displayName = 'OPositionPnLCard';
