/**
 * OChatMessage - AI 对话单条消息气泡。
 *
 * 4 角色: user (你) / assistant (AI) / system (系统提示) / tool (工具调用结果)
 *
 * 视觉:
 *   - user:     右对齐 + primary 色
 *   - assistant: 左对齐 + card 色 + AI 头像
 *   - system:   居中 + 灰色细字
 *   - tool:     折叠面板风,显示工具名 + 参数 + 结果
 *
 * 不渲染内容本身(content 是任意 ReactNode,通常套 OMarkdownRenderer)。
 */
'use client';

import { forwardRef, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';
import { OAvatar } from '../OAvatar';

export type ChatRole = 'user' | 'assistant' | 'system' | 'tool';

export interface OChatMessageProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  role: ChatRole;
  /** 消息内容 (推荐传 OMarkdownRenderer 或纯文本)。 */
  content: ReactNode;
  /** 头像 (assistant/user 显示)。 */
  avatar?: { name: string; src?: string };
  /** 时间戳 (ISO 字符串或 Date)。 */
  timestamp?: string | Date;
  /** 流式输出中 (显示光标 + 不可复制)。 */
  streaming?: boolean;
  /** 工具调用元信息 (role='tool' 时显示)。 */
  toolInfo?: {
    name: string;
    args?: Record<string, unknown>;
    /** 默认折叠。 */
    collapsed?: boolean;
  };
  /** 错误状态 (e.g. 生成失败)。 */
  error?: boolean;
  /** 操作按钮 (复制、重生成等)。 */
  actions?: ReactNode;
}

function formatTime(t: string | Date): string {
  const d = typeof t === 'string' ? new Date(t) : t;
  if (Number.isNaN(d.getTime())) return '';
  return d.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
}

export const OChatMessage = forwardRef<HTMLDivElement, OChatMessageProps>(function OChatMessage(
  { role, content, avatar, timestamp, streaming, toolInfo, error, actions, className, theme: _t },
  ref
) {
  if (role === 'system') {
    return (
      <div
        ref={ref}
        className={cn('flex justify-center my-3', className)}
        role="status"
      >
        <div className="text-xs text-muted-foreground italic max-w-prose text-center px-3 py-1.5 rounded-full bg-muted/40">
          {content}
        </div>
      </div>
    );
  }

  if (role === 'tool') {
    return (
      <div
        ref={ref}
        className={cn('my-2 max-w-3xl mx-auto', className)}
      >
        <details className="rounded-md border border-border bg-muted/30 overflow-hidden" open={!toolInfo?.collapsed}>
          <summary className="px-3 py-2 text-xs font-mono text-muted-foreground cursor-pointer hover:bg-muted/50 flex items-center gap-2">
            <span aria-hidden>🔧</span>
            <span className="font-semibold">{toolInfo?.name ?? 'tool'}</span>
            {toolInfo?.args ? (
              <span className="truncate opacity-70">
                ({Object.keys(toolInfo.args).join(', ')})
              </span>
            ) : null}
          </summary>
          <div className="px-3 py-2 text-xs font-mono whitespace-pre-wrap text-foreground/80 border-t border-border/40">
            {content}
          </div>
        </details>
      </div>
    );
  }

  const isUser = role === 'user';

  return (
    <div
      ref={ref}
      className={cn(
        'flex gap-3 max-w-3xl mx-auto my-4 @container',
        isUser ? 'flex-row-reverse' : 'flex-row',
        className
      )}
      role={role === 'assistant' ? 'article' : undefined}
    >
      {avatar ? (
        <OAvatar
          name={avatar.name}
          src={avatar.src}
          size="sm"
          fallback={role === 'assistant' ? <span aria-hidden>✦</span> : undefined}
        />
      ) : null}
      <div className={cn('flex flex-col gap-1 min-w-0 flex-1', isUser && 'items-end')}>
        <div
          className={cn(
            // w-fit(fit-content)让气泡按内容宽度自适应、超出才在 max-w-full 处换行;
            // 不能用 inline-block —— 作为 flex 列子项会被 blockify,配合 items-end/break-words
            // 会塌成 1 字宽逐字竖排(user),或被 align stretch 拉满(assistant)。
            'w-fit px-4 py-2.5 rounded-2xl max-w-full break-words',
            isUser
              ? 'bg-primary text-primary-foreground rounded-tr-sm'
              : 'bg-card border border-border text-card-foreground rounded-tl-sm',
            error && 'border-destructive bg-destructive/10 text-destructive'
          )}
        >
          <div className="text-sm leading-relaxed">
            {content}
            {streaming ? (
              <span
                aria-hidden="true"
                className="inline-block w-1.5 h-4 align-middle ml-0.5 bg-current animate-pulse"
              />
            ) : null}
          </div>
        </div>
        <div className={cn('flex items-center gap-2 text-xs text-muted-foreground px-1', isUser && 'flex-row-reverse')}>
          {timestamp ? <time>{formatTime(timestamp)}</time> : null}
          {actions && !streaming ? <div className="flex items-center gap-1">{actions}</div> : null}
        </div>
      </div>
    </div>
  );
});

OChatMessage.displayName = 'OChatMessage';
