'use client';
import { forwardRef, type LabelHTMLAttributes } from 'react';
import { cn } from '../../lib/cn';
import { labelRecipe } from '../../recipes';
export interface OLabelProps extends LabelHTMLAttributes<HTMLLabelElement> { required?: boolean; }
export const OLabel = forwardRef<HTMLLabelElement, OLabelProps>(
  function OLabel({ className, required, children, ...props }, ref) {
    return (
      <label ref={ref} className={cn(labelRecipe(), className)} {...props}>
        {children}
        {required && <span className="text-[color:var(--destructive)] ml-0.5" aria-hidden>*</span>}
      </label>
    );
  }
);
OLabel.displayName = 'OLabel';
