/**
 * chart-tokens — 把主题的 CSS 变量解析成具体色值,供 canvas / WebGL 图表使用。
 *
 * 为什么需要:Recharts 的 SVG 能直接吃 CSS 变量,但 <canvas>(lightweight-charts)、
 * WebGL(three.js / OGlobe3D)、粒子背景 读不到 CSS 变量。此 helper 用 getComputedStyle
 * 把 --chart-1..5 / --quote-up/down 等解析成浏览器已算好的最终值(oklch→rgb),可直接喂给它们,
 * 从而让这些非 DOM 渲染也跟随 [data-theme] 切换。
 *
 * 注意:纯 DOM 组件(SVG/HTML)应直接用 var(--chart-1),不要用本 helper —— 那样才是原生、零成本、可级联。
 */
'use client';

import { useEffect, useState } from 'react';

export interface HeliosChartColors {
  /** chart-1..5 语义序列色(跟随主题) */
  series: [string, string, string, string, string];
  /** 涨(quote-up / success) */
  up: string;
  /** 跌(quote-down / destructive) */
  down: string;
  neutral: string;
  background: string;
  foreground: string;
  mutedForeground: string;
  border: string;
  primary: string;
}

function readVar(style: CSSStyleDeclaration, name: string, fallback: string): string {
  const v = style.getPropertyValue(name).trim();
  return v || fallback;
}

/** SSR / 无 window 时的中性兜底(避免 hydration 崩)。 */
const SSR_FALLBACK: HeliosChartColors = {
  series: ['#22d3ee', '#a855f7', '#f59e0b', '#34d399', '#fbbf24'],
  up: '#34d399',
  down: '#f87171',
  neutral: '#6b7280',
  background: '#0a0a0a',
  foreground: '#e5e7eb',
  mutedForeground: '#9ca3af',
  border: '#262626',
  primary: '#3b82f6',
};

/**
 * 读取当前主题的图表色板。
 * @param el 作用域元素(默认 document.documentElement);图表挂在局部 [data-theme] 容器内时传入该容器。
 */
export function getHeliosChartColors(el?: Element | null): HeliosChartColors {
  if (typeof window === 'undefined') return SSR_FALLBACK;
  const s = getComputedStyle(el ?? document.documentElement);
  return {
    series: [
      readVar(s, '--chart-1', SSR_FALLBACK.series[0]),
      readVar(s, '--chart-2', SSR_FALLBACK.series[1]),
      readVar(s, '--chart-3', SSR_FALLBACK.series[2]),
      readVar(s, '--chart-4', SSR_FALLBACK.series[3]),
      readVar(s, '--chart-5', SSR_FALLBACK.series[4]),
    ],
    up: readVar(s, '--quote-up', readVar(s, '--success', SSR_FALLBACK.up)),
    down: readVar(s, '--quote-down', readVar(s, '--destructive', SSR_FALLBACK.down)),
    neutral: readVar(s, '--quote-neutral', readVar(s, '--muted-foreground', SSR_FALLBACK.neutral)),
    background: readVar(s, '--background', SSR_FALLBACK.background),
    foreground: readVar(s, '--foreground', SSR_FALLBACK.foreground),
    mutedForeground: readVar(s, '--muted-foreground', SSR_FALLBACK.mutedForeground),
    border: readVar(s, '--border', SSR_FALLBACK.border),
    primary: readVar(s, '--primary', SSR_FALLBACK.primary),
  };
}

/**
 * React hook:图表色板,主题切换(<html> 上 data-theme / data-mode 变化)时自动重算。
 */
export function useHeliosChartColors(el?: Element | null): HeliosChartColors {
  const [colors, setColors] = useState<HeliosChartColors>(() => getHeliosChartColors(el));

  useEffect(() => {
    const recompute = () => setColors(getHeliosChartColors(el));
    recompute(); // 挂载后按真实 DOM 再算一次(覆盖 SSR 兜底)

    const root = document.documentElement;
    const mo = new MutationObserver(recompute);
    mo.observe(root, { attributes: true, attributeFilter: ['data-theme', 'data-mode', 'class', 'style'] });
    if (el && el !== root) {
      mo.observe(el, { attributes: true, attributeFilter: ['data-theme', 'data-mode', 'class', 'style'] });
    }
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    mq.addEventListener('change', recompute);
    return () => {
      mo.disconnect();
      mq.removeEventListener('change', recompute);
    };
  }, [el]);

  return colors;
}
