/**
 * viewTransition — View Transitions API 包装
 *
 * 用法:
 *   import { navigateWithTransition } from '@helios/blocks';
 *
 *   navigateWithTransition(() => router.push('/next-page'));
 *   // → 有 View Transitions 支持时: 平滑淡变
 *   // → 不支持时: 直接执行,无 fallback 错误
 *
 * 给元素命名 view transition:
 *   <div style={{ viewTransitionName: 'hero-card' }}>...</div>
 *   // CSS class: .o-vt-card { view-transition-name: var(--vt-name, none); }
 */

/** 带 View Transitions 的导航/状态切换 */
export function navigateWithTransition(callback: () => void | Promise<void>): void {
  if (
    typeof document !== 'undefined' &&
    'startViewTransition' in document
  ) {
    (document as Document & { startViewTransition: (cb: () => void | Promise<void>) => unknown })
      .startViewTransition(callback);
  } else {
    void callback();
  }
}

/** 是否支持 View Transitions */
export function supportsViewTransitions(): boolean {
  return typeof document !== 'undefined' && 'startViewTransition' in document;
}

/** React hook 版 — 在 useCallback 里用 */
export function useViewTransition() {
  return {
    navigate: navigateWithTransition,
    supported: supportsViewTransitions(),
  };
}
