/**
 * OFlowField - WebGL shader 粒子流场 (类 3 重型,视觉装饰)。
 *
 * 用 GLSL fragment shader 在 GPU 上计算流场,可以选择数据驱动 (driver param)。
 *
 * SPEC §3.5-§3.7:
 *   - GPU tier ≤ 1 时退化为 Canvas 2D 渐变 fallback
 *   - reduced-motion 时画面暂停 (paused)
 *   - bundle: shader 代码 ~3KB,远低于 three.js
 */
'use client';

import { Suspense, lazy, forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { useGpuTier } from '../../hooks/useGpuTier';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps, OHeavyBlockProps } from '../../lib/types';

const FlowFieldScene = lazy(() =>
  import('./OFlowField.scene').then((m) => ({ default: m.FlowFieldScene }))
);

const COLOR_SCHEMES = {
  cyan_purple: { a: 'oklch(0.7 0.2 200)', b: 'oklch(0.6 0.25 300)' },
  orange_purple: { a: 'oklch(0.75 0.3 30)', b: 'oklch(0.6 0.25 300)' },
  green_blue: { a: 'oklch(0.72 0.2 145)', b: 'oklch(0.6 0.18 240)' },
} as const;

export interface OFlowFieldProps extends Omit<OBlockBaseProps, 'variant' | 'size'>, OHeavyBlockProps {
  /** 流场强度 (0.1 - 2.0)。 */
  intensity?: number;
  /** 颜色方案。 */
  colorScheme?: keyof typeof COLOR_SCHEMES;
  /** 数据驱动 (覆盖 intensity)。0-1 映射到 0.3-1.5 intensity。 */
  driver?: number;
  /** 鼠标交互。 */
  interactive?: boolean;
  /** 强制 fallback。 */
  forceFallback?: boolean;
}

const DefaultFallback = ({ scheme }: { scheme: keyof typeof COLOR_SCHEMES }) => {
  const c = COLOR_SCHEMES[scheme];
  return (
    <div
      className="w-full h-full"
      style={{
        background: `radial-gradient(circle at 30% 40%, ${c.a} 0%, transparent 50%), radial-gradient(circle at 70% 60%, ${c.b} 0%, transparent 50%)`,
      }}
    />
  );
};

export const OFlowField = forwardRef<HTMLDivElement, OFlowFieldProps>(function OFlowField(
  {
    intensity = 0.8,
    colorScheme = 'cyan_purple',
    driver,
    interactive = false,
    fallback,
    forceFallback = false,
    className,
    theme: _t,
  },
  ref
) {
  const gpu = useGpuTier();
  const reduced = useReducedMotion();
  const effIntensity = typeof driver === 'number' ? 0.3 + Math.max(0, Math.min(1, driver)) * 1.2 : intensity;
  const colors = COLOR_SCHEMES[colorScheme];

  const shouldFallback = forceFallback || gpu.tier <= 1;
  if (shouldFallback) {
    return (
      <div
        ref={ref}
        aria-hidden="true"
        className={cn('absolute inset-0 w-full h-full pointer-events-none', className)}
        data-fallback="true"
      >
        {fallback ?? <DefaultFallback scheme={colorScheme} />}
      </div>
    );
  }

  return (
    <div
      ref={ref}
      aria-hidden="true"
      className={cn(
        'absolute inset-0 w-full h-full @container',
        interactive ? 'pointer-events-auto' : 'pointer-events-none',
        className
      )}
      data-gpu-tier={gpu.tier}
    >
      <Suspense fallback={<DefaultFallback scheme={colorScheme} />}>
        <FlowFieldScene
          intensity={effIntensity}
          colorA={colors.a}
          colorB={colors.b}
          interactive={interactive}
          paused={reduced}
        />
      </Suspense>
    </div>
  );
});

OFlowField.displayName = 'OFlowField';
