/**
 * OPlanConsistencyChart (Tide Wave 3 E21, Block)
 *
 * Plan 一致性 4 段堆叠 bar(同向遵循 / 同向偏离 / 反向遵循 / 反向偏离)。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §3.2
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { useUiLang } from '../../lang/LangProvider';
import type { OBlockBaseProps } from '../../lib/types';

export interface PlanConsistencyData {
  sameDirCompliant: number;
  sameDirDeviation: number;
  oppDirCompliant: number;
  oppDirDeviation: number;
  totalTrades: number;
}

export interface OPlanConsistencyChartProps extends Omit<OBlockBaseProps, 'variant'> {
  data: PlanConsistencyData;
  /** 是否显示百分比 */
  showPercents?: boolean;
  /** 是否显示数字 */
  showCounts?: boolean;
  onSegmentClick?: (segment: 'sd-c' | 'sd-d' | 'od-c' | 'od-d') => void;
}

const SEG_COLORS = {
  'sd-c': 'var(--green-down)', // 同向遵循 — A 股反转, 但纪律语义用 green = good
  'sd-d': 'var(--yellow)',
  'od-c': 'var(--blue-accent)',
  'od-d': 'var(--red-up)',
};

const SEG_LABEL: Record<'sd-c' | 'sd-d' | 'od-c' | 'od-d', { zh: string; en: string }> = {
  'sd-c': { zh: '同向遵循', en: 'Same dir compliant' },
  'sd-d': { zh: '同向偏离', en: 'Same dir deviation' },
  'od-c': { zh: '反向遵循', en: 'Opp dir compliant' },
  'od-d': { zh: '反向偏离', en: 'Opp dir deviation' },
};

export const OPlanConsistencyChart = forwardRef<HTMLDivElement, OPlanConsistencyChartProps>(
  function OPlanConsistencyChart(
    {
      data,
      showPercents = true,
      showCounts = true,
      onSegmentClick,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const { tr } = useUiLang();
    const labelOf = (k: keyof typeof SEG_LABEL) => tr(SEG_LABEL[k].zh, SEG_LABEL[k].en);
    const total = data.totalTrades || 1;
    const segs: { key: keyof typeof SEG_COLORS; val: number }[] = [
      { key: 'sd-c', val: data.sameDirCompliant },
      { key: 'sd-d', val: data.sameDirDeviation },
      { key: 'od-c', val: data.oppDirCompliant },
      { key: 'od-d', val: data.oppDirDeviation },
    ];

    return (
      <div
        ref={ref}
        className={cn('flex flex-col gap-2 px-3 py-2 rounded @container',
          'bg-[color:var(--card)] border border-[color:var(--border-strong)]',
          className
        )}
        style={{ fontFamily: 'var(--font-mono)' }}
        role="region"
        aria-label={tr("Plan 一致性", "Plan consistency")}
      >
        <div className="flex items-center justify-between text-[10px] uppercase tracking-[0.04em]">
          <span style={{ color: 'var(--text-tertiary)' }}>{tr("Plan 一致性", "Plan consistency")}</span>
          <span style={{ color: 'var(--muted-foreground)' }}>
            {tr("总样本", "Total")} {data.totalTrades}
          </span>
        </div>

        {/* stacked bar */}
        <div
          className="flex h-[18px] rounded overflow-hidden"
          aria-label={`${tr("Plan 一致性", "Plan consistency")}: ${labelOf("sd-c")} ${((data.sameDirCompliant / total) * 100).toFixed(0)}%, ${tr("总样本", "total")} ${data.totalTrades}`}
        >
          {segs.map((s) => {
            const pct = (s.val / total) * 100;
            if (pct === 0) return null;
            const clickable = !!onSegmentClick;
            const inner = (
              <span
                className="text-[10px] font-bold whitespace-nowrap"
                style={{ color: '#fff', mixBlendMode: 'difference' }}
              >
                {pct >= 8 && showPercents ? `${pct.toFixed(0)}%` : ''}
              </span>
            );
            return clickable ? (
              <button
                key={s.key}
                type="button"
                onClick={() => onSegmentClick!(s.key)}
                aria-label={`${labelOf(s.key)} ${s.val} ${tr("次", "")} ${pct.toFixed(0)}%`}
                className="flex items-center justify-center hover:opacity-80 transition-opacity"
                style={{ width: `${pct}%`, backgroundColor: SEG_COLORS[s.key], border: 'none' }}
              >
                {inner}
              </button>
            ) : (
              <div
                key={s.key}
                className="flex items-center justify-center"
                style={{ width: `${pct}%`, backgroundColor: SEG_COLORS[s.key] }}
              >
                {inner}
              </div>
            );
          })}
        </div>

        {/* legend */}
        <ul className="grid grid-cols-2 gap-x-3 gap-y-1 list-none p-0 m-0">
          {segs.map((s) => {
            const pct = (s.val / total) * 100;
            return (
              <li key={s.key} className="flex items-center gap-1 text-[10px]">
                <span
                  className="inline-block w-2 h-2 rounded-sm shrink-0"
                  style={{ backgroundColor: SEG_COLORS[s.key] }}
                />
                <span style={{ color: 'var(--muted-foreground)' }}>
                  {labelOf(s.key)}
                </span>
                <span className="ml-auto" style={{ color: 'var(--foreground)' }}>
                  {showCounts && s.val} {showPercents && `(${pct.toFixed(0)}%)`}
                </span>
              </li>
            );
          })}
        </ul>
      </div>
    );
  }
);

OPlanConsistencyChart.displayName = 'OPlanConsistencyChart';
