/**
 * TimelineProvider - 时空切片 / 回放控制。
 *
 * 提供 currentTime / play / pause / seek / setSpeed / 多标的同步回放。
 *
 * 实现:
 *   - 内部用 requestAnimationFrame 驱动 currentTime 推进
 *   - 用 ref 存状态,subscribe 推送变化
 *   - 退出 live 时切换数据源 (Block 自己判断)
 */
'use client';

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  type ReactNode,
} from 'react';
import type { TimelineProtocol, TimelineState, SymbolKey } from '../protocols';

const INITIAL: TimelineState = {
  currentTime: null,
  range: null,
  playState: 'idle',
  speed: 1,
  symbols: [],
};

const TimelineContext = createContext<TimelineProtocol | null>(null);

interface TimelineProviderProps {
  children: ReactNode;
}

export function TimelineProvider({ children }: TimelineProviderProps) {
  const stateRef = useRef<TimelineState>({ ...INITIAL });
  const listenersRef = useRef(new Set<(s: TimelineState) => void>());
  const rafRef = useRef<number | null>(null);
  const lastTickRef = useRef<number>(0);

  function notify(): void {
    const s = stateRef.current;
    for (const l of listenersRef.current) {
      try {
        l(s);
      } catch (e) {
        console.error('[TimelineProvider listener]', e);
      }
    }
  }

  function setState(patch: Partial<TimelineState>): void {
    stateRef.current = { ...stateRef.current, ...patch };
    notify();
  }

  function tick(now: number): void {
    if (stateRef.current.playState !== 'playing') {
      rafRef.current = null;
      return;
    }
    const dt = lastTickRef.current ? (now - lastTickRef.current) / 1000 : 0;
    lastTickRef.current = now;

    const currentTime = stateRef.current.currentTime;
    const range = stateRef.current.range;
    const speed = stateRef.current.speed;

    if (currentTime != null && range) {
      const next = currentTime + dt * speed;
      if (next >= range[1]) {
        // 到末尾,暂停
        stateRef.current = { ...stateRef.current, currentTime: range[1], playState: 'paused' };
        notify();
        rafRef.current = null;
        return;
      }
      stateRef.current = { ...stateRef.current, currentTime: next };
      notify();
    }

    rafRef.current = requestAnimationFrame(tick);
  }

  function startTicking(): void {
    if (rafRef.current != null) return;
    lastTickRef.current = 0;
    rafRef.current = requestAnimationFrame(tick);
  }

  // 清理 raf
  useEffect(() => {
    return () => {
      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  const protocol = useMemo<TimelineProtocol>(
    () => ({
      getState() {
        return stateRef.current;
      },
      subscribe(callback) {
        listenersRef.current.add(callback);
        callback(stateRef.current);
        return () => listenersRef.current.delete(callback);
      },
      setRange(start, end) {
        const t = Math.max(start, Math.min(stateRef.current.currentTime ?? start, end));
        setState({ range: [start, end], currentTime: t });
      },
      seek(time) {
        const range = stateRef.current.range;
        const clamped = range ? Math.max(range[0], Math.min(time, range[1])) : time;
        setState({ currentTime: clamped });
      },
      play() {
        if (stateRef.current.range == null) return;
        if (stateRef.current.currentTime == null) {
          setState({ currentTime: stateRef.current.range[0] });
        }
        setState({ playState: 'playing' });
        startTicking();
      },
      pause() {
        setState({ playState: 'paused' });
      },
      resume() {
        if (stateRef.current.playState === 'paused') {
          setState({ playState: 'playing' });
          startTicking();
        }
      },
      exitToLive() {
        if (rafRef.current != null) {
          cancelAnimationFrame(rafRef.current);
          rafRef.current = null;
        }
        stateRef.current = { ...INITIAL, symbols: stateRef.current.symbols };
        notify();
      },
      setSpeed(speed) {
        setState({ speed });
      },
      addSymbol(s: SymbolKey) {
        if (!stateRef.current.symbols.includes(s)) {
          setState({ symbols: [...stateRef.current.symbols, s] });
        }
      },
      removeSymbol(s: SymbolKey) {
        setState({ symbols: stateRef.current.symbols.filter((x) => x !== s) });
      },
    }),
    // setState / startTicking 是 provider 闭包内函数,通过 ref 操作 state,
    // 不需要随 render 重建 protocol。空依赖是有意的。
    // eslint-disable-next-line react-hooks/exhaustive-deps
    []
  );

  return <TimelineContext.Provider value={protocol}>{children}</TimelineContext.Provider>;
}

TimelineProvider.displayName = 'TimelineProvider';

export function useTimeline(): TimelineProtocol {
  const ctx = useContext(TimelineContext);
  if (!ctx) {
    return {
      getState: () => INITIAL,
      subscribe: () => () => {},
      setRange: () => {},
      seek: () => {},
      play: () => {},
      pause: () => {},
      resume: () => {},
      exitToLive: () => {},
      setSpeed: () => {},
      addSymbol: () => {},
      removeSymbol: () => {},
    };
  }
  return ctx;
}
