/**
 * OExecutionFidelity — 执行真实度对比(量化通用)。
 *
 * backtest 假设 vs 真实 fill 并排,暴露 backtest 不可靠处(诚实)。
 * 滑点 / fill rate / funding 偏差。
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface FidelityMetric {
  label: string;
  backtest: number;
  actual: number;
  unit?: string;
  /** 偏差越大越糟,用于着色 */
  worseWhenHigher?: boolean;
}

export interface OExecutionFidelityProps extends Omit<OBlockBaseProps, 'variant'> {
  metrics: FidelityMetric[];
}

export const OExecutionFidelity = forwardRef<HTMLDivElement, OExecutionFidelityProps>(
  function OExecutionFidelity({ metrics, className, ...rest }, ref) {
    return (
      <div ref={ref} className={cn('rounded-lg border border-border bg-card overflow-hidden', className)} {...rest}>
        <div className="grid grid-cols-[1fr_auto_auto_auto] text-xs">
          {/* header */}
          <div className="px-3 py-2 font-semibold uppercase tracking-[0.04em] text-muted-foreground border-b border-border">指标</div>
          <div className="px-3 py-2 font-semibold uppercase tracking-[0.04em] text-muted-foreground text-right border-b border-border">Backtest</div>
          <div className="px-3 py-2 font-semibold uppercase tracking-[0.04em] text-muted-foreground text-right border-b border-border">真实</div>
          <div className="px-3 py-2 font-semibold uppercase tracking-[0.04em] text-muted-foreground text-right border-b border-border">偏差</div>

          {metrics.map((m, i) => {
            const diff = m.actual - m.backtest;
            const pct = m.backtest !== 0 ? (diff / Math.abs(m.backtest)) * 100 : 0;
            const bad = m.worseWhenHigher ? diff > 0 : diff < 0;
            return (
              <div key={i} className="contents">
                <div className="px-3 py-2 border-b border-border/50">{m.label}</div>
                <div className="px-3 py-2 text-right tabular-nums border-b border-border/50 text-muted-foreground">
                  {m.backtest}{m.unit}
                </div>
                <div className="px-3 py-2 text-right tabular-nums border-b border-border/50 font-semibold">
                  {m.actual}{m.unit}
                </div>
                <div className="px-3 py-2 text-right tabular-nums border-b border-border/50 font-semibold"
                  style={{ color: bad ? 'var(--destructive)' : 'var(--success, oklch(0.62 0.18 145))' }}>
                  {pct > 0 ? '+' : ''}{pct.toFixed(1)}%
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }
);

OExecutionFidelity.displayName = 'OExecutionFidelity';
