/**
 * TerminalProviders - Helios Terminal 一站式 Provider 容器。
 *
 * 业务方只需:
 * ```tsx
 * <TerminalProviders
 *   region="global"
 *   dataMode="ws"
 *   dataEndpoint="wss://api.helios.dev/stream"
 *   aiEndpoint="/api/ai/intent"
 * >
 *   <App />
 * </TerminalProviders>
 * ```
 *
 * 这一行,8 个 Provider 全部就位,任意 Block 用对应 hook 即可。
 *
 * 嵌套顺序经过精心设计:
 *   Regulation (最外,影响所有显示)
 *   ↓
 *   FastData (核心数据源)
 *   ↓
 *   Crosshair / Timeline / Workspace (UI 协同)
 *   ↓
 *   Command (依赖前者)
 *   ↓
 *   AIIntent (依赖 Command)
 *   ↓
 *   Presence (最内,可选)
 */
'use client';

import { type ReactNode } from 'react';
import { FastDataProvider } from './FastDataProvider';
import { CrosshairProvider } from './CrosshairProvider';
import { TimelineProvider } from './TimelineProvider';
import { WorkspaceProvider } from './WorkspaceProvider';
import { CommandProvider } from './CommandProvider';
import { AIIntentProvider } from './AIIntentProvider';
import { RegulationProvider } from './RegulationProvider';
import { PresenceProvider } from './PresenceProvider';
import type { RegulationRegion, SerializedLayout } from '../protocols';

export interface TerminalProvidersProps {
  children: ReactNode;

  // Regulation
  region?: RegulationRegion;

  // FastData
  dataMode?: 'mock' | 'ws' | 'worker';
  dataEndpoint?: string;
  dataDebug?: boolean;

  // Workspace
  workspacePresets?: Record<string, SerializedLayout>;
  defaultWorkspacePreset?: string;
  workspaceStorageKey?: string;

  // Command
  globalHotkey?: string;

  // AIIntent
  aiEndpoint?: string;
  aiStreamEndpoint?: string;

  // Presence
  presenceEnabled?: boolean;

  // Crosshair
  initialSymbol?: string;
}

export function TerminalProviders({
  children,
  region = 'global',
  dataMode = 'mock',
  dataEndpoint,
  dataDebug,
  workspacePresets,
  defaultWorkspacePreset,
  workspaceStorageKey,
  globalHotkey = 'cmd+k',
  aiEndpoint,
  aiStreamEndpoint,
  presenceEnabled = false,
  initialSymbol,
}: TerminalProvidersProps) {
  return (
    <RegulationProvider region={region}>
      <FastDataProvider mode={dataMode} endpoint={dataEndpoint} debug={dataDebug}>
        <CrosshairProvider initialSymbol={initialSymbol}>
          <TimelineProvider>
            <WorkspaceProvider
              presets={workspacePresets}
              defaultPreset={defaultWorkspacePreset}
              storageKey={workspaceStorageKey}
            >
              <CommandProvider globalHotkey={globalHotkey}>
                <AIIntentProvider endpoint={aiEndpoint} streamEndpoint={aiStreamEndpoint}>
                  <PresenceProvider enabled={presenceEnabled}>{children}</PresenceProvider>
                </AIIntentProvider>
              </CommandProvider>
            </WorkspaceProvider>
          </TimelineProvider>
        </CrosshairProvider>
      </FastDataProvider>
    </RegulationProvider>
  );
}

TerminalProviders.displayName = 'TerminalProviders';
