/**
 * OTestimonialCarousel - 用户证言轮播。
 *
 * 自动轮播 + 手动翻页 + 暂停 (hover/focus)。
 * reduced-motion 下关闭自动轮播,只显示静态。
 */
'use client';

import { forwardRef, useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

export interface OTestimonial {
  id: string;
  /** 引文 (核心)。 */
  quote: string;
  /** 作者名。 */
  author: string;
  /** 职位/公司。 */
  role?: string;
  /** 头像 URL。 */
  avatar?: string;
  /** 星级 1-5 (可选)。 */
  rating?: number;
  /** 公司 logo URL (可选)。 */
  logo?: string;
}

export interface OTestimonialCarouselProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  testimonials: OTestimonial[];
  /** 自动轮播间隔 (ms),0 = 关闭。 */
  autoplay?: number;
  /** 显示样式。 */
  variant?: 'single' | 'cards';
  /** 章节标题 (可选)。 */
  heading?: string;
}

function StarRow({ rating }: { rating: number }) {
  return (
    <div className="flex gap-0.5" aria-label={`${rating} of 5 stars`}>
      {Array.from({ length: 5 }, (_, i) => (
        <svg
          key={i}
          width="14"
          height="14"
          viewBox="0 0 24 24"
          fill={i < rating ? 'currentColor' : 'none'}
          stroke="currentColor"
          strokeWidth="2"
          className={i < rating ? 'text-warning' : 'text-muted-foreground/30'}
          aria-hidden="true"
        >
          <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
        </svg>
      ))}
    </div>
  );
}

function Avatar({ url, name }: { url?: string; name: string }) {
  const initials = name.split(' ').map((p) => p[0]).join('').slice(0, 2).toUpperCase();
  if (url) {
    return <img src={url} alt={name} className="w-10 h-10 rounded-full object-cover" />;
  }
  return (
    <div className="w-10 h-10 rounded-full bg-primary/15 text-primary flex items-center justify-center text-sm font-medium">
      {initials}
    </div>
  );
}

export const OTestimonialCarousel = forwardRef<HTMLElement, OTestimonialCarouselProps>(
  function OTestimonialCarousel(
    {
      testimonials,
      autoplay = 5000,
      variant = 'single',
      heading,
      className,
      theme: _t,
    },
    ref
  ) {
    const reduced = useReducedMotion();
    const [index, setIndex] = useState(0);
    const [paused, setPaused] = useState(false);
    const len = testimonials.length;

    useEffect(() => {
      if (reduced || autoplay <= 0 || paused || len <= 1) return;
      const id = setInterval(() => setIndex((i) => (i + 1) % len), autoplay);
      return () => clearInterval(id);
    }, [autoplay, paused, reduced, len]);

    if (len === 0) return null;

    if (variant === 'cards') {
      return (
        <section ref={ref} className={cn('w-full @container', className)}>
          {heading ? (
            <h2 className="text-3xl font-bold text-center mb-8">{heading}</h2>
          ) : null}
          <div className="grid grid-cols-1 @[768px]:grid-cols-2 @[1024px]:grid-cols-3 gap-4">
            {testimonials.map((t) => (
              <figure
                key={t.id}
                className="flex flex-col gap-4 p-6 bg-card border border-border rounded-lg"
              >
                {t.rating ? <StarRow rating={t.rating} /> : null}
                <blockquote className="text-sm text-foreground leading-relaxed">
                  &ldquo;{t.quote}&rdquo;
                </blockquote>
                <figcaption className="flex items-center gap-3 mt-auto pt-2 border-t border-border/60">
                  <Avatar url={t.avatar} name={t.author} />
                  <div className="min-w-0 flex-1">
                    <div className="text-sm font-medium truncate">{t.author}</div>
                    {t.role ? (
                      <div className="text-xs text-muted-foreground truncate">{t.role}</div>
                    ) : null}
                  </div>
                  {t.logo ? <img src={t.logo} alt="" className="h-5 opacity-70 shrink-0" /> : null}
                </figcaption>
              </figure>
            ))}
          </div>
        </section>
      );
    }

    const current = testimonials[index]!;

    return (
      <section
        ref={ref}
        className={cn('w-full', className)}
        onMouseEnter={() => setPaused(true)}
        onMouseLeave={() => setPaused(false)}
        onFocus={() => setPaused(true)}
        onBlur={() => setPaused(false)}
      >
        {heading ? (
          <h2 className="text-3xl font-bold text-center mb-8">{heading}</h2>
        ) : null}
        <div className="relative max-w-3xl mx-auto px-6 py-12 text-center min-h-[280px]">
          <AnimatePresence mode="wait">
            <motion.figure
              key={current.id}
              initial={reduced ? false : { opacity: 0, y: 10 }}
              animate={reduced ? undefined : { opacity: 1, y: 0 }}
              exit={reduced ? undefined : { opacity: 0, y: -10 }}
              transition={{ duration: 0.4 }}
              className="flex flex-col items-center gap-6"
            >
              {current.rating ? <StarRow rating={current.rating} /> : null}
              <blockquote className="text-xl md:text-2xl font-medium text-foreground leading-snug max-w-2xl">
                &ldquo;{current.quote}&rdquo;
              </blockquote>
              <figcaption className="flex items-center gap-3">
                <Avatar url={current.avatar} name={current.author} />
                <div className="text-left">
                  <div className="text-sm font-semibold">{current.author}</div>
                  {current.role ? (
                    <div className="text-xs text-muted-foreground">{current.role}</div>
                  ) : null}
                </div>
                {current.logo ? <img src={current.logo} alt="" className="h-6 ml-2 opacity-70" /> : null}
              </figcaption>
            </motion.figure>
          </AnimatePresence>
        </div>
        <div className="flex items-center justify-center gap-2">
          {testimonials.map((t, i) => (
            <button
              key={t.id}
              onClick={() => setIndex(i)}
              aria-label={`Show testimonial ${i + 1}`}
              aria-current={i === index}
              className={cn(
                'h-1.5 rounded-full transition-all',
                i === index ? 'w-8 bg-primary' : 'w-1.5 bg-border hover:bg-muted-foreground'
              )}
            />
          ))}
        </div>
      </section>
    );
  }
);

OTestimonialCarousel.displayName = 'OTestimonialCarousel';
