/**
 * OOrderbookL2 - 加密 L2 盘口 (Helios 杀手锏 Block)。
 *
 * 与 OOrderbookDepth (展示场景,Batch 8) 的区别:
 *   - OOrderbookDepth = 简单深度图,营销/教学场景
 *   - OOrderbookL2 = 全功能 L2,工作台场景,200 档 + 60Hz 更新 + 多维数据
 *
 * Helios 独有功能 (TV 没有):
 *   1. maker/taker 分流可视化
 *   2. 大额 whale tracker 气泡 (单笔 > 阈值)
 *   3. 累积成交流右侧滚动
 *   4. 接 FastDataProvider (Web Worker 数据)
 *   5. 接 CrosshairProvider (跨图联动)
 *   6. 接 FlashOnChange (五维脉冲)
 *
 * 性能合同 (Terminal SPEC §8):
 *   200 档 × 10Hz 更新 必须 60fps
 *   Canvas 自绘,不走 React 重渲染
 *
 * 用法 (受控,数据从 FastDataProvider 推):
 *   <OOrderbookL2 symbol="BTC/USDT" channel="l2:BTC-USDT" />
 *
 * 用法 (受控,直接传 data):
 *   <OOrderbookL2 data={{ symbol, bids, asks, recentTrades }} />
 */

'use client';

import { forwardRef, useEffect, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import type { OBlockDataProps } from '../../lib/types';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import { useFastData } from '../../providers/FastDataProvider';
import { useCrosshair } from '../../providers/CrosshairProvider';

// ============================================================
// 数据契约
// ============================================================

export interface OL2Level {
  price: number;
  size: number;
  /** 累积订单数 (此档位有几个挂单)。 */
  orderCount?: number;
  /** 此档位是否有大单(可视化用)。 */
  hasLargeOrder?: boolean;
  /** 此档近 1s 内的变化趋势。 */
  trend?: 'up' | 'down' | 'flat';
}

export interface OL2Trade {
  /** Unix ms。 */
  timestamp: number;
  price: number;
  size: number;
  /** 主动方。 */
  side: 'buy' | 'sell';
  /** taker / maker 标签。 */
  type: 'taker' | 'maker';
  /** 是否大单(超过阈值,Helios 独有)。 */
  isWhale?: boolean;
}

export interface OL2Data {
  symbol: string;
  /** 买盘,从高到低排序,5-200 档。 */
  bids: OL2Level[];
  /** 卖盘,从低到高排序,5-200 档。 */
  asks: OL2Level[];
  /** 最近成交流,新的在前。 */
  recentTrades?: OL2Trade[];
  /** 最近 N 秒的累积统计。 */
  flow?: {
    /** 主动买量 (taker buy)。 */
    takerBuy: number;
    /** 主动卖量 (taker sell)。 */
    takerSell: number;
    /** 统计窗口 (秒)。 */
    windowSec: number;
  };
  /** 时间戳 (用于 reduced-motion 下显示 "更新于")。 */
  updatedAt?: number;
}

// ============================================================
// Props
// ============================================================

export interface OOrderbookL2Props
  extends OBlockDataProps<OL2Data> {
  /** 数据驱动方式 1: 直接 data 受控 */
  // (继承自 OBlockDataProps)

  /** 数据驱动方式 2: 订阅 FastDataProvider 的 channel */
  channel?: string;
  /** 数据驱动方式 3: symbol (自动生成 channel = "l2:{symbol}") */
  symbol?: string;

  /** 显示档位数 (每侧)。默认 20。 */
  levels?: number;
  /** 高度 (px)。默认 480。 */
  height?: number;
  /** 显示最近成交流 (右侧)。默认 true。 */
  showTrades?: boolean;
  /** 显示主动买卖累计流 (中间)。默认 true。 */
  showFlow?: boolean;
  /** whale 阈值 (单笔成交额 USD)。超过此值标记为大单。默认 50000。 */
  whaleThreshold?: number;
  /** 接入跨图联动 (Crosshair) 标的 key。 */
  syncToCrosshair?: string;
  /** 数据延时 (分钟,合规标记)。 */
  dataDelay?: number;
  /** 性能降级模式。 */
  lowPerformanceMode?: boolean;
}

// ============================================================
// 工具
// ============================================================

function cssVar(name: string, fallback = '#888'): string {
  if (typeof document === 'undefined') return fallback;
  const v = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  return v || fallback;
}

function formatSize(n: number): string {
  if (n >= 1e9) return (n / 1e9).toFixed(2) + 'B';
  if (n >= 1e6) return (n / 1e6).toFixed(2) + 'M';
  if (n >= 1e3) return (n / 1e3).toFixed(2) + 'K';
  return n.toFixed(2);
}

function formatTime(ts: number): string {
  const d = new Date(ts);
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}:${String(d.getSeconds()).padStart(2, '0')}`;
}

// ============================================================
// Canvas 绘制核心 (高性能,不走 React)
// ============================================================

interface DrawColors {
  bgCard: string;
  bgBuy: string;
  bgSell: string;
  textPrimary: string;
  textMuted: string;
  textLabel: string;
  quoteUp: string;
  quoteDown: string;
  whaleBuy: string;
  whaleSell: string;
  border: string;
  midPrice: string;
}

function readColors(): DrawColors {
  return {
    bgCard: cssVar('--card', 'oklch(0.12 0.015 240)'),
    bgBuy: cssVar('--quote-up-bg', 'oklch(0.68 0.20 145 / 0.10)'),
    bgSell: cssVar('--quote-down-bg', 'oklch(0.62 0.22 25 / 0.10)'),
    textPrimary: cssVar('--text-primary', '#fff'),
    textMuted: cssVar('--text-muted', '#888'),
    textLabel: cssVar('--text-secondary', '#bbb'),
    quoteUp: cssVar('--quote-up', 'oklch(0.68 0.20 145)'),
    quoteDown: cssVar('--quote-down', 'oklch(0.62 0.22 25)'),
    whaleBuy: cssVar('--whale-buy', 'oklch(0.80 0.22 145)'),
    whaleSell: cssVar('--whale-sell', 'oklch(0.72 0.25 25)'),
    border: cssVar('--border', 'oklch(0.22 0.025 240)'),
    midPrice: cssVar('--text-primary', '#fff'),
  };
}

interface LayoutCfg {
  rowHeight: number;
  priceCol: number;
  sizeCol: number;
  cumCol: number;
  midBarHeight: number;
  showFlow: boolean;
}

function drawBook(
  ctx: CanvasRenderingContext2D,
  w: number,
  h: number,
  data: OL2Data,
  levels: number,
  cfg: LayoutCfg,
  colors: DrawColors,
  whaleThreshold: number
) {
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = colors.bgCard;
  ctx.fillRect(0, 0, w, h);

  const bids = data.bids.slice(0, levels);
  const asks = data.asks.slice(0, levels);

  // 累积 size
  let cumA = 0;
  const asksCum = asks.map((a) => ((cumA += a.size), { ...a, cum: cumA }));
  let cumB = 0;
  const bidsCum = bids.map((b) => ((cumB += b.size), { ...b, cum: cumB }));

  const maxCum = Math.max(cumA, cumB, 1);

  // 区域划分
  const midY = h / 2;
  const askArea = midY - cfg.midBarHeight / 2;
  const bidArea = midY + cfg.midBarHeight / 2;

  ctx.font = `11px var(--font-data, ui-monospace, monospace)`;
  ctx.textBaseline = 'middle';

  // ============ ASKS (从 mid 向上画) ============
  for (let i = 0; i < asks.length; i++) {
    const a = asksCum[i];
    if (!a) continue; // strict mode 守卫:如果 cum 数组没对齐(数据竞争),跳过
    const y = askArea - (i + 1) * cfg.rowHeight;
    if (y < 0) break;

    // 累积深度条
    const barW = (a.cum / maxCum) * w * 0.9;
    ctx.fillStyle = colors.bgSell;
    ctx.fillRect(w - barW, y, barW, cfg.rowHeight);

    // 价格
    ctx.fillStyle = colors.quoteDown;
    ctx.textAlign = 'left';
    ctx.fillText(a.price.toFixed(2), cfg.priceCol, y + cfg.rowHeight / 2);

    // size
    ctx.fillStyle = colors.textPrimary;
    ctx.textAlign = 'right';
    ctx.fillText(formatSize(a.size), cfg.sizeCol, y + cfg.rowHeight / 2);

    // 累积
    ctx.fillStyle = colors.textMuted;
    ctx.textAlign = 'right';
    ctx.fillText(formatSize(a.cum), cfg.cumCol, y + cfg.rowHeight / 2);

    // 大单标记 (Helios 独有)
    if (a.hasLargeOrder || a.size * a.price >= whaleThreshold) {
      ctx.fillStyle = colors.whaleSell;
      ctx.beginPath();
      ctx.arc(8, y + cfg.rowHeight / 2, 3, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // ============ 中线区域 ============
  const bestBid = bids[0]?.price;
  const bestAsk = asks[0]?.price;
  if (bestBid != null && bestAsk != null) {
    const mid = (bestBid + bestAsk) / 2;
    const spread = bestAsk - bestBid;
    const spreadBp = (spread / mid) * 10000;

    // mid 价格
    ctx.fillStyle = colors.midPrice;
    ctx.font = `bold 13px var(--font-data, ui-monospace, monospace)`;
    ctx.textAlign = 'center';
    ctx.fillText(mid.toFixed(2), w / 2, midY - 6);

    // spread
    ctx.font = `10px var(--font-data, ui-monospace, monospace)`;
    ctx.fillStyle = colors.textMuted;
    ctx.fillText(`${spread.toFixed(2)} (${spreadBp.toFixed(1)}bp)`, w / 2, midY + 8);

    // 上下分割线
    ctx.strokeStyle = colors.border;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, askArea);
    ctx.lineTo(w, askArea);
    ctx.moveTo(0, bidArea);
    ctx.lineTo(w, bidArea);
    ctx.stroke();
  }

  // ============ flow 累计柱 (Helios 独有) ============
  if (cfg.showFlow && data.flow) {
    const { takerBuy, takerSell } = data.flow;
    const total = takerBuy + takerSell;
    if (total > 0) {
      const buyRatio = takerBuy / total;
      const barY = midY + cfg.midBarHeight / 2 - 4;
      const barH = 3;
      // 买 (从中间向左)
      ctx.fillStyle = colors.quoteUp;
      const buyW = w * 0.5 * buyRatio * 2;
      ctx.fillRect(w / 2 - buyW / 2, barY, buyW / 2, barH);
      // 卖 (从中间向右)
      ctx.fillStyle = colors.quoteDown;
      const sellW = w * 0.5 * (1 - buyRatio) * 2;
      ctx.fillRect(w / 2, barY, sellW / 2, barH);
    }
  }

  // ============ BIDS (从 mid 向下画) ============
  for (let i = 0; i < bids.length; i++) {
    const b = bidsCum[i];
    if (!b) continue; // strict mode 守卫
    const y = bidArea + i * cfg.rowHeight;
    if (y > h) break;

    const barW = (b.cum / maxCum) * w * 0.9;
    ctx.fillStyle = colors.bgBuy;
    ctx.fillRect(w - barW, y, barW, cfg.rowHeight);

    ctx.fillStyle = colors.quoteUp;
    ctx.font = `11px var(--font-data, ui-monospace, monospace)`;
    ctx.textAlign = 'left';
    ctx.fillText(b.price.toFixed(2), cfg.priceCol, y + cfg.rowHeight / 2);

    ctx.fillStyle = colors.textPrimary;
    ctx.textAlign = 'right';
    ctx.fillText(formatSize(b.size), cfg.sizeCol, y + cfg.rowHeight / 2);

    ctx.fillStyle = colors.textMuted;
    ctx.textAlign = 'right';
    ctx.fillText(formatSize(b.cum), cfg.cumCol, y + cfg.rowHeight / 2);

    if (b.hasLargeOrder || b.size * b.price >= whaleThreshold) {
      ctx.fillStyle = colors.whaleBuy;
      ctx.beginPath();
      ctx.arc(8, y + cfg.rowHeight / 2, 3, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

// ============================================================
// 最近成交流 (右侧虚拟列表)
// ============================================================

function TradeStream({
  trades,
  whaleThreshold,
}: {
  trades: OL2Trade[];
  whaleThreshold: number;
}) {
  // 最多显示 50 笔(更多用虚拟化,但成交流通常滚动消失,50 足够)
  const visible = trades.slice(0, 50);
  return (
    <div
      style={{
        background: 'var(--card)',
        borderLeft: '1px solid var(--border)',
        fontFamily: 'var(--font-data, ui-monospace, monospace)',
        fontSize: 11,
        overflow: 'hidden',
      }}
    >
      <div
        style={{
          padding: '6px 10px',
          color: 'var(--text-muted)',
          borderBottom: '1px solid var(--border)',
          display: 'flex',
          justifyContent: 'space-between',
          fontSize: 10,
        }}
      >
        <span>Time</span>
        <span>Price</span>
        <span>Size</span>
      </div>
      {visible.map((t, i) => {
        const isWhale = t.isWhale ?? t.size * t.price >= whaleThreshold;
        const c = t.side === 'buy' ? 'var(--quote-up)' : 'var(--quote-down)';
        return (
          <div
            key={`${t.timestamp}-${i}`}
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              padding: '2px 10px',
              color: c,
              fontVariantNumeric: 'tabular-nums',
              background: isWhale
                ? `color-mix(in oklch, ${c} 12%, transparent)`
                : 'transparent',
              borderLeft: isWhale ? `2px solid ${c}` : '2px solid transparent',
            }}
          >
            <span style={{ color: 'var(--text-muted)', fontSize: 10 }}>
              {formatTime(t.timestamp)}
            </span>
            <span>{t.price.toFixed(2)}</span>
            <span>
              {formatSize(t.size)}
              {isWhale && <span style={{ marginLeft: 4 }}>🐋</span>}
            </span>
          </div>
        );
      })}
    </div>
  );
}

// ============================================================
// 组件主体
// ============================================================

export const OOrderbookL2 = forwardRef<HTMLDivElement, OOrderbookL2Props>(
  function OOrderbookL2(
    {
      data: dataProp,
      loading,
      error,
      empty,
      channel: channelProp,
      symbol,
      levels = 20,
      height = 480,
      showTrades = true,
      showFlow = true,
      whaleThreshold = 50000,
      syncToCrosshair,
      dataDelay,
      lowPerformanceMode = false,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    // 数据源解析:三选一
    const channel = channelProp ?? (symbol ? `l2:${symbol}` : null);
    const fastData = useFastData();
    const crosshair = useCrosshair();

    const [streamData, setStreamData] = useState<OL2Data | null>(null);

    useEffect(() => {
      if (!channel || !fastData) return;
      // 先取快照
      const snap = fastData.snapshot<OL2Data>(channel);
      if (snap) setStreamData(snap);
      // 订阅
      const unsub = fastData.subscribe<OL2Data>(channel, (next) => {
        setStreamData(next);
      });
      return unsub;
    }, [channel, fastData]);

    const data = dataProp ?? streamData;
    const state = resolveBlockState({ data, loading, error, empty });

    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const containerRef = useRef<HTMLDivElement | null>(null);
    const dataRef = useRef<OL2Data | null>(data);
    const rafRef = useRef<number | null>(null);
    const needsDrawRef = useRef(true);

    // 同步 data ref
    useEffect(() => {
      dataRef.current = data;
      needsDrawRef.current = true;
    }, [data]);

    // 绘制循环 (60fps,但仅在 needsDraw 时画)
    useEffect(() => {
      if (state !== 'ready') return;
      const canvas = canvasRef.current;
      const container = containerRef.current;
      if (!canvas || !container) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      let lastW = 0;
      let lastH = 0;
      let cancelled = false;

      function frame() {
        if (cancelled) return;
        const cw = container!.clientWidth;
        const ch = container!.clientHeight;
        if (cw !== lastW || ch !== lastH) {
          const dpr = Math.min(window.devicePixelRatio || 1, 2);
          canvas!.width = cw * dpr;
          canvas!.height = ch * dpr;
          canvas!.style.width = `${cw}px`;
          canvas!.style.height = `${ch}px`;
          ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
          lastW = cw;
          lastH = ch;
          needsDrawRef.current = true;
        }
        if (needsDrawRef.current && dataRef.current) {
          const colors = readColors();
          drawBook(
            ctx!,
            cw,
            ch,
            dataRef.current,
            levels,
            {
              rowHeight: lowPerformanceMode ? 18 : 16,
              priceCol: 18,
              sizeCol: cw * 0.55,
              cumCol: cw - 8,
              midBarHeight: 32,
              showFlow,
            },
            colors,
            whaleThreshold
          );
          needsDrawRef.current = false;
        }
        rafRef.current = requestAnimationFrame(frame);
      }
      frame();

      // ResizeObserver 强制重绘
      const ro = new ResizeObserver(() => {
        needsDrawRef.current = true;
      });
      ro.observe(container);

      return () => {
        cancelled = true;
        if (rafRef.current) cancelAnimationFrame(rafRef.current);
        ro.disconnect();
      };
    }, [state, levels, whaleThreshold, showFlow, lowPerformanceMode]);

    // 鼠标移动 → CrosshairProvider broadcast
    function onMouseMove(e: React.MouseEvent<HTMLCanvasElement>) {
      if (!syncToCrosshair || !crosshair || !data) return;
      const rect = e.currentTarget.getBoundingClientRect();
      const y = e.clientY - rect.top;
      // 简化:点中 ask/bid 估算价格
      const midY = rect.height / 2;
      const rowH = 16;
      const indexFromMid = Math.round((midY - y) / rowH);
      let price: number | null = null;
      if (indexFromMid > 0) {
        const askRow = data.asks[indexFromMid - 1];
        if (askRow) price = askRow.price;
      } else if (indexFromMid < 0) {
        const bidRow = data.bids[-indexFromMid - 1];
        if (bidRow) price = bidRow.price;
      }
      if (price != null) {
        crosshair.broadcast({
          symbol: syncToCrosshair,
          value: price,
          source: 'orderbook',
        });
      }
    }

    function onMouseLeave() {
      if (syncToCrosshair && crosshair) {
        crosshair.clear();
      }
    }

    // ===== 状态机渲染 =====
    if (state === 'loading')
      return (
        <div
          ref={ref}
          className={cn(
            'rounded-md border border-border bg-card overflow-hidden @container',
            className
          )}
          style={{ height }}
        >
          <OLoadingState rows={5} />
        </div>
      );
    if (state === 'error')
      return <OErrorState ref={ref} error={error!} className={className} />;
    if (
      state === 'empty' ||
      !data ||
      (data.bids.length === 0 && data.asks.length === 0)
    )
      return <OEmptyState ref={ref} title="No orderbook data" className={className} />;

    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border overflow-hidden flex',
          className
        )}
        style={{
          height,
          background: 'var(--card)',
        }}
      >
        {/* 主盘口 */}
        <div
          ref={containerRef}
          style={{
            flex: showTrades ? '1 1 auto' : '1 1 100%',
            position: 'relative',
            minWidth: 0,
          }}
        >
          <div
            style={{
              padding: '6px 10px',
              fontSize: 11,
              color: 'var(--text-muted)',
              borderBottom: '1px solid var(--border)',
              display: 'flex',
              justifyContent: 'space-between',
              fontFamily: 'var(--font-data, ui-monospace, monospace)',
            }}
          >
            <span style={{ color: 'var(--foreground)', fontWeight: 600 }}>
              {data.symbol}
            </span>
            <span>L2 · {data.bids.length + data.asks.length} lvl</span>
          </div>
          <canvas
            ref={canvasRef}
            onMouseMove={syncToCrosshair ? onMouseMove : undefined}
            onMouseLeave={syncToCrosshair ? onMouseLeave : undefined}
            style={{
              display: 'block',
              width: '100%',
              height: 'calc(100% - 28px)',
              cursor: syncToCrosshair ? 'crosshair' : 'default',
            }}
            aria-label={`${data.symbol} orderbook with ${data.bids.length} bids and ${data.asks.length} asks`}
          />
          {dataDelay != null ? (
            <div
              style={{
                position: 'absolute',
                bottom: 4,
                right: 8,
                fontSize: 10,
                color: 'var(--text-hint)',
                pointerEvents: 'none',
              }}
            >
              延时 {dataDelay} 分钟
            </div>
          ) : null}
        </div>

        {/* 成交流 */}
        {showTrades && data.recentTrades ? (
          <div style={{ width: 200, flexShrink: 0 }}>
            <TradeStream trades={data.recentTrades} whaleThreshold={whaleThreshold} />
          </div>
        ) : null}
      </div>
    );
  }
);

OOrderbookL2.displayName = 'OOrderbookL2';
