/**
 * OWalkForwardChart — walk-forward CPCV fold 分解图(量化通用)。
 *
 * 每 fold 的 IS/OOS Sharpe 并排,方差可视化。
 * fold 方差高是策略 FAIL 主因,要看得见(诚实诊断)。
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface WalkForwardFold {
  fold: number;
  is_sharpe: number;   // in-sample
  oos_sharpe: number;  // out-of-sample
}

export interface OWalkForwardChartProps extends Omit<OBlockBaseProps, 'variant'> {
  folds: WalkForwardFold[];
  /** OOS Sharpe 目标线(低于则该 fold 不达标) */
  threshold?: number;
}

export const OWalkForwardChart = forwardRef<HTMLDivElement, OWalkForwardChartProps>(
  function OWalkForwardChart({ folds, threshold = 0, className, ...rest }, ref) {
    const allVals = folds.flatMap(f => [f.is_sharpe, f.oos_sharpe]);
    const max = Math.max(1, ...allVals);
    const min = Math.min(0, ...allVals);
    const range = max - min || 1;
    const h = (v: number) => `${((v - min) / range) * 100}%`;

    // OOS 方差(诊断)
    const oosVals = folds.map(f => f.oos_sharpe);
    const mean = oosVals.reduce((a, b) => a + b, 0) / (oosVals.length || 1);
    const variance = oosVals.reduce((a, b) => a + (b - mean) ** 2, 0) / (oosVals.length || 1);

    return (
      <div ref={ref} className={cn('rounded-lg border border-border bg-card p-4', className)} {...rest}>
        <div className="flex items-center justify-between mb-3">
          <span className="text-sm font-bold">Walk-Forward Folds</span>
          <span className="text-xs text-muted-foreground tabular-nums">
            OOS 方差 {variance.toFixed(3)}
            {variance > 0.5 && <span className="text-destructive ml-1">⚠ 高</span>}
          </span>
        </div>

        <div className="flex items-end gap-3 h-32" style={{ borderBottom: '1px solid var(--border)' }}>
          {folds.map(f => (
            <div key={f.fold} className="flex-1 flex flex-col items-center gap-1 h-full justify-end">
              <div className="flex items-end gap-0.5 w-full h-full justify-center">
                {/* IS */}
                <div className="w-3 rounded-t" title={`IS ${f.is_sharpe.toFixed(2)}`}
                  style={{ height: h(f.is_sharpe), background: 'color-mix(in oklch, var(--primary) 50%, transparent)' }} />
                {/* OOS */}
                <div className="w-3 rounded-t" title={`OOS ${f.oos_sharpe.toFixed(2)}`}
                  style={{ height: h(f.oos_sharpe),
                    background: f.oos_sharpe >= threshold ? 'var(--success, oklch(0.62 0.18 145))' : 'var(--destructive)' }} />
              </div>
              <span className="text-[10px] text-muted-foreground">f{f.fold}</span>
            </div>
          ))}
        </div>

        <div className="flex items-center gap-4 mt-2 text-[10px] text-muted-foreground">
          <span className="flex items-center gap-1">
            <span className="inline-block w-2 h-2 rounded" style={{ background: 'color-mix(in oklch, var(--primary) 50%, transparent)' }} /> IS
          </span>
          <span className="flex items-center gap-1">
            <span className="inline-block w-2 h-2 rounded" style={{ background: 'var(--success, oklch(0.62 0.18 145))' }} /> OOS
          </span>
        </div>
      </div>
    );
  }
);

OWalkForwardChart.displayName = 'OWalkForwardChart';
