/**
 * OAnomalyFeed (Tide Wave 3 E16, Block)
 *
 * 多源异常聚合显示。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §2.1
 *
 * 3 variant:
 *   - compact: 5 列 grid(default A1 cell)
 *   - big: 卡片 + severity 边框(monitor 左列)
 *   - full-page: 表格(/realtime page)
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export type AnomalySeverity = 'critical' | 'major' | 'minor' | 'info';
export type AnomalySource =
  | 'regime'
  | 'detector'
  | 'position'
  | 'discipline'
  | 'watchlist'
  | 'policy';

export interface AnomalyAction {
  label: string;
  actionType: 'navigate' | 'modal' | 'mute' | 'external';
  target?: string;
  actionVariant: 'primary' | 'secondary';
}

export interface AnomalyEntry {
  id: string;
  severity: AnomalySeverity;
  type: string;
  description: string;
  symbol?: string;
  industry?: string;
  time: string | Date;
  timeRelative: string;
  source: AnomalySource;
  read: boolean;
  pushedToTelegram?: boolean;
  actions: AnomalyAction[];
  context?: Record<string, unknown>;
}

export interface OAnomalyFeedProps extends Omit<OBlockBaseProps, 'variant'> {
  anomalies: AnomalyEntry[];
  feedVariant: 'compact' | 'big' | 'full-page';
  showActions?: boolean;
  showRead?: boolean;
  onItemClick?: (item: AnomalyEntry) => void;
  onActionClick?: (item: AnomalyEntry, action: AnomalyAction) => void;
  onMarkRead?: (item: AnomalyEntry) => void;
  onMute?: (item: AnomalyEntry, scope: string, duration: string) => void;
  emptyMessage?: string;
}

const SEVERITY_STYLE: Record<AnomalySeverity, { border: string; bg: string; icon: string }> = {
  critical: {
    border: 'var(--red-up)',
    bg: 'color-mix(in srgb, var(--red-up) 8%, transparent)',
    icon: '🔴',
  },
  major: {
    border: 'var(--yellow)',
    bg: 'color-mix(in srgb, var(--yellow) 6%, transparent)',
    icon: '🟡',
  },
  minor: { border: 'var(--text-tertiary)', bg: 'transparent', icon: '⚪' },
  info: { border: 'var(--text-tertiary)', bg: 'transparent', icon: 'ℹ' },
};

export const OAnomalyFeed = forwardRef<HTMLDivElement, OAnomalyFeedProps>(
  function OAnomalyFeed(
    {
      anomalies,
      feedVariant,
      showActions = true,
      showRead: _showRead,
      onItemClick,
      onActionClick,
      onMarkRead: _onMarkRead,
      emptyMessage = '今日无 critical, 系统正常运行',
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    if (anomalies.length === 0) {
      return (
        <div
          ref={ref}
          className={cn(
            'px-4 py-6 text-center text-sm @container',
            'border border-dashed rounded',
            className
          )}
          style={{
            color: 'var(--text-tertiary)',
            borderColor: 'var(--border-strong)',
          }}
        >
          {emptyMessage}
        </div>
      );
    }

    // compact variant: 紧凑 5 列 grid
    if (feedVariant === 'compact') {
      return (
        <ul
          ref={ref as React.Ref<HTMLUListElement>}
          className={cn('flex flex-col w-full list-none p-0 m-0', className)}
          style={{ fontFamily: 'var(--font-mono)' }}
          aria-label={`异常列表 ${anomalies.length} 条`}
        >
          {anomalies.map((a) => {
            const s = SEVERITY_STYLE[a.severity];
            return (
              <li key={a.id}>
                <button
                  type="button"
                  onClick={() => onItemClick?.(a)}
                  className={cn(
                    'grid items-center gap-2 px-2 py-1 text-left text-xs w-full',
                    'hover:bg-[color:var(--accent)] transition-colors',
                    'border-l-2',
                    !a.read && 'font-bold'
                  )}
                  style={{
                    gridTemplateColumns: '4px 50px 1fr 70px',
                    borderLeftColor: s.border,
                    backgroundColor: !a.read ? s.bg : 'transparent',
                  }}
                >
                  <span />
                  <span style={{ color: 'var(--text-tertiary)' }}>{a.timeRelative}</span>
                  <span style={{ color: 'var(--foreground)' }} className="truncate">
                    <span style={{ color: 'var(--muted-foreground)' }}>[{a.type}]</span>{' '}
                    {a.description}
                  </span>
                  <span
                    className="text-right"
                    style={{ color: 'var(--muted-foreground)', fontFamily: 'var(--font-mono)' }}
                  >
                    {a.symbol ?? a.industry ?? ''}
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      );
    }

    // big variant: 大卡片 + severity glow
    if (feedVariant === 'big') {
      return (
        <ul
          ref={ref as React.Ref<HTMLUListElement>}
          className={cn('flex flex-col gap-2 list-none p-0 m-0', className)}
          style={{ fontFamily: 'var(--font-mono)' }}
          aria-label={`异常列表 ${anomalies.length} 条`}
        >
          {anomalies.map((a) => {
            const s = SEVERITY_STYLE[a.severity];
            return (
              <li
                key={a.id}
                className={cn(
                  'flex flex-col gap-1.5 px-3 py-2 rounded',
                  'border-l-4',
                  'bg-[color:var(--card)]'
                )}
                style={{
                  borderLeftColor: s.border,
                  boxShadow:
                    a.severity === 'critical'
                      ? `0 0 12px color-mix(in srgb, ${s.border} 30%, transparent)`
                      : undefined,
                }}
              >
                <div className="flex items-center gap-2">
                  <span aria-hidden="true">{s.icon}</span>
                  <span
                    style={{
                      color: s.border,
                      fontWeight: 700,
                      fontSize: 11,
                      textTransform: 'uppercase',
                    }}
                  >
                    [{a.type}]
                  </span>
                  <span
                    className="text-[10px] ml-auto"
                    style={{ color: 'var(--text-tertiary)' }}
                  >
                    {a.timeRelative}
                  </span>
                </div>
                <button
                  type="button"
                  onClick={() => onItemClick?.(a)}
                  className="text-sm text-left hover:opacity-80 transition-opacity"
                  style={{
                    color: 'var(--foreground)',
                    fontFamily: 'var(--font-sans)',
                  }}
                >
                  {a.description}
                </button>
                {(a.symbol || a.industry) && (
                  <div
                    className="text-[10px] flex items-center gap-2"
                    style={{ color: 'var(--muted-foreground)' }}
                  >
                    {a.symbol && <span>📊 {a.symbol}</span>}
                    {a.industry && <span>🏢 {a.industry}</span>}
                  </div>
                )}
                {showActions && a.actions.length > 0 && (
                  <div className="flex gap-1.5 flex-wrap">
                    {a.actions.map((act, i) => (
                      <button
                        key={i}
                        type="button"
                        onClick={() => onActionClick?.(a, act)}
                        className={cn('px-2 py-0.5 text-[10px] rounded transition-opacity hover:opacity-80')}
                        style={
                          act.actionVariant === 'primary'
                            ? { backgroundColor: 'var(--blue-accent)', color: '#fff' }
                            : { backgroundColor: 'var(--muted)', color: 'var(--foreground)' }
                        }
                      >
                        {act.label}
                      </button>
                    ))}
                  </div>
                )}
              </li>
            );
          })}
        </ul>
      );
    }

    // full-page variant: 表格
    return (
      <div
        ref={ref}
        className={cn('flex flex-col w-full', className)}
        style={{ fontFamily: 'var(--font-mono)' }}
        role="table"
        aria-label={`异常列表 ${anomalies.length} 条`}
      >
        <div
          className="grid items-center gap-2 px-2 py-1 text-[10px] uppercase tracking-[0.04em] border-b"
          style={{
            gridTemplateColumns: '60px 100px 70px 1fr 80px 100px',
            color: 'var(--text-tertiary)',
            borderColor: 'var(--border-strong)',
          }}
          role="row"
        >
          <div>时间</div>
          <div>类型</div>
          <div>级别</div>
          <div>详情</div>
          <div>标的</div>
          <div className="text-right">操作</div>
        </div>
        {anomalies.map((a) => {
          const s = SEVERITY_STYLE[a.severity];
          return (
            <button
              key={a.id}
              type="button"
              onClick={() => onItemClick?.(a)}
              className={cn(
                'grid items-center gap-2 px-2 py-1.5 text-left text-xs',
                'hover:bg-[color:var(--accent)] transition-colors',
                'border-b border-[color:var(--border-subtle)]',
                !a.read && 'font-bold'
              )}
              style={{
                gridTemplateColumns: '60px 100px 70px 1fr 80px 100px',
                color: 'var(--foreground)',
              }}
              role="row"
            >
              <span style={{ color: 'var(--text-tertiary)' }}>{a.timeRelative}</span>
              <span style={{ color: 'var(--muted-foreground)' }}>{a.type}</span>
              <span style={{ color: s.border, fontWeight: 700 }}>
                {s.icon} {a.severity}
              </span>
              <span className="truncate">{a.description}</span>
              <span style={{ color: 'var(--muted-foreground)' }}>{a.symbol ?? '-'}</span>
              <span className="text-right" style={{ color: 'var(--text-tertiary)' }}>
                {a.actions.length} 项
              </span>
            </button>
          );
        })}
      </div>
    );
  }
);

OAnomalyFeed.displayName = 'OAnomalyFeed';
