/**
 * @helios/blocks recipe 层(Layer 3)
 * ───────────────────────────────────────────────────────────────────────────
 * 单一真源:所有原子组件的视觉决策集中在此,只消费语义 token + 控件 token。
 * 组件文件不写裸值;改 token → 全组件级联;改 recipe → 用它的组件全变。
 * 密度(comfortable/compact/terminal)由 [data-density] 的 token 覆盖驱动,
 * recipe 用 var(--control-*) 自动适配,无需感知密度模式。
 *
 * 标杆锚定:通用控件 = Apple HIG + shadcn/ui(Tailwind v4)+ Radix。
 */
import { cva, type VariantProps } from 'class-variance-authority';

// 统一焦点环(全不透明 2px + 2px offset,过 WCAG 1.4.11 的 3:1;不用 shadcn 的 ring/50)
const FOCUS =
  'outline-none focus-visible:ring-2 focus-visible:ring-[color:var(--ring)] ' +
  'focus-visible:ring-offset-2 focus-visible:ring-offset-[color:var(--background)]';

// ── Button ───────────────────────────────────────────────────────────────────
export const buttonRecipe = cva(
  [
    'inline-flex items-center justify-center whitespace-nowrap select-none',
    'font-[number:var(--fw-medium)] rounded-[var(--control-radius)]',
    // 过渡覆盖 色/阴影/位移;按下微缩 0.98 给出触感反馈(Linear 风)
    'gap-[var(--control-gap)] transition-[color,background-color,border-color,box-shadow,transform] duration-[var(--duration-fast)] ease-[var(--ease-out)]',
    'active:scale-[0.98]',
    'disabled:opacity-50 disabled:pointer-events-none',
    '[&_svg]:size-4 [&_svg]:shrink-0',
    FOCUS,
  ],
  {
    variants: {
      variant: {
        // 实心变体带轻微投影(深度);primary hover 用主题自己的 glow(有则霓虹,无则普通阴影)
        primary:     'bg-[color:var(--primary)] text-[color:var(--primary-foreground)] shadow-[var(--shadow-xs)] hover:bg-[color:var(--primary-hover)] hover:shadow-[var(--shadow-glow-primary,var(--shadow-sm))] active:bg-[color:var(--primary-active)]',
        secondary:   'bg-[color:var(--secondary)] text-[color:var(--secondary-foreground)] shadow-[var(--shadow-xs)] hover:bg-[color:var(--secondary-hover)] hover:shadow-[var(--shadow-sm)] active:bg-[color:var(--secondary-active)]',
        destructive: 'bg-[color:var(--destructive)] text-[color:var(--destructive-foreground)] shadow-[var(--shadow-xs)] hover:bg-[color:var(--destructive-hover)] hover:shadow-[var(--shadow-sm)] active:bg-[color:var(--destructive-active)]',
        outline:     'border border-[color:var(--border)] bg-[color:var(--background)] text-[color:var(--foreground)] hover:bg-[color:var(--primary-subtle)] hover:shadow-[var(--shadow-xs)]',
        ghost:       'bg-transparent text-[color:var(--foreground)] hover:bg-[color:var(--primary-subtle)]',
        link:        'bg-transparent text-[color:var(--primary)] underline-offset-4 hover:underline',
        // 披露控件(展开/折叠触发器):内联、无背景、无固定尺寸、色继承,配合 size='inline'
        disclosure:  'bg-transparent p-0 h-auto font-[number:var(--fw-medium)] hover:opacity-80 [color:inherit]',
      },
      size: {
        sm:   'h-[var(--control-h-sm)] px-[var(--control-px-sm)] text-[length:var(--text-xs)]',
        md:   'h-[var(--control-h-md)] px-[var(--control-px-md)] text-[length:var(--text-sm)]',
        lg:   'h-[var(--control-h-lg)] px-[var(--control-px-lg)] text-[length:var(--text-base)]',
        icon: 'h-[var(--control-h-md)] w-[var(--control-h-md)] p-0',
        inline: 'h-auto p-0 gap-1',
      },
    },
    defaultVariants: { variant: 'primary', size: 'md' },
  }
);
export type ButtonRecipeProps = VariantProps<typeof buttonRecipe>;

// ── Input ─────────────────────────────────────────────────────────────────────
export const inputRecipe = cva(
  [
    'flex w-full rounded-[var(--control-radius)] border bg-[color:var(--background)]',
    'border-[color:var(--input,var(--border))] text-[color:var(--foreground)]',
    'placeholder:text-[color:var(--muted-foreground)]',
    'transition-colors duration-[var(--duration-fast)] ease-[var(--ease-out)]',
    'disabled:opacity-50 disabled:cursor-not-allowed',
    'focus-visible:border-[color:var(--ring)]',
    FOCUS,
  ],
  {
    variants: {
      size: {
        sm: 'h-[var(--control-h-sm)] px-[var(--control-px-sm)] text-[length:var(--text-xs)]',
        md: 'h-[var(--control-h-md)] px-[var(--control-px-md)] text-[length:var(--text-sm)]',
        lg: 'h-[var(--control-h-lg)] px-[var(--control-px-md)] text-[length:var(--text-base)]',
      },
      invalid: {
        true: 'border-[color:var(--destructive)] focus-visible:ring-[color:var(--destructive)]',
        false: '',
      },
    },
    defaultVariants: { size: 'md', invalid: false },
  }
);
export type InputRecipeProps = VariantProps<typeof inputRecipe>;

// ── Card ──────────────────────────────────────────────────────────────────────
export const cardRecipe = cva(
  [
    'rounded-[var(--card-radius)] bg-[color:var(--card)] text-[color:var(--card-foreground)]',
    'transition-[box-shadow,transform] duration-[var(--duration-base)] ease-[var(--ease-out)]',
  ],
  {
    variants: {
      elevation: {
        flat:  '',
        sm:    'shadow-[var(--shadow-sm)]',
        md:    'shadow-[var(--shadow-md)]',
      },
      interactive: {
        // 悬停轻抬 2px + 加深阴影(Vercel/Linear 卡片风),按下回落
        true:  'hover:shadow-[var(--shadow-md)] hover:-translate-y-0.5 active:translate-y-0 active:shadow-[var(--shadow-sm)] cursor-pointer',
        false: '',
      },
      // 边框强调:normal=1px 常规边框, emphasis=2px(用 accentColor 配合动态色)
      emphasis: {
        true:  'border-2',
        false: 'border border-[color:var(--border)]',
      },
      // 开启 CSS 容器查询(高层组件响应式所需)
      container: {
        true:  '@container',
        false: '',
      },
    },
    defaultVariants: { elevation: 'sm', interactive: false, emphasis: false, container: false },
  }
);
export type CardRecipeProps = VariantProps<typeof cardRecipe>;

// ── Badge ─────────────────────────────────────────────────────────────────────
export const badgeRecipe = cva(
  [
    'inline-flex items-center gap-[var(--space-1)] w-fit',
    'px-[var(--space-2)] py-[var(--space-0-5,2px)]',
    'text-[length:var(--text-xs)] font-[number:var(--fw-medium)]',
    'border [&_svg]:size-3 [&_svg]:shrink-0',
    'transition-colors duration-[var(--duration-fast)]',
  ],
  {
    variants: {
      variant: {
        neutral:     'bg-[color:var(--muted)] text-[color:var(--muted-foreground)] border-transparent',
        primary:     'bg-[color:var(--primary-subtle)] text-[color:var(--primary)] border-[color:var(--primary)]/30',
        success:     'bg-[color:var(--success-subtle)] text-[color:var(--success)] border-[color:var(--success)]/30',
        warning:     'bg-[color:var(--warning-subtle)] text-[color:var(--warning)] border-[color:var(--warning)]/30',
        destructive: 'bg-[color:var(--destructive-subtle)] text-[color:var(--destructive)] border-[color:var(--destructive)]/30',
        outline:     'bg-transparent text-[color:var(--foreground)] border-[color:var(--border)]',
      },
      shape: {
        rounded: 'rounded-[var(--radius-md)]',
        pill:    'rounded-[var(--radius-full)]',
      },
    },
    defaultVariants: { variant: 'neutral', shape: 'rounded' },
  }
);
export type BadgeRecipeProps = VariantProps<typeof badgeRecipe>;

// ── Checkbox / Radio(方形/圆形选择框)────────────────────────────────────────
export const checkboxRecipe = cva(
  [
    'peer shrink-0 border border-[color:var(--input,var(--border))]',
    'bg-[color:var(--background)] transition-colors duration-[var(--duration-fast)]',
    'disabled:opacity-50 disabled:cursor-not-allowed',
    'data-[checked=true]:bg-[color:var(--primary)] data-[checked=true]:border-[color:var(--primary)]',
    'data-[checked=true]:text-[color:var(--primary-foreground)]',
    FOCUS,
  ],
  {
    variants: {
      shape: { square: 'rounded-[4px]', circle: 'rounded-full' },
      size: {
        sm: 'size-[0.875rem]',   // 14px
        md: 'size-4',            // 16px
      },
    },
    defaultVariants: { shape: 'square', size: 'md' },
  }
);
export type CheckboxRecipeProps = VariantProps<typeof checkboxRecipe>;

// ── Switch(开关)─────────────────────────────────────────────────────────────
export const switchRecipe = cva(
  [
    'peer inline-flex shrink-0 items-center rounded-full border-2 border-transparent',
    'transition-colors duration-[var(--duration-fast)] ease-[var(--ease-snappy)]',
    'disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer',
    'bg-[color:var(--input,var(--border))]',
    'data-[checked=true]:bg-[color:var(--primary)]',
    FOCUS,
  ],
  {
    variants: {
      size: {
        sm: 'h-4 w-7',           // track 16×28
        md: 'h-[1.15rem] w-8',   // ~18×32 (shadcn v4)
      },
    },
    defaultVariants: { size: 'md' },
  }
);
export const switchThumbRecipe = cva(
  [
    'pointer-events-none block rounded-full bg-[color:var(--background)]',
    'shadow-[var(--shadow-sm)] ring-0 transition-transform duration-[var(--duration-fast)] ease-[var(--ease-snappy)]',
    'translate-x-0 data-[checked=true]:translate-x-[calc(100%-0px)]',
  ],
  {
    variants: { size: { sm: 'size-3', md: 'size-4' } },
    defaultVariants: { size: 'md' },
  }
);
export type SwitchRecipeProps = VariantProps<typeof switchRecipe>;

