/**
 * OAISummaryCard — 渲染 daily_digest agent output 摘要
 *
 * 消费 API v1.0 §4.2.2 daily_digest output:
 *   { new_substrates: number, digest_sent: boolean, summary: string }
 * 加上 AgentRun.citations 引用。
 *
 * 设计:
 *   - 标题 + 日期(可选)
 *   - 摘要文本
 *   - new_substrates 计数 badge
 *   - citations 列表(强制渲染,OCitationCard)
 *   - digest_sent 状态指示
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import { OCitationCard } from '../OCitationCard';
import type { Citation, AgentCitation } from '../../types/stratum';
import type { OBlockBaseProps } from '../../lib/types';

export interface OAISummaryCardProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 'default' = 自带框+标题;'ghost' = 无框无背景无标题(嵌入 OWidgetFrame 等容器时用) */
  variant?: 'default' | 'ghost';
  /** 标题(可选,默认 "每日摘要")。 */
  title?: string;
  /** 日期(可选,显示在标题旁,ISO 8601 或自由 string)。 */
  date?: string;
  /** 摘要正文。 */
  summary: string;
  /** 新增 substrate 数。 */
  newSubstrates?: number;
  /** 摘要是否已推送。 */
  digestSent?: boolean;
  /** 引用列表(强制渲染)。 */
  citations?: Array<Citation | AgentCitation>;
  /** 点击 citation 回调。 */
  onCitationClick?: (c: Citation | AgentCitation) => void;
}

export const OAISummaryCard = forwardRef<HTMLDivElement, OAISummaryCardProps>(
  function OAISummaryCard(
    {
      title = '每日摘要',
      variant = 'default',
      date,
      summary,
      newSubstrates,
      digestSent,
      citations = [],
      onCitationClick,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const isGhost = variant === 'ghost';
    return (
      <article
        ref={ref}
        className={cn(
          'flex flex-col gap-3 @container',
          isGhost ? '' : 'px-4 py-3 rounded-lg bg-card border border-border',
          className
        )}
      >
        {!isGhost && (
        <header className="flex items-center justify-between gap-2 flex-wrap">
          <div className="flex items-center gap-2">
            <span aria-hidden="true">📰</span>
            <h3 className="text-base font-bold text-[color:var(--foreground)] tracking-[-0.01em]">
              {title}
            </h3>
            {date && (
              <span className="text-xs text-[color:var(--text-muted)] font-mono">
                {date}
              </span>
            )}
          </div>
          <div className="flex items-center gap-2">
            {typeof newSubstrates === 'number' && (
              <span
                className={cn(
                  'px-2 py-0.5 rounded text-xs font-mono',
                  'bg-primary/20 text-primary'
                )}
              >
                +{newSubstrates} 新条目
              </span>
            )}
            {digestSent !== undefined && (
              <span
                className={cn(
                  'px-2 py-0.5 rounded text-xs',
                  digestSent
                    ? 'bg-green-500/20 text-green-700 dark:text-green-300'
                    : 'bg-muted text-[color:var(--text-muted)]'
                )}
              >
                {digestSent ? '已推送' : '未推送'}
              </span>
            )}
          </div>
        </header>
        )}

        <div className="text-sm leading-relaxed text-[color:var(--foreground)] whitespace-pre-wrap">
          {summary}
        </div>

        {citations.length > 0 && (
          <footer className="flex flex-col gap-1">
            <div className="text-[10px] uppercase tracking-[0.04em] text-[color:var(--text-muted)] font-semibold">
              引用 ({citations.length})
            </div>
            <div className="flex flex-wrap gap-1.5">
              {citations.map((c, i) => (
                <OCitationCard
                  key={`${c.substrate_id}-${c.fragment_id ?? i}`}
                  citation={c}
                  compact
                  {...(onCitationClick && { onClick: () => onCitationClick(c) })}
                />
              ))}
            </div>
          </footer>
        )}
      </article>
    );
  }
);

OAISummaryCard.displayName = 'OAISummaryCard';
