'use client';
import { forwardRef, type HTMLAttributes } from 'react';
import { cn } from '../../lib/cn';
import { progressTrackRecipe, progressBarRecipe, type ProgressTrackRecipeProps } from '../../recipes';
export interface OProgressProps extends HTMLAttributes<HTMLDivElement>, ProgressTrackRecipeProps {
  value?: number;
  max?: number;
}
export const OProgress = forwardRef<HTMLDivElement, OProgressProps>(
  function OProgress({ className, value = 0, max = 100, size, ...props }, ref) {
    const pct = Math.max(0, Math.min(100, (value / max) * 100));
    return (
      <div ref={ref} role="progressbar" aria-valuenow={value} aria-valuemin={0} aria-valuemax={max}
        className={cn(progressTrackRecipe({ size }), className)} {...props}>
        <div className={progressBarRecipe()} style={{ transform: `translateX(-${100 - pct}%)` }} />
      </div>
    );
  }
);
OProgress.displayName = 'OProgress';
