/**
 * OPolicyHeatmap (Tide Wave 3 E25, Block)
 *
 * 政策×板块 热力(intensity * 时间衰减)。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §4.2
 */
import { forwardRef, useMemo } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface PolicyHeatmapCell {
  policy: string;
  sector: string;
  /** -1 to +1 */
  intensity: number;
  /** 距今天数 */
  daysAgo: number;
}

export interface OPolicyHeatmapProps extends Omit<OBlockBaseProps, 'variant'> {
  data: PolicyHeatmapCell[];
  policies: string[];
  sectors: string[];
  /** 半衰期(天),用于时间衰减 */
  halfLifeDays?: number;
  onCellClick?: (cell: PolicyHeatmapCell) => void;
}

function decay(daysAgo: number, halfLife: number): number {
  return Math.pow(0.5, daysAgo / halfLife);
}

function cellColor(adjIntensity: number): string {
  // -1..+1, A 股: + 为利好(红)
  const abs = Math.abs(adjIntensity);
  if (abs < 0.05) return 'var(--muted)';
  const c = adjIntensity > 0 ? 'var(--red-up)' : 'var(--green-down)';
  return `color-mix(in srgb, ${c} ${Math.round(abs * 70)}%, var(--card))`;
}

export const OPolicyHeatmap = forwardRef<HTMLDivElement, OPolicyHeatmapProps>(
  function OPolicyHeatmap(
    {
      data,
      policies,
      sectors,
      halfLifeDays = 30,
      onCellClick,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const grid = useMemo(() => {
      const map = new Map<string, PolicyHeatmapCell>();
      for (const d of data) {
        const key = `${d.policy}|${d.sector}`;
        map.set(key, d);
      }
      return map;
    }, [data]);

    return (
      <div
        ref={ref}
        className={cn(
          'flex flex-col gap-1 px-2 py-2 rounded @container',
          'bg-[color:var(--card)] border border-[color:var(--border-strong)]',
          className
        )}
        style={{ fontFamily: 'var(--font-mono)' }}
        role="table"
        aria-label="政策×板块 热力图"
      >
        <div className="text-[10px] uppercase tracking-[0.04em] flex items-center justify-between mb-1"
          style={{ color: 'var(--text-tertiary)' }}
        >
          <span>政策 × 板块</span>
          <span>半衰期 {halfLifeDays}d</span>
        </div>

        {/* header row: sectors */}
        <div
          className="grid items-center"
          style={{
            gridTemplateColumns: `100px repeat(${sectors.length}, 1fr)`,
            gap: 2,
          }}
          role="row"
        >
          <div />
          {sectors.map((s) => (
            <div
              key={s}
              role="columnheader"
              className="text-[9px] text-center truncate"
              style={{ color: 'var(--muted-foreground)' }}
              title={s}
            >
              {s}
            </div>
          ))}
        </div>

        {/* policies rows */}
        {policies.map((p) => (
          <div
            key={p}
            className="grid items-center"
            style={{
              gridTemplateColumns: `100px repeat(${sectors.length}, 1fr)`,
              gap: 2,
            }}
            role="row"
          >
            <div
              role="rowheader"
              className="text-[10px] truncate"
              style={{ color: 'var(--foreground)' }}
              title={p}
            >
              {p}
            </div>
            {sectors.map((s) => {
              const c = grid.get(`${p}|${s}`);
              const adj = c ? c.intensity * decay(c.daysAgo, halfLifeDays) : 0;
              const bg = cellColor(adj);
              const display = c && Math.abs(adj) >= 0.05 ? (adj * 100).toFixed(0) : '';
              return (
                <div
                  key={s}
                  role="cell"
                  aria-label={`${p} ${s} ${display ? `强度 ${display}%` : '无信号'}`}
                >
                  <button
                    type="button"
                    disabled={!c || !onCellClick}
                    onClick={() => c && onCellClick?.(c)}
                    aria-label={`${p} × ${s}`}
                    className={cn(
                      'w-full h-[18px] rounded text-[9px] font-bold',
                      c && onCellClick && 'cursor-pointer hover:opacity-80'
                    )}
                    style={{ backgroundColor: bg, color: '#fff', border: 'none' }}
                  >
                    {display}
                  </button>
                </div>
              );
            })}
          </div>
        ))}
      </div>
    );
  }
);

OPolicyHeatmap.displayName = 'OPolicyHeatmap';
