/**
 * OStatusBadge - 状态徽章。
 *
 * 标准 6 状态: active / inactive / error / warning / pending / info
 * 自定义 status: 用 'custom' + 自定义 colorVar / label。
 *
 * pulse 动画在 reduced-motion 下自动关闭。
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, type CSSProperties } from 'react';
import { cn } from '../../lib/cn';
import { useReducedMotion } from '../../hooks/useReducedMotion';
import type { OBlockBaseProps } from '../../lib/types';

const badgeVariants = cva(
  'inline-flex items-center gap-1.5 rounded-full border font-medium whitespace-nowrap transition-colors',
  {
    variants: {
      status: {
        active: 'bg-success/15 text-success border-success/30',
        inactive: 'bg-muted text-muted-foreground border-border',
        error: 'bg-destructive/15 text-destructive border-destructive/30',
        warning: 'bg-warning/15 text-warning border-warning/30',
        pending: 'bg-info/15 text-info border-info/30',
        info: 'bg-info/15 text-info border-info/30',
        custom: '',
      },
      size: {
        sm: 'px-[var(--space-2)] py-0.5 text-[length:var(--text-xs)]',
        md: 'px-[var(--space-2)] py-0.5 text-[length:var(--text-sm)]',
        lg: 'px-[var(--space-3)] py-1 text-[length:var(--text-base)]',
      },
    },
    defaultVariants: {
      status: 'active',
      size: 'sm',
    },
  }
);

type BadgeVariantProps = VariantProps<typeof badgeVariants>;

export interface OStatusBadgeProps
  extends Omit<OBlockBaseProps, 'variant' | 'size'>,
    BadgeVariantProps {
  /** 标签文本。 */
  label: string;
  /** 是否启用 pulse 动画 (active/error/pending 推荐)。 */
  pulse?: boolean;
  /** custom status 的颜色变量名 (e.g. '--chart-3')。 */
  customColorVar?: string;
}

const DEFAULT_DOT_COLOR: Record<string, string> = {
  active: 'var(--success)',
  inactive: 'var(--muted-foreground)',
  error: 'var(--destructive)',
  warning: 'var(--warning)',
  pending: 'var(--info)',
  info: 'var(--info)',
};

export const OStatusBadge = forwardRef<HTMLSpanElement, OStatusBadgeProps>(function OStatusBadge(
  { status = 'active', size = 'sm', label, pulse = false, customColorVar, className, theme: _t, ...rest },
  ref
) {
  const reduced = useReducedMotion();
  const animate = pulse && !reduced;
  const dotColor =
    status === 'custom' && customColorVar
      ? `var(${customColorVar})`
      : DEFAULT_DOT_COLOR[status ?? 'active'] ?? 'currentColor';

  const dotStyle: CSSProperties = { backgroundColor: dotColor };
  const customStyle: CSSProperties | undefined =
    status === 'custom' && customColorVar
      ? {
          color: `var(${customColorVar})`,
          borderColor: `color-mix(in oklch, var(${customColorVar}) 30%, transparent)`,
          backgroundColor: `color-mix(in oklch, var(${customColorVar}) 15%, transparent)`,
        }
      : undefined;

  return (
    <span
      ref={ref}
      className={cn(badgeVariants({ status, size }), className)}
      style={customStyle}
      data-status={status}
      {...rest}
    >
      <span className="relative inline-flex items-center justify-center @container" aria-hidden="true">
        {animate ? (
          <span
            className="absolute inline-flex h-full w-full rounded-full opacity-75 animate-ping"
            style={dotStyle}
          />
        ) : null}
        <span className="relative inline-flex h-1.5 w-1.5 rounded-full" style={dotStyle} />
      </span>
      <span>{label}</span>
    </span>
  );
});

OStatusBadge.displayName = 'OStatusBadge';
