/**
 * ODataTableCardList - ODataTable 的移动卡片列表形态。
 *
 * 表格在 phone 上无法正常显示 (列太多挤压),改为竖向卡片列表:
 *   ┌──────────────────────┐
 *   │ BTC/USDT       ▲2.4% │   ← primaryField (大字)
 *   │ 67,432.10            │   ← secondaryField (小字)
 *   │ Vol 1.2B   24h 高 .. │   ← extraFields (灰字)
 *   └──────────────────────┘
 *
 * 与 ODataTable 共享:
 *   - data 契约相同
 *   - virtual / flashOnUpdate / channel 全支持
 *   - 按 trackField 变化整张卡片闪一下
 *
 * 移动专有:
 *   - 触摸目标 ≥ 44px (Apple HIG)
 *   - 长按调出快捷菜单 (onRowLongPress)
 *   - 默认 minimal visual density
 */

'use client';

import { forwardRef, useEffect, useRef, useState } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';
import { useFastData } from '../../providers/FastDataProvider';
import { useTouchGesture } from '../../hooks/useTouchGesture';

export interface ODataTableCardListData<T> {
  rows: T[];
  /** 主字段 key (卡片左上,大字)。 */
  primaryField: keyof T & string;
  /** 第二字段 key (主字段下方,中字)。 */
  secondaryField?: keyof T & string;
  /** 右上 chip (例如涨跌幅)。 */
  chipField?: keyof T & string;
  /** chip 的 indicator 字段 (用于决定 chip 颜色:up/down/neutral)。 */
  chipIndicatorField?: keyof T & string;
  /** 底部灰字额外字段 (最多 3 个)。 */
  extraFields?: { key: keyof T & string; label?: string }[];
  /** 唯一 key 字段。 */
  trackKey?: keyof T & string;
}

export interface ODataTableCardListProps<T>
  extends OBlockDataProps<ODataTableCardListData<T>>,
    Pick<
      TerminalBlockProps,
      'virtual' | 'flashOnUpdate' | 'channel' | 'dataDelay' | 'regulation' | 'lowPerformanceMode'
    > {
  onRowClick?: (row: T) => void;
  onRowLongPress?: (row: T) => void;
  /** 虚拟化最大高度。 */
  maxHeight?: number;
  /** 监听变化的字段。 */
  trackField?: keyof T & string;
}

function CardRow<T>({
  row,
  primaryField,
  secondaryField,
  chipField,
  chipIndicatorField,
  extraFields,
  flashBg,
  onClick,
  onLongPress,
}: {
  row: T;
  primaryField: keyof T & string;
  secondaryField?: keyof T & string;
  chipField?: keyof T & string;
  chipIndicatorField?: keyof T & string;
  extraFields?: { key: keyof T & string; label?: string }[];
  flashBg?: string;
  onClick?: () => void;
  onLongPress?: () => void;
}) {
  const gestureRef = useTouchGesture<HTMLDivElement>({
    onLongPress: onLongPress ? () => onLongPress() : undefined,
    haptic: true,
  });

  const r = row as Record<string, unknown>;
  const primary = String(r[primaryField] ?? '');
  const secondary = secondaryField ? String(r[secondaryField] ?? '') : '';
  const chip = chipField ? String(r[chipField] ?? '') : '';
  const indicator = chipIndicatorField
    ? (r[chipIndicatorField] as 'up' | 'down' | 'neutral' | undefined)
    : undefined;

  return (
    <div
      ref={gestureRef as never}
      onClick={onClick}
      role={onClick ? 'button' : undefined}
      tabIndex={onClick ? 0 : undefined}
      onKeyDown={
        onClick
          ? (e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onClick();
              }
            }
          : undefined
      }
      className={cn(
        'px-4 py-3 border-b border-border/50 transition-colors @container',
        onClick && 'cursor-pointer active:bg-muted/40',
        'min-h-[60px]' // 触摸目标 ≥ 44px + 内容空间
      )}
      style={{
        background: flashBg,
      }}
    >
      <div className="flex items-baseline justify-between gap-3">
        <span
          className="font-semibold tabular-nums truncate"
          style={{
            fontSize: 'var(--font-size-title, 15px)',
            fontFamily: 'var(--font-data)',
            color: 'var(--foreground)',
          }}
        >
          {primary}
        </span>
        {chip ? (
          <span
            className="text-sm tabular-nums shrink-0 font-mono"
            style={{
              color:
                indicator === 'up'
                  ? 'var(--quote-up)'
                  : indicator === 'down'
                    ? 'var(--quote-down)'
                    : 'var(--text-muted)',
            }}
          >
            {indicator === 'up' ? '▲ ' : indicator === 'down' ? '▼ ' : ''}
            {chip}
          </span>
        ) : null}
      </div>
      {secondary ? (
        <div
          className="mt-0.5 tabular-nums truncate"
          style={{
            fontSize: 'var(--font-size-data, 13px)',
            color: 'var(--muted-foreground)',
            fontFamily: 'var(--font-data)',
          }}
        >
          {secondary}
        </div>
      ) : null}
      {extraFields && extraFields.length > 0 ? (
        <div
          className="mt-1 flex flex-wrap gap-x-3 gap-y-0.5 text-[color:var(--text-muted)]"
          style={{ fontSize: 'var(--font-size-label, 11px)', fontFamily: 'var(--font-data)' }}
        >
          {extraFields.map((f) => (
            <span key={String(f.key)}>
              {f.label ? `${f.label} ` : ''}
              <span className="text-[color:var(--muted-foreground)] tabular-nums">
                {String(r[f.key] ?? '-')}
              </span>
            </span>
          ))}
        </div>
      ) : null}
    </div>
  );
}

function ODataTableCardListInner<T>(
  {
    data: dataProp,
    loading,
    error,
    empty,
    virtual = true,
    flashOnUpdate,
    channel,
    dataDelay = 0,
    regulation: _r,
    lowPerformanceMode,
    maxHeight = 480,
    trackField,
    onRowClick,
    onRowLongPress,
    className,
    theme: _t,
    size: _s,
  }: ODataTableCardListProps<T>,
  ref: React.Ref<HTMLDivElement>
) {
  const fastData = useFastData();
  const [channelData, setChannelData] = useState<ODataTableCardListData<T> | null>(null);

  useEffect(() => {
    if (!channel || !fastData) return;
    return fastData.subscribe<ODataTableCardListData<T>>(channel, setChannelData);
  }, [channel, fastData]);

  const data = channel ? channelData : (dataProp ?? null);
  const state = resolveBlockState({ data, loading, error, empty });

  // flash 追踪
  const prevValuesRef = useRef<Map<unknown, number>>(new Map());
  const flashedRowsRef = useRef<Map<unknown, { dir: 'up' | 'down'; ts: number }>>(
    new Map()
  );
  const [, force] = useState(0);

  const flashEnabled = !!flashOnUpdate && !lowPerformanceMode;

  useEffect(() => {
    if (!flashEnabled || !data || !trackField) return;
    const next = new Map<unknown, number>();
    const newFlashes = new Map(flashedRowsRef.current);
    const now = Date.now();
    const keyField = (data.trackKey ?? data.primaryField) as keyof T & string;

    for (const row of data.rows) {
      const r = row as Record<string, unknown>;
      const key = r[keyField];
      const value = r[trackField] as number;
      if (typeof value !== 'number') continue;
      next.set(key, value);
      const prev = prevValuesRef.current.get(key);
      if (prev != null && prev !== value) {
        newFlashes.set(key, { dir: value > prev ? 'up' : 'down', ts: now });
      }
    }
    prevValuesRef.current = next;

    for (const [k, f] of newFlashes) {
      if (now - f.ts > 220) newFlashes.delete(k);
    }
    flashedRowsRef.current = newFlashes;
    force((c) => c + 1);

    const timer = setTimeout(() => {
      const t = Date.now();
      for (const [k, f] of flashedRowsRef.current) {
        if (t - f.ts > 220) flashedRowsRef.current.delete(k);
      }
      force((c) => c + 1);
    }, 240);
    return () => clearTimeout(timer);
  }, [data, flashEnabled, trackField]);

  // 虚拟化
  const scrollRef = useRef<HTMLDivElement | null>(null);
  const rows = data?.rows ?? [];
  const virtualizer = useVirtualizer({
    count: virtual ? rows.length : 0,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => 76, // 卡片估算高度
    overscan: 4,
  });

  if (state === 'loading')
    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card p-4',
          className
        )}
      >
        <OLoadingState rows={6} rowHeight="3rem" />
      </div>
    );
  if (state === 'error')
    return <OErrorState ref={ref} error={error!} className={className} variant="inline" />;
  if (state === 'empty' || !data || data.rows.length === 0)
    return (
      <OEmptyState
        ref={ref}
        title="No records"
        description="No data to display."
        className={className}
      />
    );

  const keyField = (data.trackKey ?? data.primaryField) as keyof T & string;

  return (
    <div
      ref={ref}
      className={cn(
        'w-full rounded-md border border-border bg-card overflow-hidden relative',
        className
      )}
    >
      {dataDelay > 0 ? (
        <div className="absolute top-2 right-3 z-10 text-[10px] text-[color:var(--alert-warn)] font-mono pointer-events-none">
          延时 {dataDelay}m
        </div>
      ) : null}

      {virtual ? (
        <div ref={scrollRef} style={{ maxHeight, overflow: 'auto' }}>
          <div
            style={{
              height: virtualizer.getTotalSize(),
              position: 'relative',
              width: '100%',
            }}
          >
            {virtualizer.getVirtualItems().map((vRow) => {
              const row = rows[vRow.index];
              if (!row) return null;
              const r = row as Record<string, unknown>;
              const key = r[keyField as string];
              const flash = flashEnabled ? flashedRowsRef.current.get(key) : null;
              const flashBg = flash
                ? flash.dir === 'up'
                  ? 'var(--quote-up-bg)'
                  : 'var(--quote-down-bg)'
                : undefined;

              return (
                <div
                  key={String(key) || vRow.index}
                  ref={virtualizer.measureElement as never}
                  data-index={vRow.index}
                  style={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '100%',
                    transform: `translateY(${vRow.start}px)`,
                  }}
                >
                  <CardRow
                    row={row}
                    primaryField={data.primaryField}
                    secondaryField={data.secondaryField}
                    chipField={data.chipField}
                    chipIndicatorField={data.chipIndicatorField}
                    extraFields={data.extraFields}
                    flashBg={flashBg}
                    onClick={onRowClick ? () => onRowClick(row) : undefined}
                    onLongPress={onRowLongPress ? () => onRowLongPress(row) : undefined}
                  />
                </div>
              );
            })}
          </div>
        </div>
      ) : (
        <div style={{ maxHeight, overflow: 'auto' }}>
          {rows.map((row, i) => {
            const r = row as Record<string, unknown>;
            const key = r[keyField as string];
            const flash = flashEnabled ? flashedRowsRef.current.get(key) : null;
            const flashBg = flash
              ? flash.dir === 'up'
                ? 'var(--quote-up-bg)'
                : 'var(--quote-down-bg)'
              : undefined;
            return (
              <CardRow
                key={String(key) || i}
                row={row}
                primaryField={data.primaryField}
                secondaryField={data.secondaryField}
                chipField={data.chipField}
                chipIndicatorField={data.chipIndicatorField}
                extraFields={data.extraFields}
                flashBg={flashBg}
                onClick={onRowClick ? () => onRowClick(row) : undefined}
                onLongPress={onRowLongPress ? () => onRowLongPress(row) : undefined}
              />
            );
          })}
        </div>
      )}
    </div>
  );
}

export const ODataTableCardList = forwardRef(ODataTableCardListInner) as <T>(
  props: ODataTableCardListProps<T> & { ref?: React.Ref<HTMLDivElement> }
) => ReturnType<typeof ODataTableCardListInner>;
