/**
 * OAlertList - 告警列表。
 *
 * 数据契约: { alerts: [{ id, severity, title, ..., time }] }
 *
 * variants:
 *   - dense:    紧凑,适合大量告警
 *   - spacious: 宽松,每条信息更多
 *   - grouped:  按 severity 分组
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, useMemo } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import type { OBlockDataProps } from '../../lib/types';
import { OStatusBadge } from '../OStatusBadge';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { OEmptyState } from '../OEmptyState';

export type AlertSeverity = 'critical' | 'warning' | 'info';

export interface OAlertItem {
  id: string;
  severity: AlertSeverity;
  title: string;
  description?: string;
  time: Date | string;
  source?: string;
}

export interface OAlertListData {
  alerts: OAlertItem[];
}

const listVariants = cva('w-full overflow-auto rounded-md border border-border bg-card', {
  variants: {
    variant: {
      dense: '',
      spacious: '',
      grouped: '',
    },
  },
  defaultVariants: { variant: 'spacious' },
});

type ListVariantProps = VariantProps<typeof listVariants>;

export interface OAlertListProps extends OBlockDataProps<OAlertListData>, ListVariantProps {
  onAlertClick?: (alert: OAlertItem) => void;
}

function formatTime(t: Date | string): string {
  const d = t instanceof Date ? t : new Date(t);
  const diff = (Date.now() - d.getTime()) / 1000;
  if (diff < 60) return 'just now';
  if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
  if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
  return d.toLocaleDateString();
}

const SEVERITY_TO_STATUS: Record<AlertSeverity, 'error' | 'warning' | 'info'> = {
  critical: 'error',
  warning: 'warning',
  info: 'info',
};

function AlertRow({
  item,
  variant,
  onClick,
}: {
  item: OAlertItem;
  variant: 'dense' | 'spacious' | 'grouped';
  onClick?: (a: OAlertItem) => void;
}) {
  const compact = variant === 'dense';
  return (
    <li
      className={cn(
        'border-b border-border/40 last:border-0 transition-colors @container',
        compact ? 'px-3 py-2' : 'px-4 py-3',
        onClick && 'cursor-pointer hover:bg-muted/30'
      )}
      onClick={onClick ? () => onClick(item) : undefined}
    >
      <div className={cn('flex items-start gap-3', compact && 'items-center')}>
        <OStatusBadge
          label={item.severity}
          status={SEVERITY_TO_STATUS[item.severity]}
          size={compact ? 'sm' : 'sm'}
          pulse={item.severity === 'critical'}
        />
        <div className="min-w-0 flex-1">
          <div className={cn('font-medium', compact ? 'text-sm' : 'text-base')}>{item.title}</div>
          {!compact && item.description ? (
            <p className="text-sm text-muted-foreground mt-0.5">{item.description}</p>
          ) : null}
          <div className="text-xs text-muted-foreground mt-1 flex items-center gap-2">
            <span>{formatTime(item.time)}</span>
            {item.source ? <span className="opacity-60">· {item.source}</span> : null}
          </div>
        </div>
      </div>
    </li>
  );
}

export const OAlertList = forwardRef<HTMLDivElement, OAlertListProps>(function OAlertList(
  { data, loading, error, empty, variant = 'spacious', onAlertClick, className, theme: _t, size: _s },
  ref
) {
  const state = resolveBlockState({ data, loading, error, empty });

  const grouped = useMemo(() => {
    if (variant !== 'grouped' || !data) return null;
    const out: Record<AlertSeverity, OAlertItem[]> = { critical: [], warning: [], info: [] };
    for (const a of data.alerts) out[a.severity].push(a);
    return out;
  }, [variant, data]);

  if (state === 'loading')
    return (
      <div ref={ref} className={cn(listVariants({ variant }), 'p-4', className)}>
        <OLoadingState rows={4} />
      </div>
    );
  if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
  if (state === 'empty' || !data || data.alerts.length === 0)
    return (
      <OEmptyState
        ref={ref}
        title="No alerts"
        description="All systems are operating normally."
        className={className}
      />
    );

  if (variant === 'grouped' && grouped) {
    return (
      <div ref={ref} className={cn(listVariants({ variant }), className)}>
        {(['critical', 'warning', 'info'] as const).map((sev) =>
          grouped[sev].length > 0 ? (
            <div key={sev}>
              <div className="px-4 py-2 text-xs uppercase tracking-[0.04em] text-muted-foreground bg-muted/30 border-b border-border/40">
                {sev} · {grouped[sev].length}
              </div>
              <ul>
                {grouped[sev].map((item) => (
                  <AlertRow key={item.id} item={item} variant="spacious" onClick={onAlertClick} />
                ))}
              </ul>
            </div>
          ) : null
        )}
      </div>
    );
  }

  return (
    <div ref={ref} className={cn(listVariants({ variant }), className)}>
      <ul>
        {data.alerts.map((item) => (
          <AlertRow key={item.id} item={item} variant={variant ?? 'spacious'} onClick={onAlertClick} />
        ))}
      </ul>
    </div>
  );
});

OAlertList.displayName = 'OAlertList';
