/**
 * OFocusMode (Tide Wave 3 E19, Frame)
 *
 * 全局 focus 模式,隔离非当前决策面板。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §2.4
 */
import { forwardRef, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OFocusModeProps extends Omit<OBlockBaseProps, 'variant'> {
  isActive: boolean;
  focusedElementId: string;
  dimOthers?: boolean;
  blurOthers?: boolean;
  onExit?: () => void;
}

export const OFocusMode = forwardRef<HTMLDivElement, OFocusModeProps>(
  function OFocusMode(
    {
      isActive,
      focusedElementId,
      dimOthers = true,
      blurOthers = false,
      onExit,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    useEffect(() => {
      if (!isActive) return;
      const onKey = (e: globalThis.KeyboardEvent) => {
        if (e.key === 'Escape') onExit?.();
      };
      document.addEventListener('keydown', onKey);
      return () => document.removeEventListener('keydown', onKey);
    }, [isActive, onExit]);

    // 应用全局 style 到 focusedElementId 与其他元素
    useEffect(() => {
      if (!isActive) return;
      const focused = document.getElementById(focusedElementId);
      if (!focused) return;
      // 标记 focused 元素 z-index 高
      const prevZ = focused.style.zIndex;
      const prevPos = focused.style.position;
      focused.style.zIndex = '1001';
      if (!prevPos || prevPos === 'static') focused.style.position = 'relative';
      return () => {
        focused.style.zIndex = prevZ;
        focused.style.position = prevPos;
      };
    }, [isActive, focusedElementId]);

    if (!isActive) return null;

    const overlayStyle: React.CSSProperties = {
      backgroundColor: dimOthers ? 'rgba(0,0,0,0.75)' : 'transparent',
      backdropFilter: blurOthers ? 'blur(8px)' : undefined,
      WebkitBackdropFilter: blurOthers ? 'blur(8px)' : undefined,
    };

    const content = (
      <div
        ref={ref}
        role="presentation"
        aria-label="Focus 模式"
        onClick={onExit}
        className={cn('fixed inset-0 z-[1000] transition-opacity @container', className)}
        style={overlayStyle}
      >
        {/* Esc 提示 */}
        <div
          className="absolute top-4 right-4 px-2 py-1 rounded text-xs"
          style={{
            backgroundColor: 'var(--card)',
            color: 'var(--muted-foreground)',
            border: '1px solid var(--border-strong)',
            fontFamily: 'var(--font-mono)',
          }}
        >
          按 Esc 退出 focus 模式
        </div>
      </div>
    );

    return typeof document !== 'undefined' ? createPortal(content, document.body) : null;
  }
);

OFocusMode.displayName = 'OFocusMode';
