/**
 * OTooltip - 悬浮提示。基于 @radix-ui/react-tooltip。
 *
 * 用法:
 *   <OTooltip content="点击保存">
 *     <button>Save</button>
 *   </OTooltip>
 *
 * 注意:Tooltip.Provider 需要在 App 根部挂一次,内置在本组件,
 * 但如果你已有自己的 Provider,可以避免嵌套(它幂等)。
 */
'use client';

import * as Tooltip from '@radix-ui/react-tooltip';
import { forwardRef, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OTooltipProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  /** 提示内容。 */
  content: ReactNode;
  /** 触发的子元素。 */
  children: ReactNode;
  /** 显示位置。 */
  side?: 'top' | 'right' | 'bottom' | 'left';
  /** 距 trigger 间距。 */
  sideOffset?: number;
  /** 对齐方式。 */
  align?: 'start' | 'center' | 'end';
  /** 延迟显示 (ms)。 */
  delayDuration?: number;
  /** 受控开关 (一般留空让 Radix 自动控制)。 */
  open?: boolean;
  onOpenChange?: (o: boolean) => void;
  /** 强制禁用 tooltip。 */
  disabled?: boolean;
  /** 视觉变体。 */
  variant?: 'default' | 'inverted' | 'rich';
}

const VARIANT_CLASS: Record<NonNullable<OTooltipProps['variant']>, string> = {
  default: 'bg-popover text-popover-foreground border border-border',
  inverted: 'bg-foreground text-background border-transparent',
  rich: 'bg-card text-card-foreground border border-border shadow-lg max-w-xs',
};

export const OTooltip = forwardRef<HTMLDivElement, OTooltipProps>(function OTooltip(
  {
    content,
    children,
    side = 'top',
    sideOffset = 6,
    align = 'center',
    delayDuration = 200,
    open,
    onOpenChange,
    disabled,
    variant = 'default',
    className,
    theme: _t,
  },
  ref
) {
  if (disabled) {
    return <>{children}</>;
  }

  return (
    <Tooltip.Provider delayDuration={delayDuration} disableHoverableContent={false}>
      <Tooltip.Root open={open} onOpenChange={onOpenChange}>
        <Tooltip.Trigger asChild>{children}</Tooltip.Trigger>
        <Tooltip.Portal>
          <Tooltip.Content
            ref={ref}
            side={side}
            sideOffset={sideOffset}
            align={align}
            className={cn(
              'z-50 rounded-md px-2.5 py-1.5 text-xs @container',
              'data-[state=delayed-open]:animate-in data-[state=closed]:animate-out',
              'data-[state=closed]:fade-out-0 data-[state=delayed-open]:fade-in-0',
              'data-[state=closed]:zoom-out-95 data-[state=delayed-open]:zoom-in-95',
              'data-[side=bottom]:slide-in-from-top-2 data-[side=top]:slide-in-from-bottom-2',
              'data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2',
              VARIANT_CLASS[variant],
              className
            )}
          >
            {content}
            <Tooltip.Arrow className={variant === 'inverted' ? 'fill-foreground' : 'fill-border'} />
          </Tooltip.Content>
        </Tooltip.Portal>
      </Tooltip.Root>
    </Tooltip.Provider>
  );
});

OTooltip.displayName = 'OTooltip';
