'use client';
import { forwardRef, type HTMLAttributes, type ElementType, type CSSProperties } from 'react';
import { cn } from '../../lib/cn';
import { cardRecipe, type CardRecipeProps } from '../../recipes';

export interface OCardProps extends HTMLAttributes<HTMLElement>, CardRecipeProps {
  /** 渲染的标签,默认 div。高层组件可传 'article'/'section' 保留语义。 */
  as?: ElementType;
  /** 是否套用默认 padding(--card-padding)。高层组件常自管内边距 → padded=false。默认 true。 */
  padded?: boolean;
  /** 强调态的动态边框色(配合 emphasis=true)。如 epistemic 卡的 emp 状态色。 */
  accentColor?: string;
}

export const OCard = forwardRef<HTMLElement, OCardProps>(
  function OCard(
    { as, elevation, interactive, emphasis, container, padded = true, accentColor, className, style, ...rest },
    ref
  ) {
    const Comp: any = as ?? 'div';
    const mergedStyle: CSSProperties = {
      ...(padded ? { padding: 'var(--card-padding)' } : {}),
      ...(emphasis && accentColor ? { borderColor: accentColor } : {}),
      ...style,
    };
    return (
      <Comp
        ref={ref}
        className={cn(cardRecipe({ elevation, interactive, emphasis, container }), className)}
        style={mergedStyle}
        {...rest}
      />
    );
  }
);
OCard.displayName = 'OCard';

export const OCardHeader = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement>>(
  function OCardHeader({ className, ...rest }, ref) {
    return <div ref={ref} className={cn('flex flex-col gap-1', className)} {...rest} />;
  }
);
OCardHeader.displayName = 'OCardHeader';

export const OCardTitle = forwardRef<HTMLHeadingElement, HTMLAttributes<HTMLHeadingElement>>(
  function OCardTitle({ className, ...rest }, ref) {
    return <h3 ref={ref} className={cn('font-[number:var(--fw-semibold)] text-[length:var(--text-lg)] leading-[var(--lh-snug)]', className)} {...rest} />;
  }
);
OCardTitle.displayName = 'OCardTitle';
