/**
 * OPlanCard (Tide Wave 2 E8, Block)
 *
 * Plan Card 的 UI 展示, Domain 03 核心。
 * 来源:OUI_WAVE_2_REQUIREMENTS_v1.0.md §5
 *
 * 3 variant:
 *   - embedded: 紧凑 6 行(候选列表行内)
 *   - expanded: 完整 12 行+(详情)
 *   - compact: 单行摘要
 */
import { forwardRef, useMemo } from 'react';
import { cn } from '../../lib/cn';
import type { PlanData } from '../../types/tide';
import type { OBlockBaseProps } from '../../lib/types';

export interface OPlanCardProps extends Omit<OBlockBaseProps, 'variant'> {
  plan: PlanData;
  planVariant?: 'embedded' | 'expanded' | 'compact';
  editable?: boolean;
  onExplain?: () => void;
  onCustomize?: () => void;
  onExecute?: () => void;
}

export const OPlanCard = forwardRef<HTMLDivElement, OPlanCardProps>(
  function OPlanCard(
    {
      plan,
      planVariant = 'expanded',
      onExplain,
      onCustomize,
      onExecute,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const inRange = useMemo(
      () =>
        plan.currentPrice >= plan.entryRange.low &&
        plan.currentPrice <= plan.entryRange.high,
      [plan.currentPrice, plan.entryRange]
    );

    // compact: 单行摘要
    if (planVariant === 'compact') {
      return (
        <div
          ref={ref}
          className={cn(
            'inline-flex items-center gap-2 px-2 py-1 rounded text-xs @container',
            'bg-[color:var(--card)] border border-[color:var(--blue-accent)]/40',
            className
          )}
          style={{ fontFamily: 'var(--font-mono)' }}
          role="group"
          aria-label="Plan 摘要"
        >
          <span style={{ color: 'var(--red-up)' }}>
            +{plan.takeProfitPct.toFixed(0)}%
          </span>
          <span style={{ color: 'var(--text-tertiary)' }}>/</span>
          <span style={{ color: 'var(--green-down)' }}>
            -{Math.abs(plan.stopLossPct).toFixed(1)}%
          </span>
          <span style={{ color: 'var(--text-tertiary)' }}>/</span>
          <span style={{ color: 'var(--muted-foreground)' }}>
            {plan.holdPeriodDays.min}-{plan.holdPeriodDays.max}d
          </span>
          <span style={{ color: 'var(--text-tertiary)' }}>/</span>
          <span style={{ color: 'var(--muted-foreground)' }}>
            {(plan.positionPctRange.min * 100).toFixed(0)}-{(plan.positionPctRange.max * 100).toFixed(0)}%
          </span>
        </div>
      );
    }

    const isEmbedded = planVariant === 'embedded';

    return (
      <article
        ref={ref}
        className={cn(
          'flex flex-col gap-1.5 rounded',
          'bg-[color:var(--card)]',
          'border border-[color:var(--blue-accent)]/60',
          isEmbedded ? 'px-2 py-1.5' : 'px-3 py-2',
          className
        )}
        style={{ fontFamily: 'var(--font-mono)' }}
        aria-label="Plan 卡片"
      >
        {/* badge */}
        <header
          className={cn(
            'flex items-center justify-between',
            'pb-1 border-b border-[color:var(--border-subtle)]'
          )}
        >
          <span
            className="text-[10px] uppercase tracking-[0.04em] flex items-center gap-1"
            style={{
              color: plan.isCustom ? 'var(--yellow)' : 'var(--blue-accent)',
            }}
          >
            {plan.isCustom ? '✏ Wiki 自定义' : `📊 LLM + ${plan.regimeContext}`}
          </span>
        </header>

        {/* entry */}
        <div
          className="text-xs flex items-center justify-between"
          style={{ color: 'var(--foreground)' }}
        >
          <span style={{ color: 'var(--muted-foreground)' }}>入场区间</span>
          <span>
            {plan.entryRange.low.toFixed(2)} - {plan.entryRange.high.toFixed(2)}{' '}
            <span style={{ color: inRange ? 'var(--green-down)' : 'var(--red-up)' }}>
              {inRange ? '✓ in' : '✗ out'}
            </span>
          </span>
        </div>

        {/* current price */}
        <div
          className="text-xs flex items-center justify-between"
          style={{ color: 'var(--foreground)' }}
        >
          <span style={{ color: 'var(--muted-foreground)' }}>当前价</span>
          <span style={{ fontWeight: 600 }}>{plan.currentPrice.toFixed(2)}</span>
        </div>

        {/* take profit */}
        <div
          className="text-xs flex items-center justify-between"
          style={{ color: 'var(--foreground)' }}
        >
          <span style={{ color: 'var(--muted-foreground)' }}>止盈</span>
          <span style={{ color: 'var(--red-up)' }}>
            {plan.takeProfit.toFixed(2)} (+{plan.takeProfitPct.toFixed(1)}%)
          </span>
        </div>

        {/* stop loss */}
        <div
          className="text-xs flex items-center justify-between"
          style={{ color: 'var(--foreground)' }}
        >
          <span style={{ color: 'var(--muted-foreground)' }}>止损</span>
          <span style={{ color: 'var(--green-down)' }}>
            {plan.stopLoss.toFixed(2)} ({plan.stopLossPct.toFixed(1)}%)
          </span>
        </div>

        {/* RR */}
        {!isEmbedded && (
          <div
            className="text-xs flex items-center justify-between"
            style={{ color: 'var(--foreground)' }}
          >
            <span style={{ color: 'var(--muted-foreground)' }}>盈亏比</span>
            <span style={{ fontWeight: 600 }}>{plan.riskRewardRatio.toFixed(2)}</span>
          </div>
        )}

        {/* hold */}
        <div
          className="text-xs flex items-center justify-between"
          style={{ color: 'var(--foreground)' }}
        >
          <span style={{ color: 'var(--muted-foreground)' }}>持仓周期</span>
          <span>
            {plan.holdPeriodDays.min}-{plan.holdPeriodDays.max} 天
          </span>
        </div>

        {/* position */}
        <div
          className="text-xs flex items-center justify-between"
          style={{ color: 'var(--foreground)' }}
        >
          <span style={{ color: 'var(--muted-foreground)' }}>仓位</span>
          <span>
            {(plan.positionPctRange.min * 100).toFixed(0)}-
            {(plan.positionPctRange.max * 100).toFixed(0)}%
          </span>
        </div>

        {/* exit triggers (expanded only) */}
        {!isEmbedded && plan.exitTriggers.length > 0 && (
          <div
            className="text-[10px] mt-1 pt-1 border-t border-[color:var(--border-subtle)]"
            style={{ color: 'var(--muted-foreground)' }}
          >
            <div className="uppercase tracking-[0.04em] mb-0.5">退出触发</div>
            <ul className="list-none p-0 m-0 flex flex-col gap-0.5">
              {plan.exitTriggers.map((t, i) => (
                <li key={i} className="flex items-start gap-1">
                  <span aria-hidden="true">•</span>
                  <span style={{ color: 'var(--foreground)' }}>{t}</span>
                </li>
              ))}
            </ul>
          </div>
        )}

        {/* warnings */}
        {!isEmbedded && plan.warnings.length > 0 && (
          <div
            className="text-[10px] mt-1 px-2 py-1 rounded"
            style={{
              backgroundColor: 'color-mix(in srgb, var(--yellow) 15%, transparent)',
              color: 'var(--yellow)',
            }}
            role="alert"
          >
            {plan.warnings.map((w, i) => (
              <div key={i}>⚠ {w}</div>
            ))}
          </div>
        )}

        {/* actions (expanded only) */}
        {!isEmbedded && (onExplain || onCustomize || onExecute) && (
          <div className="flex gap-1.5 mt-1 pt-1 border-t border-[color:var(--border-subtle)]">
            {onExplain && (
              <button
                type="button"
                onClick={onExplain}
                className={cn(
                  'flex-1 px-2 py-1 text-xs rounded',
                  'bg-[color:var(--muted)] text-[color:var(--foreground)]',
                  'hover:bg-[color:var(--accent)] transition-colors'
                )}
              >
                📋 解释
              </button>
            )}
            {onCustomize && (
              <button
                type="button"
                onClick={onCustomize}
                className={cn(
                  'flex-1 px-2 py-1 text-xs rounded',
                  'bg-[color:var(--muted)] text-[color:var(--foreground)]',
                  'hover:bg-[color:var(--accent)] transition-colors'
                )}
              >
                ✏ 自定义
              </button>
            )}
            {onExecute && (
              <button
                type="button"
                onClick={onExecute}
                className={cn(
                  'flex-1 px-2 py-1 text-xs rounded font-bold',
                  'bg-[color:var(--blue-accent)] text-white',
                  'hover:opacity-90 transition-opacity'
                )}
              >
                ⚡ 下单
              </button>
            )}
          </div>
        )}
      </article>
    );
  }
);

OPlanCard.displayName = 'OPlanCard';
