/**
 * OLeverageSlider - 杠杆调节滑块 (1-125x)。
 *
 * 合约工具 Block。可独立使用,也可嵌入 OTradePanel。
 *
 * 功能:
 *   - 1x ~ maxLeverage 滑动
 *   - 5 个 step 标记 (1x / 5x / 10x / 25x / 125x 之类)
 *   - 实时显示该杠杆下的最大可开仓位
 *   - 风险等级颜色 (低/中/高/极高)
 *   - reduce-motion 友好
 *
 * 用法:
 *   <OLeverageSlider
 *     value={10}
 *     maxLeverage={125}
 *     availableBalance={1000}
 *     onChange={(v) => setLev(v)}
 *   />
 */

'use client';

import { forwardRef, useMemo } from 'react';
import { cn } from '../../lib/cn';

export interface OLeverageSliderProps {
  /** 当前杠杆 (受控). */
  value: number;
  /** 品种最大杠杆 (例如 BTC 125x). */
  maxLeverage?: number;
  /** 用户可用余额 USDT (用于显示最大可开). */
  availableBalance?: number;
  /** 步进 (默认 1). */
  step?: number;
  /** 自定义 step 标记位置. */
  marks?: number[];
  /** 改变时回调. */
  onChange?: (leverage: number) => void;
  /** 用户拖完手放开 (适合发到后端). */
  onCommit?: (leverage: number) => void;
  disabled?: boolean;
  className?: string;
  /** 紧凑模式 (不显示风险提示). */
  compact?: boolean;
}

function riskColor(lev: number, max: number): string {
  const ratio = lev / max;
  if (ratio < 0.1) return 'var(--quote-up)';        // 低风险
  if (ratio < 0.3) return 'var(--alert-info)';       // 中
  if (ratio < 0.6) return 'var(--alert-warn)';       // 高
  return 'var(--quote-down)';                         // 极高
}

function riskLabel(lev: number, max: number): string {
  const ratio = lev / max;
  if (ratio < 0.1) return '低风险';
  if (ratio < 0.3) return '中等风险';
  if (ratio < 0.6) return '高风险';
  return '极高风险';
}

export const OLeverageSlider = forwardRef<HTMLDivElement, OLeverageSliderProps>(
  function OLeverageSlider(
    {
      value,
      maxLeverage = 125,
      availableBalance,
      step = 1,
      marks,
      onChange,
      onCommit,
      disabled = false,
      compact = false,
      className,
    },
    ref
  ) {
    // 默认 marks: 1, 5, 10, 25, 50, 100, max
    const computedMarks = useMemo(() => {
      if (marks) return marks;
      return [1, 5, 10, 25, 50, 100, maxLeverage].filter(
        (m, i, arr) => m <= maxLeverage && arr.indexOf(m) === i
      );
    }, [marks, maxLeverage]);

    const color = riskColor(value, maxLeverage);
    const label = riskLabel(value, maxLeverage);
    const maxNotional = (availableBalance ?? 0) * value;

    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card p-3 @container',
          disabled && 'opacity-60',
          className
        )}
        style={{ fontFamily: 'var(--font-ui)' }}
      >
        {/* 头部: 当前值 + 风险 */}
        <div className="flex items-baseline justify-between mb-2">
          <div className="flex items-baseline gap-2">
            <span className="text-[10px] text-[color:var(--text-muted)] uppercase tracking-[0.04em]">
              杠杆
            </span>
            <span
              className="text-2xl font-extrabold tracking-[-0.03em] tabular-nums"
              style={{ color, fontFamily: 'var(--font-data)' }}
            >
              {value}x
            </span>
          </div>
          {!compact ? (
            <span className="text-[10px] font-mono" style={{ color }}>
              {label}
            </span>
          ) : null}
        </div>

        {/* Slider */}
        <input
          type="range"
          min={1}
          max={maxLeverage}
          step={step}
          value={value}
          disabled={disabled}
          onChange={(e) => onChange?.(parseInt(e.target.value, 10))}
          onMouseUp={(e) => onCommit?.(parseInt((e.target as HTMLInputElement).value, 10))}
          onTouchEnd={(e) => onCommit?.(parseInt((e.target as HTMLInputElement).value, 10))}
          className="w-full h-1.5 appearance-none cursor-pointer rounded-full"
          style={{
            // gradient track 反映风险等级
            background: `linear-gradient(to right,
              var(--quote-up) 0%,
              var(--quote-up) ${(maxLeverage * 0.1) / maxLeverage * 100}%,
              var(--alert-info) ${(maxLeverage * 0.1) / maxLeverage * 100}%,
              var(--alert-info) ${(maxLeverage * 0.3) / maxLeverage * 100}%,
              var(--alert-warn) ${(maxLeverage * 0.3) / maxLeverage * 100}%,
              var(--alert-warn) ${(maxLeverage * 0.6) / maxLeverage * 100}%,
              var(--quote-down) ${(maxLeverage * 0.6) / maxLeverage * 100}%,
              var(--quote-down) 100%)`,
          }}
          aria-valuemin={1}
          aria-valuemax={maxLeverage}
          aria-valuenow={value}
        />

        {/* Step marks (点击直接跳到) */}
        <div className="flex justify-between mt-2">
          {computedMarks.map((m) => (
            <button
              key={m}
              type="button"
              onClick={() => {
                if (!disabled) {
                  onChange?.(m);
                  onCommit?.(m);
                }
              }}
              disabled={disabled}
              className={cn(
                'text-[10px] tabular-nums font-mono cursor-pointer',
                'hover:text-[color:var(--foreground)]',
                value === m
                  ? 'text-[color:var(--foreground)] font-bold'
                  : 'text-[color:var(--text-muted)]'
              )}
            >
              {m}x
            </button>
          ))}
        </div>

        {/* 最大可开 (非 compact) */}
        {!compact && typeof availableBalance === 'number' ? (
          <div className="mt-3 pt-2 border-t border-border/50 grid grid-cols-2 gap-2 text-[10px]">
            <div>
              <div className="text-[color:var(--text-muted)]">最大开仓</div>
              <div className="tabular-nums font-mono text-[color:var(--foreground)]">
                {maxNotional.toFixed(2)} USDT
              </div>
            </div>
            <div>
              <div className="text-[color:var(--text-muted)]">维持保证金率</div>
              <div className="tabular-nums font-mono text-[color:var(--foreground)]">
                {(0.5 / value).toFixed(3)}%
              </div>
            </div>
          </div>
        ) : null}
      </div>
    );
  }
);

OLeverageSlider.displayName = 'OLeverageSlider';
