/**
 * OTOCNav - 文档目录侧栏 (Table of Contents)。
 *
 * 自动跟踪页面滚动,高亮当前可视区域的标题。
 * 用 IntersectionObserver 监听标题位置,无需复杂 scroll math。
 *
 * 数据契约: items 由 Page 传入(可从 markdown AST 提取或手动列出)。
 * 受控:onItemClick 可由 Page 处理 (e.g. 平滑滚动 + 更新 URL hash)。
 */
'use client';

import { forwardRef, useEffect, useRef, useState } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export interface OTOCItem {
  id: string;
  label: string;
  /** 层级 (1-6 对应 h1-h6)。 */
  level: number;
}

export interface OTOCNavProps extends Omit<OBlockBaseProps, 'variant' | 'size'> {
  items: OTOCItem[];
  /** 标题。 */
  heading?: string;
  /** 容器 ref / scroll root,默认 window/documentElement。 */
  rootMargin?: string;
  /** 选中项回调 (可用于平滑滚动 / 路由)。默认 hash 滚动。 */
  onItemClick?: (id: string) => void;
  /** 最大层级 (e.g. 3 = 只显示 h1-h3)。 */
  maxLevel?: number;
}

export const OTOCNav = forwardRef<HTMLElement, OTOCNavProps>(function OTOCNav(
  { items, heading = 'On this page', rootMargin = '-40% 0px -50% 0px', onItemClick, maxLevel = 4, className, theme: _t },
  ref
) {
  const [activeId, setActiveId] = useState<string | null>(null);
  const ratioMap = useRef(new Map<string, number>());

  useEffect(() => {
    if (typeof document === 'undefined') return;
    const targets: HTMLElement[] = [];
    for (const it of items) {
      const el = document.getElementById(it.id);
      if (el) targets.push(el);
    }
    if (targets.length === 0) return;

    const observer = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          ratioMap.current.set(e.target.id, e.intersectionRatio);
        }
        // 选取当前可见比例最高的
        let best: { id: string; ratio: number } | null = null;
        for (const [id, ratio] of ratioMap.current.entries()) {
          if (!best || ratio > best.ratio) best = { id, ratio };
        }
        if (best && best.ratio > 0) setActiveId(best.id);
      },
      { rootMargin, threshold: [0, 0.25, 0.5, 0.75, 1] }
    );
    for (const t of targets) observer.observe(t);
    return () => observer.disconnect();
  }, [items, rootMargin]);

  const filtered = items.filter((it) => it.level <= maxLevel);

  function handleClick(e: React.MouseEvent, id: string) {
    if (onItemClick) {
      e.preventDefault();
      onItemClick(id);
    }
    setActiveId(id);
  }

  return (
    <nav ref={ref} aria-label={heading} className={cn('w-full text-sm', className)}>
      {heading ? (
        <div className="text-xs uppercase tracking-[0.04em] text-muted-foreground font-medium mb-3">
          {heading}
        </div>
      ) : null}
      <ul className="space-y-1 border-l border-border">
        {filtered.map((it) => {
          const active = it.id === activeId;
          return (
            <li key={it.id}>
              <a
                href={`#${it.id}`}
                onClick={(e) => handleClick(e, it.id)}
                aria-current={active ? 'true' : undefined}
                className={cn(
                  'block py-1 transition-colors border-l-2 -ml-px @container',
                  'hover:text-foreground hover:border-muted-foreground/50',
                  active
                    ? 'text-primary border-primary font-medium'
                    : 'text-muted-foreground border-transparent'
                )}
                style={{ paddingLeft: `${0.75 + (it.level - 1) * 0.75}rem` }}
              >
                {it.label}
              </a>
            </li>
          );
        })}
      </ul>
    </nav>
  );
});

OTOCNav.displayName = 'OTOCNav';
