/**
 * OAIQAPanel — reading_companion agent 问答面板
 *
 * 消费 API v1.0 §4.2.4:
 *   reading_companion(question) → { answer: string, sources_used: number } + citations[]
 *
 * v1.0 限制:
 *   - 全非流式 → 用 loading spinner + Promise.then
 *   - 不假设 SSE,future-proof:用 onAsk callback,消费方可接入流式
 *
 * 设计:
 *   - 问题输入框 + 提交
 *   - 回答区(answer + 强制 citations chip)
 *   - 历史 turn(最近 5 个 Q/A)
 *   - 加载状态 / 错误状态
 */
import {
  forwardRef,
  useCallback,
  useState,
  type ChangeEvent,
  type KeyboardEvent,
} from 'react';
import { cn } from '../../lib/cn';
import { OCitationCard } from '../OCitationCard';
import type { Citation, AgentCitation } from '../../types/stratum';
import type { OBlockBaseProps } from '../../lib/types';

export interface QAResponse {
  /** Agent 回答正文。 */
  answer: string;
  /** 引用列表(可空,但 reading_companion 一般会有)。 */
  citations: Array<Citation | AgentCitation>;
  /** 元数据(API §4.2.4 output)。 */
  sources_used?: number;
}

export interface QATurn {
  question: string;
  response: QAResponse;
  timestamp: string;
}

export interface OAIQAPanelProps extends Omit<OBlockBaseProps, 'variant'> {
  /** 问答 callback(消费方实施 reading_companion agent 调用)。 */
  onAsk: (question: string) => Promise<QAResponse>;
  /** 历史 turn(可选,受控/非受控两用,受控时不维护内部 state)。 */
  history?: QATurn[];
  /** 新 turn 完成 callback。 */
  onTurnComplete?: (turn: QATurn) => void;
  /** placeholder。 */
  placeholder?: string;
  /** 历史保留 turn 数(默认 5)。 */
  maxHistory?: number;
}

export const OAIQAPanel = forwardRef<HTMLDivElement, OAIQAPanelProps>(
  function OAIQAPanel(
    {
      onAsk,
      history: controlledHistory,
      onTurnComplete,
      placeholder = '问点什么...',
      maxHistory = 5,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const [question, setQuestion] = useState('');
    const [localHistory, setLocalHistory] = useState<QATurn[]>([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const history = controlledHistory ?? localHistory;
    const isControlled = controlledHistory !== undefined;

    const handleAsk = useCallback(async () => {
      const q = question.trim();
      if (!q) return;
      setLoading(true);
      setError(null);
      try {
        const r = await onAsk(q);
        const turn: QATurn = {
          question: q,
          response: r,
          timestamp: new Date().toISOString(),
        };
        if (!isControlled) {
          setLocalHistory((prev) => [...prev, turn].slice(-maxHistory));
        }
        onTurnComplete?.(turn);
        setQuestion('');
      } catch (e) {
        setError(e instanceof Error ? e.message : '问答失败');
      } finally {
        setLoading(false);
      }
    }, [question, onAsk, isControlled, maxHistory, onTurnComplete]);

    const handleKeyDown = useCallback(
      (e: KeyboardEvent<HTMLTextAreaElement>) => {
        if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
          e.preventDefault();
          void handleAsk();
        }
      },
      [handleAsk]
    );

    return (
      <div ref={ref} className={cn('flex flex-col gap-3 w-full', className)}>
        {history.length > 0 && (
          <div
            className="flex flex-col gap-3 max-h-[400px] overflow-y-auto"
            aria-label={`问答历史 ${history.length} 条`}
          >
            {history.map((turn, i) => (
              <div key={`${turn.timestamp}-${i}`} className="flex flex-col gap-2">
                <div
                  className={cn(
                    'px-3 py-2 rounded-md text-sm @container',
                    'bg-primary/10 text-[color:var(--foreground)]',
                    'border border-primary/20'
                  )}
                >
                  <div className="text-[10px] uppercase tracking-[0.04em] text-[color:var(--text-muted)] mb-1 font-mono">
                    你
                  </div>
                  {turn.question}
                </div>
                <div
                  className={cn(
                    'px-3 py-2 rounded-md text-sm',
                    'bg-card text-[color:var(--foreground)]',
                    'border border-border'
                  )}
                >
                  <div className="flex items-center gap-2 mb-1">
                    <span aria-hidden="true">🤖</span>
                    <span className="text-[10px] uppercase tracking-[0.04em] text-[color:var(--text-muted)] font-mono">
                      reading_companion
                    </span>
                    {turn.response.sources_used !== undefined && (
                      <span className="text-[10px] text-[color:var(--text-muted)] font-mono">
                        {turn.response.sources_used} 个来源
                      </span>
                    )}
                  </div>
                  <div className="whitespace-pre-wrap leading-relaxed">
                    {turn.response.answer}
                  </div>
                  {turn.response.citations.length > 0 && (
                    <div className="flex flex-wrap gap-1.5 mt-2 pt-2 border-t border-border">
                      {turn.response.citations.map((c, ci) => (
                        <OCitationCard
                          key={`${c.substrate_id}-${c.fragment_id ?? ci}`}
                          citation={c}
                          compact
                        />
                      ))}
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}

        {error && (
          <div
            role="alert"
            className={cn(
              'px-3 py-2 rounded-md text-sm',
              'bg-destructive/10 text-destructive',
              'border border-destructive/30'
            )}
          >
            {error}
          </div>
        )}

        <div className="flex flex-col gap-2">
          <textarea
            value={question}
            onChange={(e: ChangeEvent<HTMLTextAreaElement>) => setQuestion(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            disabled={loading}
            aria-label="问题输入"
            rows={2}
            className={cn(
              'w-full px-3 py-2 rounded-md text-sm resize-y',
              'bg-card border border-border',
              'text-[color:var(--foreground)] placeholder:text-[color:var(--text-muted)]',
              'focus:outline-none focus-visible:ring-2 focus-visible:ring-ring',
              'disabled:opacity-50'
            )}
          />
          <div className="flex items-center justify-between">
            <span className="text-[10px] text-[color:var(--text-muted)] font-mono">
              ⌘/Ctrl + Enter 发送
            </span>
            <button
              type="button"
              onClick={() => void handleAsk()}
              disabled={loading || !question.trim()}
              className={cn(
                'px-4 py-1.5 rounded-md text-sm font-medium',
                'bg-primary text-primary-foreground',
                'hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed',
                'transition-opacity'
              )}
            >
              {loading ? '思考中...' : '问'}
            </button>
          </div>
        </div>
      </div>
    );
  }
);

OAIQAPanel.displayName = 'OAIQAPanel';
