/**
 * OMacroQuadrantReport (Tide Wave 3 E27, Block)
 *
 * 2x2 宏观象限报告(增长 × 通胀)。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §4.4
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export type Quadrant = 'Q1' | 'Q2' | 'Q3' | 'Q4';

export interface QuadrantInfo {
  name: string;
  label: string;
  description: string;
  favoredSectors: string[];
  avoidSectors: string[];
}

export interface OMacroQuadrantReportProps extends Omit<OBlockBaseProps, 'variant'> {
  currentQuadrant: Quadrant;
  /** 增长趋势 -1 to 1 */
  growthTrend: number;
  /** 通胀趋势 -1 to 1 */
  inflationTrend: number;
  quadrantInfo: Record<Quadrant, QuadrantInfo>;
  /** 历史轨迹点 [{q, t}] */
  trajectory?: { quadrant: Quadrant; date: string }[];
  onQuadrantClick?: (q: Quadrant) => void;
}

const QUADRANT_COLOR: Record<Quadrant, string> = {
  Q1: 'var(--yellow)',      // overheating
  Q2: 'var(--red-up)',      // goldilocks
  Q3: 'var(--green-down)',  // recession
  Q4: 'var(--red-up)',      // stagflation - 危险
};

export const OMacroQuadrantReport = forwardRef<HTMLDivElement, OMacroQuadrantReportProps>(
  function OMacroQuadrantReport(
    {
      currentQuadrant,
      growthTrend,
      inflationTrend,
      quadrantInfo,
      onQuadrantClick,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const current = quadrantInfo[currentQuadrant];
    return (
      <div
        ref={ref}
        className={cn(
          'flex flex-col gap-3 px-3 py-2 rounded @container',
          'bg-[color:var(--card)] border border-[color:var(--border-strong)]',
          className
        )}
        style={{ fontFamily: 'var(--font-sans)' }}
        role="region"
        aria-label="宏观象限"
      >
        {/* header */}
        <div>
          <div
            className="text-[10px] uppercase tracking-[0.04em]"
            style={{ color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)' }}
          >
            宏观象限
          </div>
          <div className="flex items-baseline gap-2">
            <span
              className="text-lg font-bold"
              style={{ color: QUADRANT_COLOR[currentQuadrant] }}
            >
              {currentQuadrant}
            </span>
            <span style={{ color: 'var(--foreground)' }}>{current?.label}</span>
          </div>
        </div>

        {/* 2x2 quadrant grid */}
        <div className="relative">
          <div
            className="grid gap-1"
            style={{ gridTemplateColumns: '1fr 1fr', gridTemplateRows: '80px 80px' }}
          >
            {(['Q2', 'Q1', 'Q3', 'Q4'] as Quadrant[]).map((q) => {
              const isActive = q === currentQuadrant;
              const info = quadrantInfo[q];
              return (
                <button
                  key={q}
                  type="button"
                  onClick={() => onQuadrantClick?.(q)}
                  disabled={!onQuadrantClick}
                  className={cn(
                    'rounded text-xs flex flex-col items-center justify-center p-2 transition-opacity',
                    isActive ? 'ring-2 ring-[color:var(--blue-accent)]' : 'opacity-70 hover:opacity-100'
                  )}
                  style={{
                    backgroundColor: isActive
                      ? `color-mix(in srgb, ${QUADRANT_COLOR[q]} 25%, var(--card))`
                      : 'var(--muted)',
                    color: 'var(--foreground)',
                    border: 'none',
                  }}
                  aria-label={`${q}: ${info?.label}`}
                >
                  <span className="font-bold" style={{ color: QUADRANT_COLOR[q] }}>
                    {q}
                  </span>
                  <span className="text-[10px] text-center">{info?.label}</span>
                </button>
              );
            })}
          </div>
          {/* axes labels */}
          <div
            className="absolute -bottom-5 left-1/2 text-[10px]"
            style={{ color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)' }}
          >
            通胀 →
          </div>
          <div
            className="absolute -left-7 top-1/2 text-[10px] -rotate-90"
            style={{ color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)' }}
          >
            增长 →
          </div>
        </div>

        {/* trends */}
        <div className="grid grid-cols-2 gap-2 mt-3 text-[10px]" style={{ color: 'var(--muted-foreground)', fontFamily: 'var(--font-mono)' }}>
          <div>增长趋势: {growthTrend > 0 ? '↑' : growthTrend < 0 ? '↓' : '→'} {growthTrend.toFixed(2)}</div>
          <div>通胀趋势: {inflationTrend > 0 ? '↑' : inflationTrend < 0 ? '↓' : '→'} {inflationTrend.toFixed(2)}</div>
        </div>

        {/* current quadrant detail */}
        {current && (
          <div className="flex flex-col gap-1.5 pt-2 border-t border-[color:var(--border-subtle)]">
            <p className="text-xs" style={{ color: 'var(--foreground)' }}>
              {current.description}
            </p>
            <div className="grid grid-cols-2 gap-2 text-[10px]">
              <div>
                <div style={{ color: 'var(--text-tertiary)' }}>偏好板块</div>
                <div style={{ color: 'var(--red-up)' }}>{current.favoredSectors.join(' / ')}</div>
              </div>
              <div>
                <div style={{ color: 'var(--text-tertiary)' }}>规避板块</div>
                <div style={{ color: 'var(--green-down)' }}>{current.avoidSectors.join(' / ')}</div>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }
);

OMacroQuadrantReport.displayName = 'OMacroQuadrantReport';
