/**
 * OCandleRotateHint - K 线图竖屏时提示旋转横屏。
 *
 * 加密散户在手机上看 K 线,竖屏 K 线信息密度太低。
 * 这个组件在 phone 竖屏时显示一个轻提示,横屏后自动隐藏。
 *
 * 使用方式:
 *   <ResponsiveBlock
 *     mobile={
 *       <>
 *         <OCandleRotateHint />
 *         <OCandlestickChart data={...} height={300} />
 *       </>
 *     }
 *     desktop={<OCandlestickChart data={...} height={500} />}
 *   />
 *
 * 也可作为 wrapper:
 *   <OCandleRotateHint>
 *     <OCandlestickChart ... />
 *   </OCandleRotateHint>
 *
 * 用户体验:
 *   - 不阻塞 (仍可在竖屏查看)
 *   - 一次性 (用户旋转过一次后,本会话不再提示)
 *   - 可手动关闭 (右上 x)
 */

'use client';

import { useEffect, useState, type ReactNode } from 'react';
import { useViewport } from '../../hooks/useViewportClass';
import { cn } from '../../lib/cn';

const STORAGE_KEY = 'helios-rotate-hint-dismissed';

export interface OCandleRotateHintProps {
  /** 子内容 (可选,作为 wrapper 时传入)。 */
  children?: ReactNode;
  /** 自定义提示文字。 */
  message?: string;
  /** 强制隐藏 (例如用户在设置里关闭了所有提示)。 */
  disabled?: boolean;
  /** className 透传到 wrapper。 */
  className?: string;
}

export function OCandleRotateHint({
  children,
  message = '横屏可获得更佳 K 线体验',
  disabled = false,
  className,
}: OCandleRotateHintProps) {
  const { class: vp, landscape, touch } = useViewport();
  const [dismissed, setDismissed] = useState(true); // SSR 兜底先隐藏

  useEffect(() => {
    if (typeof sessionStorage === 'undefined') return;
    setDismissed(sessionStorage.getItem(STORAGE_KEY) === '1');
  }, []);

  // 横屏 / 已关闭 / 非手机 / 禁用 / 非触摸设备 都不显示
  const shouldShow = !disabled && vp === 'phone' && !landscape && touch && !dismissed;

  function dismiss() {
    setDismissed(true);
    try {
      sessionStorage.setItem(STORAGE_KEY, '1');
    } catch {
      /* ignore */
    }
  }

  // 旋转到横屏时自动隐藏 (但不写入 storage,因为可能转回来)
  useEffect(() => {
    if (landscape && !dismissed) {
      setDismissed(true);
    }
  }, [landscape, dismissed]);

  const hint = shouldShow ? (
    <div
      role="status"
      className="px-3 py-2 mb-2 flex items-center justify-between gap-2 rounded-md border border-border bg-muted/40 @container"
    >
      <span className="flex items-center gap-2 text-[color:var(--muted-foreground)]" style={{ fontSize: 'var(--font-size-data)' }}>
        <RotateIcon />
        {message}
      </span>
      <button
        type="button"
        onClick={dismiss}
        className="w-6 h-6 inline-flex items-center justify-center rounded text-[color:var(--text-muted)] hover:bg-muted"
        aria-label="Dismiss"
      >
        <svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true">
          <path
            d="M2 2L10 10M10 2L2 10"
            stroke="currentColor"
            strokeWidth="1.4"
            strokeLinecap="round"
          />
        </svg>
      </button>
    </div>
  ) : null;

  if (!children) return hint;

  return (
    <div className={cn(className)}>
      {hint}
      {children}
    </div>
  );
}

function RotateIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
      <rect
        x="3"
        y="2"
        width="6"
        height="10"
        rx="1"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.2"
      />
      <path
        d="M11 8H14M14 8L12 6M14 8L12 10"
        stroke="currentColor"
        strokeWidth="1.2"
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

OCandleRotateHint.displayName = 'OCandleRotateHint';
