/**
 * OTrainingTaskList (Tide Wave 3 E22, Block)
 *
 * 训练任务列表 P0/P1/P2 + completed status。
 * 来源:OUI_WAVE_3_REQUIREMENTS_v1.0.md §3.3
 */
import { forwardRef } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

export type TaskPriority = 'P0' | 'P1' | 'P2';
export type TaskStatus = 'pending' | 'in_progress' | 'completed';

export interface TrainingTask {
  id: string;
  priority: TaskPriority;
  title: string;
  description?: string;
  category: string;
  status: TaskStatus;
  createdAt: string | Date;
  dueDate?: string | Date;
}

export interface OTrainingTaskListProps extends Omit<OBlockBaseProps, 'variant'> {
  tasks: TrainingTask[];
  showCompleted?: boolean;
  onTaskClick?: (task: TrainingTask) => void;
  onComplete?: (taskId: string) => void;
  emptyMessage?: string;
}

const PRIO_COLORS: Record<TaskPriority, string> = {
  P0: 'var(--red-up)',
  P1: 'var(--yellow)',
  P2: 'var(--text-tertiary)',
};

export const OTrainingTaskList = forwardRef<HTMLDivElement, OTrainingTaskListProps>(
  function OTrainingTaskList(
    {
      tasks,
      showCompleted = true,
      onTaskClick,
      onComplete,
      emptyMessage = '暂无训练任务',
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const filtered = showCompleted ? tasks : tasks.filter((t) => t.status !== 'completed');

    if (filtered.length === 0) {
      return (
        <div
          ref={ref}
          className={cn('text-center py-6 text-sm border border-dashed rounded', className)}
          style={{ color: 'var(--text-tertiary)', borderColor: 'var(--border-strong)' }}
        >
          {emptyMessage}
        </div>
      );
    }

    return (
      <ul
        ref={ref as React.Ref<HTMLUListElement>}
        className={cn('flex flex-col gap-1 list-none p-0 m-0', className)}
        style={{ fontFamily: 'var(--font-sans)' }}
        aria-label={`训练任务 ${filtered.length} 项`}
      >
        {filtered.map((t) => {
          const isDone = t.status === 'completed';
          return (
            <li
              key={t.id}
              className={cn(
                'flex items-start gap-2 px-2 py-1.5 rounded @container',
                'bg-[color:var(--card)] border-l-2',
                'hover:bg-[color:var(--accent)] transition-colors',
                isDone && 'opacity-60'
              )}
              style={{ borderLeftColor: PRIO_COLORS[t.priority] }}
            >
              {/* prio badge */}
              <span
                className="text-[10px] font-bold px-1 rounded shrink-0"
                style={{ backgroundColor: PRIO_COLORS[t.priority], color: '#fff' }}
              >
                {t.priority}
              </span>
              {/* body */}
              <button
                type="button"
                onClick={() => onTaskClick?.(t)}
                className="flex flex-col flex-1 min-w-0 text-left"
              >
                <span
                  className={cn('text-xs', isDone && 'line-through')}
                  style={{ color: 'var(--foreground)' }}
                >
                  {t.title}
                </span>
                {t.description && (
                  <span
                    className="text-[10px] truncate"
                    style={{ color: 'var(--text-tertiary)' }}
                  >
                    {t.description}
                  </span>
                )}
                <span
                  className="text-[10px]"
                  style={{ color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)' }}
                >
                  {t.category}
                  {t.dueDate &&
                    ` · 截止 ${typeof t.dueDate === 'string' ? t.dueDate : t.dueDate.toLocaleDateString()}`}
                </span>
              </button>
              {/* complete checkbox */}
              {onComplete && !isDone && (
                <button
                  type="button"
                  onClick={() => onComplete(t.id)}
                  aria-label={`完成: ${t.title}`}
                  className={cn(
                    'shrink-0 w-5 h-5 rounded border text-[10px]',
                    'border-[color:var(--border-strong)] text-[color:var(--text-tertiary)]',
                    'hover:bg-[color:var(--green-down)] hover:text-white hover:border-[color:var(--green-down)]',
                    'transition-colors'
                  )}
                >
                  ✓
                </button>
              )}
              {isDone && (
                <span
                  className="shrink-0 text-xs"
                  style={{ color: 'var(--green-down)' }}
                  aria-label="已完成"
                >
                  ✓
                </span>
              )}
            </li>
          );
        })}
      </ul>
    );
  }
);

OTrainingTaskList.displayName = 'OTrainingTaskList';
