/**
 * OFundingRate - 资金费率 + 下次结算倒计时。
 *
 * 合约必备 Block (永续合约每 8 小时结算一次资金费)。
 *
 * 数据契约 (对齐 Binance markPrice stream):
 *   symbol:          BTCUSDT
 *   fundingRate:     0.00010000  (0.01% 表示 0.0001)
 *   nextFundingTime: Unix ms     (下次结算时间)
 *   markPrice:       11793.63    (mark 价)
 *   indexPrice:      11781.80    (index 价)
 *
 * 视觉:
 *   - 上行: 资金费率 (大字, 颜色按正负)
 *   - 中行: 下次结算倒计时 (HH:MM:SS)
 *   - 下行: mark / index 价 + 偏差
 */

'use client';

import { forwardRef, useEffect, useMemo, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { useFastData } from '../../providers/FastDataProvider';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';

export interface OFundingRateData {
  symbol: string;
  /** 当前资金费率 (decimal, 0.0001 = 0.01%). */
  fundingRate: number;
  /** 下次结算时间 Unix ms. */
  nextFundingTime: number;
  markPrice: number;
  indexPrice?: number;
  /** 历史平均资金费率 (可选). */
  avgFundingRate?: number;
}

export interface OFundingRateProps
  extends OBlockDataProps<OFundingRateData>,
    Pick<TerminalBlockProps, 'channel' | 'dataDelay' | 'regulation' | 'flashOnUpdate'> {
  /** 紧凑横向布局 (单行). */
  compact?: boolean;
}

function formatCountdown(ms: number): string {
  if (ms <= 0) return '00:00:00';
  const total = Math.floor(ms / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
}

export const OFundingRate = forwardRef<HTMLDivElement, OFundingRateProps>(
  function OFundingRate(
    {
      data: dataProp,
      loading,
      error,
      empty,
      channel,
      compact = false,
      dataDelay = 0,
      regulation: _r,
      flashOnUpdate: _f,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OFundingRateData | null>(null);
    useEffect(() => {
      if (!channel || !fastData) return;
      return fastData.subscribe<OFundingRateData>(channel, setChannelData);
    }, [channel, fastData]);

    const data = channel ? channelData : (dataProp ?? null);
    const state = resolveBlockState({ data, loading, error, empty });

    // 倒计时(每秒 tick)
    const [now, setNow] = useState(() => Date.now());
    useEffect(() => {
      const id = setInterval(() => setNow(Date.now()), 1000);
      return () => clearInterval(id);
    }, []);

    const countdown = useMemo(() => {
      if (!data) return 0;
      return data.nextFundingTime - now;
    }, [data, now]);

    if (state === 'loading')
      return (
        <div
          ref={ref}
          className={cn(
            'rounded-md border border-border bg-card p-3 @container',
            className
          )}
        >
          <OLoadingState rows={2} rowHeight="1rem" />
        </div>
      );
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data) return null;

    const ratePct = data.fundingRate * 100;
    const rateColor =
      data.fundingRate > 0
        ? 'var(--quote-up)'
        : data.fundingRate < 0
          ? 'var(--quote-down)'
          : 'var(--text-muted)';
    const ratePrefix = data.fundingRate > 0 ? '+' : '';

    // 倒计时颜色 - < 1 分钟时红色提示
    const countdownColor =
      countdown < 60_000 ? 'var(--quote-down)' : countdown < 300_000 ? 'var(--alert-warn)' : 'var(--foreground)';

    if (compact) {
      return (
        <div
          ref={ref}
          className={cn(
            'flex items-center gap-3 px-3 py-2 rounded-md border border-border bg-card',
            className
          )}
          style={{ fontFamily: 'var(--font-data)' }}
        >
          <div className="flex items-baseline gap-1">
            <span className="text-[10px] text-[color:var(--text-muted)]">资金费率</span>
            <span className="tabular-nums text-sm font-mono" style={{ color: rateColor }}>
              {ratePrefix}
              {ratePct.toFixed(4)}%
            </span>
          </div>
          <div className="flex items-baseline gap-1 border-l border-border pl-3">
            <span className="text-[10px] text-[color:var(--text-muted)]">下次结算</span>
            <span className="tabular-nums text-sm font-mono" style={{ color: countdownColor }}>
              {formatCountdown(countdown)}
            </span>
          </div>
          {dataDelay > 0 ? (
            <span className="text-[10px] text-[color:var(--alert-warn)] ml-auto">
              延时 {dataDelay}m
            </span>
          ) : null}
        </div>
      );
    }

    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card p-3 flex flex-col gap-2 relative',
          className
        )}
        style={{ fontFamily: 'var(--font-ui)' }}
      >
        {dataDelay > 0 ? (
          <div className="absolute top-1 right-2 text-[10px] text-[color:var(--alert-warn)] font-mono pointer-events-none">
            延时 {dataDelay}m
          </div>
        ) : null}

        {/* 资金费率 */}
        <div>
          <div className="text-[10px] text-[color:var(--text-muted)] uppercase tracking-[0.04em]">
            资金费率 · {data.symbol}
          </div>
          <div
            className="text-2xl font-extrabold tracking-[-0.03em] tabular-nums"
            style={{ color: rateColor, fontFamily: 'var(--font-data)' }}
          >
            {ratePrefix}
            {ratePct.toFixed(4)}%
          </div>
          {typeof data.avgFundingRate === 'number' ? (
            <div className="text-[10px] text-[color:var(--text-muted)] tabular-nums">
              7d 均: {(data.avgFundingRate * 100).toFixed(4)}%
            </div>
          ) : null}
        </div>

        {/* 倒计时 */}
        <div className="border-t border-border pt-2">
          <div className="text-[10px] text-[color:var(--text-muted)] uppercase tracking-[0.04em]">
            下次结算
          </div>
          <div
            className="text-lg font-mono tabular-nums"
            style={{ color: countdownColor }}
          >
            {formatCountdown(countdown)}
          </div>
        </div>

        {/* Mark / Index */}
        <div className="border-t border-border pt-2 grid grid-cols-2 gap-2 text-xs">
          <div>
            <div className="text-[10px] text-[color:var(--text-muted)]">Mark</div>
            <div className="tabular-nums font-mono">{data.markPrice.toFixed(2)}</div>
          </div>
          {typeof data.indexPrice === 'number' ? (
            <div>
              <div className="text-[10px] text-[color:var(--text-muted)]">Index</div>
              <div className="tabular-nums font-mono">{data.indexPrice.toFixed(2)}</div>
            </div>
          ) : null}
        </div>
      </div>
    );
  }
);

OFundingRate.displayName = 'OFundingRate';
