/**
 * perf-budget - 帮助消费方在单页面跟踪重型 Block 用量。
 *
 * SPEC §3.6:
 *   - 类 3 (重型 3D/WebGL):  ≤ 1 个/页
 *   - 类 2 (视觉增强):        ≤ 5 个/页
 *
 * 这是诊断工具,不强制(强制会破坏组合自由度)。
 * 在 dev 模式下挂在 window.__heliosPerfBudget,过 budget 时 console.warn。
 *
 * @example
 * // Page 顶部:
 * if (process.env.NODE_ENV === 'development') {
 *   import('@helios/blocks/perf').then(({ resetPerfBudget }) => resetPerfBudget());
 * }
 */

type Tier = 'tier-2' | 'tier-3';

interface BudgetState {
  counts: Record<Tier, number>;
  limits: Record<Tier, number>;
  warned: Set<string>;
}

const LIMITS: Record<Tier, number> = {
  'tier-2': 5,
  'tier-3': 1,
};

function getState(): BudgetState {
  if (typeof window === 'undefined') {
    return { counts: { 'tier-2': 0, 'tier-3': 0 }, limits: LIMITS, warned: new Set() };
  }
  const w = window as unknown as { __heliosPerfBudget?: BudgetState };
  if (!w.__heliosPerfBudget) {
    w.__heliosPerfBudget = {
      counts: { 'tier-2': 0, 'tier-3': 0 },
      limits: { ...LIMITS },
      warned: new Set(),
    };
  }
  return w.__heliosPerfBudget;
}

export function registerBlockUsage(blockName: string, tier: Tier): void {
  if (typeof window === 'undefined') return;
  const s = getState();
  s.counts[tier]++;
  if (s.counts[tier] > s.limits[tier] && !s.warned.has(blockName)) {
    s.warned.add(blockName);
    console.warn(
      `[@helios/blocks] Performance budget exceeded for ${tier}: ` +
        `${s.counts[tier]}/${s.limits[tier]} on this page. ` +
        `Block: ${blockName}. See SPEC §3.6.`
    );
  }
}

export function resetPerfBudget(): void {
  if (typeof window === 'undefined') return;
  const s = getState();
  s.counts['tier-2'] = 0;
  s.counts['tier-3'] = 0;
  s.warned.clear();
}

export function getPerfBudgetUsage() {
  const s = getState();
  return {
    used: { ...s.counts },
    limits: { ...s.limits },
    overBudget: {
      'tier-2': s.counts['tier-2'] > s.limits['tier-2'],
      'tier-3': s.counts['tier-3'] > s.limits['tier-3'],
    },
  };
}
