'use client';
import { forwardRef, type ComponentPropsWithoutRef, type ElementRef } from 'react';
import * as DialogPrimitive from '@radix-ui/react-dialog';
import { cn } from '../../lib/cn';
import { dialogOverlayRecipe, dialogContentRecipe, type DialogContentRecipeProps } from '../../recipes';

export const ODialog = DialogPrimitive.Root;
export const ODialogTrigger = DialogPrimitive.Trigger;
export const ODialogClose = DialogPrimitive.Close;
export const ODialogPortal = DialogPrimitive.Portal;

export const ODialogContent = forwardRef<
  ElementRef<typeof DialogPrimitive.Content>,
  ComponentPropsWithoutRef<typeof DialogPrimitive.Content> & DialogContentRecipeProps
>(function ODialogContent({ className, size, children, ...props }, ref) {
  return (
    <DialogPrimitive.Portal>
      <DialogPrimitive.Overlay className={dialogOverlayRecipe()} />
      <DialogPrimitive.Content ref={ref} className={cn(dialogContentRecipe({ size }), className)} {...props}>
        {children}
        <DialogPrimitive.Close
          className="absolute right-4 top-4 rounded-[var(--radius-sm)] opacity-60 transition-opacity hover:opacity-100 focus-visible:ring-2 focus-visible:ring-[color:var(--ring)] outline-none"
          aria-label="关闭 (Close)"
        >
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
            <path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/>
          </svg>
        </DialogPrimitive.Close>
      </DialogPrimitive.Content>
    </DialogPrimitive.Portal>
  );
});
ODialogContent.displayName = 'ODialogContent';

export const ODialogHeader = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) =>
  <div className={cn('flex flex-col gap-1.5 text-left', className)} {...props} />;
ODialogHeader.displayName = 'ODialogHeader';

export const ODialogTitle = forwardRef<
  ElementRef<typeof DialogPrimitive.Title>,
  ComponentPropsWithoutRef<typeof DialogPrimitive.Title>
>(function ODialogTitle({ className, ...props }, ref) {
  return <DialogPrimitive.Title ref={ref} className={cn('font-[number:var(--fw-semibold)] text-[length:var(--text-lg)] leading-[var(--lh-snug)]', className)} {...props} />;
});
ODialogTitle.displayName = 'ODialogTitle';

export const ODialogDescription = forwardRef<
  ElementRef<typeof DialogPrimitive.Description>,
  ComponentPropsWithoutRef<typeof DialogPrimitive.Description>
>(function ODialogDescription({ className, ...props }, ref) {
  return <DialogPrimitive.Description ref={ref} className={cn('text-[length:var(--text-sm)] text-[color:var(--muted-foreground)]', className)} {...props} />;
});
ODialogDescription.displayName = 'ODialogDescription';
