/**
 * OStreamingProvider — 统一流式数据抽象(SSE / WebSocket)
 *
 * 痛点:
 *   - Stratum agent_run 用 SSE
 *   - Aegis log stream 用 WebSocket
 *   - hevi pipeline progress 也用 WebSocket
 *   各 Block 自己写连接 / 重连 / 解析逻辑,30% 代码重复。
 *
 * 解法:
 *   StreamingService 抽象:subscribe(channel, handler) → unsubscribe
 *   默认两个实现:WebSocket(双向)、EventSource(单向 SSE)。
 *   应用层可注入自定义实现(测试 mock / 重连策略 / 协议升级)。
 *
 * 不在范围:
 *   - 短轮询(用 TanStack Query refetchInterval)
 *   - 高频 tick(用 FastDataProvider 专门优化)
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  type ReactNode,
} from 'react';

// ============================================================
// 协议
// ============================================================

export type StreamingMessage<T = unknown> = {
  /** 频道名,跟 ChannelName 规范对齐:{project}.{domain}.{resource}.{detail}。 */
  channel: string;
  /** 消息 payload。 */
  data: T;
  /** ISO 8601 时间戳。 */
  ts: string;
  /** 跟踪 ID(trc_xxx)。 */
  trace_id?: string;
};

export type StreamingHandler<T = unknown> = (msg: StreamingMessage<T>) => void;

export type StreamingStatus =
  | 'idle'
  | 'connecting'
  | 'open'
  | 'reconnecting'
  | 'closed'
  | 'error';

export interface StreamingService {
  /** 订阅频道。返回 unsubscribe 函数。 */
  subscribe<T = unknown>(channel: string, handler: StreamingHandler<T>): () => void;
  /** 发送消息(WebSocket 才支持;SSE 走 HTTP POST 配套)。 */
  send?<T = unknown>(channel: string, data: T): void;
  /** 获取当前连接状态。 */
  status(): StreamingStatus;
  /** 订阅状态变化。 */
  onStatusChange(handler: (status: StreamingStatus) => void): () => void;
  /** 手动重连。 */
  reconnect(): void;
  /** 关闭连接。 */
  close(): void;
}

// ============================================================
// WebSocket 实现
// ============================================================

export interface WebSocketServiceOptions {
  /** ws:// 或 wss:// URL。 */
  url: string;
  /** 重连策略(指数退避)。默认 1s, 2s, 4s, 8s, 30s。 */
  reconnectDelays?: number[];
  /** 心跳间隔(ms)。0 = 关闭。默认 25000(25s)。 */
  heartbeatIntervalMs?: number;
  /** 心跳消息内容。 */
  heartbeatMessage?: unknown;
}

export function createWebSocketService(opts: WebSocketServiceOptions): StreamingService {
  const reconnectDelays = opts.reconnectDelays ?? [1000, 2000, 4000, 8000, 30000];
  const heartbeatMs = opts.heartbeatIntervalMs ?? 25000;

  let ws: WebSocket | null = null;
  let status: StreamingStatus = 'idle';
  let reconnectAttempt = 0;
  let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  let heartbeatTimer: ReturnType<typeof setInterval> | null = null;
  let manualClose = false;

  const handlers = new Map<string, Set<StreamingHandler>>();
  const statusListeners = new Set<(s: StreamingStatus) => void>();

  function setStatus(s: StreamingStatus) {
    status = s;
    for (const l of statusListeners) l(s);
  }

  function connect() {
    if (typeof WebSocket === 'undefined') return;
    setStatus(reconnectAttempt === 0 ? 'connecting' : 'reconnecting');
    try {
      ws = new WebSocket(opts.url);
    } catch {
      setStatus('error');
      scheduleReconnect();
      return;
    }

    ws.onopen = () => {
      reconnectAttempt = 0;
      setStatus('open');
      if (heartbeatMs > 0) {
        heartbeatTimer = setInterval(() => {
          try {
            ws?.send(JSON.stringify(opts.heartbeatMessage ?? { type: 'ping' }));
          } catch {
            /* ignore */
          }
        }, heartbeatMs);
      }
    };

    ws.onmessage = (e) => {
      try {
        const parsed = JSON.parse(e.data) as StreamingMessage;
        if (typeof parsed.channel !== 'string') return;
        const set = handlers.get(parsed.channel);
        if (set) {
          for (const h of set) h(parsed);
        }
      } catch {
        // 忽略非 JSON 消息(可能是心跳响应)
      }
    };

    ws.onerror = () => {
      setStatus('error');
    };

    ws.onclose = () => {
      if (heartbeatTimer) {
        clearInterval(heartbeatTimer);
        heartbeatTimer = null;
      }
      if (manualClose) {
        setStatus('closed');
        return;
      }
      scheduleReconnect();
    };
  }

  function scheduleReconnect() {
    const delay =
      reconnectDelays[Math.min(reconnectAttempt, reconnectDelays.length - 1)] ?? 30000;
    reconnectAttempt++;
    reconnectTimer = setTimeout(connect, delay);
  }

  function teardown() {
    manualClose = true;
    if (reconnectTimer) clearTimeout(reconnectTimer);
    if (heartbeatTimer) clearInterval(heartbeatTimer);
    if (ws) {
      try {
        ws.close();
      } catch {
        /* ignore */
      }
      ws = null;
    }
  }

  // 立即连接
  connect();

  return {
    subscribe(channel, handler) {
      let set = handlers.get(channel);
      if (!set) {
        set = new Set();
        handlers.set(channel, set);
      }
      set.add(handler as StreamingHandler);
      return () => {
        set?.delete(handler as StreamingHandler);
        if (set && set.size === 0) handlers.delete(channel);
      };
    },
    send(channel, data) {
      if (ws?.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({ channel, data, ts: new Date().toISOString() }));
      }
    },
    status() {
      return status;
    },
    onStatusChange(handler) {
      statusListeners.add(handler);
      return () => statusListeners.delete(handler);
    },
    reconnect() {
      reconnectAttempt = 0;
      teardown();
      manualClose = false;
      connect();
    },
    close() {
      teardown();
    },
  };
}

// ============================================================
// 内存实现(测试 / SSR fallback)
// ============================================================

export function createMemoryStreamingService(): StreamingService {
  const handlers = new Map<string, Set<StreamingHandler>>();
  const statusListeners = new Set<(s: StreamingStatus) => void>();

  return {
    subscribe(channel, handler) {
      let set = handlers.get(channel);
      if (!set) {
        set = new Set();
        handlers.set(channel, set);
      }
      set.add(handler as StreamingHandler);
      return () => set?.delete(handler as StreamingHandler);
    },
    send() {
      // memory 模式下,send 触发本地 echo(测试用)
    },
    status() {
      return 'idle';
    },
    onStatusChange(handler) {
      statusListeners.add(handler);
      return () => statusListeners.delete(handler);
    },
    reconnect() {
      // noop
    },
    close() {
      handlers.clear();
    },
  };
}

// ============================================================
// Context + Provider
// ============================================================

const StreamingContext = createContext<StreamingService | null>(null);

export interface OStreamingProviderProps {
  /** 自定义实现。不传则需要传 url 用 WebSocket 默认实现。 */
  service?: StreamingService;
  /** WebSocket URL(传了 service 后忽略)。 */
  url?: string;
  children: ReactNode;
}

export function OStreamingProvider({
  service,
  url,
  children,
}: OStreamingProviderProps) {
  const resolvedService = useMemo<StreamingService>(() => {
    if (service) return service;
    if (url) return createWebSocketService({ url });
    return createMemoryStreamingService();
  }, [service, url]);

  // 卸载时关闭连接
  useEffect(() => {
    return () => {
      resolvedService.close();
    };
  }, [resolvedService]);

  return (
    <StreamingContext.Provider value={resolvedService}>
      {children}
    </StreamingContext.Provider>
  );
}

OStreamingProvider.displayName = 'OStreamingProvider';

/**
 * 拿到当前 StreamingService。无 Provider 时返回内存 fallback。
 */
export function useStreaming(): StreamingService {
  const ctx = useContext(StreamingContext);
  return ctx ?? createMemoryStreamingService();
}

/**
 * 订阅频道的 hook,自动管理订阅生命周期。
 */
export function useStreamingChannel<T = unknown>(
  channel: string,
  handler: StreamingHandler<T>
): void {
  const streaming = useStreaming();
  // 用 ref 锁定 handler 引用,避免每次 render 重订阅
  const handlerRef = useRef(handler);
  handlerRef.current = handler;

  const stableHandler = useCallback<StreamingHandler<T>>((msg) => {
    handlerRef.current(msg);
  }, []);

  useEffect(() => {
    return streaming.subscribe<T>(channel, stableHandler);
  }, [streaming, channel, stableHandler]);
}
