/**
 * ODocumentTree — Substrate 列表 + medium 分组
 *
 * 消费 Substrate[](API §1.1)。
 *
 * 设计:
 *   - 按 medium 分组(webpage / paper / book / markdown_note / ...)
 *   - 每组可折叠
 *   - 每个 substrate 显示 title + pinned 图标 + created_at
 *   - 点击触发 onSelect callback
 *   - 选中态高亮
 *
 * v1.0 限制(API §15.1 #8):
 *   - list_substrates 无 REST 端点,消费方用 MCP search 替代
 *   - 本 Block 只负责渲染,数据来源由消费方提供
 */
import {
  forwardRef,
  useCallback,
  useMemo,
  useState,
  type KeyboardEvent,
} from 'react';
import { cn } from '../../lib/cn';
import type { Substrate, Medium } from '../../types/stratum';
import type { OBlockBaseProps } from '../../lib/types';

export interface ODocumentTreeProps extends Omit<OBlockBaseProps, 'variant'> {
  /** Substrate 列表(消费方提供)。 */
  substrates: Substrate[];
  /** 当前选中的 substrate id(可选,受控)。 */
  selectedId?: string;
  /** 点击 substrate 触发。 */
  onSelect?: (substrate: Substrate) => void;
  /** 初始展开的 medium 分组(默认全部展开)。 */
  defaultExpandedMediums?: Medium[];
  /** 空状态文案。 */
  emptyText?: string;
}

const MEDIUM_LABEL: Record<string, string> = {
  webpage: '网页',
  paper: '论文',
  book: '书籍',
  markdown_note: '笔记',
  transcript: '字幕',
  chat: '对话',
  other: '其他',
};

const MEDIUM_ICON: Record<string, string> = {
  webpage: '🌐',
  paper: '📄',
  book: '📚',
  markdown_note: '📝',
  transcript: '🎬',
  chat: '💬',
  other: '📦',
};

export const ODocumentTree = forwardRef<HTMLDivElement, ODocumentTreeProps>(
  function ODocumentTree(
    {
      substrates,
      selectedId,
      onSelect,
      defaultExpandedMediums,
      emptyText = '暂无文档',
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const groups = useMemo(() => {
      const map = new Map<string, Substrate[]>();
      for (const s of substrates) {
        const m = s.meta_json?.medium ?? 'other';
        if (!map.has(m)) map.set(m, []);
        map.get(m)!.push(s);
      }
      return Array.from(map.entries()).sort(([a], [b]) => a.localeCompare(b));
    }, [substrates]);

    const [expanded, setExpanded] = useState<Set<string>>(() => {
      if (defaultExpandedMediums) return new Set(defaultExpandedMediums);
      return new Set(groups.map(([m]) => m));
    });

    const toggleGroup = useCallback((medium: string) => {
      setExpanded((prev) => {
        const next = new Set(prev);
        if (next.has(medium)) next.delete(medium);
        else next.add(medium);
        return next;
      });
    }, []);

    const handleSubstrateKey = useCallback(
      (e: KeyboardEvent<HTMLButtonElement>, s: Substrate) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onSelect?.(s);
        }
      },
      [onSelect]
    );

    if (substrates.length === 0) {
      return (
        <div
          ref={ref}
          className={cn(
            'px-4 py-8 text-center text-sm text-[color:var(--text-muted)] @container',
            'border border-dashed border-border rounded-lg',
            className
          )}
        >
          {emptyText}
        </div>
      );
    }

    return (
      <nav
        ref={ref}
        className={cn('flex flex-col gap-1 w-full', className)}
        aria-label="文档树"
      >
        {groups.map(([medium, items]) => {
          const isExpanded = expanded.has(medium);
          return (
            <div key={medium} className="flex flex-col">
              <button
                type="button"
                onClick={() => toggleGroup(medium)}
                aria-expanded={isExpanded}
                className={cn(
                  'flex items-center gap-2 px-2 py-1 rounded text-sm',
                  'hover:bg-muted/30 transition-colors',
                  'text-[color:var(--foreground)]'
                )}
              >
                <span
                  className={cn('text-[10px] transition-transform', isExpanded && 'rotate-90')}
                  aria-hidden="true"
                >
                  ▶
                </span>
                <span aria-hidden="true">{MEDIUM_ICON[medium] ?? '📦'}</span>
                <span className="font-medium">{MEDIUM_LABEL[medium] ?? medium}</span>
                <span className="text-xs text-[color:var(--text-muted)] font-mono">
                  ({items.length})
                </span>
              </button>
              {isExpanded && (
                <ul className="flex flex-col gap-0.5 list-none p-0 m-0 ml-4">
                  {items.map((s) => {
                    const isSelected = s.id === selectedId;
                    return (
                      <li key={s.id} className="flex">
                        <button
                          type="button"
                          onClick={() => onSelect?.(s)}
                          onKeyDown={(e) => handleSubstrateKey(e, s)}
                          aria-current={isSelected ? 'true' : undefined}
                          className={cn(
                            'flex items-center gap-1.5 px-2 py-1 rounded text-sm w-full text-left',
                            'hover:bg-muted/30 transition-colors',
                            isSelected && 'bg-primary/10',
                            'focus:outline-none focus-visible:ring-2 focus-visible:ring-ring'
                          )}
                        >
                          {s.is_pinned && (
                            <span className="text-[10px]" title="已 Pin" aria-label="已 Pin">
                              📌
                            </span>
                          )}
                          <span className="truncate flex-1 text-[color:var(--foreground)]">
                            {s.title || s.id.slice(0, 16)}
                          </span>
                        </button>
                      </li>
                    );
                  })}
                </ul>
              )}
            </div>
          );
        })}
      </nav>
    );
  }
);

ODocumentTree.displayName = 'ODocumentTree';
