/**
 * OPersistenceProvider — 统一持久化抽象
 *
 * 痛点:
 *   各 Block / Provider 散落 localStorage 调用,SSR 不安全,无法切换 storage
 *   后端,无法统一序列化策略,清理用户数据时找不到 keys。
 *
 * 解法:
 *   注入一个统一的 PersistenceService,各处通过 usePersistence() 拿到。
 *   默认实现:localStorage(浏览器)/ 内存(SSR)。
 *   可替换:IndexedDB(大数据)/ Server(跨设备同步)/ Encrypted(敏感数据)。
 *
 * 自托管原则:数据所有权 — 默认本地,云端同步必须用户显式选择。
 */

import { createContext, useContext, useMemo, type ReactNode } from 'react';

// ============================================================
// 协议
// ============================================================

export interface PersistenceService {
  /** 读(同步,小数据用)。失败返回 null。 */
  get<T = unknown>(key: string): T | null;
  /** 写(同步)。失败抛错(quota 超限等)。 */
  set<T = unknown>(key: string, value: T): void;
  /** 删除。 */
  remove(key: string): void;
  /** 列出所有匹配前缀的 keys。 */
  list(prefix?: string): string[];
  /** 清空所有项目专属 keys(不动其他 app 的数据,通过 namespace 隔离)。 */
  clearNamespace(): void;
  /** 当前 namespace(用于 debug)。 */
  readonly namespace: string;
}

// ============================================================
// 默认实现:localStorage(带 namespace 隔离 + SSR 安全)
// ============================================================

function createLocalStorageService(namespace: string): PersistenceService {
  const prefix = `${namespace}:`;
  const isClient = typeof window !== 'undefined' && !!window.localStorage;

  return {
    namespace,

    get<T>(key: string): T | null {
      if (!isClient) return null;
      try {
        const raw = window.localStorage.getItem(prefix + key);
        return raw == null ? null : (JSON.parse(raw) as T);
      } catch {
        return null;
      }
    },

    set<T>(key: string, value: T): void {
      if (!isClient) return;
      // quota 超限或其他错误直接抛给调用方
      window.localStorage.setItem(prefix + key, JSON.stringify(value));
    },

    remove(key: string): void {
      if (!isClient) return;
      try {
        window.localStorage.removeItem(prefix + key);
      } catch {
        // ignore
      }
    },

    list(filterPrefix?: string): string[] {
      if (!isClient) return [];
      const out: string[] = [];
      const fullPrefix = filterPrefix ? prefix + filterPrefix : prefix;
      for (let i = 0; i < window.localStorage.length; i++) {
        const k = window.localStorage.key(i);
        if (k && k.startsWith(fullPrefix)) {
          out.push(k.slice(prefix.length));
        }
      }
      return out;
    },

    clearNamespace(): void {
      if (!isClient) return;
      const keys = this.list();
      for (const k of keys) this.remove(k);
    },
  };
}

// ============================================================
// 内存实现(SSR / 测试用)
// ============================================================

function createMemoryService(namespace: string): PersistenceService {
  const store = new Map<string, unknown>();
  return {
    namespace,
    get: <T,>(key: string) => (store.has(key) ? (store.get(key) as T) : null),
    set: <T,>(key: string, value: T) => {
      store.set(key, value);
    },
    remove: (key: string) => {
      store.delete(key);
    },
    list: (filterPrefix?: string) => {
      const out: string[] = [];
      for (const k of store.keys()) {
        if (!filterPrefix || k.startsWith(filterPrefix)) out.push(k);
      }
      return out;
    },
    clearNamespace: () => {
      store.clear();
    },
  };
}

// ============================================================
// Context + Provider
// ============================================================

const PersistenceContext = createContext<PersistenceService | null>(null);

export interface OPersistenceProviderProps {
  /** namespace 前缀。建议 = 项目名,例:'helios' / 'stratum' / 'aegis'。 */
  namespace: string;
  /** 自定义实现(不传则用 localStorage,SSR 自动退化到 memory)。 */
  service?: PersistenceService;
  children: ReactNode;
}

export function OPersistenceProvider({
  namespace,
  service,
  children,
}: OPersistenceProviderProps) {
  const resolvedService = useMemo<PersistenceService>(() => {
    if (service) return service;
    return typeof window !== 'undefined' && window.localStorage
      ? createLocalStorageService(namespace)
      : createMemoryService(namespace);
  }, [namespace, service]);

  return (
    <PersistenceContext.Provider value={resolvedService}>
      {children}
    </PersistenceContext.Provider>
  );
}

OPersistenceProvider.displayName = 'OPersistenceProvider';

/**
 * 拿到当前 PersistenceService。无 Provider 时返回内存 fallback。
 */
export function usePersistence(): PersistenceService {
  const ctx = useContext(PersistenceContext);
  if (!ctx) {
    // 没 Provider 时给个静默 fallback(避免崩溃,但 warn 提示)
    if (typeof console !== 'undefined' && typeof window !== 'undefined') {
      // 仅在 client 端 warn 一次
      console.warn(
        '[OPersistenceProvider] usePersistence() called outside Provider; ' +
          'using memory fallback (data will NOT persist across page reloads).'
      );
    }
    return createMemoryService('__fallback__');
  }
  return ctx;
}

// ============================================================
// 导出工厂函数(应用层可以自己包 IndexedDB / 加密 / server-side)
// ============================================================

export { createLocalStorageService, createMemoryService };
