/**
 * ORegimeExplanationPopover (Tide Wave 1 E2, Block)
 *
 * 用途:ORegimeBar 单击后弹出的解释面板。
 * 来源:OUI_WAVE_1_REQUIREMENTS_v1.0.md §4
 *
 * 显示:
 *   - 当前 regime / confidence / 趋势 / 持续天数
 *   - 触发条件 list(✓ / ✗)
 *   - smoothing 状态(已确认 / transitional 中)
 *   - 仓位上限信息
 *   - Fusion weight overrides
 */
import {
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  type KeyboardEvent,
} from 'react';
import { createPortal } from 'react-dom';
import { cn } from '../../lib/cn';
import {
  REGIME_LABEL,
  REGIME_COLOR_VAR,
  type RegimeState,
} from '../../types/tide';
import type { OBlockBaseProps } from '../../lib/types';

export interface TriggerCondition {
  label: string;
  actualValue: string;
  passed: boolean;
}

export interface SmoothingStatus {
  rawState: RegimeState;
  isConfirmed: boolean;
  confirmedDaysAgo?: number;
  transitionalState?: RegimeState;
  transitionalDays?: number;
}

export interface PositionLimits {
  regimeLimitPct: number;
  currentPositionPct: number;
  availableIncreasePct: number;
}

export interface FusionOverride {
  dimName: string;
  multiplier: number;
  isBoosted: boolean;
  isDampened: boolean;
  iconEmoji?: string;
}

export interface ORegimeExplanationPopoverProps extends Omit<OBlockBaseProps, 'variant'> {
  isOpen: boolean;
  onClose: () => void;
  regime: RegimeState;
  confidence: number;
  trendDirection: 'up' | 'down' | 'flat';
  daysInState: number;
  triggerConditions: TriggerCondition[];
  smoothingStatus: SmoothingStatus;
  positionLimits: PositionLimits;
  fusionOverrides: FusionOverride[];
  anchorRect?: DOMRect;
}

const TREND_LABEL: Record<'up' | 'down' | 'flat', string> = {
  up: '⬈ up',
  down: '⬊ down',
  flat: '→ flat',
};

export const ORegimeExplanationPopover = forwardRef<
  HTMLDivElement,
  ORegimeExplanationPopoverProps
>(function ORegimeExplanationPopover(
  {
    isOpen,
    onClose,
    regime,
    confidence,
    trendDirection,
    daysInState,
    triggerConditions,
    smoothingStatus,
    positionLimits,
    fusionOverrides,
    anchorRect,
    className,
    theme: _t,
    size: _s,
  },
  ref
) {
  const popoverRef = useRef<HTMLDivElement | null>(null);

  // Esc 关闭
  useEffect(() => {
    if (!isOpen) return;
    const onKey = (e: globalThis.KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [isOpen, onClose]);

  // 点弹窗外关闭
  useEffect(() => {
    if (!isOpen) return;
    const onClick = (e: MouseEvent) => {
      if (popoverRef.current && !popoverRef.current.contains(e.target as Node)) {
        onClose();
      }
    };
    // 延迟绑定避免立即触发(单击 ORegimeBar 的同一事件)
    const t = setTimeout(() => document.addEventListener('mousedown', onClick), 0);
    return () => {
      clearTimeout(t);
      document.removeEventListener('mousedown', onClick);
    };
  }, [isOpen, onClose]);

  // 焦点自动进入弹窗
  useEffect(() => {
    if (isOpen && popoverRef.current) {
      popoverRef.current.focus();
    }
  }, [isOpen]);

  const handleEsc = useCallback(
    (e: KeyboardEvent<HTMLDivElement>) => {
      if (e.key === 'Escape') onClose();
    },
    [onClose]
  );

  if (!isOpen) return null;

  // 锚定位置(默认顶部居中)
  const positionStyle: React.CSSProperties = anchorRect
    ? {
        position: 'fixed',
        top: anchorRect.bottom + 6,
        left: Math.max(8, anchorRect.left),
        zIndex: 1000,
      }
    : {
        position: 'fixed',
        top: 80,
        left: '50%',
        transform: 'translateX(-50%)',
        zIndex: 1000,
      };

  const positionPercent = (positionLimits.currentPositionPct * 100).toFixed(0);
  const limitPercent = (positionLimits.regimeLimitPct * 100).toFixed(0);
  const availablePercent = (positionLimits.availableIncreasePct * 100).toFixed(0);

  const content = (
    <div
      ref={(node) => {
        popoverRef.current = node;
        if (typeof ref === 'function') ref(node);
        else if (ref) ref.current = node;
      }}
      role="dialog"
      aria-modal="true"
      aria-label="Regime 解释"
      tabIndex={-1}
      onKeyDown={handleEsc}
      style={{ ...positionStyle, fontFamily: 'var(--font-sans)' }}
      className={cn(
        'w-[420px] max-h-[80vh] overflow-auto rounded-md @container',
        'bg-[color:var(--card)] border border-[color:var(--border-strong)]',
        'shadow-2xl',
        className
      )}
    >
      {/* header */}
      <header className="flex items-center justify-between px-3 py-2 border-b border-[color:var(--border-subtle)]">
        <h2
          className="text-sm font-bold tracking-[-0.01em]"
          style={{ color: 'var(--foreground)' }}
        >
          Regime 解释
        </h2>
        <button
          type="button"
          onClick={onClose}
          aria-label="关闭"
          className={cn(
            'text-xs px-2 py-0.5 rounded',
            'text-[color:var(--muted-foreground)] hover:text-[color:var(--foreground)]',
            'hover:bg-[color:var(--muted)] transition-colors'
          )}
        >
          关闭
        </button>
      </header>

      {/* 当前 */}
      <section className="px-3 py-2 border-b border-[color:var(--border-subtle)]">
        <div className="flex items-center gap-2 mb-1">
          <span
            className="px-1.5 py-0.5 rounded text-xs font-bold"
            style={{ backgroundColor: REGIME_COLOR_VAR[regime], color: '#fff' }}
          >
            {REGIME_LABEL[regime]}
          </span>
          <span
            className="text-xs"
            style={{ color: 'var(--muted-foreground)' }}
          >
            (smoothed)
          </span>
        </div>
        <div
          className="text-xs"
          style={{ color: 'var(--muted-foreground)', fontFamily: 'var(--font-mono)' }}
        >
          置信度 {confidence.toFixed(2)} / 趋势 {TREND_LABEL[trendDirection]} / 持续 {daysInState} 天
        </div>
      </section>

      {/* 触发条件 */}
      <section className="px-3 py-2 border-b border-[color:var(--border-subtle)]">
        <h3
          className="text-[10px] uppercase tracking-[0.04em] mb-1 font-mono"
          style={{ color: 'var(--text-tertiary)' }}
        >
          触发条件 ({triggerConditions.filter((c) => c.passed).length}/{triggerConditions.length}{' '}
          通过)
        </h3>
        <ul className="flex flex-col gap-0.5 list-none p-0 m-0">
          {triggerConditions.map((c, i) => (
            <li
              key={i}
              className="flex items-center gap-2 text-xs"
              style={{ fontFamily: 'var(--font-mono)' }}
            >
              <span
                style={{
                  color: c.passed ? 'var(--green-down)' : 'var(--red-up)',
                }}
                aria-label={c.passed ? '通过' : '未通过'}
              >
                {c.passed ? '✓' : '✗'}
              </span>
              <span style={{ color: 'var(--foreground)' }}>{c.label}</span>
              <span style={{ color: 'var(--text-tertiary)' }}>{c.actualValue}</span>
            </li>
          ))}
        </ul>
      </section>

      {/* smoothing */}
      <section className="px-3 py-2 border-b border-[color:var(--border-subtle)]">
        <h3
          className="text-[10px] uppercase tracking-[0.04em] mb-1 font-mono"
          style={{ color: 'var(--text-tertiary)' }}
        >
          Smoothing 状态
        </h3>
        <div
          className="text-xs"
          style={{ color: 'var(--foreground)', fontFamily: 'var(--font-mono)' }}
        >
          <div>raw_state: {REGIME_LABEL[smoothingStatus.rawState]} (今日)</div>
          {smoothingStatus.isConfirmed ? (
            <div style={{ color: 'var(--green-down)' }}>
              ✓ 已确认切换{' '}
              {smoothingStatus.confirmedDaysAgo !== undefined &&
                `(${smoothingStatus.confirmedDaysAgo} 天前)`}
            </div>
          ) : smoothingStatus.transitionalState ? (
            <div style={{ color: 'var(--yellow)' }}>
              ⏳ 转换中 → {REGIME_LABEL[smoothingStatus.transitionalState]}{' '}
              {smoothingStatus.transitionalDays ?? 0}d
            </div>
          ) : (
            <div style={{ color: 'var(--muted-foreground)' }}>无 transitional 状态</div>
          )}
        </div>
      </section>

      {/* 仓位 */}
      <section className="px-3 py-2 border-b border-[color:var(--border-subtle)]">
        <h3
          className="text-[10px] uppercase tracking-[0.04em] mb-1 font-mono"
          style={{ color: 'var(--text-tertiary)' }}
        >
          仓位上限
        </h3>
        <div
          className="text-xs flex flex-col gap-0.5"
          style={{ fontFamily: 'var(--font-mono)', color: 'var(--foreground)' }}
        >
          <div>
            上限: {limitPercent}% ({REGIME_LABEL[regime]} regime)
          </div>
          <div>当前: {positionPercent}%</div>
          <div style={{ color: 'var(--green-down)' }}>可加: {availablePercent}%</div>
        </div>
      </section>

      {/* Fusion overrides */}
      {fusionOverrides.length > 0 && (
        <section className="px-3 py-2">
          <h3
            className="text-[10px] uppercase tracking-[0.04em] mb-1 font-mono"
            style={{ color: 'var(--text-tertiary)' }}
          >
            Fusion weight overrides
          </h3>
          <ul className="flex flex-col gap-0.5 list-none p-0 m-0">
            {fusionOverrides.map((f, i) => {
              if (f.multiplier === 1.0) return null;
              return (
                <li
                  key={i}
                  className="text-xs flex items-center gap-2"
                  style={{ fontFamily: 'var(--font-mono)' }}
                >
                  {f.iconEmoji && <span aria-hidden="true">{f.iconEmoji}</span>}
                  <span style={{ color: 'var(--foreground)' }}>{f.dimName}</span>
                  <span
                    style={{
                      color: f.isBoosted
                        ? 'var(--red-up)'
                        : f.isDampened
                        ? 'var(--text-tertiary)'
                        : 'var(--muted-foreground)',
                    }}
                  >
                    × {f.multiplier.toFixed(1)}
                    {f.isDampened && ' (dampened)'}
                  </span>
                </li>
              );
            })}
          </ul>
        </section>
      )}
    </div>
  );

  // Portal 到 document.body(避免父容器 overflow:hidden 切割)
  return typeof document !== 'undefined' ? createPortal(content, document.body) : null;
});

ORegimeExplanationPopover.displayName = 'ORegimeExplanationPopover';
