/**
 * OQuickClose - 一键平仓 / 一键反手 / 部分平仓。
 *
 * 合约老炮高频操作:
 *   - 一键平仓 (市价立即关闭当前持仓)
 *   - 一键反手 (平当前仓 + 反向开同量)
 *   - 部分平仓 (25% / 50% / 75%)
 *
 * 自带二次确认 (避免误操作),可关闭 (老炮).
 *
 * 用法:
 *   <OQuickClose
 *     data={{ symbol: 'BTCUSDT', position: { side: 'LONG', amount: 0.5, entryPrice: 67000, markPrice: 67500 } }}
 *     onClose={(pct) => api.closePosition(pct)}
 *     onReverse={() => api.reverse()}
 *   />
 */

'use client';

import { forwardRef, useEffect, useState } from 'react';
import { cn } from '../../lib/cn';
import { resolveBlockState } from '../../lib/resolveBlockState';
import { OLoadingState } from '../OLoadingState';
import { OErrorState } from '../OErrorState';
import { useFastData } from '../../providers/FastDataProvider';
import type { OBlockDataProps } from '../../lib/types';
import type { TerminalBlockProps } from '../../protocols';

export interface OQuickClosePosition {
  side: 'LONG' | 'SHORT';
  amount: number;
  entryPrice: number;
  markPrice: number;
  /** 未实现盈亏 (USDT). */
  unrealizedPnl?: number;
  /** 盈亏百分比 (相对入场). */
  pnlPercent?: number;
}

export interface OQuickCloseData {
  symbol: string;
  position: OQuickClosePosition | null;
}

export interface OQuickCloseProps
  extends OBlockDataProps<OQuickCloseData>,
    Pick<TerminalBlockProps, 'channel' | 'flashOnUpdate'> {
  /** 平仓回调. pct = 100 全平,= 25/50/75 部分. */
  onClose?: (percent: number) => void | Promise<void>;
  /** 反手 (平 + 反向开同量). */
  onReverse?: () => void | Promise<void>;
  /** 关闭二次确认 (老炮模式). */
  skipConfirm?: boolean;
  /** 紧凑模式 (单行). */
  compact?: boolean;
}

export const OQuickClose = forwardRef<HTMLDivElement, OQuickCloseProps>(
  function OQuickClose(
    {
      data: dataProp,
      loading,
      error,
      empty,
      channel,
      onClose,
      onReverse,
      skipConfirm = false,
      compact = false,
      flashOnUpdate: _f,
      className,
      theme: _t,
      size: _s,
    },
    ref
  ) {
    const fastData = useFastData();
    const [channelData, setChannelData] = useState<OQuickCloseData | null>(null);
    useEffect(() => {
      if (!channel || !fastData) return;
      return fastData.subscribe<OQuickCloseData>(channel, setChannelData);
    }, [channel, fastData]);

    const data = channel ? channelData : (dataProp ?? null);
    const state = resolveBlockState({ data, loading, error, empty });

    const [pendingAction, setPendingAction] = useState<string | null>(null);

    function trigger(action: 'close-25' | 'close-50' | 'close-75' | 'close-100' | 'reverse') {
      if (skipConfirm) {
        executeAction(action);
      } else {
        setPendingAction(action);
      }
    }

    function executeAction(action: string) {
      if (action.startsWith('close-')) {
        const pct = parseInt(action.split('-')[1]!, 10);
        void onClose?.(pct);
      } else if (action === 'reverse') {
        void onReverse?.();
      }
      setPendingAction(null);
    }

    if (state === 'loading')
      return (
        <div
          ref={ref}
          className={cn('rounded-md border border-border bg-card p-3', className)}
        >
          <OLoadingState rows={2} rowHeight="1.5rem" />
        </div>
      );
    if (state === 'error') return <OErrorState ref={ref} error={error!} className={className} />;
    if (state === 'empty' || !data || !data.position) {
      return (
        <div
          ref={ref}
          className={cn(
            'rounded-md border border-border bg-card p-3 text-center text-xs text-[color:var(--text-muted)] @container',
            className
          )}
        >
          {data?.symbol ?? '无持仓'}
        </div>
      );
    }

    const pos = data.position;
    const sideColor = pos.side === 'LONG' ? 'var(--quote-up)' : 'var(--quote-down)';
    const reverseColor = pos.side === 'LONG' ? 'var(--quote-down)' : 'var(--quote-up)';
    const pnlPositive = (pos.unrealizedPnl ?? 0) >= 0;

    const actionLabel: Record<string, string> = {
      'close-25': '平仓 25%',
      'close-50': '平仓 50%',
      'close-75': '平仓 75%',
      'close-100': '全部平仓',
      reverse: '一键反手',
    };

    return (
      <div
        ref={ref}
        className={cn(
          'rounded-md border border-border bg-card flex flex-col',
          className
        )}
        style={{ fontFamily: 'var(--font-ui)' }}
      >
        {/* 持仓摘要 */}
        <div className="px-3 py-2 border-b border-border flex items-baseline justify-between">
          <div className="flex items-baseline gap-2">
            <span className="text-xs font-mono" style={{ color: sideColor }}>
              {pos.side === 'LONG' ? '多' : '空'} {pos.amount}
            </span>
            <span className="text-[10px] text-[color:var(--text-muted)] font-mono">
              {data.symbol}
            </span>
          </div>
          {typeof pos.unrealizedPnl === 'number' ? (
            <span
              className="text-sm tabular-nums font-mono"
              style={{ color: pnlPositive ? 'var(--quote-up)' : 'var(--quote-down)' }}
            >
              {pnlPositive ? '+' : ''}
              {pos.unrealizedPnl.toFixed(2)}
              {typeof pos.pnlPercent === 'number' ? (
                <span className="text-[10px] ml-1">
                  ({pnlPositive ? '+' : ''}
                  {pos.pnlPercent.toFixed(2)}%)
                </span>
              ) : null}
            </span>
          ) : null}
        </div>

        {/* 按钮区 */}
        {compact ? (
          <div className="flex p-2 gap-1">
            <button
              type="button"
              onClick={() => trigger('close-100')}
              className="flex-1 py-1.5 text-xs rounded text-white"
              style={{ background: sideColor }}
            >
              平仓
            </button>
            <button
              type="button"
              onClick={() => trigger('reverse')}
              className="flex-1 py-1.5 text-xs rounded text-white"
              style={{ background: reverseColor }}
            >
              反手
            </button>
          </div>
        ) : (
          <div className="p-2 grid grid-cols-4 gap-1">
            <button
              type="button"
              onClick={() => trigger('close-25')}
              className="py-1.5 text-[11px] rounded border border-border hover:bg-muted"
            >
              25%
            </button>
            <button
              type="button"
              onClick={() => trigger('close-50')}
              className="py-1.5 text-[11px] rounded border border-border hover:bg-muted"
            >
              50%
            </button>
            <button
              type="button"
              onClick={() => trigger('close-75')}
              className="py-1.5 text-[11px] rounded border border-border hover:bg-muted"
            >
              75%
            </button>
            <button
              type="button"
              onClick={() => trigger('close-100')}
              className="py-1.5 text-[11px] rounded text-white"
              style={{ background: sideColor }}
            >
              全平
            </button>
            <button
              type="button"
              onClick={() => trigger('reverse')}
              className="col-span-4 py-1.5 text-xs rounded text-white mt-1"
              style={{ background: reverseColor }}
            >
              一键反手 → {pos.side === 'LONG' ? '做空' : '做多'} {pos.amount}
            </button>
          </div>
        )}

        {/* 二次确认弹层 */}
        {pendingAction ? (
          <div className="absolute inset-0 bg-card/95 backdrop-blur-sm rounded-md flex flex-col items-center justify-center p-4 z-10 border-2 border-[color:var(--alert-warn)]">
            <div className="text-sm text-[color:var(--foreground)] mb-2 text-center">
              确认 <strong>{actionLabel[pendingAction]}</strong>?
            </div>
            <div className="text-[10px] text-[color:var(--text-muted)] mb-3 text-center font-mono">
              {data.symbol} · {pos.side === 'LONG' ? '多仓' : '空仓'} {pos.amount}
            </div>
            <div className="flex gap-2 w-full">
              <button
                type="button"
                onClick={() => setPendingAction(null)}
                className="flex-1 py-2 text-xs rounded border border-border text-[color:var(--text-muted)] hover:bg-muted"
              >
                取消
              </button>
              <button
                type="button"
                onClick={() => executeAction(pendingAction)}
                className="flex-1 py-2 text-xs rounded text-white"
                style={{
                  background: pendingAction === 'reverse' ? reverseColor : sideColor,
                }}
              >
                确认
              </button>
            </div>
          </div>
        ) : null}
      </div>
    );
  }
);

OQuickClose.displayName = 'OQuickClose';
