/**
 * OTextInput - 文本输入框。
 *
 * 受控,标准 HTML input 增强:
 *   - 前置/后置图标 或 文本
 *   - 清除按钮
 *   - 字符计数 (maxLength 时显示)
 *   - 密码显示切换 (type=password)
 *   - error 视觉状态 (由外部 OFormField 控制)
 */
'use client';

import { cva, type VariantProps } from 'class-variance-authority';
import { forwardRef, useState, type InputHTMLAttributes, type ReactNode } from 'react';
import { cn } from '../../lib/cn';
import type { OBlockBaseProps } from '../../lib/types';

// v2.10.0: 尺寸消费控件密度 token(--control-h-*),与 OInput 统一到同一尺寸系统,
// 自动吃上 [data-density] 级联。保留 filled/underlined 等组件特有 variant。
const inputVariants = cva(
  'w-full bg-[color:var(--card)] text-[color:var(--foreground)] placeholder:text-[color:var(--muted-foreground)] outline-none transition-colors duration-[var(--duration-fast)] disabled:opacity-50 disabled:cursor-not-allowed',
  {
    variants: {
      size: {
        sm: 'h-[var(--control-h-sm)] text-[length:var(--text-xs)] px-[var(--control-px-sm)]',
        md: 'h-[var(--control-h-md)] text-[length:var(--text-sm)] px-[var(--control-px-md)]',
        lg: 'h-[var(--control-h-lg)] text-[length:var(--text-base)] px-[var(--control-px-md)]',
      },
      variant: {
        outlined: 'border border-[color:var(--input,var(--border))] rounded-[var(--control-radius)] focus-within:ring-2 focus-within:ring-[color:var(--ring)]',
        filled: 'bg-[color:var(--muted)] border border-transparent rounded-[var(--control-radius)] focus-within:bg-[color:var(--card)] focus-within:border-[color:var(--input,var(--border))] focus-within:ring-2 focus-within:ring-[color:var(--ring)]',
        underlined: 'border-0 border-b border-[color:var(--input,var(--border))] rounded-none px-0 focus-within:border-[color:var(--primary)]',
      },
      invalid: {
        true: '!border-[color:var(--destructive)] focus-within:!ring-[color:var(--destructive)]',
        false: '',
      },
    },
    defaultVariants: { size: 'md', variant: 'outlined', invalid: false },
  }
);

type InputVariantProps = VariantProps<typeof inputVariants>;

export interface OTextInputProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'size' | 'prefix'>,
    Omit<OBlockBaseProps, 'size'>,
    InputVariantProps {
  /** 前置图标或文本 (e.g. 搜索图标, "$" 单位)。 */
  prefix?: ReactNode;
  /** 后置图标或文本。 */
  suffix?: ReactNode;
  /** 清除按钮 (有值时显示)。 */
  clearable?: boolean;
  /** 字符计数显示 (maxLength 时自动启用,可手动 disable)。 */
  showCount?: boolean;
}

function EyeIcon({ open }: { open: boolean }) {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
      {open ? (
        <>
          <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
          <circle cx="12" cy="12" r="3" />
        </>
      ) : (
        <>
          <path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19m-6.72-1.07a3 3 0 11-4.24-4.24" />
          <line x1="1" y1="1" x2="23" y2="23" />
        </>
      )}
    </svg>
  );
}

function ClearIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
      <circle cx="12" cy="12" r="10" />
      <line x1="15" y1="9" x2="9" y2="15" />
      <line x1="9" y1="9" x2="15" y2="15" />
    </svg>
  );
}

export const OTextInput = forwardRef<HTMLInputElement, OTextInputProps>(function OTextInput(
  {
    size = 'md',
    variant = 'outlined',
    invalid,
    prefix,
    suffix,
    clearable,
    showCount,
    type = 'text',
    value,
    defaultValue,
    onChange,
    maxLength,
    className,
    theme: _t,
    ...rest
  },
  ref
) {
  const [internal, setInternal] = useState<string>(
    typeof defaultValue === 'string' ? defaultValue : ''
  );
  const [showPwd, setShowPwd] = useState(false);

  const isControlled = value !== undefined;
  const currentValue = isControlled ? String(value ?? '') : internal;

  const realType = type === 'password' ? (showPwd ? 'text' : 'password') : type;

  function emit(next: string, e: React.ChangeEvent<HTMLInputElement>) {
    if (!isControlled) setInternal(next);
    onChange?.(e);
  }

  const hasValue = currentValue.length > 0;
  const shouldShowCount = (showCount ?? typeof maxLength === 'number') && typeof maxLength === 'number';

  return (
    <div className={cn('relative w-full', className)}>
      <div
        className={cn(
          'flex items-stretch w-full @container',
          inputVariants({ size, variant, invalid }),
          'p-0', // 父级清掉 padding,让 input 自己处理
          'overflow-hidden'
        )}
      >
        {prefix ? (
          <span className="flex items-center pl-3 pr-1 text-muted-foreground shrink-0">{prefix}</span>
        ) : null}
        <input
          ref={ref}
          type={realType}
          // 内部统一受控(uncontrolled 模式也走 internal state,这样 clear 能真清空 DOM)
          value={currentValue}
          maxLength={maxLength}
          onChange={(e) => emit(e.target.value, e)}
          className={cn(
            'flex-1 bg-transparent outline-none min-w-0',
            size === 'sm' ? 'px-[var(--control-px-sm)] text-[length:var(--text-xs)]' : size === 'lg' ? 'px-[var(--control-px-md)] text-[length:var(--text-base)]' : 'px-[var(--control-px-md)] text-[length:var(--text-sm)]',
            prefix ? 'pl-1' : '',
            'placeholder:text-[color:var(--muted-foreground)] disabled:cursor-not-allowed'
          )}
          {...rest}
        />
        {clearable && hasValue && !rest.disabled ? (
          <button
            type="button"
            onClick={() => {
              const ev = { target: { value: '' } } as React.ChangeEvent<HTMLInputElement>;
              if (!isControlled) setInternal('');
              onChange?.(ev);
            }}
            aria-label="Clear"
            className="px-2 text-muted-foreground hover:text-foreground transition-colors"
          >
            <ClearIcon />
          </button>
        ) : null}
        {type === 'password' ? (
          <button
            type="button"
            onClick={() => setShowPwd((v) => !v)}
            aria-label={showPwd ? 'Hide password' : 'Show password'}
            className="px-2 text-muted-foreground hover:text-foreground transition-colors"
          >
            <EyeIcon open={showPwd} />
          </button>
        ) : null}
        {suffix ? (
          <span className="flex items-center pl-1 pr-3 text-muted-foreground shrink-0">{suffix}</span>
        ) : null}
      </div>
      {shouldShowCount ? (
        <div className="text-[10px] text-muted-foreground text-right mt-1">
          {currentValue.length} / {maxLength}
        </div>
      ) : null}
    </div>
  );
});

OTextInput.displayName = 'OTextInput';
