/**
 * OHighDensityTable (Tide Wave 2 E7, Block)
 *
 * 极致紧凑的数据表格(rowHeight 默认 24px)。
 * 来源:OUI_WAVE_2_REQUIREMENTS_v1.0.md §4
 *
 * 与 helios 已有 ODataTable 区别:
 *   - 更紧凑(rowHeight 24 vs ODataTable 默认 48)
 *   - 数据列等宽 JetBrains Mono
 *   - hover 左侧 2px blue 边框
 *   - 可选 flash-on-update(数据变化时高亮 0.8s)
 *
 * 适用:watchlist / candidates / holdings / sector list 等高密度场景。
 */
import {
  forwardRef,
  useCallback,
  useEffect,
  useMemo,
  useReducer,
  useRef,
  type ReactNode,
  type Ref,
  type ReactElement,
} from 'react';
import { cn } from '../../lib/cn';
import { useUiLang } from '../../lang/LangProvider';
import type { OBlockBaseProps } from '../../lib/types';

export interface HDTColumn<T> {
  key: keyof T;
  header: string;
  /** px 或 "1fr" */
  width?: number | string;
  align?: 'left' | 'right' | 'center';
  format?: (value: unknown, row: T) => ReactNode;
  sortable?: boolean;
}

export interface OHighDensityTableProps<T = Record<string, unknown>>
  extends Omit<OBlockBaseProps, 'variant'> {
  columns: HDTColumn<T>[];
  rows: T[];
  rowHeight?: number;
  onRowClick?: (row: T) => void;
  onRowHover?: (row: T) => void;
  sortBy?: keyof T;
  sortOrder?: 'asc' | 'desc';
  onSort?: (column: keyof T) => void;
  /** 数据更新时 flash 该 row */
  flashOnUpdate?: boolean;
  /** flash 的 stable key(row 中字段名)*/
  rowKey?: keyof T;
  emptyMessage?: string;
}

interface RowFlash {
  [key: string]: { dir: 'up' | 'down'; expires: number };
}

function OHighDensityTableImpl<T extends Record<string, unknown>>(
  {
    columns,
    rows,
    rowHeight = 24,
    onRowClick,
    onRowHover,
    sortBy,
    sortOrder,
    onSort,
    flashOnUpdate,
    rowKey,
    emptyMessage,
    className,
  }: OHighDensityTableProps<T>,
  ref: Ref<HTMLDivElement>
): ReactElement {
  const { tr } = useUiLang();
  const emptyText = emptyMessage ?? tr('无数据', 'No data');
  const gridTemplate = useMemo(
    () =>
      columns
        .map((c) => (typeof c.width === 'number' ? `${c.width}px` : c.width ?? '1fr'))
        .join(' '),
    [columns]
  );

  const lastValuesRef = useRef<Record<string, unknown>>({});
  const flashesRef = useRef<RowFlash>({});
  const [, forceUpdate] = useReducer((x: number) => x + 1, 0);

  useEffect(() => {
    if (!flashOnUpdate || !rowKey) return;
    const flashSortKey = sortBy ?? columns.find((c) => c.align === 'right')?.key;
    if (!flashSortKey) return;
    const now = Date.now();
    const newFlashes: RowFlash = { ...flashesRef.current };
    rows.forEach((row) => {
      const id = String(row[rowKey] ?? '');
      if (!id) return;
      const oldV = lastValuesRef.current[id] as number | undefined;
      const newV = row[flashSortKey] as number;
      if (typeof newV === 'number' && typeof oldV === 'number' && newV !== oldV) {
        newFlashes[id] = { dir: newV > oldV ? 'up' : 'down', expires: now + 800 };
      }
      lastValuesRef.current[id] = newV;
    });
    flashesRef.current = newFlashes;
    const t = setTimeout(() => {
      const stillActive: RowFlash = {};
      const tNow = Date.now();
      for (const [k, v] of Object.entries(flashesRef.current)) {
        if (v.expires > tNow) stillActive[k] = v;
      }
      flashesRef.current = stillActive;
      forceUpdate();
    }, 800);
    return () => clearTimeout(t);
  }, [rows, flashOnUpdate, rowKey, sortBy, columns]);

  const handleSort = useCallback(
    (col: HDTColumn<T>) => {
      if (!col.sortable || !onSort) return;
      onSort(col.key);
    },
    [onSort]
  );

  if (rows.length === 0) {
    return (
      <div
        ref={ref}
        className={cn(
          'flex items-center justify-center px-4 py-6',
          'text-sm text-[color:var(--text-tertiary)]',
          'border border-dashed border-[color:var(--border-strong)] rounded',
          className
        )}
      >
        {emptyText}
      </div>
    );
  }

  return (
    <div
      ref={ref}
      className={cn('flex flex-col w-full @container', className)}
      style={{ fontFamily: 'var(--font-mono)' }}
      role="table"
    >
      {/* header */}
      <div
        className={cn(
          'grid items-center px-1 py-1',
          'border-b border-[color:var(--border-strong)]',
          'sticky top-0 z-[1]'
        )}
        style={{
          gridTemplateColumns: gridTemplate,
          backgroundColor: 'var(--card)',
          fontSize: 10,
        }}
        role="row"
      >
        {columns.map((col) => {
          const isSorted = sortBy === col.key;
          return (
            <div
              key={String(col.key)}
              role="columnheader"
              aria-sort={
                isSorted ? (sortOrder === 'asc' ? 'ascending' : 'descending') : 'none'
              }
              style={{
                textAlign: col.align ?? 'left',
              }}
            >
              <button
                type="button"
                disabled={!col.sortable}
                onClick={() => handleSort(col)}
                className={cn(
                  'uppercase tracking-[0.04em] font-semibold truncate w-full',
                  col.sortable && 'cursor-pointer hover:text-[color:var(--foreground)]'
                )}
                style={{
                  textAlign: col.align ?? 'left',
                  color: 'var(--text-tertiary)',
                  fontFamily: 'var(--font-mono)',
                  background: 'transparent',
                  border: 'none',
                  padding: 0,
                  font: 'inherit',
                }}
              >
                {col.header}
                {isSorted && <span aria-hidden="true">{sortOrder === 'asc' ? ' ▲' : ' ▼'}</span>}
              </button>
            </div>
          );
        })}
      </div>

      {/* rows */}
      <div role="rowgroup">
        {rows.map((row, idx) => {
          const id = rowKey ? String(row[rowKey] ?? idx) : String(idx);
          const flash = flashesRef.current[id];
          const flashClass = flash
            ? flash.dir === 'up'
              ? 'tide-flash-up'
              : 'tide-flash-down'
            : '';
          return (
            <div
              key={id}
              role="row"
              onClick={() => onRowClick?.(row)}
              onMouseEnter={() => onRowHover?.(row)}
              className={cn(
                'grid items-center px-1 group relative o-cv-row-sm',
                onRowClick && 'cursor-pointer',
                'hover:bg-[color:var(--accent)]',
                flashClass
              )}
              style={{
                gridTemplateColumns: gridTemplate,
                height: rowHeight,
                fontSize: 13,
              }}
            >
              {/* hover 左侧 2px blue 边框 */}
              <span
                className="absolute left-0 top-0 bottom-0 w-[2px] opacity-0 group-hover:opacity-100 transition-opacity"
                style={{ backgroundColor: 'var(--blue-accent)' }}
                aria-hidden="true"
              />
              {columns.map((col) => {
                const v = row[col.key];
                const content = col.format ? col.format(v, row) : (v as ReactNode);
                return (
                  <div
                    key={String(col.key)}
                    role="cell"
                    className="truncate"
                    style={{
                      textAlign: col.align ?? 'left',
                      color: 'var(--foreground)',
                      padding: '0 4px',
                      fontFamily: col.align === 'right' ? 'var(--font-mono)' : 'var(--font-sans)',
                    }}
                  >
                    {content as ReactNode}
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>
    </div>
  );
}

export const OHighDensityTable = forwardRef(OHighDensityTableImpl) as <
  T extends Record<string, unknown> = Record<string, unknown>,
>(
  props: OHighDensityTableProps<T> & { ref?: Ref<HTMLDivElement> }
) => ReactElement;

(OHighDensityTable as unknown as { displayName?: string }).displayName = 'OHighDensityTable';
